    ["*(Dialogue 13:)*"] = "*(Diálogo 13 :)*",
    ["How do you organise a party in outer space?"] = "¿Cómo se organiza una fiesta en el espacio exterior?",
    ["You planet"] = "Tu planeta",
    ["*(Dialogue 14:)*"] = "*(Diálogo 14 :)*",
    ["I delivered presents to the guy who invented windowsills before."] = "Le entregué regalos al tipo que inventó los alféizares antes.",
    ["Was he a nice guy?"] = "¿Era un buen tipo?",
    ["What a ledge."] = "Qué repisa.",
    ["*(Dialogue 15:)*"] = "*(Diálogo 15 :)*",
