    ["He uses the Maul of Snowmens!"] = "¡Utiliza el Mazo de los Hombres de Nieve!",
    ["*(Dialogue 16:)*"] = "*(Diálogo 16 :)*",
    ["I don't often tell dad jokes."] = "No suelo contar chistes de papá.",
    ["But when I do, he laughs."] = "Pero cuando lo hago, se ríe.",
    ["*(Dialogue 17:)*"] = "*(Diálogo 17 :)*",
