    ["*shrug*"] = "*encogimiento de hombros*",
    ["Cross Mouse Cards!"] = "¡Tarjetas cruzadas de ratón!",
    ["*(Dialogue 33:)*"] = "*(Diálogo 33 :)*",
    ["What do ghosts ride at an amusement park?"] = "¿Qué montan los fantasmas en un parque de diversiones?",
    ["I don't know. What do ghosts ride at an amusement park?"] = "No lo sé. ¿Qué montan los fantasmas en un parque de diversiones?",
    ["A roller-ghoster."] = "Un fantasma rodante.",
    ["*(Dialogue 34:)*"] = "*(Diálogo 34 :)*",
