    ["Newly-webs."] = "Nuevas webs.",
    ["*(Dialogue 40:)*"] = "*(Diálogo 40:)*",
    ["What do you call a cat in the desert?"] = "¿Cómo se llama a un gato en el desierto?",
    ["Sandy Claws!"] = "Sandy ¡Garras!",
    ["*(Dialogue 41:)*"] = "*(Diálogo 41 :)*",
