    ["Poultry-geist!"] = "¡Geist de aves de corral!",
    ["*(Dialogue 42:)*"] = "*(Diálogo 42 :)*",
    ["What do you call a jacket that goes up in flames?"] = "¿Cómo se llama una chaqueta que se incendia?",
