    ["Tinsilitis!"] = "¡Tinsilitis!",
    ["*(Dialogue 50:)*"] = "*(Diálogo 50 :)*",
    ["What do you get when you cross a snowman with a vampire?"] = "¿Qué obtienes cuando cruzas un muñeco de nieve con un vampiro?",
    ["Frostbite!"] = "¡Congelación!",
    ["*(Dialogue 51:)*"] = "*(Diálogo 51 :)*",
