    ["*(Dialogue 65:)*"] = "*(Diálogo 65 :)*",
    ["Which boss monster would you most likely find in a workshop?"] = "¿Qué monstruo jefe es más probable que encuentres en un taller?",
    ["A rack o'saws!"] = "¡Un estante de sierras!",
    ["*(Dialogue 66:)*"] = "*(Diálogo 66 :)*",
