    ["*(Dialogue 69:)*"] = "*(Diálogo 69 :)*",
    ["Why can't a nose be 12 inches long?"] = "¿Por qué una nariz no puede medir 30 centímetros de largo?",
    ["Because it would be a foot!"] = "¡Porque sería un pie!",
    ["*(Dialogue 70:)*"] = "*(Diálogo 70 :)*",
    ["Why couldn't the ranger kill Nex?"] = "¿Por qué el guardabosques no pudo matar a Nex?",
    ["He didn't bring Za-ryte bow!"] = "¡No trajo el arco de Za-ryte!",
    ["*(Dialogue 71:)*"] = "*(Diálogo 71 :)*",
    ["Why did one of my helpers see the doctor?"] = "¿Por qué uno de mis ayudantes vio al médico?",
    ["Because he had a low 'elf' esteem!"] = "¡Porque tenía una baja estima de 'elfo'!",
    ["*(Dialogue 72:)*"] = "*(Diálogo 72 :)*",
    ["Why did the walrus lick the envelope?"] = "¿Por qué la morsa lamió el sobre?",
    ["Because he was looking for a good seal!"] = "¡Porque estaba buscando un buen sello!",
    ["*(Dialogue 73:)*"] = "*(Diálogo 73 :)*",
    ["Why didn't Rudolph go to school?"] = "¿Por qué Rudolph no fue a la escuela?",
    ["I don't know, why didn't Rudolph go to school?"] = "No sé, ¿por qué Rudolph no fue a la escuela?",
    ["Because he was Elf-taught!"] = "¡Porque le enseñaron los elfos!",
    ["*(Dialogue 74:)*"] = "*(Diálogo 74 :)*",
    ["Why do cows have hooves instead of feet?"] = "¿Por qué las vacas tienen pezuñas en lugar de patas?",
    ["Because they lac-toes!"] = "¡Porque tienen dedos de los pies!",
    ["*(Dialogue 75:)*"] = "*(Diálogo 75 :)*",
    ["Why do people try and mine the Barrows?"] = "¿Por qué la gente intenta minar los Túmulos?",
    ["To get to Dha-rocks!"] = "¡Para llegar a Dha-rocks!",
    ["*(Dialogue 76:)*"] = "*(Diálogo 76 :)*",
    ["Why does Santa have three gardens?"] = "¿Por qué Santa tiene tres jardines?",
    ["So he can 'ho ho ho'!"] = "¡Para que pueda 'ho ho ho'!",
    ["*(Dialogue 77:)*"] = "*(Diálogo 77 :)*",
    ["Why does Vorago eat shark and shrimp pizza?"] = "¿Por qué Vorago come pizza de tiburón y camarones?",
    ["Becasuse he likes the size mix!"] = "¡Porque le gusta la combinación de tallas!",
    ["*(Dialogue 78:)*"] = "*(Diálogo 78 :)*",
    ["Why is the elven marketplace always sad?"] = "¿Por qué el mercado de los elfos siempre está triste?",
    ["It's full of cry-stalls!"] = "¡Está lleno de puestos de llanto!",
    ["*facepalm*"] = "*palma de la cara*",
    ["*(Dialogue 3):*"] = "*(Diálogo 3):*",
    ["BOOM BOOM!"] = "¡BUM BUM!",
    ["HAHAHA THAT'S HILARIOUS!"] = "JAJAJA ¡ESO ES DIVERTIDO!",
    ["HAHAHAHAHA!"] = "¡JAJAJAJAJAJA!",
    ["Please stop."] = "Por favor, detente.",
    ["Santa, you are just the worst!"] = "¡Papá Noel, eres el peor!",
    ["Wow. Just wow."] = "Vaya. Simplemente guau.",
    ["You really are just full of dad jokes, aren't you!"] = "Realmente estás lleno de chistes de papá, ¿no?",
    ["Ho ho ho! There's plenty more where that came from!"] = "¡Ho, ho, ho! ¡Hay mucho más de donde vino eso!",
    ["Did you like it?"] = "¿Te gustó?",
    ["That was the best joke I have ever heard in my life!"] = "¡Ese fue el mejor chiste que he escuchado en mi vida!",
    ["I never get tired of telling that one!"] = "¡Nunca me canso de contarlo!",
    ["You probably should..."] = "Probablemente deberías...",
    ["Ho-ho-ho! Merry Christmas!"] = "¡Ho-ho-ho! ¡Feliz navidad!",
    ["[Santa looks down and checks over his list.]"] = "[Santa mira hacia abajo y revisa su lista.]",
    ["I don't have anything for you right now."] = "No tengo nada para ti en este momento.",
    ["I will be back next week. Be nice between now and then and I just might have more gifts for you!"] = "Volveré la semana que viene. ¡Sé amable de ahora en adelante y quizás tenga más regalos para ti!",
    ["The festivities are now ending but this has been one of the best years yet! I'll see you again next year!"] = "¡Las festividades están terminando pero este ha sido uno de los mejores años hasta ahora! ¡Te veré de nuevo el año que viene!",
    ["Merry Christmas and a Happy New Year!"] = "¡Feliz Navidad y próspero año nuevo!",
    ["It looks like you've been very nice over this past week!"] = "¡Parece que has sido muy amable durante la semana pasada!",
    ["I have no new presents for you but you have been nice. Let's see if those Nice Points will get you a black partyhat!"] = "No tengo regalos nuevos para ti pero has sido amable. ¡Veamos si esos Nice Points te dan un sombrero de fiesta negro!",
    ["The following has been added to your currency pouch: [number] x Christmas spirit."] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] x Espíritu navideño.",
    ["[number] Christmas spirit"] = "[número] Espíritu navideño",
    ["Mystery gift"] = "regalo misterioso",
    ["Here, take this gift!"] = "¡Toma, toma este regalo!",
    ["You need at least 5 spaces in your backpack to receive your present."] = "Necesitas al menos 5 espacios en tu backpack para recibir tu regalo.",
    ["1 x Peppermint top"] = "1 x tapa de menta",
    ["1 x Peppermint legs"] = "1 x patas de menta",
    ["1 x Peppermint shoes"] = "1 x zapatos de menta",
    ["1 x Peppermint gloves"] = "1 x guantes de menta",
    ["You need at least 2 spaces in your backpack to receive your present."] = "Necesitas al menos 2 espacios en tu backpack para recibir tu regalo.",
    ["1 x Winter Hat"] = "1 gorro de invierno.",
    ["1 x Winter Scarf"] = "1 bufanda de invierno.",
    ["You need at least 1 spaces in your backpack to receive your present."] = "Necesitas al menos 1 espacios en tu backpack para recibir tu regalo.",
    ["Cosy Pyjamas (Trees)' cosmetic override"] = "Anulación cosmética 'Pijamas acogedores (árboles)",
    ["Cosy Slippers (Zuk)' cosmetic override"] = "Anulación cosmética 'Cosy Slipper (Zuk)",
    ["Cosy Pyjamas (Snowflakes)' cosmetic override"] = "Anulación cosmética 'Cosy Pyjamas (Snowflakes)",
    ["Cosy Slippers (Plain)' cosmetic override"] = "Anulación cosmética \"Zapatillas acogedoras (lisas)",
    ["Cosy Pyjamas (Candy Canes)' cosmetic override"] = "Anulación cosmética 'Pijamas acogedores (bastones de caramelo)",
    ["Cosy Slippers (Penguin)' cosmetic override"] = "Anulación cosmética \"Zapatillas acogedoras (pingüino)",
    ["Cosy Pyjamas (Plaid)' cosmetic override"] = "Anulación cosmética 'Cosy Pyjamas (a cuadros)",
    ["Cosy Slippers (Plaid)' cosmetic override"] = "Anulación cosmética \"Zapatillas acogedoras (a cuadros)",
    ["[You dig deep to check if Santa left you anything special for your Nice Points.]"] = "[Profundizas para comprobar si Santa te dejó algo especial para tus Nice Points.]",
    ["[There was nothing else addressed to you.]"] = "[No había nada más dirigido a usted.]",
    ["Unlucky, Player. No black partyhat for you today, but there's always next time!"] = "Desafortunado, Player. No hay sombrero de fiesta negro para ti hoy, ¡pero siempre habrá la próxima vez!",
    ["How does the Terrorbird Racing work?"] = "¿Cómo funciona Terrorbird Racing?",
    ["These races are an extra part of the Christmas festivities for this year. They're very exciting."] = "Estas carreras son una parte extra de las festividades navideñas de este año. Son muy emocionantes.",
    ["You can race once an hour and the idea is to get round all of the 8 gates in the quickest time possible."] = "Puedes correr una vez por hora y la idea es pasar las 8 puertas en el menor tiempo posible.",
    ["The quicker you are the greater your reward will be at the end of the race."] = "Cuanto más rápido seas, mayor será tu recompensa al final de la carrera.",
    ["As you go through each gate you'll be told where the next gate can be found."] = "A medida que atraviesas cada puerta, se te indicará dónde se puede encontrar la siguiente puerta.",
    ["Remember, you'll need to be wearing a Terrorbird mount to be able to take part. It adds to the fun!"] = "Recuerda, necesitarás llevar una montura Terrorbird para poder participar. ¡Se suma a la diversión!",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["Where can I get a Terrorbird costume?"] = "¿Dónde puedo conseguir un disfraz de Terrorbird?",
    ["You can wear your own Terrorbird mount costume but there is a special Christmas themed one available for free in Solomon's Store."] = "Puedes usar tu propio disfraz de montura Terrorbird, pero hay uno especial con temática navideña disponible de forma gratuita en la tienda de Solomon.",
    ["How do the hi-scores work?"] = "¿Cómo funcionan las puntuaciones altas?",
    ["The top 10 quickest times are stored and can be seen by checking on any of the race gates."] = "Los 10 tiempos más rápidos se almacenan y se pueden ver consultando cualquiera de las puertas de la carrera.",
    ["Hopefully you'll make the top 10!"] = "¡Ojalá llegues al top 10!",
    ["Happy racing!"] = "¡Felices carreras!",
    ["The elf seems to be muttering to herself."] = "La elfa parece estar murmurando para sí misma.",
    ["...Brown paper, who has brown paper, what is the point of brown paper?..."] = "...Papel marrón, quién tiene papel marrón, ¿para qué sirve el papel marrón?...",
    ["...pretending like I'm not here..."] = "...fingiendo que no estoy aquí...",
    ["...we have more wrapping paper than snow..."] = "...tenemos más papel de regalo que nieve...",
    ["...just have to ask..."] = "...sólo tengo que preguntar...",
    ["You back away quietly."] = "Retrocedes en silencio.",
    ["...They really think I can't hear them..."] = "...Realmente creen que no puedo oírlos...",
    ["...thinking that whistling is working..."] = "...pensando que silbar funciona...",
    ["...I could do a better job alone..."] = "...Podría hacer un mejor trabajo solo...",
    ["...if I could just get rid of these two boneheads..."] = "...si pudiera deshacerme de estos dos idiotas...",
    ["...it'd be so easy..."] = "...sería tan fácil...",
    ["That's not very Christmassy of you."] = "Eso no es muy navideño de tu parte.",
    ["Pardon!?"] = "¿¡Perdón!?",
    ["Nothing! Carry on."] = "¡Nada! Continuar.",
    ["Welcome, human, to the Quality Weapons Shop! Can I interest you in a purchase?"] = "¡Bienvenido, humano, a Quality Weapons Shop! ¿Puedo interesarte en una compra?",
    ["Welcome, human, to the Quality Weapons Shop! Since the defeat of the Red Axe, I now have dragon battlestaves in stock. Can I interest you in a purchase?"] = "¡Bienvenido, humano, a Quality Weapons Shop! Desde la derrota del Hacha Roja, ahora tengo bastones de batalla de dragones en stock. ¿Puedo interesarte en una compra?",
    ["Yes, I'm looking for some weapons."] = "Sí, estoy buscando algunas armas.",
    ["Dragon battlestaves?"] = "¿Bastones de batalla de dragones?",
    ["Yes! Colonel Grenda recovered Hreidmar's dragon battlestaff from his palace. I've examined it and learned how to create more."] = "¡Sí! Colonel Grenda recuperó el dragón battlestaff de Hreidmar de su palacio. Lo examiné y aprendí a crear más.",
    ["It's a remarkable weapon. Hugi the librarian claims it might date back to the very early days of Keldagrim, before even the Age of Kings!"] = "Es un arma extraordinaria. Hugi, el bibliotecario, afirma que podría remontarse a los primeros días de Keldagrim, ¡incluso antes de la Era de los Reyes!",
    ["Unfortunately it requires a lot of expensive raw materials, so I've got to charge you for them, even if you did lead to its capture."] = "Desafortunadamente requiere muchas materias primas costosas, así que tengo que cobrarte por ellas, incluso si condujiste a su captura.",
    ["Are you interested?"] = "¿Estás interesado?",
    ["Good day to you, human. I have a little task for you, are you interested?"] = "Buenos días para ti, humano. Tengo una pequeña tarea para ti, ¿estás interesado?",
    ["What's the task?"] = "¿Cuál es la tarea?",
    ["Oh, it's nothing too major. But I need [item] in the next [number] minutes."] = "Oh, no es nada demasiado importante. Pero necesito [item] en los próximos minutos [número].",
    ["Sure, got it. That's [item] in the next [number] minutes, I'll get right on it."] = "Claro, lo tengo. Eso es [item] en los próximos minutos [número], me pondré manos a la obra.",
    ["Sorry, I'm a little busy."] = "Lo siento, estoy un poco ocupado.",
    ["No problem, I'll find someone else to do it!"] = "No hay problema, ¡buscaré a alguien más para hacerlo!",
    ["Did you get [item], perchance?"] = "¿Conseguiste [item], tal vez?",
    ["No, I've given up on that."] = "No, ya me di por vencido.",
    ["That's very unfortunate to hear. I suppose I will need to find someone else now."] = "Es muy desafortunado escuchar eso. Supongo que tendré que encontrar a alguien más ahora.",
    ["No, I'm still looking for them."] = "No, todavía los estoy buscando.",
    ["Keep it up, I'm sure you'll succeed."] = "Sigue así, estoy seguro de que lo conseguirás.",
    ["Look, I've got you your [item]!"] = "¡Mira, te tengo tu [item]!",
    ["That's wonderful, thanks a lot Player! Do you want me to pay you in gold or do you wish me to teach you how to attack with these?"] = "¡Eso es maravilloso, muchas gracias Player! ¿Quieres que te pague en oro o quieres que te enseñe a atacar con estos?",
    ["Show me the gold!"] = "¡Muéstrame el oro!",
    ["Enlighten me."] = "Ilumíname.",
    ["You feel more experienced."] = "Te sientes más experimentado.",
    ["*When speaking to Sara Onnear in Draynor Village.*"] = "*Al hablar con Sara Onnear en Draynor Village.*",
    ["No, no, no! This isn't right at all!"] = "¡No, no, no! ¡Esto no está nada bien!",
    ["What's wrong?"] = "¿Qué pasa?",
    ["I'm trying to train my divination, but I'm just not getting it right! Perhaps I should ask Orla how to do it. Again..."] = "¡Estoy intentando entrenar mi adivinación, pero no lo hago bien! Quizás debería preguntarle a Orla cómo hacerlo. De nuevo...",
    ["*Before completion of Missing, Presumed Death:*"] = "*Antes de completar Desaparecido, Muerte Presunta:*",
    ["So, this is the World Guardian. I believe the standard line is 'I expected someone taller', but I have no desire to offend you this day."] = "Entonces, este es el Guardián Mundial. Creo que la frase estándar es \"Esperaba a alguien más alto\", pero no tengo ningún deseo de ofenderte este día.",
    ["I assume I do not need to introduce myself. My religion has been the primary religion of humanity since before humanity left Teragard."] = "Supongo que no necesito presentarme. Mi religión ha sido la religión principal de la humanidad desde antes de que la humanidad abandonara Teragard.",
    ["Why are you back now?"] = "¿Por qué has vuelto ahora?",
    ["Because the other gods are here and when the gods gather it means that something dangerous is approaching."] = "Porque los otros dioses están aquí y cuando los dioses se reúnen significa que algo peligroso se acerca.",
    ["I must be there to help guide people towards a sensible outcome, for the younger gods are not wise enough to do so without me."] = "Debo estar allí para ayudar a guiar a la gente hacia un resultado sensato, porque los dioses más jóvenes no son lo suficientemente sabios como para hacerlo sin mí.",
    ["*After completion of Missing, Presumed Death:*"] = "*Después de completar Desaparecido, Muerte Presunta:*",
    ["Hello again World Guardian<!-- different if not world guardian? -->. I assume you've noticed how shadows have begun to fall strangely across the world. It is the strange light that heralds an eclipse, the time when Zanaris blocks the light of the sun. A time of great power, and even greater danger. We both know what this eclipse heralds. Sliske's final pieces of his inevitable trap have fallen into place and we gods must spring it."] = "Hola de nuevo World Guardian<!-- different if not world guardian? -->. Supongo que habrás notado cómo las sombras han comenzado a caer de manera extraña en todo el mundo. Es la extraña luz que presagia un eclipse, el momento en que Zanaris bloquea la luz del sol. Una época de gran poder y peligro aún mayor. Ambos sabemos lo que presagia este eclipse. Las últimas piezas de la inevitable trampa de Sliske han caído en su lugar y nosotros, los dioses, debemos activarlas.",
    ["Could you not just stay away and avoid the trap?"] = "¿No podrías simplemente mantenerte alejado y evitar la trampa?",
    ["Would that we could Player, but no. We gods must answer this call, or the stone will inevitably fall into the wrong hands. Zamorak, Zaros, even Armadyl and Seren. If any of these were to claim the stone, it would lead to war. No, the stone must be claimed by a strong god. A god wise enough to use it. Only I have such experience. Only I can be trusted to save the lesser gods from themselves."] = "Ojalá pudiéramos Player, pero no. Nosotros, los dioses, debemos responder a este llamado, o la piedra caerá inevitablemente en las manos equivocadas. Zamorak, Zaros, incluso Armadyl y Seren. Si alguno de ellos reclamara la piedra, conduciría a la guerra. No, la piedra debe ser reclamada por un dios fuerte. Un dios lo suficientemente sabio como para usarlo. Sólo yo tengo esa experiencia. Sólo yo puedo confiar en mí para salvar a los dioses menores de sí mismos.",
    ["*After completion of Evil Dave's Big Day Out:*"] = "*Después de completar el Gran Día Fuera de Evil Dave:*",
    ["Sorry - I didn't recognise you when you weren't acting like a toddler and being a gigantic pain in my divine behind."] = "Lo siento, no te reconocí cuando no actuabas como un niño pequeño y eras un dolor gigantesco en mi divino trasero.",
    ["How are you and Zamorak getting on? Best friends?"] = "¿Cómo os lleváis tú y Zamorak? ¿Mejores amigos?",
    ["Just kidding, I seriously don't care. Get out of my sight."] = "Es broma, en serio, no me importa. Fuera de mi vista.",
    ["Can I talk to you about Sliske's game?"] = "¿Puedo hablarte sobre el juego de Sliske?",
    ["It is better that the stone is lost, than for it to have fallen into enemy hands."] = "Es mejor que la piedra se pierda, que haber caído en manos enemigas.",
    ["Still without the stone what becomes of the dragonkin now? This is not the end of the danger they represent. Merely the beginning."] = "Aún sin la piedra, ¿qué será de los dragonantes ahora? Este no es el final del peligro que representan. Simplemente el comienzo.",
    ["Can I ask you about..."] = "¿Puedo preguntarte sobre...?",
    ["Armadyl showed great promise when I first encountered him. A willingness to learn and a drive for justice that appealed to my own. He was a young deity, but not a rival, and I saw a wisdom in taking him under my wing...if you'll pardon the pun. During the conflict with the vile Zamorak, Armadyl counselled a temporary alliance with ourselves and the warmongering Bandos. A wise move, for Zamorak was the more immediate threat. Sadly, that allegiance would not last. Old rivalries proved more important than reason. Armadyl's people would perhaps suffer the most from the conflict that followed. I know Armadyl holds me in some way responsible. i suspect he is unwilling to recognise his own fault in this. Still, I would be willing to accept vassalage of Armadyl and his people. They are a noble species and I believe they would benefit from my tutelage."] = "Armadyl se mostró muy prometedor cuando lo conocí por primera vez. Una voluntad de aprender y un impulso por la justicia que atraía al mío. Era una deidad joven, pero no un rival, y vi que era una sabiduría tomarlo bajo mi protección... si me permiten el juego de palabras. Durante el conflicto con el vil Zamorak, Armadyl aconsejó una alianza temporal con nosotros y el belicista Bandos. Un acierto, ya que Zamorak era la amenaza más inmediata. Lamentablemente, esa lealtad no duraría. Las viejas rivalidades resultaron más importantes que la razón. La gente de Armadyl tal vez sería la que más sufriría el conflicto que siguió. Sé que Armadyl me hace responsable de alguna manera. Sospecho que no está dispuesto a reconocer su propia culpa en esto. Aún así, estaría dispuesto a aceptar el vasallaje de Armadyl y su gente. Son una especie noble y creo que se beneficiarían de mi tutela.",
    ["*(Shows previous options)*"] = "*(Muestra opciones anteriores)*",
    ["Seren thinks of herself as a good, kind, deity, but she is a fraud. She enslaved her people and she refuses to help anyone beyond her precious elves. A benevolent god would seek to protect all people, not just a subset."] = "Seren se considera una deidad buena y amable, pero es un fraude. Esclavizó a su pueblo y se niega a ayudar a nadie más que a sus preciosos elfos. Un dios benévolo buscaría proteger a todas las personas, no sólo a un subconjunto.",
    ["Would you?"] = "¿Lo harías?",
    ["What alternative is there? Understand. I do not say this out of arrogance. I have lived millennia, and in that time I have seen countless governments rise and fall. There is a pattern to the ascendance and collapse of civilisation. A cycle of tragedy. I have the knowledge to break this cycle, and most importantly the will to lead everyone forwards. Is it wrong to use this knowledge? Gielinor, and other worlds, would be bought to a new future. A utopia. Other gods can claim this, but only I have the experience necessary to make it happen."] = "¿Qué alternativa hay? Entender. No lo digo por arrogancia. He vivido milenios y en ese tiempo he visto incontables gobiernos surgir y caer. Hay un patrón en el ascenso y el colapso de la civilización. Un ciclo de tragedia. Tengo el conocimiento para romper este ciclo y, lo más importante, la voluntad de guiar a todos hacia adelante. ¿Está mal utilizar este conocimiento? Gielinor y otros mundos serían comprados para un nuevo futuro. Una utopía. Otros dioses pueden reclamar esto, pero sólo yo tengo la experiencia necesaria para hacerlo realidad.",
    ["*(Shows previous-to-previous options)*"] = "*(Muestra opciones anteriores a anteriores)*",
    ["You mean control them?"] = "¿Quieres decir controlarlos?",
    ["You say that as though it were a bad thing. People need to be led. They need governments. They need leaders. They need structures. Freedom doesn't mean anarchy. Just as control doesn't have to mean slavery. I offer guidance and leadership. Law and order. Under my 'control', people could thrive. Everyone would have the reassurance that they know where they belong and how they should behave. The people crave. Deep down everyone wants to know where they sit in the world. What you call control, I would argue is true freedom. Freedom to know how life should be lived and how to fulfil once potential."] = "Dices eso como si fuera algo malo. La gente necesita ser guiada. Necesitan gobiernos. Necesitan líderes. Necesitan estructuras. Libertad no significa anarquía. Así como control no tiene por qué significar esclavitud. Ofrezco orientación y liderazgo. Orden público. Bajo mi \"control\", la gente podría prosperar. Todos tendrían la seguridad de saber a dónde pertenecen y cómo deben comportarse. La gente anhela. En el fondo, todo el mundo quiere saber dónde se encuentra en el mundo. Yo diría que lo que usted llama control es verdadera libertad. Libertad para saber cómo se debe vivir la vida y cómo realizarla una vez potencial.",
    ["[Say nothing]"] = "[no digas nada]",
    ["I have walked many worlds and interacted with numerous deities, but none I find quite as deplorable as the usurper Zamorak. Even his divine nature is brought about by the betrayal of one he claimed to serve. The theft of another's essence. He preaches a creed of 'strength through chaos', spreading the lie that his acts of wanton cruelty are really lessons that help us grow. Why must people die for us to learn how to defend them? Could he not simply teach them? Offer the people ways to improve themselves, spread his meagre knowledge to better them? No. Instead he sends demons to raid their villages. He tricks learned mages into dabbling with foreign magics. Then Zamorak watches as people die in suffering and agony. Where is the strength in that? Where is the wisdom? It's psychotic indulgence of a monster, not the acts of a god."] = "He caminado por muchos mundos e interactuado con numerosas deidades, pero ninguna me parece tan deplorable como el usurpador Zamorak. Incluso su naturaleza divina se debe a la traición de alguien a quien afirmaba servir. El robo de la esencia ajena. Predica un credo de \"fuerza a través del caos\", difundiendo la mentira de que sus actos de crueldad sin sentido son en realidad lecciones que nos ayudan a crecer. ¿Por qué la gente debe morir para que aprendamos a defenderla? ¿No podría simplemente enseñarles? ¿Ofrecer a la gente formas de mejorarse, difundir sus escasos conocimientos para mejorarlos? No. En lugar de eso, envía demonios a asaltar sus aldeas. Engaña a magos eruditos para que incursionen en magias extranjeras. Luego, Zamorak observa cómo la gente muere en sufrimiento y agonía. ¿Dónde está la fuerza en eso? ¿Dónde está la sabiduría? Es la indulgencia psicótica de un monstruo, no los actos de un dios.",
    ["You've killed people, though."] = "Pero has matado gente.",
    ["Yes. I have taken lives in my time. I won't deny that. But i have always done so with purpose...with greater good in mind. I fought wars because there are some who understand no other discussion. Without the clash of sword and shield, they cannot hear reason. It is silence to them. I have committed acts that some would call cruel, but they are a woeful necessity. Once I was forced to take the wings of an icyene. To tear them from her back and leave to the the mercy of winter. We were heading into a time of war, against an aggressor native to Hallow. I had been forced to militarise the noble icyene. The icyene are a powerful race, but still mortal, and their numbers comparatively few. I needed each of them to stand up and join the fight, less they all suffer. But one refused. She cried out that the conflict would solve nothing. She proclaimed that all icyene should lay down their spear and embrace a peaceful approach. Her words were...enticing. I wanted to follow them myself. I would have loved little more than for conflict to end and peace to flourish. But I knew better. I knew inaction would lead to the destruction of my people. I had to show the icyene what they faced if they did not fight. I had to show them how the enemy would show no mercy...just as I had to show no mercy. I will not forget that...feeling. that horrible stretching sensation followed by that terrible, sudden, snap. Feathers and tendons falling around me like some horrible snowstorm. It was...cruel, but I had no choice. That act reminded the icyene why they were fighting, what they were fighting, and it reminded them that everyone must do their duty. A moment of cruelty, for decades of prosperity. A fair, if unsightly, trade."] = "Sí. He quitado vidas en mi tiempo. No lo negaré. Pero siempre lo he hecho con un propósito... con un bien mayor en mente. Peleé guerras porque hay algunos que no entienden otra discusión. Sin el choque de espada y escudo, no pueden entrar en razón. Para ellos es silencio. He cometido actos que algunos llamarían crueles, pero son una necesidad lamentable. Una vez me obligaron a tomar las alas de un helado. Para arrancarlos de su espalda y dejarlos a merced del invierno. Nos dirigíamos a una época de guerra, contra un agresor nativo de Hallow. Me había visto obligado a militarizar al noble icyene. Los icyene son una raza poderosa, pero aún mortal, y su número es comparativamente reducido. Necesitaba que cada uno de ellos se levantara y se uniera a la lucha, para que todos no sufrieran. Pero uno se negó. Ella gritó que el conflicto no resolvería nada. Proclamó que todos los icyene deberían deponer la lanza y adoptar un enfoque pacífico. Sus palabras fueron... tentadoras. Quería seguirlos yo mismo. Me hubiera gustado poco más que terminar el conflicto y florecer la paz. Pero yo lo sabía mejor. Sabía que la inacción conduciría a la destrucción de mi pueblo. Tenía que mostrarle a los icyene a qué se enfrentarían si no luchaban. Tenía que mostrarles cómo el enemigo no mostraría piedad... así como yo no tenía que mostrar piedad. No olvidaré ese... sentimiento. esa horrible sensación de estiramiento seguida de ese terrible y repentino chasquido. Plumas y tendones cayendo a mi alrededor como una horrible tormenta de nieve. Fue... cruel, pero no tuve elección. Ese acto les recordó a los icyene por qué estaban peleando, contra qué estaban peleando, y les recordó que todos deben cumplir con su deber. Un momento de crueldad, para décadas de prosperidad. Un comercio justo, aunque desagradable.",
    ["Thats not how Garlandia sees it"] = "No es así como lo ve Garlandia.",
    ["No. I imagine not. She will only see the barbarism and the cruelty, but the lesson was, ultimately, not for her."] = "No. Me imagino que no. Ella sólo verá la barbarie y la crueldad, pero la lección, en última instancia, no fue para ella.",
    ["*(Shows previous-to-previous-to-previous options)*"] = "*(Muestra opciones de anterior a anterior a anterior)*",
    ["[Stay silent]"] = "[quédate en silencio]",
    ["*(Shows previous-to-previous-to-previous otpions)*"] = "*(Muestra opciones anteriores a anteriores)*",
    ["They better themselves."] = "Se mejoran a sí mismos.",
    ["But do they? Really? What of the ones who die? Their potential lost, squandered and meaningless."] = "¿Pero lo hacen? ¿En realidad? ¿Qué pasa con los que mueren? Su potencial perdido, desperdiciado y sin sentido.",
    ["What of the wise scholar, whose library is burned to the ground. He becomes a builder, reclaiming what was lost, but he could have resolved vital mysteries."] = "¿Qué pasa con el sabio erudito, cuya biblioteca está quemada hasta los cimientos? Se convierte en constructor, recupera lo perdido, pero podría haber resuelto misterios vitales.",
    ["At best, chaos is an engine for change, but it is change without focus or purpose. Simply reaction, rather than evolution. There are better ways."] = "En el mejor de los casos, el caos es un motor de cambio, pero es un cambio sin enfoque ni propósito. Simplemente reacción, más que evolución. Hay mejores maneras.",
    ["No. Zamorak is a dangerous creature with delusions of grandeur; little more."] = "No. Zamorak es una criatura peligrosa con delirios de grandeza; poco más.",
    ["Ah, yes. The \"Empty Lord\". The lord of the Empty Throne who ruled his empire from the shadows. Another god whose lethargy was stronger than his leadership skills. He ruled from seclusion, letting his own people do the work for him. No wonder he was betrayed. He would have you believe he is a guide rather than a monarch, but he lacks the conviction to truly lead. True leadership is sacrifice. A willingness to give yourself fully to guiding your people."] = "Ah, sí. El \"Señor Vacío\". El señor del Trono Vacío que gobernó su imperio desde las sombras. Otro dios cuyo letargo era más fuerte que sus habilidades de liderazgo. Gobernó desde su reclusión, dejando que su propio pueblo hiciera el trabajo por él. No es de extrañar que haya sido traicionado. Quiere hacerte creer que es un guía más que un monarca, pero carece de la convicción para liderar de verdad. El verdadero liderazgo es sacrificio. La voluntad de entregarse plenamente para guiar a su pueblo.",
    ["Zaros is our only hope."] = "Zaros es nuestra única esperanza.",
    ["You think so? Who told you this? Hmm? Was it the Empty Lord himself, perchance? Or one of his sycophants? I would expect more from the World Guardian. You are a role model...an inspiration to some. I would counsel you to use more common sense. Zaros has an agenda. Just as we all do."] = "¿Crees que sí? ¿Quién te dijo esto? ¿Mmm? ¿Fue tal vez el mismísimo Señor Vacío? ¿O uno de sus aduladores? Esperaría más del World Guardian. Eres un modelo a seguir... una inspiración para algunos. Le aconsejaría que utilice más el sentido común. Zaros tiene una agenda. Tal como lo hacemos todos.",
    ["[More Options]"] = "[Más opciones]",
    ["And you would expect me to say what about this hulking monstrosity? Should I be in awe? Should I cower in fear? I have wandered worlds long before the first footprints pressed into Gielinor. In that time, I have witnessed wonders and nightmares that make this Vorago pale in comparison. I am not sure why Sliske invited him, but his presence changes little."] = "¿Y esperarías que dijera qué pasa con esta enorme monstruosidad? ¿Debería estar asombrado? ¿Debería encogerme de miedo? He vagado por mundos mucho antes de que las primeras huellas se dejaran en Gielinor. En ese tiempo, he sido testigo de maravillas y pesadillas que hacen que este Vorago palidezca en comparación. No estoy seguro de por qué Sliske lo invitó, pero su presencia cambia poco.",
    ["He serves a noble purpose. I can respect that. If he sticks to his duty I will have no qualms with him."] = "Tiene un propósito noble. Puedo respetar eso. Si cumple con su deber no tendré ningún reparo con él.",
    ["Death"] = "Muerte",
    ["Death performs a necessary function, however little most mortals may like it. It is a lonely, but important job. I wish him well. That said, it would be unwise to allow Death to claim the stone. There is a natural order to things, and we should not risk that."] = "La muerte cumple una función necesaria, por poco que le guste a la mayoría de los mortales. Es un trabajo solitario pero importante. Le deseo lo mejor. Dicho esto, sería imprudente permitir que la Muerte reclame la piedra. Hay un orden natural en las cosas y no debemos arriesgarnos a eso.",
    ["Sliske is a dangerous creature. Perhaps even more so than Zamorak. Both seek chaos, but at least one seeks chaos for a purpose. Sliske just wants to see the world aflame, with all hope and purpose cast into the inferno for his amusement. That such a lunatic could possess the stone is concerning. That such a lunatic has chosen not to ascend, perhaps more worrying still. If he craved power, I could understand. If he craved a nihilistic end to existence, I could perhaps begin to understand that. But Sliske's motivations appear...incomprehensible, and that concerns me greatly."] = "Sliske es una criatura peligrosa. Quizás incluso más que Zamorak. Ambos buscan el caos, pero al menos uno busca el caos con un propósito. Sliske sólo quiere ver el mundo en llamas, con toda la esperanza y el propósito arrojados al infierno para su diversión. Que un lunático así pueda poseer la piedra es preocupante. Que un lunático así haya decidido no ascender, quizás sea aún más preocupante. Si ansiaba poder, podría entenderlo. Si anhelaba un final nihilista para su existencia, tal vez podría empezar a entenderlo. Pero las motivaciones de Sliske parecen... incomprensibles, y eso me preocupa mucho.",
    ["There is little point to speak of the dead. Bandos had his merits and his flaws, but he is gone now and no more needs to be said."] = "No tiene mucho sentido hablar de los muertos. Bandos tuvo sus méritos y sus defectos, pero ya no está y no hace falta decir más.",
    ["The Dragonkin"] = "Los dragonantes",
    ["I have little to say of these creatures. They are dangerous beasts, little more."] = "Tengo poco que decir de estas criaturas. Son bestias peligrosas, poco más.",
    ["You get the impression that Saradomin may be hiding something."] = "Da la impresión de que Saradomin puede estar ocultando algo.",
    ["Ha ha ha. That thing calls itself a god? Laughable. Truly. Whatever that thing is, it has demonstrated no real power and has no real followers. I find it almost contemptible that we're even discussing it."] = "Ja, ja, ja. ¿Esa cosa se llama a sí misma un dios? Cómico. Realmente. Sea lo que sea, no ha demostrado ningún poder real y no tiene seguidores reales. Me parece casi despreciable que estemos siquiera discutiéndolo.",
    ["We will not discuss that...that...drunken harlot."] = "No hablaremos de esa... esa... ramera borracha.",
    ["[See previous options]"] = "[Ver opciones anteriores]",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["[Ask about something else]"] = "[pregunta sobre otra cosa]",
    ["*(Shows initial options)*"] = "*(Muestra opciones iniciales)*",
    ["Goodbye"] = "Adiós",
    ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
    ["Can you talk about your history?"] = "¿Puedes hablar de tu historia?",
    ["How did you ascend?"] = "¿Cómo ascendiste?",
    ["*If consistently aligned to Saradomin*"] = "*Si está consistentemente alineado con Saradomin*",
    ["I was a justicar on Teragard, one tasked with upholding and enforcing the law. I risked my life each day to preserve order and protect the innocent. At times the forces of avarice and corruption I fought against seemed insurmountable. Upholding the law was a tough yet noble duty, and my obsession. It took its toll on me, and my family, but my community thrived as a result. Perhaps that's why the Crown chose me. It could sense in me the drive for order. The yearning for the world to be the best it could. You perhaps expect the Crown to have been discovered at the end of an epic quest. Perhaps I slew demons or wrestled chthonic entities into the abyss, but I did none of these things. Instead, whilst hunting down a criminal, I discovered a cave that hadn't seen human life...ever. Within, I saw a golden circlet that called out to me, choosing me. This was the Crown and I knew without hesitation that it was made for me. That I had been chosen. My apotheosis did not happen overnight. The Crown led me to objects of power and importance, and these became my tools. With them, I began to slowly reshape Teragard into something greater. Over time, I discovered the tools were no longer necessary, and that I now wielded the power without them. Henceforth, my power grew and grew, and I took my rightful place as the god of Teragard. Progression from there was obvious and inevitable. I realized that there would be other worlds out there, worlds that needed guidance and order. I would not leave them forgotten."] = "Yo era un justicar en Teragard, encargado de defender y hacer cumplir la ley. Arriesgué mi vida todos los días para preservar el orden y proteger a los inocentes. En ocasiones, las fuerzas de la avaricia y la corrupción contra las que luché parecían insuperables. Defender la ley era un deber duro pero noble, y mi obsesión. Me pasó factura a mí y a mi familia, pero como resultado mi comunidad prosperó. Quizás por eso me eligió la Corona. Podía sentir en mí el impulso por el orden. El anhelo de que el mundo sea lo mejor que pueda. Quizás esperes que la Corona haya sido descubierta al final de una búsqueda épica. Quizás maté demonios o luché con entidades ctónicas hacia el abismo, pero no hice ninguna de estas cosas. En cambio, mientras perseguía a un criminal, descubrí una cueva en la que nunca había visto vida humana... nunca. Dentro, vi un círculo dorado que me llamaba, eligiéndome. Esta era la Corona y supe sin dudarlo que estaba hecha para mí. Que yo había sido elegido. Mi apoteosis no ocurrió de la noche a la mañana. La Corona me llevó a objetos de poder e importancia, y éstos se convirtieron en mis herramientas. Con ellos, comencé a transformar lentamente a Teragard en algo más grande. Con el tiempo, descubrí que las herramientas ya no eran necesarias y que ahora ejercía el poder sin ellas. A partir de entonces, mi poder creció y creció, y tomé el lugar que me correspondía como dios de Teragard. La progresión a partir de ahí fue obvia e inevitable. Me di cuenta de que habría otros mundos ahí fuera, mundos que necesitaban guía y orden. No los dejaría olvidados.",
    ["*If unaligned to Saradomin:*"] = "*Si no está alineado con Saradomin:*",
    ["No. You have shown me little loyalty, so I see no reason to explain my secrets."] = "No. Me has mostrado poca lealtad, así que no veo ninguna razón para explicar mis secretos.",
    ["*If you have not consistently supported Saradomin (unknown condition)): *"] = "*Si no ha apoyado consistentemente a Saradomin (condición desconocida)): *",
    ["Whilst your allegiance to me now is gratifying, your track record has been less than exceptional. Perhaps in future I will have this conversation, but not today. Forgive me."] = "Si bien su lealtad hacia mí ahora es gratificante, su historial no ha sido excepcional. Quizás en el futuro tenga esta conversación, pero hoy no. Perdóname.",
    ["Can you tell me about Teragard?"] = "¿Puedes hablarme de Teragard?",
    ["The birthplace of humanity is a beautiful world, if not a kind one. Snow covers the lands and the winds would chill you to the bone. Nonetheless, it was my home. We were disparate nations, spread across the world. When I ascended, I decided to rectify that. To bring an end to pointless conflicts over invisible territorial lines that serve no one. I created magisters...priests and teachers who were to act as my authority where I could not. They were learned individuals whom I would personally instruct on what lessons to teach others. I created twelve in total, each tasked with governing a different part of the world, and each given a mandate to improve humanity in line with my teachings. With the magisters in place, my people prospered, and entered a glorious age of enlightenment. Confident that my world was in safe hands, I turned my attention to other worlds in greater need of my assistance."] = "El lugar de nacimiento de la humanidad es un mundo hermoso, si no amable. La nieve cubre las tierras y los vientos te congelarían hasta los huesos. Sin embargo, era mi hogar. Éramos naciones dispares, repartidas por todo el mundo. Cuando ascendí, decidí rectificar eso. Poner fin a los conflictos inútiles por líneas territoriales invisibles que no sirven a nadie. Creé magistrados... sacerdotes y maestros que actuarían como mi autoridad donde yo no podía. Eran personas cultas a quienes yo personalmente instruía sobre qué lecciones enseñar a otros. Creé doce en total, cada uno con la tarea de gobernar una parte diferente del mundo, y a cada uno con el mandato de mejorar la humanidad de acuerdo con mis enseñanzas. Con los magistrados en sus puestos, mi pueblo prosperó y entró en una gloriosa era de iluminación. Confiado en que mi mundo estaba en buenas manos, centré mi atención en otros mundos que necesitaban más mi ayuda.",
    ["Do you often return to Teragard?"] = "¿Regresas a menudo a Teragard?",
    ["I...have not yet had the opportunity. Other worlds have greater need of my attention."] = "Yo... todavía no he tenido la oportunidad. Otros mundos tienen mayor necesidad de mi atención.",
    ["Can you tell me about your family?"] = "¿Puedes hablarme de tu familia?",
    ["What family I had are long since dead."] = "La familia que tenía hace tiempo que murió.",
    ["I'm sorry."] = "Lo siento.",
    ["There is no reason to be, it was millennia ago. Death comes to all mortals. I watched each of my family line wither and die, and could do nothing to prevent the ravages of time. At one time, I held onto their personal possessions, but they have long since disintegrated. All I have of them are the memories I carry through the ages, though I barely recall the names of my parents or the colour of my wife's eyes. They are part of the life of the man I was before, not the god I am now. I have moved on from that life and embraced a greater responsibility."] = "No hay razón para serlo, fue hace milenios. La muerte llega a todos los mortales. Vi a cada miembro de mi línea familiar marchitarse y morir, y no pude hacer nada para evitar los estragos del tiempo. Hubo un tiempo en que conservé sus pertenencias personales, pero hace tiempo que se desintegraron. Lo único que tengo de ellos son los recuerdos que llevo a través de los tiempos, aunque apenas recuerdo los nombres de mis padres o el color de ojos de mi esposa. Son parte de la vida del hombre que era antes, no del dios que soy ahora. Dejé atrás esa vida y acepté una mayor responsabilidad.",
    ["They are part of the life of the man I was before, not the god I am now. I have moved on from that life and embraced a greater responsibility."] = "Son parte de la vida del hombre que era antes, no del dios que soy ahora. Dejé atrás esa vida y acepté una mayor responsabilidad.",
    ["Can you tell me about Hallow?"] = "¿Puedes hablarme de Hallow?",
    ["It is a beautiful world filled with noble creatures. The transition from day to night takes almost a year as you know it, so each night the icyene move from one island to the next. The migrations are such a sight to behold. Flocks of icyene abandon one home and fly across the oceans to settle once more in structures that have lain empty for the entire winter."] = "Es un mundo hermoso lleno de criaturas nobles. La transición del día a la noche lleva casi un año como la conoces, por lo que cada noche los hielos se mueven de una isla a la siguiente. Las migraciones son un espectáculo digno de contemplar. Bandadas de icyene abandonan su hogar y vuelan a través de los océanos para establecerse una vez más en estructuras que han permanecido vacías durante todo el invierno.",
    ["Are there any other races there?"] = "¿Hay otras carreras allí?",
    ["There are other creatures, certainly. Skypouncers roam the plains and there are visitors from other worlds from time to time...but natives...no."] = "Ciertamente hay otras criaturas. Los saltadores del cielo deambulan por las llanuras y hay visitantes de otros mundos de vez en cuando... pero nativos... no.",
    ["Saradomin doesn't say the words 'no longer' but they hang in the air, spoken but unsaid."] = "Saradomin no dice las palabras \"ya no\", pero quedan suspendidas en el aire, dichas pero no dichas.",
    ["Ask about something else."] = "Pregunta por otra cosa.",
    ["I want to side with you."] = "Quiero estar de tu lado.",
    ["Side with Saradomin in the endgame?"] = "¿Del lado de Saradomin en el final del juego?",
    ["Yes"] = "si",
    ["Saradomin, you deserve the stone. I shall stand with you."] = "Saradomin, te mereces la piedra. Estaré contigo.",
    ["Thank you, Player. Together we will lay the foundation for a glorious future."] = "Gracias, Player. Juntos sentaremos las bases de un futuro glorioso.",
    ["*When talking to Saradominist Priest in the of Explorer Jack's house in Lumbridge.*"] = "*Al hablar con Saradominist Priest en el de la casa de Explorer Jack en Lumbridge.*",
    ["It's been rough recently but thanks to Saradomin and Duke Horacio we've moved here. I've got to admit it's getting better, so much better, all the time."] = "Ha sido difícil últimamente, pero gracias a Saradomin y Duke Horacio nos hemos mudado aquí. Debo admitir que está mejorando, mucho mejor, todo el tiempo.",
    ["*When talking to Saradominist Priestess in the of Explorer Jack's house in Lumbridge.*"] = "*Al hablar con Saradominist Priestess en el de la casa de Explorer Jack en Lumbridge.*",
    ["Our daughter loves this new place! She is over the moon talking to Explorer Jack about his adventures!"] = "¡A nuestra hija le encanta este nuevo lugar! ¡Está encantada de hablar con Explorer Jack sobre sus aventuras!",
    ["You look like a skilled adventurer. Would you like to join the forces of the holy Saradomin?"] = "Pareces un hábil aventurero. ¿Te gustaría unirte a las fuerzas del santo Saradomin?",
    ["Yes! Where do I sign up?"] = "¡Sí! ¿Dónde me registro?",
    ["I'm pleased to see there is still some good in the world!"] = "¡Me alegra ver que todavía hay algo bueno en el mundo!",
    ["You can find the forces of holy Saradomin by finding our recruitment officer in our camp. It's to the north of the battlefield by Lumbridge."] = "Puedes encontrar las fuerzas del santo Saradomin encontrando a nuestro oficial de reclutamiento en nuestro campamento. Está al norte del campo de batalla por Lumbridge.",
    ["You will be able to find out more about the skills we need there, although everyone has something to offer."] = "Allí podrás descubrir más sobre las habilidades que necesitamos, aunque todos tienen algo que ofrecer.",
    ["I thank you for your support. Know that our lord looks kindly on his followers."] = "Les agradezco su apoyo. Sepan que nuestro señor mira con bondad a sus seguidores.",
    ["Maybe. Why should I join you?"] = "Quizás. ¿Por qué debería unirme a usted?",
    ["Because we fight to defeat evil! For years, the power of Saradomin has kept the forces of Zamorak at bay."] = "¡Porque luchamos para derrotar al mal! Durante años, el poder de Saradomin ha mantenido a raya las fuerzas de Zamorak.",
    ["But now, with the return of Zamorak, the weak and the helpless are more vulnerable than ever."] = "Pero ahora, con el regreso de Zamorak, los débiles y los indefensos son más vulnerables que nunca.",
    ["Saradomin's forces are the barrier preventing chaos and death from reigning over the world!"] = "¡Las fuerzas de Saradomin son la barrera que impide que el caos y la muerte reine en el mundo!",
    ["We need all the help we can get. Whether you're a fighter, a fisher, a woodcutter or a miner, you can help tip the battle in our lords favour."] = "Necesitamos toda la ayuda que podamos conseguir. Ya seas un luchador, un pescador, un leñador o un minero, puedes ayudar a inclinar la batalla a favor de nuestro señor.",
    ["To join the forces of good and drive evil from the land, travel to the battlefield at Lumbridge, and talk to the recruiter in the north camp."] = "Para unirte a las fuerzas del bien y expulsar al mal de la tierra, viaja al campo de batalla en Lumbridge y habla con el reclutador en el campamento norte.",
    ["Great! I'm on my way!"] = "¡Genial! ¡Estoy en camino!",
    ["That's great news! I know that with your help we will keep the evil of Zamorak at bay."] = "¡Esa es una gran noticia! Sé que con tu ayuda mantendremos a raya la maldad de Zamorak.",
    ["No way! I support Zamorak!"] = "¡De ninguna manera! ¡Apoyo a Zamorak!",
    ["It truly pains me to see you sell your soul to evil."] = "Realmente me duele verte vender tu alma al mal.",
    ["It's not too late for you. You can still join the forces of good, if you head to Saradomin's camp at the north of the battlefield instead."] = "No es demasiado tarde para ti. Aún puedes unirte a las fuerzas del bien si te diriges al campamento de Saradomin en el norte del campo de batalla.",
    ["I don't want to get involved."] = "No quiero involucrarme.",
    ["How can you not take part? Zamorak is an evil that must be stopped at all cost."] = "¿Cómo no puedes participar? Zamorak es un mal que hay que detener a toda costa.",
    ["Please, for the vulnerable and the powerless in the world, you must side with us to defeat Zamorak!"] = "¡Por favor, para los vulnerables y los impotentes del mundo, debéis poneros del lado de nosotros para derrotar a Zamorak!",
    ["How you can side with evil I do not understand. You should go before I bring the wrath of the holy Saradomin upon you."] = "Cómo puedes ponerte del lado del mal, no lo entiendo. Deberías irte antes de que traiga sobre ti la ira del santo Saradomin.",
    ["I see you have already joined our cause, and I thank you. But please - go to the battlefield in Lumbridge before it's too late!"] = "Veo que ya te has unido a nuestra causa y te lo agradezco. Pero, por favor, ¡ve al campo de batalla en Lumbridge antes de que sea demasiado tarde!",
    ["Glory to Saradomin, the rightful victor of the Battle of Lumbridge!"] = "¡Gloria a Saradomin, el legítimo vencedor de la Batalla de Lumbridge!",
    ["What happened here?"] = "¿Qué pasó aquí?",
    ["You don't know?"] = "¿No lo sabes?",
    ["The Battle of Lumbridge was an epic battle fought between the noble god Saradomin and the wicked pretender god Zamorak."] = "La Batalla de Lumbridge fue una batalla épica librada entre el noble dios Saradomin y el malvado dios pretendiente Zamorak.",
    ["Zamorak came through a portal in Lumbridge and immediately began destroying everything around him. But then, the mighty Saradomin appeared and intervened, protecting us all."] = "Zamorak entró a través de un portal en Lumbridge e inmediatamente comenzó a destruir todo lo que lo rodeaba. Pero entonces, apareció el poderoso Saradomin e intervino, protegiéndonos a todos.",
    ["They locked blows, and both bore their full might down upon each other. The force of their fury rent the ground beneath our feet asunder and created the crater we see today."] = "Se dieron golpes y ambos lanzaron todo su poder el uno contra el otro. La fuerza de su furia desgarró el suelo bajo nuestros pies y creó el cráter que vemos hoy.",
    ["They locked blows, and both bore their full might down upon each other. The force of their fury rent the ground beneath our feet asunder."] = "Se dieron golpes y ambos lanzaron todo su poder el uno contra el otro. La fuerza de su furia desgarró el suelo bajo nuestros pies.",
    ["Locked in a stalemate, each summoned their mighty armies and waged war across Lumbridge."] = "Atrapados en un punto muerto, cada uno convocó a sus poderosos ejércitos y emprendió la guerra en Lumbridge.",
    ["They were locked in vicious battle for ten weeks, before Saradomin finally emerged victorious, leaving Zamorak broken and defeated."] = "Estuvieron enfrascados en una feroz batalla durante diez semanas, antes de que Saradomin finalmente saliera victorioso, dejando a Zamorak destrozado y derrotado.",
    ["What is that armour you're wearing?"] = "¿Qué es esa armadura que llevas?",
    ["This armour? Why it is the armour of the dedicated warriors of Saradomin."] = "¿Esta armadura? Por qué es la armadura de los dedicados guerreros de Saradomin.",
    ["Brave followers of Saradomin were given this armour when they had earned enough recognition with his army."] = "Los valientes seguidores de Saradomin recibieron esta armadura cuando obtuvieron suficiente reconocimiento con su ejército.",
    ["During the battle you could have claimed this from the quartermaster, if you fought for Saradomin. Other than that, it is only borne by from devout Saradominst warriors in the God Wars dungeon."] = "Durante la batalla podrías haberle reclamado esto al intendente, si hubieras luchado por Saradomin. Aparte de eso, solo lo soportan los devotos guerreros Saradominst en la mazmorra de God Wars.",
    ["Saradominist NPCs in the God Wars Dungeon can drop pieces of the Saradominist War Priest armour set when defeated."] = "Los NPC saradoministas en God Wars Dungeon pueden soltar piezas de la armadura Saradominist War Priest cuando son derrotados.",
    ["The vile Zamorakian forces have similar - though far more sinister - armour that can be taken from Zamorakian warriors in the God Wars Dungeon."] = "Las viles fuerzas zamorakianas tienen una armadura similar, aunque mucho más siniestra, que se les puede quitar a los guerreros zamorakianos en God Wars Dungeon.",
    ["You have insufficient space in your inventory to accept a token of fealty. Make 1 free space in your inventory then speak to the preacher again to reclaim your token of fealty."] = "No tienes espacio suficiente en tu inventario para aceptar una muestra de lealtad. Haz 1 espacio libre en tu inventario y luego habla con el predicador nuevamente para reclamar tu muestra de lealtad.",
    ["[You reclaim your token of fealty.]"] = "[Reclamas tu muestra de lealtad.]",
    ["What are you up to?"] = "¿Qué estás haciendo?",
    ["Well first I'm going to slay a few trolls, and then I'm going to sneak into a dragon's lair and steal all his gold."] = "Bueno, primero voy a matar a algunos trolls y luego me colaré en la guarida de un dragón y robaré todo su oro.",
    ["Or perhaps I'll spend the day doing mindless, repetitive chores. Either's fine with me."] = "O tal vez pase el día haciendo tareas repetitivas y sin sentido. Cualquiera de los dos está bien para mí.",
    ["Looks like you saved the day."] = "Parece que salvaste el día.",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["We've set up a fun coconut shy game. Just pick up some balls and try to knock off the coconuts."] = "Hemos creado un divertido juego de cocos tímidos. Simplemente recoge algunas bolas e intenta quitar los cocos.",
    ["It looks like some of the coconuts are stuck. You wouldn't know anything about that would you?"] = "Parece que algunos cocos están atascados. No sabrías nada sobre eso, ¿verdad?",
    ["What are you saying, deary? That you don't trust little old me? How dare you accuse me of such things!"] = "¿Qué estás diciendo, cariño? ¿Que no confías en mi pequeño? ¿Cómo te atreves a acusarme de esas cosas?",
    ["How does the coconut shy work?"] = "¿Cómo funciona el coco tímido?",
    ["Simply pick up some balls and try to knock off the coconuts. You get balls at a time to throw."] = "Simplemente recoge algunas bolas e intenta quitar los cocos. Obtienes bolas a la vez para lanzar.",
    ["How does the hook a duck work?"] = "¿Cómo funciona el anzuelo de un pato?",
    ["Simply pick up a rod and try to catch the ducks. You get goes at a time."] = "Simplemente toma una caña e intenta atrapar a los patos. Obtienes a la vez.",
    ["How are things going?"] = "¿Cómo van las cosas?",
    ["I'm having a whale of a time. You can tell a lot about a person from the types of balls they throw, and I find that very interesting."] = "Lo estoy pasando genial. Se puede saber mucho sobre una persona por los tipos de pelotas que lanza, y eso me parece muy interesante.",
    ["What do normal balls mean?"] = "¿Qué significan las bolas normales?",
    ["Ah, the choice of the balanced. For those who are happy to flow with the wind and be one with the world."] = "Ah, la elección del equilibrado. Para aquellos que están felices de fluir con el viento y ser uno con el mundo.",
    ["What do cabbages mean?"] = "¿Qué significan las coles?",
    ["Cabbages. These people are strong-willed and spontaneous, loyal to the end and always fight for what they believe in."] = "Coles. Estas personas son tenaces y espontáneas, leales hasta el final y siempre luchan por lo que creen.",
    ["What do chinchompas mean?"] = "¿Qué significan chinchompas?",
    ["Chinchompas, the choice of the creative soul, the artist. Kind souls who are often misunderstood."] = "Chinchompas, la elección del alma creativa, del artista. Almas bondadosas que a menudo son incomprendidas.",
    ["It's not an exact science though. I'm still ironing out the kinks."] = "Aunque no es una ciencia exacta. Todavía estoy solucionando los problemas.",
    ["Oo, a stranger left this for you!"] = "¡Oh, un extraño te dejó esto!",
    ["You need 1 free space in your backpack to receive your clue caskets."] = "Necesitas 1 espacio libre en tu backpack para recibir tus cofres de pistas.",
    ["[You are handed a casket!]"] = "[¡Te entregan un ataúd!]",
    ["Hello. How can I help you?"] = "Hola. ¿Le puedo ayudar en algo?",
    ["What are you selling?"] = "¿Qué estás vendiendo?",
    ["Can you give me any farming advice?"] = "¿Puedes darme algún consejo agrícola?",
    ["Yes - ask a gardener."] = "Sí, pregúntale a un jardinero.",
    ["Can you tell me how to use the loom?"] = "¿Puedes decirme cómo usar el telar?",
    ["Well, it's actually my loom but I don't mind you using it, if you like. You can use it to weave sacks and baskets in which you can put vegetables and fruit."] = "Bueno, en realidad es mi telar, pero no me importa que lo uses, si quieres. Puedes utilizarlo para tejer sacos y cestas en los que poner verduras y frutas.",
    ["What do I need to weave sacks?"] = "¿Qué necesito para tejer sacos?",
    ["Well, the best sacks are made from jute fibres. You can grow jute yourself in a hops patch. I'd say about four jute fibres should be enough to weave a sack."] = "Bueno, los mejores sacos están hechos de fibras de yute. Puedes cultivar yute tú mismo en un huerto de lúpulo. Yo diría que unas cuatro fibras de yute deberían ser suficientes para tejer un saco.",
    ["Thank you, that's very kind."] = "Gracias, es muy amable.",
    ["What do I need to weave baskets?"] = "¿Qué necesito para tejer cestas?",
    ["Well, the best baskets are made with young branches cut from a willow tree. You'll need a very young willow tree, otherwise the branches will have grown too thick to be able to weave. I suggest growing your own."] = "Bueno, las mejores cestas están hechas con ramas jóvenes cortadas de un willow tree. Necesitarás una willow tree muy joven, de lo contrario las ramas habrán crecido demasiado gruesas para poder tejer. Sugiero cultivar el tuyo propio.",
    ["You can cut the branches with a standard pair of secateurs. You will probably need about six willow branches to weave a complete basket."] = "Puedes cortar las ramas con un par de tijeras de podar estándar. Probablemente necesitarás unas seis ramas de sauce para tejer una cesta completa.",
    ["I'm okay, thank you."] = "Estoy bien, gracias.",
    ["This gnome lady appears to be singing ... to her toads."] = "Esta dama gnomo parece estar cantándoles... a sus sapos.",
    ["La la la, toadies in their holeys... Oh hello, I didn't notice you."] = "La la la, aduladores con sus agujeros... Oh, hola, no te había notado.",
    ["Hello, What do you do here?"] = "Hola, ¿Qué haces aquí?",
    ["I look after the toads and worms. They are very useful in gnome cooking, don't you know."] = "Cuido los sapos y los gusanos. Son muy útiles en la cocina de los gnomos, ¿no lo sabes?",
    ["Does singing to the toads help them grow?"] = "¿Cantarles a los sapos les ayuda a crecer?",
    ["Don't be silly, I just sing to pass the time while looking after them!"] = "¡No seas tonto, solo canto para pasar el tiempo mientras los cuido!",
    ["Of course..."] = "Por supuesto...",
    ["What a mess you've made..."] = "Qué lío has hecho...",
    ["We protect Seiryu, for the greater good."] = "Protegemos a Seiryu, por el bien común.",
    ["How dare you defile this monastery."] = "¿Cómo te atreves a profanar este monasterio?",
    ["Is it treasure that you seek?"] = "¿Es un tesoro lo que buscas?",
    ["Welcome to my store, human! Are you interested in buying anything?"] = "¡Bienvenido a mi tienda, humano! ¿Estás interesado en comprar algo?",
    ["Yes, I'm looking for some armour."] = "Sí, estoy buscando una armadura.",
    ["Say, would you be interested in doing a little task for me?"] = "Dime, ¿te interesaría hacer una pequeña tarea por mí?",
    ["What do you need me to do?"] = "¿Qué necesitas que haga?",
    ["A special client has a little request for me. I will need [item] in the next [number] minutes."] = "Un cliente especial tiene una pequeña petición para mí. Necesitaré [item] en los próximos minutos [número].",
    ["Right, I'll get you [item] in the next [number] minutes. I can do that, yes."] = "Bien, te conseguiré [item] en los próximos minutos [número]. Puedo hacer eso, sí.",
    ["I don't have time for that, no."] = "No tengo tiempo para eso, no.",
    ["That's really unfortunate, I hope I can find someone else."] = "Eso es realmente desafortunado, espero poder encontrar a alguien más.",
    ["How are you doing getting me my [item]?"] = "¿Cómo te va al conseguirme mi [item]?",
    ["I don't want to look for them anymore."] = "Ya no quiero buscarlos.",
    ["Next time, can you decide on that in advance? You've put me in a spot of trouble now. I suppose I'll find a way out though."] = "La próxima vez, ¿puedes decidirlo con antelación? Me has puesto en un problema ahora. Aunque supongo que encontraré una salida.",
    ["I'm still looking for them."] = "Todavía los estoy buscando.",
    ["Good, good. Hurry back!"] = "Bien, bien. ¡Date prisa!",
    ["I've brought you your [item]!"] = "¡Te traje tu [item]!",
    ["Excellent, much appreciated! Do you want me to pay you in gold or do you want me to show you how to fight properly in these?"] = "¡Excelente, muy apreciado! ¿Quieres que te pague en oro o quieres que te muestre cómo luchar correctamente en estos?",
    ["*One of the following dialogues plays at random*"] = "*Uno de los siguientes diálogos se reproduce al azar*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["How's the King treating you then?"] = "¿Cómo te trata el Rey entonces?",
    ["Like serfs."] = "Como siervos.",
    ["Serf?"] = "¿Siervo?",
    ["Yes, you know - peons, plebs, the downtrodden. He treats us like his own personal possessions."] = "Sí, ya sabes: peones, plebeyos, los oprimidos. Nos trata como a sus posesiones personales.",
    ["You should leave this place."] = "Deberías abandonar este lugar.",
    ["I keep trying to save up enough to leave, but the King keeps taxing us! We have no money left."] = "Sigo intentando ahorrar lo suficiente para irme, ¡pero el Rey sigue cobrando impuestos! No nos queda dinero.",
    ["Oh dear."] = "Dios mío.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["It's a bit grey round here, isn't it?"] = "Está un poco gris por aquí, ¿no?",
    ["It gets you down after a while, you know. There are 273 shades of grey, you know, and we have them all."] = "Te deprime después de un tiempo, ¿sabes? Hay 273 tonos de gris, ya sabes, y los tenemos todos.",
    ["That's grey-t."] = "Eso es gris-t.",
    ["That attempt at humour merely made me more depressed. Leave me alone."] = "Ese intento de humor simplemente me deprimió más. Déjame en paz.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["How are you today?"] = "¿Cómo estás hoy?",
    ["**sigh**"] = "**suspiro**",
    ["That good? Everyone around here seems a little depressed."] = "¿Tan bueno? Todos por aquí parecen un poco deprimidos.",
    ["And not particularly talkative."] = "Y no es particularmente hablador.",
    ["I'll leave you to your sighing. It looks like you have plenty to do."] = "Te dejo con tus suspiros. Parece que tienes mucho que hacer.",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Cheer up! It's not the end of the world."] = "¡Anímate! No es el fin del mundo.",
    ["I'd prefer that, if it meant I didn't have to talk to people as insanely happy as you."] = "Preferiría eso, si eso significara no tener que hablar con personas tan increíblemente felices como tú.",
    ["Whoa! I think you need to get out more."] = "¡Vaya! Creo que necesitas salir más.",
    ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
    ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
    ["*When speaking to Sassilik in Rellekka.*"] = "*Al hablar con Sassilik en Rellekka.*",
    ["*Sassilik may greet you with any of the following at random:*"] = "*Sassilik puede saludarte con cualquiera de los siguientes al azar:*",
    ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
    ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
    ["All is well with me also!"] = "¡Todo está bien para mí también!",
    ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
    ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
    ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["Hello to you, too!"] = "¡Hola a ti también!",
    ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
    ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
    ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
    ["*Sassilik may reply to you with any of the following at random:*"] = "*Sassilik puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
    ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
    ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
    ["*When talking to the Sawmill operator in the Ithell district in Prifddinas.*"] = "*Al hablar con Sawmill operator en el distrito de Ithell en Prifddinas.*",
    ["Hello. Do you want me to make some planks for you or would you be interested in some other housing supplies?"] = "Hola. ¿Quieres que te haga planks o te interesarían otros suministros para el hogar?",
    ["Planks, please."] = "Planks, por favor.",
    ["What kind of planks do you want?"] = "¿Qué tipo de planks quieres?",
    ["*If the player doesn't have any suitable logs:*"] = "*Si el player no tiene ningún logs adecuado:*",
    ["You are not carrying any logs to cut into planks."] = "No lleva ningún logs para cortar en planks.",
    ["What kind of planks can you make?"] = "¿Qué tipo de planks puedes hacer?",
    ["I can make planks from wood, oak, teak and mahogany. I don't make planks from other woods as they're no good for making furniture. Wood and oak are all over the place, but teak and mahogany can only be found in a few places like Karamja and Etceteria."] = "Puedo hacer planks con madera, roble, teca y caoba. No hago planks con otras maderas porque no sirven para hacer furniture. La madera y el roble están por todas partes, pero la teca y la caoba sólo se pueden encontrar en unos pocos lugares como Karamja y Etceteria.",
    ["Can I buy some housing supplies?"] = "¿Puedo comprar algunos suministros para la vivienda?",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["Well, come back when you want some. You can't get good quality planks anywhere but here!"] = "Bueno, vuelve cuando quieras. ¡No puedes conseguir planks de buena calidad en ningún otro lugar que no sea aquí!",
    ["Hello stranger. Would you like me to tan any hides for you?"] = "Hola extraño. ¿Quieres que te curta alguna piel?",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Yes please."] = "Sí, por favor.",
    ["No thanks, I'm not interested."] = "No, gracias, no me interesa.",
    ["Okay; you change your mind, you come see me. I'm your guy!"] = "Está bien; Si cambias de opinión, vienes a verme. ¡Soy tu chico!",
    ["Hello, dryfoot."] = "Hola, pie seco.",
    ["Choose..."] = "Elige...",
    ["Tool storage."] = "Almacenamiento de herramientas.",
    ["What tools can you store?"] = "¿Qué herramientas puedes almacenar?",
    ["What can you store?"] = "¿Qué puedes almacenar?",
    ["Me can store farming tools, obviously. You want to be using the store?"] = "Puedo guardar herramientas agrícolas, obviamente. ¿Quieres usar la tienda?",
    ["Yes, please."] = "Sí, por favor.",
    ["What do you do with the tools you're storing?"] = "¿Qué haces con las herramientas que estás almacenando?",
    ["What do you do with the tools you're storing? They can't possibly all fit in your pockets!"] = "¿Qué haces con las herramientas que almacenas? ¡Es imposible que todos quepan en tus bolsillos!",
    ["Silly question, obviously keep tools in bog."] = "Pregunta tonta, obviamente mantén las herramientas en el pantano.",
    ["Now, you want me to look after yours or not?"] = "Ahora, ¿quieres que cuide el tuyo o no?",
    ["No thanks, I'll keep hold of my stuff."] = "No, gracias, guardaré mis cosas.",
    ["Okay? Another time maybe."] = "¿Está bien? Quizás en otra ocasión.",
    ["Open your tool store, please."] = "Abre tu tienda de herramientas, por favor.",
    ["Actually, I'm fine."] = "En realidad, estoy bien.",
    ["Winkin's Farm."] = "La granja de Winkin.",
    ["Can you take me to Winkin's Farm?"] = "¿Puedes llevarme a Winkin's Farm?",
    ["What's a Winkin?"] = "¿Qué es un Winkin?",
    ["Oh... I guess not then."] = "Oh... Supongo que entonces no.",
    ["You an odd one dryfoot."] = "Eres un extraño con los pies secos.",
    ["Composting."] = "Compostaje.",
    ["Can you compost patches for me?"] = "¿Pueden hacerme abono con parches?",
    ["Sure, I can do it at all of your patches using the compost you give me, if you're willing to pay for the convenience."] = "Claro, puedo hacerlo en todos tus parches usando el abono que me das, si estás dispuesto a pagar por la conveniencia.",
    ["500 gold for regular compost, 1,500 gold for supercompost or 2,500 gold for ultracompost. Pay for up to 60,000 upfront, but no refunds."] = "500 de oro para abono normal, 1500 de oro para supercompost o 2500 de oro para ultracompost. Paga hasta 60.000 por adelantado, pero no hay reembolsos.",
    ["What do you want to top up?"] = "¿Qué quieres recargar?",
    ["cond=With normal composting left to buy:"] = "cond=Con compost normal queda por comprar:",
    ["**Pay [number] coins?**"] = "**¿Pagar [número] coins?**",
    ["Yes."] = "Sí.",
    ["Looks like ye can't pay up. Come back when ye can."] = "Parece que no puedes pagar. Vuelve cuando puedas.",
    ["Very well, I'll keep your patches composted. Just keep yer storage topped up!"] = "Muy bien, mantendré tus parches en abono. ¡Solo mantén tu almacenamiento lleno!",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["cond=With supercomposting left to buy:"] = "cond=Con supercompostaje queda por comprar:",
    ["cond=With ultracomposting left to buy:"] = "cond=Con ultracompostaje queda por comprar:",
    ["Looks like you can't pay up. Come back when you can."] = "Parece que no puedes pagar. Vuelve cuando puedas.",
    ["Nothing"] = "nada",
    ["Looks like yer all paid up."] = "Parece que ya pagaste todo.",
    ["Can you stop composting patches for me?"] = "¿Puedes dejar de hacer abono con parches por mí?",
    ["You hadn't paid me, so I wasn't doing it anyway."] = "No me habías pagado, así que no lo haría de todos modos.",
    ["How much have I paid for?"] = "¿Cuánto he pagado?",
    ["How much compost will you use?"] = "¿Cuánto abono usarás?",
    ["We'll use [number] regular, [number] supercompost and [number] ultracompost. Want to top up?"] = "Usaremos [número] regular, supercompost [número] y ultracompost [número]. ¿Quieres recargar?",
    ["Do you want a refund then?"] = "¿Quieres un reembolso entonces?",
    ["Looks like you're all refunded anyway! Phew..."] = "¡Parece que ya te han reembolsado todo! Uf...",
    ["**What do you want to refund?**"] = "**¿Qué quieres reembolsar?**",
    ["cond=Only with normal compost to refund:"] = "cond=Sólo con abono normal a reembolsar:",
    ["There you go!"] = "¡Ahí lo tienes!",
    ["cond=Only with supercompost to refund:"] = "cond=Solo con supercompost para reembolsar:",
    ["cond=Only with ultracompost to refund:"] = "cond=Solo con ultracompost para reembolsar:",
    ["Can I change which patches you compost?"] = "¿Puedo cambiar qué parches compostas?",
    ["We'll currently use yer compost on: Tree patches Allotment patches Hops patches Bush patches Herb patches Flower patches Special patches"] = "Actualmente usaremos su abono en: Parches de árboles Parches de huertos Parches de lúpulo Parches de arbustos Parches de hierbas Parches de flores Parches especiales",
    ["We'll not use yer compost on Tree patches Allotment patches Hops patches Bush patches Herb patches Flower patches Special patches"] = "No usaremos su abono en Parches de árboles Parches de huertos Parches de lúpulo Parches de arbustos Parches de hierbas Parches de flores Parches especiales",
    ["Toggle tree patches"] = "Alternar parches de árbol",
    ["Do you want to change some more?"] = "¿Quieres cambiar algo más?",
    ["Toggle allotment patches"] = "Alternar parches de asignación",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["Toggle hops patches"] = "Alternar parches de lúpulo",
    ["Toggle bush patches"] = "Alternar parches de arbustos",
    ["Toggle herb patches"] = "Alternar parches de hierbas",
    ["Toggle flower patches"] = "Alternar parches de flores",
    ["Toggle miscellaneous patches"] = "Alternar parches varios",
    ["Other topics."] = "Otros temas.",
    ["cond=If there are rewards to collect:"] = "cond=Si hay recompensas para recolectar:",
    ["Tell me about yourself."] = "Háblame de ti.",
    ["Do you grow anything out here?"] = "¿Cultivas algo aquí?",
    ["Tried flowers. Tried 'shrooms. Tried mud. All goes bad."] = "Probé flores. Probé 'hongos'. Probé barro. Todo va mal.",
    ["Any idea why?"] = "¿Alguna idea de por qué?",
    ["Because of those nasty totems."] = "Por esos desagradables tótems.",
    ["Keep the good bits out. Keep us in."] = "Deja fuera lo bueno. Mantennos dentro.",
    ["That doesn't seem ideal."] = "Eso no parece ideal.",
    ["It's not, seemed to work when green guy was around."] = "No lo es, parecía funcionar cuando el tipo verde estaba cerca.",
    ["Green guy?"] = "¿Chico verde?",
    ["Yeah little guy with a funny hat, used to grow lots here."] = "Sí, un pequeño con un sombrero gracioso, solía crecer mucho aquí.",
    ["That sounds like a leprechaun, what happened to him?"] = "Eso suena como un duende, ¿qué le pasó?",
    ["Fenmoor took him. Not even hat left."] = "Fenmoor se lo llevó. Ni siquiera queda el sombrero.",
    ["Mmhmm."] = "Mmmmm.",
    ["Now want me to look after anything?."] = "¿Ahora quieres que me ocupe de algo?",
    ["Oi! Not for humies! Only sanguine boggos or friendly vampyre ladies."] = "¡Oye! ¡No para humies! Sólo boggos optimistas o amigables damas vampyre.",
    ["That's oddly specific."] = "Eso es extrañamente específico.",
    ["Oh dear… oh dear…"] = "Dios mío... Dios mío...",
    ["Are you alright?"] = "¿Estás bien?",
    ["The young druidess seems intent on staring into the well and wringing her hands, and does not reply."] = "La joven druida parece decidida a mirar fijamente el pozo y retorcerse las manos, y no responde.",
    ["Uh… ok then! Have a nice day!"] = "Uh… ¡vale entonces! ¡Que tenga un lindo día!",
    ["It looks like those troll leaders have fled back to the mountain."] = "Parece que esos líderes trolls han regresado a la montaña.",
    ["So have all the trolls followed them?"] = "Entonces, ¿los han seguido todos los trolls?",
    ["No, it looks like they have been sneaking past in small groups and hiding in the well."] = "No, parece que han estado escabulléndose en pequeños grupos y escondiéndose en el pozo.",
    ["Well hopefully the numbers should be small enough for me and the other soldiers to deal with."] = "Bueno, espero que los números sean lo suficientemente pequeños para que yo y los otros soldados podamos lidiar con ellos.",
    ["Guthix protect you, take care if you do go inside."] = "Guthix te protege, ten cuidado si entras.",
    ["So, tell me about yourself."] = "Entonces, cuéntame sobre ti.",
    ["Of course! I suppose introductions were sort of lost in all the kafuffle."] = "¡Por supuesto! Supongo que las presentaciones se perdieron en todo este jaleo.",
    ["I'm Scalectrix, although that is my druid name. I was originally from Burthorpe, but came to live here when the trolls invaded."] = "Soy Scalectrix, aunque ese es mi nombre de druida. Yo era originario de Burthorpe, pero vine a vivir aquí cuando los trolls invadieron.",
    ["My home was one of the ones destroyed. The druids took me in and let me live here among them, like the other refugees."] = "Mi casa fue una de las destruidas. Los druidas me acogieron y me dejaron vivir aquí entre ellos, como los demás refugiados.",
    ["Apparently I have a talent for summoning, so I came to work with Pikkupstix while I got settled and the trolls were repelled."] = "Aparentemente tengo talento para invocar, así que vine a trabajar con Pikkupstix mientras me instalaba y los trolls eran repelidos.",
    ["One day I hope, while working for him, I will attain the level of master and wear a Summoning skillcape too!"] = "Espero que algún día, mientras trabajo para él, alcance el nivel de maestro y también use un Summoning skillcape.",
    ["What brought you to Taverley?"] = "¿Qué te trajo a Taverley?",
    ["The war, mostly. I lived in Burthorpe all my life, and then the major push from the trolls destroyed my house and displaced me down here."] = "La guerra, principalmente. Viví en Burthorpe toda mi vida, y luego el gran empujón de los trolls destruyó mi casa y me desplazó aquí abajo.",
    ["I'd always liked coming to Taverley when I had free time from my work in the games room, and I was lucky that the druids took me in."] = "Siempre me gustó venir a Taverley cuando tenía tiempo libre de mi trabajo en la sala de juegos, y tuve suerte de que los druidas me acogieran.",
    ["A lot of the refugees moved back up once the trolls were repelled."] = "Muchos de los refugiados regresaron una vez que los trolls fueron repelidos.",
    ["But I love it here! I never want to leave!"] = "¡Pero me encanta estar aquí! ¡Nunca quiero irme!",
    ["How do you think the trolls got here?"] = "¿Cómo crees que llegaron aquí los trolls?",
    ["Do you mean in general, or here in this well?"] = "¿Te refieres a en general o aquí en este pozo?",
    ["Here in this well."] = "Aquí en este pozo.",
    ["Well a mass of trolls would have been spotted by the troops, so I suppose they are scouts and stragglers."] = "Bueno, las tropas habrían detectado una masa de trolls, así que supongo que son exploradores y rezagados.",
    ["If one or two of them at a time slip past the guard through the wells and tunnels, or in the confusion of combat, then they could have found each other."] = "Si uno o dos de ellos a la vez pasan al guardia a través de los pozos y túneles, o en la confusión del combate, entonces podrían haberse encontrado.",
    ["Although I get the feeling those two leaders were scouts, who must have found this well and let the others know."] = "Aunque tengo la sensación de que esos dos líderes eran exploradores, quienes debieron haber encontrado esto bien y avisar a los demás.",
    ["That might be why there are more still sneaking in there; the leaders ran off and never told them to stop coming."] = "Quizás esa sea la razón por la que todavía hay más merodeando por ahí; Los líderes salieron corriendo y nunca les dijeron que dejaran de venir.",
    ["Still, now the guards know to look for them, there are patrols of the Imperial Guard from Burthorpe looking around to sweep up any survivors."] = "Aún así, ahora que los guardias saben que deben buscarlos, hay patrullas de la Guardia Imperial de Burthorpe mirando a su alrededor para barrer a los supervivientes.",
    ["And me, of course."] = "Y yo, por supuesto.",
    ["Of course! I'm sure you'll help keep them at bay!"] = "¡Por supuesto! ¡Estoy seguro de que ayudarás a mantenerlos a raya!",
    ["I'd best be off."] = "Será mejor que me vaya.",
    ["Be well."] = "Que estés bien.",
    ["*Scarg may say any one of the following at random:*"] = "*Scarg puede decir cualquiera de las siguientes palabras al azar:*",
    ["Me's gonna ged da pridy chompy hatsies...an looks like a good-un wiv da laydies."] = "Me voy a llevar unos sombreros orgullosos y masticadores... y parece una buena esposa con las lagas.",
    ["Da fatsy toadies geddin' all messy..."] = "Los aduladores gordos se ensucian todo...",
    ["Yous creature doesn't stick mee's chompy, else mee's squeeze creature till yous a deadun!"] = "¡Tu criatura no me pega el mordisco, de lo contrario me aprieta hasta que te quedas sin vida!",
    ["Chompy is bestest yumms..."] = "Chompy es el mejor delicioso...",
    ["Mee's scared of Jiggig and da zogries, deyz is not da right dead-uns."] = "Mee tiene miedo de Jiggig y da zogries, deyz no son los muertos correctos.",
    ["Yous creatures too weedy for da ogre stabby chucker, yous best stick wiv da cluks-cluks."] = "Ustedes, criaturas, son demasiado malas para el ogro apuñalador, será mejor que se queden con los cluks-cluks.",
    ["Mee's got no stabbers no more...gonna go home wiv no chompy..."] = "Mee ya no tiene apuñaladores... me iré a casa sin morder...",
    ["Me'se can't wait for da chompy yumms...I's dribbling all down me's for da tasty chompy."] = "No puedo esperar por los deliciosos chompys... Estoy goteando por todos lados por los sabrosos chompys.",
    ["De'se stabbers are worser dan a dead dog...."] = "Estos apuñaladores son peores que un perro muerto....",
    ["I's stickin' da chompy..."] = "Me estoy quedando con el mordisco...",
    ["Ello, matey! D'ya wanna buy some exciting new toys?"] = "¡Hola, amigo! ¿Quieres comprar algunos juguetes nuevos y emocionantes?",
    ["No - toys are for kids."] = "No, los juguetes son para niños.",
    ["Let's have a look, then."] = "Entonces echemos un vistazo.",
    ["Ooh, goody-goody - toys!"] = "¡Oh, Dios mío, juguetes!",
    ["Why do you sell most rune armour but not platebodies?"] = "¿Por qué vendes la mayoría de armaduras rúnicas pero no cuerpos de placas?",
    ["Oh, you have to complete a special quest in order to wear rune platebodies. You should talk to the guild master downstairs about that."] = "Oh, tienes que completar una misión especial para poder usar cuerpos de placas rúnicas. Deberías hablar con el maestro del gremio de abajo sobre eso.",
    ["Can you find my teacher? I need the toilet!"] = "¿Puedes encontrar a mi maestro? ¡Necesito el baño!",
    ["Yaaay! A day off school."] = "¡Sí! Un día libre de escuela.",
    ["I wonder what they're doing behind that rope."] = "Me pregunto qué estarán haciendo detrás de esa cuerda.",
    ["Teacher! Can we go to the Natural History exhibit now?"] = "¡Maestro! ¿Podemos ir ahora a la exposición de Historia Natural?",
    ["*sniff* They won't let me take an arrowhead as a souvenir."] = "*sniff* No me dejan llevarme una punta de flecha como recuerdo.",
    ["I wanna be an archaeologist when I grow up!"] = "¡Quiero ser arqueólogo cuando sea mayor!",
    ["Sada...Sram...Sa-ra-do-min is bestest!"] = "Sada...Sram...¡Sa-ra-do-min es el mejor!",
    ["*cough* It's so dusty in here."] = "*tos* Hay mucho polvo aquí.",
    ["Maz...Zar...Za-mor-ak is bestest!"] = "¡Maz...Zar...Za-mor-ak es el mejor!",
    ["The Kalphite Queen is soo scary!"] = "¡El Kalphite Queen da mucho miedo!",
    ["I want a pet sea slug for my birthday. They are so cute!"] = "Quiero una babosa marina como mascota para mi cumpleaños. ¡Son tan lindos!",
    ["The monkeys are so funny-looking!"] = "¡Los monos tienen un aspecto muy divertido!",
    ["I bet a wyvern could beat a dragon in a fight!"] = "¡Apuesto a que un wyvern podría vencer a un dragón en una pelea!",
    ["My dad says he got bitten by a giant snail once."] = "Mi papá dice que una vez lo mordió un caracol gigante.",
    ["Do you know where the moles are?"] = "¿Sabes dónde están los lunares?",
    ["We're going to see the dragons! They're my favourite!"] = "¡Vamos a ver los dragones! ¡Son mis favoritos!",
    ["Watch out for the big scary mean creatures!"] = "¡Cuidado con las grandes y aterradoras criaturas!",
    ["Hello, you look new here. Welcome to the Death Guard!"] = "Hola, pareces nuevo aquí. ¡Bienvenidos a la Guardia de la Muerte!",
    ["Death Guard? Nah, mate, I'm just a hired hand - a cleaner, ya know?"] = "¿Guardia de la Muerte? No, amigo, solo soy un empleado contratado, un limpiador, ¿sabes?",
    ["You're not...you know?"] = "No lo eres... ¿sabes?",
    ["You're not an elf under that gasmask?"] = "¿No eres un elfo bajo esa máscara de gas?",
    ["Elf? Nah, mate: human. You're talking like there's some sort of mass conspiracy going on."] = "¿Elfo? No, amigo: humano. Estás hablando como si hubiera algún tipo de conspiración masiva.",
    ["Would you believe me if I said there was? What if you could take that gasmask off and be completely safe?"] = "¿Me creerías si te dijera que sí? ¿Qué pasaría si pudieras quitarte esa máscara de gas y estar completamente a salvo?",
    ["Nice try! 'Hello, you look new here' - that ol' routine, eh? 'Take yer mask off,' you say. 'It's perfectly safe,' you say. Then, 'BOOM', Scotty gets the plague...and you'll steal my business!"] = "¡Buen intento! \"Hola, pareces nuevo aquí\", esa vieja rutina, ¿eh? \"Quítate la máscara\", dices. \"Es perfectamente seguro\", dices. Entonces, 'BOOM', Scotty contrae la plaga... ¡y me robarás el negocio!",
    ["You think I'd try to kill you just to become the new janitor?"] = "¿Crees que intentaría matarte sólo para convertirme en el nuevo conserje?",
    ["Of course! Everyone's trying to move in on us! You shoulda seen the fiasco when we were working some waiting rooms for a guy called Mandrith. Every other guy was coming at us with a dragon dagger!"] = "¡Por supuesto! ¡Todos están intentando acercarse a nosotros! Deberías haber visto el fiasco cuando estábamos trabajando en algunas salas de espera para un tipo llamado Mandrith. ¡Todos los demás tipos venían hacia nosotros con un dragon dagger!",
    ["Yet you live to tell the tale?"] = "¿Aun así vives para contarlo?",
    ["What can I say? This old broom's as lethal on people as it is on trash."] = "¿Qué puedo decir? Esta vieja escoba es tan letal para las personas como para la basura.",
    ["Spy! I shall kill you!"] = "¡Espía! ¡Te mataré!",
    ["Eek!"] = "¡Eek!",
    ["You can see into the Shadow Realm, but you are not of it. I cannot trust you."] = "Puedes ver el Reino de las Sombras, pero no perteneces a él. No puedo confiar en ti.",
    ["I am not of it? What Shadow Realm? Hello? He's not listening."] = "¿No soy de eso? ¿Qué reino de las sombras? ¿Hola? Él no está escuchando.",
    ["I am on a mission. I cannot spare time to speak to you."] = "Estoy en una misión. No puedo perder tiempo para hablar contigo.",
    ["Okay."] = "Está bien.",
    ["A mere mortal can see into the Shadow Realm? The General will want to know this."] = "¿Un simple mortal puede ver el Reino de las Sombras? El General querrá saber esto.",
    ["General who? Hello? How rude, he's not listening."] = "¿General quién? ¿Hola? Qué grosero, no me escucha.",
    ["Begone, you filthy human. I spare no words for you."] = "Vete, asqueroso humano. No escatimo palabras para ti.",
    ["All you had to say was: 'Please, come back some other time."] = "Todo lo que tenías que decir era: \"Por favor, vuelve en otro momento\".",
    ["Hello again."] = "Hola de nuevo.",
    ["I can't speak to you; I must continue on my mission."] = "No puedo hablar contigo; Debo continuar con mi misión.",
    ["*Scout may randomly say any of the following:*"] = "*El explorador puede decir al azar cualquiera de los siguientes:*",
    ["A mere mortal can see into the Shadow Realm? The General will want to know of this."] = "¿Un simple mortal puede ver el Reino de las Sombras? El General querrá saber esto.",
    ["*(wearing full ghostly set)*"] = "*(vistiendo un conjunto fantasmal completo)*",
    ["[Scratchy glares at you in a threatening manner.]"] = "[Scratchy te mira de manera amenazadora.]",
    ["Scratchy... Best rat..."] = "Scratchy... Mejor rata...",
    ["Scratchy... Best rat... Last human... that shooed... Scratchy..."] = "Scratchy... Mejor rata... Último humano... que ahuyentó... Scratchy...",
    ["Scratchy... Best rat... Last human... that shooed... Scratchy... Not live... To tell tale."] = "Scratchy... Mejor rata... Último humano... que ahuyentó... Scratchy... No vivo... Para contarlo.",
    ["[number]/14 owls tracked"] = "[número]/14 búhos rastreados",
    ["Congratulations! You have completed: 'Birds of Prey' - Track all of the owls for Deryn."] = "¡Felicitaciones! Has completado: 'Aves de presa': rastrea todos los búhos para Deryn.",
    ["You have unlocked the title: 'Player,"] = "Has desbloqueado el título: 'Player,",
    ["You can activate this via the 'Titles' tab in the Customisations interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz de Personalizaciones.",
    ["I like to hang out here so the heat from the blacksmith's can warm me up."] = "Me gusta pasar el rato aquí para que el calor de la herrería pueda calentarme.",
    ["Good day, sir. How may I be of assistance?"] = "Buenos días, señor. ¿Cómo puedo ser de ayuda?",
    ["I'd like more information about clans."] = "Me gustaría tener más información sobre clanes.",
    ["What are the benefits of being in a clan?"] = "¿Cuáles son los beneficios de estar en un clan?",
    ["I'm so glad you asked me that, [ma'am/sir]. Allow me to explain."] = "Me alegra mucho que me hayas preguntado eso, [ma'am/sir]. Permítame explicarle.",
    ["A clan is a group of players who have banded together for mutual benefit."] = "Un clan es un grupo de jugadores que se han unido para beneficio mutuo.",
    ["As a member of a clan, you can do things you couldn't do on your own."] = "Como miembro de un clan, puedes hacer cosas que no podrías hacer por tu cuenta.",
    ["You can create your very own clan citadel, and decorate it with your clan motif."] = "Puedes crear tu propia ciudadela de clan y decorarla con el motivo de tu clan.",
    ["You can take part in social events, including meetings and parties."] = "Puedes participar en eventos sociales, incluidas reuniones y fiestas.",
    ["You can create a clan avatar, a customisable companion who can give you an experience boost."] = "Puedes crear un avatar de clan, un compañero personalizable que puede darte un impulso de experiencia.",
    ["You can work with your clanmates to increase your skills."] = "Puedes trabajar con tus compañeros de clan para aumentar tus habilidades.",
    ["You can battle other players' clans in the Wilderness and the Clan Wars Arena."] = "Puedes luchar contra clanes de otros jugadores en Wilderness y Clan Wars Arena.",
    ["And you can fight powerful enemies, such as the King Black Dragon and Kalphite Queen, and earn valuable rewards."] = "Y puedes luchar contra enemigos poderosos, como el Rey Dragón Negro y Kalphite Queen, y ganar valiosas recompensas.",
    ["How do I recruit more clanmates?"] = "¿Cómo recluto más compañeros de clan?",
    ["If you are the founder of your clan or a recruiter, you can invite others to join by using your vexillum on them. But remember that if a player has already joined a clan, they will not receive your invitation."] = "Si eres el fundador de tu clan o un reclutador, puedes invitar a otros a unirse usando tu vexillum en ellos. Pero recuerda que si un jugador ya se ha unido a un clan, no recibirá tu invitación.",
    ["How do I leave a clan?"] = "¿Cómo salgo de un clan?",
    ["I can help you leave your clan right now if you wish. Remember, however, that if you are the last remaining member of the clan, leaving will permanently dissolve the clan."] = "Puedo ayudarte a dejar tu clan ahora mismo si lo deseas. Recuerda, sin embargo, que si eres el último miembro restante del clan, dejarlo disolverá permanentemente el clan.",
    ["Do you want to leave your clan?"] = "¿Quieres dejar tu clan?",
    ["More..."] = "Más...",
    ["What is a clan cloak?"] = "¿Qué es una capa de clan?",
    ["A clan cloak identifies you as a member of a clan, and displays your clan's motif. The Captain of the Guard can provide you with one, if you wish."] = "Una capa de clan te identifica como miembro de un clan y muestra el motivo de tu clan. El Captain of the Guard puede proporcionarle uno, si lo desea.",
    ["What is a vexillum?"] = "¿Qué es un vexillum?",
    ["A vexillum is a banner that displays your clan's colours and emblem. It can be carried, displayed, or used to recruit new clanmates. If you place the vexillum in the ground, others can use it to find out more about your clan, and contact you if they are interested in joining. You can also use the vexillum directly on other players to invite them to join your clan. Finally, you can use the vexillum to teleport directly here."] = "Un vexillum es un estandarte que muestra los colores y el emblema de tu clan. Se puede llevar, exhibir o utilizar para reclutar nuevos compañeros de clan. Si colocas el vexillum en el suelo, otros pueden usarlo para saber más sobre tu clan y contactarte si están interesados ​​en unirse. También puedes usar el vexillum directamente con otros jugadores para invitarlos a unirse a tu clan. Finalmente, puedes usar el vexillum para teletransportarte directamente aquí.",
    ["Can I have a vexillum?"] = "¿Puedo tener un vexillum?",
    ["It would be my pleasure, [ma'am/sir]."] = "Sería un placer, [ma'am/sir].",
    ["The scribe gives you a vexillum."] = "El escriba te da un vexillum.",
    ["*(If the player is the owner of the clan:)*"] = "*(Si el player es el dueño del clan:)*",
    ["Can I rename my clan?"] = "¿Puedo cambiar el nombre de mi clan?",
    ["Certainly. Just let me check my records and then you can choose your new clan name."] = "Por supuesto. Sólo déjame revisar mis registros y luego podrás elegir el nombre de tu nuevo clan.",
    ["*(The text is red)* Warning: You can only change your clan name once every 28 days."] = "*(El texto es rojo)* Advertencia: Solo puedes cambiar el nombre de tu clan una vez cada 28 días.",
    ["*(A text entry box appears labeled* \"Enter your new clan name.\"*)* *(*\"0/20\"*)* [Text is entered here] *(The text below says:* \"Clan names may only contain A-Z, a-z, 0-9 and space. No special characters e.g. å, ä\"*)*"] = "*(Aparece un cuadro de entrada de texto con la etiqueta* \"Ingresa el nombre de tu nuevo clan.\"*)* *(*\"0/20\"*)* [Text is entered here] *(El texto a continuación dice:* \"Los nombres de los clanes solo pueden contener A-Z, a-z, 0-9 y espacios. No se permiten caracteres especiales, por ejemplo, å, ä\"*)*",
    ["*(After typing in a name:)*"] = "*(Después de escribir un nombre:)*",
    ["[New clan name]"] = "[Nuevo nombre del clan]",
    ["One moment, please."] = "Un momento, por favor.",
    ["*(If the name is already taken:)*"] = "*(Si el nombre ya está en uso:)*",
    ["I'm afraid that name is taken."] = "Me temo que ese nombre está en uso.",
    ["*(If the name is available:)*"] = "*(Si el nombre está disponible:)*",
    ["[New clan name] is available, rename?"] = "[New clan name] está disponible, ¿cambiar el nombre?",
    ["Not yet."] = "Todavía no.",
    ["Chose a different name."] = "Elija un nombre diferente.",
    ["*(Returns to the clan name entry box.)*"] = "*(Regresa al cuadro de entrada del nombre del clan.)*",
    ["Back..."] = "Atrás...",
    ["Clan scribe Amos Twinly at your service, sir. I keep a record of all clans, and distribute clan charters to those who wish to start a clan. If you are a member of a clan, I can also provide you with a vexillum - a banner displaying your clan's motif."] = "El escriba del clan Amos Twinly a su servicio, señor. Mantengo un registro de todos los clanes y distribuyo estatutos de clan a aquellos que desean iniciar un clan. Si eres miembro de un clan, también puedo proporcionarte un vexillum, un estandarte que muestra el motivo de tu clan.",
    ["Goodbye, [ma'am/sir]."] = "Adiós, [ma'am/sir].",
    ["Hello there! Do you wish to participate in a special Clan Cup for your clan?"] = "¡Hola! ¿Quieres participar en una Copa de Clan especial para tu clan?",
    ["What's this about?"] = "¿De qué se trata esto?",
    ["This is a special competition where I'll track all Clans who wish to dedicate time to this competition!"] = "¡Esta es una competencia especial en la que realizaré un seguimiento de todos los clanes que deseen dedicar tiempo a esta competencia!",
    ["For this particular Clan Cup you'll be required to skin as many dinosaurs in Anachronia as possible!"] = "¡Para esta Copa de Clan en particular, deberás despellejar tantos dinosaurios en Anacronia como sea posible!",
    ["How do I take part?"] = "¿Cómo participo?",
    ["*(If the player doesn't have a clan vexillum:)*"] = "*(Si el player no tiene un clan vexillum:)*",
    ["Easy enough! You need to acquire a Clan Vexillum from myself, would you like me to give you one?"] = "¡Bastante fácil! Necesitas adquirir un Clan Vexillum de mi parte, ¿te gustaría que te diera uno?",
    ["Will you take a clan vexillum from the scribe?"] = "¿Aceptarás un vexillum del clan del escriba?",
    ["It would be my pleasure, sir."] = "Sería un placer, señor.",
    ["No problem, should you want a Clan Vexillum in the future you can acquire one from myself or a fellow clan member."] = "No hay problema, si quieres un Clan Vexillum en el futuro, puedes adquirir uno mío o de un miembro del clan.",
    ["*(If the player has a clan vexillum:)*"] = "*(Si el player tiene un clan vexillum:)*",
    ["Easy enough! If you interact with the Clan Vexillum you've got there you'll get an option to start a session."] = "¡Bastante fácil! Si interactúas con el Clan Vexillum que tienes allí, tendrás la opción de iniciar una sesión.",
    ["If you wish to take part without a Vexillum, feel free to select the 'Clan Cup Functions' option on the trophy in Clan Chat!"] = "Si deseas participar sin un Vexillum, ¡no dudes en seleccionar la opción 'Funciones de la Copa del Clan' en el trofeo en el chat del clan!",
    ["Now on to the competition..."] = "Ahora vamos a la competencia...",
    ["You'll have 1 hour to set the highest score you can, the top ten members for your clan will constribute to a clan total which will be compared against the other clans!"] = "Tendrás 1 hora para establecer la puntuación más alta que puedas, ¡los diez mejores miembros de tu clan contribuirán al total del clan que se comparará con los otros clanes!",
    ["What can we win?"] = "¿Qué podemos ganar?",
    ["If your clan finishes in the top ten for the entire competition, expect some goodies including a boost to that avatar of yours and more!"] = "Si tu clan termina entre los diez primeros en toda la competencia, ¡espera algunos beneficios, incluido un impulso para ese avatar tuyo y más!",
    ["My fellow scribes will be in touch to arrange prizes, should you finish in the top 10!"] = "¡Mis compañeros escribas se pondrán en contacto para concertar premios en caso de que termines entre los 10 primeros!",
    ["You should speak to Ben before you start this activity."] = "Debes hablar con Ben antes de comenzar esta actividad.",
    ["You need a space in your backpack to collect the cuttings."] = "Necesitas un espacio en tu backpack para recoger los esquejes.",
    ["You alternate between whittling and warming the zygomite's cuticles, gathering fungal shafts from each action."] = "Alternas entre tallar y calentar las cutículas del zigomita, recolectando ejes de hongos de cada acción.",
    ["You carefully whittle the zygomite's cuticles with your fletching knife, peeling off several fungal shafts."] = "Con cuidado, tallas las cutículas del cigomita con tu cuchillo para emplumar, quitando varios ejes de hongos.",
    ["You gently warm the zygomite's cuticles with soothing fire, peeling off several fungal shafts."] = "Calientas suavemente las cutículas del cigomita con un fuego relajante, despegando varios tallos de hongos.",
    ["You inexplicably adopt a zygomite sporeling!"] = "¡Inexplicablemente adoptas una espora de cigomita!",
    ["Crystal fletching: you cut double arrow shafts, so carefully the knife doesn't degrade."] = "Flecha de cristal: se cortan flechas dobles, con mucho cuidado para que el cuchillo no se degrade.",
    ["Cut and Dry (Fletching and Firemaking XP)"] = "Cortar y secar (Fletching y Firemaking XP)",
    ["Cut (Fletching XP)"] = "Cortar (Fletching XP)",
    ["Dry (Firemaking XP)"] = "Seco (Firemaking XP)",
    ["You ready to take on the Maize Maze, then?"] = "¿Estás listo para enfrentarte al Maize Maze, entonces?",
    ["What's the Maize Maze?"] = "¿Qué es el Laberinto de Maíz?",
    ["It's a little something War cooked up. You could call it a proving ground for new clan members, to check if they're up to snuff."] = "Es algo que War preparó. Podríamos llamarlo un campo de pruebas para los nuevos miembros del clan, para comprobar si están a la altura.",
    ["We also use it to heighten our reflexes and steel our hearts against all fear."] = "También lo usamos para aumentar nuestros reflejos y fortalecer nuestro corazón contra todo miedo.",
    ["It's not actually made of maize by the way. Some crop blight wiped out most of it, so we had to rebuild the maze with hedges and brick walls."] = "Por cierto, en realidad no está hecho de maíz. Una plaga de cultivos acabó con la mayor parte, por lo que tuvimos que reconstruir el laberinto con setos y paredes de ladrillo.",
    ["Name was too good to change, though."] = "Sin embargo, Name era demasiado bueno para cambiarlo.",
    ["How does it work?"] = "¿Cómo funciona?",
    ["When you go through this gate, we'll assign you a starting location."] = "Cuando cruces esta puerta, te asignaremos una ubicación de inicio.",
    ["From there, all you have to do is make it to the centre and overcome the terrifying illusion that dwells there."] = "A partir de ahí, todo lo que tienes que hacer es llegar al centro y superar la aterradora ilusión que habita allí.",
    ["Once you've done that, we'll pull you back out, job done. Easy."] = "Una vez que hayas hecho eso, te sacaremos de nuevo y trabajo hecho. Fácil.",
    ["What will I find in there?"] = "¿Qué encontraré allí?",
    ["Well, first there's the roaming enemies that will spook you if they spot you."] = "Bueno, primero están los enemigos errantes que te asustarán si te ven.",
    ["You can deal with them by spooking them back with the help of the local impling population."] = "Puedes lidiar con ellos asustándolos con la ayuda de la población implícita local.",
    ["You can hunt zombie implings to get tools for spooking enemies up close."] = "Puedes cazar implicaciones de zombis para conseguir herramientas que te permitan asustar a los enemigos de cerca.",
    ["Ghost implings will give you materials that can upgrade your melee tools into ranged ones."] = "Los impulsos fantasma te darán materiales que pueden mejorar tus herramientas cuerpo a cuerpo y convertirlas en herramientas a distancia.",
    ["Ghost implings will give you a spooking tool you can use at range."] = "Los implicaciones fantasma te darán una herramienta aterradora que puedes usar a distancia.",
    ["Then there's the walls. Sometimes, they will open up shortcuts that can get you to the centre more quickly if you use them right."] = "Luego están las paredes. A veces, abrirán atajos que pueden llevarlo al centro más rápidamente si los usa correctamente.",
    ["And last but not least, there's the magical illusion at the maze's centre. It can take the shape of various different horrifying creatures."] = "Y por último, pero no menos importante, está la ilusión mágica en el centro del laberinto. Puede tomar la forma de varias criaturas horribles diferentes.",
    ["The statue over there always shows its current form, but it can change form even while you're fighting it!"] = "La estatua de allí siempre muestra su forma actual, ¡pero puede cambiar de forma incluso mientras luchas contra ella!",
    ["Either way, you'll get real spooked by its attacks, but with enough spooking of your own, you'll be able to defeat it no problem."] = "De cualquier manera, tus ataques te asustarán mucho, pero si te asustas lo suficiente, podrás derrotarlo sin problemas.",
    ["What's in it for me?"] = "¿Qué gano yo con esto?",
    ["If you manage to defeat the illusion at the centre of the maze, I'll give you some spooky tokens."] = "Si logras derrotar la ilusión en el centro del laberinto, te daré algunas fichas espeluznantes.",
    ["You'll also get a themed bag of spoils. The stuff inside depends on the form the illusion took when you defeated it."] = "También recibirás una bolsa temática de botín. Lo que hay dentro depende de la forma que tomó la ilusión cuando la derrotaste.",
    ["If you join the clan, you can also get another team's uniform from those."] = "Si te unes al clan, también puedes obtener el uniforme de otro equipo.",
    ["[Complete the 'Field of Screams' quest to unlock the ability to receive 'The Horsemen's Uniform token' from spoils.]"] = "[Completa la misión \"Campo de los gritos\" para desbloquear la posibilidad de recibir la \"ficha del uniforme de los jinetes\" del botín.]",
    ["I'll give you three of those bags for your first successful run every day, two of 'em for your second and third runs, and one for every run after that. I'm nice like that."] = "Te daré tres de esas bolsas por tu primera carrera exitosa cada día, dos por tu segunda y tercera carrera, y una por cada carrera posterior. Soy agradable así.",
    ["Of course, you'll also learn on the job from jumping over obstacles, hunting implings and fletching ranged spooking tools."] = "Por supuesto, también aprenderás en el trabajo saltando obstáculos, cazando implings y emplumando herramientas aterradoras a distancia.",
    ["I'll give you three of those bags for your first successful run every day, and two of 'em for your second and third runs. You'll also find triple and double loot entry tokens while skilling around Harvest Hollow."] = "Te daré tres de esas bolsas por tu primera carrera exitosa todos los días, y dos por tu segunda y tercera carrera. También encontrarás fichas de entrada de botín triple y doble mientras practicas en Harvest Hollow.",
    ["Of course, you'll also learn on the job from jumping over obstacles and hunting implings."] = "Por supuesto, también aprenderás en el trabajo saltando obstáculos y cazando implings.",
    ["Do I need to bring anything?"] = "¿Necesito traer algo?",
    ["Nope, you'll find everything you need in the maze."] = "No, encontrarás todo lo que necesitas en el laberinto.",
    ["Just grab some implings on your way to the centre to gather the spooking tools that you'll need to overcome the illusion."] = "Simplemente toma algunos implings en tu camino hacia el centro para reunir las espeluznantes herramientas que necesitarás para superar la ilusión.",
    ["I'm good for now."] = "Estoy bien por ahora.",
    ["I'm good for now, thanks."] = "Estoy bien por ahora, gracias.",
    ["I'll get you to go in there eventually!"] = "¡Eventualmente haré que entres allí!",
    ["Show me the available rewards."] = "Muéstrame las recompensas disponibles.",
    ["Maybe later."] = "Quizás más tarde.",
    ["That's what they all say!"] = "¡Eso es lo que todos dicen!",
    ["Open the spoils for loot, and for a chance at special, boss-specific prizes! Rewards shown are for the currently active boss."] = "¡Abre el botín para obtener botín y tener la oportunidad de ganar premios especiales específicos para jefes! Las recompensas que se muestran son para el jefe actualmente activo.",
    ["File:Basic Phosphosseous spoils.png Basic Phosphosseous spoils"] = "Archivo:Botín básico de Phosphosseous spoils.png básico Phosphosseous",
    ["INFO"] = "INFORMACIÓN",
    ["Contains that can be obtained. only at the Spooky token soft cap.|colour=#E3D7CF|bg=#322E28}}"] = "Contiene que se puede obtener. solo en el límite flexible del token Spooky.|color=#E3D7CF|bg=#322E28}}",
    ["BACK"] = "VOLVER",
    ["File:Impressive Phosphosseous spoils.png Impressive Phosphosseous spoils"] = "Archivo:Impresionante Phosphosseous spoils.png Impresionante botín de Phosphosseous",
    ["File:Prestigious Phosphosseous spoils.png Prestigious Phosphosseous spoils"] = "Archivo:Prestigioso Phosphosseous spoils.png Prestigioso Phosphosseous botín",
    ["Contains"] = "Contiene",
    ["File:Basic Skaraxxi spoils.png Basic Skaraxxi spoils"] = "Archivo:Botín básico de Skaraxxi spoils.png básico Skaraxxi",
    ["File:Impressive Skaraxxi spoils.png Impressive Skaraxxi spoils"] = "Archivo:Impresionante Skaraxxi spoils.png Impresionante botín de Skaraxxi",
    ["File:Prestigious Skaraxxi spoils.png Prestigious Skaraxxi spoils"] = "Archivo:Prestigioso Skaraxxi spoils.png Prestigioso Skaraxxi botín",
    ["File:Basic Solak-o'-lantern spoils.png Basic Solak-o'-lantern spoils"] = "Archivo:Botín básico de Solak-o'-lantern spoils.png básico Solak-o'-lantern",
    ["File:Impressive Solak-o'-lantern spoils.png Impressive Solak-o'-lantern spoils"] = "Archivo:Impresionante Solak-o'-lantern spoils.png Impresionante botín de Solak-o'-lantern",
    ["File:Prestigious Solak-o'-lantern spoils.png Prestigious Solak-o'-lantern spoils"] = "Archivo:Prestigioso Solak-o'-lantern spoils.png Prestigioso Solak-o'-lantern botín",
    ["The woman's gaze is fixed on the distant ocean. She is singing a beautiful yet haunting melody. It almost resembles whale song."] = "La mirada de la mujer está fija en el océano lejano. Ella está cantando una melodía hermosa pero inquietante. Casi se parece al canto de las ballenas.",
    ["The sea witch ignores you, and does not miss a beat in her song."] = "La bruja del mar te ignora y no pierde el ritmo de su canción.",
    ["Can you hear me?"] = "¿Puedes oírme?",
    ["*(After Head of the Family)* Sing again of the moai that travelled on water."] = "*(Después de Jefe de Familia)* Cantar nuevamente del moai que viajaba sobre el agua.",
    ["The sea witch pauses, and for a moment turns her terrible gaze toward you. Her eyes glow with mad intensity."] = "La bruja del mar hace una pausa y por un momento vuelve su terrible mirada hacia ti. Sus ojos brillan con loca intensidad.",
    ["Fixing her gaze once more upon the horizon, the sea witch parts her lips, and begins to sing. The lyrics are ancient and cannot be replicated in the common tongue, but their meaning echoes in your head."] = "Fijando su mirada una vez más en el horizonte, la bruja del mar abre los labios y comienza a cantar. La letra es antigua y no se puede reproducir en la lengua común, pero su significado resuena en tu cabeza.",
    ["There once was a curious moai who longed to see the ocean."] = "Había una vez un moai curioso que anhelaba ver el océano.",
    ["Like all moai, his gaze was turned inward, to keep his focus on his island, and the happiness of its inhabitants."] = "Como todos los moai, su mirada se volvió hacia adentro, para concentrarse en su isla y la felicidad de sus habitantes.",
    ["This moai was curious and inquisitive. He heard the ocean waves lapping behind him. The crash of surf against sand."] = "Este moai era curioso e inquisitivo. Escuchó las olas del océano batiendo detrás de él. El choque de las olas contra la arena.",
    ["He heard the sounds of whale song, and the bellow of mighty sea creatures. The chittering of tiny shoals of invisible salmon."] = "Escuchó los sonidos del canto de las ballenas y el bramido de poderosas criaturas marinas. El chirrido de diminutos bancos de salmones invisibles.",
    ["He pestered his fellow moai with questions of their islands. What did they see? What did they hear?"] = "Molestaba a sus compañeros moai con preguntas sobre sus islas. ¿Qué vieron? ¿Qué oyeron?",
    ["His family patiently answered his questions, but the curious moai could not be satisfied with words."] = "Su familia respondió pacientemente a sus preguntas, pero el curioso moai no pudo contentarse con las palabras.",
    ["He was ravenous for knowledge. He wanted to see the world beyond his island with his own eyes."] = "Estaba hambriento de conocimiento. Quería ver el mundo más allá de su isla con sus propios ojos.",
    ["The curious moai called the island elders to him. He begged them, the bugs that lived on his back, for aid."] = "El curioso moai llamó a los ancianos de la isla. Les suplicó ayuda a los insectos que vivían en su espalda.",
    ["He asked to be moved to the shore of his island, so he could see the ocean."] = "Pidió que lo trasladaran a la orilla de su isla para poder ver el océano.",
    ["The elders agreed. They wove a bowl of the finest bamboo, and filled it with the island's soil."] = "Los ancianos estuvieron de acuerdo. Tejieron un cuenco del bambú más fino y lo llenaron con tierra de la isla.",
    ["The tribe's strongest men lifted the curious moai into the bowl, and they dragged the bowl toward the shore."] = "Los hombres más fuertes de la tribu levantaron el curioso moai dentro del cuenco y lo arrastraron hacia la orilla.",
    ["The curious moai was delighted! Finally, he could see the lapping waves. He could watch the sun rise across the water."] = "¡El curioso moai estaba encantado! Finalmente, pudo ver las olas rompiendo. Podía ver salir el sol sobre el agua.",
    ["He could even see great water beasts on the far horizon! He asked the elders to pull him closer to the shore."] = "¡Incluso podía ver grandes bestias acuáticas en el horizonte lejano! Pidió a los ancianos que lo acercaran a la orilla.",
    ["The other moai cautioned him to not get too close to the water. They feared he would drown."] = "El otro moai le advirtió que no se acercara demasiado al agua. Temían que se ahogara.",
    ["The curious moai insisted. Just a little closer, he begged. He could almost see the great whales..."] = "Insistió el curioso moai. Un poco más cerca, suplicó. Casi podía ver las grandes ballenas...",
    ["The islanders dragged the bowl closer to the shoreline. They pushed and strained and pulled the great weight of the moai down the beach."] = "Los isleños arrastraron el cuenco más cerca de la costa. Empujaron, tiraron y arrastraron el gran peso del moai playa abajo.",
    ["The moai, now settled on the golden sand, peered out across the water, and he revelled in the view of the ocean."] = "El moai, ahora asentado sobre la arena dorada, miró hacia el agua y se deleitó con la vista del océano.",
    ["Life teemed in the depths. He could see the fish swimming in shoals, and the great birds flying overhead."] = "La vida bullía en las profundidades. Podía ver los peces nadando en cardúmenes y los grandes pájaros volando sobre sus cabezas.",
    ["The curious moai looked around him in wonder, and was finally content. He was happy. Then the moai noticed that the shoreline was getting closer. The tide was coming in."] = "El curioso moai miró a su alrededor con asombro y finalmente quedó satisfecho. Estaba feliz. Entonces los moai notaron que la costa se acercaba. La marea estaba subiendo.",
    ["The moai's family wailed and sobbed. 'Too close, they cried. You are too close to the water's edge. Turn back!"] = "La familia del moai gimió y sollozó. \"Demasiado cerca\", gritaron. Estás demasiado cerca de la orilla del agua. ¡Hacer retroceder!",
    ["The curious moai called out to the islanders. He begged them to push him back onto dry land."] = "El curioso moai llamó a los isleños. Les rogó que lo empujaran de regreso a tierra firme.",
    ["The islanders tried, but the moai was too heavy. The water lapped at the moai's bowl, stealing away the soil that sustained him."] = "Los isleños lo intentaron, pero el moai era demasiado pesado. El agua lamió el cuenco del moai, robándole la tierra que lo sustentaba.",
    ["Waves cascaded over the frightened moai, filling his mouth and nose with salt water."] = "Las olas cayeron en cascada sobre el asustado moai, llenándole la boca y la nariz con agua salada.",
    ["The moai's soil dissolved in the ocean spray, and he turned deathly pale. The ocean poured into his mouth. He could not breathe."] = "La tierra del moai se disolvió en la espuma del océano y se puso pálido. El océano se vertió en su boca. No podía respirar.",
    ["The curious moai gurgled and moaned, his screams echoing in the ears of his helpless family."] = "El curioso moai gorgoteó y gimió, y sus gritos resonaron en los oídos de su indefensa familia.",
    ["After a final harrowing death rattle, the curious moai was silent."] = "Después de un último y desgarrador estertor, el curioso moai guardó silencio.",
    ["The moai's family mourned him, and chastised his foolishness."] = "La familia del moai lo lloró y reprendió su necedad.",
    ["The other moai promised to learn from the dead moai's terrible fate. They will never again face the ocean."] = "Los otros moai prometieron aprender del terrible destino del moai muerto. Nunca más volverán a mirar al océano.",
    ["The sea witch ends her tale. Your head pounds from the assault of the words in your head. Without a word, she slides back into incomprehensibly beautiful whale song."] = "La bruja del mar pone fin a su relato. Tu cabeza late con fuerza por el asalto de las palabras en tu cabeza. Sin decir una palabra, vuelve a cantar un canto de ballena incomprensiblemente hermoso.",
    ["A sea monster has appeared!"] = "¡Ha aparecido un sea monster!",
    ["The sea monster is only interested in crates of rotten fish."] = "Al sea monster sólo le interesan las cajas de pescado podrido.",
    ["You have no raw fish that the sea monster is interested in."] = "No tienes pescado crudo que le interese al sea monster.",
    ["The sea monster is no longer hungry."] = "El sea monster ya no tiene hambre.",
    ["You take [number] crates of rotten fish."] = "Tomas [número] cajas de pescado podrido.",
    ["The sea monster departs feeling unsatisfied."] = "El sea monster se marcha sintiéndose insatisfecho.",
    ["Unfortunately the encounter was not completed in time. Completing encounters successfully rewards deep sea fishing buffs."] = "Lamentablemente el encuentro no se completó a tiempo. Completar encuentros con éxito recompensa a los aficionados a la pesca en alta mar.",
    ["The sea monster has departed..."] = "El sea monster ha partido...",
    ["As the sea monster departs, water splashes the area."] = "Cuando el sea monster sale, el agua salpica el área.",
    ["Boost active: A 10% chance to gain an additional catch (10 minutes)"] = "Impulso activo: 10 % de probabilidad de obtener una captura adicional (10 minutos)",
    ["You try to scare off the seagull."] = "Intentas ahuyentar a la gaviota.",
    ["You've already tried to scare off the seagull."] = "Ya has intentado ahuyentar a la gaviota.",
    ["You are rewarded for shooing away the seagull - You receive 1,940 Fishing XP."] = "Serás recompensado por ahuyentar a la gaviota: recibirás 1940 Fishing XP.",
    ["Do you want to go on a trip to Karamja?"] = "¿Quieres ir de viaje a Karamja?",
    ["The trip will cost you 30 coins."] = "El viaje te costará 30 coins.",
    ["Oh dear, I don't seem to have enough money."] = "Dios mío, parece que no tengo suficiente dinero.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["Wait a minute, didn't you earn Karamja gloves? Thought I'd seen you helping around the island. You can go on half price - 15 coins."] = "Espera un momento, ¿no te ganaste los guantes Karamja? Pensé que te había visto ayudando en la isla. Puedes comprar a mitad de precio: 15 coins.",
    ["You pay 15 coins and board the ship."] = "Pagas 15 coins y abordas el barco.",
    ["The ship arrives at Karamja."] = "El barco llega a Karamja.",
    ["You pay 30 coins and board the ship."] = "Pagas 30 coins y abordas el barco.",
    ["*(With a ring of charos (a) equipped:)* Or I could pay you nothing at all..."] = "*(Con un ring of charos (a) equipado :)* O podría no pagarte nada en absoluto...",
    ["Or I could pay you nothing at all..."] = "O no podría pagarte nada en absoluto...",
    ["Mmmm, nothing at all, you say..."] = "Mmmm, nada de nada, dices...",
    ["Yes, why not - jump aboard then."] = "Sí, ¿por qué no? Entonces, súbete a bordo.",
    ["You board the ship."] = "Subes al barco.",
    ["*(If you have completed the Karamja easy tasks but do not have 15 coins:)*"] = "*(Si has completado las tareas fáciles de Karamja pero no tienes 15 coins :)*",
    ["You do not have enough coins to pay passage. You need 15 coins having earned the Karamja gloves."] = "No tienes suficiente coins para pagar el pasaje. Necesitas 15 coins habiendo ganado los guantes Karamja.",
    ["You do not have enough money for that."] = "No tienes suficiente dinero para eso.",
    ["*(If you have completed the Karamja easy tasks:)*"] = "*(Si has completado las tareas fáciles de Karamja:)*",
    ["The Seaman smiles as he recognises you as having earned Karamja gloves and lets you pass for half price - 15 coins."] = "El marinero sonríe al reconocer que te has ganado guantes Karamja y te deja pasar a mitad de precio: 15 coins.",
    ["*Before Song from the Depths is completed*"] = "*Antes de que se complete Canción desde las profundidades*",
    ["Not now, can't you see I'm busy?"] = "Ahora no, ¿no ves que estoy ocupado?",
    ["Oh sorry, I didn't want to disturb you."] = "Oh, lo siento, no quería molestarte.",
    ["*After Song from the Depths is completed*"] = "*Después de completar Canción desde las profundidades*",
    ["Hey, could you please sing 'Wending through the Willows' for me? I love that song!"] = "Oye, ¿podrías cantarme 'Wending Through the Willows'? ¡Me encanta esa canción!",
    ["It is a terribly difficult song, I wouldn't do it justice. We are young and still learning to master our singing, that's what brought us here."] = "Es una canción terriblemente difícil, no le haría justicia. Somos jóvenes y todavía estamos aprendiendo a dominar nuestro canto, eso es lo que nos trajo aquí.",
    ["Ahoy!"] = "¡Ahoye!",
    ["Good day to you, wanderer! What do you want?"] = "¡Buenos días, vagabundo! ¿Qué deseas?",
    ["What are you doing out here?"] = "¿Qué estás haciendo aquí afuera?",
    ["My sisters and I came out here to sing and practice our beautiful voices, we strive to become famous seasingers."] = "Mis hermanas y yo vinimos aquí para cantar y practicar nuestras hermosas voces, nos esforzamos por convertirnos en cantantes marinos famosos.",
    ["As quaint as the island we call our home is, not much ever happens there. Music needs inspiration, new impressions, a fresh breeze!"] = "Por muy pintoresca que sea la isla que llamamos nuestro hogar, nunca sucede mucho allí. ¡La música necesita inspiración, nuevas impresiones, una brisa fresca!",
    ["This place here is exciting, all kinds of creatures emerge from the depths and I adore watching the people going about their busy lives."] = "Este lugar aquí es emocionante, todo tipo de criaturas emergen de las profundidades y adoro ver a la gente seguir con sus ocupadas vidas.",
    ["Are you singing your own songs...?"] = "¿Estás cantando tus propias canciones...?",
    ["Are you singing your own songs or just reciting those of your people?"] = "¿Estás cantando tus propias canciones o simplemente recitando las de tu gente?",
    ["I take great pride in writing my own songs. Of course, there's classics everyone adores, but it's important to leave your own mark on the world."] = "Me siento muy orgulloso de escribir mis propias canciones. Por supuesto, hay clásicos que todo el mundo adora, pero es importante dejar tu propia huella en el mundo.",
    ["Do you have a song you could share with me?"] = "¿Tienes una canción que puedas compartir conmigo?",
    ["I'm still working on the lyrics, but I'd love to hear what you think!"] = "Todavía estoy trabajando en la letra, ¡pero me encantaría escuchar lo que piensas!",
    ["*(The seasinger sings the song below.)*"] = "*(El cantante marino canta la canción a continuación.)*",
    ["That's is. What do you think?"] = "Ese es is. ¿Qué opinas?",
    ["What do you think about the siren's song?"] = "¿Qué opinas del canto de sirena?",
    ["I liked it. I find it very inspirational!"] = "Me gustó. ¡Lo encuentro muy inspirador!",
    ["Ah, a true appreciator of my song and storytelling, you flatter me! I will need to improve it, but I thank you kindly for being so encouraging."] = "Ah, un verdadero apreciador de mi canción y mi narración, ¡me halagas! Necesitaré mejorarlo, pero les agradezco amablemente por ser tan alentadores.",
    ["A bit cheesy, if you ask me."] = "Un poco cursi, si me preguntas.",
    ["Well, it is a song for sailors and fishing folk after all. Their lives are hard enough, sometimes they just need something uplifting!"] = "Bueno, después de todo, es una canción para marineros y pescadores. Sus vidas son bastante duras, ¡a veces simplemente necesitan algo que los levante!",
    ["I kind of spaced out halfway through."] = "Me quedé un poco distraído a mitad de camino.",
    ["Sorry, I kind of spaced out halfway through."] = "Lo siento, me quedé un poco distraído a la mitad.",
    ["What an awful habit. Sometimes I feel like people don't really listen to me. I wonder why they go through the effort of talking to me in the first place..."] = "Qué hábito tan horrible. A veces siento que la gente realmente no me escucha. Me pregunto por qué se esfuerzan en hablar conmigo en primer lugar...",
    ["I thought maybe you'd have some reward for me?"] = "Pensé que tal vez tendrías alguna recompensa para mí.",
    ["*sigh* Sometimes our experiences are the real reward, rather than what waits at the end. I hope you'll come to understand that one day."] = "*suspiro* A veces nuestras experiencias son la verdadera recompensa, en lugar de lo que nos espera al final. Espero que algún día llegues a entenderlo.",
    ["On the stormy isle of old Echo Bay lived once a maiden fair,"] = "En la tormentosa isla de la antigua Echo Bay hubo una vez una feria de doncellas,",
    ["Her heart was like the raging sea and wild as the wind her hair."] = "Su corazón era como el mar embravecido y salvaje como el viento su cabello.",
    ["Many yearned to win her love but she just had one wish,"] = "Muchos anhelaban conquistar su amor pero ella solo tenía un deseo,",
    ["To sail across the roaring waves, live freely like the fish."] = "Para navegar a través de las olas rugientes, vive libremente como los peces.",
    ["Throughout the day she toiled and moiled on the island's factory,"] = "Durante todo el día trabajó y se afanó en la fábrica de la isla,",
    ["Crafting barrels for gunpowder while she dreamt of being free."] = "Crafting barriles de pólvora mientras ella soñaba con ser libre.",
    ["At night she sat upon the beach, made plans to leave the land,"] = "Por la noche se sentaba en la playa, hacía planes para abandonar la tierra,",
    ["Tooralay hey, Tooraley dee,"] = "Tooralay oye, Tooraley dee,",
    ["When, oh when, will I be free?"] = "¿Cuándo, oh cuándo, seré libre?",
    ["Tooralay dee, tooralay hey,"] = "Tooralay dee, tooralay oye,",
    ["With the winds I'll sail one day!"] = "¡Con los vientos navegaré algún día!",
    ["Her first attempt to leave the isle was by charming a bold lad,"] = "Su primer intento de abandonar la isla fue encantando a un muchacho atrevido,",
    ["The dashing captain helped her escape and made the maiden glad."] = "El apuesto capitán la ayudó a escapar y alegró a la doncella.",
    ["But soon he saw into her heart, and was quite sad to see,"] = "Pero pronto él vio dentro de su corazón, y se entristeció mucho al ver,",
    ["Her dreams were filled with sailing, no love for him had she."] = "Sus sueños estaban llenos de navegación, ella no lo amaba.",
    ["He dropped her back onto her isle, gave her a golden heart."] = "La dejó de nuevo en su isla y le dio un corazón de oro.",
    ["This is my gift of love to you', he said as they did part,"] = "Este es mi regalo de amor para ti\", dijo mientras se separaban.",
    ["You shall forget your childish dreams, wish you had a husband dear!"] = "¡Olvidarás tus sueños infantiles, ojalá tuvieras un marido querida!",
    ["The gal didn't surrender, donned big boots and a shirt,"] = "La chica no se rindió, se puso unas botas grandes y una camisa,",
    ["Dressed as a lad in trousers, her face covered in dirt,"] = "Vestida como un muchacho con pantalones, con la cara cubierta de tierra,",
    ["She joined a ship, amongst the men she learned to sail and fight."] = "Se unió a un barco, entre los hombres aprendió a navegar y luchar.",
    ["Until she was discovered and brought back to her plight."] = "Hasta que la descubrieron y la devolvieron a su difícil situación.",
    ["Tears in h er eyes she stood by the shore as the ship set sail,"] = "Con lágrimas en los ojos, permaneció junto a la orilla mientras el barco zarpaba,",
    ["Oh mighty sea, I beg you' the young maiden did implore,"] = "Oh mar poderoso, te lo ruego' imploró la joven doncella,",
    ["Give me a ship to sail your waves and leave this cursed shore!"] = "¡Dame un barco para surcar tus olas y abandonar esta costa maldita!",
    ["They often said the sea was cruel but this time they were wrong,"] = "Muchas veces decían que el mar era cruel pero esta vez se equivocaban,",
    ["For it seems the waves had enjoyed our lovely maiden's song."] = "Porque parece que las olas habían disfrutado del canto de nuestra encantadora doncella.",
    ["Since short after her sacrifice a ship stranded on the isle,"] = "Dado que poco después de su sacrificio un barco encalló en la isla,",
    ["With broken mast, no crew around, she embraced it with a smile."] = "Con el mástil roto y sin tripulación cerca, lo abrazó con una sonrisa.",
    ["She fixed it up and found a crew of souls who love the sea,"] = "Ella lo arregló y encontró un grupo de almas que aman el mar,",
    ["Old and young and lad and lass, come all aboard!' yelled she."] = "¡Viejos y jóvenes, muchachos y muchachas, suban todos a bordo!' gritó ella.",
    ["And sometimes you may spot her in the distance with her crew,"] = "Y a veces puedes verla a lo lejos con su tripulación,",
    ["I love the sea for setting us free!"] = "¡Amo el mar por liberarnos!",
    ["With the winds we sail away!"] = "¡Con los vientos nos alejamos!",
    ["Hmm... Door hinge... No... Boar cringe? Urgh, this is so frustrating!"] = "Hmm... Bisagra de puerta... No... ¿Se encoge de jabalí? ¡Urgh, esto es tan frustrante!",
    ["Excuse me, what?"] = "Disculpe, ¿qué?",
    ["Oh, hello there! Sorry, I didn't see you, I was deep in thought."] = "¡Oh, hola! Lo siento, no te vi, estaba sumido en mis pensamientos.",
    ["Why, what's going on?"] = "¿Por qué? ¿Qué está pasando?",
    ["Oh, I'm trying to win a bet. A band of sailors have promised me a fair amount of gold if I can find a good rhyme for them!"] = "Oh, estoy intentando ganar una apuesta. ¡Una banda de marineros me ha prometido una buena cantidad de oro si encuentro una buena rima para ellos!",
    ["Maybe I can help?"] = "¿Quizás pueda ayudar?",
    ["That would be amazing! All I need is a rhyme for orange?"] = "¡Eso sería increíble! ¿Todo lo que necesito es una rima para naranja?",
    ["Sure, what about... erm..."] = "Claro, ¿qué pasa con... ejem...?",
    ["...uhmmm..."] = "...ummm...",
    ["Okay, I guess sometimes even I have to admit defeat. Good luck with that one!"] = "Vale, supongo que a veces incluso yo tengo que admitir la derrota. ¡Buena suerte con eso!",
    ["You wave at the siren. She seems to pout about something and pays no attention to you in the slightest."] = "Saludas a la sirena. Ella parece hacer pucheros por algo y no te presta la más mínima atención.",
    ["You listen to the seasinger's song."] = "Escuchas la canción del cantor marino.",
    ["She's not interested in you."] = "Ella no está interesada en ti.",
    ["You've already listened to her song."] = "Ya has escuchado su canción.",
    ["You are rewarded for listening to the seasinger - You receive [number] Fishing XP."] = "Serás recompensado por escuchar al cantante marino: recibirás [número] Fishing XP.",
    ["So you're the new Portmaster? I can tell you're busy, but maybe we should catch up later?"] = "¿Entonces eres el nuevo Portmaster? Puedo ver que estás ocupado, pero ¿tal vez deberíamos ponernos al día más tarde?",
    ["Oh, hello there. Don't mind me, I'm just taking a break from sweeping."] = "Oh, hola. No me hagas caso, sólo estoy tomando un descanso de barrer.",
    ["I'm Umi."] = "Soy Umi.",
    ["*(Continues below)*"] = "*(Continúa a continuación)*",
    ["What are you?"] = "¿Qué eres?",
    ["What am I? How rude. I'm a siren, obviously."] = "¿Qué soy? Qué grosero. Soy una sirena, obviamente.",
    ["Are you a siren?"] = "¿Eres una sirena?",
    ["Very observant! Normally I'm asked whether I'm a mermaid or a fish. I've heard more fish jokes than you could shake a mermaid's tail at. Nice to meet you."] = "¡Muy observador! Normalmente me preguntan si soy una sirena o un pez. He escuchado más chistes sobre peces de los que podrías imaginar con la cola de una sirena. Encantado de conocerlo.",
    ["Seems odd that a siren would work as a sweep. Shouldn't you be luring sailors to their watery graves?"] = "Parece extraño que una sirena funcione como barrido. ¿No deberías atraer a los marineros a sus tumbas acuáticas?",
    ["If only. No I'm training to become a seasinger. One day I'll be able to control the seas and the creatures that live within it. It just takes such a long time to learn. Until then I've got to earn my keep. Some day I'll work for a khan, guide his ships and sleep in his palace. When I think of that, well, the sweeping doesn't seem so bad."] = "Si tan solo. No, estoy entrenando para convertirme en cantante marino. Un día podré controlar los mares y las criaturas que viven en ellos. Simplemente lleva mucho tiempo aprender. Hasta entonces tengo que ganarme el sustento. Algún día trabajaré para un Khan, guiaré sus barcos y dormiré en su palacio. Cuando pienso en eso, bueno, barrer no parece tan malo.",
    ["Hiya. I'm giving out free books that teach you how to keep your account secure."] = "Hola. Estoy repartiendo libros gratuitos que le enseñan cómo mantener segura su cuenta.",
    ["[The Security Guard hands you a book about security.]"] = "[El Security Guard te entrega un libro sobre seguridad.]",
    ["Oh? Thanks."] = "¿Ah? Gracias.",
    ["You're welcome."] = "De nada.",
    ["Got one already, thanks."] = "Ya tengo uno, gracias.",
    ["Okay. Have a nice day."] = "Está bien. Que tenga un lindo día.",
    ["Aha! Question time! Should you log in anywhere other than the RuneScape website?"] = "¡Ajá! ¡Hora de preguntas! ¿Deberías iniciar sesión en cualquier otro lugar que no sea el sitio web de RuneScape?",
    ["IMPORTANT: You should never log in in anywhere other than the RuneScape website."] = "IMPORTANTE: Nunca debes iniciar sesión en ningún otro lugar que no sea el sitio web de RuneScape.",
    ["Good, you're smarter than you look."] = "Bien, eres más inteligente de lo que pareces.",
    ["The guard happily hands you a scroll box."] = "El guardia te entrega felizmente un cuadro de pergamino.",
    ["Well done, you received a [pair of caskets/scroll box]!"] = "¡Bien hecho, recibiste un [pair of caskets/scroll box]!",
    ["Aha! Question time! What do I do if my account is compromised?"] = "¡Ajá! ¡Tiempo de preguntas! ¿Qué hago si mi cuenta está comprometida?",
    ["Post on social media about it."] = "Publica en las redes sociales al respecto.",
    ["Wrong! Social media will often not solve the problem directly and will only succeed in directing you to the RuneScape website to regain access to your account."] = "¡Mal! Las redes sociales a menudo no resolverán el problema directamente y solo lograrán dirigirlo al sitio web de RuneScape para recuperar el acceso a su cuenta.",
    ["Secure my computer and reset my RuneScape password."] = "Asegure mi computadora y restablezca mi contraseña de RuneScape.",
    ["Correct! Securing your systems with virus and malware scans is important before resetting your account password to ensure your details are not compromised again. Don't forget to secure your email account too!"] = "¡Correcto! Es importante proteger sus sistemas con análisis de virus y malware antes de restablecer la contraseña de su cuenta para garantizar que sus datos no vuelvan a verse comprometidos. ¡No olvides proteger también tu cuenta de correo electrónico!",
    ["Well done, you received a [pair of caskets./scroll box!]"] = "Bien hecho, recibiste un [pair of caskets./scroll box!].",
    ["Aha! Question time! You have been offered an opportunity to check out a free giveaway or double XP sign-up via social media or stream. What should you do?"] = "¡Ajá! ¡Hora de preguntas! Se le ha ofrecido la oportunidad de ver un sorteo gratuito o registrarse con doble XP a través de las redes sociales o en streaming. ¿Qué deberías hacer?",
    ["Respond quickly so as not to miss the offer."] = "Responde rápidamente para no perder la oferta.",
    ["Wrong! Jagex will NEVER make offers like this - it is an attempt to obtain your account details. Please report the incident using whatever reporting methods offered by the site you are on."] = "¡Mal! Jagex NUNCA hará ofertas como esta: es un intento de obtener los detalles de su cuenta. Informe el incidente utilizando cualquier método de informe que ofrezca el sitio en el que se encuentra.",
    ["*(The guard disappears.)*"] = "*(El guardia desaparece.)*",
    ["Report the incident and do not click any links."] = "Informe el incidente y no haga clic en ningún enlace.",
    ["Correct! This is an attempt to obtain your account details and should be reported to the relevant organisation via their own reporting systems."] = "¡Correcto! Este es un intento de obtener los detalles de su cuenta y debe informarse a la organización correspondiente a través de sus propios sistemas de informes.",
    ["Follow this trail! Visit our Support Centre by going to the RuneScape homepage and hitting 'Support' in the top-right of the website. Search for the 'securing your computer and account' article. How many steps do we advise players to go through?"] = "¡Sigue este rastro! Visita nuestro Centro de soporte yendo a la página de inicio de RuneScape y presionando \"Soporte\" en la parte superior derecha del sitio web. Busque el artículo \"proteger su computadora y su cuenta\". ¿Cuántos pasos recomendamos que sigan los jugadores?",
    ["*(If players enter a number not equal to 7:)*"] = "*(Si los jugadores ingresan un número distinto de 7:)*",
    ["Incorrect! Please visit the Support Centre to find the correct answer."] = "¡Incorrecto! Visite el Centro de soporte para encontrar la respuesta correcta.",
    ["*(If players enters 7:)*"] = "*(Si los jugadores ingresan 7:)*",
    ["Correct! Well done!"] = "¡Correcto! ¡Bien hecho!",
    ["The guard happily hands you a reward."] = "El guardia te entrega felizmente una recompensa.",
    ["Well done, you received a [pair of caskets/scroll box]."] = "Bien hecho, recibiste un [pair of caskets/scroll box].",
    ["Aha! Question time! Should you give your Authenticator code to anyone who asks?"] = "¡Ajá! ¡Hora de preguntas! ¿Deberías darle tu código de autenticación a cualquiera que te lo pida?",
    ["IMPORTANT: You should never put in your Authenticator other than when logging into RuneScape."] = "IMPORTANTE: Nunca debes ingresar tu Autenticador excepto cuando inicias sesión en RuneScape.",
    ["You're handed a [clue scroll/pair of caskets]."] = "Te entregan un [clue scroll/pair of caskets].",
    ["Aha! Question time! How do you set a bank PIN?"] = "¡Ajá! ¡Tiempo de preguntas! ¿Cómo se configura un PIN bancario?",
    ["Talk to any banker in RuneScape."] = "Habla con cualquier banquero en RuneScape.",
    ["Correct! Simply talking to a banker will give you the option to set a bank PIN. Never use personal details for passwords or bank PINs!"] = "¡Correcto! Simplemente hablar con un banquero le dará la opción de establecer un PIN bancario. ¡Nunca utilice datos personales como contraseñas o PIN bancarios!",
    ["Use the Account Management section on the website."] = "Utilice la sección Gestión de cuentas del sitio web.",
    ["Wrong! Your password can be changed from the Account Management section, but you must talk to a banker to set a bank PIN. Never use personal details for passwords or bank PINs!"] = "¡Mal! Su contraseña se puede cambiar desde la sección Gestión de cuenta, pero debe hablar con un banquero para establecer un PIN bancario. ¡Nunca utilice datos personales como contraseñas o PIN bancarios!",
    ["Aha! Question time! How do you set up two-factor authentication for your RuneScape account?"] = "¡Ajá! ¡Hora de preguntas! ¿Cómo se configura la autenticación de dos factores para su cuenta de RuneScape?",
    ["Through account settings on RuneScape.com."] = "A través de la configuración de la cuenta en RuneScape.com.",
    ["Correct! Vising RuneScape.com and using the Account link at the top of the page will allow you to set up two-factor authentication."] = "¡Correcto! Visitar RuneScape.com y utilizar el enlace Cuenta en la parte superior de la página le permitirá configurar la autenticación de dos factores.",
    ["By emailing RuneScape."] = "Enviando un correo electrónico a RuneScape.",
    ["Wrong! Visiting RuneScape.com and using the Account link at the top of the page will allow you to set up two-factor authentication."] = "¡Mal! Visitar RuneScape.com y utilizar el enlace Cuenta en la parte superior de la página le permitirá configurar la autenticación de dos factores.",
    ["I buy and sell adventurer's equipment, do you want to trade?"] = "Compro y vendo equipo de aventurero, ¿quieres intercambiar?",
    ["No thank you."] = "No, gracias.",
    ["I See. You?"] = "Ya veo. ¿Tú?",
    ["Er, do you? With that weird hat on?"] = "Er, ¿y tú? ¿Con ese sombrero raro puesto?",
    ["No. I am See - that's my name. Who are you?"] = "No. Soy See, ese es mi nombre. ¿Quién eres?",
    ["I see."] = "Ya veo.",
    ["You said that already."] = "Eso ya lo dijiste.",
    ["You are here to ask me questions."] = "Estás aquí para hacerme preguntas.",
    ["Am I? Are you asking me that or telling me?"] = "¿Lo soy? ¿Me preguntas eso o me lo dices?",
    ["Er, okay."] = "Er, está bien.",
    ["You talking to See?"] = "¿Estás hablando con Ver?",
    ["I contemplate the moon, and shall do so until it dawns on me."] = "Contemplo la luna, y así lo haré hasta que amanezca sobre mí.",
    ["Isn't that a contradiction - moon, dawn?"] = "¿No es una contradicción: luna, amanecer?",
    ["It is a metaphor."] = "Es una metáfora.",
    ["Ancient cyclopean beliefs tell of the two creators - the Eyes in the Sky. Those being Hanalan - the sun - and Birman - the moon"] = "Las antiguas creencias ciclópeas hablan de los dos creadores: los Ojos en el Cielo. Estos son Hanalan - el sol - y Birman - la luna.",
    ["When our path led us away from Bandos, we took back our old traditions. We are no longer naive enough to believe them being divine creators."] = "Cuando nuestro camino nos alejó de Bandos, recuperamos nuestras antiguas tradiciones. Ya no somos tan ingenuos como para creer que son creadores divinos.",
    ["Rather, we recognise the good and bad that both the sun and moon can bring, and that both are necessary for our way of life."] = "Más bien, reconocemos lo bueno y lo malo que tanto el sol como la luna pueden traer, y que ambos son necesarios para nuestra forma de vida.",
    ["As one of the eldest cyclopes, I hold the mantle of moon priestess, and represent the issues faced by those that live on moon-side."] = "Como uno de los cíclopes mayores, sostengo el manto de sacerdotisa de la luna y represento los problemas que enfrentan quienes viven en el lado de la luna.",
    ["And I contemplate the teachings of Birman within the Moon Tower."] = "Y contemplo las enseñanzas de Birmania dentro de la Torre de la Luna.",
    ["See and you shall find?"] = "¿Ves y encontrarás?",
    ["Can you tell me about Birman?"] = "¿Puedes hablarme de Birmania?",
    ["Am I asking, though, or just leaving?"] = "¿Estoy preguntando o simplemente me voy?",
    ["Birman is the Eye in the Night Sky. His eye is the moon, and his beard the stars."] = "Birmania es el ojo en el cielo nocturno. Su ojo es la luna y su barba las estrellas.",
    ["When he brings the night, he brings sweetness to the world with berries and coconuts, and sometimes a tiny umbrella."] = "Cuando trae la noche, trae dulzura al mundo con berries y cocos y, a veces, un pequeño paraguas.",
    ["How does that work?"] = "¿Cómo funciona eso?",
    ["Hoo, boy. Well, if you don't already know, then I'm not the person to have 'the talk' with you."] = "Hoo, muchacho. Bueno, si aún no lo sabes, entonces no soy la persona indicada para tener \"la charla\" contigo.",
    ["You are leaving. See?"] = "Te vas. ¿Ver?",
    ["Hello, there! Nice day, isn't it?"] = "¡Hola! Bonito día, ¿no?",
    ["Hmph, it an okay day. Not so sure is nice day. Bit sticky, bit hot. Makes my bones itch."] = "Hmph, es un buen día. No estoy tan seguro de que sea un buen día. Un poco pegajoso, un poco caliente. Hace que me piquen los huesos.",
    ["Makes your bones...itch? How does that work?"] = "¿Te pica los huesos...? ¿Cómo funciona eso?",
    ["When you get old, you understand."] = "Cuando envejeces, lo entiendes.",
    ["Thank you much, human. You may be scrawny, but you not bad thinker."] = "Muchas gracias, humano. Puede que seas flacucho, pero no eres mal pensador.",
    ["Can you tell me about these pools?"] = "¿Puedes hablarme de estas piscinas?",
    ["Of course. Which pool you want know about?"] = "Por supuesto. ¿De qué piscina quieres saber?",
    ["Bandos pool"] = "piscina Bandos",
    ["Can you tell me about the red Bandos pool, please?"] = "¿Puedes contarme sobre el grupo rojo Bandos, por favor?",
    ["Oh, dat de most mysterious of all pools here - it infused with energy of Bandos. Anyone who takes bath in dat pool can be recognised as one of Bandos' own. No follower of Bandos will raise hand against you when you purified with dat water."] = "Oh, la más misteriosa de todas las piscinas que hay aquí es la que está impregnada de la energía de Bandos. Cualquiera que se bañe en esa piscina puede ser reconocido como uno de los de Bandos. Ningún seguidor de Bandos levantará la mano contra ti cuando te purifiques con esa agua.",
    ["Interesting."] = "Interesante.",
    ["Anything else you want know about?"] = "¿Algo más que quieras saber?",
    ["Sure thing! Which pool you want know about?"] = "¡Claro! ¿De qué piscina quieres saber?",
    ["No, thanks."] = "No, gracias.",
    ["Salt-water spring"] = "manantial de agua salada",
    ["Can you tell me about the salt-water spring, please?"] = "¿Puedes contarme sobre el manantial de agua salada, por favor?",
    ["Dat pool very interesting - is fed by source under surface of water. You feel it moving fast when you bathe there. We take swim in that pool if we know we have long way to run. Always seems like one not get so tired quickly after bath in fast waters."] = "Esta piscina es muy interesante: se alimenta de una fuente debajo de la superficie del agua. Sientes que se mueve rápido cuando te bañas allí. Nadamos en esa piscina si sabemos que tenemos un largo camino por recorrer. Siempre parece que uno no se cansa tan rápido después de bañarse en aguas rápidas.",
    ["Mud bath"] = "baño de barro",
    ["Can you tell me about the mud pool, please?"] = "¿Puedes contarme sobre la piscina de barro, por favor?",
    ["Dat a very useful pool for young creatures who like to hunt. Mud very good at disguising smells. You take a swim in de mud, you find de little creatures nearly jump into your traps."] = "Es una reserva muy útil para criaturas jóvenes a las que les gusta cazar. Barro muy bueno para disimular los olores. Te das un baño en el barro y descubres que las pequeñas criaturas casi saltan a tus trampas.",
    ["Sulphur spring"] = "manantial de azufre",
    ["Can you tell me about the sulphur spring, please?"] = "¿Puedes contarme sobre el manantial de azufre, por favor?",
    ["Hmm, yes, dat an interesting pool, human. Mostly used by ogre shamans and mystics like me, though some like to bathe in it because it smell so nice."] = "Hmm, sí, es un grupo interesante, humano. Lo utilizan principalmente chamanes ogros y místicos como yo, aunque a algunos les gusta bañarse en él porque huele muy bien.",
    ["It smells like horrible rotten eggs that have been marinated in swamp gas!"] = "¡Huele como a huevos podridos horribles marinados en gas de pantano!",
    ["Yes, very lovely smell - and lasts long time!"] = "Sí, huele muy bien, ¡y dura mucho tiempo!",
    ["Uh, right."] = "Ah, claro.",
    ["It also good place to go if you feeling empty in spirit. Me think you humans use altars? We ogres sometimes use pools like this one."] = "También es un buen lugar para ir si te sientes vacío de espíritu. ¿Creo que ustedes los humanos usan altares? Los ogros a veces usamos piscinas como ésta.",
    ["Thermal bath"] = "baño termal",
    ["Can you tell me about the thermal bath, please?"] = "¿Puedes hablarme del baño termal, por favor?",
    ["Ah, dat pool very pure and it runs deep - you can tell by de turquoise colour. You relax in dat pool for a while, you feel much better."] = "Ah, esa piscina es muy pura y profunda; se nota por el color turquesa. Te relajas un rato en esa piscina, te sientes mucho mejor.",
    ["Ogres use dat pool for many, many years to cure all sorts of ailments. If you poisoned, if you diseased, if you hurt, you just take a swim - you feel better than ever, me promise!"] = "Los ogros usan ese grupo durante muchos, muchos años para curar todo tipo de dolencias. Si estás envenenado, si estás enfermo, si te duele, simplemente date un baño y te sentirás mejor que nunca, ¡lo prometo!",
    ["Uh, what was that dark force? I've never sensed anything like it..."] = "Eh, ¿qué era esa fuerza oscura? Nunca he sentido nada parecido...",
    ["Anyway, sorry about that."] = "De todos modos, lo siento.",
    ["I seek knowledge and power."] = "Busco conocimiento y poder.",
    ["I seek knowledge and power!"] = "¡Busco conocimiento y poder!",
    ["Knowledge comes from experience, power comes from battleaxes."] = "El conocimiento proviene de la experiencia, el poder proviene de las hachas de batalla.",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["Hi. I've completed the Easy Tasks in the Seers' Village set."] = "Hola. Completé las tareas fáciles en el conjunto Aldea de los videntes.",
    ["Well done, adventurer. You are clearly a man of great wisdom. I have a gift for you."] = "Bien hecho, aventurero. Es evidente que eres un hombre de gran sabiduría. Tengo un regalo para ti.",
    ["[The seer hands you a strange-looking headband and a rusty lamp.]"] = "[El vidente te entrega una diadema de aspecto extraño y una lámpara oxidada.]",
    ["You are now a honorary seer and Geoffrey - who works in the flax field to the south - will give you free flax every day. Don't call him Geoffrey, though; he prefers to be known as 'Flax'."] = "Ahora eres un vidente honorario y Geoffrey, que trabaja en el campo de lino del sur, te dará lino gratis todos los días. Pero no lo llames Geoffrey; prefiere que lo conozcan como \"Flax\".",
    ["Is that it?"] = "¿Es eso todo?",
    ["No, no. As well as Flax giving you 30 flax per day, you'll be able to see dimly in the dark and your defence against magic attacks will be boosted."] = "No, no. Además de que Flax te dará 30 linaza por día, podrás ver con claridad en la oscuridad y tu defensa contra los ataques mágicos aumentará.",
    ["Stankers will allow 140 pieces of coal in his coal truck, and you'll get an extra log when cutting normal trees."] = "Stankers permitirá 140 trozos de carbón en su camión de carbón y obtendrás un tronco adicional al cortar árboles normales.",
    ["Flax? What sort of name is that for a person?"] = "¿Lino? ¿Qué clase de nombre es ese para una persona?",
    ["I know, I know. The poor boy is a simple soul - he just really loves picking flax. A little too much, I fear."] = "Lo sé, lo sé. El pobre niño es un alma sencilla: le encanta recoger lino. Me temo que demasiado.",
    ["I've lost my seers' headband."] = "He perdido la diadema de mi vidente.",
    ["Never fear! I can give you a new one. We seers are forgetful ourselves, so I have plenty."] = "¡No temas! Puedo darte uno nuevo. Nosotros, los videntes, somos olvidadizos, así que tengo muchos.",
    ["[The seer hands you a strange-looking headband.]"] = "[El vidente te entrega una diadema de aspecto extraño.]",
    ["How are you enjoying your headband?"] = "¿Cómo disfrutas tu diadema?",
    ["I love it!"] = "¡Me encanta!",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["For completing the Seers' Village set, you are presented with a headband."] = "Para completar el conjunto Seers' Village, se te presenta una diadema.",
    ["You will receive a better headband with each difficulty level of the set that you complete."] = "Recibirás una diadema mejor con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in a set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas de un conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Seers' Village set's Tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Seers' Village son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["To claim your Seers' Village set rewards, speak to Stankers at the coal mine to the west, Sir Kay in Camelot, or any of us seers."] = "Para reclamar las recompensas del conjunto Seers' Village, habla con Stankers en la mina de carbón al oeste, con Sir Kay en Camelot o con cualquiera de nosotros, los videntes.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Seer's headband 1"] = "Diadema de Seer 1",
    ["Seer's headband 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿La diadema 1 de Seer? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["[You're handed another Seer's headband 1.]"] = "[Te entregan la diadema 1 de otro Seer.]",
    ["Seer's headband 2"] = "Diadema de Seer 2",
    ["Seer's headband 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿La diadema 2 de Seer? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Seer's headband 2.]"] = "[Te entregan la diadema 2 de otro Seer.]",
    ["Seer's headband 3"] = "Diadema de Seer 3",
    ["Seer's headband 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿La diadema 3 de Seer? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Seer's headband 3.]"] = "[Te entregan la diadema de otro Seer 3.]",
    ["Seer's headband 4"] = "Diadema de Seer 4",
    ["Seer's headband 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿La diadema 4 de Seer? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Seer's headband 4.]"] = "[Te entregan la diadema de otro Seer 4.]",
    ["I'd like to change my teleport point."] = "Me gustaría cambiar mi punto de teletransporte.",
    ["I'd like to change my Camelot Teleport point."] = "Me gustaría cambiar mi punto de Camelot Teleport.",
    ["Toggle Camelot Teleport to [Seers' Village/Camelot]?"] = "¿Cambiar Camelot Teleport a [Seers' Village/Camelot]?",
    ["Camelot Teleport will now teleport you to the [Seers' Village/to the gates of Camelot]."] = "Camelot Teleport ahora te teletransportará al [Seers' Village/to the gates of Camelot].",
    ["Toggle Camelot Teleport"] = "Alternar teletransporte de Camelot",
    ["What have you sensed lately?"] = "¿Qué has sentido últimamente?",
    ["I haven't sensed much lately, except when the gods departed from the battlefield near Lumbridge."] = "No he sentido mucho últimamente, excepto cuando los dioses partieron del campo de batalla cerca de Lumbridge.",
    ["Perhaps something will happen soon!"] = "¡Quizás suceda algo pronto!",
    ["*or*"] = "*o*",
    ["Seiryu is already communicating telepathically to you, it would be best not to interrupt him."] = "Seiryu ya se está comunicando telepáticamente contigo, lo mejor sería no interrumpirlo.",
    ["Seiryu acknowledges you gratefully as he slowly recovers."] = "Seiryu te reconoce agradecido mientras se recupera lentamente.",
    ["Seiryu nods at you graciously and with great relief."] = "Seiryu te saluda con gracia y con gran alivio.",
    ["*(Random one of the following is shown:)*"] = "*(Se muestra uno de los siguientes al azar:)*",
    ["*(Variant 1:)*"] = "*(Variante 1:)*",
    ["*(Variant 2:)*"] = "*(Variante 2:)*",
    ["*(Variant 3:)*"] = "*(Variante 3:)*",
    ["*(Variant 4:)*"] = "*(Variante 4:)*",
    ["*(Variant 5:)*"] = "*(Variante 5:)*",
    ["*(Variant 6:)*"] = "*(Variante 6:)*",
    ["*(Variant 7:)*"] = "*(Variante 7:)*",
    ["*(Variant 8:)*"] = "*(Variante 8:)*",
    ["Seiryu activates your inert black stone crystal!"] = "¡Seiryu activa tu cristal de piedra negra inerte!",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["Can you tell me a bit about your people?"] = "¿Puedes contarme un poco sobre tu gente?",
    ["Ok. Like what?"] = "Vale. ¿Cómo qué?",
    ["How about the values of the Moon clan!"] = "¿Qué tal los valores del clan Moon?",
    ["Let me see... We value knowledge of self because it is this that gives us our strength! It is most important!"] = "Déjame ver... Valoramos el conocimiento de nosotros mismos porque es esto lo que nos da nuestra fuerza. ¡Es lo más importante!",
    ["Well... I know things about myself. I know I like hot chocolate!"] = "Bueno... sé cosas sobre mí. ¡Sé que me gusta el chocolate caliente!",
    ["I was meaning something a little deeper than that. We also like to see someone listen. You know how they say a wise man listens?"] = "Me refería a algo un poco más profundo que eso. También nos gusta ver a alguien escuchar. ¿Sabes lo que dicen que un hombre sabio escucha?",
    ["Did you hear me?"] = "¿Me escuchaste?",
    ["... I'm listening."] = "... I estoy escuchando.",
    ["Most wise."] = "Muy sabio.",
    ["Greetings, young one. It is not often we see the living in these parts."] = "Saludos, joven. No es frecuente ver a los vivos en estos lugares.",
    ["I am Selene. I was a priestess in life, and I suppose I still am even in death."] = "Soy Selene. Fui sacerdotisa en vida, y supongo que todavía lo soy incluso muerta.",
    ["2 souls fly over to power the vessel."] = "2 almas vuelan para impulsar el barco.",
    ["Which God do you worship?"] = "¿A qué Dios adoras?",
    ["What god are you a priestess of?"] = "¿De qué dios eres sacerdotisa?",
    ["Not god, sweet child. Gods."] = "Dios no, dulce niña. Gallinero.",
    ["You worship multiple gods? That's uncommon."] = "¿Adoras a varios dioses? Eso es poco común.",
    ["Yes, so I've been told."] = "Sí, eso me han dicho.",
    ["You see, where I am from, we see value in the teachings of all the gods."] = "Verás, de donde soy, vemos valor en las enseñanzas de todos los dioses.",
    ["But how can you worship both gods that teach peace and gods that promote war? Chaos and order? Aren't they conflicting?"] = "Pero ¿cómo puedes adorar tanto a dioses que enseñan la paz como a dioses que promueven la guerra? ¿Caos y orden? ¿No son contradictorios?",
    ["Ah, you are familiar with the gods."] = "Ah, estás familiarizado con los dioses.",
    ["You see, my child, these aren't as conflicting as you believe."] = "Verás, hija mía, estos no son tan contradictorios como crees.",
    ["Perhaps I could teach you one day."] = "Quizás algún día pueda enseñarte.",
    ["I'm good."] = "Estoy bien.",
    ["Uhhh... I'm good, thanks."] = "Uhhh... Estoy bien, gracias.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["I suppose you're wondering about the shrines."] = "Supongo que te estarás preguntando acerca de los santuarios.",
    ["Well, yes, a little."] = "Bueno, sí, un poco.",
    ["There are those that struggle greatly, my child. Both in life and in death."] = "Hay quienes luchan mucho, hija mía. Tanto en la vida como en la muerte.",
    ["I create the shrines in honour of those, in hope that the universe might ease their burden."] = "Creo los santuarios en honor a ellos, con la esperanza de que el universo pueda aliviar su carga.",
    ["There is an irony, I suppose."] = "Hay una ironía, supongo.",
    ["In life, it was the dead I pitied. But only in death did I realise that, for some, life is much harder."] = "En vida, me compadecían de los muertos. Pero sólo en la muerte me di cuenta de que, para algunos, la vida es mucho más dura.",
    ["That's sad."] = "Eso es triste.",
    ["Indeed it is. Perhaps I will light a shrine for you too."] = "De hecho lo es. Quizás también te encienda un santuario.",
    ["Can you teach me any prayers?"] = "¿Puedes enseñarme alguna oración?",
    ["Would you happen to know any prayers that can aid me in necromancy?"] = "¿Conoces alguna oración que pueda ayudarme en la nigromancia?",
    ["Lord Saradomin not hearing your call?"] = "¿Señor Saradomin no escucha tu llamada?",
    ["I would be happy to sit and hear these words, young one."] = "Me encantaría sentarme y escuchar estas palabras, joven.",
    ["You study Selene as she teaches you two prayers to help with necromancy."] = "Estudias a Selene mientras ella te enseña dos oraciones para ayudarte con la nigromancia.",
    ["[You have unlocked the Hand of Doom and Accelerated Decay prayers.]"] = "[Has desbloqueado las oraciones de Hand of Doom y Accelerated Decay.]",
    ["Anything else?"] = "¿Algo más?",
    ["What would you like to learn?"] = "¿Qué te gustaría aprender?",
    ["Sanctity (requires 60 Necromancy)."] = "Santidad (requires 60 Necromancy).",
    ["Do you know any other prayers you could teach me?"] = "¿Conoces alguna otra oración que puedas enseñarme?",
    ["Tell me, do you know the Pious prayers of Saradomin?"] = "Dime, ¿conoces las Piadosas oraciones de Saradomin?",
    ["I'm afraid not."] = "Me temo que no.",
    ["Return to me when you have deepened your knowledge of Saradomin's teachings."] = "Vuelve a mí cuando hayas profundizado tu conocimiento de las enseñanzas de Saradomin.",
    ["[You require level 60 Necromancy, and need to have completed the King's Ransom quest and Knight's Waves training grounds to unlock the Sanctity prayer.]"] = "[Necesitas el nivel 60 Necromancy y haber completado la misión King's Ransom y el campo de entrenamiento Knight's Waves para desbloquear la oración de santidad.]",
    ["I do."] = "Sí, sí.",
    ["Let me get a look at you then."] = "Déjame verte entonces.",
    ["Hmm... I do not think you are sufficiently strong to learn this prayer. Return to me when you are."] = "Hmm... No creo que seas lo suficientemente fuerte para aprender esta oración. Vuelve a mí cuando lo estés.",
    ["[You require level 60 Necromancy to unlock the Sanctity prayer.]"] = "[Necesitas el nivel 60 Necromancy para desbloquear la oración de santidad.]",
    ["Then allow me to teach you further."] = "Entonces permíteme enseñarte más.",
    ["You listen intently as Selene teaches you an old Saradominst prayer."] = "Escuchas atentamente mientras Selene te enseña una antigua oración saradominista.",
    ["[You have unlocked the Sanctity prayer.]"] = "[Has desbloqueado la oración de Santidad.]",
    ["Sap Necromancy."] = "Savia Necromancy.",
    ["Hmm... Tell me, child, what do you know of Zaros's teachings?"] = "Hmm... Dime, niña, ¿qué sabes de las enseñanzas de Zaros?",
    ["Not a great deal, actually."] = "No es mucho, en realidad.",
    ["Expand your horizons, then return to me. You have much to learn."] = "Expande tus horizontes y luego regresa a mí. Tienes mucho que aprender.",
    ["[You need to have completed the The Temple at Senntisten quest to unlock the Sap Necromancy Attack and Sap Necromancy Strength curses.]"] = "[Debes haber completado la misión The Temple at Senntisten para desbloquear las maldiciones Sap Necromancy Attack y Sap Necromancy Strength.]",
    ["I'd say I know my fair share. I actually already know a series of ancient curses through an ancient hymnal I once read."] = "Yo diría que conozco mi parte justa. De hecho, ya conozco una serie de maldiciones antiguas a través de un antiguo himnario que leí una vez.",
    ["Very good, then allow me to teach you more."] = "Muy bien, entonces déjame enseñarte más.",
    ["You listen intently as Selene recites a pair of ancient curses."] = "Escuchas atentamente mientras Selene recita un par de maldiciones antiguas.",
    ["[You have unlocked the Sap Necromancy Attack and Sap Necromancy Strength curses.]"] = "[Has desbloqueado las maldiciones Sap Necromancy Attack y Sap Necromancy Strength.]",
    ["Leech Necromancy (requires 70 Necromancy)."] = "Sanguijuela Necromancy (requires 70 Necromancy).",
    ["Do you know any other curses you could teach me?"] = "¿Conoces alguna otra maldición que puedas enseñarme?",
    ["I could teach you more ancient curses?"] = "¿Podría enseñarte más maldiciones antiguas?",
    ["Alas, you need to grow stronger to master this curse."] = "Lamentablemente, necesitas hacerte más fuerte para dominar esta maldición.",
    ["[You require level 70 Necromancy to unlock the Leech Necromancy Attack and Leech Necromancy Strength curses.]"] = "[Necesitas el nivel 70 Necromancy para desbloquear las maldiciones Leech Necromancy Attack y Leech Necromancy Strength.]",
    ["I am ready."] = "Estoy listo.",
    ["Very well, then allow me to teach you."] = "Muy bien, entonces déjame enseñarte.",
    ["You listen as Selene teaches you a very old Zarosian proverb. You're not sure what it's got to do with prayers."] = "Escuchas mientras Selene te enseña un proverbio zarosiano muy antiguo. No estás seguro de qué tiene que ver con las oraciones.",
    ["[You have unlocked the Leech Necromancy Attack and Leech Necromancy Strength curses.]"] = "[Has desbloqueado las maldiciones Leech Necromancy Attack y Leech Necromancy Strength.]",
    ["Sorrow (requires 90 Necromancy)."] = "Dolor (requires 90 Necromancy).",
    ["There is one last powerful curse I could teach you."] = "Hay una última maldición poderosa que podría enseñarte.",
    ["Alas, you need to grow stonger to master this curse."] = "Por desgracia, necesitas volverte más fuerte para dominar esta maldición.",
    ["[You require level 90 Necromancy to unlock the Sorrow curse.]"] = "[Necesitas el nivel 90 Necromancy para desbloquear la maldición del dolor.]",
    ["Selene teaches you to draw an ancient power from yourself, you're not sure if you nodded off."] = "Selene te enseña a extraer un poder antiguo de ti mismo, no estás seguro si te quedaste dormido.",
    ["[You have unlocked the Sorrow curse.]"] = "[Has desbloqueado la maldición del dolor.]",
    ["Ruination (requires 95 Necromancy)."] = "Ruina (requires 95 Necromancy).",
    ["I believe you've learnt all the curses I have to teach."] = "Creo que has aprendido todas las maldiciones que tengo para enseñarte.",
    ["Although..."] = "Aunque...",
    ["When I was alive, I heard musings."] = "Cuando estaba vivo, escuché reflexiones.",
    ["If there was any weight to them, it would suggest there are a few copies of a codex detailing curses used by the ancient Praesul order."] = "Si tuvieran algo de peso, sugeriría que hay algunas copias de un códice que detalla las maldiciones utilizadas por la antigua orden Praesul.",
    ["If you happen upon one in your travels bring it to me."] = "Si te encuentras con uno en tus viajes, tráemelo.",
    ["I'll keep my eyes open for any old books."] = "Estaré atento a cualquier libro antiguo.",
    ["[You need to bring a Praesul codex to Selene to unlock the Ruination curse.]"] = "[Debes llevar un códice Praesul a Selene para desbloquear la maldición de la ruina.]",
    ["Oh you mean a Praesul codex?"] = "Oh, ¿te refieres a un códice Praesul?",
    ["It just so happens I have one here."] = "Da la casualidad de que tengo uno aquí.",
    ["Hmm... What an odd ."] = "Hmm... Qué extraño.",
    ["Yeah... Odd..."] = "Sí... Extraño...",
    ["Unlock the ruination curse?"] = "¿Desbloquear la maldición de la ruina?",
    ["Selene reads a scripture from the codex, then tucks it away behind a shrine. You feel like you probably could've read it yourself."] = "Selene lee una escritura del códice y luego la guarda detrás de un santuario. Sientes que probablemente podrías haberlo leído tú mismo.",
    ["[You have unlocked the Ruination curse.]"] = "[Has desbloqueado la maldición de la ruina.]",
    ["On second thoughts, I'd rather keep hold of it a little longer."] = "Pensándolo bien, prefiero conservarlo un poco más.",
    ["Very well. Return to me if you change your mind."] = "Muy bien. Vuelve conmigo si cambias de opinión.",
    ["Any luck finding a Praesul codex?"] = "¿Tuviste suerte para encontrar un códice Praesul?",
    ["Afraid not."] = "Me temo que no.",
    ["I wish you luck finding one, my child."] = "Te deseo suerte para encontrar uno, hija mía.",
    ["Thanks."] = "Gracias.",
    ["I have one here!"] = "¡Tengo uno aquí!",
    ["Excellent, hand it to me, and I will teach you."] = "Excelente, dámelo y te lo enseñaré.",
    ["[You require level 95 Necromancy to unlock the Ruination curse.]"] = "[Necesitas el nivel 95 Necromancy para desbloquear la maldición de la ruina.]",
    ["Other."] = "Otro.",
    ["Hmm, perhaps we could take you through the prayers of another god?"] = "Hmm, ¿quizás podríamos explicarte las oraciones de otro dios?",
    ["Tell me, do you have a fundamental knowledge of the Guthixian prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones gutixianas?",
    ["Tell me, do you have a fundamental knowledge of the Zamorakian prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones zamorakianas?",
    ["Tell me, do you have a fundamental knowledge of the Kharazian prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones Kharazian?",
    ["Tell me, do you have a fundamental knowledge of the prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones?",
    ["Tell me, do you have a fundamental knowledge of the Godless prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones sin Dios?",
    ["Tell me, do you have a fundamental knowledge of the Bandosian prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones bandosianas?",
    ["Tell me, do you have a fundamental knowledge of the Menaphite prayers?"] = "Dime, ¿tienes un conocimiento fundamental de las oraciones menafitas?",
    ["I...uh, no. I don't"] = "Yo... eh, no. yo no",
    ["Return to me when you do. Perhaps we can teach each other."] = "Vuelve conmigo cuando lo hagas. Quizás podamos enseñarnos unos a otros.",
    ["Nevermind."] = "No importa.",
    ["Thanks for the chat, bye!"] = "¡Gracias por la charla, adiós!",
    ["Farewell, young one."] = "Adiós, joven.",
    ["I would not wish to bore you with the details, young one."] = "No quisiera aburrirte con los detalles, joven.",
    ["I'm interested, honestly."] = "Estoy interesado, sinceramente.",
    ["In life, I was Priestess of the Grey, a great honour among my people."] = "En vida, fui Sacerdotisa de los Grises, un gran honor entre mi pueblo.",
    ["I offered spiritual guidance through teachings of the gods, so that my people might better themselves."] = "Ofrecí guía espiritual a través de las enseñanzas de los dioses, para que mi pueblo pudiera mejorar.",
    ["Through Zamorak: I taught ambition, strength and change."] = "A través de Zamorak: enseñé ambición, fuerza y cambio.",
    ["Through Saradomin: loyalty, wisdom, self-control."] = "A través de Saradomin: lealtad, sabiduría, autocontrol.",
    ["Through Armadyl: altruism, equity, forgiveness..."] = "A través de Armadyl: altruismo, equidad, perdón...",
    ["I...I lost myself for a moment there."] = "Yo... me perdí por un momento allí.",
    ["You seem to be reliving it."] = "Parece que lo estás reviviendo.",
    ["Ironic. Now, run along, there will be plenty of time for gods later."] = "Irónico. Ahora, sigue adelante, que habrá mucho tiempo para los dioses más tarde.",
    ["*When talking to Selma at the Golden Palace throne room in Menaphos*"] = "*Al hablar con Selma en el salón del trono del Palacio Dorado en Menaphos*",
    ["The Pharaoh's ridiculous revisionism cannot continue! There has been a book burning every week, pilfering any text that dare utter an inkling of the throne's lineage! This is crazy!"] = "¡El ridículo revisionismo del Faraón no puede continuar! ¡Ha habido un libro quemado cada semana, robando cualquier texto que se atreva a expresar un indicio del linaje del trono! ¡Esto es una locura!",
    ["*After she has been 100% restored, there are many conversations the player can have with her regarding history.*"] = "*Después de que haya sido restaurada al 100%, hay muchas conversaciones que el player puede tener con ella sobre la historia.*",
    ["Greetings, traveller."] = "Saludos viajero.",
    ["Greetings, your majesty. May I ask you some questions?"] = "Saludos, majestad. ¿Puedo hacerte algunas preguntas?",
    ["Certainly, traveller, I have had not much contact with the sentient of late, you will no doubt remind me of the living and happier days."] = "Ciertamente, viajero, últimamente no he tenido mucho contacto con los seres sensibles, sin duda me recordarás aquellos días más vivos y felices.",
    ["Can I talk to you about Leela?"] = "¿Puedo hablarte de Leela?",
    ["**Player:** Can I talk to you about Leela?"] = "**Player:** ¿Puedo hablarte de Leela?",
    ["I have talked with Leela now, she should be treated with respect by those who wish to go far."] = "He hablado con Leela ahora, aquellos que desean llegar lejos deberían tratarla con respeto.",
    ["Why did she contact you and what is all this about respect?"] = "¿Por qué te contactó y qué es todo esto del respeto?",
    ["All will be revealed when the momentous times are come. Have patience and ancient wrongs will be righted."] = "Todo será revelado cuando lleguen los tiempos trascendentales. Tened paciencia y los antiguos errores serán corregidos.",
    ["Can I talk to you about the tomb robbers?"] = "¿Puedo hablarte de los ladrones de tumbas?",
    ["**Player:** Can I talk to you about the tomb robbers?"] = "**Player:** ¿Puedo hablarte sobre los ladrones de tumbas?",
    ["The ones who seek to steal are beset by my curses and become guardians. Irony is served as revenge. With the coming of my rebirth, the mortal, too, will protect me as befits my station."] = "Los que buscan robar son acosados por mis maldiciones y se convierten en guardianes. La ironía sirve como venganza. Con la llegada de mi renacimiento, los mortales también me protegerán como corresponde a mi posición.",
    ["Will I be cursed, too? I don't want to become a skeleton."] = "¿Yo también seré maldecido? No quiero convertirme en un esqueleto.",
    ["You were protected before you set foot in here, young one. Once I would have said an excess, now my silence may tell you more than my words once did."] = "Estabas protegido antes de poner un pie aquí, joven. Una vez habría dicho un exceso, ahora mi silencio puede decirles más de lo que alguna vez dijeron mis palabras.",
    ["Well that is a relief, at least, while still remaining confusing."] = "Bueno, eso es un alivio, al menos, aunque sigue siendo confuso.",
    ["Can I talk to you about history?"] = "¿Puedo hablarte de historia?",
    ["I will answer to the best of my ability, but note well that until reunited my faculties are dulled."] = "Responderé lo mejor que pueda, pero tenga en cuenta que hasta que no me reúna mis facultades se embotarán.",
    ["**Senliten:** What history would you like to know?"] = "**Senliten:** ¿Qué historia te gustaría saber?",
    ["Can you tell me about your lands and palaces?"] = "¿Puedes hablarme de tus tierras y palacios?",
    ["I was, in life, ruler of these lands from the plains of Uzer to the forests of Ullek. From the new settlement of Sophanem to the untamed hunting grounds of the Bedabin."] = "Yo fui, en vida, gobernante de estas tierras desde las llanuras de Uzer hasta los bosques de Ullek. Desde el nuevo asentamiento de Sophanem hasta los indómitos cotos de caza de Bedabin.",
    ["You talk of forests and plains, what kinds of lands were these?"] = "Hablas de bosques y llanuras, ¿qué tipo de tierras eran estas?",
    ["Lands rich in resources, granite, sandstone, timber and game. You seem surprised by this?"] = "Tierras ricas en recursos, granito, arenisca, madera y caza. ¿Pareces sorprendido por esto?",
    ["Well the lands are now mostly deserts and, although Sophanem is a town, the rest are ruins, I think."] = "Bueno, las tierras ahora son en su mayoría desiertos y, aunque Sophanem es un pueblo, el resto son ruinas, creo.",
    ["I fear our enemies must have fallen upon us after my demise. We were ever beset from the North."] = "Me temo que nuestros enemigos deben haber caído sobre nosotros después de mi muerte. Alguna vez nos acosaron desde el Norte.",
    ["Who would these enemies be, then?"] = "¿Quiénes serían entonces estos enemigos?",
    ["Dark forces of which you are happily not yet fully aware. Ever plotting in the dark lands of Morytania. During my reign, we defeated them temporarily with the aid of the Stern Judges."] = "Fuerzas oscuras de las que felizmente aún no eres plenamente consciente. Siempre conspirando en las tierras oscuras de Morytania. Durante mi reinado, los derrotamos temporalmente con la ayuda de los Jueces Severos.",
    ["Icthlarin be praised for his strength and wisdom."] = "Icthlarin sea alabado por su fuerza y sabiduría.",
    ["That vile creature Zaros and his minions. Ever plotting in the dark lands of Morytania. During my reign, we defeated him temporarily with the aid of the Stern Judges. Icthlarin be praised for his strength and wisdom."] = "Esa vil criatura Zaros y sus secuaces. Siempre conspirando en las tierras oscuras de Morytania. Durante mi reinado, lo derrotamos temporalmente con la ayuda de los Jueces Stern. Icthlarin sea alabado por su fuerza y ​​sabiduría.",
    ["I always thought that Zamorak was the root of evil?"] = "¿Siempre pensé que Zamorak era la raíz del mal?",
    ["I have never heard of this Zamorak you speak of, I assume he is a newcomer to this world."] = "Nunca había oído hablar de ese Zamorak del que hablas, supongo que es un recién llegado a este mundo.",
    ["Well, he's an immortal deity, I guess you'll find out about him soon enough. What was that about Stern Judges?"] = "Bueno, es una deidad inmortal, supongo que lo sabrás muy pronto. ¿Qué fue eso de Jueces Stern?",
    ["The Stern Judges, the faceless ones, are Icthlarin's workers in the lands of the living. They see all, wield great power and are reborn through death. What more fitting servants could he have?"] = "Los Jueces Stern, los sin rostro, son los trabajadores de Icthlarin en las tierras de los vivos. Lo ven todo, ejercen un gran poder y renacen a través de la muerte. ¿Qué sirvientes más apropiados podría tener?",
    ["What was that about rebirth through death, and why are they called faceless ones?"] = "¿Qué es eso del renacimiento a través de la muerte y por qué se les llama sin rostro?",
    ["The Judges have a central mystery in that one of their number must die in order to give life to the others. You can see how this appealed to Icthlarin."] = "Los Jueces tienen un misterio central: uno de ellos debe morir para dar vida a los demás. Puedes ver cómo esto atrajo a Icthlarin.",
    ["They can also take any form they choose, any face that is of use. The power to rule is much enhanced when one's advisers can speak with traitors using the face of another."] = "También pueden tomar cualquier forma que elijan, cualquier rostro que sea de utilidad. El poder de gobernar aumenta mucho cuando los asesores de uno pueden hablar con los traidores usando el the face de otro.",
    ["I don't doubt. Were these Judges minor deities, spirits or something else? It all seems a bit strange that I haven't heard of them before."] = "No lo dudo. ¿Eran estos jueces deidades menores, espíritus o algo más? Me parece un poco extraño que no haya oído hablar de ellos antes.",
    ["Like many of the servants of the gods, and indeed like the newcomer gods worshiped by most of the North, the Stern Judges were not native to this world."] = "Como muchos de los sirvientes de los dioses, y de hecho como los dioses recién llegados adorados por la mayor parte del Norte, los Jueces Severos no eran nativos de este mundo.",
    ["Icthlarin, in his wisdom, foresaw that he would need servants to do his bidding among mortals. He thus transported the faceless ones to these lands."] = "Icthlarin, en su sabiduría, previó que necesitaría sirvientes para cumplir sus órdenes entre los mortales. Así transportó a los sin rostro a estas tierras.",
    ["So, where are they now?"] = "Entonces, ¿dónde están ahora?",
    ["I am still recovering my knowledge in some areas and must admit that I do not know."] = "Todavía estoy recuperando mis conocimientos en algunas áreas y debo admitir que no lo sé.",
    ["Perhaps they were no longer needed and returned to their own plane. Perhaps they were freed by Icthlarin from their vows of obedience."] = "Quizás ya no fueron necesarios y regresaron a su propio avión. Quizás Icthlarin los liberó de sus votos de obediencia.",
    ["It is a subject I will look into in due time."] = "Es un tema que analizaré a su debido tiempo.",
    ["What history would you like to know?"] = "¿Qué historia te gustaría saber?",
    ["Can you tell me of religion?"] = "¿Puedes hablarme de religión?",
    ["As you will know, the chief deities of these lands are Tumeken, the sun that gives life and punishes, and Elidinis, the water that gives life and soothes."] = "Como sabrás, las deidades principales de estas tierras son Tumeken, el sol que da vida y castiga, y Elidinis, el agua que da vida y calma.",
    ["Icthlarin seems very popular, too."] = "Icthlarin también parece muy popular.",
    ["Icthlarin is indeed powerful and exerts his force in the mortal world. While he is the force that brings life through death, Amascut is she who brings death through life. Together they maintain the balance."] = "Icthlarin es realmente poderoso y ejerce su fuerza en el mundo mortal. Mientras él es la fuerza que trae la vida a través de la muerte, Amascut es ella quien trae la muerte a través de la vida. Juntos mantienen el equilibrio.",
    ["Amascut and Icthlarin seem to be in opposition now. Amascut is known as 'The Devourer' and didn't seem very friendly to me at all."] = "Amascut y Icthlarin parecen estar en oposición ahora. Amascut es conocido como 'El Devorador' y no me pareció nada amigable.",
    ["You may think this, yet mortals do not always see the purpose behind the ways of the immortal."] = "Puedes pensar esto, pero los mortales no siempre ven el propósito detrás de los caminos de los inmortales.",
    ["For all that death is undesirable to the living, we must die or the lands would be overrun with our children and our children's children."] = "Por mucho que la muerte sea indeseable para los vivos, debemos morir o las tierras serían invadidas por nuestros hijos y los hijos de nuestros hijos.",
    ["Do not judge the deathbringer lest she judge you."] = "No juzgues al portador de la muerte para que ella no te juzgue a ti.",
    ["What do you know of Scabaras?"] = "¿Qué sabes de Scabaras?",
    ["Scabaras cleanses mind and body through solitude. His followers are always deep thinkers, coming to conclusions tempered by lack of distractions."] = "Scabaras limpia la mente y el cuerpo a través de la soledad. Sus seguidores siempre son pensadores profundos y llegan a conclusiones atenuadas por la falta de distracciones.",
    ["If you wish for a life of study, you can do no better than to follow his ways."] = "Si deseas una vida de estudio, lo mejor que puedes hacer es seguir sus caminos.",
    ["By the example of the dung beetle we learn that the unpalatable may be transformed into life through proper attitudes."] = "Con el ejemplo del escarabajo pelotero aprendemos que lo desagradable puede transformarse en vida mediante actitudes adecuadas.",
    ["I think that, like Amascut, Scabaras has changed since you last were able to communicate with the world."] = "Creo que, al igual que Amascut, Scabaras ha cambiado desde la última vez que pudiste comunicarte con el mundo.",
    ["I sense things are not as they were, that there is dissent where there once was cooperation."] = "Siento que las cosas no son como antes, que hay disensión donde antes había cooperación.",
    ["The ways of the greater powers are mysterious, yet this is something that worries me greatly."] = "Los caminos de los poderes mayores son misteriosos, pero esto es algo que me preocupa mucho.",
    ["Perhaps the situation is able to be altered by you mortals, we will see in time."] = "Quizás la situación pueda ser alterada por ustedes, los mortales, lo veremos con el tiempo.",
    ["I am pretty sure I have annoyed Amascut and having a deity as an enemy isn't my idea of sensible. I would hope to be involved if ever you plan to return her to her old, friendly ways."] = "Estoy bastante seguro de que he molestado a Amascut y tener una deidad como enemiga no es mi idea de sensatez. Espero participar si alguna vez planeas devolverla a sus antiguas y amigables costumbres.",
    ["Friendly is not the phrase I would use to describe Amascut. You will be contacted, however, if ever I have plans to investigate this situation."] = "Amistoso no es la frase que usaría para describir a Amascut. Sin embargo, nos comunicaremos con usted si alguna vez tengo planes de investigar esta situación.",
    ["Can you tell me of your life and deeds?"] = "¿Puedes contarme de tu vida y tus hechos?",
    ["I lived in defence of my realm, as all rulers do. I provided an heir in my son Osmumten, as a good ruler does, and guaranteed the continuation of both the realm and the bloodline."] = "Viví en defensa de mi reino, como hacen todos los gobernantes. Proporcioné un heredero a mi hijo Osmumten, como hace un buen gobernante, y garanticé la continuación tanto del reino como del linaje.",
    ["Were there any notable occurrences in your reign?"] = "¿Hubo algún acontecimiento notable durante su reinado?",
    ["I pride myself that no notable occurrences occurred. This mastaba, however, my burial place and testament to my power; this was a thing not seen before."] = "Me enorgullezco de que no hayan ocurrido sucesos notables. Esta mastaba, sin embargo, es mi lugar de sepultura y testimonio de mi poder; Esto era algo que no se había visto antes.",
    ["So this is the first pyramid? Do you know that they are quite common now?"] = "¿Entonces esta es la primera pirámide? ¿Sabes que son bastante comunes ahora?",
    ["That is gratifying, imitation is flattery indeed. It is disappointing, however, that my creation of such a thing is blurred by these later copies."] = "Eso es gratificante, la imitación es realmente un halago. Es decepcionante, sin embargo, que mi creación de tal cosa quede desdibujada por estas copias posteriores.",
    ["Well the others are somewhat differently shaped, so you are distinguished by that, at least. Is there any other legacy you are proud of?"] = "Bueno, los demás tienen formas algo diferentes, así que al menos tú te distingues por eso. ¿Hay algún otro legado del que estés orgulloso?",
    ["I mention my bloodline, the power that is transmitted to this day. Interruptions and diversions are inflicted upon the true flow of power but you are righting the course, albeit unwittingly."] = "Menciono mi linaje, el poder que se transmite hasta el día de hoy. Se infligen interrupciones y desvíos al verdadero flujo de poder, pero ustedes están enderezando el rumbo, aunque sea sin darse cuenta.",
    ["I see, or rather I see to the extent that you seem to wish me to."] = "Ya veo, o más bien veo en la medida en que pareces desearlo.",
    ["Can you tell me of life after death?"] = "¿Puedes hablarme de la vida después de la muerte?",
    ["Icthlarin takes those who die into a new life. Whether this is new life after death or new life instead of death is something only he can decide."] = "Icthlarin lleva a aquellos que mueren a una nueva vida. Si se trata de una nueva vida después de la muerte o de una nueva vida en lugar de la muerte es algo que sólo él puede decidir.",
    ["Why were you split up when you died, though? It all seems rather odd to me."] = "¿Pero por qué se separaron cuando murieron? Todo me parece bastante extraño.",
    ["In order to enter the afterlife in a full existence and not be reborn as a mortal, the deceased must be both mentally prepared and physically treated in the correct fashion."] = "Para entrar en el más allá con una existencia plena y no renacer como un mortal, el difunto debe estar preparado mentalmente y tratado físicamente de la manera correcta.",
    ["As a member of the royal bloodline, I was prepared mentally and destined to be worthy."] = "Como miembro del linaje real, estaba preparado mentalmente y destinado a ser digno.",
    ["What effect does reassembling you have?"] = "¿Qué efecto tiene volver a montarlo?",
    ["As you will have realised, I am merely being returned to my proper state of burial. It is sometimes the case, for wise rulers such as I, to make themselves available to their descendants."] = "Como te habrás dado cuenta, simplemente estoy siendo devuelto a mi estado adecuado de entierro. A veces sucede que gobernantes sabios como yo se ponen a disposición de sus descendientes.",
    ["By reassembling my burial place you will make it possible for me to contact the world of the living, even to talk to those not directly related such as yourself."] = "Al reorganizar mi lugar de entierro, me permitirás contactar con el mundo de los vivos, incluso hablar con aquellos que no están directamente relacionados, como tú.",
    ["Who performs these rituals?"] = "¿Quién realiza estos rituales?",
    ["A priest of Icthlarin is trained from their earliest days to be adept in these operations, which they will only perform upon the devout and deserving. In most cases, of course, simple burial suffices. Most are not worthy enough to enter the afterlife."] = "Un sacerdote de Icthlarin es entrenado desde sus primeros días para ser experto en estas operaciones, que solo realizarán a los devotos y merecedores. En la mayoría de los casos, por supuesto, basta con un simple entierro. La mayoría no son lo suficientemente dignos de entrar al más allá.",
    ["What if mistakes are made by the priest?"] = "¿Qué pasa si el sacerdote comete errores?",
    ["The process is more often twisted rather than mistakes being made - after all, Icthlarin is a deity and thus rather able to make good any minor mistakes by his devout followers."] = "El proceso suele ser retorcido en lugar de cometer errores; después de todo, Icthlarin es una deidad y, por lo tanto, es bastante capaz de corregir cualquier error menor de sus devotos seguidores.",
    ["Twisted? What sort of effect would this have?"] = "¿Retorcido? ¿Qué tipo de efecto tendría esto?",
    ["If certain parts of the separation process are performed out of order or upon a living victim, the victim will be caught in a state between living and death. They may also be bound to the will of a person who controls certain parts of the ritual or physical portions of the one so afflicted. Such things are not good to discuss without good reason however."] = "Si ciertas partes del proceso de separación se realizan fuera de orden o sobre una víctima viva, la víctima quedará atrapada en un estado entre la vida y la muerte. También pueden estar sujetos a la voluntad de una persona que controla ciertas partes del ritual o partes físicas del afectado. Sin embargo, no es bueno discutir estas cosas sin una buena razón.",
    ["Quite so, it sounds horrible."] = "Así es, suena horrible.",
    ["Horrible, maybe; although the Stern Judges were masters of the art. Sometimes foul deeds must be done in the pursuit of further good."] = "Horrible, tal vez; aunque los jueces severos eran maestros en el arte. A veces es necesario cometer malas acciones en aras de un bien mayor.",
    ["That's enough history for now."] = "Ya es suficiente historia por ahora.",
    ["Can we talk about quests again?"] = "¿Podemos hablar de misiones otra vez?",
    ["Talk about Dealing with Scabaras."] = "Hable sobre cómo lidiar con Scabaras.",
    ["**Player:** Can I talk about the Scabarites?"] = "**Player:** ¿Puedo hablar de los Scabarites?",
    ["Certainly."] = "Por supuesto.",
    ["Why do you think the Devourer used the Scabarites to attack?"] = "¿Por qué crees que el Devorador usó a los Scabarites para atacar?",
    ["Why, you answered the question from your own lips. She wanted to 'burn Sophanem to the ground'."] = "Bueno, respondiste la pregunta con tus propios labios. Quería \"quemar a Sophanem hasta los cimientos\".",
    ["Ah right, yes, I forgot."] = "Ah, claro, sí, lo olvidé.",
    ["But..."] = "Pero...",
    ["Ah, you are sceptical. Good, yes, very good. I see why Leela respects you. The Scabarites of my day were mainly scholars and intellectuals - the shy, retiring types."] = "Ah, eres escéptico. Bueno, sí, muy bueno. Veo por qué Leela te respeta. Los scabaritas de mi época eran principalmente eruditos e intelectuales, del tipo tímido y retraído.",
    ["They were not warriors that could be used to overthrow a city. Perhaps they have changed..."] = "No eran guerreros que pudieran usarse para derrocar una ciudad. Quizás hayan cambiado...",
    ["You have to see; they gave up their isolation. There is importance to this. Isolation is the one ideal a Scabarite holds above everything else. Know this; in the attack, the Scabarites lost more than their enemies."] = "Tienes que ver; abandonaron su aislamiento. Hay importancia en esto. El aislamiento es el único ideal que un scabarita sostiene por encima de todo lo demás. Sepa esto; En el ataque, los scabaritas perdieron más que sus enemigos.",
    ["So, Amascut meant to hurt the Scabarites?"] = "Entonces, ¿Amascut tenía la intención de dañar a los scabaritas?",
    ["Perhaps, perhaps. Let us hope, since the alternative is...surely not..."] = "Quizás, quizás. Esperemos, ya que la alternativa es...seguramente no...",
    ["Talk about Do No Evil."] = "Habla de No hacer el mal.",
    ["Can I be of service?"] = "¿Puedo ser de ayuda?",
    ["Not at this moment; you need to learn more of the desert, first."] = "No en este momento; Primero necesitas aprender más sobre el desierto.",
    ["Talk about Crocodile Tears."] = "Habla sobre las lágrimas de Crocodile.",
    ["Greetings, Player."] = "Saludos, Player.",
    ["Talk about Dealing With Scabaras."] = "Hable sobre cómo lidiar con Scabaras.",
    ["Can we talk about Apmeken?"] = "¿Podemos hablar de Apmeken?",
    ["Apmeken is only the beginning. In restoring her, you have done the desert a great service, but there is still more to be done. Amascut's deeds, I fear, are widespread. No doubt her actions have bred more evil."] = "Apmeken es sólo el comienzo. Al restaurarla, habéis prestado un gran servicio al desierto, pero aún queda mucho por hacer. Me temo que los actos de Amascut están muy extendidos. Sin duda, sus acciones han engendrado más maldad.",
    ["I don't understand."] = "No entiendo.",
    ["The actions of gods are mirrored in the mortal realm. Amascut's actions heralded an era of cruelty, and mortals have adopted her unseemly behaviour towards sentient beings."] = "Las acciones de los dioses se reflejan en el reino de los mortales. Las acciones de Amascut anunciaron una era de crueldad, y los mortales han adoptado su comportamiento indecoroso hacia los seres sintientes.",
    ["We must tread carefully, for we do not have just Amascut to contend with. Those who have benefitted from her storm of destruction will try to stop us."] = "Debemos andar con cuidado, porque no solo tenemos que lidiar con Amascut. Aquellos que se han beneficiado de su tormenta de destrucción intentarán detenernos.",
    ["I spoke to Apmeken after restoring her. She didn't act as I had expected."] = "Hablé con Apmeken después de restaurarla. Ella no actuó como esperaba.",
    ["How so?"] = "¿Cómo es eso?",
    ["Jex and the wise monkeys spoke of her as mischievous and cunning, but she seemed almost sombre."] = "Jex y los monos sabios hablaban de ella como traviesa y astuta, pero parecía casi sombría.",
    ["Interesting. Gods suffer and feel pleasure as you do; their feelings are infinitely refined, but the general sentiments are one and the same."] = "Interesante. Los dioses sufren y sienten placer como tú; sus sentimientos son infinitamente refinados, pero los sentimientos generales son uno y el mismo.",
    ["She had a harrowing experience that will leave its mark. In time, we may see a return to form. Let us hope."] = "Tuvo una experiencia desgarradora que dejará huella. Con el tiempo, es posible que veamos un regreso a la forma. Esperemos.",
    ["Thank you for setting things right with Crondis. I can already feel her modesty returning to the hearts of the Kharidian people."] = "Gracias por arreglar las cosas con Crondis. Ya puedo sentir que su modestia regresa a los corazones del pueblo Kharidian.",
    ["Talk about Our Man in the North."] = "Habla de Nuestro Hombre del Norte.",
    ["Osman admitted it - he says he only worked with Jabari for the greater good, to gain undeniable proof of his claim so that he could cement peace between Menaphos and Al Kharid."] = "Osman lo admitió: dice que solo trabajó con Jabari por el bien común, para obtener pruebas innegables de su reclamo y poder cimentar la paz entre Menaphos y Al Kharid.",
    ["I cannot believe he would stoop so low. He has been spymaster so long, he has forgotten how to act."] = "No puedo creer que haya caído tan bajo. Ha sido el maestro de espías durante tanto tiempo que ha olvidado cómo actuar.",
    ["How can he become Pharaoh with such thoughts in his mind, such willingness to compromise his morals? I don't know if I can forgive him for this..."] = "¿Cómo puede convertirse en faraón con esos pensamientos en la mente y tanta voluntad de comprometer su moral? No sé si puedo perdonarlo por esto...",
    ["Worry not, Leela. Osman knows he must come to see me before he can progress his plans any further. We shall get through to him."] = "No te preocupes, Leela. Osman sabe que debe venir a verme antes de poder avanzar con sus planes. Nos comunicaremos con él.",
    ["I don't serve outsiders. Sorry."] = "No atiendo a forasteros. Lo siento.",
    ["What brings you here, adventurer? Will you assist me?"] = "¿Qué te trae por aquí, aventurero? ¿Me ayudarás?",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["You've done well."] = "Lo has hecho bien.",
    ["Not right now."] = "No en este momento.",
    ["Those pesky [monster] are eating my crops!"] = "¡Esos molestos [monster] se están comiendo mis cultivos!",
    ["Well, that is a problem. Anything I can do to help?"] = "Bueno, eso es un problema. ¿Puedo hacer algo para ayudar?",
    ["Yes, I have a plan."] = "Sí, tengo un plan.",
    ["I believe if we coat the crops with some sort of disgusting mixture it will deter them."] = "Creo que si cubrimos los cultivos con algún tipo de mezcla desagradable, los disuadiremos.",
    ["Yeah, that seems reasonable."] = "Sí, eso parece razonable.",
    ["First of all I need [number] of [item]. Could you get these for me?"] = "Primero que nada necesito [número] de [item]. ¿Podrías conseguirlos para mí?",
    ["Where could I find [item]?"] = "¿Dónde puedo encontrar [item]?",
    ["**Sennefer:** [Herb] seeds are often dropped by monsters, or they can be procured from master farmers across Gielinor. Hurry, though, before all my crops are gone."] = "**Sennefer:** Las semillas de [Herb] a menudo las dejan los monstruos, o se pueden obtener de maestros agricultores en Gielinor. Pero date prisa antes de que se acaben todas mis cosechas.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Have you got the [number] of [item]? ([number] remaining)"] = "¿Tienes el [número] de [item]? ([número] restantes)",
    ["Not yet. Where could I find [item] again?"] = "Todavía no. ¿Dónde podría encontrar [item] nuevamente?",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Number of [item] given to Sennefer ([number]/[number])"] = "Número de [item] dado a Sennefer ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["Yeah, got the [item]!"] = "¡Sí, tengo el [item]!",
    ["Excellent, the [item] will make a great base for the concoction!"] = "¡Excelente, el [item] será una excelente base para el brebaje!",
    ["Now, let's think about what we will need next."] = "Ahora, pensemos en lo que necesitaremos a continuación.",
    ["What we need is fuel for the furnace."] = "Lo que necesitamos es combustible para el horno.",
    ["How about [item]?"] = "¿Qué tal [item]?",
    ["Perfect! I think if you get me [number] of [item] we are good to go."] = "¡Perfecto! Creo que si me consigues [número] de [item] estaremos listos.",
    ["Alright."] = "Muy bien.",
    ["Do you know where I could get [item]?"] = "¿Sabes dónde puedo conseguir [item]?",
    ["**Sennefer:** You can mine coal north of Al Kharid.."] = "**Sennefer:** Puedes extraer carbón al norte de Al Kharid.",
    ["No, sorry."] = "No, lo siento.",
    ["Have you found [number] of [item] yet? ([number] remaining)"] = "¿Ya has encontrado [número] de [item]? ([número] restantes)",
    ["Nope, where should I be looking for the [item]?"] = "No, ¿dónde debería buscar el [item]?",
    ["I have the [item]."] = "Tengo el [item].",
    ["Well, now we can finish our deterrent."] = "Bueno, ahora podemos terminar nuestro elemento disuasorio.",
    ["Is something wrong?"] = "¿Pasa algo?",
    ["While you were gone, the [monster] came back and ate even more of my crops!."] = "Mientras no estabas, ¡el [monster] regresó y se comió aún más de mis cultivos!",
    ["This deterrent is not going to be enough! I need you to send a message that nobody messes with my crops!"] = "¡Este elemento disuasorio no será suficiente! ¡Necesito que envíes un mensaje de que nadie se mete con mis cultivos!",
    ["Uh… Well, we haven't tried the det-"] = "Uh... Bueno, no hemos probado el detector.",
    ["Forget the deterrent! I need you to kill [number] of [monster] for me!"] = "¡Olvídate del elemento disuasorio! ¡Necesito que mates a [número] de [monster] por mí!",
    ["Sure."] = "Claro.",
    ["What do you know about [monster]?"] = "¿Qué sabes sobre [monster]?",
    ["**Sennefer:** Other than the fact that they are crop-stealing fiends? They can be found out to the east in the desert."] = "**Sennefer:** ¿Aparte del hecho de que son demonios ladrones de cosechas? Se pueden encontrar al este en el desierto.",
    ["Nope."] = "No.",
    ["Did you deal with the [number] of [monster]? ([number] remaining)"] = "¿Trataste con el [número] de [monster]? ([número] restantes)",
    ["Not yet. Could you point me in the direction of some [monster]?"] = "Todavía no. ¿Podrías indicarme la dirección de algún [monster]?",
    ["Did you deal with the [number] of [monster]? (0 remaining)"] = "¿Trataste con el [número] de [monster]? (0 restante)",
    ["Yes, your crops should be safe now."] = "Sí, sus cultivos deberían estar seguros ahora.",
    ["At last, my crops are safe!"] = "¡Por fin mis cultivos están a salvo!",
    ["So…"] = "Entonces…",
    ["I don't suppose you want to buy some [first item] and [second item]?"] = "Supongo que no querrás comprar [first item] y [second item].",
    ["I've had a brilliant idea for a new product I can sell in the city. It is so brilliant that it would be a bad move to share with you what it is...yet."] = "He tenido una idea brillante para un nuevo producto que puedo vender en la ciudad. Es tan brillante que sería una mala decisión compartir con ustedes lo que es... todavía.",
    ["I could tell you if you helped me out by sourcing what I'll need to create my invention!"] = "¡Te lo podría decir si me ayudases a conseguir lo que necesitaré para crear mi invento!",
    ["What do you think? Could you please bring me [number] [item]?"] = "¿Qué opinas? ¿Podrías traerme [número] [item]?",
    ["Sure thing."] = "Claro.",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["How are you getting along with getting me [number] [item]? ([number] remaining)"] = "¿Cómo te llevas consiguiendome [número] [item]? ([número] restantes)",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["Just the ticket!"] = "¡Solo el boleto!",
    ["Now I have the base items, I need to add a few more components to complete my product!"] = "Ahora que tengo los artículos básicos, ¡necesito agregar algunos componentes más para completar mi producto!",
    ["Let me see... Yes, yes, that's what I would need!"] = "Déjame ver... Sí, sí, ¡eso es lo que necesitaría!",
    ["What's that?"] = "¿Qué es eso?",
    ["I would need...some [item]."] = "Necesitaría... algo de [item].",
    ["Some [item]? But why?"] = "¿Algunos [item]? ¿Pero por qué?",
    ["And reveal my trade secrets? No, Player, you won't get that knowledge out of me!"] = "¿Y revelar mis secretos comerciales? No, Player, ¡no me sacarás ese conocimiento!",
    ["Don't worry. If you get me [number] [item], then I will make sure to reimburse you for your time."] = "No te preocupes. Si me consigues [número] [item], me aseguraré de reembolsarte tu tiempo.",
    ["Okay, then."] = "Bien, entonces.",
    ["How goes your quest of finding me [number] [item], Player? ([number] remaining)"] = "¿Cómo va tu búsqueda para encontrarme [número] [item], Player? ([número] restantes)",
    ["There. Your [item]."] = "Ahí. Tu [item].",
    ["My project is nearing completion! You've been so helpful!"] = "¡Mi proyecto está a punto de completarse! ¡Has sido de gran ayuda!",
    ["My invention is almost ready!"] = "¡Mi invento está casi listo!",
    ["There is one more type of component I need to finish this amazing invention of mine!"] = "¡Hay un tipo más de componente que necesito para terminar este increíble invento mío!",
    ["Please do tell..."] = "Por favor, dímelo...",
    ["It is none other than...[number] [item]."] = "No es otro que...[número] [item].",
    ["If you do me this last favour, I will be rich! And you can reap the benefits, too!"] = "¡Si me haces este último favor, seré rico! ¡Y usted también puede aprovechar los beneficios!",
    ["Sure, fine, whatever."] = "Claro, está bien, lo que sea.",
    ["Ah, Player! Please tell me you have managed to acquire [number] [item]? ([number] remaining)"] = "¡Ah, Player! Por favor, dime que has logrado adquirir [número] [item]. ([número] restantes)",
    ["Brilliant! As brilliant as my invention, I must say! Time to put it together!"] = "¡Brillante! ¡Tan brillante como mi invento, debo decir! ¡Es hora de armarlo!",
    ["So... What's that amazing invention you came up with, then?"] = "Entonces... ¿Cuál es ese increíble invento que se te ocurrió entonces?",
    ["Ah, the fruit of my hard labour, the apple of my eyes, my newest creation, the thing that will revolutionise the life of adventurers around the world...for which I have yet to come up with a good name for!"] = "Ah, el fruto de mi arduo trabajo, la niña de mis ojos, mi nueva creación, lo que revolucionará la vida de los aventureros de todo el mundo... ¡para lo cual todavía tengo que encontrar un buen nombre!",
    ["Wait, it's really not wise to talk to you about it until the prototype is fully working... I cannot risk having you steal my idea and getting it manufactured somewhere else for less."] = "Espera, realmente no es prudente hablar contigo sobre esto hasta que el prototipo esté funcionando completamente... No puedo arriesgarme a que robes mi idea y la fabriquen en otro lugar por menos dinero.",
    ["Thanks for the vote of confidence."] = "Gracias por el voto de confianza.",
    ["I hope I haven't offended you! Please, Player, accept this reward as token of my appreciation."] = "¡Espero no haberte ofendido! Por favor, Player, acepta esta recompensa como muestra de mi agradecimiento.",
    ["Greetings! Welcome to Tuai Leit."] = "¡Saludos! Bienvenidos a Tuai Leit.",
    ["Thanks. What is this place?"] = "Gracias. ¿Qué es este lugar?",
    ["This is our humble centre of learning. All manner of beings come here to study, to better their knowledge of the natural world and the spiritual world."] = "Este es nuestro humilde centro de aprendizaje. Todo tipo de seres vienen aquí para estudiar, para mejorar su conocimiento del mundo natural y del mundo espiritual.",
    ["Somewhere, something incredible is always waiting to be known."] = "En algún lugar, siempre hay algo increíble esperando ser conocido.",
    ["Thank you for your assistance in trying to cure my friend."] = "Gracias por tu ayuda para intentar curar a mi amigo.",
    ["Explain the situation."] = "Explica la situación.",
    ["We convinced the original necromancer to remove her curse not only from him, but many others who were affected by it. She did so by tearing a piece of paper that was stuck on a jiangshi's forehead."] = "Convencimos a la nigromante original para que eliminara su maldición no solo sobre él, sino también sobre muchos otros que se vieron afectados por ella. Lo hizo rasgando un trozo de papel que estaba pegado en la frente de un jiangshi.",
    ["Poppycock! What drivel. I'm sure there must be some sort of physical or spiritual explanation behind all of this superstitious mystical twaddle."] = "¡Poppycock! Qué tontería. Estoy seguro de que debe haber algún tipo de explicación física o espiritual detrás de toda esta tontería mística y supersticiosa.",
    ["Next you'll be trying to convince me of the benefits of homeopathic medicines, as if tigers' dangly bits ever did anyone any good."] = "A continuación intentarás convencerme de los beneficios de los medicamentos homeopáticos, como si los pedazos colgantes de los tigres alguna vez hicieran algún bien a alguien.",
    ["Excuse my disbelief, though - I am most pleased that your friend has recovered."] = "Disculpe mi incredulidad, pero estoy muy contento de que su amigo se haya recuperado.",
    ["Is there anything for me to learn?"] = "¿Hay algo que pueda aprender?",
    ["Is there anything left for me to learn?"] = "¿Me queda algo por aprender?",
    ["That's incredible! There's nothing left for you to learn."] = "¡Eso es increíble! No te queda nada por aprender.",
    ["I've told you before that you have nothing left to learn. Why would you ask me again?"] = "Ya te dije antes que no te queda nada que aprender. ¿Por qué me lo preguntarías de nuevo?",
    ["You have unlocked the '' title!|colour=#d7f388}}"] = "¡Has desbloqueado el título ''!|color=#d7f388}}",
    ["This is surprising. I didn't know there was anyone else out there that knew this much."] = "Esto es sorprendente. No sabía que había alguien más que supiera tanto.",
    ["Alright. You look like you could help."] = "Muy bien. Parece que podrías ayudar.",
    ["What with?"] = "¿Con qué?",
    ["I'm trying to perform a study on some wandering spirits, but I don't have the budget to travel much in search of them."] = "Estoy intentando realizar un estudio sobre algunos espíritus errantes, pero no tengo presupuesto para viajar mucho en busca de ellos.",
    ["You seem the inquisitive type, plus you have your own ship from what I can gather."] = "Pareces del tipo curioso, además tienes tu propio barco, por lo que puedo entender.",
    ["Okay, how would I help, and what's in it for me?"] = "Bien, ¿cómo puedo ayudar y qué gano yo con esto?",
    ["I'm studying entities I call kami spirits - they're these floating spectral things that appear to be wearing masks."] = "Estoy estudiando entidades a las que llamo espíritus kami: son cosas espectrales flotantes que parecen llevar máscaras.",
    ["For each new specimen you bring me, I can impart some of my knowledge to you."] = "Por cada nuevo espécimen que me traigas, puedo impartirte algunos de mis conocimientos.",
    ["And if you can help me collect one of each type, I'm sure we can work out something more rewarding."] = "Y si puedes ayudarme a recolectar uno de cada tipo, estoy seguro de que podemos encontrar algo más gratificante.",
    ["How do I catch them?"] = "¿Cómo los atrapo?",
    ["You'll need a jar of some sort, and probably a net too. Although they are spirits, their masks make them easy to catch."] = "Necesitarás algún tipo de frasco y probablemente también una red. Aunque son espíritus, sus máscaras los hacen fáciles de atrapar.",
    ["Would an impling jar work?"] = "¿Funcionaría un frasco implícito?",
    ["I don't know; what's an impling? Maybe just give that a try and you tell me."] = "No lo sé; ¿Qué es una implicación? Tal vez inténtalo y me cuentas.",
    ["Will do. How many types I hunting for?"] = "Lo haré. ¿Cuántos tipos estoy buscando?",
    ["Honestly, I couldn't tell you. Maybe you could keep track of them in a journal or something. What I do know is that there are two kinds."] = "Sinceramente, no sabría decírtelo. Tal vez podrías realizar un seguimiento de ellos en un diario o algo así. Lo que sí sé es que hay dos tipos.",
    ["Some you will only find on populated islands - those are quite common and easy to catch. They're used to living creatures and less skittish."] = "Algunos solo los encontrarás en islas pobladas; son bastante comunes y fáciles de capturar. Están acostumbrados a los seres vivos y son menos asustadizos.",
    ["And then there are those only found in the uncharted islands - they'll be more difficult to catch. I call them orokami to differentiate them, but they're basically the same as bakami."] = "Y luego están los que solo se encuentran en las islas inexploradas; serán más difíciles de capturar. Los llamo orokami para diferenciarlos, pero básicamente son iguales que los bakami.",
    ["Any questions?"] = "¿Alguna pregunta?",
    ["Any questions about kami?"] = "¿Alguna pregunta sobre kami?",
    ["What are kami spirits?"] = "¿Qué son los espíritus kami?",
    ["What does 'bakami' mean?"] = "¿Qué significa 'bakami'?",
    ["No questions here."] = "No hay preguntas aquí.",
    ["That's what I'm trying to figure out. So far, I've determined that they are spirits of some kind."] = "Eso es lo que estoy tratando de descubrir. Hasta ahora, he determinado que son espíritus de algún tipo.",
    ["Considering their tendency to be animalistic, my leading theory is that they are the wandering spirits of deceased sea monsters."] = "Considerando su tendencia a ser animales, mi teoría principal es que son los espíritus errantes de monstruos marinos fallecidos.",
    ["Are they all creatures of the sea, though?"] = "¿Son todas criaturas del mar?",
    ["From what I've witnessed so far, no. There are bird-like ones, and mammals, and then some really strange ones, and mammals, and then there are some really strange ones too."] = "Por lo que he presenciado hasta ahora, no. Los hay parecidos a pájaros y mamíferos, y luego algunos realmente extraños, y mamíferos, y luego hay algunos realmente extraños también.",
    ["You know, though, that there are more 'monsters' in the Wushanko Isles than live in the sea. My theory is that they are all connected somehow."] = "Sin embargo, sabes que hay más \"monstruos\" en las islas Wushanko que los que viven en el mar. Mi teoría es que todos están conectados de alguna manera.",
    ["Though it's true, we do have a lot of water here, so perhaps that's why we predominantly find sea monsters."] = "Aunque es cierto, aquí tenemos mucha agua, así que quizás por eso encontramos predominantemente monstruos marinos.",
    ["Well, that's just my name for them. It's sort of a joke, but I discovered them, so I got to name them!"] = "Bueno, ese es solo mi nombre para ellos. Es una especie de broma, pero los descubrí, ¡así que tengo que nombrarlos!",
    ["You might well already know the word 'kami' - it's sort of our word for...well, it can mean a lot of things - spirits, gods - but we mainly use it when referring to sea monsters."] = "Quizás ya conozcas la palabra 'kami'; es una especie de palabra que significa... bueno, puede significar muchas cosas: espíritus, dioses, pero la usamos principalmente cuando nos referimos a monstruos marinos.",
    ["But the word 'baka', that again can have many meanings - idiot, silly - but I see it in this case being closer to 'mischievous'."] = "Pero la palabra 'baka', que nuevamente puede tener muchos significados - idiota, tonto - pero la veo en este caso más cercana a 'travieso'.",
    ["So, 'bakami' means 'idiot gods'?"] = "Entonces, ¿'bakami' significa 'dioses idiotas'?",
    ["That's losing the nuance. It's more like 'mischievous spirits of sea monsters'...though they aren't all sea monsters, and some seem friendly, others dangerous. Mostly, they're quite benign, though."] = "Eso es perder el matiz. Es más como 'espíritus traviesos de monstruos marinos'... aunque no todos son monstruos marinos, y algunos parecen amigables, otros peligrosos. Sin embargo, en su mayoría son bastante benignos.",
    ["Orokami' means much the same thing, though there is a slight difference. Whatever bakami are, orokami are the same but 'more' in some way."] = "Orokami' significa prácticamente lo mismo, aunque hay una ligera diferencia. Sean lo que sean los bakami, los orokami son iguales pero \"más\" de alguna manera.",
    ["Can I toggle my kami spirit reward?"] = "¿Puedo alternar mi recompensa espiritual kami?",
    ["Which would you prefer from catching kami?"] = "¿Cuál preferirías de atrapar a kami?",
    ["Triple experience."] = "Triple experiencia.",
    ["Alright. From now on, any kami spirit you catch, however you catch 'em, will earn you triple the usual experience!"] = "Muy bien. De ahora en adelante, cualquier espíritu kami que captures, como sea que lo captures, ¡te otorgará el triple de experiencia habitual!",
    ["Double loot."] = "Doble botín.",
    ["Alright. From now on, any kami spirit you catch barehanded will earn you twice the normal loot! It won't work for opening kami jars, though. That'd be cheating."] = "Muy bien. ¡A partir de ahora, cualquier espíritu kami que atrapes con las manos desnudas te otorgará el doble del botín normal! Sin embargo, no funcionará para abrir tarros kami. Eso sería hacer trampa.",
    ["Alright! You've caught one of each type of kami spirit for me. Many thanks!"] = "¡Muy bien! Has atrapado uno de cada tipo de espíritu kami para mí. ¡Muchas gracias!",
    ["So, I can share some of my study with you. Would you rather gain more experience when catching kami or more loot?"] = "Entonces, puedo compartir algunos de mis estudios contigo. ¿Preferirías ganar más experiencia al atrapar kami o más botín?",
    ["If you ever change your mind about the triple experience, double loot thing, come talk to me."] = "Si alguna vez cambias de opinión sobre la experiencia triple y el doble botín, ven a hablar conmigo.",
    ["Can you solve this for me?"] = "¿Puedes resolver esto por mí?",
    ["[Sensei Seaworth has given you a Towers puzzle scroll!]"] = "[¡Sensei Seaworth te ha regalado un pergamino de rompecabezas de Torres!]",
    ["Nope, that's not completed yet."] = "No, eso aún no está completo.",
    ["Excellent, here is your reward!"] = "¡Excelente, aquí tienes tu recompensa!",
    ["[You've found another clue!]"] = "[¡Has encontrado otra pista!]",
    ["Don't worry about me, this happens all the time."] = "No te preocupes por mí, esto pasa todo el tiempo.",
    ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
    ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
    ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
    ["Good to see you again, Player."] = "Me alegro de verte de nuevo, Player.",
    ["What happened to out-doing Vulcan?"] = "¿Qué pasó con superar a Vulcan?",
    ["Oh, I decided to let him have his glory for now. I know I easily have the experience to out-do him after our excursion."] = "Oh, decidí dejarle tener su gloria por ahora. Sé que fácilmente tengo la experiencia para superarlo después de nuestra excursión.",
    ["In the mean time, I'm running the fire-breathing here. Let me give you a rundown of what to do."] = "Mientras tanto, yo me encargo de escupir fuego. Déjame darte un resumen de qué hacer.",
    ["Do you want to start your fire-breathing performance?"] = "¿Quieres comenzar tu actuación de escupir fuego?",
    ["Could you explain it to me again?"] = "¿Podrías explicármelo de nuevo?",
    ["If I must."] = "Si es necesario.",
    ["**Sera:** I've made up some solutions that will enable you to breathe different colour flames."] = "**Sera:** He inventado algunas soluciones que te permitirán respirar llamas de diferentes colores.",
    ["You can breathe whichever you like, but some of the solutions are harder than others; I've written guidelines on the bottles."] = "Puedes respirar lo que quieras, pero algunas de las soluciones son más difíciles que otras; He escrito pautas en las botellas.",
    ["You've got as much time as you like, but you can only perform 6 colours. At the end, I'll let you know how you've done."] = "Tienes todo el tiempo que quieras, pero solo puedes realizar 6 colores. Al final te contaré cómo te ha ido.",
    ["If you can't take it, and want to finish early, just speak to me. You can only do one performance at a time."] = "Si no puedes soportarlo y quieres terminar temprano, háblame. Sólo puedes hacer una actuación a la vez.",
    ["*(If audience reaction is toggled off)* Can you tell me how I'm doing?"] = "*(Si la reacción de la audiencia está desactivada)* ¿Puedes decirme cómo me va?",
    ["*(If audience reaction is toggled on)* Could you stop telling me how I'm doing?"] = "*(Si la reacción de la audiencia está activada)* ¿Podrías dejar de decirme cómo me va?",
    ["Of course! They won't stop talking to you, but they'll stop telling you if they think you're being repetitive or not."] = "¡Por supuesto! No dejarán de hablarte, pero dejarán de decirte si creen que estás siendo repetitivo o no.",
    ["Do you still want me to stop them?"] = "¿Todavía quieres que los detenga?",
    ["You've already done your fire-breathing performance this week. Speak to the ringmaster to see if there's anything else you can do."] = "Ya hiciste tu actuación de escupir fuego esta semana. Habla con el maestro de ceremonias para ver si hay algo más que puedas hacer.",
    ["If you want to end your performance, just tell me or walk away from the performance area."] = "Si quieres finalizar tu actuación, dímelo o aléjate del área de actuación.",
    ["Do you want to end your performance early?"] = "¿Quieres terminar tu actuación antes de tiempo?",
    ["Congratulations! You scored [amount] in your Firemaking (fire-breathing) performance. You received [amount] experience points."] = "¡Felicitaciones! Obtuviste una puntuación de [amount] en tu actuación de Firemaking (escupe fuego). Recibiste puntos de experiencia [amount].",
    ["I'm sorry, but that performance just wasn't good enough for a reward. Try again next week."] = "Lo siento, pero esa actuación no fue lo suficientemente buena para recibir una recompensa. Vuelve a intentarlo la semana que viene.",
    ["Oh no! You didn't score anything in your Firemaking (fire-breathing) performance. You received 0 experience points."] = "¡Oh, no! No obtuviste nada en tu actuación de Firemaking (escupe fuego). Recibiste 0 puntos de experiencia.",
    ["Can you tell me how I'm doing?"] = "¿Puedes decirme cómo estoy?",
    ["What are you doing here?"] = "¿Qué estás haciendo aquí?",
    ["Emmet and I heard about the celebration and we simply couldn't resist a huge glowing fire!"] = "Emmet y yo nos enteramos de la celebración y ¡simplemente no pudimos resistirnos a un enorme fuego resplandeciente!",
    ["What is it you're doing exactly?"] = "¿Qué estás haciendo exactamente?",
    ["Fire breathing, which helps me vent my anger."] = "Respiración de fuego, que me ayuda a desahogar mi ira.",
    ["Can I have a go?"] = "¿Puedo intentarlo?",
    ["Sure, take this fire breathing solution. Who knows you might even have an 'extraordinary talent' for it."] = "Claro, toma esta solución para respirar fuego. Quién sabe, es posible que incluso tengas un \"talento extraordinario\" para ello.",
    ["Thanks; got any tips?"] = "Gracias; ¿Tienes algún consejo?",
    ["It's all about one thing and that's making sure you take a deep breath so you have enough air to breathe the correct pressure."] = "Se trata de una cosa y es asegurarse de respirar profundamente para tener suficiente aire para respirar con la presión correcta.",
    ["Have you got any more fire breathing solution?"] = "¿Tienes más solución para expulsar incendios?",
    ["Sorry, I've not got any on me, but I did give some supplies to Alice."] = "Lo siento, no tengo ninguno encima, pero le di algunos suministros a Alice.",
    ["We're here for a celebration and we simply couldn't resist a huge glowing fire!"] = "¡Estamos aquí para una celebración y simplemente no pudimos resistirnos a un enorme fuego resplandeciente!",
    ["We haven't quite started yet though, so come back soon!"] = "Aún no hemos empezado, ¡así que vuelve pronto!",
    ["The Wintumber Warmer event hasn't started yet."] = "El evento Wintumber Warmer aún no ha comenzado.",
    ["Breathe fire."] = "Respira fuego.",
    ["We're just packing up after the new year's celebration"] = "Estamos haciendo las maletas después de la celebración de año nuevo",
    ["I'd love to come back next year! This has been so much fun!"] = "¡Me encantaría volver el año que viene! ¡Esto ha sido muy divertido!",
    ["The Wintumber Warmer event has ended."] = "El evento Wintumber Warmer ha finalizado.",
    ["What puny human do near Trollgrav. Seradoomin smoosh like tiny bug!"] = "Qué hacen los humanos insignificantes cerca de Trollgrav. ¡Seradoomin se mueve como un pequeño insecto!",
    ["Woah, woah. I just wanted to talk!"] = "Vaya, vaya. ¡Solo quería hablar!",
    ["Sorry, Seradoomin on edge lately. Not used to being a spooky."] = "Lo siento, Seradoomin está al límite últimamente. No estoy acostumbrado a ser espeluznante.",
    ["That's okay."] = "Está bien.",
    ["**What would you like to say?**"] = "**¿Qué te gustaría decir?**",
    ["Me helpin' train puny spookies."] = "Yo ayudo a entrenar fantasmas insignificantes.",
    ["Need to make sure weaklins get into Trollgrav."] = "Necesito asegurarnos de que los débiles entren en Trollgrav.",
    ["Ah, okay."] = "Ah, está bien.",
    ["Can I get into Trollgrav?"] = "¿Puedo entrar en Trollgrav?",
    ["Silly human, Trollgrav only for trolls. You go to... Humangrav. Yeah Humangrav me guess."] = "Humano tonto, Trollgrav solo para trolls. Ve a... Humangrav. Sí, Humangrav, supongo.",
    ["You want fight some troll spookies for me? Might help you get into Humangrav?"] = "¿Quieres luchar contra algunos trolls espeluznantes por mí? ¿Podría ayudarte a entrar en Humangrav?",
    ["Seradoomin tired of training dem."] = "Seradoomin está cansado de entrenarlos.",
    ["Uh... I'll think about it."] = "Uh... Lo pensaré.",
    ["Okay den."] = "Está bien, guarida.",
    ["Why are you called Saradomin?"] = "¿Por qué te llamas Saradomin?",
    ["I was just wondering, why are you called Saradomin."] = "Me preguntaba por qué te llamas Saradomin.",
    ["No it's Seradoomin not 'sah-rah-doh-min', stoopid human."] = "No, es Seradoomin, no 'sah-rah-doh-min', humano estúpido.",
    ["Okay, well, why are you called 'Seradoomin'."] = "Vale, bueno, ¿por qué te llaman 'Seradoomin'?",
    ["Me fought humans supposed to be smart. All trolls named after first thing dey eat."] = "Luché contra humanos que se supone que son inteligentes. Todos los trolls llevan el nombre de lo primero que comen.",
    ["When Seradoomin just small troll pebble, me eat silly human dat came too close to home."] = "Cuando Seradoomin era un pequeño guijarro troll, yo comía un humano tonto que se acercaba demasiado a casa.",
    ["Dey already came wrapped up in big brown wrapper an every-fing like dey want to be eaten!"] = "¡Ya vinieron envueltos en un gran envoltorio marrón y todo como si quisieran ser comidos!",
    ["Uh..."] = "Eh...",
    ["Anyway when me munchin on dem, they keep saying 'Seradoomin! Seradoomin! help! help!'."] = "De todos modos, cuando los como, siguen diciendo '¡Seradoomin! ¡Seradoomin! ¡ayuda! ¡ayuda!'.",
    ["We fink dat musta been mans name, so dat's why Seradoomin's mumma, 'Gufix' name him 'Seradoomin'."] = "Creemos que debe ser el nombre de un hombre, así que es por eso que la mamá de Seradoomin, 'Gufix', lo llama 'Seradoomin'.",
    ["Right... What a... Lovely? Story."] = "Cierto... Qué... ¿Encantador? Historia.",
    ["Yep, It my faverut."] = "Sí, es mi favorito.",
    ["Byebye puny."] = "Adiós, insignificante.",
    ["Where you fink you goin."] = "Adónde crees que vas.",
    ["I was just seeing what's through this tunnel."] = "Estaba viendo lo que hay a través de este túnel.",
    ["Dat Trollgrav, strictly trolls only."] = "Dat Trollgrav, estrictamente solo trolls.",
    ["Now go away, me very busy."] = "Ahora vete, estoy muy ocupado.",
    ["I'm getting out of here Bwana, the place is infested with zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombies.",
    ["Hello Bwana. Are you interested in buying a ticket for the 'Lady of the Waves'?"] = "Hola Bwana. ¿Estás interesado en comprar una entrada para la 'Dama de las Olas'?",
    ["Yes, that sounds great!"] = "Sí, ¡eso suena genial!",
    ["Great, nice doing business with you."] = "Genial, es un placer hacer negocios contigo.",
    ["Sorry Bwana, you don't have enough money. Come back when you have 25 Gold Pieces."] = "Lo siento Bwana, no tienes suficiente dinero. Vuelve cuando tengas 25 piezas de oro.",
    ["Fair enough Bwana, let me know if you change your mind."] = "Muy bien Bwana, avísame si cambias de opinión.",
    ["Tell me more about the ship."] = "Cuéntame más sobre el barco.",
    ["It's a ship that can take you to either Port Sarim or Port Khazard. The ship lies west of Shilo Village and south of Cairn Island. The tickets cost 25 Gold Pieces. Would you like to purchase a ticket Bwana?"] = "Es un barco que puede llevarte a Port Sarim o a Port Khazard. El barco se encuentra al oeste de Shilo Village y al sur de Cairn Island. Los billetes cuestan 25 monedas de oro. ¿Quieres comprar un billete Bwana?",
    ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
    ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
    ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
    ["I've already spotted this !"] = "¡Ya vi este !",
    ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
    ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    ["A Seren spirit appears, interested in your actions."] = "Aparece un Seren spirit, interesado en tus acciones.",
    ["A Seren spirit appears. Your spirit attraction potion allows you to catch it as it spawns."] = "Aparece un Seren spirit. Tu poción de atracción espiritual te permite atraparlo cuando se genera.",
    ["The Seren spirit gifts you: [quantity] x [Item]. The gift is sent to your bank."] = "El Seren spirit te regala: [quantity] x [Item]. El regalo se envía a su banco.",
    ["The Seren spirit gifts you: [quantity] x [Item]. The gift is sent to your backpack."] = "El Seren spirit te regala: [quantity] x [Item]. El regalo se envía a tu backpack.",
    ["The Seren spirit gifts you: [quantity] x [Item]. The gift drops to the floor."] = "El Seren spirit te regala: [quantity] x [Item]. El regalo cae al suelo.",
    ["The Seren spirit disappears before you could receive a gift from it."] = "El Seren spirit desaparece antes de que puedas recibir un regalo.",
    ["It has been many years since I found my beloved elves and still each day feels like a gift. The world is vibrant with anima and there are no signs of the Creators to diminish it. Is this what it feels like to be home? I have shown my elves the rudimentary tools to improve their civilisation. Simple things, agriculture and just a little magic. They already live in harmony with their world. All I have done is to give them the tools to intensify their connection with it. I have become the focus of a religion. Ceidwad, one of the elven mystics, has spread 'the word of Seren' via a great book called the Cerddi and the elves have embraced it. It is gratifying, but I think of myself less as a god and more as a protector. I still sometimes ponder whether they love me of their own volition or they are enamoured by my divine status. I choose to believe the former. I have almost forgotten the harshness of Freneskae. It was a cold, dead world, but this world teams with life and warmth."] = "Han pasado muchos años desde que encontré a mis amados elfos y todavía siento cada día como un regalo. El mundo vibra con ánima y no hay señales de los Creadores que la disminuyan. ¿Es esto lo que se siente al estar en casa? Les he mostrado a mis elfos las herramientas rudimentarias para mejorar su civilización. Cosas sencillas, agricultura y sólo un poco de magia. Ya viven en armonía con su mundo. Lo único que he hecho es darles las herramientas para intensificar su conexión con ello. Me he convertido en el foco de una religión. Ceidwad, uno de los místicos elfos, ha difundido \"la palabra de Seren\" a través de un gran libro llamado Cerddi y los elfos lo han adoptado. Es gratificante, pero me considero menos un dios y más un protector. A veces todavía me pregunto si me aman por su propia voluntad o si están enamorados de mi estatus divino. Elijo creer en lo primero. Casi me he olvidado de la dureza de Freneskae. Era un mundo frío y muerto, pero este mundo está lleno de vida y calidez.",
    ["I wept for so long when my beloved Ceidwad died. It had been mere decades, but her body had grown decrepit and failed her. How is this fair, that Zaros and I get to live forever, but these noble creatures do not? Why must they wither and die, simply because of the passage of time? Their lives are so brief; they deserve more. I must fix this. I shall give them the gift of time. Music sits at the heart of elven culture. I have devised a method to share my essence with them through sound. In this way, they will accept and embrace my gift. Just enough to give them a measure of my longevity. Their lives will be measured in centuries, not decades. My priests have spread the song and already I can see them growing healthier. They are calling it the 'Song of Creation' - not quite apt, but it has a nice ring to it. Now my elves will live the long lives they deserve."] = "Lloré durante mucho tiempo cuando murió mi amado Ceidwad. Habían pasado apenas décadas, pero su cuerpo se había vuelto decrépito y le había fallado. ¿Cómo es justo que Zaros y yo podamos vivir para siempre, pero estas nobles criaturas no? ¿Por qué deben marchitarse y morir simplemente por el paso del tiempo? Sus vidas son muy breves; merecen más. Debo arreglar esto. Les daré el regalo del tiempo. La música se encuentra en el corazón de la cultura élfica. He ideado un método para compartir mi esencia con ellos a través del sonido. De esta manera aceptarán y abrazarán mi regalo. Lo suficiente para darles una medida de mi longevidad. Sus vidas se medirán en siglos, no en décadas. Mis sacerdotes han difundido la canción y ya puedo verlos cada vez más sanos. La llaman la 'Canción de la Creación'; no es del todo apropiado, pero suena muy bien. Ahora mis elfos vivirán la larga vida que se merecen.",
    ["I have done something terrible. I hope my children can forgive me. The song that was to bless them with long, happy lives has inextricably tied them to me. Our souls have become harmonised. Though I believe they love me by choice, the part of me that instils a feeling of love in others became a great hook in their souls. Barbed kindness, a love that literally breaks their heart if they are apart from me for too long. If they leave my side for more than a few days, they become sick and feverish and will do anything in their power to return to me again. Forsaking duty, forsaking family and friendship. All that matters to them is that they return to my presence. Kept apart from me for too long and their fever becomes worse, their heart stops and I lose them forever. I have done a terrible thing. I am so sorry, my children."] = "He hecho algo terrible. Espero que mis hijos puedan perdonarme. La canción que los bendeciría con una vida larga y feliz los ha unido inextricablemente a mí. Nuestras almas se han armonizado. Aunque creo que me aman por elección propia, la parte de mí que infunde un sentimiento de amor en los demás se convirtió en un gran gancho en sus almas. Bondad punzante, un amor que literalmente les rompe el corazón si están separados de mí por mucho tiempo. Si se alejan de mi lado por más de unos pocos días, se enferman y tienen fiebre y harán todo lo que esté en sus manos para regresar a mí nuevamente. Renunciar al deber, abandonar la familia y la amistad. Lo único que les importa es que regresen a mi presencia. Se mantienen separados de mí durante demasiado tiempo y su fiebre empeora, su corazón se detiene y los pierdo para siempre. He hecho algo terrible. Lo siento mucho, hijos míos.",
    ["He visited again, a young god empowered through accident rather than design. Gifted with divinity, yet he neither craves nor desires it. It must be strange to acquire such a mantle. I cannot empathise for I have always been thus. Like my elves he was a gentle soul and I grew fond of his visits. I find myself impatiently awaiting him; our conversations have become the highlight of decades. He told me of his people and the tragedy that befell them and in doing so he warned me against the dangers of the young gods. Perhaps he would be able to help me, but I am too ashamed to share my burden with him, lest he see me in the same light as those who destroyed his kind. For an entire race to be lost to the whims of a god is unforgivable. I must correct my mistake alone."] = "Lo visitó de nuevo, un dios joven fortalecido por accidente en lugar de diseño. Dotado de divinidad, sin embargo, no la anhela ni la desea. Debe ser extraño adquirir semejante manto. No puedo sentir empatía porque siempre he sido así. Como mis elfos, era un alma amable y me encariñé con sus visitas. Me encuentro esperándolo con impaciencia; Nuestras conversaciones se han convertido en lo más destacado de décadas. Me habló de su pueblo y de la tragedia que les sobrevino y al hacerlo me advirtió contra los peligros de los dioses jóvenes. Quizás él podría ayudarme, pero me da mucha vergüenza compartir mi carga con él, no sea que me vea de la misma manera que aquellos que destruyeron a los de su especie. Que una raza entera se pierda por los caprichos de un dios es imperdonable. Debo corregir mi error solo.",
    ["Guthix is different, stronger somehow. He has grown in potential to a power that rivals my own, perhaps even surpasses it. I have shared my knowledge of the anima with him, and he has gradually grown in power, but this change is sudden and disturbing. With it he has grown in confidence. Were it not tempered by the gentle nature that has always been at his core, this growth would be frightening to see. He has told me of a world that he has discovered - a perfect world. He has already taken some races there, and now he invites me and my elves. The newfound strength emanating from him has a familiar feel. Not Mah... This is one of the others. I shall accept his invitation. I must see this world and discover the cause of his gain in power."] = "Guthix es diferente, más fuerte de alguna manera. Su potencial ha crecido hasta alcanzar un poder que rivaliza con el mío, tal vez incluso lo supera. He compartido mis conocimientos sobre el ánima con él y su poder ha ido aumentando gradualmente, pero este cambio es repentino e inquietante. Con ello ha ganado confianza. Si no estuviera atenuado por la naturaleza amable que siempre ha estado en su esencia, sería aterrador ver este crecimiento. Me ha hablado de un mundo que ha descubierto: un mundo perfecto. Ya ha tomado algunas carreras allí y ahora nos invita a mí y a mis elfos. La nueva fuerza que emana de él tiene una sensación familiar. No Mah... Este es uno de los otros. Aceptaré su invitación. Debo ver este mundo y descubrir la causa de su aumento de poder.",
    ["Knowing I could not leave my elves alone for any length of time, I removed a shard of my being and breathed life into it. I shaped it to look like one of my elves and named it Haluned, then sent it to explore this world of Guthix's. She would be my eyes and ears. This world's abundance of anima struck me immediately, but I could also feel a drain on it. There was no doubt; my suspicions had been confirmed - the creators were here. Haluned explored this world as my proxy. Guthix's humans were there, attuned with nature but in a manner different from my elves. One of them was different from the others, out of flux somehow as though misplaced in time. I shall inform Guthix of this. If magic such as this existed here, then I knew there must be a way to fix what I had done to the elves. The elves will be sad to leave their home, but they must come here with me. This new world could be their salvation."] = "Sabiendo que no podía dejar a mis elfos solos por mucho tiempo, eliminé un fragmento de mi ser y le insuflé vida. Le di forma para que pareciera uno de mis elfos y lo llamé Haluned, luego lo envié a explorar este mundo de Guthix. Ella sería mis ojos y mis oídos. La abundancia de ánima de este mundo me llamó la atención de inmediato, pero también pude sentir su agotamiento. No había ninguna duda; Mis sospechas se habían confirmado: los creadores estaban aquí. Haluned exploró este mundo como mi representante. Los humanos de Guthix estaban allí, en sintonía con la naturaleza pero de una manera diferente a mis elfos. Uno de ellos era diferente de los demás, fuera de flujo, como si estuviera fuera de lugar en el tiempo. Informaré a Guthix de esto. Si magia como ésta existía aquí, entonces sabía que debía haber una manera de arreglar lo que les había hecho a los elfos. Los elfos estarán tristes al dejar su hogar, pero deben venir aquí conmigo. Este nuevo mundo podría ser su salvación.",
    ["I asked them to give up the world of their birth, to travel with me to a brand new world. They wanted to please me, but were reluctant to leave. They did not understand why they must, but to tell them would have shattered their innocence and their trust in me. The only way I could convince them was to withdraw from them for a while, to deprive them of my presence. It was a cruel tactic - one that I regret even now - but it was a necessity. When I returned, their sickness had made them so desperate to be near me that they forgot all about their concerns of abandoning Tarddiad and agreed to come with me. It's for the best, I kept telling myself. I know what is best for them."] = "Les pedí que renunciaran al mundo en el que nacieron y que viajaran conmigo a un mundo completamente nuevo. Querían complacerme, pero se resistían a irse. No entendían por qué debían hacerlo, pero decírselo habría destrozado su inocencia y su confianza en mí. La única manera de convencerlos era alejarme de ellos por un tiempo, privarlos de mi presencia. Fue una táctica cruel, de la que incluso ahora me arrepiento, pero era una necesidad. Cuando regresé, su enfermedad los había vuelto tan desesperados por estar cerca de mí que se olvidaron por completo de sus preocupaciones por abandonar Tarddiad y aceptaron venir conmigo. Es lo mejor, me decía una y otra vez. Sé lo que es mejor para ellos.",
    ["Thankfully, upon our arrival, my elves embraced Gielinor, recognising its perfect beauty. The elves chose a lush forest as their new home, and I instructed them to build a new city. I left Haluned with them so they would not suffer while I set out to explore this world with Guthix. Guthix showed me much of what he had discovered and done. All the while I was looking for signs of the elders, but to no avail. But then Guthix showed me how their magic was all around us. He had wrought strange stones, infused with the world's latent power, that could be used to wield the strange elements and work wonders. It was a magic far beneath anything Guthix or I could muster, but it was magic nonetheless, and its origin was clear. My elves came to understand magic through their connection with me, but Guthix's humans literally plucked magic from the ground. As I cannot find the elders, then these runes are my best chance. I must study the source of their power, for within it I feel will be found a solution."] = "Afortunadamente, a nuestra llegada, mis elfos abrazaron a Gielinor y reconocieron su perfecta belleza. Los elfos eligieron un bosque frondoso como nuevo hogar y les ordené que construyeran una nueva ciudad. Dejé a Haluned con ellos para que no sufrieran mientras yo me disponía a explorar este mundo con Guthix. Guthix me mostró gran parte de lo que había descubierto y hecho. Todo el tiempo estuve buscando señales de los mayores, pero fue en vano. Pero entonces Guthix me mostró cómo su magia nos rodeaba. Había forjado piedras extrañas, imbuidas del poder latente del mundo, que podían usarse para manejar los elementos extraños y hacer maravillas. Era una magia muy inferior a cualquier cosa que Guthix o yo pudiéramos reunir, pero era magia de todos modos y su origen era claro. Mis elfos llegaron a comprender la magia a través de su conexión conmigo, pero los humanos de Guthix literalmente arrancaron magia del suelo. Como no puedo encontrar a los ancianos, estas runas son mi mejor oportunidad. Debo estudiar la fuente de su poder, porque creo que en ella se encontrará una solución.",
    ["**Exploration.**"] = "**Exploración.**",
    ["Guthix has gone to slumber in order to mitigate the drain on this world as best he can, but also to leave his humans to their own devices. He invited me to join him, and I wished to go. But if I were to do so, it would leave my elves to their fate. I care for them, and I must try to set them free. The magic of the creators woven into stone is the key, I feel it. I must find a way to use it to break my link, so that I may assist Guthix. Prifddinas's population has boomed since our arrival, and Haluned's presence alone is no longer enough to sustain them. Thus, I must remain, and Haluned can once again be my proxy in the world. Although I feel like I already know every corner of Isafdar, I shall begin my search anew, with fresh eyes. Haluned is a capable mage in her own right, but I have asked her to travel as a human would, to view this world from their perspective. This will require her to traverse beneath the mountains to the east into human lands. I hope it is safe."] = "Guthix se ha ido a dormir para mitigar el drenaje de este mundo lo mejor que pueda, pero también para dejar a sus humanos a su suerte. Me invitó a unirme a él y yo deseaba ir. Pero si lo hiciera, dejaría a mis elfos a su suerte. Me preocupo por ellos y debo intentar liberarlos. La magia de los creadores tejida en piedra es la clave, lo siento. Debo encontrar una manera de usarlo para romper mi vínculo y poder ayudar a Guthix. La población de Prifddinas ha aumentado desde nuestra llegada y la presencia de Haluned por sí sola ya no es suficiente para sustentarlos. Por lo tanto, debo permanecer y Haluned puede volver a ser mi representante en el mundo. Aunque siento que ya conozco cada rincón de Isafdar, comenzaré mi búsqueda de nuevo, con ojos nuevos. Haluned es una maga capaz por derecho propio, pero le he pedido que viaje como lo haría un humano, para ver este mundo desde su perspectiva. Esto requerirá que ella atraviese debajo de las montañas hacia el este hacia tierras humanas. Espero que sea seguro.",
    ["**Emanation.**"] = "**Emanación.**",
    ["If only I had viewed the world from the perspective of mortals sooner! During her traversal of the secret pass beneath the mountains, Haluned felt a strange emanation. It brought to me memories of my time with Zaros back on Freneskae. I felt its draw through her. At the point of this emanation we discovered a rift through which poured a near-limitless supply of deathly energy. My own energy derives from the light end of the spectrum, but this energy type sits at the opposite end of the scale, much like my old companion did. Could such energy counteract my own, and break my link with the elves? If I can find a way to safely tap this energy, then the elves might be free of me. They would regain their diminished mortality, but such is how it should be."] = "¡Si tan solo hubiera visto el mundo desde la perspectiva de los mortales antes! Durante su recorrido por el paso secreto bajo las montañas, Haluned sintió una extraña emanación. Me trajo recuerdos de mi tiempo con Zaros en Freneskae. Sentí su atracción a través de ella. En el punto de esta emanación descubrimos una grieta a través de la cual fluía un suministro casi ilimitado de energía mortal. Mi propia energía se deriva del extremo luminoso del espectro, pero este tipo de energía se encuentra en el extremo opuesto de la escala, al igual que mi antiguo compañero. ¿Podría esa energía contrarrestar la mía y romper mi vínculo con los elfos? Si puedo encontrar una manera de aprovechar esta energía de forma segura, entonces los elfos podrían liberarse de mí. Recuperarían su mortalidad disminuida, pero así debe ser.",
    ["**Enervation.**"] = "**Enervación.**",
    ["The Iorwerth seem best suited for my initial tests with this death energy. They were willing volunteers, of course, for they both loved and trusted me. Together we developed a range of spells, rituals and blessings, and infused this energy with crystal to explore its effects. To begin with, nothing happened, but slowly the elves grew more accustomed to the energy and grew more confident in its use. From this, we learned a great many things that would be of value to elven society. Unfortunately, it did not have the desired effect of negating my influence over them. There was something about this energy, though. It made me feel something I had not felt for a long time. And while I enjoyed this sensation - which I can only describe as a memory of euphoria - it was only ever temporary. And while away from the energy, negative thoughts found their way into my mind. Depression over my lack of progress, guilt over what I had done to the elves, anxiety of what might become of them, longing for our old home on Tarddiad. I aborted the tests and sealed away the energy - it was not the answer I had been seeking."] = "Los Iorwerth parecen ser los más adecuados para mis pruebas iniciales con esta energía de muerte. Eran voluntarios dispuestos, por supuesto, porque ambos me querían y confiaban en mí. Juntos desarrollamos una variedad de hechizos, rituales y bendiciones, e infundimos esta energía con cristal para explorar sus efectos. Al principio no pasó nada, pero poco a poco los elfos se acostumbraron más a la energía y tuvieron más confianza en su uso. De esto aprendimos muchas cosas que serían valiosas para la sociedad élfica. Desafortunadamente, no tuvo el efecto deseado de negar mi influencia sobre ellos. Sin embargo, había algo en esta energía. Me hizo sentir algo que no había sentido en mucho tiempo. Y aunque disfruté de esta sensación, que sólo puedo describir como un recuerdo de euforia, fue sólo temporal. Y mientras estaba lejos de la energía, los pensamientos negativos llegaron a mi mente. Depresión por mi falta de progreso, culpa por lo que les había hecho a los elfos, ansiedad por lo que podría ser de ellos, añoranza por nuestro antiguo hogar en Tarddiad. Aborté las pruebas y sellé la energía; no era la respuesta que había estado buscando.",
    ["I have been so enrapt in my goal of freeing my elves from their unseen enslavement to me, and so focussed on my efforts under the mountains, that I have failed to notice events occurring in the wider world. Word of an ever-expanding empire has reached our borders. My first thoughts were of fear for the safety of my people, and so I endeavoured to learn as much as I could of this new potential threat. And it was not long before I discovered that its emperor was none other than Zaros. Knowing this, my concern dissipated. I wondered what could have led him to such, but after reflecting upon my own experiences with mortality I wondered no more. I reached out to him, in hopes that he might hold the answers I sought. I was apprehensive, considering how we affect one another, but upon his arrival I noted that our connection had waned, and within that I saw the truth. Magic could not undo what I had done to my elves, only separation from the source. From me. As divine beings, Zaros and I could withstand such separation, but the frailty of the elves leads them to sickness and death. My separation from them must be gradual. It was as well that I figured this for myself, for Zaros did not come with solutions, only problems of his own. I would have helped if I could, but my elves must come first. All I could do was tell him of my own journey through Guthix's gate, in hopes that he could find his answers elsewhere. My elves and I would not be requiring a way to return home to Tarddiad for a very long time..."] = "He estado tan absorto en mi objetivo de liberar a mis elfos de su esclavitud invisible hacia mí, y tan concentrado en mis esfuerzos bajo las montañas, que no he notado los eventos que ocurren en el resto del mundo. La noticia de un imperio en constante expansión ha llegado a nuestras fronteras. Mis primeros pensamientos fueron de temor por la seguridad de mi gente, por lo que me esforcé por aprender todo lo que pudiera sobre esta nueva amenaza potencial. Y no pasó mucho tiempo antes de que descubriera que su emperador no era otro que Zaros. Sabiendo esto, mi preocupación se disipó. Me preguntaba qué podría haberlo llevado a eso, pero después de reflexionar sobre mis propias experiencias con la mortalidad no me pregunté más. Me acerqué a él con la esperanza de que pudiera tener las respuestas que buscaba. Estaba preocupado, considerando cómo nos afectamos unos a otros, pero cuando llegó, noté que nuestra conexión había disminuido, y en eso vi la verdad. Magic no pudo deshacer lo que les había hecho a mis elfos, sólo la separación de la fuente. De mi parte. Como seres divinos, Zaros y yo podríamos resistir tal separación, pero la fragilidad de los elfos los lleva a la enfermedad y la muerte. Mi separación de ellos debe ser gradual. Fue una suerte que me diera cuenta de esto por mí mismo, porque Zaros no vino con soluciones, solo sus propios problemas. Habría ayudado si pudiera, pero mis elfos deben ser lo primero. Todo lo que pude hacer fue contarle mi propio viaje a través de la puerta de Guthix, con la esperanza de que pudiera encontrar sus respuestas en otra parte. Mis elfos y yo no necesitaríamos una forma de regresar a Tarddiad durante mucho tiempo...",
    ["He is dead! How can he be dead? How is this possible? We are the divine offspring of the creators of this universe - how could it be possible for us to die at the hands of mortals? And if he can die...can I? His energy was derived from darkness and death, but mine springs from light and life. Surely that means I cannot die, even though he could. And I must not, for if I do, then what will happen to those under my care? Though Zaros is gone, his legacy - at least - will remain. Those who followed him are left with all that he gave them, all that he taught them. Yet my sudden departure would soon see the elves follow me into oblivion. I must ensure that I will have time enough to undo what I have done, and wean the elves off their dependency on me."] = "¡Está muerto! ¿Cómo puede estar muerto? ¿Cómo es esto posible? Somos la descendencia divina de los creadores de este universo. ¿Cómo podría ser posible que muramos a manos de los mortales? Y si él puede morir... ¿yo puedo? Su energía derivaba de la oscuridad y la muerte, pero la mía brota de la luz y la vida. Seguramente eso significa que no puedo morir, aunque él sí. Y no debo hacerlo, porque si lo hago, ¿qué pasará con los que están bajo mi cuidado? Aunque Zaros ya no está, su legado (al menos) permanecerá. Los que lo siguieron se quedan con todo lo que él les dio, todo lo que les enseñó. Sin embargo, mi repentina partida pronto haría que los elfos me siguieran hasta el olvido. Debo asegurarme de tener tiempo suficiente para deshacer lo que he hecho y hacer que los elfos dejen de depender de mí.",
    ["I was wrong about Zaros's legacy. Even now, his empire crumbles, beset on all sides by the followers of other gods. His life's work is being undone by fear and jealousy, and in time will be forgotten entirely. The peace that his empire brought to the world is broken - and now the vultures picking at his corpse seek to encroach upon Tirranwn. I shan't allow it! I have tasked Clan Cadarn with the protection of all the clans and these lands we call home. Baxtorian holds the eastern entrance to the hidden pass with a cadre of elven mages and scouts, and a small force of Iorwerth. While Zaros held the reigns of his empire we were safe - he ensured our lands were left untouched - but that can no longer be relied upon. I shall attune the anima of Tirranwn to erect a barrier around us, which should keep us isolated from the others of this world. All elves must retreat into the forests. If Zaros can be forgotten, then so can we. Hopefully, it will buy the time I require. We shall leave the rest of the world to their wars. I have been wrong about so much. I hope that I am not wrong about this."] = "Me equivoqué sobre el legado de Zaros. Incluso ahora, su imperio se desmorona, acosado por todos lados por los seguidores de otros dioses. El trabajo de su vida está siendo deshecho por el miedo y los celos, y con el tiempo será olvidado por completo. La paz que su imperio trajo al mundo se ha roto y ahora los buitres que picotean su cadáver intentan invadir Tirranwn. ¡No lo permitiré! Le he encargado al Clan Cadarn la protección de todos los clanes y de estas tierras que llamamos hogar. Baxtorian mantiene la entrada oriental al paso oculto con un grupo de magos y exploradores elfos, y una pequeña fuerza de Iorwerth. Mientras Zaros mantuvo las riendas de su imperio, estábamos a salvo (él se aseguró de que nuestras tierras permanecieran intactas), pero ya no se puede confiar en eso. Sintonizaré el anima de Tirranwn para erigir una barrera a nuestro alrededor, que debería mantenernos aislados de los demás de este mundo. Todos los elfos deben retirarse a los bosques. Si Zaros puede ser olvidado, nosotros también. Con suerte, me permitirá ganar el tiempo que necesito. Dejaremos al resto del mundo con sus guerras. Me he equivocado en muchas cosas. Espero no equivocarme en esto.",
    ["As the elves have withdrawn from the world, I have withdrawn from them; I have cloistered myself within the Tower of Voices. Only the lords and ladies of the eight largest families are permitted entry, so that I might instruct them. Their clans remain healthy - it is starting to work. I must prepare the elves to live in this world without me - once they are weaned, I intend to leave. Each of the clans must find their own place within a new elven society, becoming more reliant on each other for their survival, and less on my guidance. The family I find myself most concerned with is the Iorwerth. Their talents for hunting and killing are necessary for the survival of all clans. They keep the dark beasts at bay, and provide fish and meat to the other clans. As such, they have more need to venture beyond the safety of the city, and for longer and longer stints. Perhaps they are becoming less dependent on my presence - more so than the other clans. Their lady, when she visits, second guesses me at every turn. Though I desire revenge upon Zaros's murderer, it is not something I would act upon. But she has picked up on this desire, and though she cannot understand the source of it, her thoughts run dark with it. It is perhaps an encouraging sign to see such free thought, but it worries me all the same. I cannot finally free the elves of me only to leave them with an imprint of my darker impulses. I can control them, but they cannot."] = "Así como los elfos se han retirado del mundo, yo me he retirado de ellos; Me he enclaustrado dentro de la Torre de las Voces. Sólo se permite la entrada a los señores y damas de las ocho familias más grandes, para que yo pueda instruirlos. Sus clanes siguen sanos: está empezando a funcionar. Debo preparar a los elfos para vivir en este mundo sin mí; una vez que sean destetados, tengo la intención de irme. Cada uno de los clanes debe encontrar su propio lugar dentro de una nueva sociedad élfica, volviéndose más dependientes unos de otros para su supervivencia y menos de mi guía. La familia que más me preocupa es la de Iorwerth. Sus talentos para cazar y matar son necesarios para la supervivencia de todos los clanes. Mantienen a raya a las bestias oscuras y proporcionan pescado y carne a los demás clanes. Como tales, tienen más necesidad de aventurarse más allá de la seguridad de la ciudad y por períodos cada vez más largos. Quizás se estén volviendo menos dependientes de mi presencia, más que los otros clanes. Su señora, cuando me visita, me cuestiona a cada paso. Aunque deseo vengarme del asesino de Zaros, no es algo que haría. Pero ella se ha dado cuenta de este deseo y, aunque no puede comprender su origen, sus pensamientos se oscurecen. Tal vez sea un signo alentador ver tal libre pensamiento, pero de todos modos me preocupa. Finalmente no puedo liberar a los elfos de mí solo para dejarles una huella de mis impulsos más oscuros. Puedo controlarlos, pero ellos no.",
    ["So much has happened since Guthix removed himself from this world. I thought if I were ever to see him again it would bring joy to both our hearts, but we have found nothing but sadness. The petty squabbling of the young gods has awoken him. He has taken the example of my barrier around Tirranwn and applied it to the world as a whole, to stop the evicted gods from returning. I am glad he has returned and put a stop to them. I am glad that he returned to me too, but he no longer asks me to leave this place...he demands it. In that moment, I confessed to him what I had done to the elves and hence why I could not...why I still cannot. There was only one course of action. I would be leaving, just not with Guthix. He tried to convince me otherwise, but upon realising my resolve he conceded, and with no words left to speak, he bowed his head, then turned and left. Before I could do what must be done, I recalled my proxy, and into it poured all of my negativity, my darkest thoughts, my fears and regrets, and then sent it away from elven lands where it could do no harm. I had to be rid of it for what was to come next. Prifddinas now lies temporarily evacuated - it shall be regrown once I am gone, with the crystals I have handed to the lords and ladies. By expelling my energy, this area will be forever infused with it, and small fragments of my body, when carried, will allow elves to journey far beyond these city walls. In time, even these shall no longer be needed. I have encouraged Baxorian to do just this, and to journey east once more. Now that the wars have ended, it is time for my elves to rejoin this world. I accept now that even divine beings can die, and that my time has come. At least I go knowing that the harm I have caused this gentle people can and will eventually be undone, and that my death will not lead to theirs."] = "Han pasado muchas cosas desde que Guthix se retiró de este mundo. Pensé que si alguna vez lo volvía a ver traería alegría a nuestros corazones, pero no hemos encontrado nada más que tristeza. Las pequeñas disputas de los jóvenes dioses lo han despertado. Ha tomado el ejemplo de mi barrera alrededor de Tirranwn y lo ha aplicado al mundo en su conjunto, para impedir que los dioses desalojados regresen. Me alegro de que haya regresado y les haya puesto fin. Me alegro de que él también haya regresado a mí, pero ya no me pide que abandone este lugar... lo exige. En ese momento, le confesé lo que les había hecho a los elfos y por eso no pude... por qué todavía no puedo. Sólo había un curso de acción. Me iría, pero no con Guthix. Intentó convencerme de lo contrario, pero al darse cuenta de mi determinación accedió y, sin palabras para hablar, inclinó la cabeza, luego se giró y se fue. Antes de que pudiera hacer lo que debía hacer, recordé a mi apoderado, y en él vertí toda mi negatividad, mis pensamientos más oscuros, mis miedos y arrepentimientos, y luego lo envié lejos de las tierras élficas donde no podía hacer daño. Tenía que deshacerme de él para lo que vendría después. Prifddinas ahora se encuentra temporalmente evacuado; volverá a crecer una vez que yo me haya ido, con los cristales que le he entregado a los señores y damas. Al expulsar mi energía, esta área quedará infundida para siempre con ella, y pequeños fragmentos de mi cuerpo, cuando los lleve, permitirán a los elfos viajar mucho más allá de los muros de esta ciudad. Con el tiempo, incluso estos ya no serán necesarios. He alentado a Baxorian a hacer precisamente esto y a viajar hacia el este una vez más. Ahora que las guerras han terminado, es hora de que mis elfos se reúnan con este mundo. Acepto ahora que incluso los seres divinos pueden morir y que ha llegado mi hora. Al menos voy sabiendo que el daño que he causado a esta gentil gente puede y eventualmente será deshacer, y que mi muerte no conducirá a la de ellos.",
    ["*(See above)*"] = "*(Ver arriba)*",
    ["No! You left me! You left me all alone! Get away from me! GET AWAY FROM ME!"] = "¡No! ¡Me dejaste! ¡Me dejaste sola! ¡Aléjate de mí! ¡ALETÉJATE DE MÍ!",
    ["You left her alone as well, just when she needed you most."] = "También la dejaste sola, justo cuando más te necesitaba.",
    ["Get away from me! Abandoner, monster, ungrateful child. We have no more to say to one another."] = "¡Aléjate de mí! Abandonado, monstruo, niño desagradecido. No tenemos más que decirnos unos a otros.",
    ["**Unlocks \"the Fractured\" title**"] = "**Desbloquea el título \"el Fracturado\"**",
    ["Is it really you? I can feel your presence, that familiar energy!"] = "¿De verdad eres tú? ¡Puedo sentir tu presencia, esa energía familiar!",
    ["No...wait...diminished...shattered...gone."] = "No... espera... disminuido... destrozado... desaparecido.",
    ["Not gone...taken away, ripped from life."] = "No desaparecido... arrebatado, arrancado de la vida.",
    ["Gone..."] = "Se fue...",
    ["Alone..."] = "Solo...",
    ["Broken... I can never be whole again."] = "Roto... Nunca podré estar completo otra vez.",
    ["**Unlocks \"the Corrupted\" title**"] = "**Desbloquea el título \"el corrupto\"**",
    ["Unclean! It cloys, clinging to my soul as it does the crystal."] = "¡Inmundo! Me empalaga, se aferra a mi alma como lo hace el cristal.",
    ["Iaia, poor Iaia. Did you fix the illujanka, brother? Or was that another empty promise?"] = "Iaia, pobre Iaia. ¿Arreglaste la illujanka, hermano? ¿O fue otra promesa vacía?",
    ["That...that is one of their instruments. It should not be in the hands of a mortal."] = "Ese... ese es uno de sus instrumentos. No debería estar en manos de un mortal.",
    ["Naive. He was too trusting of other gods and joined their wars too readily."] = "Ingenuo. Confiaba demasiado en otros dioses y se unía a sus guerras con demasiada facilidad.",
    ["So ready to shout about the atrocities of the other gods."] = "Muy dispuesto a gritar sobre las atrocidades de los otros dioses.",
    ["If only he could learn to listen."] = "Si tan solo pudiera aprender a escuchar.",
    ["He would have reduced Gielinor to rubble given half the chance."] = "Habría reducido a Gielinor a escombros si hubiera tenido la mitad de oportunidad.",
    ["I felt his destruction, it echoed out through the anima mundi."] = "Sentí su destrucción, resonó a través del anima mundi.",
    ["I am not saddened by his death, we are all better for it."] = "No me entristece su muerte, todos estamos mejor por ello.",
    ["Saradomin. So self-righteous, believing that he alone should rule a world."] = "Saradomin. Tan moralista, que cree que sólo él debería gobernar el mundo.",
    ["Arrogant. No god should rule. We should protect and nurture."] = "Arrogante. Ningún dios debería gobernar. Debemos proteger y nutrir.",
    ["Those who desire power almost never deserve it and he is no different."] = "Quienes desean el poder casi nunca lo merecen y él no es diferente.",
    ["The sword of the betrayer! Usurper! You killed my sibling! To use Their tools for such selfish goals... Unthinkable. Unforgivable!"] = "¡La espada del traidor! ¡Usurpador! ¡Mataste a mi hermano! Usar Sus herramientas para objetivos tan egoístas... Impensable. ¡Imperdonable!",
    ["Ambition like his is a danger to all of us."] = "Una ambición como la suya es un peligro para todos nosotros.",
    ["Yet...I should not have risen against him."] = "Sin embargo... No debería haberme levantado contra él.",
    ["He was not worth breaking my promise over."] = "No valía la pena romper mi promesa.",
    ["You! You gave me hope...that I could fix...but I couldn't."] = "¡Tú! Me diste esperanza... de que podía arreglarlo... pero no pude.",
    ["The amulet... A simple challenge, still unfulfilled."] = "El amuleto... Un desafío sencillo, aún sin cumplir.",
    ["Bring the clans together, and it shall be complete."] = "Reúne a los clanes y todo estará completo.",
    ["Together...At last."] = "Juntos... Por fin.",
    ["A piece of myself. I can feel myself spread over the city, like butter over too much toast."] = "Un pedazo de mí. Puedo sentirme esparcido por la ciudad, como mantequilla sobre demasiada tostada.",
    ["Why would you this to me? Show me the shredded pieces of the soul of the god I adored. How can you be so cruel?"] = "¿Por qué me dices esto? Muéstrame los pedazos del alma del dios que adoraba. ¿Cómo puedes ser tan cruel?",
    ["A cruel reminder of my darker moments."] = "Un cruel recordatorio de mis momentos más oscuros.",
    ["That means little to me I'm afraid."] = "Me temo que eso significa poco para mí.",
    ["*The fragmented form of Seren occasionally says one of a number of lines of speech randomly*"] = "*La forma fragmentada de Seren ocasionalmente dice una de varias líneas de discurso al azar*",
    ["Broken...shattered...lost."] = "Roto... destrozado... perdido.",
    ["But is it really love?"] = "¿Pero es realmente amor?",
    ["Can't set them free... What have I done?"] = "No puedo liberarlos... ¿Qué he hecho?",
    ["Dreams...just dreams. Am I real?"] = "Sueños... sólo sueños. ¿Soy real?",
    ["Freneskae was a barren place, but I had Mah to watch over."] = "Freneskae era un lugar árido, pero tenía que vigilar a Mah.",
    ["*A new fragment of Seren apppears above the next elven clan's symbol clockwise and says the following line; this continues until the monologue is over, except for the last line which is said in the beginning position*"] = "*Un nuevo fragmento de Seren aparece encima del símbolo del siguiente clan elfo en el sentido de las agujas del reloj y dice la siguiente línea; esto continúa hasta que termina el monólogo, excepto la última línea que se dice en la posición inicial*",
    ["My companion had left me alone. There was only her."] = "Mi compañero me había dejado solo. Sólo estaba ella.",
    ["In time there came other children of Mah."] = "Con el tiempo vinieron otros hijos de Mah.",
    ["But she was asleep and unable to raise them herself."] = "Pero ella estaba dormida y no podía levantarlos ella misma.",
    ["I lied to them, pretended I was Mah and taught them of their world."] = "Les mentí, fingí ser Mah y les enseñé su mundo.",
    ["I went wrong somewhere along the way and they became violent."] = "Me equivoqué en algún punto del camino y se volvieron violentos.",
    ["I was ashamed for the bloodshed I helped to cause and so I withdrew from them."] = "Me avergoncé por el derramamiento de sangre que contribuí a causar y por eso me retiré de ellos.",
    ["In time I left, for a new world."] = "Con el tiempo me fui, hacia un mundo nuevo.",
    ["A world full of life, and my beautiful, noble elves."] = "Un mundo lleno de vida y de mis hermosos y nobles elfos.",
    ["A home at last."] = "Un hogar por fin.",
    ["Guthix told me about this world that he had discovered, a place filled with anima."] = "Guthix me habló de este mundo que había descubierto, un lugar lleno de ánima.",
    ["*Seren divides into a new fragment over the next elven clan's symbol clockwise and says the following line; this continues until the full monologue is over*"] = "*Seren se divide en un nuevo fragmento sobre el símbolo del siguiente clan élfico en el sentido de las agujas del reloj y dice la siguiente línea; Esto continúa hasta que termina el monólogo completo*",
    ["He invited me to take my elves there and, while I trusted him, I was not so willing to risk them without seeing it for myself."] = "Me invitó a llevar a mis elfos allí y, aunque confiaba en él, no estaba tan dispuesto a arriesgarlos sin verlo por mí mismo.",
    ["I disguised myself as one of my most faithful scouts and travelled through the World Gate to see this new world."] = "Me disfrazé de uno de mis exploradores más fieles y viajé a través de la Puerta del Mundo para ver este nuevo mundo.",
    ["The world was brimming with anima, just as Guthix had promised, but there was something else. A familiar presence."] = "El mundo rebosaba ánima, tal como había prometido Guthix, pero había algo más. Una presencia familiar.",
    ["I knew Guthix could not see it, but I could see those familiar patterns in the anima's glow."] = "Sabía que Guthix no podía verlo, pero podía ver esos patrones familiares en el brillo del ánima.",
    ["They were here."] = "Estaban aquí.",
    ["Under Guthix's careful minstrations the Anima Mundi was calm, but strong. I wondered - could he keep them asleep indefinitely?"] = "Bajo los cuidadosos cuidados de Guthix, el Anima Mundi estaba tranquilo, pero fuerte. Me pregunté: ¿podría mantenerlos dormidos indefinidamente?",
    ["I knew that were it possible, then it would be through him. So I decided, there and then, that I would bring the elves to Gielinor."] = "Sabía que si fuera posible, sería a través de él. Así que decidí, en ese momento, que traería a los elfos a Gielinor.",
    ["Perhaps together we would be able to keep them asleep."] = "Quizás juntos logremos mantenerlos dormidos.",
    ["He's gone, isn't he? I can't feel his presence anymore."] = "Se ha ido, ¿no? Ya no puedo sentir su presencia.",
    ["His plan...always his plan...must stay strong..."] = "Su plan...siempre su plan...debe mantenerse fuerte...",
    ["I am in so many pieces, so many places."] = "Estoy en tantas piezas, en tantos lugares.",
    ["*Seren shatters into five fragments around the original one, and each says one of these randomly*"] = "*Seren se rompe en cinco fragmentos alrededor del original, y cada uno dice uno de estos al azar*",
    ["GET IT OFF ME!"] = "¡QUITALO DE MÍ!",
    ["Ha ha ha ha ha ha ha ha"] = "Ja ja ja ja ja ja ja ja ja",
    ["I AM A GOD! WORSHIP ME!"] = "¡SOY UN DIOS! ¡ADORAME!",
    ["I hear them stirring."] = "Los oigo moverse.",
    ["So alone..."] = "Tan solo...",
    ["Such beautiful music..."] = "Que música tan hermosa...",
    ["What is happening?"] = "¿Qué está pasando?",
    ["Why, Guthix, why?"] = "¿Por qué, Guthix, por qué?",
    ["I am...we are...cannot feel my soul."] = "Yo soy... nosotros somos... no puedo sentir mi alma.",
    ["I betrayed him...so ashamed."] = "Lo traicioné... tan avergonzado.",
    ["I can feel them...stirring..."] = "Puedo sentirlos... moviéndose...",
    ["I love my elves and they love me."] = "Amo a mis elfos y ellos me aman.",
    ["It was too late that I realised that all must love me, such was Mah's decree."] = "Ya era demasiado tarde cuando me di cuenta de que todos debían amarme, tal era el decreto de Mah.",
    ["At first I distanced myself from them, in the hope that they would find their own path."] = "Al principio me distancié de ellos, con la esperanza de que encontraran su propio camino.",
    ["But as I distanced myself, I watched as they suffered in my absence."] = "Pero mientras me distanciaba, vi cómo sufrían en mi ausencia.",
    ["It was more that emotional, I saw them become ill, weak, fevered with their need for my presence."] = "Fue más que emocional, los vi enfermarse, débiles, febriles por la necesidad de mi presencia.",
    ["When some began dying I knew I couldn't leave them any more and so I returned."] = "Cuando algunos empezaron a morir supe que no podía dejarlos más y por eso regresé.",
    ["I had been with them so long that my power had changed them on a physiological level."] = "Llevaba tanto tiempo con ellos que mi poder los había cambiado a nivel fisiológico.",
    ["I knew then that I could not leave them, whatever the reason."] = "Entonces supe que no podía dejarlos, fuera cual fuera el motivo.",
    ["So when Guthix bid me leave, though it broke my heart to hear him say so, I knew I could not leave my elves."] = "Así que cuando Guthix me pidió que me fuera, aunque me rompió el corazón oírlo decirlo, supe que no podía dejar a mis elfos.",
    ["I took that feeling of heartbreak and I filled it with my desire to protect my children."] = "Tomé ese sentimiento de desamor y lo llené con mi deseo de proteger a mis hijos.",
    ["The strain grew so great that I fractured, shattering into fragments."] = "La tensión creció tanto que me fracturé y me rompí en fragmentos.",
    ["My people collected the pieces and kept them close to themselves, seemingly safe from the pain they suffered before."] = "Mi gente recogió las piezas y las mantuvo cerca de ellos, aparentemente a salvo del dolor que sufrieron antes.",
    ["Now they sing such sweet music to me. Perhaps it was worth it."] = "Ahora me cantan una música tan dulce. Quizás valió la pena.",
    ["I was trying to help. I'm so sorry!"] = "Estaba tratando de ayudar. ¡Lo siento mucho!",
    ["Lost him...lost..."] = "Lo perdí...perdí...",
    ["Loved him once...now...again...never."] = "Lo amé una vez... ahora... otra vez... nunca.",
    ["Mah had become too much."] = "Mah se había vuelto demasiado.",
    ["With my companion gone, I was all she had and she clung to me with terrifying strength."] = "Sin mi compañera, yo era todo lo que tenía y se aferró a mí con una fuerza aterradora.",
    ["I found myself glad when she fell into her slumber. Finally, I could do what I wanted."] = "Me alegré cuando ella se quedó dormida. Finalmente pude hacer lo que quería.",
    ["When the time came for me to leave, I hesitated, but not nearly as much as I should."] = "Cuando llegó el momento de irme, dudé, pero no tanto como debería.",
    ["Mah was - is - my maker, but she felt more like my child."] = "Mah fue, es, mi creadora, pero se sentía más como mi hija.",
    ["I could not bear it anymore; could no longer devote my life to her care. I had to escape...and I did."] = "No pude soportarlo más; Ya no podía dedicar mi vida a su cuidado. Tenía que escapar... y lo hice.",
    ["The guilt was overwhelming at first. There were several moments where I almost stepped back through the World Gate to find her again."] = "La culpa fue abrumadora al principio. Hubo varios momentos en los que casi retrocedí por la Puerta del Mundo para encontrarla de nuevo.",
    ["But the elves needed me more and as I made them happy, they too made me happy. I had found my place, my purpose."] = "Pero los elfos me necesitaban más y como yo los hacía felices, ellos también me hacían feliz a mí. Había encontrado mi lugar, mi propósito.",
    ["By the time I had discovered what my presence had done to my beloved children, it was too late."] = "Cuando descubrí lo que mi presencia les había hecho a mis amados hijos, ya era demasiado tarde.",
    ["Mah. I'm sorry I left you...had to..."] = "Mah. Lamento haberte dejado... tuve que...",
    ["My children...my elves...so proud."] = "Mis hijos... mis elfos... muy orgullosos.",
    ["Oh, shiny!"] = "¡Oh, brillante!",
    ["On Tarddiad I found such beauty and wonder."] = "En Tarddiad encontré tanta belleza y maravilla.",
    ["*Seren divides into a new fragment over the next clan's symbol clockwise and says the following line; this continues until the full monologue is over*"] = "*Seren se divide en un nuevo fragmento sobre el símbolo del siguiente clan en el sentido de las agujas del reloj y dice la siguiente línea; Esto continúa hasta que termina el monólogo completo*",
    ["Whereas Mah's children had turned violent, the elves were graceful and peaceful."] = "Mientras que los hijos de Mah se habían vuelto violentos, los elfos eran elegantes y pacíficos.",
    ["I met him there as well. Another god, powerful, but with a gentleness that radiated from him."] = "Allí también lo conocí. Otro dios, poderoso, pero con una dulzura que irradiaba de él.",
    ["He was new to his power, almost innocent in his divinity. I found it strangely charming."] = "Era nuevo en su poder, casi inocente en su divinidad. Lo encontré extrañamente encantador.",
    ["I taught him of anima; of the way that nature can empower us. He became enamoured with this and left for another world."] = "Le enseñé de anima; de la forma en que la naturaleza puede empoderarnos. Se enamoró de esto y se fue a otro mundo.",
    ["When he returned, he was stronger than before. In him, I sensed a power that equalled my own."] = "Cuando regresó, era más fuerte que antes. En él sentí un poder que igualaba el mío.",
    ["For a time I was concerned, as power can corrupt even the purest of hearts."] = "Por un tiempo estuve preocupado, ya que el poder puede corromper incluso el corazón más puro.",
    ["My concern was misplaced, however, for in him remained that same gentle soul, the same god who wanted the world to be for the mortals."] = "Sin embargo, mi preocupación estaba fuera de lugar, porque en él seguía esa misma alma gentil, el mismo dios que quería que el mundo fuera para los mortales.",
    ["It was in that moment, that I knew that I loved him."] = "Fue en ese momento que supe que lo amaba.",
    ["Though shattered, we watch over."] = "Aunque destrozados, vigilamos.",
    ["*Seren shatters into eight fragments, each hovering over an elven clan's symbol*"] = "*Seren se rompe en ocho fragmentos, cada uno flotando sobre el símbolo de un clan élfico*",
    ["UNCLEAN, UNCLEAN, UNCLEAN!"] = "¡INMUNO, INMUNO, INMUNO!",
    ["What have I done to you? My children..."] = "¿Qué te he hecho? Mis hijos...",
    ["Greetings, World Guardian."] = "Saludos, Guardián Mundial.",
    ["*(Only if not selected last:)*"] = "*(Sólo si no fue seleccionado en último lugar:)*",
    ["World Guardian is a bit formal."] = "World Guardian es un poco formal.",
    ["World Guardian is a bit formal. Don't you think?"] = "World Guardian es un poco formal. ¿No crees?",
    ["Perhaps. But Guthix does not bestow his trust lightly and so the title must be well earned. Humility is a worthy virtue. But we should be willing to embrace our achievements rather than obfuscate them out of some false sense of modesty. For good or ill, you are the World Guardian now. To some that makes you a beacon of hope and to others a threat to destroy."] = "Quizás. Pero Guthix no otorga su confianza a la ligera, por lo que el título debe estar bien ganado. La humildad es una virtud digna. Pero deberíamos estar dispuestos a aceptar nuestros logros en lugar de ofuscarlos por algún falso sentido de modestia. Para bien o para mal, ahora eres el Guardián Mundial. Para algunos eso te convierte en un faro de esperanza y para otros en una amenaza a destruir.",
    ["And which am I to you?"] = "¿Y quién soy yo para ti?",
    ["Now now, that would be telling wouldn't it Player?"] = "Ahora bien, eso sería revelador, ¿no es así Player?",
    ["I'd like to ask about you."] = "Me gustaría preguntar por ti.",
    ["What would you know?"] = "¿Qué sabrías tú?",
    ["What was it like, shattering yourself into pieces?"] = "¿Cómo fue hacerte añicos?",
    ["A difficult question to answer. Take a knife and cut off your toes. Then cut off your fingers. Then your ears and your nose. Your lips, then gouge out your eyes."] = "Una pregunta difícil de responder. Toma un cuchillo y córtate los dedos de los pies. Luego córtate los dedos. Luego tus oídos y tu nariz. Tus labios, luego sácate los ojos.",
    ["I'd really rather not."] = "Realmente preferiría no hacerlo.",
    ["Of course not. But you asked what it was like. It was like ripping myself apart. Cutting off my limbs and tearing off my skin. It was a horrible experience. But a necessary one. As the shards I was only passingly aware of the world around me. Time was meaningless and I had little grasp on events around me. Given all that has happened, it was probably for the best."] = "Por supuesto que no. Pero preguntaste cómo era. Fue como destrozarme. Cortarme las extremidades y arrancarme la piel. Fue una experiencia horrible. Pero uno necesario. Como los fragmentos, sólo era consciente de pasada del mundo que me rodeaba. El tiempo no tenía sentido y tenía poca comprensión de los acontecimientos que me rodeaban. Teniendo en cuenta todo lo sucedido, probablemente fue lo mejor.",
    ["I'd like to talk about Haluned, the Dark Lord."] = "Me gustaría hablar sobre Haluned, el Señor Oscuro.",
    ["Ah, very well, let us dig up painful memories once more."] = "Ah, muy bien, desenterremos recuerdos dolorosos una vez más.",
    ["*(If you did not include the Dark Lord shard as part of Seren:)*"] = "*(Si no incluiste el fragmento del Señor Oscuro como parte de Seren:)*",
    ["What was Haluned?"] = "¿Qué fue Haluned?",
    ["Who was Haluned?"] = "¿Quién fue Haluned?",
    ["I remember very little of Haluned. I remember creating her, taking a piece of my chest and giving it a body of it's own."] = "Recuerdo muy poco de Haluned. Recuerdo haberla creado, tomar un pedazo de mi pecho y darle un cuerpo propio.",
    ["You created life?"] = "¿Tú creaste la vida?",
    ["From nothing? No. It would be better to say that I found a way to exist in two places at once. For a while I was both Haluned and I was Seren."] = "¿De la nada? No. Sería mejor decir que encontré una manera de existir en dos lugares a la vez. Durante un tiempo fui Haluned y Seren.",
    ["Were you aware of what it was doing?"] = "¿Estabas consciente de lo que estaba haciendo?",
    ["I ... I cannot remember."] = "Yo... no puedo recordarlo.",
    ["How do you feel about the Dark lord?"] = "¿Qué sientes por el Señor Oscuro?",
    ["How do you feel about the Dark Lord"] = "¿Qué sientes por el Señor Oscuro?",
    ["Nothing. That part of me is gone. I am sorry for the danger it presented, but that is all I can feel."] = "Nada. Esa parte de mí se ha ido. Lamento el peligro que representó, pero eso es todo lo que puedo sentir.",
    ["How are you going to atone?"] = "¿Cómo vas a expiar?",
    ["I shall do nothing. That part of me has already been destroyed, you saw to that. I shall use it as an example to inspire me to not make such mistake again."] = "No haré nada. Esa parte de mí ya ha sido destruida, tú te ocupaste de eso. Lo usaré como ejemplo para inspirarme a no volver a cometer ese error.",
    ["*(If you did include the Dark Lord shard as part of Seren:)*"] = "*(Si incluiste el fragmento del Señor Oscuro como parte de Seren:)*",
    ["She was a part of me that I allowed to live its own life. It is not a concept I can explain easily. She was me and yet she was not me. Writers talk of characters living their own lives, but lives created from the imagination and experiences of the author. I suppose that best describes what she was. When I shattered myself, she took on the burden of my darker aspects. She became the Dark Lord out of a noble sacrifice. She would be corrupted, so that the rest of my would remain free."] = "Ella era una parte de mí a la que le permití vivir su propia vida. No es un concepto que pueda explicar fácilmente. Ella era yo y, sin embargo, no era yo. Los escritores hablan de personajes que viven sus propias vidas, pero vidas creadas a partir de la imaginación y las experiencias del autor. Supongo que eso describe mejor lo que ella era. Cuando me destrocé, ella asumió la carga de mis aspectos más oscuros. Ella se convirtió en el Señor Oscuro gracias a un noble sacrificio. Ella sería corrompida, para que el resto de mi quedara libre.",
    ["Yes. But only dimly. Like it was happening out of the corner of my eye. I could not stop it, please believe me on that."] = "Sí. Pero sólo vagamente. Como si estuviera sucediendo por el rabillo del ojo. No pude detenerlo, por favor créanme en eso.",
    ["How do you feel about the Dark Lord?"] = "¿Qué opinas del Señor Oscuro?",
    ["Guilty. Ashamed. Are these the words you want to hear? That a god can admit they made mistakes? Had I known what she would have become ... how the Iorwerth would have used her ... I would have done it differently. But then we are all saints when looking through hindsight."] = "Culpable. Avergonzado. ¿Son estas las palabras que quieres escuchar? ¿Que un dios puede admitir que cometió errores? Si hubiera sabido en qué se habría convertido... cómo la habrían utilizado los Iorwerth... lo habría hecho de otra manera. Pero claro, todos somos santos cuando miramos en retrospectiva.",
    ["[More...]"] = "[Más...]",
    ["You pass judgement so quickly. Have I not already atoned? To save my people I tore myself to pieces and scattered myself in the wind. Yes the Dark Lord was a travesty, an abomination, but it was sealed away. It was the Iorwerth and the greed of mortal men that empowered that creature, not I. But to ensure that there will not be another Dark Lord, I will pull myself away from the elves. In time they will no longer need my presence and I can leave them, to be forgotten."] = "Juzgas muy rápido. ¿No he expiado ya? Para salvar a mi pueblo me hice pedazos y me dispersé en el viento. Sí, el Señor Oscuro era una farsa, una abominación, pero estaba sellado. Fue el Iorwerth y la avaricia de los hombres mortales los que dieron poder a esa criatura, no yo. Pero para asegurar que no habrá otro Señor Oscuro, me alejaré de los elfos. Con el tiempo ya no necesitarán mi presencia y podré dejarlos para que sean olvidados.",
    ["I'd like to ask about something else."] = "Me gustaría preguntar sobre algo más.",
    ["*(Returns to the options before the previous ones.)*"] = "*(Vuelve a las opciones anteriores a las anteriores.)*",
    ["That's all for now."] = "Eso es todo por ahora.",
    ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["I'd like to talk about Eluned."] = "Me gustaría hablar sobre Eluned.",
    ["*(If Eluned was saved:)*"] = "*(Si se guardó Eluned:)*",
    ["What was Eluned?"] = "¿Qué era Eluned?",
    ["What is she?"] = "¿Qué es ella?",
    ["She thinks herself your friend. Is that not enough?"] = "Ella se considera tu amiga. ¿No es eso suficiente?",
    ["That's not really what I was asking."] = "Eso no es realmente lo que estaba preguntando.",
    ["No, Indeed. In truth she is simply Eluned, she was created from a memory inside a shard of me. A shard that sang itself into the elven woman you know well. From then her life has been her own."] = "No, de hecho. En verdad ella es simplemente Eluned, fue creada a partir de un recuerdo dentro de un fragmento de mí. Un fragmento que cantó en la mujer elfa que conoces bien. Desde entonces su vida ha sido suya.",
    ["Where has she gone?"] = "¿A dónde ha ido?",
    ["She has decided to visit Tarddiad and see what she can do for the elves there. It is my hope that she can help correct my cruel mistake. I should never have abandoned them."] = "Ha decidido visitar Tarddiad y ver qué puede hacer por los elfos de allí. Tengo la esperanza de que ella pueda ayudarme a corregir mi cruel error. Nunca debí haberlos abandonado.",
    ["But then you'd have never come to Gielinor."] = "Pero entonces nunca habrías venido a Gielinor.",
    ["And I fear my elves would be all the better for it. This world has been the cause of so much pain. I should have stayed with my elves on Tarddiad."] = "Y me temo que mis elfos estarían mucho mejor por ello. Este mundo ha sido la causa de tanto dolor. Debería haberme quedado con mis elfos en Tarddiad.",
    ["*(If Eluned was sacrificed:)*"] = "*(Si Eluned fue sacrificado:)*",
    ["Your friend, or at least she thought so. This is how I would remember her, were I you. Before I shattered myself, just after I created Haluned, I created another. Eluned. Whereas Haluned was intended to be a permanent extension of myself, Eluned was my way of seeing through the eyes of the elves, rather than from above them. She showed me the wonder of my people in a way I never could have imagined. Then she returned to me. The Eluned you remember is as unique a creation as the Dark Lord. A fragment of myself with a memory of a person. A single crystal that remembered how to sing itself into being. It became Eluned. Until I started to reform, she had no idea what she was. She was just an elf, as far as she knew."] = "Tu amiga, o al menos eso creía. Así es como la recordaría, si fuera tú. Antes de destrozarme, justo después de crear Haluned, creé otro. Eluned. Mientras que Haluned pretendía ser una extensión permanente de mí mismo, Eluned era mi forma de ver a través de los ojos de los elfos, en lugar de desde arriba de ellos. Ella me mostró la maravilla de mi pueblo de una manera que nunca hubiera imaginado. Luego ella regresó a mí. El Eluned que recuerdas es una creación tan única como el Señor Oscuro. Un fragmento de mí con un recuerdo de una persona. Un único cristal que recordaba cómo cantar para nacer. Se convirtió en Eluned. Hasta que comencé a reformarme, ella no tenía idea de lo que era. Ella era sólo una elfa, hasta donde ella sabía.",
    ["Can you bring her back?"] = "¿Puedes traerla de vuelta?",
    ["No. The Eluned you know is gone. I could no more separate her from myself than you could separate rainwater from a river. I could create a new Eluned, who looked and acted like the old one, but it would not be her. All I can do is to strive to live up to her sacrifice. To give it meaning."] = "No. El Eluned que conoces ya no existe. No podía separarla de mí más de lo que tú podrías separar el agua de lluvia de un río. Podría crear una nueva Eluned, que se viera y actuara como la anterior, pero no sería ella. Todo lo que puedo hacer es esforzarme por estar a la altura de su sacrificio. Para darle significado.",
    ["How do you feel about her?"] = "¿Qué sientes por ella?",
    ["This is a strange question Player. She is a part of me now, so I cannot feel her loss. I lament the loss of her potential, what she could have been could have been beautiful. But she is a part of me. And a piece I welcome."] = "Esta es una pregunta extraña Player. Ella es parte de mí ahora, así que no puedo sentir su pérdida. Lamento la pérdida de su potencial, lo que ella podría haber sido podría haber sido hermoso. Pero ella es parte de mí. Y una pieza que doy la bienvenida.",
    ["I'd like to talk about something else."] = "Me gustaría hablar de otra cosa.",
    ["I'd like to talk about the other gods."] = "Me gustaría hablar de los otros dioses.",
    ["I'd like to ask about Zaros."] = "Me gustaría preguntar sobre Zaros.",
    ["I would rather not discuss my brother, but if we must. What do you want to know?"] = "Preferiría no hablar de mi hermano, pero si es necesario. ¿Qué quieres saber?",
    ["Did you know that he's returned?"] = "¿Sabías que ha regresado?",
    ["I felt his influence earlier, so yes, I know he's back. My brother and I are made of hardier stuff than the lesser gods, so I was not convinced at his earlier demise. Perhaps 'death' has taught him a little humility. Though I doubt it."] = "Sentí su influencia antes, así que sí, sé que ha vuelto. Mi hermano y yo estamos hechos de un material más resistente que los dioses menores, por lo que no me convenció su anterior desaparición. Quizás la 'muerte' le haya enseñado un poco de humildad. Aunque lo dudo.",
    ["What is your relationship with Zaros?"] = "¿Cuál es tu relación con Zaros?",
    ["He is my brother. The darkness to my light. My polar opposite and the only person ... living ... that can truly understand me. It's complicated really. We were both forged from the dreams of a half-formed elder god. We rather defy the traditional concepts of family that you might be used to."] = "Él es mi hermano. La oscuridad a mi luz. Mi polo opuesto y la única persona... viva... que realmente puede entenderme. Es realmente complicado. Ambos fuimos forjados a partir de los sueños de un dios anciano a medio formar. Más bien desafiamos los conceptos tradicionales de familia a los que usted podría estar acostumbrado.",
    ["Are you two on good terms with each other?"] = "¿Se llevan bien ustedes dos?",
    ["Zaros always has an agenda. He must always be in control. I believe that everyone should govern their own actions. So, no, I suppose we are not on the best of terms."] = "Zaros siempre tiene una agenda. Él siempre debe tener el control. Creo que cada uno debería gobernar sus propias acciones. Entonces no, supongo que no estamos en los mejores términos.",
    ["Should I trust Zaros?"] = "¿Debería confiar en Zaros?",
    ["Only you can make that choice Player. But ask yourself, what is he after? Would he be approaching you if you weren't the World Guardian? Zaros always has an agenda. Think carefully about where you might sit within it."] = "Sólo tú puedes hacer esa elección Player. Pero pregúntate: ¿qué busca? ¿Se acercaría a ti si no fueras el Guardián Mundial? Zaros siempre tiene una agenda. Piense detenidamente dónde podría sentarse dentro de él.",
    ["I'd like to ask about Guthix."] = "Me gustaría preguntar sobre Guthix.",
    ["No ... please. To me it was like he died yesterday. It's still too painful to discuss."] = "No... por favor. Para mí fue como si hubiera muerto ayer. Todavía es demasiado doloroso discutirlo.",
    ["I'm sorry, let me ask something else."] = "Lo siento, déjame preguntarte algo más.",
    ["Did you love him?"] = "¿Lo amabas?",
    ["That word is too small to describe what we had ... I left Tarddiad for him ... I shattered myself rather than bare his disappointment in me. Love is a mortal word, with mortal restrictions. We were more."] = "Esa palabra es demasiado pequeña para describir lo que teníamos... Dejé Tarddiad por él... Me destrocé en lugar de exponer su decepción hacia mí. El amor es una palabra mortal, con restricciones mortales. Éramos más.",
    ["*(Returns to the initial options about gods.)*"] = "*(Vuelve a las opciones iniciales sobre dioses.)*",
    ["I'd like to ask about the Elder Gods."] = "Me gustaría preguntar sobre los Dioses Mayores.",
    ["What are they?"] = "¿Qué son?",
    ["They are the driving force of creation. The origins of all the worlds and the life that dwells amongst them. They feed on the anima mundi of a world and become reborn, cycle after cycle. All the younger gods owe their power to these beings. Even Zaros and myself are born from Mah's restless sleep. To attempt to define them further is to fundamentally fail to understand them and to overthink your position in creation. It would be like describing a dragon to an amoeba. So utterly beyond its understanding."] = "Son la fuerza impulsora de la creación. Los orígenes de todos los mundos y la vida que habita entre ellos. Se alimentan del anima mundi de un mundo y renacen, ciclo tras ciclo. Todos los dioses más jóvenes deben su poder a estos seres. Incluso Zaros y yo nacemos del sueño inquieto de Mah. Intentar definirlos más es fundamentalmente no comprenderlos y pensar demasiado en su posición en la creación. Sería como describir un dragón a una ameba. Totalmente más allá de su comprensión.",
    ["Where are they?"] = "¿Dónde están?",
    ["Come now, you know this answer as well as I do."] = "Vamos, conoces esta respuesta tan bien como yo.",
    ["Yes. Beneath the very ground we stand on, in the heart of this world, sleep the living engines of creation. It is, in part, why this world is so interesting to the younger gods and the other races. Gielinor is a perfect world. A perfect magical crucible of limitless potential. This is, of course, their doing."] = "Sí. Debajo del suelo sobre el que nos encontramos, en el corazón de este mundo, duermen los motores vivientes de la creación. Ésa es, en parte, la razón por la que este mundo es tan interesante para los dioses más jóvenes y las otras razas. Gielinor es un mundo perfecto. Un crisol mágico perfecto de potencial ilimitado. Esto, por supuesto, es obra de ellos.",
    ["How can they be stopped?"] = "¿Cómo se pueden detener?",
    ["In the past I would have said they couldn't, but now ... Guthix felt that if he could carefully control the flow of Anima Mundi, he could keep the elder gods docile and the world thriving. It wasn't until the younger gods interfered with his plans that this changed. I have no answer now, but perhaps I can find one. Come see me when you learn more about the elder gods, perhaps together we can find a solution."] = "En el pasado habría dicho que no podían, pero ahora... Guthix sentía que si podía controlar cuidadosamente el flujo de Anima Mundi, podría mantener dóciles a los dioses mayores y al mundo próspero. No fue hasta que los dioses más jóvenes interfirieron con sus planes que esto cambió. No tengo respuesta ahora, pero tal vez pueda encontrar una. Ven a verme cuando aprendas más sobre los dioses mayores, tal vez juntos podamos encontrar una solución.",
    ["I shall."] = "Lo haré.",
    ["*(Returns to the options before previous ones.)*"] = "*(Vuelve a las opciones anteriores a las anteriores.)*",
    ["But Zaros already has a plan."] = "Pero Zaros ya tiene un plan.",
    ["Oh, of that I have little doubt. But Zaros always has a plan. A plan to see just how much power he can gather. How much control he can wield over the world. My brother cannot be trusted, remember that."] = "Oh, de eso no tengo ninguna duda. Pero Zaros siempre tiene un plan. Un plan para ver cuánto poder puede reunir. Cuánto control puede ejercer sobre el mundo. No se puede confiar en mi hermano, recuérdalo.",
    ["I'd like to ask about the Dragonkin."] = "Me gustaría preguntar sobre Dragonkin.",
    ["I'm afraid I can be of little help there. I have precious little knowledge of the Dragonkin. My brother, on the other hand, was studying them quite carefully."] = "Me temo que puedo ser de poca ayuda en eso. Tengo muy poco conocimiento sobre los Dragonkin. Mi hermano, en cambio, los estudiaba con bastante atención.",
    ["I'd like to ask about Armadyl."] = "Me gustaría preguntar sobre Armadyl.",
    ["You forget, my consciousness has been shattered and spread apart from itself. The Armadyl I remember is a naive idealist who is easily led astray by the machinations of older gods. But time is the ultimate catalyst for change and the Armadyl of today is likely quite different."] = "Lo olvidas, mi conciencia ha sido destrozada y separada de sí misma. El Armadyl que recuerdo es un idealista ingenuo que se deja desviar fácilmente por las maquinaciones de dioses más antiguos. Pero el tiempo es el catalizador definitivo del cambio y el Armadyl de hoy probablemente sea bastante diferente.",
    ["*(If aligned to Armadyl:)*"] = "*(Si está alineado con Armadyl:)*",
    ["Would you consider working with him, Armadyl believes that Gielinor can unite under a banner of peace."] = "¿Considerarías trabajar con él? Armadyl cree que Gielinor puede unirse bajo una bandera de paz.",
    ["Perhaps. But not today. I have too much history to catch up on, before I make any decisions about the future."] = "Quizás. Pero no hoy. Tengo demasiada historia de la que ponerme al día antes de tomar decisiones sobre el futuro.",
    ["I'd like to ask about Bandos."] = "Me gustaría preguntar sobre Bandos.",
    ["A dead god and one whose death I do not mourn. He was a tyrant and a monster, who only wished to see everything bloodied and burnt. He would have burned countless worlds to ash in his pursuit of mindless 'glory'."] = "Un dios muerto y uno cuya muerte no lamento. Era un tirano y un monstruo, que sólo deseaba verlo todo ensangrentado y quemado. Habría quemado innumerables mundos hasta reducirlos a cenizas en su búsqueda de una \"gloria\" sin sentido.",
    ["*(If aligned to Bandos:)*"] = "*(Si está alineado con Bandos:)*",
    ["But don't you see the wisdom in his philosophy? Survival of the fittest is a fundamental trait of nature."] = "¿Pero no ves la sabiduría en su filosofía? La supervivencia del más fuerte es un rasgo fundamental de la naturaleza.",
    ["There's survival and then there is bloodthirsty conquest. Bandos cared more for the latter. His philosophy was an excuse for wanton violence, nothing more."] = "Está la supervivencia y luego está la conquista sanguinaria. Bandos se preocupaba más por este último. Su filosofía era una excusa para la violencia sin sentido, nada más.",
    ["I'd like to ask about Saradomin."] = "Me gustaría preguntar sobre Saradomin.",
    ["Saradomin means well. Even back in the time of the god wars, he genuinely believed he was doing what was best for Gielinor. Misguided, perhaps. Arrogant, certainly. But there is a genuine sense of duty to his actions. That said, his zeal and inability to recognise the wisdom of others, has meant that he has fallen more and more from his path. He can be redeemed, I believe, but that is more your choice than mine."] = "Saradomin tiene buenas intenciones. Incluso en la época de las guerras de los dioses, él realmente creía que estaba haciendo lo mejor para Gielinor. Quizás equivocado. Arrogante, sin duda. Pero hay un genuino sentido del deber hacia sus acciones. Dicho esto, su celo e incapacidad para reconocer la sabiduría de los demás, ha hecho que se haya desviado cada vez más de su camino. Creo que puede ser redimido, pero esa es más tu elección que la mía.",
    ["I'd like to ask about Zamorak."] = "Me gustaría preguntar sobre Zamorak.",
    ["He who tried to kill my brother. I have no positive words for him."] = "El que intentó matar a mi hermano. No tengo palabras positivas para él.",
    ["But I thought you and Zaros didn't get along?"] = "¿Pero pensé que tú y Zaros no se llevaban bien?",
    ["I distrust, despise and sometimes even hate my brother Zaros. But I also love him. Whatever comes between us, whatever trials we face, he is the only brother I will ever have. So forgive me if I dislike someone trying to take him from me."] = "Desconfío, desprecio y a veces incluso odio a mi hermano Zaros. Pero también lo amo. Independientemente de lo que se interponga entre nosotros, sean cuales sean las pruebas que enfrentemos, él es el único hermano que tendré. Así que perdóname si no me gusta que alguien intente quitármelo.",
    ["*(If aligned to Zamorak:)*"] = "*(Si está alineado con Zamorak:)*",
    ["But surely you see the wisdom in his philosophy? We improve only in response through chaos."] = "¿Pero seguramente ves la sabiduría en su filosofía? Mejoramos sólo en respuesta a través del caos.",
    ["Order brings only stagnation."] = "El orden sólo trae estancamiento.",
    ["Perhaps, but there is also imagination and community. When sharing with others, we can learn to see the world differently. Look at all my elves accomplished. It was undone for a time because of chaos. It was harmony that restored them."] = "Quizás, pero también hay imaginación y comunidad. Al compartir con los demás, podemos aprender a ver el mundo de manera diferente. Mira todos mis elfos logrados. Se deshizo por un tiempo debido al caos. Fue la armonía la que los restauró.",
    ["I'd like to ask about Sliske."] = "Me gustaría preguntar sobre Sliske.",
    ["I'd like to talk about Sliske."] = "Me gustaría hablar sobre Sliske.",
    ["I will not discuss the man who murdered my ... my Guthix. I have been a pacifist. Refusing to turn my power to destruction ... But if I meet him ... I will remind him how light can burn."] = "No hablaré del hombre que asesinó a mi... mi Guthix. He sido pacifista. Negarme a convertir mi poder en destrucción... Pero si lo encuentro... Le recordaré cómo la luz puede arder.",
    ["I'd like to ask about Brassica Prime."] = "Me gustaría preguntar sobre Brassica Prime.",
    ["Ah yes. The god of cabbage. I must say I'm pleased he's still around. The younger gods are so full of fury, duty and a stoic seriousness, it is nice to see one who lives in a world of whimsey."] = "Ah, sí. El dios del repollo. Debo decir que me alegro de que todavía esté por aquí. Los dioses más jóvenes están tan llenos de furia, deber y una seriedad estoica que es agradable ver a uno que vive en un mundo de fantasía.",
    ["But what does he even do? I mean he just seems ... well nuts."] = "¿Pero qué hace? Quiero decir que simplemente parece... bueno, loco.",
    ["Yes, I suppose he does. But remember that he sees the world through the eyes of a cabbage. Plants have different priorities to the rest of us. In his own way he tends to the anima mundi, helping to keep it healthy and bountiful."] = "Sí, supongo que sí. Pero recuerda que él ve el mundo a través de los ojos de una col. Las plantas tienen prioridades diferentes a las del resto de nosotros. A su manera, cuida el anima mundi, ayudando a mantenerla sana y abundante.",
    ["So he helps the anima mundi?"] = "¿Entonces ayuda al anima mundi?",
    ["In his own, insane, little way. It's why we remain friends. I have memories of him chatting away to the pieces of me across the world. Of course he didn't understand that I was incomplete and took my silence to be deep rapture in his bizarre monologue. There are only so many different ways to hear about how delicious a cabbage is before you start going mad from boredom."] = "A su manera, loca y pequeña. Por eso seguimos siendo amigos. Tengo recuerdos de él charlando con mis partes en todo el mundo. Por supuesto, él no entendió que yo estaba incompleto y tomó mi silencio como un profundo éxtasis en su extraño monólogo. Hay muchas maneras diferentes de escuchar lo delicioso que es el repollo antes de que empieces a volverte loco de aburrimiento.",
    ["I'd like to talk about the future."] = "Me gustaría hablar sobre el futuro.",
    ["I'd like to talk about the future. What will you do now?"] = "Me gustaría hablar sobre el futuro. ¿Qué harás ahora?",
    ["Now, I shall withdraw from the elves. It is time that I found a way to remove their dependance on me. I shall remain here, in this tower, out of the way and reflect on the choices that has led to this situation. Since the danger of the elder gods is here and ever present, I shall consider them too."] = "Ahora, me retiraré de los elfos. Es hora de que encuentre una manera de eliminar su dependencia de mí. Permaneceré aquí, en esta torre, apartado y reflexionaré sobre las decisiones que han llevado a esta situación. Dado que el peligro de los dioses mayores está aquí y siempre presente, también los consideraré.",
    ["So that's it, you'll just sit here and think?"] = "Entonces eso es todo, ¿te sentarás aquí y pensarás?",
    ["You trivialise it quite well there. Thought is useless without action, this is true, but action without thought can be a dangerous thing. I have made that mistake before, I shall not do so again."] = "Lo trivializas bastante bien ahí. El pensamiento es inútil sin acción, esto es cierto, pero la acción sin pensamiento puede ser algo peligroso. Ya cometí ese error antes, no lo volveré a hacer.",
    ["I'd like to talk about your history."] = "Me gustaría hablar de tu historia.",
    ["I'd like to talk about your history"] = "Me gustaría hablar de tu historia.",
    ["So like mortals, dwelling on what was rather than focus on what is to come. Very well, what do you want to know?"] = "Así que, como los mortales, nos concentramos en lo que fue en lugar de centrarnos en lo que está por venir. Muy bien, ¿qué quieres saber?",
    ["What was your role in the god wars?"] = "¿Cuál fue tu papel en las guerras de los dioses?",
    ["For the most part I stayed well away from it. I knew that Zamorak had not truly destroyed Zaros, so I curtailed my wrath. I had promised Guthix a peaceful world, after all. As the fighting grew more widespread, I sent a few scouts to investigate. Some were discovered and fought to survive. They did not. Some of my people screamed for vengeance, but I forbade it. A few went anyway, but their impact on the war was negligible."] = "La mayor parte del tiempo me mantuve alejado de eso. Sabía que Zamorak realmente no había destruido a Zaros, así que reduje mi ira. Después de todo, le había prometido a Guthix un mundo pacífico. A medida que los combates se generalizaron, envié algunos exploradores a investigar. Algunos fueron descubiertos y lucharon por sobrevivir. No lo hicieron. Algunos de mi pueblo clamaron venganza, pero yo se lo prohibí. Algunos fueron de todos modos, pero su impacto en la guerra fue insignificante.",
    ["I'd like to ask about your history with the elves."] = "Me gustaría preguntarte sobre tu historia con los elfos.",
    ["What was Tarddiad like?"] = "¿Cómo era Tarddiad?",
    ["Stunning. A world of trees and beautiful crystalline structures. The elves lived in harmony with it, growing their houses from seeds. They lived as part of the ecosystem, rather than exploiting it. I often think that I should never have left it."] = "Impresionante. Un mundo de árboles y hermosas estructuras cristalinas. Los elfos vivían en armonía con él y cultivaban sus casas a partir de semillas. Vivían como parte del ecosistema, en lugar de explotarlo. A menudo pienso que nunca debería haberlo dejado.",
    ["Tell me about elven longevity."] = "Háblame de la longevidad de los elfos.",
    ["My greatest mistake. The lifespan of my elves was so short. A few decades, barely a century, and then they were gone. Understand, World Guardian, that to me these were my children. Each one that died was a grief I could barely contain. It was out of love for them that I tried to share with them some of my longevity. My immortality. It worked ... but at a price. They were bound to me. Unable to leave my presence without growing sick and dying. It was why I had to shatter myself, rather than leave them. I am not proud of this mistake, Player. If I could undo it, I would."] = "Mi mayor error. La vida útil de mis elfos era muy corta. Unas cuantas décadas, apenas un siglo, y luego desaparecieron. Entiende, Guardián Mundial, que para mí estos eran mis hijos. Cada uno de los que morían era un dolor que apenas podía contener. Fue por amor a ellos que traté de compartir con ellos algo de mi longevidad. Mi inmortalidad. Funcionó... pero a un precio. Estaban atados a mí. Incapaz de abandonar mi presencia sin enfermar y morir. Por eso tuve que destrozarme, en lugar de dejarlos. No estoy orgulloso de este error, Player. Si pudiera deshacerlo, lo haría.",
    ["How do you feel about the clans?"] = "¿Qué opinas de los clanes?",
    ["When I first discovered the nine clans on Tarddiad, I was enamoured with their society. Everyone took their place within the clan and worked for the betterment of the elven people. The Cadarn were the scouts and mages who scoured the many forests for potential danger. The Iorwerth were great warriors who fought the dangerous beasts that hid amongst the trees. The Meilyr and Crwys both worked in harmony with nature to find medicines and grow food. The Ithell and Trahaearn worked tirelessly to create houses, tools and anything else that was needed. And the Hefin and Amlodd focused on more spiritual pursuits. Seeking ways of enlightenment for their people."] = "Cuando descubrí por primera vez los nueve clanes de Tarddiad, me enamoré de su sociedad. Todos ocuparon su lugar dentro del clan y trabajaron para el mejoramiento del pueblo elfo. Los Cadarn eran los exploradores y magos que recorrían los numerosos bosques en busca de peligros potenciales. Los Iorwerth eran grandes guerreros que luchaban contra las peligrosas bestias que se escondían entre los árboles. Tanto los Meilyr como los Crwy trabajaron en armonía con la naturaleza para encontrar medicinas y cultivar alimentos. Los Ithell y Trahaearn trabajaron incansablemente para crear casas, herramientas y todo lo que fuera necesario. Y Hefin y Amlodd se centraron en actividades más espirituales. Buscando caminos de iluminación para su pueblo.",
    ["You said nine clans?"] = "¿Dijiste nueve clanes?",
    ["Yes. There was also the Cywir. A clan dedicated to elven traditions. They kept the lore of the old people and they maintained the shrines to the elven spirits. They ... would not come with me to Gielinor."] = "Sí. También estaba el Cywir. Un clan dedicado a las tradiciones élficas. Mantuvieron la tradición de los ancianos y mantuvieron los santuarios de los espíritus elfos. Ellos... no quisieron venir conmigo a Gielinor.",
    ["I'd like to ask about your life on Freneskae."] = "Me gustaría preguntarte sobre tu vida en Freneskae.",
    ["Mah was, in many ways, both my mother and my child. She dreamed me into existence so that Zaros would not leave her. I believe she felt that a companion, an equal, would keep Zaros happy. But we were the creation of a child. One who could not understand the complexity of sentient emotion. In me she created an ... ability. It would impose upon others a twisted sense of what she understood as love. Zaros was compelled to be in love with me, just as his nature compelled loyalty in me. But it was a hollow feeling and to each of us it felt like chains holding us against our will. Love is as deadly an emotion as it is a wondrous one. Just as it can bring people together, it can lead to unbearable pain and a complete loss of self. I do not blame him for wanting to escape that. But he wanted more than to escape, he wanted to ascend. Zaros tries to control everything around him. He tried to control me, even as I unconsciously controlled him. Power as great as he wishes to attain, should not go to someone like that."] = "Mah fue, en muchos sentidos, mi madre y mi hija. Ella soñó que yo existiera para que Zaros no la abandonara. Creo que sentía que un compañero, un igual, mantendría feliz a Zaros. Pero éramos la creación de un niño. Alguien que no podía comprender la complejidad de las emociones sensibles. En mí ella creó una... habilidad. Impondría a los demás un sentido retorcido de lo que ella entendía como amor. Zaros se vio obligado a enamorarse de mí, del mismo modo que su naturaleza me imponía lealtad. Pero era un sentimiento vacío y para cada uno de nosotros lo sentíamos como cadenas que nos mantenían contra nuestra voluntad. El amor es una emoción tan mortal como maravillosa. Así como puede unir a las personas, puede provocar un dolor insoportable y una pérdida total de uno mismo. No lo culpo por querer escapar de eso. Pero quería más que escapar: quería ascender. Zaros intenta controlar todo lo que le rodea. Intentó controlarme, incluso cuando yo inconscientemente lo controlaba a él. El poder que desee alcanzar no debería recaer en alguien así.",
    ["*(Only if not selected last, and Children of Mah has been completed:)*"] = "*(Solo si no se seleccionó en último lugar y se completó Children of Mah :)*",
    ["I'd like to talk about Children of Mah."] = "Me gustaría hablar sobre Children of Mah.",
    ["Ask about Mah."] = "Pregunta por Mah.",
    ["Everything I have, everything I am, was given to me by Mah; my life is Mah's, my being is Mah's, my strength is Mah's. She was more than a mother to us, yet Zaros saw her as a distant relative. He waited for her to pass, hoping for an inheritance. I would be angry with him, if I wasn't already busy with my own grief and guilt. They're not fun to be around, I can promise you. I am planning to visit Mah again - soon, if the events of this world will allow it. My elves observe a particular funeral rite, and I would like to bring my lords and ladies to Freneskae to perform it. A crystal seed will be placed in her mouth. This seed will represent the death of her voice, but the continuation of her song. For as long as is possible, we will visit her, and continue her memory by singing. The seed will grow, and will fill her body with crystal flowers. I have always loves the sentiment: that a person's memory can grow, rather than shrink away. I would like that to be true of me, when I pass. I will make sure my lords and ladies know that this is my desire."] = "Todo lo que tengo, todo lo que soy, me lo dio Mah; mi vida es de Mah, mi ser es de Mah, mi fuerza es de Mah. Ella era más que una madre para nosotros, pero Zaros la veía como una pariente lejana. Esperó a que ella falleciera, esperando recibir una herencia. Estaría enfadada con él si no estuviera ya ocupada con mi propio dolor y culpa. No es divertido estar con ellos, te lo prometo. Estoy planeando visitar Mah nuevamente, pronto, si los acontecimientos de este mundo lo permiten. Mis elfos observan un rito funerario particular y me gustaría llevar a mis señores y damas a Freneskae para realizarlo. Le colocarán una semilla de cristal en la boca. Esta semilla representará la muerte de su voz, pero la continuación de su canto. Mientras sea posible la visitaremos y continuaremos su memoria cantando. La semilla crecerá y llenará su cuerpo de flores de cristal. Siempre me ha encantado ese sentimiento: que la memoria de una persona puede crecer, en lugar de disminuir. Me gustaría que eso fuera cierto para mí cuando muera. Me aseguraré de que mis señores y damas sepan que este es mi deseo.",
    ["Ask about Zaros."] = "Pregunta por Zaros.",
    ["We have rarely been close, Zaros and I. As a brother of sorts, he kept me at arm's length. As a god, even more so. That has never been a problem. My interests have been far from his, and he has - largely - kept his armies to himself. But he knew, and knew very well, that the one common ground we had was Mah. And while he was indifferent to her, he knew that I loved her. He knew that by hurting Mah, he was hurting me. It's undoubted: Zaros's favourite hobby is to calculate how the world will change to his every whim and action. The magnitude of his indifference makes me sick. I could almost feel the boot in my face as he stepped to victory."] = "Rara vez hemos sido cercanos, Zaros y yo. Como una especie de hermano, él me mantuvo a distancia. Como dios, más aún. Eso nunca ha sido un problema. Mis intereses han estado lejos de los suyos y él, en gran medida, se ha reservado sus ejércitos. Pero él sabía, y sabía muy bien, que el único punto en común que teníamos era Mah. Y aunque él le era indiferente, sabía que yo la amaba. Sabía que al lastimar a Mah, me estaba lastimando a mí. Es indudable: el pasatiempo favorito de Zaros es calcular cómo cambiará el mundo según cada uno de sus caprichos y acciones. La magnitud de su indiferencia me enferma. Casi podía sentir la bota en mi cara mientras avanzaba hacia la victoria.",
    ["Ask about the Mahjarrat."] = "Pregunta por el Mahjarrat.",
    ["What is there to say about the Mahjarrat other than 'I am sorry' and 'I would not do the same again? I worry that I will forever be known as the God of Regret. It's like I was last in line for godhood: Zamorak has taken Chaos, and now I must be the God of Remorse and Wistful Thoughts. Regardless, I feel intensely that I did wrong. I have not figured out how I can right that wrong, but I will. I may start by talking to Kharshai. He was always the most-level headed of the Mahjarrat, and I feel that has not changed. Reparations must be paid, and I am not one to renege on a debt."] = "¿Qué se puede decir sobre el Mahjarrat aparte de \"lo siento\" y \"no volvería a hacer lo mismo\"? Me preocupa que siempre seré conocido como el Dios del arrepentimiento. Es como si fuera el último en la fila para convertirse en dios: Zamorak se ha apoderado del Caos, y ahora debo ser el Dios del remordimiento y los pensamientos nostálgicos. De todos modos, siento intensamente que hice mal. No he descubierto cómo puedo corregir ese error, pero lo haré. Puedo empezar hablando con Kharshai. Siempre fue el más sensato de Mahjarrat y siento que eso no ha cambiado. Hay que pagar reparaciones y no soy de los que incumplen una deuda.",
    ["I'm afraid you're a bit early for the meeting."] = "Me temo que llegas un poco temprano a la reunión.",
    ["Tell me about the Lumbridge Guardsmen."] = "Cuéntame sobre el Lumbridge Guardsmen.",
    ["I spoke to a few people who asked me about joining the Lumbridge Guardsmen. To be asked, you need to be a true local. I mean, when the call to arms is raised, you don't want your troops to be scattered across the world: they need to be waiting here, ready to spring in to action."] = "Hablé con algunas personas que me preguntaron acerca de unirme a Lumbridge Guardsmen. Para que te pregunten, debes ser un verdadero local. Quiero decir, cuando se levanta el llamado a las armas, no quieres que tus tropas se dispersen por todo el mundo: deben estar esperando aquí, listas para entrar en acción.",
    ["What is there to do around here?"] = "¿Qué hay que hacer por aquí?",
    ["If you'd like to make a bit of spending money, try speaking to the skill tutors. They go through a lot of supplies, so I'm sure they'd be happy to pay you to make the supplies they need."] = "Si quieres ganar un poco de dinero, intenta hablar con los tutores de habilidades. Usan muchos suministros, así que estoy seguro de que estarán felices de pagarte para que fabriques los suministros que necesitan.",
    ["If you're interested in learning to make leather armour, there's the cow field to get hides, and through the eastern tollgate you can reach the tanner and Crafting Shop."] = "Si estás interesado en aprender a hacer armaduras de cuero, está el campo de vacas para conseguir pieles y, a través del peaje del este, puedes llegar al curtidor y a la tienda Crafting.",
    ["Tell me about Lumbridge."] = "Háblame de Lumbridge.",
    ["It used to be much nicer here, before the goblins overran the east side of town. You'd think that the Guardsmen would be sent to flush them out, but for every one we slay, three more appear in its place."] = "Solía ser mucho más bonito aquí, antes de que los duendes invadieran el lado este de la ciudad. Uno pensaría que enviarían a los guardias para expulsarlos, pero por cada uno que matamos, aparecen tres más en su lugar.",
    ["If I'm honest, I don't much care for it here. I understand why so many do enjoy the lifestyle, but I long for the city life. If I do well in my job here, perhaps I could move to Varrock, or Falador, and join the guards there."] = "Si soy honesto, no me importa mucho esto aquí. Entiendo por qué tanta gente disfruta de este estilo de vida, pero yo añoro la vida en la ciudad. Si hago bien mi trabajo aquí, tal vez podría mudarme a Varrock o Falador y unirme a los guardias allí.",
    ["I suppose it's a good place to find your feet in the world. There's reasonable fishing in the river, and with lots of farmland around it's rare that you go hungry. Yes, there's plenty worse places you could live in than Lumbridge."] = "Supongo que es un buen lugar para encontrar tu lugar en el mundo. Se puede pescar razonablemente en el río y, con muchas tierras de cultivo alrededor, es raro pasar hambre. Sí, hay muchos lugares peores en los que podrías vivir que Lumbridge.",
    ["What exactly are you guarding?"] = "¿Qué estás protegiendo exactamente?",
    ["Peace, happiness, tranquillity, that sort of thing. So, let me know if you see anything upsetting. Dragons in cellars, goblins under beds, that sort of thing."] = "Paz, felicidad, tranquilidad, ese tipo de cosas. Entonces, avíseme si ve algo molesto. Dragones en sótanos, duendes debajo de las camas, ese tipo de cosas.",
    ["I suppose I'm guarding the castle, and the Lumbridge way of life. Although, there was once a dragon near here, and I helped defend the castle from it. That was an exciting time!"] = "Supongo que estoy protegiendo el castillo y el estilo de vida de Lumbridge. Aunque una vez hubo un dragón cerca de aquí y yo ayudé a defender el castillo de él. ¡Ese fue un momento emocionante!",
    ["*When speaking to Sergeant Damien in Balthazar's Big Top Bonanza:*"] = "*Al hablar con Sergeant Damien en Balthazar's Big Top Bonanza:*",
    ["*Sergeant Damien may say any one of the following at random:*"] = "*Sergeant Damien puede decir cualquiera de las siguientes palabras al azar:*",
    ["Someone should whip these recruits into shape."] = "Alguien debería poner en forma a estos reclutas.",
    ["Yes, sir!"] = "¡Sí, señor!",
    ["Are you eyeballin' me, [boy/girl]?"] = "¿Me estás mirando, [boy/girl]?",
    ["No, sir!"] = "¡No, señor!",
    ["What a snivelling pile of maggots!"] = "¡Qué montón de gusanos lloriqueantes!",
    ["What is your major malfunction?"] = "¿Cuál es su principal falla?",
    ["I wasn't aware I had one, sir!"] = "¡No sabía que tenía uno, señor!",
    ["It's like a circus in here!"] = "¡Es como un circo aquí!",
    ["At ease, soldier; I'm not on duty."] = "Tranquilo, soldado; No estoy de servicio.",
    ["Then what are you doing here, Sergeant Damien, sir, if I might ask?"] = "Entonces, ¿qué hace aquí, Sergeant Damien, señor, si puedo preguntar?",
    ["Balthazar's a buddy of mine, from my old unit. After the war - you know, THE war - old BB retired to civilian life; set up this little carnival of his."] = "Balthazar es un amigo mío, de mi antigua unidad. Después de la guerra (ya sabes, LA guerra), el viejo BB se retiró a la vida civil; montó este pequeño carnaval suyo.",
    ["Now my drill sergeant days are behind me, he offered me a job here as a roustie."] = "Ahora que mis días de sargento instructor quedaron atrás, me ofreció un trabajo aquí como peón.",
    ["A roustie? What's that?"] = "¿Un peón? ¿Qué es eso?",
    ["A roustabout, boy; a roughneck; a handyman!"] = "Un peón, muchacho; un matón; ¡un manitas!",
    ["I keep all the equipment in good repair, do all the manual labour, and - best of all - I get to keep the audience in line! There's no better work for an old soldier like me."] = "Mantengo todo el equipo en buen estado, hago todo el trabajo manual y, lo mejor de todo, ¡puedo mantener a la audiencia en línea! No hay mejor trabajo para un viejo soldado como yo.",
    ["*As Sergeant Damien walks around, he repeats several overhead messages in short patterns.*"] = "*Mientras Sergeant Damien camina, repite varios mensajes en patrones cortos.*",
    ["*Each pattern always starts with the same overhead message:*"] = "*Cada patrón siempre comienza con el mismo mensaje general:*",
    ["*The pattern is then followed by one of the following at random:*"] = "*El patrón es seguido por uno de los siguientes al azar:*",
    ["*The pattern is then followed by another segment that always starts with:*"] = "*El patrón es seguido por otro segmento que siempre comienza con:*",
    ["*The second segment then continues with one of the following at random:*"] = "*El segundo segmento continúa con uno de los siguientes al azar:*",
    ["*The pattern always ends in the same overhead message, before repeating from the start, once again randomizing:*"] = "*El patrón siempre termina con el mismo mensaje general, antes de repetirse desde el principio, una vez más de forma aleatoria:*",
    ["*When talking to Sergeant Wadjmos at the Golden Palace throne room in Menaphos*"] = "*Al hablar con Sergeant Wadjmos en el salón del trono del Palacio Dorado en Menaphos*",
    ["There is a disturbing trend of soldiers deserting the guard and becoming thugs. This development is utterly unacceptable and must be addressed immediately, although I can't blame them!"] = "Hay una tendencia inquietante de soldados que abandonan la guardia y se convierten en matones. Esta evolución es absolutamente inaceptable y debe abordarse de inmediato, ¡aunque no puedo culparlos!",
    ["Want something?"] = "¿Quieres algo?",
    ["I'm the Sergeant-at-Arms. I organise Rated Clan Wars matches."] = "Soy el Sergeant-at-Arms. Organizo partidas de Guerras de clanes puntuadas.",
    ["You look like you've seen combat."] = "Parece que has visto un combate.",
    ["I was here at the Siege of Falador. A lot of people died. I didn't."] = "Estuve aquí en el asedio de Falador. Mucha gente murió. No lo hice.",
    ["I'd like to know more about Rated Clan Wars."] = "Me gustaría saber más sobre Rated Clan Wars.",
    ["Rated Clan Wars is a pitched battle between two clans. You need to be in a clan to take part, and you need a Rated Clan Wars badge."] = "Rated Clan Wars es una batalla campal entre dos clanes. Debes estar en un clan para participar y necesitas una insignia de Rated Clan Wars.",
    ["*If the player has Rcw rules in the inventory:*"] = "*Si el player tiene reglas Rcw en el inventario:*",
    ["*If the player does not have Rcw rules in the inventory:*"] = "*Si el player no tiene reglas Rcw en el inventario:*",
    ["There's a rulebook if you want to know more."] = "Hay un libro de reglas si quieres saber más.",
    ["Would you like a copy of the rulebook?"] = "¿Quieres una copia del libro de reglas?",
    ["The sergeant gives you a copy of the rulebook."] = "El sargento te entrega una copia del libro de reglas.",
    ["I need a Rated Clan Wars badge."] = "Necesito una insignia de Guerras de clanes clasificadas.",
    ["*If the player is not in a clan:*"] = "*Si el player no está en un clan:*",
    ["You need to be in a clan to get a badge. I can't just give them out to just anyone. Talk to the clan scribe over there. He can help you set up a clan."] = "Debes estar en un clan para obtener una insignia. No puedo dárselos a cualquiera. Habla con el escriba del clan que está allí. Él puede ayudarte a crear un clan.",
    ["*If the player is in a clan:*"] = "*Si el player está en un clan:*",
    ["*If the player does not have an Rcw badge in the inventory:*"] = "*Si el player no tiene una insignia Rcw en el inventario:*",
    ["The sergeant hands you an RCW badge."] = "El sargento le entrega una placa de RCW.",
    ["*If the player has an Rcw badge in the inventory:*"] = "*Si el player tiene una insignia Rcw en el inventario:*",
    ["You've already got a badge. Don't waste my time."] = "Ya tienes una insignia. No me hagas perder el tiempo.",
    ["See you around."] = "Nos vemos por ahí.",
    ["Dialogue 4"] = "Diálogo 4",
    ["Dialogue 5"] = "Diálogo 5",
    ["Dialogue 6"] = "Diálogo 6",
    ["Dialogue 7"] = "Diálogo 7",
    ["Dialogue 8"] = "Diálogo 8",
    ["Dialogue 9"] = "Diálogo 9",
    ["Dialogue 10"] = "Diálogo 10",
    ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
    ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
    ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
    ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
    ["You're more than welcome."] = "De nada.",
    ["Not that it makes much difference but my name's Sergiu. Like all the other survivors here, I just try to make do and get through life one day at a time."] = "No es que haga mucha diferencia, pero mi nombre es Sergiu. Como todos los demás supervivientes aquí, sólo trato de arreglármelas y vivir la vida día a día.",
    ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
    ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
    ["What's happening around here?"] = "¿Qué está pasando por aquí?",
    ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
    ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
    ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
    ["Excuse me, sir."] = "Disculpe, señor.",
    ["Yes?"] = "¿Sí?",
    ["I am Serjeant Cole, an officer of A.R.M.S. for 4 years, I'll have you know."] = "Soy Serjeant Cole, un oficial de A.R.M.S. durante 4 años, te lo haré saber.",
    ["What's 'arms', except for handy limbs?"] = "¿Qué es \"brazos\", excepto extremidades prácticas?",
    ["The Army Recruitment and Mobilisation Society. We're here to make sure that all war heroes and warriors can earn a living through honourable combat."] = "Sociedad de Reclutamiento y Movilización del Ejército. Estamos aquí para asegurarnos de que todos los héroes y guerreros de guerra puedan ganarse la vida mediante un combate honorable.",
    ["It's a job of great responsibility that you could learn from."] = "Es un trabajo de gran responsabilidad del que podrías aprender.",
    ["You seem very proud."] = "Pareces muy orgulloso.",
    ["Naturally. There is no higher honour."] = "Naturalmente. No hay mayor honor.",
    ["Can I exchange my reward credits?"] = "¿Puedo canjear mis créditos de recompensa?",
    ["So, you're a man of combat, are you? I've a selection of reward items and spoils of war. I can also imbue rings."] = "Entonces eres un hombre de combate, ¿verdad? Tengo una selección de artículos de recompensa y botín de guerra. También puedo imbuir anillos.",
    ["Reward items. *[opens interface]*"] = "Artículos de recompensa. *[opens interface]*",
    ["Spoils of war. *[opens interface]*"] = "Botín de guerra. *[opens interface]*",
    ["Imbue rings."] = "Imbuir anillos.",
    ["I can imbue gold rings for you, giving you additional combat boosts. It'll cost 37,100 reward credits."] = "Puedo imbuirte anillos de oro, dándote mejoras de combate adicionales. Costará 37.100 créditos de recompensa.",
    ["I've changed my mind."] = "He cambiado de opinión.",
    ["Can I change my rank prefix please?"] = "¿Puedo cambiar mi prefijo de rango, por favor?",
    ["Of course. What rank prefix would you like?"] = "Por supuesto. ¿Qué prefijo de rango te gustaría?",
    ["Sorry, I thought you were someone else."] = "Lo siento, pensé que eras otra persona.",
    ["Look, I'd better not talk. I'll get in trouble."] = "Mira, será mejor que no hable. Me meteré en problemas.",
    ["If you want someone to show you round the castle ask Eohric, the Head Servant."] = "Si quieres que alguien te muestre el castillo, pregúntale a Eohric, el sirviente principal.",
    ["You'd better get Evil Bob some supper or he might make you his new slave."] = "Será mejor que le traigas algo de cenar a Evil Bob o podría convertirte en su nuevo esclavo.",
    ["How do I do that?"] = "¿Cómo hago eso?",
    ["Just use one of the fishing spots on the coast - any of them will do - and catch something. Then use the pots here to prepare the meal, and feed it to Evil Bob."] = "Simplemente use uno de los lugares de pesca en la costa (cualquiera de ellos servirá) y pesque algo. Luego usa las ollas aquí para preparar la comida y dásela a Evil Bob.",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Okay, but don't hang around too long or Evil Bob might force you to!"] = "Está bien, ¡pero no te quedes demasiado tiempo o Evil Bob podría obligarte a hacerlo!",
    ["Thanks for feeding him and putting him to sleep."] = "Gracias por alimentarlo y ponerlo a dormir.",
    ["You should escape while you can."] = "Deberías escapar mientras puedas.",
    ["Oh, I wasn't trapped here. I could have left at anytime. You should escape now, though."] = "Oh, no estaba atrapado aquí. Podría haberme ido en cualquier momento. Aunque deberías escapar ahora.",
    ["Oh, that's okay. It's not so bad here."] = "Oh, está bien. Aquí no está tan mal.",
    ["You do know where 'here' is, though, don't you?"] = "Pero sí sabes dónde está \"aquí\", ¿no?",
    ["Of course - this is ScapeRune! It's a sort of mirror dimension to your world... but like one designed by someone who didn't fully understand the word 'opposite'."] = "Por supuesto, ¡esto es ScapeRune! Es una especie de dimensión reflejada de su mundo... pero como una diseñada por alguien que no entendió completamente la palabra \"opuesto\".",
    ["Believe me, I used to want for nothing more than to escape, but Evil Bob... well, he's not so bad; he's grown on me."] = "Créeme, no quería nada más que escapar, pero Evil Bob... bueno, no es tan malo; él ha crecido en mí.",
    ["He lets me explore the island sometimes, he strokes my hair..."] = "A veces me deja explorar la isla, me acaricia el pelo...",
    ["... plus I should be getting my new litter tray soon!"] = "... ¡Además, pronto debería recibir mi nueva bandeja de arena!",
    ["I think you might have been here too long. You've become conditioned to your - um - conditions."] = "Creo que quizás hayas estado aquí demasiado tiempo. Te has condicionado a tus... um... condiciones.",
    ["Maybe so, but at least I'm happy now. How many people can truly say that?"] = "Tal vez sea así, pero al menos ahora soy feliz. ¿Cuánta gente puede realmente decir eso?",
    ["Farewell!"] = "¡Adiós!",
    ["Hi there. I don't suppose you could help me find something to keep Evil Bob entertained? Something shiny."] = "Hola. ¿Supongo que no podrías ayudarme a encontrar algo para mantener entretenido a Evil Bob? Algo brillante.",
    ["Well, Evil Bob really likes his balls of wool. And all of the shinies, gold is his favourite."] = "Bueno, a Evil Bob realmente le gustan sus ovillos de lana. Y de todos los brillantes, el dorado es su favorito.",
    ["So if I can just find some golden wool then, he should be happy?"] = "Entonces, si puedo encontrar un poco de lana dorada, ¿él debería estar feliz?",
    ["Yep! He might even set you free."] = "¡Sí! Incluso podría liberarte.",
    ["But I'm already free."] = "Pero ya soy libre.",
    ["That's what they all say."] = "Eso es lo que todos dicen.",
    ["M'arnin'....going to milk me cowsies!"] = "Buenos días.... ¡voy a ordeñarme, vacas!",
    ["I have a free Shadow Gem Shard for you here. But you don't have space for it!"] = "Aquí tengo un fragmento de gema de las sombras gratis para ti. ¡Pero no tienes espacio para ello!",
    ["Hey there! Here's a free Shadow Gem Shard!"] = "¡Hola! ¡Aquí tienes un fragmento de gema de las sombras gratis!",
    ["Can I interest you in something from the Shadow Gem Shop?"] = "¿Puedo interesarte en algo de Shadow Gem Shop?",
    ["You can get more Shadow Gem Shards from the Crystal Capsules Treasure Hunter Promotion."] = "Puedes obtener más fragmentos de gemas de las sombras de la promoción Crystal Capsules Treasure Hunter.",
    ["A shadow rift has appeared on the ritual site!"] = "¡Ha aparecido un shadow rift en el sitio del ritual!",
    ["The shadow rift has been successfully closed!"] = "¡El shadow rift se ha cerrado con éxito!",
    ["Hello, stranger."] = "Hola, extraño.",
    ["*If the player doesn't have all the pieces of the First age outfit:*"] = "*Si el player no tiene todas las piezas del outfit de Primera edad:*",
    ["Got somethin' that might interest ya, stranger. He he he."] = "Tengo algo que podría interesarte, extraño. Je je je.",
    ["What're you sellin'?"] = "¿Qué estás vendiendo?",
    ["Got some real old trinkets, accessories if you like. Holy. Might help you train your inner powers. Yours for 1,000 ecto-tokens."] = "Tengo algunas baratijas antiguas y accesorios si quieres. Santo. Podría ayudarte a entrenar tus poderes internos. Tuyo por 1.000 ecto-tokens.",
    ["*(If the player has at least 1,000 ecto-tokens:)*"] = "*(Si el player tiene al menos 1000 ecto-tokens:)*",
    ["Purchase a piece of the first-age outfit for 1,000 ecto-tokens?"] = "¿Comprar una pieza del traje de la primera edad por 1000 ecto-tokens?",
    ["I'll take one!"] = "¡Me llevaré uno!",
    ["You purchase a piece of the first-age outfit from the ghost."] = "Le compras una pieza del traje de la primera edad al fantasma.",
    ["All yours. Goodbye, stranger."] = "Todo tuyo. Adiós, extraño.",
    ["Erm, no thanks."] = "Emmm, no gracias.",
    ["*(If the player has less than 1,000 ecto-tokens:)*"] = "*(Si el player tiene menos de 1000 ecto-tokens:)*",
    ["It doesn't look like I have enough. Maybe another time."] = "Parece que no tengo suficiente. Quizás en otra ocasión.",
    ["*(If the player already has all of the outfit pieces:)*"] = "*(Si el player ya tiene todas las piezas del outfit:)*",
    ["I'd show you my wares, but it seems I'm out of stock at the moment."] = "Te mostraría mis productos, pero parece que no tengo stock en este momento.",
    ["I'll leave you to it then. Goodbye."] = "Entonces te dejo con eso. Adiós.",
    ["Goodbye, stranger."] = "Adiós, extraño.",
    ["You cannot understand the ghost."] = "No puedes entender al fantasma.",
    ["*(If there are Menaphite coins to hand in:)*"] = "*(Si hay Menaphite coins para entregar:)*",
    ["*(Dialogue from handing in Menaphite coins occurs, then continues below.)*"] = "*(Se produce el diálogo de la entrega de Menaphite coins, luego continúa a continuación.)*",
    ["Hey there traveller! I don't suppose you're allowed through those gates are you? If you are then I may just have a job for you."] = "¡Hola viajero! Supongo que no se te permitirá pasar por esas puertas, ¿verdad? Si es así, es posible que tenga un trabajo para usted.",
    ["What is it you need?"] = "¿Qué es lo que necesitas?",
    ["Menaphite coins! These beauties are all over the places beyond these walls. If you can bring 'em back to me, I can reward you!"] = "¡Menafita coins! Estas bellezas están por todos lados más allá de estos muros. ¡Si puedes devolvérmelos, puedo recompensarte!",
    ["That sounds like a good deal to me."] = "Eso me parece un buen negocio.",
    ["Can't you just go and collect them yourself?"] = "¿No puedes simplemente ir a recogerlos tú mismo?",
    ["Ah, I should have guessed you would ask that. The short answer is no, they cast me out! I was once a citizen of Menaphos but I am no longer allowed within those walls. It's not something I really want to talk about."] = "Ah, debería haber adivinado que preguntarías eso. La respuesta corta es no, ¡me echaron! Una vez fui ciudadano de Menaphos pero ya no se me permite entrar entre esos muros. No es algo de lo que realmente quiera hablar.",
    ["Sorry to hear that, from what I heard it's a beautiful city."] = "Lamento escuchar eso, por lo que escuché, es una ciudad hermosa.",
    ["Oh you don't need to tell me!"] = "¡Oh, no es necesario que me lo digas!",
    ["What do you do?"] = "¿Qué haces?",
    ["Nowadays I travel around in search of interesting items, and then I trade them with travellers like yourself. I've got some pretty interesting offerings that I know are of a specific interest to a few people within Menaphos."] = "Hoy en día viajo en busca de artículos interesantes y luego los cambio con viajeros como tú. Tengo algunas ofertas bastante interesantes que sé que son de interés específico para algunas personas dentro de Menaphos.",
    ["How long will you be around for?"] = "¿Cuánto tiempo estarás aquí?",
    ["Not too long as I'm a busy guy, I have things to do, people to trade y'know? I'll be around for a little while though as I need a good bunch of Menaphite coins before I'm ready to move on. One of my clients needs a large chunk of them for their own reasons that I will not go into."] = "No mientras sea un tipo ocupado, tengo cosas que hacer, gente con quien intercambiar, ¿sabes? Estaré aquí por un tiempo, ya que necesito una buena cantidad de Menaphite coins antes de estar listo para seguir adelante. Uno de mis clientes necesita una gran cantidad de ellos por sus propios motivos en los que no entraré.",
    ["You do not have anything to hand in."] = "No tienes nada que entregar.",
    ["Handing in event currency will increase your progress for this event unlocking unique rewards. This will remove currency up to the amount that is required to complete the event."] = "Entregar la moneda del evento aumentará tu progreso en este evento y desbloqueará recompensas únicas. Esto eliminará moneda hasta la cantidad necesaria para completar el evento.",
    ["Do you wish to continue?"] = "¿Quieres continuar?",
    ["You hand in [X] Menaphite coins. You need to hand in [Y] more to complete the event."] = "Entregas [X] Menaphite coins. Debes entregar [Y] más para completar el evento.",
    ["*(Dialogue from claiming rewards occurs.)*"] = "*(Se produce un diálogo para reclamar recompensas.)*",
    ["You have unlocked all of the rewards available for this event. You can convert any remaining currency into consumable rewards."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes convertir cualquier moneda restante en recompensas consumibles.",
    ["You'll need to help me some more before I can offer you any rewards."] = "Tendrás que ayudarme un poco más antes de poder ofrecerte alguna recompensa.",
    ["There you go Player."] = "Ahí tienes Player.",
    ["*(If items are obtained:)*"] = "*(Si se obtienen artículos:)*",
    ["*(If the inventory is full:)*"] = "*(Si el inventario está lleno:)*",
    ["You do not have enough inventory space for some of the rewards. Please make some space and try again."] = "No tienes suficiente espacio en el inventario para algunas de las recompensas. Por favor, deja algo de espacio e inténtalo de nuevo.",
    ["*(If there is space in inventory:)*"] = "*(Si hay espacio en el inventario:)*",
    ["Congratulations, you have been awarded [item(s)]."] = "Felicitaciones, ha sido galardonado con [item(s)].",
    ["*(If a customisation is unlocked:)*"] = "*(Si una personalización está desbloqueada:)*",
    ["Congratulations, you have unlocked [reward]."] = "Felicitaciones, has desbloqueado [reward].",
    ["You have unlocked [X]/9 of the rewards for the 'Aiding the Exile' event."] = "Has desbloqueado [X]/9 de las recompensas del evento 'Ayudando a the Exile'.",
    ["You need to give me some more Menaphite coins before I can reward you."] = "Necesitas darme más Menaphite coins antes de que pueda recompensarte.",
    ["You've already got everything I have to offer."] = "Ya tienes todo lo que tengo para ofrecerte.",
    ["Thanks for the help Player. I've got a basket full of these coins now, so make sure you collect your rewards as I'll be off shortly."] = "Gracias por la ayuda Player. Tengo una canasta llena de estos coins ahora, así que asegúrese de recoger sus recompensas ya que saldré en breve.",
    ["*(As during the event.)*"] = "*(Como durante el evento.)*",
    ["Hello. What are you doing here?"] = "Hola. ¿Qué estás haciendo aquí?",
    ["Err, nothing much, I'm just here on business. Heard Draynor's a nice place to visit."] = "Err, no mucho, solo estoy aquí por negocios. He oído que Draynor es un buen lugar para visitar.",
    ["A shambling horror has spawned on the ritual site!"] = "¡Ha aparecido un shambling horror en el sitio del ritual!",
    ["Find the component the shambling horror is targeting to sever the bond."] = "Encuentre el componente al que apunta el shambling horror para cortar el vínculo.",
    ["You sever the bond to the shambling horror."] = "Cortas el vínculo con el shambling horror.",
    ["The following reward is added to the ritual chest: [number] x [Item]"] = "Se agrega la siguiente recompensa al cofre ritual: [número] x [Item]",
    ["The following reward is added to the ritual chest: 1 x Uncut moonstone"] = "Se agrega la siguiente recompensa al cofre ritual: 1 x Piedra lunar sin cortar",
    ["This wasn't the shambling horror's target."] = "Este no era el objetivo del shambling horror.",
    ["The shambling horror manages to reach its target and collapses."] = "El shambling horror logra alcanzar su objetivo y se desploma.",
    ["Hey! Yer big elephant! Don't go choppin' down me house, now!"] = "¡Oye! ¡Eres un gran elefante! ¡No vayas a derribar mi casa ahora!",
    ["Ah, yer big elephant! Yer've caught me! What would an elephant like yer be wanting wid ol' Shamus, then?"] = "¡Ah, gran elefante! ¡Me has atrapado! Entonces, ¿qué querría un elefante como tú con el viejo Shamus?",
    ["I'm not sure."] = "No estoy seguro.",
    ["Well, you'll have to be catchin' me again when yer are, elephant!"] = "Bueno, ¡tendrás que atraparme otra vez cuando lo hagas, elefante!",
    ["The leprechaun magically disappears."] = "El duende desaparece mágicamente.",
    ["Ha! Look at yer! Look at the stupid elephant who tries to go catching a leprechaun when he don't even be knowing what he wants!"] = "¡Ja! ¡Mírate! ¡Mira al estúpido elefante que intenta atrapar a un duende cuando ni siquiera sabe lo que quiere!",
    ["How do I get to Zanaris again?"] = "¿Cómo puedo volver a Zanaris?",
    ["Yer stupid elephant! I'll tell yer again! Yer need to be entering the shed in the middle of the swamp while holding a dramen staff. Yer can make the dramen staff"] = "¡Qué estúpido elefante! ¡Te lo diré otra vez! Tienes que entrar al cobertizo en medio del pantano mientras sostienes un dramen staff. Puedes hacer el drama staff.",
    ["from a dramen tree branch, and there's a dramen tree on Entrana. Now leave me alone, yer great elephant."] = "de la rama de un árbol de dramen, y hay un árbol de dramen en Entrana. Ahora déjame en paz, tu gran elefante.",
    ["What are you up to, Shannon?"] = "¿Qué estás haciendo, Shannon?",
    ["Just taking a break from making some decorations. Toby has already caused me to break 6 fairy lights!"] = "Estoy tomando un descanso de hacer algunas decoraciones. ¡Toby ya me ha hecho romper 6 luces de hadas!",
    ["Or you're just clumsy!"] = "¡O simplemente eres torpe!",
    ["You know Toby, if you don't stop messing with Shannon, Diango might end up stuffing you into one of those imp plushies."] = "Ya sabes, Toby, si no dejas de jugar con Shannon, Diango podría terminar metiéndote en uno de esos diablillos de peluche.",
    ["Don't tell the boss man! I'll leave Shannon alone, promise."] = "¡No se lo digas al jefe! Dejaré a Shannon en paz, lo prometo.",
    ["Alright, be off with you then."] = "Muy bien, entonces te vas.",
    ["Thanks, Player."] = "Gracias, Player.",
    ["Thanks for your help this year, Player!"] = "¡Gracias por tu ayuda este año, Player!",
    ["Greetings Player. Welcome you are in the test of combat."] = "Saludos Player. Bienvenido estás en la prueba del combate.",
    ["What do I do here?"] = "¿Qué hago aquí?",
    ["A spare suit of plate armour need you will. Full helm, plate leggings and platebody yes? Placing it in the centre of the magical machines you will be doing. KA-POOF! The armour, it attacks most furiously as if alive! Kill it you must, yes."] = "Necesitarás una armadura de placas de repuesto. Casco completo, calzas de placas y cuerpo de placas, ¿sí? Colocándolo en el centro de las máquinas mágicas que estarás haciendo. ¡KA-PUF! ¡La armadura ataca con más furia como si estuviera viva! Matarlo debes, sí.",
    ["So I use a full set of plate armour on the centre plate of the machines and it will animate it? Then I have to kill my own armour... how bizarre!"] = "Entonces, ¿uso un conjunto completo de armadura de placas en la placa central de las máquinas y la animará? Entonces tengo que matar mi propia armadura... ¡qué extraño!",
    ["Yes. It is as you are saying. For this earn tokens you will. Also gain experience in combat you will. Trained long and hard here have I."] = "Sí. Es como dices. Para esto ganarás tokens. También ganarás experiencia en combate. He entrenado mucho y duro aquí.",
    ["You're not from around here are you...?"] = "No eres de por aquí ¿verdad...?",
    ["It is as you say."] = "Es como dices.",
    ["So will I lose my armour?"] = "Entonces, ¿perderé mi armadura?",
    ["Lose armour you will if damaged too much it becomes. Rare this is, but still possible. If kill you the armour does, also lose armour you will."] = "Perderás armadura si se daña demasiado. Esto es raro, pero aún posible. Si la armadura te mata, también perderás la armadura.",
    ["So, occasionally I might lose a bit because it's being bashed about and I'll obviously lose it if I die... that it?"] = "Entonces, de vez en cuando puedo perder un poco porque están siendo criticados y obviamente lo perderé si muero... ¿es eso?",
    ["Where do the machines come from?"] = "¿De dónde vienen las máquinas?",
    ["Make them I did, with magics."] = "Los hice yo, con magia.",
    ["Magic, in the Warrior's Guild?"] = "Magic, ¿en el Gremio de Guerreros?",
    ["A skilled warrior also am I. Harrallak mistakes does not make. Potential in my invention he sees and opportunity grasps."] = "Yo también soy un guerrero hábil. Harrallak no comete errores. Él ve el potencial de mi invención y aprovecha la oportunidad.",
    ["I see, so you made the magical machines and Harrallak saw how they could be used in the guild to train warrior's combat... interesting. Harrallak certainly is an intelligent guy."] = "Ya veo, entonces hiciste las máquinas mágicas y Harrallak vio cómo podían usarse en el gremio para entrenar el combate de los guerreros... interesante. Harrallak ciertamente es un tipo inteligente.",
    ["Bye!"] = "¡Adiós!",
    ["Health be with you travelling."] = "La salud te acompañará en el viaje.",
    ["*(Shanomi cycles through the following dialogue in order, with about 8.8 seconds between each line and a 1-minute pause after the last one:)*"] = "*(Shanomi recorre el siguiente diálogo en orden, con aproximadamente 8,8 segundos entre cada línea y una pausa de 1 minuto después de la última :)*",
    ["Go talk to Shantay. I'm on duty and I don't have the time to talk to the likes of you!"] = "Ve a hablar con Shantay. ¡Estoy de servicio y no tengo tiempo para hablar con gente como tú!",
    ["Hello, effendi. I am Shantay."] = "Hola, effendi. Soy Shantay.",
    ["*If the player is on a free-to-play world:*"] = "*Si el player está en un mundo gratuito:*",
    ["*If the player is on a members' world:*"] = "*Si el player está en un mundo de miembros:*",
    ["I see you're new."] = "Veo que eres nuevo.",
    ["Hello, effendi. Welcome to Shantay Pass!"] = "Hola, effendi. ¡Bienvenido al pase Shantay!",
    ["I must be going."] = "Debo irme.",
    ["Hello, effendi."] = "Hola, effendi.",
    ["Please read the billboard poster before going into the desert. It'll give you details on the dangers you can face."] = "Por favor lea el cartel publicitario antes de adentrarse en el desierto. Le dará detalles sobre los peligros que puede enfrentar.",
    ["This is Shantay Pass. I guard this area with my men. I am responsible for keeping this pass open and repaired."] = "Este es el pase Shantay. Cuido esta zona con mis hombres. Soy responsable de mantener este pase abierto y reparado.",
    ["My men and I prevent outlaws from getting out of the desert. And we stop the inexperienced from a dry death in the sands. Which would you say you were?"] = "Mis hombres y yo evitamos que los forajidos salgan del desierto. Y evitamos que los inexpertos mueran secamente en la arena. ¿Quién dirías que eres?",
    ["I am definitely an outlaw, prepare to die!"] = "Definitivamente soy un forajido, ¡prepárate para morir!",
    ["Haha, very funny... Guards, arrest [him/her]!"] = "Jaja, muy gracioso... ¡Guardias, arresten a [him/her]!",
    ["**"] = "*(Acción: Eres teletransportado dentro de la celda de Prison Pete en la cárcel de Port Sarim)*",
    ["That's how we treat troublemakers around here. Now, if you pay a fine I will release you. Otherwise you will be deported to a maximum security jail in Port Sarim. Choose!"] = "Así es como tratamos a los alborotadores por aquí. Ahora, si pagas una multa, te liberaré. De lo contrario serás deportado a una cárcel de máxima seguridad en Port Sarim. ¡Elegir!",
    ["**WHAT WOULD YOU LIKE TO SAY?**"] = "**¿QUÉ TE GUSTARÍA DECIR?**",
    ["I'll pay."] = "Yo pagaré.",
    ["Shantay takes 5 coins and unlocks the door."] = "Shantay toma 5 coins y abre la puerta.",
    ["5 coins have been removed from your money pouch."] = "Se han eliminado 5 coins de tu bolsa de dinero.",
    ["Deport me to Port Sarim!"] = "¡Deportame a Port Sarim!",
    ["I hope this teaches you a lesson!"] = "¡Espero que esto te enseñe una lección!",
    ["You find yourself in a prison."] = "Te encuentras en una prisión.",
    ["I'll just stay in here, thanks."] = "Me quedaré aquí, gracias.",
    ["Ah, it is good that you are willing to spend time reflecting on your misdeeds."] = "Ah, es bueno que estés dispuesto a dedicar tiempo a reflexionar sobre tus fechorías.",
    ["I am a little inexperienced."] = "Soy un poco inexperto.",
    ["Can I recommend that you take at least one full waterskin into the desert. The sun is very hot, and without water to drink you may die of thirst. I see you carry a knife already on your tool belt. If your waterskins are running dry, you can cut the cacti you see to replenish them."] = "¿Puedo recomendarte que lleves al menos un odre de agua lleno al desierto? El sol calienta mucho y sin agua para beber puedes morir de sed. Veo que ya llevas un cuchillo en tu cinturón de herramientas. Si tus odres se están secando, puedes cortar los cactus que ves para reponerlos.",
    ["Can I see what you have to sell, please?"] = "¿Puedo ver lo que tienes para vender, por favor?",
    ["Er, neither, I'm an adventurer."] = "Er, tampoco, soy un aventurero.",
    ["Good, I have just the thing for the desert adventurer: clothes that will keep you cool in the heat of the sun. I also sell waterskins, which will help you survive from dying of thirst. And you are free to use the bank chest here. It is unwise to travel the desert wearing thick and heavy armour - you will only dehydrate faster."] = "Bien, tengo lo ideal para el aventurero del desierto: ropa que te mantendrá fresco bajo el calor del sol. También vendo odres de agua, que te ayudarán a sobrevivir después de morir de sed. Y puedes utilizar el cofre del banco aquí. No es aconsejable viajar por el desierto con una armadura gruesa y pesada; sólo te deshidratarás más rápido.",
    ["Absolutely, effendi!"] = "¡Absolutamente, effendi!",
    ["So long..."] = "Hasta luego...",
    ["Aha, a troublemaker! Now, you have a choice: If you pay a fine of 5 coins, I will release you. Otherwise you will be deported to a maximum security jail in Port Sarim."] = "¡Ajá, un alborotador! Ahora tienes una opción: si pagas una multa de 5 coins, te liberaré. De lo contrario serás deportado a una cárcel de máxima seguridad en Port Sarim.",
    ["I's not doing a great deal now Bwana, as I'm no spring chicken. I do my fair share around the village bwana, though, I could tell you a thing or two about the jungle slashing."] = "No estoy haciendo mucho ahora Bwana, ya que no soy un polluelo. Aunque hago mi parte en la aldea bwana, podría contarte un par de cosas sobre la tala de la jungla.",
    ["Ok, tell me about jungle slashing!"] = "Ok, ¡cuéntame sobre la tala en la jungla!",
    ["Ok Bwana, I will! To begin with you'll need a machete in order to hack your way through the jungle. There are some better gem edged weapons which you may be able to purchase from Gabooty."] = "Ok, Bwana, ¡lo haré! Para empezar, necesitarás un machete para abrirte camino a través de la jungla. Hay algunas armas con bordes de gemas mejores que puedes comprar en Gabooty.",
    ["Safta Doc makes them for him. You should be aware that hacking away at the jungle is not without its dangers though Bwana. Many times you may find some scary creatures lurking inside."] = "Safta Doc los hace para él. Debes tener en cuenta que atacar la jungla no está exento de peligros, aunque Bwana. Muchas veces es posible que encuentres criaturas aterradoras acechando en el interior.",
    ["What sort of creatures?"] = "¿Qué tipo de criaturas?",
    ["Ok, to start with there are spiders! These are pretty tough but if you defeat it, you can get a good meal from it, if you know how to cook it that is. My wife cooks them to a turn - Mmmm, delicious."] = "Ok, para empezar, ¡hay arañas! Son bastante difíciles, pero si los derrotas, puedes obtener una buena comida, si sabes cocinarlos. Mi esposa los cocina hasta su punto. Mmmm, deliciosos.",
    ["Ok go on!"] = "¡Ok, continúa!",
    ["Yes Bwana, of course. Then there are snakes...these are dangerous because they're poisonous - so be prepared! However, they're not without their uses. A bush snake is large enough to have a useful hide."] = "Sí, Bwana, por supuesto. Luego están las serpientes... son peligrosas porque son venenosas, ¡así que prepárate! Sin embargo, no están exentas de usos. Un bush snake es lo suficientemente grande como para tener un escondite útil.",
    ["Once the hide is tanned you get a snakeskin and you're able to make things from it, the same way that mainlanders use normal leather! However, it's actually still quite small."] = "Una vez curtida la piel, obtienes una piel de serpiente y puedes hacer cosas con ella, ¡de la misma manera que los continentales usan el cuero normal! Sin embargo, en realidad todavía es bastante pequeño.",
    ["You may need several skins in order to make something useful."] = "Es posible que necesites varias máscaras para hacer algo útil.",
    ["Hmm, sounds interesting!"] = "Mmm, ¡suena interesante!",
    ["Then there are giant mosquitoes bwana, they're fast and agile. You'll need to be quick if you're to hit them at all! However, it certainly does train your reactions. They're not very tough, just difficult to hit."] = "Luego están los mosquitos gigantes bwana, son rápidos y ágiles. ¡Tendrás que ser rápido si quieres golpearlos! Sin embargo, ciertamente entrena tus reacciones. No son muy duros, sólo difíciles de golpear.",
    ["I also believe that their proboscis is useful in someway, I believe Timfraku's sons sometimes use them for hunting."] = "También creo que su trompa es útil de alguna manera, creo que los hijos de Timfraku a veces la usan para cazar.",
    ["Ok, that sounds helpful...anything else?"] = "Ok, eso suena útil... ¿algo más?",
    ["Yes Bwana... and this is serious... The jungle is very ancient and many unspeakable acts have been witnessed on these lands. Bizarre supernatural curses were placed on criminals and then they were buried alive!"] = "Sí Bwana... y esto es serio... La selva es muy antigua y en estas tierras se han presenciado muchos actos atroces. ¡Se aplicaron extrañas maldiciones sobrenaturales a los criminales y luego fueron enterrados vivos!",
    ["These strange creatures have the curse of the Broodoo on them! They'll rise from their grave with their heads in their chests and move like crazy spirits of the afterlife."] = "¡Estas extrañas criaturas tienen la maldición del Broodoo sobre ellas! Se levantarán de su tumba con la cabeza en el pecho y se moverán como espíritus locos del más allá.",
    ["If they're disturbed they will attack anything in the area with their magical abilities! They suffer little from being attacked as they seem to be protected by some form of defence."] = "¡Si se les molesta, atacarán cualquier cosa en el área con sus habilidades mágicas! Sufren poco al ser atacados ya que parecen estar protegidos por alguna forma de defensa.",
    ["However... it is said that the means of their death provides the clue to their destruction. So far three distinct Broodoo have been identified. The Broodoo with a green hued skin is said to have died from poison."] = "Sin embargo... se dice que el medio de su muerte proporciona la pista de su destrucción. Hasta ahora se han identificado tres Broodoo distintos. Se dice que el Broodoo de piel de color verde murió envenenado.",
    ["There is a broodoo of yellow hue and a pale skinned broodoo, but little is known of these two!"] = "Hay un broodoo de tono amarillo y un broodoo de piel pálida, ¡pero se sabe poco de estos dos!",
    ["Erk! Well that sounds pretty scary!"] = "¡Erk! Bueno, ¡eso suena bastante aterrador!",
    ["Yes Bwana..."] = "Sí, Bwana...",
    ["Ok, thanks a lot...."] = "Ok, muchas gracias....",
    ["Wait Bwana, there's more!"] = "Espera, Bwana, ¡hay más!",
    ["More... Blimey! Ok carry on..."] = "Más... ¡Caramba! Ok, continúa...",
    ["Some of the local villagers have found strange plants which grow here-abouts. If you cut away at the jungle and find one, it's considered a blessing, though the useful part of the plant is usually buried underground. And also, you"] = "Algunos de los aldeanos locales han encontrado plantas extrañas que crecen por aquí. Si cortas la jungla y encuentras una, se considera una bendición, aunque la parte útil de la planta suele estar enterrada bajo tierra. Y también tu",
    ["may find an uncommon rock type which is impregnated with mineral wealth! Well that concludes all the help I can give you regarding the jungle in Tai Bwo Wannai!"] = "¡Puedes encontrar un tipo de roca poco común que está impregnada de riqueza mineral! ¡Bueno, aquí concluye toda la ayuda que puedo brindarte sobre la jungla en Tai Bwo Wannai!",
    ["I have to say, that's quite a lot of information...thanks very much!"] = "Debo decir que es mucha información... ¡muchas gracias!",
    ["You're more than welcome bwana!"] = "¡De nada, bwana!",
    ["Previous questions."] = "Preguntas previas.",
    ["Hey, new fish! Welcome to Waiko! Have a copy of our tourist brochure!"] = "¡Oye, pez nuevo! ¡Bienvenidos a Waiko! ¡Tenga una copia de nuestro folleto turístico!",
    ["*If you have the Arc journal already:*"] = "*Si ya tienes el diario Arc:*",
    ["I've got one, thanks."] = "Tengo uno, gracias.",
    ["*If you don't have the Arc journal:*"] = "*Si no tienes el diario Arc:*",
    ["You're enthusiastic!"] = "¡Estás entusiasmado!",
    ["Of course, Waiko is great, and we love western tourists!"] = "Por supuesto, Waiko es genial y ¡nos encantan los turistas occidentales!",
    ["Any questions? I'm here to help! Or read the brochure!"] = "¿Alguna pregunta? ¡Estoy aquí para ayudar! ¡O lea el folleto!",
    ["Where are the uncharted isles?"] = "¿Dónde están las islas inexploradas?",
    ["You should talk to Rosie in Waiko market - she's our ship chandler."] = "Deberías hablar con Rosie en el mercado de Waiko; ella es nuestra proveedora de barcos.",
    ["Buy some supplies from her, and then you'll be able to head out on an expedition on your own boat! She's even generous enough to give you a handful of supplies every day for free!"] = "¡Cómprale algunos suministros y luego podrás emprender una expedición en tu propio barco! ¡Incluso es lo suficientemente generosa como para darte un puñado de suministros todos los días gratis!",
    ["And if you want to claim an uncharted island as your own, you'd best talk to Boni, also in Waiko market. She's looking for help with a little project."] = "Y si quieres reclamar una isla inexplorada como tuya, será mejor que hables con Boni, también en el mercado de Waiko. Ella está buscando ayuda con un pequeño proyecto.",
    ["Anything here for skillers?"] = "¿Hay algo aquí para los expertos?",
    ["Of course! There are a couple of basic amenities here on Waiko...some bamboo around the market area and some fishing spots on the south dock."] = "¡Por supuesto! Hay un par de servicios básicos aquí en Waiko... algo de bambú alrededor del área del mercado y algunos lugares de pesca en el muelle sur.",
    ["If you're after trickier fish to land, though, you should head to Whale's Maw. There's some tortles to hunt there too, so I've heard."] = "Sin embargo, si buscas peces más difíciles de capturar, deberías dirigirte a las Fauces de Whale. Según tengo entendido, también hay algunas tortugas que cazar allí.",
    ["These are all only basic resources, however. They're pretty good to sell for chimes, but they're not great experience."] = "Sin embargo, estos son solo recursos básicos. Son bastante buenos para venderlos como campanadas, pero no son una gran experiencia.",
    ["But if you head out to explore the uncharted islands, you'll be able to gain some really nice experience, and better resources worth more chimes."] = "Pero si sales a explorar islas inexploradas, podrás obtener una experiencia realmente agradable y mejores recursos que valen más campanadas.",
    ["Better still, if you're able to gather a wider range of resources, you can spend some extra effort to turn them into commodities, which sell for even more chimes!"] = "Mejor aún, si eres capaz de reunir una gama más amplia de recursos, puedes dedicar un esfuerzo extra para convertirlos en productos básicos, ¡que se venden por aún más campanadas!",
    ["Anything here for killers?"] = "¿Hay algo aquí para asesinos?",
    ["There's plenty of dangerous fauna, monsters and people out in the uncharted islands."] = "Hay mucha fauna, monstruos y personas peligrosas en las islas inexploradas.",
    ["But it sounds like Aminishi might be your sort of speed."] = "Pero parece que Aminishi podría ser tu tipo de velocidad.",
    ["Last I heard, there was a Death Lotus assassin out that way...you should talk to them for more information."] = "Lo último que supe fue que había un asesino de Death Lotus en esa dirección... deberías hablar con él para obtener más información.",
    ["Anything here for questers?"] = "¿Hay algo aquí para los buscadores?",
    ["Hey, if you're ever looking for work you should talk to Sojobo in Waiko market."] = "Oye, si alguna vez buscas trabajo, deberías hablar con Sojobo en el mercado de Waiko.",
    ["His contracts are a good way to learn the ropes, while also earning some chimes and experience."] = "Sus contracts son una buena forma de aprender a manejar y al mismo tiempo ganar algunas campanadas y experiencia.",
    ["But I'm sure if you ask around, there'll be a bunch of other odd jobs you can pick up too!"] = "Pero estoy seguro de que si preguntas por ahí, ¡habrá muchos otros trabajos ocasionales que también podrás realizar!",
    ["No, I'm good, thanks."] = "No, estoy bien, gracias.",
    ["Well met."] = "Bien conocido.",
    ["We meet again."] = "Nos volvemos a encontrar.",
    ["I am Sharrigan. I am...was the Pastkeeper for the Ilujanka. Well, I suppose I still am, but also now something else."] = "Soy Sharrigan. Yo soy... era el Guardián del Pasado de Ilujanka. Bueno, supongo que todavía lo soy, pero ahora también algo más.",
    ["My role was to remember the stories of our people, but since Vindicta visited Iaia, some of our young have decided to become pioneers, travel here and find a new home."] = "Mi función era recordar las historias de nuestra gente, pero desde que Vindicta visitó Iaia, algunos de nuestros jóvenes han decidido convertirse en pioneros, viajar aquí y encontrar un nuevo hogar.",
    ["Many of them have decided to colonise this island, or at least stop here initially, as it bears some resemblance to our world - the jungles, the animals, the climate."] = "Muchos de ellos han decidido colonizar esta isla, o al menos detenerse aquí inicialmente, ya que tiene cierto parecido con nuestro mundo: las selvas, los animales, el clima.",
    ["Since I have visited this world before I volunteered to come with and support them, to keep reminding them of where they come from."] = "Desde que visité este mundo, me ofrecí como voluntario para acompañarlos y apoyarlos, para seguir recordándoles de dónde vienen.",
    ["What are you collecting?"] = "¿Qué estás coleccionando?",
    ["Would you like to view my collections or simply discuss them?"] = "¿Le gustaría ver mis colecciones o simplemente discutirlas?",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["View collections."] = "Ver colecciones.",
    ["Talk about collections."] = "Habla de colecciones.",
    ["I figure I may as well learn some of the stories of those who once lived here too. Telling stories of the past is my reason for being."] = "Supongo que también podría aprender algunas de las historias de quienes alguna vez vivieron aquí. Contar historias del pasado es mi razón de ser.",
    ["I have become fascinated with the dragonkin who once lived here, and so will accept any artefacts found on this island."] = "Estoy fascinado con los dragonantes que una vez vivieron aquí, y por eso aceptaré cualquier artefacto que se encuentre en esta isla.",
    ["What are your collection rewards?"] = "¿Cuáles son las recompensas de tu colección?",
    ["Of course, you humans enjoy your rewards..."] = "Por supuesto, ustedes, los humanos, disfrutan de sus recompensas...",
    ["I have struck a deal with the archaeologists working here. They have agreed to give me any compacted resources they find while performing their tasks."] = "He llegado a un acuerdo con los arqueólogos que trabajan aquí. Han aceptado darme cualquier recurso compactado que encuentren mientras realizan sus tareas.",
    ["Now, I have many crates full of wood, vines, leaves, pelts, stone and clay."] = "Ahora tengo muchas cajas llenas de madera, enredaderas, hojas, pieles, piedras y arcilla.",
    ["For completing my first collection, I will exchange six of these crates. You may select which compacted resource each of them grants you. I have plenty in stock of every type."] = "Por completar mi primera colección, cambiaré seis de estas cajas. Podrás seleccionar qué recurso compactado te otorga cada uno de ellos. Tengo bastante stock de todo tipo.",
    ["Then, for my second and fourth collections, I will exchange some rex skeleton fragments. I am intrigued at the reconstruction going on elsewhere in base camp."] = "Luego, para mi segunda y cuarta colección, intercambiaré algunos fragmentos de esqueleto de rex. Me intriga la reconstrucción que se está llevando a cabo en otras partes del campo base.",
    ["And as for my third collection, I have discovered a powerful magical relic from one of the dragonkin crypts."] = "Y en cuanto a mi tercera colección, descubrí una poderosa reliquia mágica de una de las criptas dragonkin.",
    ["It was once owned by a dragonkin named Kaladan. The staff itself is named Kaladanda, which suggests either this dragonkin named or created it."] = "Una vez fue propiedad de un dragonante llamado Kaladan. El staff en sí se llama Kaladanda, lo que sugiere que este dragonante lo nombró o lo creó.",
    ["So, colloquially, the 'Staff of Kaladan'? What does it do?"] = "Entonces, coloquialmente, ¿el 'Staff de Kaladan'? ¿Qué hace?",
    ["There are carvings all over it depicting scenes of death - bones and ashes and the like. It exudes an aura of death magic, but also new life - it reminds me of Iaia, of the Olun'dai."] = "Hay tallas por todas partes que representan escenas de muerte: huesos, cenizas y cosas similares. Exuda un aura de magia de muerte, pero también de vida nueva; me recuerda a Iaia, a los Olun'dai.",
    ["I believe its effects relate to the moment that your enemies perish, collecting their remains in an easily stored form, giving them new purpose."] = "Creo que sus efectos se relacionan con el momento en que tus enemigos mueren, recolectando sus restos en una forma fácil de almacenar, dándoles un nuevo propósito.",
    ["Have you unlocked the power of the Kaladanda staff?"] = "¿Has desbloqueado el poder de Kaladanda staff?",
    ["Recently, a number of archaeologists have been returning with tokens from the dungeon of Daemonheim. For my fifth collection I can provide you with two large boxes of these tokens."] = "Recientemente, varios arqueólogos han regresado con fichas de la mazmorra de Daemonheim. Para mi quinta colección puedo proporcionarles dos cajas grandes de estas fichas.",
    ["For completing my sixth collection, I've also come into possession of a rather unique relic from the past. A tapestry depicting a meeting between the and gorajo."] = "Para completar mi sexta colección, también adquirí una reliquia bastante única del pasado. Un tapiz que representa un encuentro entre los y gorajo.",
    ["Upon further study this tapestry seems to be more than just a record of this meeting."] = "Tras un estudio más profundo, este tapiz parece ser más que un simple registro de esta reunión.",
    ["It has been imbued with the precise techniques of its own meticulous creation. Through further study, you will be able to harness this meticulous precision for your own benefit."] = "Ha sido imbuido de las técnicas precisas de su propia y meticulosa creación. A través de más estudios, podrá aprovechar esta meticulosa precisión para su propio beneficio.",
    ["Were you able to make use of the power imbued within the tapestry?"] = "¿Pudiste hacer uso del poder imbuido dentro del tapiz?",
    ["For further completion of my sixth collection I can provide you with more of these large token boxes, I'll even include one of these mysterious cards some of the archaeologists discovered."] = "Para completar aún más mi sexta colección, puedo proporcionarles más de estas cajas de fichas grandes, incluso incluiré una de estas tarjetas misteriosas que descubrieron algunos de los arqueólogos.",
    ["As for my seventh collection, I can offer you a tetracompass piece."] = "En cuanto a mi séptima colección, puedo ofrecerles una pieza de tetracompass.",
    ["Besides all of that, I also have chronotes."] = "Además de todo eso, también tengo cronotas.",
    ["Oh! One last thing! This is a strange one, but Mr Mordaut has also informed me that a friend of a friend has requested a dragonkin death mask. Perhaps you know of this so-called 'Bob the cat'?"] = "¡Oh! ¡Una última cosa! Esto es extraño, pero Mr Mordaut también me informó que el amigo de un amigo solicitó una máscara mortuoria de dragón. ¿Quizás conoces el llamado 'el gato Bob'?",
    ["Do you know what I need to restore this brush?"] = "¿Sabes lo que necesito para restaurar este pincel?",
    ["[Sharrigan looks over the damaged brush handle.]"] = "[Sharrigan mira por encima del mango del cepillo dañado.]",
    ["This is the handle of a dragonkin sash brush. I've read about them, but this is the first I've seen of one."] = "Este es el mango de un cepillo de fajín dragonkin. He leído sobre ellos, pero esta es la primera vez que veo uno.",
    ["These were used in the preparation of experiment samples to ensure no contaminants were present, from my readings they were extremely effective."] = "Se utilizaron en la preparación de muestras experimentales para garantizar que no hubiera contaminantes presentes; según mis lecturas, fueron extremadamente efectivos.",
    ["Interesting, do you know what I'm going to need to restore this to a usable state?"] = "Interesante, ¿sabes qué voy a necesitar para restaurar esto a un estado utilizable?",
    ["Restoring the handle should be straightforward, a combination of felt, carbon black and dragon metal should do it."] = "Restaurar el mango debería ser sencillo; una combinación de fieltro, negro de humo y metal de dragón debería bastar.",
    ["The bristles are more complex to source. You'll need to find some dried zygomite hair, and grind it with some onyx dust."] = "Las cerdas son más complejas de obtener. Necesitarás encontrar un poco de pelo de zigomita seco y molerlo con un poco de polvo de ónix.",
    ["Then once the handle and softened zygomite hair are bound together, the last step is an infusion of draconic energy."] = "Luego, una vez que el mango y el pelo de zigomita suavizado están unidos, el último paso es una infusión de energía dracónica.",
    ["Could you remind me what I need to restore this damaged brush?"] = "¿Podrías recordarme qué necesito para restaurar este cepillo dañado?",
    ["Until next time."] = "Hasta la próxima.",
    ["Hello, Player."] = "Hola, Player.",
    ["Hi, Sharrigan. I have something for you."] = "Hola, Sharrigan. Tengo algo para ti.",
    ["Oh?"] = "¿Ah?",
    ["Before we left Iaia, I tried to get the old Pastkeeper to evacuate. She refused to leave, but she gave me this amulet."] = "Antes de dejar Iaia, intenté que el viejo Guardián del Pasado evacuara. Ella se negó a irse, pero me dio este amuleto.",
    ["She asked me to give it to you, and to tell you that you were ready."] = "Ella me pidió que te lo diera y te dijera que estabas listo.",
    ["Congratulations! You have completed: 'Out of the Past' - Give Sharrigan her mentor's Pastkeeper Amulet."] = "¡Felicitaciones! Has completado: 'Fuera del pasado': entrega a Sharrigan el amuleto del guardián del pasado de su mentor.",
    ["Her amulet?"] = "¿Su amuleto?",
    ["I can't describe how much I miss her. She taught me everything. At least one small piece of her survives, in this. And her stories - our stories - survive in me."] = "No puedo describir cuánto la extraño. Ella me enseñó todo. Al menos una pequeña parte de ella sobrevive en esto. Y sus historias -nuestras historias- sobreviven en mí.",
    ["Thank you, Player. I will treasure this for as long as I live."] = "Gracias, Player. Atesoraré esto mientras viva.",
    ["Would you like to hear any pastkeeper stories?"] = "¿Te gustaría escuchar alguna historia de pastkeeper?",
    [", in order to access their stories."] = ", para poder acceder a sus historias.",
    ["Reflecting on Bad Decisions"] = "Reflexionar sobre las malas decisiones",
    ["Pride is a virtue. We should always have pride in ourselves and what we do. But like so many things, too much or a virtue can become a vice. Pride can so easily be twist into vanity or hubris. Lamilos was a very prideful man."] = "El orgullo es una virtud. Siempre debemos estar orgullosos de nosotros mismos y de lo que hacemos. Pero como tantas cosas, demasiado o una virtud puede convertirse en un vicio. El orgullo puede fácilmente transformarse en vanidad o arrogancia. Lamilos era un hombre muy orgulloso.",
    ["Lamilos had scales that were as bright as the moons during a conjunction. They glistened in the morning light and they reflected the gentle glow of twilight in a dazzling array of colours. People were in awe of his beauty, but none quite so much as himself."] = "Lamilos tenía escamas que eran tan brillantes como las lunas durante una conjunción. Brillaban a la luz de la mañana y reflejaban el suave resplandor del crepúsculo en una deslumbrante variedad de colores. La gente estaba asombrada por su belleza, pero nadie tanto como él mismo.",
    ["So enamoured with his own beauty was Lamilos, that he decided he needed to live somewhere he could properly admire himself. He consulted with the village architects and masons and he comissions from them a house so magnificent that it would be the envy of all. He wanted a house with inner walls made of glistening glass and outer walls made from polished stone. So that he could gaze upon his reflected beauty whenever the mood struck him."] = "Lamilos estaba tan enamorado de su propia belleza que decidió que necesitaba vivir en un lugar donde pudiera admirarse adecuadamente. Consultó con los arquitectos y albañiles del pueblo y les encargó una casa tan magnífica que sería la envidia de todos. Quería una casa con paredes interiores de cristal reluciente y paredes exteriores de piedra pulida. Para poder contemplar su belleza reflejada cuando le apeteciera.",
    ["The masons and architects warned him that such a house was folly, but Lamilos would hear none of it. He demanded that they make him this house of mirrors and begrudgingly they obliged."] = "Los albañiles y arquitectos le advirtieron que una casa así era una locura, pero Lamilos no quiso oír nada de eso. Exigió que le hicieran esta casa de espejos y, a regañadientes, accedieron.",
    ["For many days and nights, Lamilos delighted in a house that showed himself whenever he turned. He revelled in his reflections and he conversed with his countenance with a relish so profound he barely slept."] = "Durante muchos días y noches, Lamilos se deleitó en una casa que se mostraba cada vez que miraba. Se deleitaba con sus reflexiones y conversaba con su rostro con un deleite tan profundo que apenas dormía.",
    ["But pride comes before a fall and before the fall comes the summer. This summer was the brightest and hottest summer of them all. A heat so strong that the crops wilted and the swamp began to dry. The sun's rays were so bright and so strong, but when they entered the house of glass and mirrors they became a blazing inferno of radiance. In an instant, Lamilos - and all his beautiful scales - became motes of dust in the summer air."] = "Pero el orgullo viene antes del otoño y antes del otoño llega el verano. Este verano fue el más brillante y caluroso de todos. Un calor tan fuerte que las cosechas se marchitaron y el pantano empezó a secarse. Los rayos del sol eran tan brillantes y tan fuertes, pero cuando entraron en la casa de vidrio y espejos se convirtieron en un ardiente infierno de resplandor. En un instante, Lamilos (y todas sus hermosas escamas) se convirtieron en motas de polvo en el aire del verano.",
    ["Or perhaps I am wrong. Perhaps they lived happily ever after, but I do not know, I was not there."] = "O quizás me equivoque. Quizás vivieron felices para siempre, pero no lo sé, yo no estuve allí.",
    ["Tempest in a Teapot"] = "Tempestad en una tetera",
    ["Trouble follows some people. No matter what they do, or where they go, it stalks them like a varigun beast hunting its prey. Poor Eldibras was one such person."] = "Los problemas siguen a algunas personas. No importa lo que hagan o adónde vayan, los acecha como una bestia varigun cazando a su presa. El pobre Eldibras era una de esas personas.",
    ["Eldibras had trained all his life as a potter, longing to craft beautiful works of art from Iaia's rich and colourful clay. But his pots always wobbled and his cups always cracked. He tried and he tried, but it was as though the Olun'dai had decided his work was never going to be of the quality he worked for."] = "Eldibras se había entrenado toda su vida como alfarero, anhelando crear hermosas obras de arte con la rica y colorida arcilla de Iaia. Pero sus ollas siempre se tambaleaban y sus tazas siempre se rompían. Lo intentó y lo intentó, pero era como si los Olundai hubieran decidido que su trabajo nunca tendría la calidad para la que había trabajado.",
    ["Then one day a strange visitor arrived in the town. He was tall and smelled of exotic spices and flowers that no one had ever smelled before. He wandered through the shops in search of something unique, but with each perfect piece of craftsmanship he turned away disgruntled."] = "Entonces, un día, un extraño visitante llegó al pueblo. Era alto y olía a especias y flores exóticas que nadie había olido antes. Deambuló por las tiendas en busca de algo único, pero con cada pieza de artesanía perfecta se alejaba disgustado.",
    ["Until finally he came upon Eldibras's meagre market stall and spied the lopsided, warped and imperfect creations that the sheeping potter offered for sale."] = "Hasta que finalmente se encontró con el exiguo puesto del mercado de Eldibras y vio las creaciones torcidas, deformadas e imperfectas que el alfarero ofrecía a la venta.",
    ["Such wonders!' spoke the man. His voice was like a bellowing wind and it shook all the pieces on the table. The pots wobbled. The cups jggled. But their warped imperfections stopped them from falling. 'Never have I seen such unique works. Each of them different. Each of them a tale of struggle and survival. I must have them!'."] = "¡Qué maravillas!' habló el hombre. Su voz era como un viento rugiente y sacudió todas las piezas de la mesa. Las ollas se tambalearon. Las tazas tintinearon. Pero sus imperfecciones deformadas les impidieron caer. 'Nunca había visto obras tan singulares. Cada uno de ellos diferente. Cada uno de ellos una historia de lucha y supervivencia. ¡Debo tenerlos!'.",
    ["He handed Eldibras not a bag of gold, nor a precious stone, but a small box that rattled and wobbled. 'Inside this box is a beautiful imperfection. A piece of time that got lost and unstuck from the rest. Keep it with you, so you will always have the time you need.' and with that the stranger took the misshapen pots and cups and he walked out of this story and into another."] = "Le entregó a Eldibras no una bolsa de oro, ni una piedra preciosa, sino una pequeña caja que traqueteaba y se tambaleaba. 'Dentro de esta caja hay una hermosa imperfección. Un trozo de tiempo que se perdió y se despegó del resto. Mantenlo contigo para que siempre tengas el tiempo que necesitas.' y con eso el extraño tomó las ollas y tazas deformes y salió de esta historia y entró en otra.",
    ["From then on, Eldibras had all the time in the world - and he knew it. He focused on his craft and in time he could make pots, bowls, plates and cups that were without blemish. Though he always kept the ones that weren't perfect. Because he knew that their imperfections made them unique, made them beautiful."] = "A partir de entonces, Eldibras tuvo todo el tiempo del mundo, y él lo sabía. Se concentró en su oficio y con el tiempo pudo hacer ollas, tazones, platos y tazas sin imperfecciones. Aunque siempre guardaba los que no eran perfectos. Porque sabía que sus imperfecciones los hacían únicos, los hacían hermosos.",
    ["Perhaps they lived happily ever after, but I do not know, I was not there."] = "Quizás vivieron felices para siempre, pero no lo sé, yo no estuve allí.",
    ["The Moons' Pearl"] = "La perla de las lunas",
    ["I shall tell you the tale of the Omisha the fisher. Omisha was not a master of her trade, nor was she a novice. Her life was a monument to mediocrity and that was the way she liked it. She had few aspirations of greatness, and no desire for power, fame, or wealth. She simply wanted to live a comfortable life and be happy."] = "Les contaré la historia del pescador Omisha. Omisha no era una maestra en su oficio ni una novata. Su vida era un monumento a la mediocridad y así le gustaba a ella. Tenía pocas aspiraciones de grandeza y ningún deseo de poder, fama o riqueza. Ella simplemente quería vivir una vida cómoda y ser feliz.",
    ["But the Olun'dai is a fickle thing and her Olun'det had other plans for her. One day, as she fished for shellfish in the warm light of summer, she came across a brightly coloured shell unlike any she had seen before. Carefully, she shucked the shell, prying it open to see what sort of creature lay inside."] = "Pero Olun'dai es algo voluble y su Olun'det tenía otros planes para ella. Un día, mientras pescaba mariscos bajo la cálida luz del verano, se encontró con una concha de colores brillantes como nunca antes había visto. Con cuidado, quitó el caparazón y lo abrió para ver qué tipo de criatura había dentro.",
    ["But no creature did she find. Instead she found only a single pearl, nestled perfectly in the shell. The pearl was a beautiful thing. When she looked at it one way, it seemed to be a beautiful silver, but as she turned it round it seemed to change first to red, then to purple and then once more to silver."] = "Pero no encontró ninguna criatura. En lugar de eso, encontró sólo una perla, perfectamente encajada en la concha. La perla era algo hermoso. Cuando lo miró de una manera, parecía ser de un hermoso color plateado, pero cuando lo giró pareció cambiar primero a rojo, luego a morado y luego una vez más a plateado.",
    ["She took the pearl home with her and wondered how best to use it, when she heard a knock on the door. Answering it, she was greeted by a woman, with scales of beautiful silver and long robes to match."] = "Se llevó la perla a casa y se preguntó cuál sería la mejor manera de usarla, cuando escuchó un golpe en la puerta. Al contestar, fue recibida por una mujer, con escamas de hermosa plata y largas túnicas a juego.",
    ["I have come for my pearl' she said. Omisha was confused, for the woman could not possibly claim to own a shell and she dismissed her rudely."] = "He venido por mi perla', dijo. Omisha estaba confundida, porque la mujer no podía afirmar que poseía una concha y la despidió con rudeza.",
    ["On the next night a knock fell upon her door again. At the door was a woman who looked identical to the first, except her scales were a deep crimson. She too asked for the pearl and was turned away."] = "A la noche siguiente, volvieron a llamar a su puerta. En la puerta había una mujer que parecía idéntica a la primera, excepto que sus escamas eran de un color carmesí intenso. Ella también pidió la perla y fue rechazada.",
    ["On the third night, as before, a knock fell upon the door. This time the woman had scales of a deep and vibrant purple. She asked for the pearl and was denied as the others had been. 'We have asked only for what is ours,' she said. 'As you have taken it from us, we shall take back what is also ours. Until you return the pearl to us.' And with that she left."] = "La tercera noche, como antes, alguien llamó a la puerta. Esta vez la mujer tenía escamas de un color púrpura intenso y vibrante. Ella pidió la perla y se la negaron como a los demás. \"Sólo hemos pedido lo que es nuestro\", dijo. 'Tal como nos lo has quitado, nosotros recuperaremos lo que también es nuestro. Hasta que nos devuelvas la perla. Y con eso se fue.",
    ["Content that she had nothing that they had given her, Omisha went about the next day as normal. But when night fell the entire village was plunged into the deepest darkness. Frantically, Omisha looked for moonlight between the clouds, but there was no sign of the moons in the sky."] = "Contenta de no tener nada de lo que le habían dado, Omisha continuó al día siguiente con normalidad. Pero cuando cayó la noche, todo el pueblo quedó sumido en la más profunda oscuridad. Frenéticamente, Omisha buscó la luz de la luna entre las nubes, pero no había señales de lunas en el cielo.",
    ["For three weeks there was nothing but darkness in the night and she could no longer escape the effects. The fish, requiring the light, began to die and so only the stronger fishers claimed them. The crops began to wilt and perish and a famine fell across the land. Omisha wept at her greed and chastised herself for her hubris."] = "Durante tres semanas no hubo nada más que oscuridad en la noche y ya no pudo escapar de los efectos. Los peces, que necesitaban luz, comenzaron a morir y sólo los pescadores más fuertes los reclamaron. Las cosechas comenzaron a marchitarse y perecer y una hambruna azotó la tierra. Omisha lloró por su codicia y se reprendió a sí misma por su arrogancia.",
    ["With regret in her heart, she returned the pearl to the waters and added her tears as an apology. That night, the moons shone once more."] = "Con pesar en su corazón, devolvió la perla al agua y añadió sus lágrimas como disculpa. Esa noche las lunas volvieron a brillar.",
    ["The Starpine Gurh"] = "El Gurh Estelarpino",
    ["Once, a long time ago, a seed fell from the sky and landed in the garden of a young woman called Fridal."] = "Una vez, hace mucho tiempo, una semilla cayó del cielo y aterrizó en el jardín de una joven llamada Fridal.",
    ["Fridal was poor and her family's farm was failing. Suffering from a terrible blight that caused all their crops to fail and their animals to become sick."] = "Fridal era pobre y la granja de su familia estaba fracasando. Sufriendo una terrible plaga que provocó que se arruinaran todas sus cosechas y que sus animales enfermaran.",
    ["Fridal found the seed and marvelled at its colourful hues and shimmering textures. Fearing that it too would fall to the blight if she planted it in her fields, she planted it in the dark part of the swamp where no one dared to go."] = "Fridal encontró la semilla y se maravilló de sus tonos coloridos y texturas brillantes. Temiendo que también se arruinara si lo plantaba en sus campos, lo plantó en la parte oscura del pantano, donde nadie se atrevía a ir.",
    ["She hoped it might grow into something beautiful, so that the swamps would be less frightening."] = "Esperaba que se convirtiera en algo hermoso, para que los pantanos fueran menos aterradores.",
    ["For thirteen days and fourteen nights, she watched as the seed sprouted and grew. To her dismay, it was not a thing of beauty. But a twisted and wicked-looking tree, with long, white branches that reached out like claws, and a knot in its trunk that looked like an angry gurh's face."] = "Durante trece días y catorce noches, observó cómo la semilla brotaba y crecía. Para su consternación, no era algo bello. Pero era un árbol retorcido y de aspecto malvado, con ramas largas y blancas que se extendían como garras y un nudo en el tronco que parecía la cara de un gurh enojado.",
    ["Feeling that all things have their place, even as firewood, she cut down the wicked tree and returned to her home. But the wood was damp and would not burn. To vent her frustration, Fridal chose instead to shape and carve the wood, so that something ugly might become beautiful."] = "Sintiendo que todas las cosas tienen su lugar, incluso como leña, cortó el árbol malvado y regresó a su casa. Pero la madera estaba húmeda y no ardía. Para desahogar su frustración, Fridal optó por darle forma y tallar la madera, para que algo feo se volviera hermoso.",
    ["She carved the wood into an elegant - if angry-looking - gurh, and she set it out in the garden so that it might watch over her crops."] = "Talla la madera en un gurh elegante, aunque de aspecto enojado, y lo coloca en el jardín para que pueda vigilar sus cultivos.",
    ["The next day, she discovered her fields were overflowing with crops and her sick animals were healthy. The carved gurh had no moved, but its expression had changed from one of angry to one of gentle contentment. Fridal smiled and laughed. The tree had been ugly, but as she had always thought, deep down it was truly beautiful."] = "Al día siguiente, descubrió que sus campos estaban repletos de cultivos y que sus animales enfermos estaban sanos. El gurh tallado no se había movido, pero su expresión había cambiado de una de enojo a otra de gentil satisfacción. Fridal sonrió y rió. El árbol había sido feo, pero como ella siempre había pensado, en el fondo era verdaderamente hermoso.",
    ["From that day on, Fridal's harvests were bountiful and her animals healthy. She kept looking to the sky to see if another seed would fall. After all, no gurh should be alone."] = "A partir de ese día, las cosechas de Fridal fueron abundantes y sus animales sanos. Siguió mirando al cielo para ver si caía otra semilla. Después de todo, ningún gurh debería estar solo.",
    ["Aliranna and the Whistling Beast"] = "Aliranna y la bestia silbadora",
    ["Once, long ago, there was a young man in love and as so often the case, his beloved had no idea."] = "Una vez, hace mucho tiempo, había un joven enamorado y, como suele ocurrir, su amada no tenía idea.",
    ["Even we Ilujanka can suffer from the cruel affliction of shyness and Aliranna had it worse than most."] = "Incluso nosotros, Ilujanka, podemos sufrir la cruel aflicción de la timidez y Aliranna lo pasó peor que la mayoría.",
    ["He wanted nothing more than to have the courage to speak to her, to tell her how he cared for her. But the words were like thorns in his throat and he could not get them out."] = "Lo único que quería era tener el coraje de hablar con ella, de decirle cuánto se preocupaba por ella. Pero las palabras eran como espinas en su garganta y no podía sacarlas.",
    ["There are few foes so powerful as the foe within ourselves and Aliranna's inner nemesis hated him."] = "Hay pocos enemigos tan poderosos como el enemigo dentro de nosotros mismos y el enemigo interno de Aliranna lo odiaba.",
    ["His shyness made him fade from view of others and he became as silent as a mouse. He could cross the village in the middle of the night and no one would know he were there."] = "Su timidez hizo que desapareciera de la vista de los demás y se volvió tan silencioso como un ratón. Podría cruzar el pueblo en mitad de la noche y nadie sabría que estaba allí.",
    ["If his heart had been cold he could have made an excellent thief, but the thought never crossed his mind."] = "Si hubiera tenido el corazón frío, podría haber sido un excelente ladrón, pero esa idea nunca se le pasó por la cabeza.",
    ["He was so quiet and so easily forgotten that he became as a ghost. He didn't mind. As long as he caught sight of her from time to time, he felt life was worth living."] = "Estaba tan callado y tan fácilmente olvidado que se convirtió en un fantasma. A él no le importó. Mientras la veía de vez en cuando, sentía que valía la pena vivir la vida.",
    ["But then one day the beast came. A huge and angry thing, with a maw so wide it could swallow a whole herd of gurh and with eyes so fierce that anyone who met its gaze became frozen in terror."] = "Pero un día llegó the beast. Una cosa enorme y furiosa, con unas fauces tan anchas que podría tragarse una manada entera de gurh y con ojos tan feroces que cualquiera que se encontrara con su mirada se quedaba helado de terror.",
    ["As it stalked across the village, eating and destroying as it went, it would whistle a strange tune that made the fins on the back of people's necks stand on end."] = "Mientras acechaba por la aldea, comiendo y destruyendo a medida que avanzaba, silbaba una extraña melodía que hacía que las aletas en la nuca de las personas se pusieran de punta.",
    ["By day it would raid the village, consuming stores of food and terrifying the families. By night it would curl itself around the great tree in the town centre and fall into a strange whistling slumber."] = "Durante el día asaltaba la aldea, consumía reservas de comida y aterrorizaba a las familias. Por la noche se enroscaba alrededor del gran árbol del centro de la ciudad y caía en un extraño sueño silbante.",
    ["The village warriors would try and sneak up to the creature to scare it away, but each time the beast saw them coming."] = "Los guerreros de la aldea intentaban acercarse sigilosamente a la criatura para ahuyentarla, pero cada vez the beast los veía venir.",
    ["One day the beast's tastes took a darker turn. One night, it stole the light of Aliranna's life and dragged her away to its nest."] = "Un día los gustos de the beast dieron un giro más oscuro. Una noche, robó la luz de la vida de Aliranna y la arrastró hasta su nido.",
    ["Though his shyness screamed at him, Aliranna could not let her become food for the beast, and so he went to the marshlands and there he collected three leaves of the jabracat plant. The leaves were deadly to the touch, but Aliranna's fingers were nimble and they were no danger to him."] = "Aunque su timidez le gritaba, Aliranna no podía permitir que ella se convirtiera en alimento para the beast, por lo que fue a las marismas y allí recogió tres hojas de la planta jabracat. Las hojas eran mortales al tacto, pero los dedos de Aliranna eran ágiles y no representaban ningún peligro para él.",
    ["He snuck back in the dead of night and crept up to the creature. His footsteps were silent and each breath no louder than an insect's heartbeat. The world had forgotten him and he used that to his advantage."] = "Se escabulló en mitad de la noche y se acercó sigilosamente a la criatura. Sus pasos eran silenciosos y cada respiración no era más fuerte que el latido del corazón de un insecto. El mundo lo había olvidado y él usó eso a su favor.",
    ["As the beast slept he placed the tree leaves of the jabracat plant upon it. One lay across its eyes, so the poisons would blind it. One lay across its nose, so that the toxins would rob it of its sense of smell."] = "Mientras the beast dormía, colocó las hojas del árbol de la planta jabracat sobre él. Uno yacía sobre sus ojos, para que los venenos lo cegaran. Uno se colocó sobre su nariz, para que las toxinas le quitaran el sentido del olfato.",
    ["The final he laid at its lips, so that deadly coating might force the beast to slumber deeper. When the beast was subdued, Aliranna crept into its nest and rescued his love."] = "El final lo puso en sus labios, de modo que la capa mortal de podría obligar a the beast a dormir más profundamente. Cuando the beast fue sometido, Aliranna se metió en su nido y rescató a su amor.",
    ["In the morning, the warriors chased the beast out of the village, and one week later Aliranna finally plucked up the courage to court his love."] = "Por la mañana, los guerreros expulsaron a the beast de la aldea y, una semana después, Aliranna finalmente reunió el coraje para cortejar a su amor.",
    ["The Tale of Radri the Red"] = "El cuento de Radri el Rojo",
    ["Gather then and listen of Radri the Red, who journeyed into the heart of the world in search of secrets."] = "Reúnete y escucha a Radri el Rojo, quien viajó al corazón del mundo en busca de secretos.",
    ["A long time ago, as these stories begin, was a young warrior named Radri the Red. She was so named for her scales, which were a deep crimson, unlike any other."] = "Hace mucho tiempo, cuando comienzan estas historias, había un joven guerrero llamado Radri el Rojo. Se llamaba así por sus escamas, que eran de un color carmesí intenso, como ninguna otra.",
    ["The villagers took her red scales as a sign that she was chosen by Akash, the great red moon and was therefore destined for great things."] = "Los aldeanos tomaron sus escamas rojas como una señal de que fue elegida por Akash, la gran luna roja y, por lo tanto, estaba destinada a grandes cosas.",
    ["When she came of age, the young warrior set out across the world to seek her destiny. Knowing that something wonderous must be waiting for her."] = "Cuando alcanzó la mayoría de edad, la joven guerrera partió por todo el mundo en busca de su destino. Sabiendo que algo maravilloso debía estar esperándola.",
    ["She journeyed across mountains, but found no treasure above or below. She swam across the mightiest rivers, but no spirit stopped to ask her riddles. She even braved the great fire lakes, yet all she found were crackling flames and harmless plumes of smoke."] = "Viajó a través de montañas, pero no encontró ningún tesoro ni arriba ni abajo. Nadó a través de los ríos más caudalosos, pero ningún espíritu se detuvo para preguntarle acertijos. Incluso desafió los grandes lagos de fuego, pero todo lo que encontró fueron llamas crepitantes y columnas de humo inofensivas.",
    ["For years she wandered the world in search of destiny, until she came, one day, upon a great chasm that seemed to fall down into the very heart of the world."] = "Durante años vagó por el mundo en busca de su destino, hasta que un día llegó a un gran abismo que parecía caer en el corazón mismo del mundo.",
    ["Hello!' She cried out into the darkness. But only silence answered. Having journeyed everywhere else, this was the only place left to her, so she tied a rope around a nearby tree and descended down into the darkness."] = "¡Hola!' Ella gritó en la oscuridad. Pero sólo el silencio respondió. Habiendo viajado a todos lados, este era el único lugar que le quedaba, así que ató una cuerda alrededor de un árbol cercano y descendió a la oscuridad.",
    ["The heart of the world is a dark place, where the walls are close and the air hangs heavy and thick. As Radri climbed each breath grew harder and harder, until she felt she would not have the strength to return."] = "El corazón del mundo es un lugar oscuro, donde las paredes están juntas y el aire flota pesado y denso. A medida que Radri ascendía, cada respiración se hacía más y más fuerte, hasta que sintió que no tendría fuerzas para regresar.",
    ["But she knew that destiny was down there, at the bottom of the world, so she steeled herself further and descended."] = "Pero ella sabía que el destino estaba ahí abajo, en el fondo del mundo, así que se armó de valor y descendió.",
    ["After what seemed like days, she finally reached the bottom of the chasm. All around her there was only darkness, with the only source of light being the flickering torchlight in her hands. Even the sun and the moons had abandoned this place."] = "Después de lo que parecieron días, finalmente llegó al fondo del abismo. A su alrededor solo había oscuridad, y la única fuente de luz era la parpadeante antorcha que sostenía en sus manos. Incluso el sol y las lunas habían abandonado este lugar.",
    ["At the heart of the world she found a calm like she had never felt. Though the air was thick and heavy, it did not burn her throat, nor stifle her breathing."] = "En el corazón del mundo encontró una calma como nunca había sentido. Aunque el aire era denso y pesado, no le quemaba la garganta ni le sofocaba la respiración.",
    ["As she wandered the catacombs beneath the earth, she came across the great cave illuminated by glittering stones that rested within the walls. In the heart of the room sat an ancient Ilujanka with scales as crimson as Radri's own."] = "Mientras vagaba por las catacumbas bajo tierra, se encontró con la gran cueva iluminada por piedras brillantes que descansaban dentro de las paredes. En el corazón de la habitación había una antigua Ilujanka con escamas tan carmesí como las del propio Radri.",
    ["Ah, you have come to me then? At long last.' the ancient woman asked. 'Come to seek destiny?'."] = "Ah, ¿entonces has venido a verme? Por fin. preguntó la anciana. '¿Vienes a buscar el destino?'.",
    ["Radri nodded, pleased she had finally sought what she had looked for all these years. But the old woman simply laughed, a cold and hollow laugh."] = "Radri asintió, complacida de haber finalmente buscado lo que había buscado todos estos años. Pero la anciana se limitó a reír, con una risa fría y hueca.",
    ["Then come little Radri, take my hand and see what destiny looks like."] = "Entonces ven, pequeño Radri, toma mi mano y mira cómo es el destino.",
    ["Radri stepped forward, hand stretched out in triumph and as she moved forward her hand touched the water's surface and the old woman shattered into rippling colours."] = "Radri dio un paso adelante, con la mano extendida en señal de triunfo y, mientras avanzaba, su mano tocó la superficie del agua y la anciana se hizo añicos en ondas de colores.",
    ["Moments later, she returned and faced Radri with her hand outstretched to match Radri's own."] = "Momentos después, regresó y enfrentó a Radri con la mano extendida para igualar la de Radri.",
    ["It was then that Radri recognized the old woman, for in her eyes she saw the eyes of her youth. She had spent so long searching for destiny, that she had grown ancient and old. She had forsaken every joy in life in search of a dream and now she was too late to seek another."] = "Fue entonces cuando Radri reconoció a la anciana, porque en sus ojos vio los ojos de su juventud. Había pasado tanto tiempo buscando el destino, que se había vuelto cada vez más vieja. Había abandonado todas las alegrías de la vida en busca de un sueño y ahora era demasiado tarde para buscar otro.",
    ["For it is not wise to dwell on dreams at the cost of living. Destiny, after all, does not like to be hunted."] = "Porque no es sabio insistir en sueños a costa de la vida. Al destino, después de todo, no le gusta que la persigan.",
    ["[Cancel.]"] = "[Cancelar.]",
    ["Perhaps some other time."] = "Quizás en otro momento.",
    ["You know, this workshop is much nicer than I was anticipating, based on the horror stories I'd heard."] = "Sabes, este taller es mucho mejor de lo que esperaba, basado en las historias de terror que había escuchado.",
    ["Horror stories?"] = "¿Historias de terror?",
    ["Oh yes. My dad Fionn would tell them around the bonfire in the Harvest Hollow, about his old days working in Diango's previous workshop."] = "Ah, sí. Mi papá Fionn les contaba alrededor de la hoguera en Harvest Hollow, sobre sus viejos tiempos trabajando en el taller anterior de Diango.",
    ["Let's just say you would NOT want to have been around if Slim Louie and Fat Rocco found out that you painted a bauble the wrong colour."] = "Digamos que NO querrías haber estado presente si Slim Louie y Fat Rocco descubrieran que pintaste una chuchería del color equivocado.",
    ["Dad said even Diano had a nasty streak, like he was possessed by greed! I can't imagine."] = "Dad dijo que incluso Diano tenía una racha desagradable, ¡como si estuviera poseído por la codicia! No puedo imaginarlo.",
    ["Oh, yeah. I remember having to battle marionettes with him to get him to snap out of it."] = "Ah, sí. Recuerdo haber tenido que luchar con marionetas con él para lograr que se recuperara.",
    ["Quite surprising that Santa still invited him here after that, really."] = "Es bastante sorprendente que Santa todavía lo haya invitado aquí después de eso, de verdad.",
    ["He seems to be fine now, though. And Cait's doing a wonderful job as union representative for us. Unlimited hot chocolate and gingerbread yeti breaks!"] = "Aunque parece estar bien ahora. Y Cait está haciendo un trabajo maravilloso como representante sindical para nosotros. ¡Descansos yeti ilimitados de chocolate caliente y pan de jengibre!",
    ["Living the dream!"] = "¡Viviendo el sueño!",
    ["Hi, I'm Shayk, what can I do for you?"] = "Hola, soy Shayk, ¿qué puedo hacer por ti?",
    ["Hello, what's going on?"] = "Hola, ¿qué está pasando?",
    ["What would you like to ask?"] = "¿Qué te gustaría preguntar?",
    ["Open Countdown to Menaphos Calendar"] = "Abrir cuenta atrás para el calendario Menaphos",
    ["*(Countdown to Menaphos interface opens.)*"] = "*(Se abre la cuenta atrás para la interfaz Menaphos.)*",
    ["What's all this increased activity in the desert about?"] = "¿A qué se debe todo este aumento de actividad en el desierto?",
    ["Rumour has spread that the great city of Menaphos will be opening it's gates."] = "Se ha extendido el rumor de que la gran ciudad de Menaphos abrirá sus puertas .",
    ["How do you know this?"] = "¿Cómo sabes esto?",
    ["We were once citizens but were exiled a long time ago. Mutterings have recently spread through some of our contacts that something's happening soon."] = "Una vez fuimos ciudadanos pero fuimos exiliados hace mucho tiempo. Recientemente se han difundido entre algunos de nuestros contactos rumores de que algo sucederá pronto.",
    ["Are you going to try and go back inside then?"] = "¿Vas a intentar volver a entrar entonces?",
    ["We're hoping that if we repent and change our ways, it will be viewed favourably."] = "Esperamos que si nos arrepentimos y cambiamos nuestra conducta, será visto favorablemente.",
    ["If you speak to myself or my friend Almarid who is currently outside the gates each day, we'll give you some of our erm... antiquities, so we can repent our thieving ways of old."] = "Si hablas conmigo o con mi amigo Almarid, que actualmente está fuera de las puertas todos los días, te daremos algunas de nuestras erm... antigüedades, para que podamos arrepentirnos de nuestras costumbres de ladrón de antaño.",
    ["Anything else I should know?"] = "¿Algo más que deba saber?",
    ["I can teleport you to Almarid if you like?"] = "¿Puedo teletransportarte a Almarid si quieres?",
    ["Teleport to Almarid?"] = "¿Teletransportarse a Almarid?",
    ["This will teleport you to an area of the desert where you will need water to survive."] = "Esto te teletransportará a una zona del desierto donde necesitarás agua para sobrevivir.",
    ["Continue?"] = "¿Continuar?",
    ["Who are you and what are you doing?"] = "¿Quién eres y qué estás haciendo?",
    ["We were once citizens of Menaphos but were exiled a long time ago."] = "Una vez fuimos ciudadanos de Menaphos pero fuimos exiliados hace mucho tiempo.",
    ["Now, we're attempting to seek forgiveness and gain re-entry to the great city. Perhaps you can help us..."] = "Ahora, estamos intentando buscar el perdón y lograr el reingreso a la gran ciudad. Quizás puedas ayudarnos...",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["Oi, you! Leave them alone. Gerrof them right this instant."] = "¡Oye, tú! Déjalos en paz. Gíralos en este mismo instante.",
    ["Yeah? You and whose army, you great shadowy twit? You think you can take on these razor sharp claws? Come at me, I dare you!"] = "¿Sí? ¿Tú y el ejército de quién, gran idiota sombrío? ¿Crees que podrás enfrentarte a estas garras afiladas? ¡Ven a mí, te desafío!",
    ["Who are you talking to?"] = "¿Con quién estás hablando?",
    ["Yeah. I thought you might. Not half as tough as you like to think you are, are you?"] = "Sí. Pensé que podrías hacerlo. No eres ni la mitad de duro de lo que te gusta pensar, ¿verdad?",
    ["This has gotten too weird, I'm off."] = "Esto se ha vuelto demasiado raro, me voy.",
    ["You can only save some of them, you know. I know you'll try to save everyone, but you can't and that's not your fault."] = "Sólo puedes guardar algunos de ellos, ¿sabes? Sé que intentarás salvar a todos, pero no puedes y eso no es tu culpa.",
    ["Erm, thanks?"] = "Erm, ¿gracias?",
    ["You don't have enough space in your backpack to carry any wool you would shear."] = "No tienes suficiente espacio en tu backpack para transportar la lana que cortarías.",
    ["You get some wool."] = "Consigue un poco de lana.",
    ["You should talk to Farmer Fred before shearing his special sheep."] = "Deberías hablar con el granjero Fred antes de esquilar sus ovejas especiales.",
    ["You get some black wool."] = "Obtienes un poco de lana negra.",
    ["I respect the sheep, bar none, for their purpose is essential, albeit secret."] = "Respeto a las ovejas, sin excepción, porque su propósito es esencial, aunque sea secreto.",
    ["Where there is wool, there is a way."] = "Donde hay lana, hay un camino.",
    ["Some day, you too might discover the true power of the sheep, innocent in appearance but essential in bearing."] = "Algún día, tú también podrías descubrir el verdadero poder de la oveja, inocente en apariencia pero esencial en su porte.",
    ["Sheep are under my protection. Harm them at your peril, or you shall pay for your transgression."] = "Sheep están bajo mi protección. Hazles daño bajo tu propio riesgo, o pagarás por tu transgresión.",
    ["I shall not tolerate such sheer audacity."] = "No toleraré tal audacia.",
    ["Allow me to ram this point home: watch out for the sheep with webbed feet. They are mutton but trouble, and more cunning than they look."] = "Permítanme aclarar este punto: cuidado con las ovejas con patas palmeadas. Son carneros pero problemáticos y más astutos de lo que parecen.",
    ["Though if you cannot bleat them, join them."] = "Aunque si no puedes balarlos, únete a ellos.",
    ["**Player: ** That's a sheep...I think. I can't talk to sheep."] = "**Player: ** Eso es una oveja...creo. No puedo hablar con las ovejas.",
    ["Hello, I've just finished composing my latest poem. Would you like to hear it?"] = "Hola, acabo de terminar de componer mi último poema. ¿Te gustaría escucharlo?",
    ["Excellent! The human's an aficionado! Make yourself comfortable and I'll begin..."] = "¡Excelente! ¡El humano es un aficionado! Ponte cómodo y empezaré...",
    ["How goes it, blade of grass? I'm glad you're not any thinner You should invite your friends around So I can have my dinner!"] = "¿Cómo te va, brizna de hierba? Me alegro de que no estés más delgado Deberías invitar a tus amigos ¡Así puedo cenar!",
    ["I wish I were a cow My life would be so simple I could lie around just eating grass And wonder if I were a pimple."] = "Ojalá fuera una vaca Mi vida sería tan simple Podría quedarme tumbado comiendo hierba Y preguntarme si sería un grano.",
    ["Hahaha, I don't think!"] = "¡Jajaja, no lo creo!",
    ["Well I thought it was funny."] = "Bueno, pensé que era divertido.",
    ["T'was brillig and the slithey toathes Did gyre and gimbol in the wabe All mimsy were the borrowgroves And the mome raths outgrabe."] = "Era brillante y los toathes deslizantes Hizo giros y gimboles en el wabe Todas las mimsy eran los toathes Y los mome raths superaron.",
    ["That's not even your poem, you idiotic, animated ball of wool!"] = "¡Ese ni siquiera es tu poema, idiota y animado ovillo de lana!",
    ["How now foolish cow? Do you read poetry, instead of pulling a plough?"] = "¿Y ahora vaca tonta? ¿Lees poesía en lugar de tirar del arado?",
    ["I'm not talking to you any more, you're nasty."] = "Ya no te hablo más, eres desagradable.",
    ["Oh no! Cow's not talking to me!"] = "¡Oh, no! ¡Cow no me habla!",
    ["Do I look like I care?"] = "¿Parece que me importa?",
    ["Twinkle, twinkle little egg Wouldn't you like to grow some legs? And run around, on grass so green arguing with the milk and cream."] = "Brilla, brilla huevito ¿No te gustaría que te crecieran unas piernas? Y correr por ahí, sobre la hierba tan verde Discutiendo con la leche y la nata.",
    ["Huh, the cow's right. You humans have absolutely no understanding of art!"] = "Eh, la vaca tiene razón. ¡Ustedes los humanos no tienen absolutamente ninguna comprensión del arte!",
    ["You give me a hair-cut and then expect me to talk to you? I think not!"] = "¿Me cortas el pelo y luego esperas que hable contigo? ¡Creo que no!",
    ["You find something on one of Sheldon's hats."] = "Encuentras algo en uno de los sombreros de Sheldon.",
    ["[You need 1 free space in your backpack to receive your clue caskets.]"] = "[Necesitas 1 espacio libre en tu backpack para recibir tus cofres de pistas.]",
    ["Category:Non-spoken transcripts"] = "Categoría: Transcripciones no habladas",
    ["Crabs Against Villagers went so well! I think I found my calling as a spokesperson."] = "¡Cangrejos contra aldeanos salió muy bien! Creo que encontré mi vocación como portavoz.",
    ["You guys didn't manage to take over the villager's houses though?"] = "¿Pero ustedes no lograron apoderarse de las casas de los aldeanos?",
    ["I know, but did you see how everyone was listening to me! I was the most important crab in the room."] = "Lo sé, pero ¿viste cómo todos me escuchaban? Yo era el cangrejo más importante de la sala.",
    ["Spokesperson Shelly' does have a nice ring to it."] = "Portavoz Shelly' suena bien.",
    ["I can't wait to decorate my hut. The only problem is that dad wants to paint the walls an ugly 'seaweed green', but I want them in a calming 'seashell blue'. Ugh."] = "No veo la hora de decorar mi cabaña. El único problema es que papá quiere pintar las paredes de un feo 'verde alga', pero yo las quiero de un relajante 'azul concha'. Puaj.",
    ["Maybe I'll pop in to see Hermit again.. His cave is a bit nasty, but one of the boulder crabs nearby is SUPER cute."] = "Tal vez vuelva a visitar a Hermit. Su cueva es un poco desagradable, pero uno de los cangrejos de roca cercanos es SÚPER lindo.",
    ["Hello youngster!"] = "¡Hola joven!",
    ["I don't talk to strange old people."] = "No hablo con personas mayores extrañas.",
    ["Hey who you calling old?! And strange?!"] = "¡¿Oye, a quién llamas viejo?! ¡¿Y extraño?!",
    ["You obviously. Old, strange and stupid."] = "Tú, obviamente. Viejo, extraño y estúpido.",
    ["Whatever."] = "Lo que sea.",
    ["You think you're tough do you?"] = "¿Crees que eres duro, verdad?",
    ["Pardon?"] = "¿Perdón?",
    ["I can beat anyone up!"] = "¡Puedo vencer a cualquiera!",
    ["He can you know."] = "Él puede saberlo.",
    ["The boy begins to jump around with his fists up. You wonder what sort of desperado he'll grow up to be."] = "El niño comienza a saltar con los puños en alto. Uno se pregunta en qué clase de desesperado se convertirá cuando crezca.",
    ["Good day to you."] = "Buenos días para ti.",
    ["Be in here and don't touch anything! There's some old and valuable artefacts around here. Careless outsiders.. you're always coming in and making a mess of things!"] = "¡Quédate aquí y no toques nada! Hay algunos artefactos antiguos y valiosos por aquí. Forasteros descuidados... ¡siempre vienen y hacen un desastre!",
    ["Ok calm down, I'm not going to touch anything."] = "Ok, cálmate, no voy a tocar nada.",
    ["Yes, good don't."] = "Sí, bueno, no lo hagas.",
    ["What is this building?"] = "¿Qué es este edificio?",
    ["This is our local shrine to She."] = "Este es nuestro santuario local para Ella.",
    ["What do you mean by She?"] = "¿Qué quieres decir con Ella?",
    ["Such ignorance! I suppose I should come to expect it. People are forgetting the old ways of the desert around here. But then.. do those bureaucratic fools in Menaphos expect! If they're going to take so long to send"] = "¡Qué ignorancia! Supongo que debería esperarlo. La gente se está olvidando de las viejas costumbres del desierto por aquí. Pero entonces... ¡qué esperan esos tontos burocráticos de Menaphos! Si van a tardar tanto en enviar",
    ["us a new priestess of She. Do you know we haven't had one for five years now!"] = "nosotros una nueva sacerdotisa de Ella. ¿Sabes que hace cinco años que no tenemos uno?",
    ["Errm you still haven't told me what you mean by She."] = "Errm, todavía no me has dicho qué quieres decir con Ella.",
    ["She! Otherwise known as Elidinis, Goddess of growth and fertility, Lady of the river, Wife of Tumeken, Flower of the desert, Mother of Icthlarin."] = "¡Ella! También conocida como Elidinis, Diosa del crecimiento y la fertilidad, Señora del río, Esposa de Tumeken, Flor del desierto, Madre de Icthlarin.",
    ["That all sounds very confusing, I might just call her Elidinis for short."] = "Todo eso suena muy confuso, podría llamarla Elidinis para abreviar.",
    ["Thanks for returning the statuette. You have freed us of our curse. May you forever be considered a friend of Elidinis and her followers."] = "Gracias por devolver la estatuilla. Nos has liberado de nuestra maldición. Que siempre seas considerado amigo de Elidinis y sus seguidores.",
    ["Oh, I've been expecting you."] = "Oh, te estaba esperando.",
    ["[Shiratti has given you a puzzle box!]"] = "[¡Shiratti te ha regalado una caja de rompecabezas!]",
    ["That's not right, not right at all."] = "Eso no está bien, nada bien.",
    ["[Shiratti has given you another clue scroll!]"] = "[¡Shiratti te ha dado otro pergamino de pistas!]",
    ["Enjoy your reward!"] = "¡Disfruta de tu recompensa!",
    ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
    ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
    ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
    ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
    ["What do you think of Ali Morrisane?"] = "¿Qué opinas de Ali Morrisane?",
    ["I don't trust him. Not after he's sent his men round to threaten us. Did you know, we've had four different thugs come round and threaten us if we don't join them? The owner has had hammers, rakes, swords and even scissors waved at him!"] = "No confío en él. No después de haber enviado a sus hombres para amenazarnos. ¿Sabías que cuatro matones diferentes nos han amenazado si no nos unimos a ellos? ¡Al propietario le han agitado martillos, rastrillos, espadas e incluso tijeras!",
    ["What will you do about it?"] = "¿Qué harás al respecto?",
    ["We'll carry on as normal with the store. Business as usual! Can I interest you in anything?"] = "Continuaremos con normalidad con la tienda. ¡Negocios como siempre! ¿Puedo interesarte en algo?",
    ["Yes please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
    ["What happened to your building?"] = "¿Qué pasó con tu edificio?",
    ["Yes, we did have some problems with the arrival of Zamorak and Saradomin; the upstairs is a little damaged."] = "Sí, tuvimos algunos problemas con la llegada de Zamorak y Saradomin; el piso de arriba está un poco dañado.",
    ["But we fared a lot better than Hank or Jack, so we are thankful! The battle is not good for business though."] = "Pero nos fue mucho mejor que a Hank o Jack, ¡así que estamos agradecidos! Sin embargo, la batalla no es buena para los negocios.",
    ["However, we are still open for business! Do you want to see our wares?"] = "Sin embargo, ¡todavía estamos abiertos al público! ¿Quieres ver nuestros productos?",
    ["Yes, we sustained some damage at the start of the battle of Lumbridge. We fared better than Hank and Jack though!"] = "Sí, sufrimos algunos daños al comienzo de la batalla de Lumbridge. ¡Sin embargo, nos fue mejor que a Hank y Jack!",
    ["I'm glad all that is over, and we can get back to rebuilding our business! Do you want to see our wares?"] = "¡Me alegra que todo esto haya terminado y que podamos volver a reconstruir nuestro negocio! ¿Quieres ver nuestros productos?",
    ["Yes, we sustained some damage at the start of the battle of Lumbridge. We fared better than Hank and Jack, although their houses are being sorted out by Foreman George and his team!"] = "Sí, sufrimos algunos daños al comienzo de la batalla de Lumbridge. Nos fue mejor que a Hank y Jack, ¡aunque Foreman George y su equipo están arreglando sus casas!",
    ["Soon, we too can get back to rebuilding our business! Do you want to see our wares?"] = "¡Pronto nosotros también podremos volver a reconstruir nuestro negocio! ¿Quieres ver nuestros productos?",
    ["We sustained some damage at the start of the battle of Lumbridge but Foreman George and his fantastic team are working on fixing all that. Sorry about the noise, by the way!"] = "Sufrimos algunos daños al comienzo de la batalla de Lumbridge, pero Foreman George y su fantástico equipo están trabajando para solucionarlo. ¡Perdón por el ruido, por cierto!",
    ["In the meantime, it's business as usual. Do you want to see our wares?"] = "Mientras tanto, todo sigue igual. ¿Quieres ver nuestros productos?",
    ["We sustained some damage at the start of the battle of Lumbridge but Foreman George and his team have done a fantastic job and patched up the damage perfectly!"] = "Sufrimos algunos daños al comienzo de la batalla de Lumbridge, ¡pero Foreman George y su equipo hicieron un trabajo fantástico y repararon el daño perfectamente!",
    ["Now we're properly back in business, would you like to see our wares?"] = "Ahora que volvemos a estar en funcionamiento, ¿le gustaría ver nuestros productos?",
    ["It's a beautiful day today, no? Can I do anything for you?"] = "Hoy hace un hermoso día, ¿no? ¿Puedo hacer algo por ti?",
    ["Hello, bold adventurer. Can I interest you in some swords?"] = "Hola, aventurero audaz. ¿Puedo interesarte en algunas espadas?",
    ["No, I'm okay for swords right now."] = "No, estoy bien con las espadas en este momento.",
    ["Come back if you need any."] = "Vuelve si necesitas alguno.",
    ["Yes please, what are you selling?"] = "Si por favor, ¿qué vendes?",
    ["I don't trust him, not after he's sent his men round to threaten us. Did you know, we've had four different thugs come round and threaten us if we don't join them. I've had hammers, rakes, swords and even scissors waved at me!"] = "No confío en él, no después de que envió a sus hombres para amenazarnos. ¿Sabías que cuatro matones diferentes nos han amenazado si no nos unimos a ellos? ¡Me han saludado con martillos, rastrillos, espadas e incluso tijeras!",
    ["So, are you looking to buy weapons? King Lathas keeps us very well stocked."] = "Entonces, ¿estás buscando comprar armas? King Lathas nos mantiene muy bien abastecidos.",
    ["What do you have?"] = "¿Qué tienes?",
    ["Take a look."] = "Echa un vistazo.",
    ["Ask about contracts"] = "Preguntar por contracts",
    ["What do you need repairing?"] = "¿Qué necesitas reparar?",
    ["Let me see, right now I need you to repair the following pieces of furniture."] = "Déjame ver, ahora mismo necesito que repares el siguiente pieces of furniture.",
    ["What materials do I need?"] = "¿Qué materiales necesito?",
    ["You need: Planks x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: Planks x [número], Steel nails x [número], [Additional material] x [número]",
    ["Ask about something else"] = "pregunta sobre otra cosa",
    ["I'm glad you ask! The shop has two sections to it: 'Main stock' and 'Free sample items'."] = "¡Me alegra que lo preguntes! La tienda tiene dos secciones: 'Stock principal' y 'Artículos de muestra gratuitos'.",
    ["From 'Main Stock' you can buy as many of the stocked items as you wish. I also offer free samples to help get you started and to keep you coming back. Once you take a free sample, I won't give you another for about a half an hour. I'm not made of money, you know!"] = "Desde 'Stock principal' puedes comprar tantos artículos en stock como desees. También ofrezco muestras gratuitas para ayudarle a comenzar y hacer que regrese. Una vez que tomes una muestra gratis, no te daré otra hasta dentro de media hora. ¡No estoy hecho de dinero, sabes!",
    ["You can also sell most items to the shop."] = "También puedes vender la mayoría de los artículos en la tienda.",
    ["Thank you."] = "Gracias.",
    ["You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "Puedes comprar tantos artículos almacenados como desees. También puedes vender la mayoría de los artículos en la tienda.",
    ["Didn't you used to be a shop assistant?"] = "¿No solías ser un shop assistant?",
    ["Yes, the general store owner died last year when the demon Delrith rampaged through Varrock."] = "Sí, el propietario de general store murió el año pasado cuando el demonio Delrith arrasó Varrock.",
    ["Delrith used him as a pillow to sit on."] = "Delrith lo usó como almohada para sentarse.",
    ["It took me ages to work the stains out of the floorboards."] = "Me tomó mucho tiempo quitar las manchas de las tablas del piso.",
    ["Hello. You're a bold one. Can I interest you in some swords?"] = "Hola. Eres un atrevido. ¿Puedo interesarte en algunas espadas?",
    ["No. Goodbye."] = "No, adiós.",
    ["Thanks for helping me out, friend. What can I do for you?"] = "Gracias por ayudarme, amigo. ¿Qué puedo hacer por ti?",
    ["Welcome to Tom's Trove. Where every purchase...is one you'll treasure."] = "Bienvenido a Tom's Trove. Donde cada compra... será algo que atesorarás.",
    ["Can I see your wares?"] = "¿Puedo ver tus productos?",
    ["Of course. I cannot express how much joy it would bring me. I love this job."] = "Por supuesto. No puedo expresar cuánta alegría me traería. Me encanta este trabajo.",
    ["Thank you for your visit. It would bring me no greater pleasure than to see you return again in the future."] = "Gracias por tu visita. No me traería mayor placer que verlo regresar nuevamente en el futuro.",
    ["Joining Villagers Against Crabs has done nothing for me so far. These crustaceans won't stop stinking up the shop."] = "Unirme a Villagers Against Crabs no ha hecho nada por mí hasta ahora. Estos crustáceos no dejarán de apestar la tienda.",
    ["*(If on a construction contract:)* <sub>*(Only for shopkeepers in Lumbridge, Varrock and Edgeville)*</sub> Ask about contracts"] = "*(Si está en un construction contract:)* <sub>*(Solo para comerciantes en Lumbridge, Varrock y Edgeville)*</sub> Pregunte por contracts",
    ["You need: [Planks] x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: [Planks] x [número], Steel nails x [número], [Additional material] x [número]",
    ["Once I was but a girl. Full of sin and happy for it."] = "Una vez yo no era más que una niña. Lleno de pecado y feliz por ello.",
    ["But now I am reborn, purified and enlightened."] = "Pero ahora he renacido, purificado e iluminado.",
    ["Papa would be proud of me."] = "Papá estaría orgulloso de mí.",
    ["But such worldly connections are no longer my concern."] = "Pero esas conexiones mundanas ya no son de mi incumbencia.",
    ["Lady Himiko has cured my sin."] = "Lady Himiko ha curado mi pecado.",
    ["Can you hear the song?"] = "¿Puedes oír la canción?",
    ["It's beautiful. Like staring into the ocean depths."] = "Es hermoso. Como mirar fijamente las profundidades del océano.",
    ["I am lost in it."] = "Estoy perdido en ello.",
    ["Papa forgive me. I am not who I was."] = "Papá, perdóname. No soy quien era.",
    ["*The last line is repeated until Elei is defeated*"] = "*La última línea se repite hasta que Elei sea derrotado*",
    ["Noooooo sushi!"] = "¡Nooooo sushi!",
    ["Yuck!"] = "¡Qué asco!",
    ["Get it away!"] = "¡Apártate!",
    ["*retching noises*"] = "*ruidos de arcadas*",
    ["Talk about 'Visions of Havenhythe'."] = "Habla sobre 'Visiones de Havenhythe'.",
    ["Welcome to our shrine. Apologies, but we're quite busy at the moment."] = "Bienvenido a nuestro santuario. Disculpas, pero estamos bastante ocupados en este momento.",
    ["No problem. I'll come by later."] = "No hay problema. Pasaré más tarde.",
    ["May The Great Wolf watch over you, friend. You are always welcome at this shrine."] = "Que El Gran Lobo te cuide, amigo. Siempre eres bienvenido a este santuario.",
    ["Can you tell me more about Inanna?"] = "¿Puedes contarme más sobre Inanna?",
    ["It would be my pleasure."] = "Sería un placer.",
    ["My beliefs are somewhat traditional. She is the guardian of our lands, a herald and messenger sent to us by the gods themselves in ages past."] = "Mis creencias son algo tradicionales. Ella es la guardiana de nuestras tierras, una heralda y mensajera enviada por los propios dioses en épocas pasadas.",
    ["In her we see Guthix's patience. Saradomin's wisdom. Zamorak's strength."] = "En ella vemos la paciencia de Guthix. La sabiduría de Saradomin. La fuerza de Zamorak.",
    ["When we pray to Inanna, we are offering prayers to each of the gods she represents. She is a unifying embodiment of all we value and cherish."] = "Cuando rezamos a Inanna, estamos ofreciendo oraciones a cada uno de los dioses que ella representa. Ella es una encarnación unificadora de todo lo que valoramos y apreciamos.",
    ["That's definitely a unique approach to worship."] = "Ese es definitivamente un enfoque único de adoración.",
    ["Most outlanders are confused by our beliefs. From what I understand there is a great deal of conflict between the followers of different gods on the mainland."] = "La mayoría de los forasteros están confundidos por nuestras creencias. Por lo que tengo entendido, hay muchos conflictos entre los seguidores de diferentes dioses en el continente.",
    ["That's putting it lightly."] = "Eso es decirlo a la ligera.",
    ["Thank you for sharing this with me."] = "Gracias por compartir esto conmigo.",
    ["It is nothing. Go in peace, friend."] = "No es nada. Vete en paz, amigo.",
    ["It's an honour to have you visit our shrine again, blessed of The Great Wolf."] = "Es un honor que visites nuevamente nuestro santuario, bendito del Gran Lobo.",
    ["Is there anything I can help you with?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["I was hoping you could tell me more about Inanna."] = "Esperaba que pudieras contarme más sobre Inanna.",
    ["Inanna is benevolent, nurturing and patient. Stepping in to protect her children when the need arises while providing them the distance to thrive independently of her."] = "Inanna es benevolente, cariñoso y paciente. Intervenir para proteger a sus hijos cuando surge la necesidad y al mismo tiempo brindarles la distancia para prosperar independientemente de ella.",
    ["She provided guidance to our ancestors when they first arrived here. Every Wendlewicker and their family has a unique history with and connection to her."] = "Ella brindó orientación a nuestros antepasados cuando llegaron aquí por primera vez. Cada Wendlewicker y su familia tienen una historia única y una conexión con ella.",
    ["Even my brother and I have differing philosophies, despite both tending her shrine."] = "Incluso mi hermano y yo tenemos filosofías diferentes, a pesar de que ambos cuidamos su santuario.",
    ["What are your beliefs?"] = "¿Cuáles son tus creencias?",
    ["Inanna is more than a mere messenger of the gods. She is a deity in and of herself."] = "Inanna es más que un simple mensajero de los dioses. Ella es una deidad en sí misma.",
    ["She is the one who lives among our people and safeguards our lands, while asking nothing of us in return."] = "Ella es quien vive entre nuestra gente y salvaguarda nuestras tierras, sin pedirnos nada a cambio.",
    ["The other gods crave worship, while The Great Wolf is selfless and humble. That is why she and she alone deserves my reverence."] = "Los otros dioses anhelan adoración, mientras que El Gran Lobo es desinteresado y humilde. Por eso ella y sólo ella merece mi reverencia.",
    ["I understand. Thank you for sharing that with me."] = "Lo entiendo. Gracias por compartir eso conmigo.",
    ["You are very welcome. May Inanna watch over you, my friend."] = "De nada. Que Inanna te cuide, amigo mío.",
    ["NO. You get away. Now!"] = "NO. Te escapas. ¡Ahora!",
    ["If you not go away..."] = "Si no te vas...",
    ["I erupt all over you!"] = "¡Estallo sobre ti!",
    ["Nyeehhh!"] = "¡Nyeehhh!",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["I have this acne potion which I thought might help ease your itching."] = "Tengo esta poción para el acné que pensé que podría ayudarte a aliviar la picazón.",
    ["Keh! Get away from me. The only potion or solutions I'll have anything to do with are dyes."] = "¡Eh! Aléjate de mí. La única poción o solución con la que tendré que ver es dyes.",
    ["Sorry I was just trying to help."] = "Lo siento, solo estaba tratando de ayudar.",
    ["Hello there and welcome to the shop of useful items. Can I help you at all?"] = "Hola y bienvenido a la tienda de artículos útiles. ¿Puedo ayudarte en algo?",
    ["Ok, well, if you change your mind, do pop back."] = "Ok, bueno, si cambias de opinión, vuelve.",
    ["Didn't you once sell Silverlight?"] = "¿No vendiste Silverlight alguna vez?",
    ["Silverlight? Oh, Sir Prysin of Varrock explained that was a unique sword and told us to stop selling it. If you want Silverlight and don't have it, you should speak to Gideon Bede."] = "¿Luz plateada? Oh, Sir Prysin de Varrock explicó que era una espada única y nos dijo que dejáramos de venderla. Si quieres Silverlight y no lo tienes, debes hablar con Gideon Bede.",
    ["Can I interest you in a warhammer? I now have dragon warhammers in stock!"] = "¿Puedo interesarte en un martillo de guerra? ¡Ahora tengo Dragon Warhammers en stock!",
    ["Dragon warhammers?"] = "¿Martillos de guerra de dragones?",
    ["Yes! The Black Guard recovered schematics on how to make them from the Red Axe base. Supreme Commander Bisi has asked me to make them for the elite Black Guard berserkers, and I'm also selling them here."] = "¡Sí! El Black Guard recuperó esquemas sobre cómo hacerlos a partir de la base de Red Axe. Supreme Commander Bisi me pidió que los hiciera para los berserkers de élite de Black Guard, y también los vendo aquí.",
    ["What happened to Vigr?"] = "¿Qué pasó con Vigr?",
    ["*(If Vigr was exiled:)*"] = "*(Si Vigr fue exiliado:)*",
    ["He was exiled! The Black Guard marched him straight out of the city. I've heard a lot of exiles end up near Yanille."] = "¡Fue exiliado! El Black Guard lo sacó directamente de la ciudad. He oído que muchos exiliados acaban cerca de Yanille.",
    ["*(If Vigr was executed:)*"] = "*(Si se ejecutó Vigr:)*",
    ["He was executed as a Red Axe spy! His remains will have been thrown into the Kelda. I suppose it's what he deserves if he was really working for the Red Axe."] = "¡Fue ejecutado como espía de Red Axe! Sus restos habrán sido arrojados al Kelda. Supongo que es lo que se merece si realmente estuviera trabajando para Red Axe.",
    ["Oi! Did I say you could use that?"] = "¡Oye! ¿Dije que podrías usar eso?",
    ["Hands off! That fireplace belongs to me! Not some puny arrogant human!"] = "¡No toques! ¡Esa chimenea me pertenece! ¡No un humano insignificante y arrogante!",
    ["Didn't all this belong to the Red Axe? And weren't you a member?"] = "¿No pertenecía todo esto al Hacha Roja? ¿Y no eras miembro?",
    ["I don't know what you're talking about."] = "No sé de qué estás hablando.",
    ["Oi! Did I say you could use my fireplace?"] = "¡Oye! ¿Dije que podías usar mi chimenea?",
    ["Oi! Did I say you could use my furnace?"] = "¡Oye! ¿Dije que podías usar mi horno?",
    ["Can we help you with anything?"] = "¿Podemos ayudarte en algo?",
    ["Can I go through the gate?"] = "¿Puedo pasar por la puerta?",
    ["If you want, we will let you pass into the Wilderness. Be warned that other players might attack you there, and you won't be allowed through the gate while you're in combat."] = "Si quieres, te dejaremos pasar al Wilderness. Ten en cuenta que otros jugadores podrían atacarte allí y no se te permitirá atravesar la puerta mientras estés en combate.",
    ["I am not afraid."] = "No tengo miedo.",
    ["Your speech is brave. Travel south-west, and you should reach the city of Varrock, if you don't die first."] = "Tu discurso es valiente. Viaja hacia el suroeste y deberías llegar a la ciudad de Varrock, si no mueres primero.",
    ["Now, can we help you with anything else?"] = "Ahora, ¿podemos ayudarte con algo más?",
    ["Is there any other way out of here?"] = "¿Hay alguna otra manera de salir de aquí?",
    ["Not...really. You could try one of your teleport spells, or those lodestone things you adventurers seem to be keen on."] = "No... en realidad. Podrías probar uno de tus hechizos de teletransporte o esas cosas lodestone que a los aventureros parecen gustarles.",
    ["It's far safer than trying to walk through the Wilderness. Now, can we help you with anything else?"] = "Es mucho más seguro que intentar caminar por Wilderness. Ahora bien, ¿podemos ayudarte en algo más?",
    ["Forget it, I'm not going through there."] = "Olvídalo, no voy a pasar por ahí.",
    ["That is wise. Now, can we help you with anything else?"] = "Eso es sabio. Ahora bien, ¿podemos ayudarte en algo más?",
    ["We are guarding Bryll and the other adventurers against the vicious fighters who roam the Wilderness."] = "Estamos protegiendo a Bryll y a los demás aventureros contra los feroces luchadores que deambulan por Wilderness.",
    ["Good luck with that."] = "Buena suerte con eso.",
    ["Thank you. Now, can we help you with anything else?"] = "Gracias. Ahora bien, ¿podemos ayudarte en algo más?",
    ["*When speaking to Sigbert the Adventurer in Yanille Agility Dungeon.*"] = "*Al hablar con Sigbert the Adventurer en Yanille Agility Dungeon.*",
    ["I'd be very careful going down there, friend."] = "Tendría mucho cuidado al bajar allí, amigo.",
    ["Why? What's down there?"] = "¿Por qué? ¿Qué hay ahí abajo?",
    ["Salarin the Twisted, one of Kandarin's most dangerous chaos druids. I tried to take him on, then suddenly felt immensely weak. I hear he's susceptible to attacks from the mind. However I have no idea what that means, so it's not much help to me."] = "Salarin el Retorcido, uno de los druidas del caos más peligrosos de Kandarin. Intenté enfrentarme a él, pero de repente me sentí inmensamente débil. He oído que es susceptible a los ataques de la mente. Sin embargo, no tengo idea de lo que eso significa, por lo que no me resulta de mucha ayuda.",
    ["Fear not! I am very strong."] = "¡No temas! Soy muy fuerte.",
    ["You might find you are not so strong shortly..."] = "Es posible que pronto descubras que no eres tan fuerte...",
    ["I do not speak to outerlanders. If you have anything of import to say, go and speak to the Chieftain."] = "No hablo con los extranjeros. Si tienes algo importante que decir, ve y habla con el Cacique.",
    ["Hello again Sigli."] = "Hola de nuevo Sigli.",
    ["Hello again to you [Fremennik name]. How goes the hunt?"] = "Hola de nuevo a ti [Fremennik name]. ¿Cómo va la caza?",
    ["The hunt? I've already done your task! That's why I'm a Fremennik now!"] = "¿La caza? ¡Ya hice tu tarea! ¡Por eso ahora soy Fremennik!",
    ["You think so do you? The Draugen is always out there, just as I and my hunters are always on its trail to keep it at bay. The hunt will never end until I do."] = "¿Crees que sí? El Draugen siempre está ahí fuera, al igual que mis cazadores y yo siempre estamos tras su rastro para mantenerlo a raya. La caza nunca terminará hasta que yo lo haga.",
    ["What would you like to ask about?"] = "¿Sobre qué te gustaría preguntar?",
    ["Hello there. I have some spined dagannoth hides, and believe you might be able to make an armour of them for me...?"] = "Hola. Tengo algunas pieles de dagannoth con espinas y creo que podrías hacerme una armadura con ellas...",
    ["That is fine, [Fremennik name]. What type of armour were you looking for?"] = "Está bien, [Fremennik name]. ¿Qué tipo de armadura buscabas?",
    ["A fine helm"] = "Un buen timón",
    ["It will cost you 7,500 coins to make that for you. Is that acceptable?"] = "Te costará 7500 coins hacerlo por ti. ¿Es eso aceptable?",
    ["YES"] = "SI",
    ["*If you have the required materials:*"] = "*Si cuentas con los materiales requeridos:*",
    ["*If you lack the required materials:*"] = "*Si te faltan los materiales requeridos:*",
    ["Sorry, [Fremennik name]. I will need 1 piece of dark daggermouth hide, 1 circular light daggermouth hide and 5,000 coins to make you a hunter's helmet. When you have them, I will still be here."] = "Lo siento, [Fremennik name]. Necesitaré 1 pieza de piel de boca de daga oscura, 1 piel de boca de daga clara circular y 5000 coins para hacerte un casco de cazador. Cuando los tengas, todavía estaré aquí.",
    ["Sturdy"] = "Robusto",
    ["It will cost you 10,000 coins to make that for you. Is that acceptable?"] = "Te costará 10,000 coins hacerlo por ti. ¿Es eso aceptable?",
    ["A fine piece of armour for any hunter! Did you want me to make you another?"] = "¡Una excelente armadura para cualquier cazador! ¿Querías que te hiciera otro?",
    ["I'm sorry, but I need 3 pieces of dark daggermouth hide, 1 flattened hide and 10,000 coins to make you some hunter's body armour. I will still be here when you have obtained it."] = "Lo siento, pero necesito 3 piezas de piel de boca de daga oscura, 1 piel aplanada y 10 000 coins para hacerte una armadura de cazador. Todavía estaré aquí cuando lo hayas obtenido.",
    ["Powerful leg armour"] = "Potente armadura para las piernas",
    ["That should do for any hunter! Did you want another set of legs?"] = "¡Eso debería servirle a cualquier cazador! ¿Querías otro par de piernas?",
    ["My apologies but I will need 2 pieces of dark daggermouth hide, 1 stretched hide and 7,500 coins to make you some leg armour..."] = "Mis disculpas, pero necesitaré 2 piezas de piel de boca de daga oscura, 1 piel estirada y 7500 coins para hacerte una armadura para las piernas...",
    ["Actually, I don't want anything."] = "En realidad, no quiero nada.",
    ["you wish."] = "lo deseas.",
    ["The Fremennik Trials"] = "Los juicios de Fremennik",
    ["Hello there!"] = "¡Hola!",
    ["Hello outerlander. By the laws of our tribe, I am afraid I may not speak to you without the express permission of the chieftain."] = "Hola extranjero. Según las leyes de nuestra tribu, me temo que no puedo hablar contigo sin el permiso expreso del jefe.",
    ["Where would I find him?"] = "¿Dónde podría encontrarlo?",
    ["In the longhall, outerlander."] = "En el salón largo, exterior.",
    ["Only Fremenniks may trade with this merchant."] = "Sólo los Fremenniks pueden comerciar con este comerciante.",
    ["Greetings again [brother/sister] [Fremennik name]! What can I do for you this day?"] = "¡Saludos de nuevo [brother/sister] [Fremennik name]! ¿Qué puedo hacer por ti este día?",
    ["Certainly, [Fremennik name]."] = "Por supuesto, [Fremennik name].",
    ["Nothing thanks."] = "Nada, gracias.",
    ["Well, feel free to stop by anytime that you wish [Fremennik name]. You are always welcome here!"] = "Bueno, siéntete libre de pasar por aquí cuando lo desees [Fremennik name]. ¡Siempre eres bienvenido aquí!",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["Do you have any quests for me?"] = "¿Tienes alguna misión para mí?",
    ["I'm the Duke's advisor."] = "Soy el consejero del Duque.",
    ["Can you give me any advice then?"] = "¿Puedes darme algún consejo entonces?",
    ["I only advise the Duke. But if you want to make yourself useful, there are evil goblins to slay on the other side of the river."] = "Sólo aconsejo al Duque. Pero si quieres ser útil, hay duendes malvados a los que matar al otro lado del río.",
    ["You win this time, Player. But I will have my revenge!"] = "Esta vez ganas, Player. ¡Pero tendré mi venganza!",
    ["I'll get you, Player, if it's the last thing I do!"] = "¡Te atraparé, Player, aunque sea lo último que haga!",
    ["...And I would have gotten away with it too, if it wasn't for that pesky adventurer!"] = "... ¡Y yo también me habría salido con la mía, si no fuera por ese molesto aventurero!",
    ["Hey, it's our newest dragon slayer!"] = "¡Oye, es nuestro dragon slayer más nuevo!",
    ["I told you Player would make it into the guild. Didn't I tell you?"] = "Te dije que Player entraría al gremio. ¿No te lo dije?",
    ["I still can't believe you got through that Kinshra base without being detected."] = "Todavía no puedo creer que hayas atravesado esa base de Kinshra sin ser detectado.",
    ["There were a couple of close calls. I had to hide in a cupboard for twenty minutes while I waited for the patrols to change."] = "Hubo un par de situaciones en las que estuvo a punto. Tuve que esconderme en un armario durante veinte minutos mientras esperaba que las patrullas se cambiaran.",
    ["What I mean is, doesn't your Saradominist White Knight code require you to announce yourself? Challenge your opponents to a fair fight? Bang your sword on your shield or something?"] = "Lo que quiero decir es, ¿tu código Saradominist White Knight no requiere que te anuncien? ¿Desafiar a tus oponentes a una pelea justa? ¿Golpear tu espada en tu escudo o algo así?",
    ["White Knight code does. I'm a Temple Knight now."] = "El código White Knight sí. Ahora soy un Caballero del Templo.",
    ["You never fit in with the White Knights very well, did you, Owen?"] = "Nunca encajaste muy bien con los Caballeros Blancos, ¿verdad, Owen?",
    ["No. They were on the verge of dismissing me when the Temple Knights took me in. They said I was a cold blooded killer."] = "No. Estuvieron a punto de despedirme cuando los Caballeros del Templo me acogieron. Dijeron que era un asesino a sangre fría.",
    ["Would you say you are?"] = "¿Dirías que lo eres?",
    ["Hot blooded killers make mistakes."] = "Los asesinos de sangre caliente cometen errores.",
    ["How could you say that so calmly? You shot those Kinshra guards with a crossbow bolt to the back of their necks. It doesn't seem, I don't know, it doesn't seem sporting."] = "¿Cómo pudiste decir eso con tanta calma? Disparaste a esos guardias de Kinshra con una ballesta en la nuca. No parece, no sé, no parece deportivo.",
    ["It's not sporting because it's not a game."] = "No es deportivo porque no es un juego.",
    ["Those guards had to die for me to get to my objective. Raising the alarm and giving them a chance to fight back wouldn't have helped anyone."] = "Esos guardias tuvieron que morir para que yo pudiera alcanzar mi objetivo. Dar la alarma y darles la oportunidad de contraatacar no habría ayudado a nadie.",
    ["I placed the crossbow bolts in the middle of their brains. They died instantly, they probably didn't even feel pain."] = "Coloqué las flechas de la ballesta en el medio de sus cerebros. Murieron instantáneamente, probablemente ni siquiera sintieron dolor.",
    ["Don't you have a Saradominist code of honour?"] = "¿No tienes un código de honor saradominista?",
    ["Saradomin wants me to destroy evil and protect the innocent. I'll use whatever methods are best for the job, and make any sacrifices I have to."] = "Saradomin quiere que destruya el mal y proteja a los inocentes. Usaré los mejores métodos para el trabajo y haré los sacrificios que sean necesarios.",
    ["If that means I use tactics the White Knights think are unsporting, then so be it. Succeeding in the mission is more important than obeying arbitrary rules."] = "Si eso significa que uso tácticas que los Caballeros Blancos consideran antideportivas, que así sea. Tener éxito en la misión es más importante que obedecer reglas arbitrarias.",
    ["How can you sit there and be so...so sure of yourself?"] = "¿Cómo puedes sentarte ahí y estar tan... tan seguro de ti mismo?",
    ["I pray to Saradomin every day for guidance. I know that with him as my light I'm on the right path."] = "Rezo a Saradomin todos los días para que me oriente. Sé que con él como mi luz voy por el camino correcto.",
    ["You scare me sometimes, Owen."] = "A veces me asustas, Owen.",
    ["I can't remember whose idea it was originally: either mine or Radimus's."] = "No recuerdo de quién fue la idea originalmente: si mía o de Radimus.",
    ["Radimus Erkle? The Grand Vizier of the Legends' Guild?"] = "¿Radimus Erkle? ¿El Gran Visir del Legends' Guild?",
    ["Grand Vizier'. Hah! Yes, that's the title he invented for himself."] = "Gran Visir'. ¡Ja! Sí, ese es el título que él mismo inventó.",
    ["Inventing flashy titles for yourself doesn't seem to be in the spirit of heroism."] = "Inventar títulos llamativos no parece ser un espíritu de heroísmo.",
    ["It's appropriate for the head of the Legends' Guild to have an impressive title, Ariane. The purpose of the guilds is to recognise achievement, and titles reinforce that."] = "Es apropiado que el líder de Legends' Guild tenga un título impresionante, Ariane. El propósito de los gremios es reconocer los logros y los títulos lo refuerzan.",
    ["Well, that's one of the purposes of the guilds. I didn't just want to recognise achievement; I wanted to coordinate and nurture it."] = "Bueno, ese es uno de los propósitos de los gremios. No sólo quería reconocer los logros; Quería coordinarlo y nutrirlo.",
    ["This was twenty years ago. There was a community of adventurers, working alone or in groups."] = "Esto fue hace veinte años. Había una comunidad de aventureros que trabajaban solos o en grupos.",
    ["Radimus, Dissy and I adventured together for several years. We made the first partial Kharazi jungle map together, but then the Jogre War flared up and we couldn't finish it."] = "Radimus, Dissy y yo nos aventuramos juntos durante varios años. Hicimos juntos el primer mapa parcial de la jungla de Kharazi, pero luego el Jogre War estalló y no pudimos terminarlo.",
    ["For a while after that, I ran with Harrallak and his lot. We fought against Ajjat until he switched sides and joined us. I was part of their voyage to Shanomi's homeland."] = "Durante un tiempo después de eso, corrí con Harrallak y su grupo. Luchamos contra Ajjat hasta que cambió de bando y se unió a nosotros. Fui parte de su viaje a la tierra natal de Shanomi.",
    ["Shanomi's from the Eastern Lands. You've been there?"] = "Shanomi de las Tierras del Este. ¿Has estado allí?",
    ["Yes. Maybe someday I'll tell you about it. There are parts of it I'm still sworn to secrecy about, though."] = "Sí. Quizás algún día te lo cuente. Sin embargo, hay partes sobre las que todavía juro guardar el secreto.",
    ["Anyway, there were dozens of adventurers, but we could never coordinate our efforts. If there was a big threat, it was a case of whoever got to it first."] = "De todos modos, había docenas de aventureros, pero nunca pudimos coordinar nuestros esfuerzos. Si había una gran amenaza, dependía de quien llegara primero.",
    ["We always managed, but I started to worry what would happen if there was a serious, global threat, and we couldn't mobilise in time. Luckily there was nothing we couldn't handle, but I always wondered..."] = "Siempre lo logramos, pero comencé a preocuparme por lo que sucedería si hubiera una amenaza global grave y no pudiéramos movilizarnos a tiempo. Por suerte no había nada que no pudiéramos manejar, pero siempre me pregunté...",
    ["Eventually, the number of active adventurers dwindled. Some vanished, like Achiettes' parents. Some died. Some started getting too old, or just decided they'd had enough of the life."] = "Con el tiempo, el número de aventureros activos disminuyó. Algunos desaparecieron, como los padres de Achiettes. Algunos murieron. Algunos empezaron a envejecer demasiado o simplemente decidieron que ya habían tenido suficiente de la vida.",
    ["The old guard was starting to retire, but there weren't many new adventurers taking our place. The ones that were appearing weren't being properly guided. The Guilds were meant to provide that guidance."] = "La vieja guardia estaba empezando a retirarse, pero no había muchos nuevos aventureros ocupando nuestro lugar. Los que aparecían no estaban siendo guiados adecuadamente. Los gremios estaban destinados a proporcionar esa orientación.",
    ["Do you think they worked?"] = "¿Crees que funcionaron?",
    ["Well...there are more heroes than ever, and a lot of them are Guild members, but how much we've really helped them, I can't say. I always wonder, if I'd done things differently..."] = "Bueno... hay más héroes que nunca, y muchos de ellos son miembros del Gremio, pero no puedo decir cuánto los hemos ayudado realmente. Siempre me pregunto si hubiera hecho las cosas de otra manera...",
    ["No one could have done more, Xenia."] = "Nadie podría haber hecho más, Xenia.",
    ["Perhaps. I just hope that if there's a big threat - a real threat to the world - there will be enough heroes to tackle it."] = "Quizás. Sólo espero que si hay una gran amenaza -una amenaza real para el mundo- haya suficientes héroes para enfrentarla.",
    ["That old man has his telescope pointed at the Tower. I'm sure he's up to something."] = "Ese old man tiene su telescopio apuntando a la Torre. Estoy seguro de que está tramando algo.",
    ["It's under control. The Temple Knights have him under surveillance. We've got a file on him."] = "Está bajo control. Los Caballeros del Templo lo tienen bajo vigilancia. Tenemos un expediente sobre él.",
    ["And...?"] = "¿Y...?",
    ["And it's classified, Ariane. You know that."] = "Y está clasificado, Ariane. Ya lo sabes.",
    ["Ozan, you must have heard stories about him."] = "Ozan, debes haber escuchado historias sobre él.",
    ["Hundreds. They can't possibly be true, though. I know exaggeration when I see it."] = "Cientos. Sin embargo, no es posible que sean ciertas. Reconozco la exageración cuando la veo.",
    ["Oh, more of them are true than you imagine."] = "Oh, hay más verdades de las que imaginas.",
    ["You know him?"] = "¿Lo conoces?",
    ["We used to be in an adventuring party together. He was Gielinor's greatest hero; I was a fresh newcomer. He showed me the world. Oh yes, a lot of the stories are true."] = "Solíamos estar juntos en un grupo de aventuras. Era el mayor héroe de Gielinor; Yo era un recién llegado. Me mostró el mundo. Oh, sí, muchas de las historias son ciertas.",
    ["When Radimus founded the guilds, we begged him to join us, but he wasn't interested. He's got so much he could pass on, but he's become cynical, he's only interested in personal rewards."] = "Cuando Radimus fundó los gremios, le rogamos que se uniera a nosotros, pero no estaba interesado. Tiene mucho que transmitir, pero se ha vuelto cínico y sólo le interesan las recompensas personales.",
    ["He seems to have settled. We're not expecting him to move from Draynor in the near future."] = "Parece haberse asentado. No esperamos que se mude de Draynor en un futuro próximo.",
    ["I still don't trust him."] = "Todavía no confío en él.",
    ["I'm telling you, it was the will of Saradomin. If the roof hadn't collapsed at that moment, I wouldn't be here."] = "Te lo digo, fue voluntad de Saradomin. Si el techo no se hubiera derrumbado en ese momento, yo no estaría aquí.",
    ["The roof collapsed because you'd been fighting. You said you blinded the troll and it blundered into the walls. A lot of these caves are structurally weak."] = "El techo se derrumbó porque habíais estado peleando. Dijiste que cegaste al troll y se estrelló contra las paredes. Muchas de estas cuevas son estructuralmente débiles.",
    ["But for the rocks to fall just then, right on the troll's head? I tell you, there was an icyene watching over me that day."] = "¿Pero que las rocas caigan en ese momento, justo sobre la cabeza del troll? Les cuento que había un hielo velando por mí ese día.",
    ["An icyene? Did you see her? Was she hot?"] = "¿Un helado? ¿La viste? ¿Estaba buena?",
    ["Not all icyene are female, Ozan."] = "No todos los icyene son mujeres, Ozan.",
    ["Was he hot?"] = "¿Estaba sexy?",
    ["I didn't see anyone. But I could feel a presence, watching over me, making sure I survived so that I could serve Saradomin again."] = "No vi a nadie. Pero podía sentir una presencia que me vigilaba, asegurándose de que sobreviviera para poder servir a Saradomin nuevamente.",
    ["You're imagining it, Owen."] = "Te lo estás imaginando, Owen.",
    ["Never mind that. When I tell this story, the icyene is going to make a proper appearance."] = "Eso no importa. Cuando cuente esta historia, el hielo hará su aparición adecuada.",
    ["A winged warrior-woman, shining with light...she brings the rock down on the back of the troll's head, then holds out her hand to help you up..."] = "Una mujer guerrera alada, que brilla con luz... golpea la piedra en la parte posterior de la cabeza del troll y luego extiende su mano para ayudarte a levantarte...",
    ["Her skin is like living marble; her hair shines like liquid gold. She lifts you up, spreads her wings around you..."] = "Su piel es como mármol vivo; su cabello brilla como oro líquido. Ella te levanta, extiende sus alas a tu alrededor...",
    ["Ozan! Enough of that."] = "¡Ozan! Ya basta de eso.",
    ["Come on, Owen. I know you can do it. You came up with a brilliant one the other day."] = "Vamos, Owen. Sé que puedes hacerlo. El otro día se te ocurrió uno brillante.",
    ["Well, maybe, but I don't see why you feel the need to do it every time."] = "Bueno, tal vez, pero no veo por qué sientes la necesidad de hacerlo cada vez.",
    ["It's charismatic! It gives you presence! Your enemies will feel like you're the hero, not them, and they'll be off balance."] = "¡Es carismático! ¡Te da presencia! Tus enemigos sentirán que eres el héroe, no ellos, y perderán el equilibrio.",
    ["Plus, it'll impress any bystanders who might be watching."] = "Además, impresionará a cualquier espectador que pueda estar mirando.",
    ["Ha ha. That's what it's all about for you, isn't it, Ozan?"] = "Ja, ja. De eso se trata para ti, ¿no, Ozan?",
    ["What was it you said the other day, Owen?"] = "¿Qué dijiste el otro día, Owen?",
    ["It was when we broke in on that band of thugs in Varrock sewer. Owen kicked the grating in, and they all looked up at us with their 'bwuh?' expressions, and Owen said..."] = "Fue cuando irrumpimos en esa banda de matones en las alcantarillas de Varrock. Owen pateó la reja y todos nos miraron con su '¿bwuh?' expresiones, y Owen dijo...",
    ["*sigh* I said..."] = "*suspiro* I dijo...",
    ["I'm here to kick a** and take names...and I'm a Temple Knight, so I already know your names."] = "Estoy aquí para patear traseros** y tomar nombres... y soy un Caballero del Templo, así que ya sé sus nombres.",
    ["Hmm. Maybe a bit wordy."] = "Mmm. Quizás un poco prolijo.",
    ["Well, we all know there's no impressing you! I thought it worked rather well."] = "Bueno, ¡todos sabemos que no hay forma de impresionarte! Pensé que funcionó bastante bien.",
    ["Okay, you got into the tomb. How big was it?"] = "Está bien, entraste en la tumba. ¿Qué tan grande era?",
    ["Hey, it's our newest guild member!"] = "¡Oye, es nuestro miembro más nuevo del gremio!",
    ["Several times, at length."] = "Varias veces, extensamente.",
    ["Welcome to the guild, Player."] = "Bienvenido al gremio, Player.",
    ["It was nothing."] = "No fue nada.",
    ["I don't think you understand what being an adventurer is all about."] = "No creo que entiendas de qué se trata ser un aventurero.",
    ["Perhaps Player could teach you a little humility, Ozan."] = "Quizás Player pueda enseñarte un poco de humildad, Ozan.",
    ["It's about the legend! The glory! Bards will sing of our exploits for generations - but only if we teach them the songs!"] = "¡Se trata de la leyenda! ¡La gloria! Los bardos cantarán nuestras hazañas durante generaciones, ¡pero sólo si les enseñamos las canciones!",
    ["It's not about personal glory, Ozan. It's about fulfilling the will of Saradomin, and putting down evil wherever we find it."] = "No se trata de gloria personal, Ozan. Se trata de cumplir la voluntad de Saradomin y acabar con el mal dondequiera que lo encontremos.",
    ["What about you, Ariane?"] = "¿Y tú, Ariane?",
    ["It's about making the world a better place."] = "Se trata de hacer del mundo un lugar mejor.",
    ["What about you, Xenia?"] = "¿Y tú, Xenia?",
    ["Oh, for me it's been about a few different things over the years."] = "Oh, para mí se han tratado de algunas cosas diferentes a lo largo de los años.",
    ["Sometimes, it's been about righting wrongs, sometimes it's been about the glory. Sometimes it's just been about the experience. I never was one for a boring life."] = "A veces se trata de corregir errores, a veces se trata de la gloria. A veces se trata simplemente de la experiencia. Nunca fui alguien para una vida aburrida.",
    ["You should find your own path, Player. Don't listen to us. Being in the [Champions'/Heroes'/Legends'] Guild is worthwhile, whatever led you here."] = "Deberías encontrar tu propio camino, Player. No nos escuches. Estar en el Gremio [Champions'/Heroes'/Legends'] vale la pena, sea lo que sea que te haya traído hasta aquí.",
    ["It was one of many epic adventures!"] = "¡Fue una de muchas aventuras épicas!",
    ["I know! I've heard the stories about you. I've passed some of them on myself!"] = "¡Lo sé! He oído historias sobre ti. ¡Me he pasado algunos de ellos!",
    ["Changing them to stories about you."] = "Cambiándolas a historias sobre ti.",
    ["Or inserting yourself as the one who saves the day."] = "O insertarte como quien salva el día.",
    ["Don't listen to them, Player! All my stories are the unembellished facts."] = "¡No les hagas caso, Player! Todas mis historias son hechos sin adornos.",
    ["Don't listen to her, Player! All my stories are the unembellished facts."] = "¡No la escuches, Player! Todas mis historias son hechos sin adornos.",
    ["That's the tallest tale I've heard for a while."] = "Ese es el cuento más fantástico que he escuchado en mucho tiempo.",
    ["Who are you people?"] = "¿Quiénes son ustedes?",
    ["I'm sorry, I thought you knew each other."] = "Lo siento, pensé que se conocían.",
    ["Player, these are some other members of the Guild. Sir Owen - Ariane - Ozan."] = "Player, estos son algunos otros miembros del Gremio. Sir Owen - Ariane - Ozan.",
    ["No need to introduce yourself, Player. Xenia has told us all about you."] = "No es necesario que te presentes, Player. Xenia nos ha contado todo sobre ti.",
    ["You're a worthy addition to the guild."] = "Eres una valiosa incorporación al gremio.",
    ["Player, these are some other members of the Guild. Ariane - Ozan."] = "Player, estos son algunos otros miembros del Gremio. Ariane - Ozan.",
    ["We have not seen Sir Owen here for some time..."] = "Hace tiempo que no vemos a Sir Owen por aquí...",
    ["Player, sadly there's just the two of us at the moment. This is Ozan."] = "Player, lamentablemente solo estamos nosotros dos en este momento. Este es Ozan.",
    ["No need to introduce yourself, Player. Ariane has told me all about you."] = "No es necesario que te presentes, Player. Ariane me ha contado todo sobre ti.",
    ["It was you?"] = "¿Fuiste tú?",
    ["Ha ha ha!"] = "¡Ja, ja, ja!",
    ["It's not funny, Ozan!"] = "¡No es gracioso, Ozan!",
    ["It is, though! The look on your face..."] = "¡Pero lo es! La mirada en tu cara...",
    ["I risked life and limb to retrieve those artefacts for the museum. Then I find out that you had stolen them from the museum again!"] = "Arriesgué mi vida para recuperar esos artefactos para el museo. ¡Entonces descubrí que los habías robado otra vez del museo!",
    ["The artefacts were in storage. They'd finished studying them."] = "Los artefactos estaban almacenados. Habían terminado de estudiarlos.",
    ["You never finish studying something."] = "Nunca terminas de estudiar algo.",
    ["I'm sure the theft was justified. Wasn't it, Ozan? We've often had to steal museum artefacts for a mission."] = "Estoy seguro de que el robo estuvo justificado. ¿No fue así, Ozan? A menudo hemos tenido que robar objetos de museo para una misión.",
    ["We've often had to steal museum artefacts for a mission."] = "A menudo hemos tenido que robar objetos de museo para una misión.",
    ["Yes, when we needed something and the museum wouldn't give it up, and then we returned them afterwards. Ozan stole these for private collectors."] = "Sí, cuando necesitábamos algo y el museo no nos lo daba, y luego lo devolvíamos. Ozan los robó para coleccionistas privados.",
    ["I thought you were leaving your life of crime behind you, Ozan."] = "Pensé que estabas dejando atrás tu vida criminal, Ozan.",
    ["Aw, it was just from a museum. It wasn't like I took food from poor families..."] = "Ah, era sólo de un museo. No era como si tomara comida de familias pobres...",
    ["You want me to steal them back for the museum? I could do that."] = "¿Quieres que los robe para el museo? Yo podría hacer eso.",
    ["No! No more stealing."] = "¡No! No más robos.",
    ["That old man nearly took down the Tower. Traiborn had to break out one of his thingummywuts."] = "Ese old man casi derriba la Torre. Traiborn tuvo que sacar una de sus cositas.",
    ["It was about fifty metres long, ten wide, and five high."] = "Tenía unos cincuenta metros de largo, diez de ancho y cinco de alto.",
    ["No, no! I don't want to know its measurements. You've got to say how big it was!"] = "¡No, no! No quiero saber sus medidas. ¡Tienes que decir lo grande que era!",
    ["I just said..."] = "Acabo de decir...",
    ["You need to give a sense of how big it was. Your flickering torchlight could not penetrate the dust to the far wall. The sound of your footfalls was lost in the immensity as the weight of ages pressed down on you..."] = "Tienes que dar una idea de lo grande que era. La luz parpadeante de tu antorcha no pudo atravesar el polvo hasta la pared del fondo. El sonido de tus pasos se perdió en la inmensidad mientras el peso de las edades te presionaba...",
    ["Um, alright. It was...very big?"] = "Mmm, está bien. Era... ¿muy grande?",
    ["That's a start. What did you find in the tomb?"] = "Eso es un comienzo. ¿Qué encontraste en la tumba?",
    ["There were fourteen skeletons in various states of-"] = "Había catorce esqueletos en varios estados de-",
    ["Ah! So you battled with the skeletons! Unsleeping guardians, enraged at your intrusion into-"] = "¡Ah! ¡Así que luchaste con los esqueletos! Guardianes insomnes, enfurecidos por vuestra intrusión en...",
    ["No, ordinary skeletons. The old king's servants had been buried in the outer chamber to provide for him in the next life."] = "No, esqueletos ordinarios. Los sirvientes del viejo rey habían sido enterrados en la cámara exterior para sustentarlo en la próxima vida.",
    ["The old king's guards had been buried there to protect him, and you fought them with magic fireballs! No one wants to hear a story about burial customs."] = "Los guardias del viejo rey habían sido enterrados allí para protegerlo, ¡y tú luchaste contra ellos con bolas de fuego mágicas! Nadie quiere oír una historia sobre costumbres funerarias.",
    ["Well, okay. When I had...got past...the skeletons, there was a locked door. I had to figure out its mechanism."] = "Bueno, está bien. Cuando... pasé... los esqueletos, había una puerta cerrada con llave. Tuve que descubrir su mecanismo.",
    ["While the walls were closing in? With spikes?"] = "¿Mientras los muros se cerraban? ¿Con púas?",
    ["No, there was no pressure. Actually, I left the tomb at that point to read up on that type of mechanism, back at the Tower."] = "No, no hubo presión. En realidad, salí de la tumba en ese momento para leer sobre ese tipo de mecanismo, allá en la Torre.",
    ["You can't make an exciting story about reading books! No, the walls were closing in, and you got the door open just in time. And, on the other side, you saw..."] = "¡No se puede crear una historia emocionante leyendo libros! No, las paredes se estaban cerrando y abriste la puerta justo a tiempo. Y, del otro lado, viste...",
    ["There was a marble sarcophagus about three metres-"] = "Había un sarcófago de mármol de unos tres metros-",
    ["*Ahem*"] = "*Ejem*",
    ["A...huge...marble sarcophagus...studded with jewels, and carved into a...terrifying visage."] = "Un... enorme... sarcófago de mármol... tachonado de joyas y tallado en un... rostro aterrador.",
    ["That's better. And then?"] = "Eso está mejor. ¿Y luego?",
    ["Inside the sarcophagus...inside the sarcophagus, I found the king's burial mask, solid gold and carved all over with hieroglyphics."] = "Dentro del sarcófago... dentro del sarcófago, encontré la máscara funeraria del rey, de oro macizo y tallada con jeroglíficos por todas partes.",
    ["An ancient artefact of mystical power!"] = "¡Un antiguo artefacto de poder místico!",
    ["It wasn't..."] = "No fue...",
    ["An ancient artefact...whose powers we have yet to unlock."] = "Un artefacto antiguo... cuyos poderes aún tenemos que desbloquear.",
    ["There! You're getting the idea. Now change the main character to me, and you've got the perfect story!"] = "¡Ahí! Estás entendiendo la idea. ¡Ahora cambia el personaje principal por mí y tendrás la historia perfecta!",
    ["! Hello!"] = "! ¡Hola!",
    ["I'm Sigurd the Great and Brainy."] = "Soy Sigurd el Grande e Inteligente.",
    ["Why do they call you the Great and Brainy?"] = "¿Por qué te llaman el Grande y el Inteligente?",
    ["Because I invented the Log Canoe!"] = "¡Porque inventé la canoa de troncos!",
    ["Log Canoe?"] = "¿Canoa de troncos?",
    ["Yeash! Me and my cousins were having a great party by the river when we decided to have a game of 'Smack The Tree'."] = "¡Sí! Mis primos y yo estábamos teniendo una gran fiesta junto al río cuando decidimos jugar un juego de 'Smack The Tree'.",
    ["Smack the Tree?"] = "¿Golpear el árbol?",
    ["It's a game where you take it in turnsh shmacking a tree. First one to uproot the tree winsh! Anyway, I won the game with a flying tackle. The tree came loose and down the river bank I went, still holding the tree. I woke up a few hours later and found myself several miles down river. And thatsh how I invented the log canoe!"] = "Es un juego en el que, por turnos, golpeas un árbol. ¡El primero en arrancar el árbol de raíz! De todos modos, gané el juego con una entrada voladora. El árbol se soltó y bajé por la orilla del río, todavía sosteniendo el árbol. Me desperté unas horas más tarde y me encontré a varios kilómetros río abajo. ¡Y así fue como inventé la canoa de troncos!",
    ["So you invented the 'Log Canoe' by falling into a river hugging a tree?"] = "¿Entonces inventaste la 'Canoa de troncos' al caer a un río abrazado a un árbol?",
    ["Well I refined the design from the original you know! I cut all the branches off to make it more comfortable. I could tell you how to if you like?"] = "Bueno, refiné el diseño del original, ¿sabes? Corté todas las ramas para que fuera más cómodo. ¿Podría decirte cómo hacerlo si quieres?",
    ["**Sigurd:** It's really quite simple. Just walk down to that tree on the bank and chop it down. Then take your hatchet to it and shape it how you like!"] = "**Sigurd:** Es realmente bastante simple. Simplemente camina hacia ese árbol en la orilla y córtalo. ¡Entonces llévale tu hacha y dale la forma que quieras!",
    ["*If the player has a woodcutting level higher than 57:*"] = "*Si el player tiene un nivel de corte de madera superior a 57:*",
    ["You look like you know your way around a tree, you can make a Waka canoe."] = "Parece que sabes cómo moverte alrededor de un árbol, puedes hacer una canoa Waka.",
    ["What's a Waka?"] = "¿Qué es un Waka?",
    ["I've only ever seen Hari using them. People say he's found a way to canoe the river underground and into the Wilderness Hari hangs around up near Edgeville He's a nice bloke."] = "Sólo he visto a Hari usarlos. La gente dice que ha encontrado una manera de navegar en canoa por el río subterráneo y llegar al Wilderness. Hari anda cerca de Edgeville. Es un buen tipo.",
    ["*If the player has a woodcutting level between 42 and 57:*"] = "*Si el player tiene un nivel de corte en madera entre 42 y 57:*",
    ["Well, you're pretty handy with an axe! You could make Stable Dugout canoes, like that snooty fella Tarquin. He reckons his canoes are better than mine. He's never said it to my face though."] = "Bueno, ¡eres bastante hábil con el hacha! Podrías hacer canoas Stable Dugout, como ese tipo presumido Tarquin. Considera que sus canoas son mejores que las mías. Aunque nunca me lo dijo en la cara.",
    ["*If the player has a woodcutting level between 27 and 42:*"] = "*Si el player tiene un nivel de corte en madera entre 27 y 42:*",
    ["You could make a Dugout canoe with your woodcutting skill, but I don't see why you would want to."] = "Podrías hacer una canoa con tu habilidad para cortar madera, pero no veo por qué querrías hacerlo.",
    ["*If the player has a woodcutting level between 12 and 27:*"] = "*Si el player tiene un nivel de corte en madera entre 12 y 27:*",
    ["You can make a log canoe like mine! It'll get you 1 stop down the river. There's some snooty fella down near the Champions Guild who reckons his canoes are better than mine. He's never said it to my face though."] = "¡Puedes hacer una canoa de troncos como la mía! Te llevará 1 parada río abajo. Hay un tipo presumido cerca del Gremio de Campeones que cree que sus canoas son mejores que las mías. Aunque nunca me lo dijo en la cara.",
    ["*If the player has a woodcutting level lower than 12:*"] = "*Si el player tiene un nivel de corte de madera inferior a 12:*",
    ["Well, you don't look like you have the skill to make a canoe. You need to have at least level 12 woodcutting. Once you are able to make a canoe it makes travel along the river much quicker!"] = "Bueno, no parece que tengas la habilidad para hacer una canoa. Necesitas tener al menos nivel 12 de tala de madera. Una vez que puedas hacer una canoa, viajar a lo largo del río será mucho más rápido.",
    ["Can you teach me about canoeing?"] = "¿Puedes enseñarme sobre piragüismo?",
    ["Hello there."] = "Hola.",
    ["Can't you see that I'm busy here?"] = "¿No ves que estoy ocupado aquí?",
    ["Oh. Sorry, you don't look very busy."] = "Oh. Lo siento, no pareces muy ocupado.",
    ["Don't look busy? I've got a lot of important work to do here."] = "¿No pareces ocupado? Tengo mucho trabajo importante que hacer aquí.",
    ["Really? What do you do?"] = "¿En serio? ¿A qué te dedicas?",
    ["That doesn't concern you. What are you doing here anyway?"] = "Eso no te concierne. ¿Qué estás haciendo aquí de todos modos?",
    ["Oh, it's you again. What are you doing here?"] = "Oh, eres tú otra vez. ¿Qué estás haciendo aquí?",
    ["I'm not actually sure."] = "En realidad no estoy seguro.",
    ["Hmph! Well I can tell you what you ARE doing."] = "¡Hmph! Bueno, puedo decirte lo que ESTÁS haciendo.",
    ["Wasting my time! Now go away! If you must speak to someone, speak to one of the other monks around here!"] = "¡Perdiendo mi tiempo! ¡Ahora vete! ¡Si debes hablar con alguien, habla con uno de los otros monjes que hay por aquí!",
    ["I'm on an important quest!"] = "¡Estoy en una misión importante!",
    ["Really..."] = "De verdad...",
    ["Yes! Do you want to know what my quest is?"] = "¡Sí! ¿Quieres saber cuál es mi búsqueda?",
    ["Let me see...you helped out a trader who in turn asked you to deliver something for him, and then you had to journey to some palace to see someone and they said thanks by sending you somewhere else."] = "Déjame ver... ayudaste a un comerciante que a su vez te pidió que le entregaras algo, y luego tuviste que viajar a algún palacio para ver a alguien y te dijeron gracias enviándote a otro lugar.",
    ["So, now you've ended up down here, bothering me?"] = "Entonces, ¿ahora terminaste aquí abajo, molestándome?",
    ["Uh, yes, that's about right."] = "Uh, sí, eso es cierto.",
    ["Lucky me..."] = "Qué suerte tengo...",
    ["Sorry about that. I'll leave you alone, then."] = "Lo siento. Entonces te dejaré en paz.",
    ["None of your business!"] = "¡No es asunto tuyo!",
    ["Of course it isn't, but you were the one who came here bothering me! So, unless you want something, be off with you!"] = "¡Por supuesto que no lo es, pero tú fuiste quien vino aquí molestándome! Entonces, a menos que quieras algo, ¡vete!",
    ["I am looking for something."] = "Estoy buscando algo.",
    ["And what are you looking for exactly?"] = "¿Y qué buscas exactamente?",
    ["The Chaos Altar, I think."] = "El Altar del Caos, creo.",
    ["Hmph! Well, it's just a bit further down. Now, if you don't mind, I'm very busy here!"] = "¡Hmph! Bueno, está un poco más abajo. Ahora, si no te importa, ¡estoy muy ocupado aquí!",
    ["I'm the leader of the Dagon'hai. Bow before me!"] = "Soy el líder de los Dagon'hai. ¡Inclínate ante mí!",
    ["You? Leader of the Dagon'hai? Hah! I've never heard of such rubbish! You call yourself a mage?"] = "¿Tú? ¿Líder de los Dagon'hai? ¡Ja! ¡Nunca había oído hablar de tanta basura! ¿Te llamas mago?",
    ["I'm a very powerful mage!"] = "¡Soy un mago muy poderoso!",
    ["Yes! Be afraid! Be very afraid! Ha ha ha!"] = "¡Sí! ¡Tener miedo! ¡Ten mucho miedo! ¡Ja, ja, ja!",
    ["I see. Well then, let's see how you handle this!"] = "Ya veo. Bueno, ¡veamos cómo manejas esto!",
    ["What...?!?!"] = "¡¿Qué...?!?!",
    ["*(If the player is level 80 Magic or higher:)*"] = "*(Si el player es nivel 80 Magic o superior:)*",
    ["So! You are a good mage! You deflected my spell."] = "¡Entonces! ¡Eres un buen mago! Desviaste mi hechizo.",
    ["Hah! Yes. I told you so! Now, I have work to be done."] = "¡Ja! Sí. ¡Te lo dije! Ahora tengo trabajo que hacer.",
    ["Of course. Goodbye!"] = "Por supuesto. ¡Adiós!",
    ["*(If the player is below level 80 Magic:)*"] = "*(Si el player está por debajo del nivel 80 Magic:)*",
    ["Hah! I knew you were no mage! Let that be a lesson to you! Now, please leave."] = "¡Ja! ¡Sabía que no eras un mago! ¡Que esto te sirva de lección! Ahora, por favor vete.",
    ["No, you're right. I'm not a mage."] = "No, tienes razón. No soy un mago.",
    ["I didn't think so! Now go away. As I said, I'm very busy!"] = "¡No lo creo! Ahora vete. Como dije, ¡estoy muy ocupada!",
    ["I buy silk. If you ever want to sell any silk, bring it here."] = "Compro seda. Si alguna vez quieres vender seda, tráela aquí.",
    ["Hello. I have some fine silk from Al Kharid to sell to you."] = "Hola. Tengo seda fina de Al Kharid para venderte.",
    ["Ah, I may be interested in that. What sort of price were you looking at per piece of silk?"] = "Ah, puede que me interese. ¿Qué tipo de precio estabas mirando por pieza de seda?",
    ["Okay, suits me."] = "Está bien, me parece bien.",
    ["80 coins? That's a bit steep! How about 40 coins?"] = "80 coins? ¡Eso es un poco caro! ¿Qué tal 40 coins?",
    ["Okay, 40 sounds good."] = "Vale, 40 suena bien.",
    ["50, and that's my final price."] = "50, y ese es mi precio final.",
    ["Done."] = "Listo.",
    ["No, that is not enough."] = "No, eso no es suficiente.",
    ["You'll never get that much for it. I'll be generous and give you 50 for it."] = "Nunca obtendrás tanto por ello. Seré generoso y te daré 50 por ello.",
    ["Okay, I guess 50 will do."] = "Está bien, supongo que 50 serán suficientes.",
    ["I'll give it to you for 60."] = "Te lo regalo por 60.",
    ["You drive a hard bargain but I guess that will have to do."] = "Eres un buen negociador, pero supongo que eso será suficiente.",
    ["Don't be ridiculous! That is far too much. You insult me with that price."] = "¡No seas ridículo! Eso es demasiado. Me insultas con ese precio.",
    ["Do you want to buy any fine silks?"] = "¿Quieres comprar sedas finas?",
    ["How much are they?"] = "¿Cuánto cuestan?",
    ["3gp."] = "3mo.",
    ["No, that's too much for me."] = "No, eso es demasiado para mí.",
    ["2gp and that's as low as I'll go. I'm not selling it for any less. You'll only go and sell it in Varrock for a profit."] = "2gp y eso es lo más bajo que puedo llegar. No lo vendo por menos. Sólo irás a venderlo en Varrock para obtener ganancias.",
    ["2gp sounds good."] = "2gp suena bien.",
    ["You buy some silk for 2gp."] = "Compras algo de seda por 2 po.",
    ["Oh dear. I don't have enough money."] = "Dios mío. No tengo suficiente dinero.",
    ["Well, come back when you do have some money."] = "Bueno, vuelve cuando tengas algo de dinero.",
    ["No, really, I don't want it."] = "No, de verdad, no lo quiero.",
    ["Okay, but that's the best price you're going to get."] = "Está bien, pero ese es el mejor precio que obtendrás.",
    ["Okay, that sounds good."] = "Vale, eso suena bien.",
    ["You buy some silk for 3gp."] = "Compras algo de seda por 3 po.",
    ["No, silk doesn't suit me."] = "No, la seda no me sienta bien.",
    ["My secretary is sitting just over there, thank you."] = "Mi secretaria está sentada justo ahí, gracias.",
    ["Today is not a good day, can you come back tomorrow?"] = "Hoy no es un buen día, ¿puedes volver mañana?",
    ["I'm busy, please leave."] = "Estoy ocupado, por favor vete.",
    ["If you're looking for the market, it's downstairs."] = "Si buscas el mercado, está abajo.",
    ["I can't help you, go and see my secretary."] = "No puedo ayudarte, ve a ver a mi secretaria.",
    ["Talk to my secretary. I don't have time to deal with you."] = "Habla con mi secretaria. No tengo tiempo para tratar contigo.",
    ["My secretary will deal with any inquiries you have about the Silver Cog."] = "Mi secretaria se ocupará de cualquier consulta que tengas sobre Silver Cog.",
    ["Do you mind? You're blocking my view."] = "¿Te importa? Estás bloqueando mi vista.",
    ["I said go!"] = "¡Dije que te fueras!",
    ["I told you to leave, human!"] = "¡Te dije que te fueras, humano!",
    ["You are an exceptional member of the Silver Cog."] = "Eres un miembro excepcional de Silver Cog.",
    ["Come in, Player, my secretary has been saying good things about you."] = "Pasa, Player, mi secretaria ha estado diciendo cosas buenas de ti.",
    ["Have you come to serve the Silver Cog again, Player?"] = "¿Has venido a servir al Silver Cog otra vez, Player?",
    ["You are proving yourself a loyal member of the Silver Cog, Player!"] = "¡Estás demostrando que eres un miembro leal de Silver Cog, Player!",
    ["Player! I've been hearing great things about you!"] = "¡Player! ¡He estado escuchando cosas maravillosas sobre ti!",
    ["Come, Player, let us converse a while on your future with us."] = "Ven, Player, déjanos conversar un rato sobre tu futuro con nosotros.",
    ["What have you come to ask of us, honourable Player?"] = "¿Qué ha venido a pedirnos, honorable Player?",
    ["It's an honour to meet you!"] = "¡Es un honor conocerte!",
    ["Fine, fine, now what did you want to talk about?"] = "Bien, bien, ¿ahora de qué querías hablar?",
    ["And what was it that you wanted of me, Player?"] = "¿Y qué era lo que querías de mí, Player?",
    ["It certainly must be."] = "Ciertamente debe serlo.",
    ["Yes, well, don't overdo it now, will you?"] = "Sí, bueno, no te excedas ahora, ¿quieres?",
    ["You are one of our best people, Player, naturally I have time for you."] = "Eres una de nuestras mejores personas, Player, naturalmente tengo tiempo para ti.",
    ["I can imagine!"] = "¡Me lo imagino!",
    ["It's not everyday that you run into someone as important as me, I'm sure."] = "No todos los días te encuentras con alguien tan importante como yo, estoy seguro.",
    ["Do you have any more tasks for me?"] = "¿Tienes más tareas para mí?",
    ["**Player:** Do you have any more tasks for me?"] = "**Player:** ¿Tienes más tareas para mí?",
    ["Verily, I believe I do."] = "En verdad, creo que sí.",
    ["Why, certainly."] = "Pues, claro.",
    ["I do believe so, yes."] = "Eso creo, sí.",
    ["A moment please, let me check."] = "Un momento, por favor, déjame comprobarlo.",
    ["Yes, I have something appropriate for you here."] = "Sí, tengo algo apropiado para ti aquí.",
    ["**Silver Cog Director:** We need [number] bars of [metal] in the next [number] minutes."] = "**Silver Cog Director:** Necesitamos barras [número] de [metal] en los próximos minutos [número].",
    ["I'll take it."] = "Lo aceptaré.",
    ["Excellent, get to it now!"] = "Excelente, ¡hazlo ahora!",
    ["Happy to hear that!"] = "¡Feliz de escuchar eso!",
    ["Admirable attitude, Player!"] = "¡Actitud admirable, Player!",
    ["The Silver Cog appreciates what you're doing, Player."] = "Silver Cog aprecia lo que estás haciendo, Player.",
    ["Then hurry back, Player, I'm counting on you!"] = "Entonces vuelve rápido, Player, ¡cuento contigo!",
    ["I'm sorry to hear that, Player, the company really needed those bars."] = "Lamento escuchar eso, Player, la compañía realmente necesitaba esas barras.",
    ["I don't understand, I thought you were a loyal follower?"] = "No entiendo, ¿pensé que eras un seguidor leal?",
    ["Then why did you ask, Player?"] = "Entonces, ¿por qué preguntaste, Player?",
    ["That is an unusual thing to say for you, Player."] = "Eso es algo inusual para ti, Player.",
    ["Oh? I thought you liked doing this kind of work?"] = "¿Ah? Pensé que te gustaba hacer este tipo de trabajo.",
    ["Have you completed your current task yet? Did you get me my [number] bars of [metal]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis barras [número] de [metal]?",
    ["I'm still working on it, sorry."] = "Todavía estoy trabajando en ello, lo siento.",
    ["Hurry then, I don't have time for all this."] = "Entonces date prisa, no tengo tiempo para todo esto.",
    ["Since you're so fond of the [chosen company during The Giant Dwarf], why don't you ask them?"] = "Ya que te gustan tanto los [chosen company during The Giant Dwarf], ¿por qué no les preguntas?",
    ["You are in league with the [chosen company], aren't you? Your question is inappropriate."] = "Estás aliado con [chosen company], ¿no? Tu pregunta es inapropiada.",
    ["Ask the [chosen company] for a job instead!"] = "¡Pide trabajo al [chosen company]!",
    ["Aren't you an associate of [chosen company]? Why do you ask me?"] = "¿No eres asociado de [chosen company]? ¿Por qué me preguntas?",
    ["I believe that you have business with [other Company] to finish first."] = "Creo que tienes asuntos pendientes con [other Company] para terminar primero.",
    ["*(Only after The Giant Dwarf:)* The trade floor guards keep attacking me!"] = "*(Sólo después de The Giant Dwarf:)* ¡Los guardias del piso de comercio siguen atacándome!",
    ["The trade floor guards keep attacking me."] = "Los guardias del piso comercial siguen atacándome.",
    ["No doubt they thought you were stealing from the traders. You should speak to your own company director."] = "Sin duda pensaron que les estabas robando a los comerciantes. Debería hablar con el director de su propia empresa.",
    ["Thank you for your time."] = "Gracias por tu tiempo.",
    ["Don't mention it."] = "No lo menciones.",
    ["I've completed your task! Here are your bars!"] = "¡He completado tu tarea! ¡Aquí están tus barras!",
    ["The Silver Cog can always rely on you, Player."] = "Silver Cog siempre puede confiar en ti, Player.",
    ["I will get my secretary to send this to the trade floor at once!"] = "¡Haré que mi secretaria envíe esto al parqué de inmediato!",
    ["Welcome back, Player, it's great to see you again!"] = "Bienvenido de nuevo, Player, ¡es un placer verte de nuevo!",
    ["And how can the Silver Cog be of service to you today, Player?"] = "¿Y cómo puede servirte el Silver Cog hoy, Player?",
    ["Come in, come in my friend!"] = "¡Entra, entra amigo mío!",
    ["The Silver Cog is pleased to see you again!"] = "¡El Silver Cog se complace en verte de nuevo!",
    ["Hello again, Player, come in!"] = "Hola de nuevo, Player, ¡pasa!",
    ["**Player:** It's an honour to meet you!"] = "**Player:** ¡Es un honor conocerte!",
    ["Delightful to see you again as well!"] = "¡Encantado de verte de nuevo también!",
    ["And I am honoured to make some time for you, Player!"] = "¡Y es un honor para mí dedicar algo de tiempo a ti, Player!",
    ["Don't mention it, Player!"] = "¡Ni lo menciones, Player!",
    ["Almost as much an honour as it is to meet you again, Player!"] = "¡Es casi tan honor como volver a encontrarte, Player!",
    ["I'm always happy to make time for you, Player!"] = "¡Siempre estoy feliz de tener tiempo para ti, Player!",
    ["It was time well spent!"] = "¡Fue un tiempo bien empleado!",
    ["Not at all, it was a delight to speak to you once more!"] = "Para nada, ¡fue un placer hablar contigo una vez más!",
    ["Guthix be praised!"] = "¡Alabado sea Guthix!",
    ["I am well pleased with your work, Player!"] = "¡Estoy muy satisfecho con tu trabajo, Player!",
    ["You are a true asset to the Silver Cog!"] = "¡Eres un verdadero activo para Silver Cog!",
    ["You never fail to satisfy, Player!"] = "¡Nunca dejas de satisfacer, Player!",
    ["Hello Player! Have you seen the statue? It looks beautiful! The Silver Cog is indebted to you for your dedication in making this happen!"] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! ¡Silver Cog está en deuda con usted por su dedicación para hacer que esto suceda!",
    ["More work? My, you certainly are an asset to the company."] = "¿Más trabajo? Vaya, ciertamente eres un activo para la empresa.",
    ["Really, Player, you don't need to do this anymore."] = "De verdad, Player, ya no necesitas hacer esto.",
    ["But I want to!"] = "¡Pero quiero hacerlo!",
    ["Well, if you insist..."] = "Bueno, si insistes...",
    ["You don't need to do this anymore, you know?"] = "Ya no necesitas hacer esto, ¿sabes?",
    ["Ah, if only all the members of the Silver Cog had such dedication as you."] = "Ah, si tan solo todos los miembros de Silver Cog tuvieran tanta dedicación como tú.",
    ["The trade floor guards keep attacking me!"] = "¡Los guardias del piso de comercio siguen atacándome!",
    ["I might be able to get the guards off your back, if you perform a task for the company."] = "Quizás pueda quitarte los guardias de encima si realizas una tarea para la empresa.",
    ["Until later, then, my friend! I'm sure the Silver Cog will play a role in your future again at some point!"] = "¡Hasta luego, amigo! ¡Estoy seguro de que Silver Cog volverá a desempeñar un papel en tu futuro en algún momento!",
    ["I'll have a word with the guards. They won't be watching you for the next ten minutes."] = "Hablaré con los guardias. No te estarán mirando durante los próximos diez minutos.",
    ["The trade floor guards are now bribed to ignore you."] = "Los guardias del piso de comercio ahora están sobornados para que lo ignoren.",
    ["Hello Player! Have you seen the statue? It looks beautiful! It's a pity it's been overshadowed by the departure of the Red Axe."] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! Es una pena que se haya visto eclipsado por la marcha del Red Axe.",
    ["Handing over power to the monarchy was the worst day of my life. At least King Veldaban has kept the Consortium around as an advisory body."] = "Entregar el poder a la monarquía fue el peor día de mi vida. Al menos el rey Veldaban ha mantenido al Consorcio como organismo asesor.",
    ["I hope you understand what you've done, human. You could have convinced Veldaban to step down and let the experts take over. Instead we're saddled with his ridiculous policies again."] = "Espero que entiendas lo que has hecho, humano. Podrías haber convencido a Veldaban de que renunciara y dejara que los expertos se hicieran cargo. En cambio, volvemos a cargar con sus ridículas políticas.",
    ["Things could be worse, I suppose. The new king is listening to the Consortium's advice... on the few occasions he's sober enough to understand it."] = "Las cosas podrían ser peores, supongo. El nuevo rey está escuchando los consejos del Consorcio... en las pocas ocasiones en que está lo suficientemente sobrio como para entenderlos.",
    ["Thanks for your support in the meeting, Player. Now Keldagrim can put the silly business of kings behind it and let the company directors manage things properly."] = "Gracias por tu apoyo en la reunión, Player. Ahora Keldagrim puede dejar atrás los tontos negocios de los reyes y dejar que los directores de la empresa gestionen las cosas correctamente.",
    ["I don't have much time for you, what do you want?"] = "No tengo mucho tiempo para ti, ¿qué quieres?",
    ["You're blocking my view, human, so hurry up."] = "Estás bloqueando mi vista, humano, así que date prisa.",
    ["Can we hurry this along?"] = "¿Podemos apurarnos?",
    ["Say what you want or get out of our office, human!"] = "¡Di lo que quieras o sal de nuestra oficina, humano!",
    ["Do not test the patience of the Silver Cog, human. Say what you need!"] = "No pongas a prueba la paciencia del Silver Cog, humano. ¡Di lo que necesites!",
    ["I think I've misplaced my quill somewhere..."] = "Creo que perdí mi pluma en alguna parte...",
    ["Oh, and what did you want?"] = "Ah, ¿y qué querías?",
    ["I am the head secretary of the Silver Cog."] = "Soy el secretario principal de Silver Cog.",
    ["The what?"] = "¿El qué?",
    ["The Silver Cog! A shining example of how a mining company should be run to join the Consortium."] = "¡El engranaje plateado! Un brillante ejemplo de cómo se debe gestionar una empresa minera para unirse al Consorcio.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["I'm not here to give directions!"] = "¡No estoy aquí para dar instrucciones!",
    ["Do I look like a tour guide to you?"] = "¿Te parezco un guía turístico?",
    ["I'd tell you, human, but you wouldn't understand anyway."] = "Te lo diría, humano, pero de todos modos no lo entenderías.",
    ["These are the offices of the Silver Cog."] = "Estas son las oficinas de Silver Cog.",
    ["We share this floor of the palace with the other companies of the Consortium. And trade with them on the Trade Octagon."] = "Compartimos esta planta del palacio con el resto de empresas del Consorcio. Y comercie con ellos en el octágono comercial.",
    ["The Trade Octagon?"] = "¿El octágono comercial?",
    ["See those traders standing out there, just out the door? They're all standing in the Trade Octagon. There's an awful lot of trade going on in the palace, you know."] = "¿Ves a esos comerciantes parados ahí afuera, justo afuera de la puerta? Todos están parados en el octágono comercial. Hay muchísimo comercio en el palacio, ¿sabes?",
    ["Anything else of interest in the palace?"] = "¿Algo más de interés en el palacio?",
    ["You will have to find that out on your own, I'm afraid. I do have more work to do."] = "Me temo que tendrás que descubrirlo por tu cuenta. Tengo más trabajo que hacer.",
    ["Come to redeem yourself at our company, have you?"] = "Ven a redimirte en nuestra empresa, ¿verdad?",
    ["So you're looking for work with us all of a sudden?"] = "¿Entonces de repente estás buscando trabajo con nosotros?",
    ["You're lucky the Silver Cog is very forgiving, human."] = "Tienes suerte de que Silver Cog sea muy indulgente, humano.",
    ["I'm not sure if I'm allowed to give someone like you a task, I'll check."] = "No estoy seguro de poder asignarle una tarea a alguien como tú, lo comprobaré.",
    ["All right, you've been cleared."] = "Muy bien, has sido autorizado.",
    ["Your motives are questionable but we'll give you a chance."] = "Tus motivos son cuestionables, pero te daremos una oportunidad.",
    ["We need [number] pieces of [ore] in the next [number] minutes."] = "Necesitamos [número] piezas de [ore] en los próximos minutos [número].",
    ["Do no disappoint the Silver Cog, human."] = "No decepciones al Silver Cog, humano.",
    ["Go then! The longer you stand here the more time you waste!"] = "¡Vete entonces! ¡Cuanto más tiempo estés aquí, más tiempo perderás!",
    ["Hurry back or don't come back at all!"] = "¡Date prisa o no vuelvas!",
    ["Let's hope I was wrong about you, human."] = "Esperemos haberme equivocado contigo, humano.",
    ["You'd better not fail!"] = "¡Será mejor que no falles!",
    ["Oh, so you were just stopping by to waste my time, then? Goodbye!"] = "Oh, ¿entonces viniste a hacerme perder el tiempo? ¡Adiós!",
    ["To say a thing like that after the mercy I just showed you! Go away!"] = "¡Decir algo así después de la misericordia que te acabo de mostrar! ¡Irse!",
    ["You dare!"] = "¡Te atreves!",
    ["Thought you wouldn't. Now get out of here!"] = "Pensé que no lo harías. ¡Ahora sal de aquí!",
    ["Leave now, don't make me call the Black Guard to throw you out!"] = "¡Vete ahora, no me hagas llamar al Black Guard para echarte!",
    ["Get out of our office then!"] = "¡Entonces sal de nuestra oficina!",
    ["The Silver Cog offers you a chance and you say this? Just stay away!"] = "¿El Silver Cog te ofrece una oportunidad y dices esto? ¡Sólo mantente alejado!",
    ["Have you completed your current task yet? Did you get me my [number] pieces of [ore]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis piezas [número] de [ore]?",
    ["No, not yet."] = "No, todavía no.",
    ["You're a disgrace to the Silver Cog. Hurry up if you want to redeem yourself."] = "Eres una vergüenza para Silver Cog. Date prisa si quieres redimirte.",
    ["Go back to your friends at the [other Company], I hear you're in league with them."] = "Vuelve con tus amigos del [other Company], he oído que estás aliado con ellos.",
    ["I have to go!"] = "¡Tengo que irme!",
    ["Finally...back to work at last."] = "Finalmente... por fin volvemos al trabajo.",
    ["Good."] = "Bien.",
    ["Don't hurry back."] = "No te apresures a regresar.",
    ["The door is over there. I suggest you use it."] = "La puerta está por ahí. Te sugiero que lo uses.",
    ["And good riddance to you."] = "Y adiós.",
    ["I've completed your task! Here is your ore!"] = "¡He completado tu tarea! ¡Aquí está tu mineral!",
    ["How unusual for you, but it is appreciated nonetheless."] = "Qué inusual para ti, pero de todos modos se agradece.",
    ["The Silver Cog is pleased that the trust it put in you has not been put to shame after all."] = "Silver Cog se alegra de que, después de todo, la confianza que depositó en ti no haya sido avergonzada.",
    ["That is quite a pleasant and unexpected surprise."] = "Es una sorpresa bastante agradable e inesperada.",
    ["Perhaps I was wrong about you after all..."] = "Quizás me equivoqué contigo después de todo...",
    ["Thanks... I suppose."] = "Gracias... Supongo.",
    ["What did you need of the Silver Cog?"] = "¿Qué necesitabas del Silver Cog?",
    ["And what can I do for you?"] = "¿Y qué puedo hacer por ti?",
    ["Is there anything you need assistance with?"] = "¿Hay algo con lo que necesites ayuda?",
    ["Can I help you with anything?"] = "¿Puedo ayudarte en algo?",
    ["Was there anything you wanted?"] = "¿Había algo que quisieras?",
    ["What can I do for you, human?"] = "¿Qué puedo hacer por ti, humano?",
    ["Why, this is the headquarters of the Silver Cog."] = "Vaya, esta es la sede de Silver Cog.",
    ["There's always work to be done, yes."] = "Siempre hay trabajo por hacer, sí.",
    ["Just a moment."] = "Un momento.",
    ["Yes, the Silver Cog always has work to do!"] = "Sí, ¡Silver Cog siempre tiene trabajo que hacer!",
    ["Let's see... yes, yes, I do have a task for you."] = "Veamos... sí, sí, tengo una tarea para ti.",
    ["Yes, I think we do have something for you."] = "Sí, creo que tenemos algo para ti.",
    ["I believe we have some work available, yes."] = "Creo que tenemos trabajo disponible, sí.",
    ["The Silver Cog has noted your willingness to help."] = "Silver Cog ha notado tu voluntad de ayudar.",
    ["That ore needs to go on the trade floor soon, player, please hurry back with it."] = "Ese mineral debe estar pronto en la sala de operaciones, jugador, por favor regresa con él.",
    ["Thanks, it's appreciated."] = "Gracias, se agradece.",
    ["The clock is ticking, please hurry back."] = "El tiempo corre, por favor regresa rápido.",
    ["I will await your return soon, then."] = "Entonces, esperaré tu regreso pronto.",
    ["Fair enough, maybe some other time?"] = "Muy bien, ¿tal vez en otro momento?",
    ["Please, it would be appreciated if you made up your mind before you ask. I'm very busy you know."] = "Por favor, le agradeceríamos que tomara una decisión antes de preguntar. Estoy muy ocupado, ¿sabes?",
    ["Please, in that case, you're wasting my time."] = "Por favor, en ese caso, estás perdiendo el tiempo.",
    ["That's unfortunate to hear."] = "Es lamentable escuchar eso.",
    ["I can't say I'm too pleased to hear that, to be honest."] = "Para ser honesto, no puedo decir que esté muy contento de escuchar eso.",
    ["That does not reflect well on you."] = "Eso no te refleja bien.",
    ["The Silver Cog isn't too pleased to hear that."] = "Silver Cog no está muy contento de escuchar eso.",
    ["Then please, hurry up before time runs out."] = "Entonces, por favor, apúrate antes de que se acabe el tiempo.",
    ["From what I understand, you have some business to finish with the [other Company] first."] = "Por lo que tengo entendido, primero tienes algunos asuntos que terminar con el [other Company].",
    ["See you later."] = "Hasta luego.",
    ["Goodbye, human."] = "Adiós, humano.",
    ["I have to admit, I was worried for a moment, but I'm glad to see you came through for us."] = "Tengo que admitir que estuve preocupado por un momento, pero me alegra ver que nos ayudaste.",
    ["I am happy to see that the trust we put in you has not been in vain."] = "Me alegra comprobar que la confianza que depositamos en vosotros no ha sido en vano.",
    ["And not a minute too late as well. Well done."] = "Y ni un minuto tarde también. Bien hecho.",
    ["The Silver Cog recognizes your performance."] = "El Silver Cog reconoce tu desempeño.",
    ["That's good to hear, thanks."] = "Es bueno escucharlo, gracias.",
    ["How may the Silver Cog assist you today?"] = "¿Cómo puede ayudarte Silver Cog hoy?",
    ["And what can I do for you on this fine day?"] = "¿Y qué puedo hacer por ti en este lindo día?",
    ["Come to help us some more, Player?"] = "¿Ven a ayudarnos un poco más, Player?",
    ["Oh, hello there Player! Nice to see you!"] = "¡Oh, hola Player! ¡Qué bueno verte!",
    ["Welcome back to the palace of Keldagrim, Player!"] = "¡Bienvenido de nuevo al palacio de Keldagrim, Player!",
    ["Come in, come in! And tell us what you need!"] = "¡Entra, entra! ¡Y cuéntanos qué necesitas!",
    ["The top floor of the palace is the Meeting Octagon. That's the place where the Consortium makes all the important decisions."] = "El último piso del palacio es el Octágono de Reuniones. Ese es el lugar donde el Consorcio toma todas las decisiones importantes.",
    ["Can I go there?"] = "¿Puedo ir allí?",
    ["Oh, yes, you certainly can. But not while the Consortium is in session, I would imagine."] = "Oh, sí, ciertamente puedes. Pero me imagino que no mientras el Consorcio esté en sesión.",
    ["Even though you are a very friendly human, I'm not sure if you would be allowed to visit during a meeting."] = "Aunque eres una persona muy amigable, no estoy seguro de si se te permitiría visitarnos durante una reunión.",
    ["But I don't know enough about that, the director probably knows more."] = "Pero no sé lo suficiente sobre eso, el director probablemente sepa más.",
    ["Thanks for the info!"] = "¡Gracias por la información!",
    ["Ah, always looking for ways to help us!"] = "¡Ah, siempre buscando formas de ayudarnos!",
    ["Naturally, my good human, naturally!"] = "¡Por supuesto, mi buen humano, por supuesto!",
    ["Of course, we reserve our best tasks just for you, Player!"] = "¡Por supuesto, reservamos nuestras mejores tareas solo para ti, Player!",
    ["I do believe we do, yes!"] = "Creo que sí, ¡sí!",
    ["I dare say we have something for you, yes."] = "Me atrevo a decir que tenemos algo para ti, sí.",
    ["Oh yes, as you know the Silver Cog always has work!"] = "¡Oh, sí, como sabes, Silver Cog siempre tiene trabajo!",
    ["You never disappoint, Player!"] = "¡Nunca decepcionas, Player!",
    ["Excellent, I thought you'd like this!"] = "¡Excelente, pensé que te gustaría esto!",
    ["I'm happy to hear that!"] = "¡Me alegra escuchar eso!",
    ["The Silver Cog appreciates the hard work you do."] = "Silver Cog aprecia el arduo trabajo que haces.",
    ["Thanks! But hurry back please, we really need that ore!"] = "¡Gracias! Pero date prisa, por favor, ¡realmente necesitamos ese mineral!",
    ["I suppose you have other important business to attend to?"] = "Supongo que tienes otros asuntos importantes que atender.",
    ["Oh. Didn't know you were the type to refuse work."] = "Ah. No sabía que eras del tipo que rechaza el trabajo.",
    ["Is everything okay? I didn't think you normally refused our tasks."] = "¿Está todo bien? No pensé que normalmente rechazaras nuestras tareas.",
    ["That's a great shame, Player."] = "Es una gran lástima, Player.",
    ["No? That's unusual for you, Player."] = "¿No? Eso es inusual para ti, Player.",
    ["Sorry to hear that, but please hurry up!"] = "Lamento escuchar eso, ¡pero apúrate!",
    ["Don't you have some business with [other company] to deal with first? Hurry back when you're done!"] = "¿No tienes algún asunto con [other company] que tratar primero? ¡Date prisa cuando hayas terminado!",
    ["It was a pleasure to talk to you again, Player."] = "Fue un placer volver a hablar contigo, Player.",
    ["Come back any time!"] = "¡Vuelve cuando quieras!",
    ["See you soon!"] = "¡Hasta pronto!",
    ["Wonderful! I will personally oversee that it goes to the trade floor on time!"] = "¡Maravilloso! ¡Supervisaré personalmente que llegue a tiempo al parqué!",
    ["Well done, well done!"] = "¡Bien hecho, bien hecho!",
    ["I knew you were the right human for the job!"] = "¡Sabía que eras la persona adecuada para el trabajo!",
    ["Thanks, I will make sure the director hears of your expeditiousness!"] = "¡Gracias, me aseguraré de que el director se entere de su rapidez!",
    ["You're always reliable, Player!"] = "¡Siempre eres confiable, Player!",
    ["I'm afraid I have no more work to offer you, Player, please speak to the director."] = "Me temo que no tengo más trabajo que ofrecerte, Player, por favor habla con el director.",
    ["You should speak directly to the director."] = "Deberías hablar directamente con el director.",
    ["Silver! Silver! Best prices for buying and selling in all Kandarin!"] = "¡Plata! ¡Plata! ¡Los mejores precios de compra y venta en todo Kandarin!",
    ["Ask about the Outpost."] = "Pregunta por el puesto de avanzada.",
    ["Hello, I hope Jorral was pleased with that journal."] = "Hola, espero que Jorral esté satisfecho con ese diario.",
    ["I'm sure it's been a valuable find."] = "Estoy seguro de que ha sido un hallazgo valioso.",
    ["What I came to ask was: I lost that key you gave me."] = "Lo que vine a preguntar fue: Perdí esa llave que me diste.",
    ["Oh dear. Can't help you there."] = "Dios mío. No puedo ayudarte ahí.",
    ["Suppose I could have a chat with Jorral, maybe he has ideas for getting another."] = "Supongamos que puedo charlar con Jorral, tal vez tenga ideas para conseguir otro.",
    ["G'day, mate. I'm Simon. Simon Templeton. Who are you?"] = "Buenos días, amigo. Soy Simon. Simon Templeton. ¿Quién eres?",
    ["I'm Player. What are you doing all the way out here?"] = "Soy Player. ¿Qué estás haciendo hasta aquí?",
    ["I've been contracted to retrieve artefacts from the top of this magnificient pyramid."] = "Me contrataron para recuperar artefactos de la cima de esta magnífica pirámide.",
    ["So, why are you down here and not up there?"] = "Entonces, ¿por qué estás aquí abajo y no allá arriba?",
    ["Well, it's me back...an old injury I picked up in Sophanem has come back to haunt me. I was working for Varrock Museum, but the gold they gave me wasn't even enough to pay for the carpet rides, let alone any decent equipment."] = "Bueno, soy yo de vuelta... una vieja lesión que sufrí en Sophanem ha vuelto para atormentarme. Trabajaba para el Museo Varrock, pero el oro que me dieron no era suficiente ni para pagar las atracciones en alfombra, y mucho menos un equipo decente.",
    ["But that was a long time ago... I can't even lift a chisel right now. There's no way I can climb all the way up there."] = "Pero eso fue hace mucho tiempo... Ahora mismo ni siquiera puedo levantar un cincel. No hay manera de que pueda subir hasta allí.",
    ["Hang on a second... You look like you're pretty agile and up for a challenge. How about you retrieve them for me?"] = "Espera un segundo... Parece que eres bastante ágil y estás preparado para un desafío. ¿Qué tal si me los recuperas?",
    ["I'll tell you what. I'll give you 1,000 coins for every artefact you get for me."] = "Te diré una cosa. Te daré 1000 coins por cada artefacto que me consigas.",
    ["Good on ya, mate!"] = "¡Bien por ti, amigo!",
    ["Hello, Simon."] = "Hola, Simon.",
    ["G'day, Player."] = "Buenos días, Player.",
    ["How's it going?"] = "¿Cómo te va?",
    ["I've been contracted to retrieve artefacts from the top of this magnificent pyramid."] = "Me contrataron para recuperar artefactos de la cima de esta magnífica pirámide.",
    ["Got any Agility Pyramid artefacts for me?"] = "¿Tienes algún artefacto de la pirámide Agility para mí?",
    ["Sell it."] = "Véndelo.",
    ["I have one here I'll sell you."] = "Tengo uno aquí y te lo venderé.",
    ["[Simon hands you a total of 1,000 coins for the sale.]"] = "[Simon te entrega un total de 1000 coins para la venta.]",
    ["Ripper! Thanks a bundle, mate. Thanks to you, I can fulfill me contract. You're a true blue. The boss will be pleased."] = "¡Destripador! Muchas gracias, amigo. Gracias a ti puedo cumplir mi contrato. Eres un verdadero azul. El jefe estará contento.",
    ["Glad I was able to help...but who is your boss? I thought you worked for Varrock Museum?"] = "Me alegro de haber podido ayudar... pero ¿quién es tu jefe? Pensé que trabajabas para el Museo Varrock.",
    ["Mind your own bizzo, mate. But if you get any more, you know where I am."] = "Ocúpate de tus propias bizzo, amigo. Pero si consigues más, ya sabes dónde estoy.",
    ["Keep it."] = "Guárdalo.",
    ["I have one, but I want to keep it for now."] = "Tengo uno, pero quiero conservarlo por ahora.",
    ["Careful, mate. People might come looking for a thing like that."] = "Cuidado, amigo. La gente podría venir buscando algo así.",
    ["Thanks for the advice, but I'll hang onto it for now."] = "Gracias por el consejo, pero lo mantendré por ahora.",
    ["Bye, cobber."] = "Adiós, cobber.",
    ["No, I haven't."] = "No, no lo he hecho.",
    ["Try harder, mate! It won't be long till some other critter turns up and stanches them out from under your eyes."] = "¡Esfuérzate más, amigo! No pasará mucho tiempo hasta que aparezca otra criatura y los elimine de debajo de tus ojos.",
    ["I will. Goodbye, Simon."] = "Lo haré. Adiós, Simon.",
    ["I'd like to talk a bit."] = "Me gustaría hablar un poco.",
    ["Shoot away, sport."] = "Dispara, deporte.",
    ["About that little job you mentioned..."] = "Sobre ese trabajito que mencionaste...",
    ["I can't remember whether I asked you to do this yet – mind like a sieve, I have – but have you ever talked to the Pyramid Plunder mummy in Sophanem about me?"] = "No recuerdo si te pedí que hicieras esto todavía (tengo la mente como un colador), pero ¿alguna vez has hablado con la momia Pyramid Plunder en Sophanem sobre mí?",
    ["Well, that's what you can do for me. Ask him if he'll let me have a quick shufty at some of his relics. I think I may be able to cut him a deal."] = "Bueno, eso es lo que puedes hacer por mí. Pregúntale si me dejará echar un vistazo rápido a algunas de sus reliquias. Creo que puedo hacerle un trato.",
    ["I talked to the mummy in Sophanem."] = "Hablé con la momia en Sophanem.",
    ["I take it she was no use. You look as dismal as a croc with toothache."] = "Supongo que no sirvió de nada. Te ves tan triste como un cocodrilo con dolor de muelas.",
    ["No good news, for sure. Wait. What? She? I always assumed it was a man under those bandages."] = "No hay buenas noticias, seguro. Esperar. ¿Qué? ¿Ella? Siempre supuse que había un hombre debajo de esas vendas.",
    ["Was your mummy a man? He, he, he."] = "¿Tu mamá era un hombre? Él, él, él.",
    ["That joke stinks worse than those bronze 'antiques' I delivered to you."] = "Ese chiste apesta peor que esas 'antigüedades' de bronce que te entregué.",
    ["Jokes aside, you've been a good sport. As a favour, from now on, I'm willing to take bank certificates of any objects you get from that miserable mummy's Pyramid Plunder. Well, any but the gold ones, that is - you might be tempted to fake stuff if there's a profit involved, as we both know."] = "Bromas aparte, has sido un buen deportista. Como favor, de ahora en adelante, estoy dispuesto a recibir certificados bancarios de cualquier objeto que consigas del Saqueo de la Pirámide de esa miserable momia. Bueno, cualquiera menos los de oro, es decir, podrías sentirte tentado a falsificar cosas si hay una ganancia involucrada, como ambos sabemos.",
    ["And the mummy has more loot plundered and ends up even more miserable. I see your cunning plan. It also makes me wonder, would your client for those artefacts be anything to do with a bank, by any chance?"] = "Y la momia tiene más botín saqueado y termina aún más miserable. Veo tu astuto plan. También me hace preguntarme: ¿el cliente de esos artefactos tendría algo que ver con un banco, por casualidad?",
    ["Curiosity... Cats... Need I say more?"] = "Curiosidad... Gatos... ¿Necesito decir más?",
    ["I have some more questions."] = "Tengo algunas preguntas más.",
    ["Actually, I'd like to discuss business matters."] = "En realidad, me gustaría hablar de asuntos comerciales.",
    ["What do you know of other archaeologists in this area?"] = "¿Qué sabes de otros arqueólogos en esta zona?",
    ["They're all a bit dodgy, if ya gets me drift."] = "Todos son un poco dudosos, si me entiendes.",
    ["Dodgy?"] = "¿Dudoso?",
    ["Them blokes in Varrock just put out the call for researchers, half trained 'em then ran out of cash. Left a load of folks about as angry as a barrel o' crocs. Young, angry and poor makes a fella dodgy."] = "Esos tipos de Varrock acaban de llamar a investigadores, los capacitaron a medias y luego se quedaron sin efectivo. Dejó a un montón de gente tan enojada como un barril de cocodrilos. Joven, enojado y pobre hace que un tipo sea poco fiable.",
    ["Why would Varrock stop the money?"] = "¿Por qué Varrock detendría el dinero?",
    ["They made all them fancy doodahs in the museum, for one. Bet they didn't come cheap. Then there's some island expedition they were planning – reckon that sucked up a load of cash, too."] = "Hicieron todos esos adornos elegantes en el museo, por ejemplo. Apuesto a que no fueron baratos. Luego estaban planeando una expedición a la isla, que también les costó mucho dinero.",
    ["Anyways, it does mean more folks willing to sell – so, silver linings, eh?"] = "De todos modos, eso significa que habrá más gente dispuesta a vender, así que, aspectos positivos, ¿eh?",
    ["Quite."] = "Bastante.",
    ["Who are you selling all these items on to?"] = "¿A quién le estás vendiendo todos estos artículos?",
    ["Well, it's not that Osman – I can tell ya that much. Don't be having dealings with him; he's a slippery customer."] = "Bueno, no es eso Osman – Eso te puedo decir. No tengas tratos con él; es un cliente resbaladizo.",
    ["Slippery?"] = "¿Resbaladizo?",
    ["He was always after documents – new, old, fake, authentic. Claimed it didn't matter to him. Was obvious that royal history was what got him all excited, though. Now, what's a man like him wanting with that sort of information? He's not some fancy librarian, just some sort of lackey. He musta guessed I was onto something, so he cut me out cold."] = "Siempre buscaba documentos: nuevos, viejos, falsos, auténticos. Afirmó que no le importaba. Sin embargo, era obvio que la historia real era lo que lo entusiasmaba. Ahora bien, ¿qué quiere un hombre como él con ese tipo de información? No es un bibliotecario elegante, sólo una especie de lacayo. Debió adivinar que yo estaba en algo, así que me cortó en seco.",
    ["So, who do you sell to now?"] = "Entonces, ¿a quién le vendes ahora?",
    ["Are you daft or what? I'm a middleman, a fixer – if I tell you that I'll be cutting me own throat. We'll talk about other stuff."] = "¿Eres tonto o qué? Soy un intermediario, un reparador; si te digo eso, me cortaré el cuello. Hablaremos de otras cosas.",
    ["What do you know of underground areas to the east?"] = "¿Qué sabes de las áreas subterráneas del este?",
    ["A bit of this, a bit of that. Those ruins are older than Sophanem and Menaphos, for sure. Pulled some documents out before them creepy crawlies took over."] = "Un poco de esto, un poco de aquello. Esas ruinas son más antiguas que Sophanem y Menaphos, seguro. Saqué algunos documentos antes de que esos bichos se hicieran cargo.",
    ["So the Scabarites are new arrivals there?"] = "Entonces, ¿los scabaritas son recién llegados allí?",
    ["Seems so, but don't ask me why. All that research stuff is ancient history to me, now...if ya pardom me pun. I'm just gathering cash and that's it."] = "Eso parece, pero no me preguntes por qué. Todo ese material de investigación es historia antigua para mí, ahora... si me perdonan el juego de palabras. Sólo estoy juntando efectivo y eso es todo.",
    ["Cash for what? There's nothing to spend it on out here in the middle of nowhere?"] = "¿Dinero para qué? ¿No hay nada en qué gastarlo aquí en medio de la nada?",
    ["C'mon, sport. You know me better than to stick your snout where it might end up sliced off. Ask no questions, hear no lies."] = "Vamos, deporte. Me conoces mejor que para meter el hocico donde podría terminar cortado. No hagas preguntas, no escuches mentiras.",
    ["Actually, I'd like to talk about business matters."] = "En realidad, me gustaría hablar de asuntos comerciales.",
    ["Actually, I'd like to change the subject back to business matters."] = "En realidad, me gustaría volver a cambiar el tema a asuntos comerciales.",
    ["I have some interesting artefacts I'd like you to look at."] = "Tengo algunos artefactos interesantes que me gustaría que vieras.",
    ["Bonza! Let's have a butcher's, mate."] = "¡Bonza! Vamos a una carnicería, amigo.",
    ["Do you want to flog the lot of 'em?"] = "¿Quieres azotarlos a todos?",
    ["Do you want to sell all your artefacts?"] = "¿Quieres vender todos tus artefactos?",
    ["Yes, show me the money."] = "Sí, muéstrame el dinero.",
    ["You sellin' me this gold coloured stick thing? Looks fake to me. I'll give you 100 gold for it."] = "¿Me estás vendiendo este palo dorado? Me parece falso. Te daré 100 de oro por ello.",
    ["What! This is a genuine pharaoh's sceptre - made out of solid gold and finely jewelled with precious gems by the finest craftsmen in the area."] = "¡Qué! Este es un cetro de faraón genuino, hecho de oro macizo y adornado con gemas preciosas por los mejores artesanos de la zona.",
    ["Strewth! I can tell a pile of croc when I hear it! You've got the patter mate, but I'm no mug. That's a fake."] = "¡Esparcimiento! ¡Puedo distinguir un montón de cocodrilos cuando lo escucho! Tienes la charla, compañero, pero no soy un tonto. Eso es falso.",
    ["It has magical powers!"] = "¡Tiene poderes mágicos!",
    ["Oh, magical powers ... yeah, yeah, yeah. Heard it all before mate. I'll give you a 100 gold, or some 'magic beans'. Take it or leave it."] = "Oh, poderes mágicos... sí, sí, sí. Lo escuché todo antes, amigo. Te daré 100 de oro o unos 'frijoles mágicos'. Tómalo o déjalo.",
    ["I don't think so! I'll find someone who'll give me what it's worth."] = "¡No lo creo! Encontraré a alguien que me dé lo que vale.",
    ["Suit yerself.. You wanna sell the other artefacts you have?"] = "Como quieras.. ¿Quieres vender los otros artefactos que tienes?",
    ["Sell other artefacts?"] = "¿Vender otros artefactos?",
    ["Yes, as long as I get a decent price for them."] = "Sí, siempre y cuando consiga un precio decente por ellos.",
    ["Nah, I've changed my mind."] = "No, he cambiado de opinión.",
    ["Fair Dinkum mate, Bonzer doing business with you mate."] = "Justo amigo Dinkum, Bonzer hace negocios contigo, amigo.",
    ["Fair dinkum, mate. Bonzer doing business with you."] = "Buen dinero, amigo. Bonzer haciendo negocios contigo.",
    ["No, let me think about it."] = "No, déjame pensarlo.",
    ["No probs mate. Just give me the items you want to sell and we can do them one by one."] = "No hay problema, amigo. Sólo dame los artículos que quieres vender y podemos hacerlos uno por uno.",
    ["Got any more Agility Pyramid artefacts for me?"] = "¿Tienes más artefactos de la pirámide Agility para mí?",
    ["Sell [it/them]."] = "Vender [it/them].",
    ["I have [one/some] here I'll sell you."] = "Tengo [one/some] aquí, te lo vendo.",
    ["[Simon hands you a total of [1,000/10,000 * N] coins for the sale.]"] = "[Simon te entrega un total de [1,000/10,000 * N] coins para la venta.]",
    ["Keep [it/them]."] = "Mantenga [it/them].",
    ["I have [one/some], but I want to keep [it/them] for now."] = "Tengo [one/some], pero quiero conservar [it/them] por ahora.",
    ["Well, keep my offer in mind if you do find one."] = "Bueno, ten en cuenta mi oferta si encuentras una.",
    ["Bye, mate."] = "Adiós, amigo.",
    ["Sell all your artefacts."] = "Vende todos tus artefactos.",
    ["Don't sell."] = "No vendas.",
    ["Sorry, mate, I don't see anything I want."] = "Lo siento, amigo, no veo nada de lo que quiero.",
    ["You wanna sell that mate?"] = "¿Quieres vender ese compañero?",
    ["Do you want to sell your [artefact]?"] = "¿Quieres vender tu [artefact]?",
    ["Cheers mate!"] = "¡Salud amigo!",
    ["No, I think I'll keep it."] = "No, creo que me lo quedaré.",
    ["Simon wants nothing to do with this."] = "Simon no quiere tener nada que ver con esto.",
    ["You wanna sell that, mate?"] = "¿Quieres vender eso, amigo?",
    ["Do you want to sell your null"] = "¿Quieres vender tu null?",
    ["Do you want to sell your certed [artefact]?"] = "¿Quieres vender tu [artefact] certificado?",
    ["Got any Agility Pyramid artefacts? I'll give you cash for any you have."] = "¿Tienes algún artefacto de la pirámide Agility? Te daré efectivo por lo que tengas.",
    ["I'll sell [it/them] to you."] = "Te venderé [it/them].",
    ["You sellin' me this gold coloured stick thing. Looks fake to me. I'll give you 100 gold for it."] = "Me estás vendiendo este palo de color dorado. Me parece falso. Te daré 100 de oro por ello.",
    ["Suit yerself.."] = "Haz lo que quieras..",
    ["*Shows previous options*"] = "*Muestra opciones anteriores*",
    ["*Opens Simon's Wilderness Cape Shop*"] = "*Abre la tienda de capas Wilderness de Simon*",
    ["I'd like to access my bank please."] = "Me gustaría acceder a mi banco, por favor.",
    ["*Opens Bank of Gielinor*"] = "*Abre el Banco de Gielinor*",
    ["*Closes dialogue*"] = "*Cierra el diálogo*",
    ["I brought you some astral runes."] = "Te traje algunas runas astrales.",
    ["Thank you so much!"] = "¡Muchas gracias!",
    ["You know, you're really brave being out here in the wilderness all by yourself."] = "Sabes, eres muy valiente al estar aquí solo en el wilderness.",
    ["I used to be afraid, but I overcame all my fears."] = "Solía tener miedo, pero superé todos mis miedos.",
    ["Someone once told me 'Don't believe in the you that believes in me and don't believe in the me that believes in you. Believe in the you that believes in yourself."] = "Alguien me dijo una vez: 'No creas en el tú que cree en mí y no creas en el yo que cree en ti'. Cree en el tú que cree en ti mismo.",
    ["Wow, those are strong words to live by!"] = "¡Vaya, esas son palabras fuertes para vivir!",
    ["They sure are."] = "Seguro que lo son.",
    ["I'm Simona. I'm trying to stay warm by this fire."] = "Soy Simona. Estoy tratando de mantenerme caliente junto a este fuego.",
    ["My inner eye is clouded from the wave of darkness; give me a moment."] = "Mi ojo interior está nublado por la ola de oscuridad; dame un momento.",
    ["What do you want?"] = "¿Qué quieres?",
    ["Augh! Your sins! They BLIND me!"] = "¡Ay! ¡Tus pecados! ¡Me CIEGARON!",
    ["Greetings, friend!"] = "¡Saludos amigo!",
    ["I'd like to view the rewards shop."] = "Me gustaría ver la tienda de recompensas.",
    ["Got a selection of good things on sale, stranger!"] = "¡Tengo una selección de cosas buenas a la venta, extraño!",
    ["I'm Sinn Derkwill. Inhabitant of these strange lands. Takin' the chance to sell me wares to you travellers. Don't get many visitors in these parts ya see."] = "Soy Sinn Derkwill. Habitante de estas extrañas tierras. Aprovechando la oportunidad de venderme productos a ustedes, viajeros. No recibes muchos visitantes por estas partes, ¿ves?",
    ["Don't you get lonely down here on your own?"] = "¿No te sientes solo aquí abajo?",
    ["Oh no, me and the ol' ferryman 'ave a wonderful time. The long winter evenings fly by."] = "Oh, no, el viejo barquero y yo lo pasamos de maravilla. Las largas tardes de invierno pasan volando.",
    ["Maybe it's the inhabitants of this place that are strange rather than the lands."] = "Quizás sean los habitantes de este lugar los más extraños que las tierras.",
    ["Hehehe, thank you."] = "Jejeje, gracias.",
    ["A battle that'll echo in eternity, my friend! A clash between two mighty gods of the desert pantheon. Be remembered through the ages it will! And we here are the chosen few that get to witness it. My my, whadda spectacle!"] = "¡Una batalla que resonará en la eternidad, amigo mío! Un choque entre dos poderosos dioses del panteón del desierto. ¡Será recordado a través de los siglos! Y aquí somos los pocos elegidos que podemos presenciarlo. ¡Dios mío, qué espectáculo!",
    ["If I help Icthlarin in this battle will I be able to purchase some of your wares?"] = "Si ayudo a Icthlarin en esta batalla, ¿podré comprar algunos de tus productos?",
    ["Oh yes, got some rare things on sale, stranger! Help our old friend Icthlarin out and you'll earn Noumenon Favour ya can purchase them with."] = "¡Oh, sí, tengo algunas cosas raras a la venta, extraño! Ayuda a nuestro viejo amigo Icthlarin y ganarás Noumenon Favor con el que podrás comprarlos.",
    ["Come back any time."] = "Vuelve cuando quieras.",
    ["Hey, Sweet Goods!"] = "¡Hola, Sweet Goods!",
    ["I beg your pardon! I'm a person, not an object!"] = "¡Le pido perdón! ¡Soy una persona, no un objeto!",
    ["Hahaha! No, Sweet Goods is the name of my shop, silly."] = "¡Jajaja! No, Sweet Goods es el nombre de mi tienda, tonto.",
    ["If you ever have berries to sell, bring 'em my way!"] = "Si alguna vez tienes berries para vender, ¡tráelos!",
    ["Hey! I got salt in my berries!"] = "¡Oye! ¡Tengo sal en mi berries!",
    ["Ooh, that sounds serious. You should see a doctor."] = "Oh, eso suena serio. Deberías ver a un médico.",
    ["What? No! Sea salt...in my rumberries. When I crushed that salt for you it got mixed in. My whole batch is..."] = "¿Qué? ¡No! Sal marina... en mis rumberries. Cuando trituré esa sal para ti, se mezcló. Todo mi lote es...",
    ["I'm really so-"] = "Estoy realmente tan-",
    ["DELICIOUS!"] = "¡DELICIOSO!",
    ["Happy I could help."] = "Feliz de poder ayudar.",
    ["It's a new flavour sensation! Try some!"] = "¡Es una nueva sensación de sabor! ¡Prueba algunos!",
    ["No, I'm good. Thank you. I can take your word for it that your salty berries are delicious."] = "No, estoy bien. Gracias. Puedo confiar en tu palabra de que tus berries salados son deliciosos.",
    ["I want 25 morchella mushrooms for that."] = "Quiero 25 champiñones morchella para eso.",
    ["Pay 25 morchella mushrooms?"] = "¿Pagar 25 champiñones morchella?",
    ["If you like, but I want 25 morchella mushrooms for that."] = "Si quieres, pero quiero 25 champiñones morchella para eso.",
    ["I am the leader of the White Knights of Falador. Why do you seek my audience?"] = "Soy el líder de los Caballeros Blancos de Falador. ¿Por qué buscas mi audiencia?",
    ["I seek a quest!"] = "¡Busco una búsqueda!",
    ["Speak about the A Void Dance quest."] = "Habla sobre la misión A Void Dance.",
    ["Well Player, now that you are a White Knight, I expect you should be out hunting Black Knights for us!"] = "Bueno, Player, ahora que eres un Caballero Blanco, ¡espero que deberías estar cazando a Black Knights para nosotros!",
    ["How does life find you today, Player?"] = "¿Cómo te encuentra la vida hoy, Player?",
    ["Can you explain the White Knight honour system again?"] = "¿Puedes volver a explicar el sistema de honor del Caballero Blanco?",
    ["Sadly we are not as rich as we once were, and there are many White Knights who foolishly lose their combat equipment."] = "Lamentablemente ya no somos tan ricos como antes, y hay muchos Caballeros Blancos que tontamente pierden su equipo de combate.",
    ["We do not think it fair to make a profit from our brethren, so we will sell you equipment at cost, and rebuy it at the same cost, but we will only sell equipment to those we consider responsible enough to wield it correctly."] = "No creemos que sea justo obtener ganancias de nuestros hermanos, por lo que les venderemos el equipo al costo y lo recompraremos al mismo costo, pero solo venderemos el equipo a aquellos que consideremos lo suficientemente responsables como para manejarlo correctamente.",
    ["By killing Black Knights, you will increase your reputation with us, by killing White Knights we will obviously think less of you."] = "Al matar a Black Knights, aumentarás tu reputación con nosotros, al matar a White Knights obviamente pensaremos menos en ti.",
    ["You can check your White Knight reputation level by looking at your quest journal for the Wanted! Quest, or Sir Vyvin will let you know what level you are at when you go to purchase equipment."] = "¡Puedes comprobar tu nivel de reputación de Caballero Blanco consultando tu diario de misiones de Se busca! Quest o Sir Vyvin te permitirán saber en qué nivel te encuentras cuando vayas a comprar equipo.",
    ["Sir Vyvin can be found in Falador Castle, and he will sell you any equipment appropriate to your reputation level."] = "Sir Vyvin se puede encontrar en el Castillo Falador y te venderá cualquier equipo apropiado para tu nivel de reputación.",
    ["Have fun, and go kill some Black Knights for me!"] = "¡Diviértete y ve a matar Black Knights por mí!",
    ["Okay Amik, thanks for explaining!"] = "Está bien Amik, ¡gracias por explicarlo!",
    ["Do you know anything about the siege of Falador?"] = "¿Sabes algo sobre el asedio de Falador?",
    ["Okay, bye!"] = "¡Está bien, adiós!",
    ["Okay, 'bye then Amik!"] = "Está bien, ¡adiós Amik!",
    ["Tell me about the Temple Knights."] = "Háblame de los Caballeros del Templo.",
    ["I cannot tell you much... They are called the Temple Knights, and are an organisation that was founded by Saradomin personally many centuries ago."] = "No puedo decirte mucho... Se llaman los Caballeros del Templo y son una organización que fue fundada personalmente por Saradomin hace muchos siglos.",
    ["There are many rumours and fables about their works and actions, but official records of their presence are non-existent."] = "Existen muchos rumores y fábulas sobre sus obras y acciones, pero los registros oficiales de su presencia son inexistentes.",
    ["It is a secret organisation of extraordinary power and resourcefulness..."] = "Es una organización secreta de extraordinario poder e ingenio...",
    ["Let me put it this way: Should you decide to take them up on their generous offer to join, you will find yourself in an advantageous position that many of this world would envy, and that few are called to occupy."] = "Déjame decirlo de esta manera: Si decides aceptar su generosa oferta de unirte, te encontrarás en una posición ventajosa que muchos en este mundo envidiarían y que pocos están llamados a ocupar.",
    ["Well, that wasn't quite as helpful as I thought it would be... but thanks anyway, I guess."] = "Bueno, eso no fue tan útil como pensé que sería... pero gracias de todos modos, supongo.",
    ["**Player:** Do you know anything about the siege of Falador?"] = "**Player:** ¿Sabes algo sobre el asedio de Falador?",
    ["Ah yes, the Kinshra siege was a close-run thing indeed."] = "Ah, sí, el asedio de Kinshra fue realmente un asunto reñido.",
    ["All hope seemed lost. Then she returned - Kara-Meir - with Sir Theodore at her side."] = "Toda esperanza parecía perdida. Luego regresó - Kara-Meir - con Sir Theodore a su lado.",
    ["Sir Theodore? I haven't seen anyone of that name around here."] = "¿Señor Theodore? No he visto a nadie con ese nombre por aquí.",
    ["No, you wouldn't have. He is...no longer with us."] = "No, no lo habrías hecho. Él... ya no está con nosotros.",
    ["Oh, I'm sorry."] = "Oh, lo siento.",
    ["So am I, young [man/woman]. So am I."] = "Yo también, joven [man/woman]. Yo también.",
    ["It's a glorious time for the White Knights - Saradomin has returned!"] = "Es una época gloriosa para los Caballeros Blancos: ¡Saradomin ha regresado!",
    ["He is defending us from the evil wizardry of Zamorak west of Lumbridge castle, and he's asked our order for help!"] = "¡Nos está defendiendo de la malvada hechicería de Zamorak al oeste del castillo Lumbridge y nos ha pedido ayuda a nuestra orden!",
    ["So it is the duty of all White Knights to heed the call, and take up arms against the ancient enemy."] = "Así que es deber de todos los Caballeros Blancos atender el llamado y tomar las armas contra el antiguo enemigo.",
    ["By the grace of Saradomin, we shall be victorious!"] = "¡Por la gracia de Saradomin, saldremos victoriosos!",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal] o [Animal].",
    ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
    ["If you complete this, I'll give you : Some White knight armour x 15. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: 15 armaduras de caballero blanco. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["For completing this request you've received Brassica primer x 3."] = "Por completar esta solicitud, recibió 3 imprimadores para Brassica.",
    ["[You've received : [Reward] x 15 And 13,750 farming reputation.]"] = "[Has recibido: [Reward] x 15 Y 13,750 reputación agrícola.]",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["A new request will be available in [time]"] = "Una nueva solicitud estará disponible en [time]",
    ["Which animal would you like to hand in?"] = "¿Qué animal te gustaría entregar?",
    ["You've already completed this request, there will be a new weekly request in [time]"] = "Ya has completado esta solicitud, habrá una nueva solicitud semanal en [time]",
    ["Hi! Sir Atcha service."] = "¡Hola! Servicio Sir Atcha.",
    ["I think you missed a couple of words there."] = "Creo que te perdiste un par de palabras.",
    ["You got my meaning. Gotta save time. Archaeology is a fast-paced business."] = "Entiendes lo que quiero decir. Hay que ahorrar tiempo. Archaeology es un negocio de ritmo rápido.",
    ["It really isn't..."] = "Realmente no lo es...",
    ["How can I be of service, good person?"] = "¿En qué puedo servirle, buena persona?",
    ["**Select An Option**"] = "**Seleccione una opción**",
    ["I'm Sir Atcha, a White Knight, of course. My role is something of a mix of a scholar, scribe, quartermaster and general dogsbody."] = "Soy Sir Atcha, un Caballero Blanco, por supuesto. Mi papel es una especie de mezcla de erudito, escriba, intendente y cuerpo de perro en general.",
    ["What rank are you?"] = "¿Qué rango tienes?",
    ["Oh, I'm just an initiate! I signed up to the White Knights after the Battle of Lumbridge, and I've worked hard to achieve my rank. Before this, I used to work as a clerk at Varrock Museum, which is why I've been given the honour of collecting Saradominist artefacts."] = "¡Oh, solo soy un iniciado! Me inscribí en los Caballeros Blancos después de la Batalla de Lumbridge y trabajé duro para alcanzar mi rango. Antes de esto, trabajaba como empleado en el Museo Varrock, razón por la cual tengo el honor de coleccionar artefactos saradoministas.",
    ["Saradomin himself has taken a personal interest in my work; can you believe it? I hope I don't mess up."] = "El propio Saradomin se ha interesado personalmente por mi trabajo; ¿puedes creerlo? Espero no equivocarme.",
    ["Want to look at my collections or just talk about them?"] = "¿Quieres ver mis colecciones o simplemente hablar sobre ellas?",
    ["**What would you like to do?**"] = "**¿Qué te gustaría hacer?**",
    ["I'm collecting anything Saradominist, of course! Right now, that means whatever you find at Everlight. Saradomin took the loss of Everlight harshly, so I'm told. It's not something he speaks about, though."] = "¡Estoy coleccionando cualquier cosa saradominista, por supuesto! En este momento, eso significa todo lo que encuentres en Everlight. Saradomin tomó con dureza la pérdida de Everlight, según me han dicho. Aunque no es algo de lo que él hable.",
    ["Padomenes - he's really cool - also has a vested interest in my finds. He used to live there, I think, or he had family that did? Maybe he's after something specific, I don't know."] = "Padomenes - es realmente genial - también tiene un gran interés en mis hallazgos. Creo que solía vivir allí, ¿o tenía familia que vivía allí? Tal vez busque algo específico, no lo sé.",
    ["How do you feel knowing that the person managing Everlight is a vampyre? How does Saradomin feel about that?"] = "¿Cómo te sientes al saber que la persona que gestiona Everlight es un vampyre? ¿Cómo se siente Saradomin al respecto?",
    ["I mean, it's weird, I know, but she seems cool. A little mean and curt at times, so I've heard, but she hasn't eaten anyone yet!"] = "Quiero decir, es raro, lo sé, pero ella parece genial. Un poco mala y brusca a veces, según he oído, ¡pero todavía no se ha comido a nadie!",
    ["And besides, Queen Efaritay is at Everlight too. She just doesn't like staying at that site for personal reasons. I get that."] = "Y además, Queen Efaritay también está en Everlight. Simplemente no le gusta quedarse en ese sitio por motivos personales. Lo entiendo.",
    ["Saradomin hasn't really said anything about it. Not to me, anyway, but then, I am just a novice. If he had an issue with the Efaritay-Vanescula alliance, I'd probably have heard at least something..."] = "Saradomin realmente no ha dicho nada al respecto. Para mí no, al menos, pero claro, sólo soy un novato. Si tuviera un problema con la alianza Efaritay-Vanescula, probablemente habría escuchado al menos algo...",
    ["Oh, right, cool! I've been authorised to trade a few relics in return for completing my collections."] = "Ah, claro, ¡genial! Me autorizaron a intercambiar algunas reliquias a cambio de completar mis colecciones.",
    ["I have...wait for it...a lock of hair! Wait, don't go! It's special, from a reliquary. It was taken from the wife of Dharok as a keepsake."] = "Tengo...espéralo...¡un mechón de pelo! ¡Espera, no te vayas! Es especial, de un relicario. Se lo quitó a la esposa de Dharok como recuerdo.",
    ["If you combine it with an amulet of the forsaken, I think the two things combined will give you some berserker-level strength."] = "Si lo combinas con un amuleto de los desamparados, creo que las dos cosas combinadas te darán algo de fuerza de nivel berserker.",
    ["Well, I already traded you that lock of hair from Dharok's betrothed. If you combine it with an amulet of the forsaken, that should make for a powerful relic!"] = "Bueno, ya te cambié ese mechón de pelo del prometido de Dharok. Si lo combinas con un amuleto de los abandonados, ¡debería convertirse en una reliquia poderosa!",
    ["About that..."] = "Sobre eso...",
    ["I gotcha, have another lock!"] = "¡Te tengo, ten otro candado!",
    ["Take lock of hair from Sir Atcha?"] = "¿Coger mechón de pelo de Sir Atcha?",
    ["Right, yes, I should do that..."] = "Cierto, sí, debería hacer eso...",
    ["And it did just that! Thank you."] = "¡Y eso fue precisamente lo que hizo! Gracias.",
    ["For my second and third collections, you can have...a couple of tetracompass pieces! I hope you find these things worthwhile! I'm sure they have value; you'll figure it out."] = "Para mi segunda y tercera colección, puedes tener... ¡un par de piezas de tetracompass! ¡Espero que estas cosas te parezcan útiles! Estoy seguro de que tienen valor; lo resolverás.",
    ["Ooh, I have a hat!"] = "¡Oh, tengo un sombrero!",
    ["Okay..."] = "Está bien...",
    ["It's a magic hat! It's called Petasos. Makes you gather stuff faster!"] = "¡Es un sombrero mágico! Se llama Petasos. ¡Te hace recolectar cosas más rápido!",
    ["You don't use it, do you? Because if so, you're not convincing me it works."] = "No lo usas, ¿verdad? Porque si es así no me estás convenciendo de que funcione.",
    ["I don't get it..."] = "No lo entiendo...",
    ["Not to worry. Learning gathering skills faster sounds pretty handy, thank you."] = "No te preocupes. Aprender habilidades de recolección más rápido suena bastante útil, gracias.",
    ["Is that Petasos hat speeding up your gathering, Player? I bet you go like a flash now!"] = "¿Ese sombrero de Petaso está acelerando tu reunión, Player? ¡Apuesto a que ahora te vas como un rayo!",
    ["Ooh, plus there's always chronotes for all of my collections!"] = "¡Oh, además siempre hay cronotas para todas mis colecciones!",
    ["Oh, and one last tip! Reldo - Varrock Palace's resident librarian - has expressed interest in something called a Dominarian device. My guess is if you deliver a restored one to him, you'd get something of value in return..."] = "¡Ah, y un último consejo! Reldo, bibliotecario residente del Palacio Varrock, ha expresado interés en algo llamado dispositivo Dominariano. Supongo que si le entregas uno restaurado, obtendrás algo de valor a cambio...",
    ["K'atcha later!"] = "¡K'atcha más tarde!",
    ["Zamorak's forces have this part of the city in an iron grip. We've been fighting hard, but no luck breaking through."] = "Las fuerzas de Zamorak tienen esta parte de la ciudad bajo control. Hemos estado luchando duro, pero no hemos tenido suerte para salir adelante.",
    ["We've made a couple of pushes so far, but after that last time..."] = "Hemos hecho un par de intentos hasta ahora, pero después de la última vez...",
    ["I can't risk my troops on another assault - not after so many casualties."] = "No puedo arriesgar a mis tropas en otro asalto, no después de tantas bajas.",
    ["Well, now I'm here. And I'm ready to tip the scales."] = "Bueno, ahora estoy aquí. Y estoy listo para inclinar la balanza.",
    ["I was hoping you'd say that."] = "Esperaba que dijeras eso.",
    ["You've done so much, World Guardian. I can't come with you, but I'd like to help."] = "Has hecho mucho, Guardián Mundial. No puedo ir contigo, pero me gustaría ayudarte.",
    ["It's not much, but I'll happily give you all the information I have. Anything you'd like to know before you head in?"] = "No es mucho, pero con gusto te daré toda la información que tengo. ¿Algo que quieras saber antes de entrar?",
    ["World Guardian. How goes the fight?"] = "Guardián Mundial. ¿Cómo va la pelea?",
    ["Why are we fighting against Zamorak?"] = "¿Por qué luchamos contra Zamorak?",
    ["It's all highly classified stuff, so I don't know everything. I can tell you what we troops on the ground know."] = "Son cosas altamente clasificadas, así que no lo sé todo. Puedo decirles lo que sabemos las tropas en el terreno.",
    ["Back when we were fighting the lackeys of the Elder Gods on the four fronts in Senntisten, the gods were stopping the Elder Gods' eggs from hatching."] = "Cuando luchábamos contra los lacayos de los Dioses Mayores en los cuatro frentes de Senntisten, los dioses impedían que los huevos de los Dioses Mayores eclosionaran.",
    ["That included Zamorak. We knew it'd only be a matter of time before he betrayed the other gods, and sure enough - he upped and left at the first opportunity."] = "Eso incluía a Zamorak. Sabíamos que solo sería cuestión de tiempo antes de que traicionara a los otros dioses y, efectivamente, se levantó y se fue en la primera oportunidad.",
    ["Somehow, the world was saved - not totally clear on how that happened, but no complaints."] = "De alguna manera, el mundo se salvó; no está del todo claro cómo sucedió, pero no hay quejas.",
    ["Now, though, Zamorak's back with an all-out offensive against our cities. My guess is he thinks he can establish a foothold while we're recovering from the war."] = "Ahora, sin embargo, Zamorak ha vuelto con una ofensiva total contra nuestras ciudades. Supongo que cree que puede establecer un punto de apoyo mientras nos recuperamos de la guerra.",
    ["He's got another thing coming."] = "Tiene otra cosa por venir.",
    ["Why are we attacking this part of Senntisten?"] = "¿Por qué atacamos esta parte de Senntisten?",
    ["Simple answer is 'Orders, straight from Commander Zilyana herself'. That's enough for me."] = "La respuesta simple es 'Órdenes, directamente de la propia comandante Zilyana'. Eso es suficiente para mí.",
    ["As for why she'd send us to this demon-infested pit... Well, I can only speculate."] = "En cuanto a por qué nos enviaría a este pozo infestado de demonios... Bueno, sólo puedo especular.",
    ["We know that Zamorak's holed up far to the north, summoning all manner of nasty things from the planes beyond."] = "Sabemos que Zamorak está escondido muy al norte, convocando todo tipo de cosas desagradables desde los planos más allá.",
    ["He's hiding behind a giant magical shield, and from what I've heeard, no-one's getting past it. Not even the other gods."] = "Se esconde detrás de un escudo mágico gigante y, por lo que he oído, nadie podrá atravesarlo. Ni siquiera los otros dioses.",
    ["As for this place... Intelligence is that it used to be a sort of slum where Avernic demons lived. Seems they've settled back in - just like old times."] = "En cuanto a este lugar... La inteligencia es que solía ser una especie de barrio pobre donde vivían los demonios Avernic. Parece que se han vuelto a instalar, como en los viejos tiempos.",
    ["Now, in my experience, demons'll use a fiery portal to go to the shops for some bread. So there's every chance they've got a shortcut here...straight back to Zamorak's HQ."] = "Ahora, según mi experiencia, los demonios usan un portal de fuego para ir a las tiendas a comprar pan. Así que hay muchas posibilidades de que tengan un atajo aquí... directamente a la sede de Zamorak.",
    ["If you ask me - and you did - that's why we're here. The Commander's got every battle-ready White Knight checking for potential routes behind enemy lines."] = "Si me preguntas, y lo hiciste, es por eso que estamos aquí. El Comandante tiene a todos los Caballeros Blancos listos para la batalla buscando rutas potenciales detrás de las líneas enemigas.",
    ["She must be hoping that one of us'll get lucky, and find a back door to Big Red himself."] = "Debe estar esperando que uno de nosotros tenga suerte y encuentre una puerta trasera para el mismísimo Big Red.",
    ["Who are these Zamorakians?"] = "¿Quiénes son estos zamorakianos?",
    ["The way the mages tell it, the demons are Avernic - a former slave race who were liberated by Zamorak way back when."] = "Según lo cuentan los magos, los demonios son Avernic, una antigua raza esclava que fue liberada por Zamorak hace mucho tiempo.",
    ["To them, he's a hero. And they'd do anything to protect their master."] = "Para ellos, él es un héroe. Y harían cualquier cosa para proteger a su amo.",
    ["As for the humans... The few we've captured ranted about the , or the 'Chaos Sisters'. Demons cults, no doubt."] = "En cuanto a los humanos... Los pocos que hemos capturado despotricaron sobre las , o las 'Hermanas del Caos'. Cultos de demonios, sin duda.",
    ["See, demons I get. They're evil. It's kind of what they do."] = "Mira, tengo demonios. Son malvados. Es algo así como lo que hacen.",
    ["But for someone from Gielinor to willingly side with them. To actually let them in..."] = "Pero que alguien de Gielinor esté dispuesto a ponerse del lado de ellos. Para realmente dejarlos entrar...",
    ["Unforgivable."] = "Imperdonable.",
    ["How am I supposed to defeat a god?"] = "¿Cómo se supone que debo derrotar a un dios?",
    ["I was kind of hoping you had an idea on that one."] = "Esperaba que tuvieras una idea al respecto.",
    ["In my opinion? No one has a chance of beating Zamorak in a straight fight."] = "¿En mi opinión? Nadie tiene posibilidades de vencer a Zamorak en una pelea directa.",
    ["The legends we were told as kids said that he was first banished with a great ritual. What was it...Edicts of Guthix?"] = "Las leyendas que nos contaban cuando éramos niños decían que primero fue desterrado con un gran ritual. ¿Qué fueron... los Edictos de Guthix?",
    ["Someone'd need to learn how to cast that ritual, find their way to Zamorak, then set up the ritual and banish him forever."] = "Alguien tendría que aprender a realizar ese ritual, encontrar el camino hacia Zamorak, luego configurar el ritual y desterrarlo para siempre.",
    ["All without being pummelled into the dust by a god."] = "Todo sin que un dios te convierta en polvo.",
    ["Well, I'd hate to be that person!"] = "Bueno, ¡odiaría ser esa persona!",
    ["Oh. I guess you...are the World Guardian."] = "Ah. Supongo que tú... eres el Guardián Mundial.",
    ["Zamorak won't be able to use his full god powers. That could give me a chance."] = "Zamorak no podrá usar todos sus poderes divinos. Eso podría darme una oportunidad.",
    ["Look, for what it's worth... We're all with you. Every step of the way."] = "Mira, por si sirve de algo... Estamos todos contigo. Cada paso del camino.",
    ["What happened during your last offensive?"] = "¿Qué pasó durante tu última ofensiva?",
    ["Our orders are to push into the heart of the city and hold our ground. Last time... We almost thought we'd made it."] = "Nuestras órdenes son avanzar hacia el corazón de la ciudad y mantenernos firmes. La última vez... casi pensamos que lo habíamos logrado.",
    ["We started strong. These demons are elites - the most savage and wicked of their kind. But demons don't scare us."] = "Empezamos fuerte. Estos demonios son élites, los más salvajes y malvados de su especie. Pero los demonios no nos asustan.",
    ["Our losses were heavy, but so were theirs. We were taking ground - and holding it."] = "Nuestras pérdidas fueron grandes, pero también lo fueron las de ellos. Estábamos ganando terreno y manteniéndolo.",
    ["But then...we reached the jail."] = "Pero entonces... llegamos a la cárcel.",
    ["The jail?"] = "¿La cárcel?",
    ["We got careless. It seemed unguarded - quiet even. Buoyed by our success, we stormed right in."] = "Nos descuidamos. Parecía desprotegido, incluso silencioso. Animados por nuestro éxito, entramos en acción.",
    ["It didn't occur to us that even the demons were afraid to go in there."] = "No se nos ocurrió que incluso los demonios tenían miedo de entrar allí.",
    ["It was a trap. As we broke into the atrium of the building, firebombs powered by dark magic fell upon us."] = "Fue una trampa. Cuando irrumpimos en el atrio del edificio, cayeron sobre nosotros bombas incendiarias impulsadas por magia oscura.",
    ["As the flames subsided, cowled brutes poured from the cells, laughing as they clubbed my screaming troops into submission."] = "Cuando las llamas se apagaron, brutos encapuchados salieron de las celdas, riéndose mientras golpeaban a mis tropas que gritaban hasta someterlas.",
    ["The biggest of them - a great, sinewy brute with a mace the size of a sledgehammer - shouted to me as I pulled the survivors out."] = "El más grande de ellos, un bruto enorme y nervudo con una maza del tamaño de un mazo, me gritó mientras sacaba a los supervivientes.",
    ["He...thanked me. For the 'fresh meat'. No doubt my knights were dragged away to be sacrificed in their rituals."] = "Él... me agradeció. Para la 'carne fresca'. Sin duda, mis caballeros fueron arrastrados para ser sacrificados en sus rituales.",
    ["As I've said, demons we can handle. But for real depravity... Look no further than humans."] = "Como he dicho, los demonios podemos manejarlos. Pero para la verdadera depravación... no busques más que los humanos.",
    ["I'm so sorry. Rest assured that if I meet this jailer, he'll pay."] = "Lo siento mucho. Tenga la seguridad de que si me encuentro con este carcelero, él pagará.",
    ["Just...be careful, World Guardian. We can't afford to lose you."] = "Sólo... ten cuidado, Guardián Mundial. No podemos darnos el lujo de perderte.",
    ["[Back...]"] = "[Atrás...]",
    ["Saradomin's Light go with you, my friend."] = "La Luz de Saradomin va contigo, amigo mío.",
    ["Sir Desmond Wellingtons, Knight Commander of the Order of Bear Explorers, and Quartermaster of the Queen of Snow's Royal Guard at your service!"] = "¡Sir Desmond Wellingtons, Caballero Comandante de la Orden de los Osos Exploradores e Intendente de la Guardia Real de Queen of Snow a su servicio!",
    ["Sir Desmond straightens his neck, in what you assume would be a salute if his four paws were not being used for standing."] = "Sir Desmond endereza el cuello, en lo que supones sería un saludo si sus cuatro patas no estuvieran siendo utilizadas para estar de pie.",
    ["And what brings a gentlebear of your stature to this place?"] = "¿Y qué trae a un caballero de tu talla a este lugar?",
    ["Important work as always. Here to bring cheer and goodwill on behalf of the Queen. We are in tough times at the moment, and Her Highness doesn't want to give Gielinor the cold shoulder. It might just finish everyone off, eh?"] = "Trabajo importante como siempre. Aquí para traer alegría y buena voluntad en nombre de la Reina. Estamos en tiempos difíciles en este momento, y Su Alteza no quiere darle la espalda a Gielinor. Podría acabar con todos, ¿eh?",
    ["A surprisingly warm sentiment from a queen of ice!"] = "¡Un sentimiento sorprendentemente cálido de una reina del hielo!",
    ["Well, in that vein, I've drawn up battle plans to give us all a chance to strike cheer into the hearts of our fellow bears. I have designated this Operation Secret Santa!"] = "Bueno, en ese sentido, he elaborado planes de batalla para darnos a todos la oportunidad de infundir alegría en los corazones de nuestros compañeros osos. ¡He designado esta Operación Papá Noel Secreto!",
    ["Can you tell me about the Secret Santa?"] = "¿Puedes hablarme sobre el Santa Secreto?",
    ["Happy to, happy to! There are two phases to Operation Secret Santa. Phase one: Donate. Kindly individuals can donate their hard-earned items into my care. I will distribute them in phase two. Mind you, we don't want any tat, so there is a minimum donation value. Whatever you give must be worth at least 10,000 coins on the Grand Exchange. I've got special rewards too - for anyone going beyond the call of duty. Each day I can give you a medium prismatic lamp for donations totalling 100,000 coins in value. If you do this 15 times, I can bestow you with the title of Secret Santa! There are also special honours for anyone who donates 200,000,000 coins worth in one fell swoop: the title of Top Secret Santa! Phase two: Gift. Anyone can ask me for a present, and I will randomly select an item from my stores to give them. Don't get greedy though, eh? I'll only let you take a gift once every 2 hours. That's the plan. Should be a jolly good time."] = "¡Feliz, feliz! Hay dos fases en la Operación Secret Santa. Fase uno: Donar. Las personas amables pueden donar los artículos que tanto les costó ganar a mi cuidado. Los distribuiré en la fase dos. Eso sí, no queremos ningún tatuaje, por lo que hay un valor mínimo de donación. Todo lo que des debe valer al menos 10.000 coins en Grand Exchange. También tengo recompensas especiales para cualquiera que vaya más allá del cumplimiento del deber. Cada día puedo regalarles una lámpara prismática mediana por donaciones por un valor total de 100.000 coins. ¡Si haces esto 15 veces, puedo otorgarte el título de Papá Noel Secreto! También hay honores especiales para cualquiera que done 200.000.000 coins de una sola vez: ¡el título de Top Secret Santa! Fase dos: Regalo. Cualquiera puede pedirme un regalo y seleccionaré aleatoriamente un artículo de mis tiendas para entregárselo. Pero no te pongas codicioso, ¿eh? Sólo te dejaré recibir un regalo una vez cada 2 horas. Ese es el plan. Debería ser un buen momento.",
    ["I'd like to donate to the Secret Santa."] = "Me gustaría hacer una donación al Santa Secreto.",
    ["Bally sporting of you, bally sporting indeed!"] = "¡Qué muy divertido de tu parte, muy divertido de verdad!",
    ["As an Ironman you cannot partake in the greatest joy of all - gift giving. All donations from Ironmen will be destroyed in a controlled explosion in accordance with standard Ironman rules of engagement. Any remaining residue will be destroyed in a second, larger, explosion. Your wealth will not be transferred to other players, but you will be able to receive cosmetic titles for your donations, and progress for related yak track tasks."] = "Como Ironman no puedes participar de la mayor alegría de todas: dar regalos. Todas las donaciones de Ironmen serán destruidas en una explosión controlada de acuerdo con las reglas de enfrentamiento estándar de Ironman. Cualquier residuo restante será destruido en una segunda explosión, más grande. Tu riqueza no se transferirá a otros jugadores, pero podrás recibir títulos cosméticos por tus donaciones y progreso en tareas relacionadas con la pista de yak.",
    ["Would you still like to donate items?"] = "¿Aún te gustaría donar artículos?",
    ["Yes and don't ask me again."] = "Sí y no me vuelvas a preguntar.",
    ["I'd like to claim a gift from the Secret Santa."] = "Me gustaría reclamar un regalo del Papá Noel secreto.",
    ["State your name and rank and I'll check if I have anything for you."] = "Di tu nombre y rango y comprobaré si tengo algo para ti.",
    ["If you log out, items in the reward chest will be moved to your inventory or bank. If both of those places are full you will lose the items."] = "Si cierras sesión, los artículos del cofre de recompensas se moverán a tu inventario o banco. Si ambos lugares están llenos, perderás los artículos.",
    ["*(If the player has claimed a gift in the last 2 hours:)*"] = "*(Si el player ha reclamado un regalo en las últimas 2 horas:)*",
    ["Can you tell me about my daily reward progress?"] = "¿Puedes contarme sobre el progreso de mi recompensa diaria?",
    ["You need to donate items totalling at least a value of [number] coins to recieve a daily reward. You need to donate enough to claim a daily reward on [number] more days to receive the Secret Santa title."] = "Debes donar artículos por un valor total de al menos [número] coins para recibir una recompensa diaria. Debes donar lo suficiente para reclamar una recompensa diaria en [número] días más para recibir el título de Secret Santa.",
    ["You have donated enough wealth to receive your daily reward today. If you haven't collected it from me you can claim it like you would claim a standard Secret Santa gift."] = "Has donado suficiente riqueza para recibir tu recompensa diaria hoy. Si no lo has recibido de mí, puedes reclamarlo como reclamarías un regalo estándar de Secret Santa.",
    ["You need to donate enough to claim a daily reward on [number] more days to receive the Secret Santa title."] = "Debes donar lo suficiente para reclamar una recompensa diaria en [número] días más para recibir el título de Papá Noel Secreto.",
    ["You have donated items of high enough value on enough days to receive the Secret Santa title already."] = "Has donado artículos de valor suficiente en suficientes días para recibir el título de Papá Noel Secreto.",
    ["Good morrow sirrah/madam!"] = "¡Buenos días señor/señora!",
    ["Morning. Know where an adventurer has to go to find a quest around here?"] = "Buenos días. ¿Sabes dónde tiene que ir un aventurero para encontrar una misión por aquí?",
    ["An adventurer eh? There is no service finer than serving the bountiful King Arthur, and I happen to know there's an important quest to fulfill."] = "Un aventurero, ¿eh? No hay mejor servicio que servir al generoso King Arthur, y sé que hay una misión importante que cumplir.",
    ["Sir Knight! Many thanks for your assistance in restoring Merlin to his former freedom!"] = "¡Señor Caballero! ¡Muchas gracias por su ayuda para devolverle a Merlín su antigua libertad!",
    ["Hey, no problem."] = "Oye, no hay problema.",
    ["We owe you a great debt for freeing us from that dungeon."] = "Tenemos una gran deuda contigo por liberarnos de esa mazmorra.",
    ["Awww, shucks. It was nothing."] = "Awww, caray. No fue nada.",
    ["Greetings, Sir Kay. I have completed all of the hard tasks in the Seer's Village set. May I have a reward?"] = "Saludos, Sir Kay. He completado todas las tareas difíciles del set Village de Seer. ¿Puedo tener una recompensa?",
    ["I would love to, but you will need to bring me your seer's headband after you have received the rewards for the Easy and Medium tasks."] = "Me encantaría, pero tendrás que traerme tu diadema de vidente después de haber recibido las recompensas por las tareas Fácil y Media.",
    ["Okay, well, I'd better get busy then."] = "Está bien, bueno, entonces será mejor que me ponga a trabajar.",
    ["That's the spirit, young man."] = "Ese es el espíritu, joven.",
    ["Well done, young sir. You must be a mighty adventurer indeed to have completed the Hard Tasks."] = "Bien hecho, joven señor. Debes ser un gran aventurero para haber completado las tareas difíciles.",
    ["You hand Sir Kay your headband and he concentrates for a moment. Some mysterious knightly energy passes through his hands and he gives the headband back to you, along with an old lamp."] = "Le entregas a Sir Kay tu diadema y él se concentra por un momento. Una misteriosa energía caballeresca pasa por sus manos y te devuelve la diadema, junto con una lámpara vieja.",
    ["While wearing it, 'Flax' will give you 840 flax per week, he will make you faster at spinning, you'll be able to see better in the dark and both your Prayer and defence against magic attacks will be boosted."] = "Mientras lo uses, 'Flax' te dará 840 flax por semana, te hará girar más rápido, podrás ver mejor en la oscuridad y tanto tu Prayer como tu defensa contra ataques mágicos mejorarán.",
    ["Stankers will allow 308 pieces of coal in his coal truck, and you'll get bonuses when cutting maple and normal trees."] = "Stankers permitirá 308 piezas de carbón en su camión de carbón y obtendrás bonificaciones al cortar arces y árboles normales.",
    ["I'm not finished! Your Camelot Teleport spell can be switched to Seers' Village and Thormac will lower his prices somewhat. Phew! Oh, and how could I forget - you'll get a bonus when you use the altar in the chapel here, but you don't need to wear the headband for that."] = "¡No he terminado! Tu hechizo Camelot Teleport se puede cambiar a Seers' Village y Thormac reducirá un poco sus precios. ¡Uf! Ah, y ¿cómo podría olvidarlo? Obtendrás una bonificación cuando uses el altar en la capilla aquí, pero no necesitas usar la diadema para eso.",
    ["Thank you, Sir Kay. I'll try not to harm anyone with my spinning."] = "Gracias, Sir Kay. Intentaré no dañar a nadie con mi giro.",
    ["You are most welcome. You may also find that the Lady of the Lake is prepared to reward you for your services if you wear the headband in her presence."] = "De nada. También puedes descubrir que the Lady of the Lake está preparado para recompensarte por tus servicios si usas la diadema en su presencia.",
    ["Greetings, Sir Kay. I have completed all of the Elite Tasks in the Seer's Village set. May I have a reward?"] = "Saludos, Sir Kay. He completado todas las tareas de élite del conjunto Village de Seer. ¿Puedo tener una recompensa?",
    ["Well done, young sir. You must be an awesome adventurer indeed to have completed the Elite Tasks."] = "Bien hecho, joven señor. Debes ser un aventurero increíble para haber completado las tareas de élite.",
    ["You hand Sir Kay your headband and he concentrates for a moment. Some mysterious knightly energy passes through his hands and he gives the headband back to you, along with a few old lamps."] = "Le entregas a Sir Kay tu diadema y él se concentra por un momento. Una misteriosa energía caballeresca pasa por sus manos y te devuelve la diadema, junto con algunas lámparas viejas.",
    ["Flax' will give you 200 flax per day, Stankers will ship 200 of your mined coal back to the bank, and you may find your skills with a crossbow and those fantastic enchanted bolts is improved."] = "Flax' te dará 200 lino por día, Stankers enviará 200 de tu carbón extraído al banco, y es posible que mejores tus habilidades con la ballesta y esos fantásticos pernos encantados.",
    ["Ah, and you may find Excalibur is further enhanced. Thank you for your work around the area."] = "Ah, y es posible que descubras que Excalibur está aún más mejorada. Gracias por su trabajo en la zona.",
    ["Thank you, Sir Kay."] = "Gracias, Sir Kay.",
    ["You are most welcome."] = "De nada.",
    ["Where is the headband that I gave you, Player?"] = "¿Dónde está la diadema que te regalé, Player?",
    ["I've lost it."] = "Lo he perdido.",
    ["Luckily, I have a spare headband that you can have."] = "Por suerte, tengo una diadema de repuesto que puedes tener.",
    ["[Sir Kay hands you a seer's headband.]"] = "[Sir Kay te entrega una diadema de vidente.]",
    ["To claim your Seers' Village set rewards, speak to any seer in the village, Stankers out west by the coal trucks, or myself."] = "Para reclamar las recompensas del conjunto Seers' Village, habla con cualquier vidente de la aldea, con Stankers en el oeste, junto a los camiones de carbón, o conmigo mismo.",
    ["Toggle Watchtower Teleport to [Seers' Village/Camelot]?"] = "¿Alternar teletransporte de Watchtower a [Seers' Village/Camelot]?",
    ["Watchtower Teleport will now teleport you to the [Seers' Village/to the gates of Camelot]."] = "Watchtower Teleport ahora te teletransportará al [Seers' Village/to the gates of Camelot].",
    ["[Sir Kay has given you your next clue scroll.]"] = "[Sir Kay te ha dado tu siguiente pergamino de pistas.]",
    ["A valiant effort!"] = "¡Un esfuerzo valiente!",
    ["Greetings! I am Sir Lancelot, the greatest Knight in the land! What do you want? Humph. You are indeed a better knight than I first suspected."] = "¡Saludos! ¡Soy Sir Lancelot, el Caballero más grande del país! ¿Qué deseas? Humph. De hecho, eres mejor caballero de lo que sospeché al principio.",
    ["Gee, it was nothing saving you all from the clutches of Morgan Le Faye and freeing your King."] = "Vaya, no fue nada salvarlos a todos de las garras de Morgan Le Faye y liberar a su Rey.",
    ["Greetings, Hero. Achiettes told me you'd passed her tests and been accepted into the guild. I remember how proud I was when I gained my guild membership."] = "Saludos, héroe. Achiettes me dijo que pasaste sus pruebas y fuiste aceptada en el gremio. Recuerdo lo orgulloso que estaba cuando obtuve mi membresía en el gremio.",
    ["You're a member of an exclusive order now. I hope you will remember to use your skills selflessly. As a hero, you have a solemn responsibility to fight on the side of good against evil."] = "Ahora eres miembro de un pedido exclusivo. Espero que recuerdes usar tus habilidades desinteresadamente. Como héroe, tienes la solemne responsabilidad de luchar del lado del bien contra el mal.",
    ["Father Aereck told me that you put a ghost in Lumbridge Graveyard to rest."] = "Father Aereck me dijo que pusiste a descansar un fantasma en el cementerio Lumbridge.",
    ["I wish you could have caught the warlock that desecrated that man's tomb. A person's mortal remains are sacred to Saradomin, and disturbing them is an unthinkable crime."] = "Ojalá hubieras podido atrapar al brujo que profanó la tumba de ese hombre. Los restos mortales de una persona son sagrados para Saradomin y perturbarlos es un crimen impensable.",
    ["Greetings, Dragon-slayer. Elvarg was a true monster. You've avenged a lot of people who died in her attack on Crandor."] = "Saludos, Asesino de dragones. Elvarg era un verdadero monstruo. Has vengado a mucha gente que murió en su ataque a Crandor.",
    ["I'm proud to count you as a fellow Champions' Guild member."] = "Estoy orgulloso de contarte como miembro de Champions' Guild.",
    ["Well met, Sir Knight. Sir Tiffy Cashien tells me that you're the newest member of our order."] = "Bien recibido, señor Caballero. Sir Tiffy Cashien me dice que eres el miembro más nuevo de nuestra orden.",
    ["I hope you appreciate the responsibility you have taken on. The Temple Knights have served Saradomin for longer than history remembers."] = "Espero que aprecies la responsabilidad que has asumido. Los Caballeros del Templo han servido a Saradomin durante más tiempo del que recuerda la historia.",
    ["Our choices are not easy. We must always keep the vision of Saradomin in our hearts and divine his will in every situation we face."] = "Nuestras elecciones no son fáciles. Siempre debemos mantener la visión de Saradomin en nuestro corazón y adivinar su voluntad en cada situación que enfrentemos.",
    ["So, you're the one who took down the Slug Queen? Sir Tiffy Cashien is singing your praises. It sounds like you're becoming one of the Temple Knights' best agents."] = "Entonces, ¿fuiste tú quien derrotó a Slug Queen? Sir Tiffy Cashien está cantando tus alabanzas. Parece que te estás convirtiendo en uno de los mejores agentes de los Caballeros del Templo.",
    ["Savant told me you finally took down Solus Dellagar. I'm very impressed."] = "Savant me dijo que finalmente derrotaste a Solus Dellagar. Estoy muy impresionado.",
    ["I was there at the Edgeville Incident - I saw first-hand what the 'murder mage' could do. I pray that we never see his like again."] = "Estuve allí en el incidente de Edgeville. Vi de primera mano lo que podía hacer el 'mago asesino'. Rezo para que nunca volvamos a ver algo así.",
    ["Your replica of Sir Vyvin's sword fooled everyone. Even Sir Amik had no idea that the sword was ever lost. Oh, don't worry how I found out. I have my sources, but your secret is safe with me."] = "Tu réplica de la espada de Sir Vyvin engañó a todos. Ni siquiera Sir Amik tenía idea de que la espada se hubiera perdido alguna vez. Oh, no te preocupes cómo me enteré. Tengo mis fuentes, pero tu secreto está a salvo conmigo.",
    ["Xenia told me about how you foiled a Zamorakian cult beneath Lumbridge Church. Congratulations."] = "Xenia me contó cómo frustraste un culto zamorakiano debajo de la iglesia Lumbridge. Felicidades.",
    ["Nowhere is safe from the servants of Zamorak. It makes me sick that they would try to desecrate a Saradominist church."] = "Ningún lugar está a salvo de los servidores de Zamorak. Me da asco que intenten profanar una iglesia saradominista.",
    ["You struck a powerful blow against the forces of evil when you destroyed the demon Nezikchened. Zamorak himself must be scared of you."] = "Asestaste un poderoso golpe a las fuerzas del mal cuando destruiste al demonio Nezikchened. El propio Zamorak debe tenerte miedo.",
    ["Your membership of the Legends' Guild is well deserved."] = "Su membresía en Legends' Guild es bien merecida.",
    ["So, Keldagrim has a king again, and I hear you were involved."] = "Entonces, Keldagrim tiene un rey nuevamente y escuché que estuviste involucrado.",
    ["The Temple Knights had files on the dwarven monarchy, but we had no indication that Veldaban had any royal blood. It's funny how things work out when an adventurer is involved."] = "Los Caballeros del Templo tenían archivos sobre la monarquía enana, pero no teníamos indicios de que Veldaban tuviera sangre real. Es curioso cómo suceden las cosas cuando interviene un aventurero.",
    ["I was sad to hear of Akrisae's fall. He was always so pious, so devout. That he could so easily succumb to dark magic is more than a little disconcerting. I guess his faith wasn't quite as strong as I thought."] = "Me entristeció enterarme de la caída de Akrisae. Siempre fue tan piadoso, tan devoto. Que pudiera sucumbir tan fácilmente a la magia oscura es más que un poco desconcertante. Supongo que su fe no era tan fuerte como pensaba.",
    ["Congratulations on your promotion, old bean."] = "Felicitaciones por tu ascenso, viejo.",
    ["Thank you, sir. It will be an honour to work with you."] = "Gracias, señor. Será un honor trabajar con usted.",
    ["Nonsense, young man! The honour is all mine. You come highly recommended by Sir Amik, you know. One of the bright lights of the White Knights. It won't be long before you're famous."] = "¡Tonterías, joven! El honor es todo mío. Vienes muy recomendado por Sir Amik, ¿sabes? Una de las luces brillantes de los Caballeros Blancos. No pasará mucho tiempo antes de que seas famoso.",
    ["I'm not after fame, sir. I only want to serve Saradomin. Becoming too well-known might get in the way."] = "No busco la fama, señor. Sólo quiero servir Saradomin. Volverse demasiado conocido podría ser un obstáculo.",
    ["I do believe you're completely sincere! Well, I'm sure you'll be famous in the Order, even if you're unknown outside it, what? I'm sure you have work to do, places to not be seen, and so forth. Toodle-pip!"] = "¡Creo que eres completamente sincero! Bueno, estoy seguro de que serás famoso en la Orden, aunque seas un desconocido fuera de ella, ¿qué? Estoy seguro de que tienes trabajo que hacer, lugares que no debes ver, etc. ¡Toodle-pip!",
    ["Greetings, [my friend/my lady]."] = "Saludos, [my friend/my lady].",
    ["Greetings. I saw strange lights hovering over this island. Do you know anything about it?"] = "Saludos. Vi luces extrañas flotando sobre esta isla. ¿Sabes algo al respecto?",
    ["The islanders were turned into crab people, but I took care of it."] = "Los isleños se convirtieron en cangrejos, pero yo me ocupé de ello.",
    ["I see. And I take it you are the one who defeated them? Well done!"] = "Ya veo. ¿Y supongo que fuiste tú quien los derrotó? ¡Bien hecho!",
    ["You are as courageous as you are beautiful, my lady...if I may be so bold."] = "Eres tan valiente como hermosa, mi señora... si se me permite ser tan atrevido.",
    ["Don't worry, everything is under control."] = "No te preocupes, todo está bajo control.",
    ["Can I ask you a question?"] = "¿Puedo hacerte una pregunta?",
    ["By all means."] = "Por supuesto.",
    ["[Menu]: Choose an option"] = "[Menú]: Elige una opción",
    ["Forgive me - I have neglected to introduce myself. My name is Sir Owen, Temple Knight and emissary of Saradomin. It is a pleasure to meet you, [my friend/my lady]."] = "Perdóneme. No me he presentado. Mi nombre es Sir Owen, Temple Knight y emisario de Saradomin. Es un placer conocerte, [my friend/my lady].",
    ["I was passing by on a ship when I saw an eerie light hanging in the sky."] = "Estaba pasando en un barco cuando vi una luz espeluznante colgando en el cielo.",
    ["Something about the phenomenon suggested an evil presence, so I asked the captain to drop anchor, and used a rowboat to make my way ashore."] = "Algo en el fenómeno sugería una presencia maligna, así que le pedí al capitán que echara anclas y usé un bote de remos para llegar a tierra.",
    ["Which, in a full suit of armour, was not an easy task."] = "Lo cual, con una armadura completa, no fue una tarea fácil.",
    ["Where did you come from?"] = "¿De dónde vienes?",
    ["Falador is my home, but I am often required to travel to different parts of Gielinor to advance Saradomin's cause."] = "Falador es mi hogar, pero a menudo debo viajar a diferentes partes de Gielinor para promover la causa de Saradomin.",
    ["As a Temple Knight, it is my sworn duty to defend the weak, protect the innocent, and confront evil wherever it asserts itself."] = "Como Caballero del Templo, es mi deber jurado defender a los débiles, proteger a los inocentes y enfrentar el mal dondequiera que se imponga.",
    ["Until we meet again, [my friend/my lady]."] = "Hasta que nos volvamos a encontrar, [my friend/my lady].",
    ["The mages must be protected! If the Arch-Glacor breaks free, we will lose this front!"] = "¡Los magos deben estar protegidos! ¡Si el Arch-Glacor se libera, perderemos este frente!",
    ["Greetings to the court of King Arthur! I am proud to have you as a member of the Round Table."] = "¡Saludos a la cancha de King Arthur! Estoy orgulloso de tenerle como miembro de la Mesa Redonda.",
    ["Hello, who are you?"] = "Hola, ¿quién eres?",
    ["I'm a mighty adventurer, who are you?"] = "Soy un poderoso aventurero, ¿quién eres tú?",
    ["I'm Sir Prysin, a bold and famous knight of the realm."] = "Soy Sir Prysin, un caballero del reino audaz y famoso.",
    ["I'm not sure, I was hoping you could tell me."] = "No estoy seguro, esperaba que pudieras decirme.",
    ["Well, I've never met you before."] = "Bueno, nunca te había conocido antes.",
    ["Though I see that you wield Silverlight. It seems that my ancestor's sword has found a new champion."] = "Aunque veo que empuñas Silverlight. Parece que la espada de mi antepasado ha encontrado un nuevo campeón.",
    ["**Sir Prysin:** I once sought to claim Silverlight. The spirits cared not for my inheritance, and judged my worth."] = "**Sir Prysin:** Una vez intenté reclamar Silverlight. A los espíritus no les importó mi herencia y juzgaron mi valor.",
    ["I was found wanting. Tell me. What trials did you face?"] = "Me encontré con falta. Dime. ¿Qué pruebas enfrentaste?",
    ["(Tell the truth.)"] = "(Diga la verdad).",
    ["I defeated a few skeletons, took a walk of faith across a chasm and answered some trivia questions."] = "Derroté a algunos esqueletos, caminé con fe a través de un abismo y respondí algunas preguntas de trivia.",
    ["(Exaggerate the trials.)"] = "(Exagera las pruebas.)",
    ["I fought a legion of undead...leapt a chasm of poisonous scorpions...and answered a series of devilish riddles and quadratic equations."] = "Luché contra una legión de muertos vivientes... salté un abismo de escorpiones venenosos... y respondí una serie de acertijos diabólicos y ecuaciones cuadráticas.",
    ["(Mock the trials)"] = "(burlarse de las pruebas)",
    ["I took a walk, had a chat and killed some things. I don't know how you could have failed."] = "Salí a caminar, charlé y maté algunas cosas. No sé cómo pudiste haber fallado.",
    ["**Sir Prysin:** What? That's all? What of the nine-headed serpent I was made to battle? The journey into the abyss to claim the Candelabrum of Invocation?"] = "**Sir Prysin:** ¿Qué? ¿Eso es todo? ¿Qué pasa con la serpiente de nueve cabezas contra la que fui obligado a luchar? ¿El viaje al abismo para reclamar el Candelabro de la Invocación?",
    ["And the less said about the medical examination, the better..."] = "Y cuanto menos se hable del reconocimiento médico, mejor...",
    ["Well, that was surprising."] = "Bueno, eso fue sorprendente.",
    ["I see that you wield Silverlight, though it has changed much since I last saw it. It seems my ancestor's sword has found a new champion."] = "Veo que manejas Silverlight, aunque ha cambiado mucho desde la última vez que lo vi. Parece que la espada de mi antepasado ha encontrado un nuevo campeón.",
    ["You've come to the right place, well done!"] = "Has venido al lugar correcto, ¡bien hecho!",
    ["[Sir Prysin has given you another clue scroll!]"] = "[¡Sir Prysin te ha dado otro pergamino de pistas!]",
    ["Whatever it is you're selling, I'm not interested."] = "Sea lo que sea lo que estás vendiendo, no me interesa.",
    ["I don't know how you've managed to get that sword so dirty after just one use. I know I'd take better care of it, but even though it's a family heirloom, I'm not worthy to wield it."] = "No sé cómo has conseguido ensuciar tanto esa espada después de un solo uso. Sé que lo cuidaría mejor, pero aunque es una reliquia familiar, no soy digno de empuñarlo.",
    ["About that, what happened with you and the trials?"] = "Sobre eso, ¿qué pasó contigo y las pruebas?",
    ["You should know - you've been through them too! Didn't you find them difficult? What trials did you face?"] = "Deberías saberlo: ¡tú también has pasado por ellos! ¿No te resultaron difíciles? ¿Qué pruebas enfrentaste?",
    ["What will you tell Sir Prysin about the trials?"] = "¿Qué le dirás a Sir Prysin sobre las pruebas?",
    ["Tell the truth"] = "decir la verdad",
    ["I sobered up a drunkard, aced a pop quiz and was pretty much just handed the third trial."] = "Dejé a un borracho sobrio, aprobé un examen sorpresa y prácticamente me aprobaron la tercera prueba.",
    ["What? Is that all? What of the twelve-headed hydra cat I was made to battle? The journey into Zemouregal's sock drawer to claim the Nightcap of Terror?"] = "¿Qué? ¿Eso es todo? ¿Qué pasa con el gato hidra de doce cabezas con el que me obligaron a luchar? ¿El viaje al cajón de los calcetines de Zemouregal para reclamar la copa del terror?",
    ["And that whole thing with the coughing I found VERY uncomfortable. I still have flashbacks about that."] = "Y todo eso de la tos me pareció MUY incómodo. I todavía tengo recuerdos de eso.",
    ["Exaggerate the trials"] = "Exagerar las pruebas",
    ["I performed an exorcism on a legendary vampyre hunter, after braving a dark cave that was home to a savage beast."] = "Realicé un exorcismo a un cazador legendario de vampyre, después de desafiar una cueva oscura que era el hogar de una bestia salvaje.",
    ["Then an animated grimoire posed me a raft of near impossible questions, all of which I had to answer."] = "Luego, un grimorio animado me planteó una serie de preguntas casi imposibles, todas las cuales tuve que responder.",
    ["Finally, I had to place my faith in another to guide me towards my future. I was entirely at their mercy."] = "Finalmente, tuve que depositar mi fe en otro para que me guiara hacia mi futuro. Estaba completamente a su merced.",
    ["Mock the trials"] = "Burlarse de las pruebas",
    ["I hassled a bunch of spirits until they were so annoyed with me that they just gave me the sword to get some peace and quiet."] = "Molesté a un grupo de espíritus hasta que se enojaron tanto conmigo que simplemente me dieron la espada para tener un poco de paz y tranquilidad.",
    ["How did you lose Darklight? You've got to be more careful with it - here."] = "¿Cómo perdiste a Darklight? Tienes que tener más cuidado con esto... aquí.",
    ["[You glibly dangle the Nightcap of Terror in front of Sir Prysin's face.]"] = "[Cuelgas con soltura el Nightcap of Terror frente a la cara de Sir Prysin.]",
    ["Sweet Saradomin...you claimed the Nightcap of Terror, and live to tell the tale. How is this possible?"] = "Dulce Saradomin... reclamaste la copa del terror y vives para contarlo. ¿Cómo es esto posible?",
    ["It wasn't difficult. I just had to purchase an extortionate zombie outfit, defeat undead warriors, collect the vapour from their necrotic flesh..."] = "No fue difícil. Sólo tenía que comprar un disfraz de zombi exorbitante, derrotar a guerreros no-muertos, recoger el vapor de su carne necrótica...",
    ["Endure a series of fetch quests to dye it orange, traffic in the criminal underworld to get a lockpick, and search through Zemouregal's junk in his study until I found it."] = "Soporta una serie de misiones para buscar dye en color naranja, trafica en el inframundo criminal para conseguir una ganzúa y busca entre los trastos de Zemouregal en su estudio hasta que lo encontré.",
    ["His study? So you didn't have to endure the...trial by underwear?"] = "¿Su estudio? Entonces, ¿no tuviste que soportar la... prueba de ropa interior?",
    ["Sorry, what?"] = "Lo siento, ¿qué?",
    ["Zemouregal's sock drawer. That's where they sent me. It was unspeakably vile. I dare not speak of it. You can't imagine the things I've seen."] = "Cajón de calcetines de Zemouregal. Ahí es donde me enviaron. Fue indescriptiblemente vil. No me atrevo a hablar de ello. No te imaginas las cosas que he visto.",
    ["The nether garments...the black silk and frilly lace... I'm grateful zombies don't need to sleep, for I dare never dream again."] = "Las prendas inferiores... la seda negra y el encaje con volantes... Agradezco que los zombis no necesiten dormir, porque no me atrevo a volver a soñar nunca más.",
    ["Halt, adventurer! Go no further! Mortal, wormy peril lies within this cave!"] = "¡Alto, aventurero! ¡No vayas más lejos! ¡Dentro de esta cueva se esconde un peligro mortal y lleno de gusanos!",
    ["Choose an Option:"] = "Elige una opción:",
    ["Wormy?"] = "¿Gusanero?",
    ["Wormy indeed! The most unsightly, ghastly and smelly worms you could imagine have suddenly risen from a hidden network of underground caves!"] = "¡Realmente gusano! ¡Los gusanos más desagradables, espantosos y malolientes que puedas imaginar han surgido repentinamente de una red oculta de cuevas subterráneas!",
    ["But fear not! We, the Falador White Knights, have been officially dispatched on a mission to deal with this slithering menace!"] = "¡Pero no temas! ¡Nosotros, los Caballeros Blancos de Falador, hemos sido enviados oficialmente en una misión para hacer frente a esta amenaza deslizante!",
    ["Can you tell me what's going on inside this cave?"] = "¿Puedes decirme qué está pasando dentro de esta cueva?",
    ["Well, you see, my unit was dispatched to secure the area after locals issued an alert. Giant worm creatures appeared, you see."] = "Bueno, verás, mi unidad fue enviada para asegurar el área después de que los lugareños emitieran una alerta. Aparecieron gusanos gigantes, ¿sabes?",
    ["I promptly matched in, did what needed to be done, and now the people are safe. We have successfully contained the creatures."] = "Rápidamente me uní, hice lo que había que hacer y ahora la gente está a salvo. Hemos contenido con éxito a las criaturas.",
    ["Have you actually been inside these caves?"] = "¿Has estado realmente dentro de estas cuevas?",
    ["Of course! We valiantly led a charge inside, followed by an immediate tactical retreat!"] = "¡Por supuesto! ¡Lideramos valientemente una carga hacia el interior, seguida de una retirada táctica inmediata!",
    ["Do not mistake this for running away, however. I simply called for a strategy meeting following slight losses."] = "Sin embargo, no confundas esto con huir. Simplemente convoqué una reunión estratégica tras ligeras pérdidas.",
    ["After all, losing 70% of one's fighting force makes one reconsider their situation!"] = "¡Después de todo, perder el 70% de la fuerza de combate te hace reconsiderar tu situación!",
    ["Thank you for your service, Sir Rebrum. I have to go now."] = "Gracias por su servicio, Sir Rebrum. Me tengo que ir ahora.",
    ["What can you tell me about the enemies inside?"] = "¿Qué puedes decirme sobre los enemigos que hay dentro?",
    ["Worms! Lots of them. They spit some kind of corrosive acid. We can handle the ones near the entrance."] = "¡Gusanos! Muchos de ellos. Escupen una especie de ácido corrosivo. Podemos encargarnos de los que están cerca de la entrada.",
    ["However, if you go further down the caves, you'll start meeting bigger ones with mandibles. They are no joke!"] = "Sin embargo, si profundizas en las cuevas, empezarás a encontrarte con cuevas más grandes y con mandíbulas. ¡No son ninguna broma!",
    ["By the way, I never reached the end of the caves myself, so who knows what's at the bottom."] = "Por cierto, nunca llegué al final de las cuevas, así que quién sabe qué hay en el fondo.",
    ["I have to go now."] = "Me tengo que ir ahora.",
    ["Who are you again?"] = "¿Quién eres tú otra vez?",
    ["I am the famous Sir Rebrum: hero of justice extraordinaire and destroyer of all things evil!"] = "Soy el famoso Sir Rebrum: ¡héroe de la justicia extraordinaria y destructor de todo lo malo!",
    ["I know you'd love to hear about all my adventures, but I'm on duty here."] = "Sé que te encantaría conocer todas mis aventuras, pero estoy de servicio aquí.",
    ["Don't worry, I eat peril for breakfast."] = "No te preocupes, como peligro en el desayuno.",
    ["Most impressive! Carry on, then."] = "¡Muy impresionante! Continúe entonces.",
    ["*(After Song from the Depths, if the player has destroyed their coral crossbow:)* Would you happen to have found a Coral Crossbow?"] = "*(Después de Song from the Depths, si el player ha destruido su ballesta de coral:)* ¿Habrías encontrado una ballesta de coral?",
    ["Why, yes I have! The Raptor passed by earlier. He said you might need it."] = "¡Sí, sí! The Raptor pasó antes. Dijo que podrías necesitarlo.",
    ["Come back when you're less encumbered and I'll give it to you."] = "Vuelve cuando estés menos agobiado y te lo daré.",
    ["[You receive the Coral Crossbow.]"] = "[Recibes la ballesta de coral.]",
    ["*(After Song from the Depths, if the player has destroyed their Remora's necklace:)* I don't suppose you've seen a necklace lying about?"] = "*(Después de Song from the Depths, si el player ha destruido el collar de Remora:)* ¿Supongo que no habrás visto un collar tirado por ahí?",
    ["[You receive the Siren's necklace.]"] = "[Recibes el collar de la sirena.]",
    ["Hmm? What's that, young [man/woman]? What can I do for you?"] = "¿Mmm? ¿Qué es eso, joven [man/woman]? ¿Qué puedo hacer por ti?",
    ["I don't know, what can you do for me?"] = "No lo sé, ¿qué puedes hacer por mí?",
    ["Hmm, well, mmm, do you have a family crest? I keep track of every Gielinorian family, you know, so I might be able to find yours."] = "Hmm, bueno, mmm, ¿tienes un escudo familiar? Llevo un registro de cada familia gielinoriana, ya sabes, para poder encontrar la tuya.",
    ["I'm also something of an, mmm, a painter. If you've met any important persons or visited any nice places I could paint them for you."] = "También soy algo así como, mmm, pintor. Si has conocido a personas importantes o has visitado algún lugar agradable, podría pintarlo para ti.",
    ["Can you see if I have a family crest?"] = "¿Puedes ver si tengo un escudo familiar?",
    ["A family crest, mmm? So, what is your name?"] = "Un escudo familiar, ¿mmm? Entonces, ¿cuál es tu nombre?",
    ["Mmm, Player, let me see..."] = "Mmm, Player, déjame ver...",
    ["First things first, young [man/woman]! There is not much point in having a family crest if you cannot display it. You should train construction until you can build a wall decoration in your dining room."] = "¡Lo primero es lo primero, joven [man/woman]! No tiene mucho sentido tener un escudo familiar si no puedes exhibirlo. Debes entrenar en construcción hasta que puedas construir una decoración de pared en tu comedor.",
    ["Well, I don't think you have any noble blood, but I see that your ancestors came from [Asgarnia/Kandarin/Misthalin], so that can be your crest."] = "Bueno, no creo que tengas sangre noble, pero veo que tus antepasados vinieron de [Asgarnia/Kandarin/Misthalin], así que ese puede ser tu escudo.",
    ["colour=white"] = "color = blanco",
    ["Well, I don't think you have any noble blood, but I see that your ancestors came from Varrock, so you can use that city's crest."] = "Bueno, no creo que tengas sangre noble, pero veo que tus antepasados vinieron de Varrock, así que puedes usar el escudo de esa ciudad.",
    ["According to my records, your crest is [the symbol of Shield of Arrav/the symbol of Asgarnia/the symbol of Dorgeshuun brooch/a dragon/a fairy/the symbol of Guthix/the symbol of the HAM cult/a horse/a jungle orge/the symbol of Kandarin/the symbol of Misthalin/a bag of money/the symbol of Saradomin/a skull/the symbol of Varrock/the symbol of Zamorak]."] = "Según mis registros, tu escudo es [the symbol of Shield of Arrav/the symbol of Asgarnia/the symbol of Dorgeshuun brooch/a dragon/a fairy/the symbol of Guthix/the symbol of the HAM cult/a horse/a jungle orge/the symbol of Kandarin/the symbol of Misthalin/a bag of money/the symbol of Saradomin/a skull/the symbol of Varrock/the symbol of Zamorak].",
    ["I don't like that crest. Can I have a different one?"] = "No me gusta esa cresta. ¿Puedo tener uno diferente?",
    ["Looking to tick off a hard task in your Falador Achievement diary, eh?"] = "¿Quieres marcar una tarea difícil en tu diario de logros de Falador, ¿eh?",
    ["Perhaps."] = "Quizás.",
    ["It's just that I realise you spent a lot on your current crest, it being the money crest and all, and I wish to inform you that we will be giving you a voucher allowing you to get your old crest back. Assuming you're changing to the Saradomin symbol, that is. You'll only ever get one voucher, though. We won't give you another once you've ticked off that task in your diary."] = "Es solo que me doy cuenta de que gastaste mucho en tu escudo actual, siendo el escudo de dinero y todo, y deseo informarte que te daremos un vale que te permitirá recuperar tu antiguo escudo. Suponiendo que esté cambiando al símbolo Saradomin, claro está. Sin embargo, solo recibirás un cupón. No te daremos otra una vez que hayas marcado esa tarea en tu diario.",
    ["That's very kind of you!"] = "¡Es muy amable de tu parte!",
    ["Yes, well, duty to serve and all that. Unfortunately, I can't waive the usual 5,000 fee for changing your crest, though. There are sixteen different symbols; which one would you like?"] = "Sí, bueno, deber de servir y todo eso. Desafortunadamente, no puedo renunciar a la tarifa habitual de 5.000 por cambiar tu escudo. Hay dieciséis símbolos diferentes; cual te gustaria?",
    ["**Sir Renitee:** Mmm, very well. Changing your crest will cost 5,000 coins. There are sixteen different symbols; which one would you like?"] = "**Sir Renitee:** Mmm, muy bien. Cambiar tu escudo te costará 5000 coins. Hay dieciséis símbolos diferentes; cual te gustaria?",
    ["Shield of Arrav"] = "Escudo de Arrav",
    ["But that legendary shield is still lost! I don't think it would be proper for you to wear its symbol."] = "¡Pero ese escudo legendario aún está perdido! No creo que sea apropiado que uses su símbolo.",
    ["Ah yes, the shield that you helped to retrieve. You have certainly earned the right to wear its symbol."] = "Ah, sí, el escudo que ayudaste a recuperar. Sin duda te has ganado el derecho a llevar su símbolo.",
    ["Ah, splendid, splendid. There is no better symbol than that of our fair land!"] = "Ah, espléndido, espléndido. ¡No hay mejor símbolo que el de nuestra bella tierra!",
    ["Dorgeshuun symbol"] = "Símbolo de Dorgeshuun",
    ["Hmm, have you ever even met the Dorgeshuun? I don't think you should wear their symbol until you have made contant with that lost tribe."] = "Hmm, ¿alguna vez has conocido al Dorgeshuun? No creo que debas usar su símbolo hasta que te hayas puesto en contacto con esa tribu perdida.",
    ["Ah yes, our new neighbours under Lumbridge. I hear you were the one who made contact with them, jolly good."] = "Ah, sí, nuestros nuevos vecinos bajo Lumbridge. He oído que fuiste tú quien se puso en contacto con ellos, muy bien.",
    ["Dragon"] = "dragón",
    ["When the dragon on Crandor Isle remains undefeated? I think you should prove yourself a dragon-slayer before you can wear a dragon symbol!"] = "¿Cuando el dragón de la isla Crandor permanezca invicto? ¡Creo que deberías demostrar que eres un cazador de dragones antes de poder usar un símbolo de dragón!",
    ["I see you are a mighty dragon-slayer! You have certainly earned the right to wear a dragon symbol."] = "¡Veo que eres un poderoso cazador de dragones! Sin duda te has ganado el derecho a llevar un símbolo de dragón.",
    ["Hmm, mmm, yes, everyone likes pretty fairies."] = "Hmm, mmm, sí, a todo el mundo le gustan las hadas bonitas.",
    ["You do not seem very devoted to any god. I will not let you have a divine symbol unless you have level 70 prayer."] = "No pareces muy devoto de ningún dios. No te dejaré tener un símbolo divino a menos que tengas nivel de oración 70.",
    ["Guthix, god of balance! I'm a Saradominist myself, you know, but we all find meaning in our own way, what?"] = "¡Guthix, dios del equilibrio! Yo también soy saradominista, ¿sabes? Pero todos encontramos significado a nuestra manera, ¿qué?",
    ["HAM"] = "JAMÓN",
    ["Hmm, I'm not sure I like that HAM group, their beliefs are a little extreme for me. But if that's what you want."] = "Hmm, no estoy seguro de que me guste ese grupo HAM, sus creencias son un poco extremas para mí. Pero si eso es lo que quieres.",
    ["Horse"] = "caballo",
    ["A horse? I know people talk about them, but I'm not at all sure they ever existed. I don't think I could let you use one as your symbol unless you can fetch me some kind of model of one."] = "¿Un caballo? Sé que la gente habla de ellos, pero no estoy del todo seguro de que alguna vez existieron. No creo que pueda permitirte usar uno como símbolo a menos que puedas traerme algún tipo de modelo de uno.",
    ["Ah, I see you've brought a toy horse for me to see. An interesting beast. Certainly you can use that as your crest if you like, although it seems a bit strange to me."] = "Ah, veo que trajiste un caballo de juguete para que lo vea. Una bestia interesante. Ciertamente puedes usarlo como tu escudo si quieres, aunque me parece un poco extraño.",
    ["A Jungle Ogre, eh? Odd beast, very odd."] = "Un ogro de la jungla, ¿eh? Bestia rara, muy rara.",
    ["Kandarin"] = "candarín",
    ["Our neighbours in the west? Very good, very good."] = "¿Nuestros vecinos del oeste? Muy bien, muy bien.",
    ["Ah, the fair land of Lumbridge and Varrock."] = "Ah, la bella tierra de Lumbridge y Varrock.",
    ["Money"] = "dinero",
    ["You wish to represent yourself by a moneybag? I can do that for you in exchange for that voucher, and the 5,000 coin fee of course."] = "¿Quieres representarte mediante una bolsa de dinero? Puedo hacerlo por ti a cambio de ese vale y, por supuesto, de la tarifa de 5000 monedas.",
    ["You wish to represent yourself by a moneybag? I think to make that meaningful I should increase the price to 500,000 coins. Do you agree?"] = "¿Quieres representarte mediante una bolsa de dinero? Creo que para que eso tenga sentido debería aumentar el precio a 500.000 coins. ¿Estás de acuerdo?",
    ["All right"] = "Está bien",
    ["All right."] = "Muy bien.",
    ["Thank you very much! You may now use a money-bag as your symbol."] = "¡Muchas gracias! Ahora puedes utilizar una bolsa de dinero como símbolo.",
    ["No way"] = "De ninguna manera",
    ["No way!"] = "¡De ninguna manera!",
    ["Well we can't have just any pauper using a money-bag as a symbol, can we? You'll have to choose a different symbol."] = "Bueno, no podemos permitir que cualquier pobre utilice una bolsa de dinero como símbolo, ¿verdad? Tendrás que elegir un símbolo diferente.",
    ["Ah, the great god Saradomin! May he smile on your house as you adorn it with his symbol!"] = "¡Ah, el gran dios Saradomin! ¡Que sonría en tu casa mientras la adornas con su símbolo!",
    ["As I mentioned, here's a coupon allowing you turn your crest back to the money-bag if you so wish."] = "Como mencioné, aquí tienes un cupón que te permite devolver tu escudo a la bolsa de dinero si así lo deseas.",
    ["[The herald hands you a voucher, then makes the necessary changes to your crest.]"] = "[El heraldo le entrega un vale y luego realiza los cambios necesarios en su escudo.]",
    ["Skull"] = "calavera",
    ["A symbol of death? You do not seem like a killer to me; perhaps some other symbol would suit you better."] = "¿Un símbolo de muerte? No me pareces un asesino; quizás algún otro símbolo le convenga mejor.",
    ["Of, of course you can have a skull symbol, sir/madam!"] = "¡Por supuesto que puede tener un símbolo de calavera, señor/señora!",
    ["Ah, Varrock, a fine city!"] = "¡Ah, Varrock, una hermosa ciudad!",
    ["The god of Chaos? It is a terrible thing to worship that evil being. But if that is what you wish..."] = "¿El dios del Caos? Es algo terrible adorar a ese ser maligno. Pero si eso es lo que deseas...",
    ["What does a crest do for me?"] = "¿Qué hace una cresta por mí?",
    ["Well, mmm, do you own a house? You can build a plaque on the wall with your crest, in your dining room. Then if you have a workshop you can paint your crest onto a steel shield or a banner."] = "Bueno, mmm, ¿tienes una casa? Puedes construir una placa en la pared con tu escudo, en tu comedor. Luego, si tienes un taller, puedes pintar tu escudo en un escudo de acero o en una pancarta.",
    ["Can I change my crest?"] = "¿Puedo cambiar mi escudo?",
    ["You're welcome, my [boy/girl]."] = "De nada, mi [boy/girl].",
    ["Can I buy a painting?"] = "¿Puedo comprar un cuadro?",
    ["Would you like a portrait or an, mmm, a landscape? Or a map, maybe?"] = "¿Quieres un retrato o, mmm, un paisaje? ¿O un mapa, tal vez?",
    ["A portrait"] = "un retrato",
    ["**Sir Renitee:** Mmm, well, there are a few portraits I can paint. I can only let you have one if you've got some connection with that person though. Who would you like?"] = "**Sir Renitee:** Mmm, bueno, hay algunos retratos que puedo pintar. Sin embargo, sólo puedo permitirte tener uno si tienes alguna conexión con esa persona. ¿A quién te gustaría?",
    ["Do you have, mmm, a connection with King Arthur? He wouldn't like me to just give his picture to anyone."] = "¿Tienes, mmm, conexión con King Arthur? No le gustaría que le diera su foto a nadie.",
    ["To buy the portrait of King Arthur you must have completed ."] = "Para comprar el retrato de King Arthur debes haber completado .",
    ["**Sir Renitee:** Would you like a different painting?"] = "**Sir Renitee:** ¿Quieres un cuadro diferente?",
    ["Yes - a portrait"] = "Si - un retrato",
    ["Yes - a landscape"] = "Si - un paisaje",
    ["Yes - a map"] = "Sí - un mapa",
    ["Mmm, well, see you some other time maybe."] = "Mmm, bueno, quizás nos veamos en otro momento.",
    ["**Sir Renitee:** That will be, mmm, 1000 coins please."] = "**Sir Renitee:** Eso será, mmm, 1000 coins por favor.",
    ["There you go. Would you like another painting?"] = "Ahí lo tienes. ¿Quieres otro cuadro?",
    ["No thanks"] = "No, gracias",
    ["Well, mmm, maybe a different painting, mmm?"] = "Bueno, mmm, ¿quizás un cuadro diferente, mmm?",
    ["Elena of Ardougne"] = "Elena de Ardougne",
    ["The last I heard, Elena was, mmm, trapped in West Ardougne. I wouldn't feel right selling her portrait while she was in danger."] = "Lo último que escuché es que Elena estaba, mmm, atrapado en West Ardougne. No me sentiría bien vendiendo su retrato mientras estuviera en peligro.",
    ["[Plague City] quest.}}"] = "Misión [Plague City].}}",
    ["King Alvis of Keldagrim"] = "Rey Alvis de Keldagrim",
    ["Have you ever been to Keldagrim? I think I'd need you to jog my memory..."] = "¿Has estado alguna vez en Keldagrim? Creo que necesitaría que me refrescaras la memoria...",
    ["The Prince and Princess of Miscellania"] = "El Príncipe y la Princesa de Miscellania",
    ["Do you have some connection with the prince and princess? I wouldn't want to give out their picture to just anyone?"] = "¿Tienes alguna conexión con el príncipe y la princesa? ¿No me gustaría darle su foto a cualquiera?",
    ["A landscape"] = "un paisaje",
    ["**Sir Renitee:** Mmm, well, I can paint a few places. Where have you had your adventures?"] = "**Sir Renitee:** Mmm, bueno, puedo pintar algunos lugares. ¿Dónde has vivido tus aventuras?",
    ["The River Lum"] = "El río Lum",
    ["Mmm, I'm not sure you've had enough adventures in Lumbridge to deserve a painting of it."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en Lumbridge como para merecer una pintura.",
    ["**Sir Renitee:** That will be, mmm, 2000 coins please."] = "**Sir Renitee:** Eso será, mmm, 2000 coins por favor.",
    ["The Kharid desert"] = "El desierto de Kharid",
    ["Mmm, I'm not sure you've had enough adventures in the desert to deserve a painting of it."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en el desierto como para merecer una pintura de ellas.",
    ["Mmm, I'm not sure you've had enough adventures in Morytania to deserve a painting of it."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en Morytania como para merecer una pintura.",
    ["Mmm, I'm not sure you've had enough adventures in Karamja to deserve a painting of it."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en Karamja como para merecer una pintura.",
    ["Mmm, I'm not sure you've had enough adventures in Isafdar to deserve a painting of it."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en Isafdar como para merecer una pintura.",
    ["A map"] = "un mapa",
    ["**Sir Renitee:** Mmm, yes, ah, I have painted maps of the known world on several different sizes of parchment. you like?"] = "**Sir Renitee:** Mmm, sí, ah, he pintado mapas del mundo conocido en pergaminos de varios tamaños diferentes. ¿te gusta?",
    ["Small"] = "pequeño",
    ["Mmm, I'm not sure you've had enough adventures in the world to deserve that map."] = "Mmm, no estoy seguro de que hayas tenido suficientes aventuras en el mundo para merecer ese mapa.",
    ["[51] Quest Points.}}"] = "[51] Puntos de misión.}}",
    ["Medium"] = "Medio",
    ["[101] Quest Points.}}"] = "[101] Puntos de misión.}}",
    ["Large"] = "Grande",
    ["[151] Quest Points.}}"] = "[151] Puntos de misión.}}",
    ["Nothing, thanks"] = "Nada, gracias",
    ["Buzz off, I'm not here."] = "Buzz fuera, no estoy aquí.",
    ["What ho, [sirrah/milady]. Spiffing day for a walk in the park, what?"] = "Qué hola, [sirrah/milady]. Un buen día para dar un paseo por el parque, ¿qué?",
    ["Spiffing?"] = "¿Escupiendo?",
    ["Absolutely, top-hole! Well, can't stay and chat all day, dontchaknow! Ta-ta for now!"] = "¡Por supuesto, agujero superior! Bueno, no puedo quedarme charlando todo el día, ¡no lo sabes! ¡Ta-ta por ahora!",
    ["Erm...goodbye."] = "Erm...adiós.",
    ["*If the player has completed Recruitment Drive, but not Wanted!:*"] = "*Si el player ha completado la campaña de reclutamiento, ¡pero no se busca!:*",
    ["What ho, [sirrah/milady]. Jolly good show on the old training grounds thingy, what?"] = "Qué hola, [sirrah/milady]. Muy buen espectáculo en el antiguo campo de entrenamiento, ¿qué?",
    ["*If the player has completed Wanted!, but not The Slug Menace:*"] = "*Si el player ha completado ¡Se busca!, pero no La amenaza de las babosas:*",
    ["Jolly good show on getting into the White Knights, what? Now, how can I help you, young fellow?"] = "Muy buen espectáculo sobre cómo ingresar a los Caballeros Blancos, ¿qué? Ahora, ¿cómo puedo ayudarte, jovencito?",
    ["*If the player has completed The Slug Menace:*"] = "*Si el player ha completado La amenaza de las babosas:*",
    ["Good day, Proselyte. Is there anything I can do for you?"] = "Buenos días, prosélito. ¿Hay algo que pueda hacer por ti?",
    ["*After the player has completed Ritual of the Mahjarrat:*"] = "*Después de que el player haya completado el Ritual del Mahjarrat:*",
    ["Ritual of the Mahjarrat."] = "Ritual del Mahjarrat.",
    ["Hey, Tiffy, how are you?"] = "Hola, Tiffy, ¿cómo estás?",
    ["Glad to see the back of that Lucien fellow!"] = "¡Me alegra ver la espalda de ese tipo Lucien!",
    ["Yes. And Thaerisk?"] = "Sí. ¿Y Thaerisk?",
    ["He's headed back to Taverley for the time being. I've put the Temple Knights on high alert for any dragonkin sightings or attacks."] = "Regresará a Taverley por el momento. He puesto a los Caballeros del Templo en alerta máxima por cualquier avistamiento o ataque de dragonantes.",
    ["I'll be ready when you need me."] = "Estaré listo cuando me necesites.",
    ["That's the spirit, old bean."] = "Ese es el espíritu, frijol viejo.",
    ["*If the player hasn't yet completed A Void Dance:*"] = "*Si el player aún no ha completado A Void Dance:*",
    ["Void Knights."] = "Caballeros del Vacío.",
    ["Has there been any progress on locating the rest of the boxes the Black Knights were making?"] = "¿Ha habido algún avance en la localización del resto de cajas que estaban haciendo los Black Knights?",
    ["Humph. My agents have tried their best, but we haven't been able to find them. Commodore Tyr got restless and sent Captain Korasi back to appraise the situation. She has suggested some cockeyed plan for infiltrating the Black Knights. You'd best speak to her. Jolly good to see you again, though, Player."] = "Humph. Mis agentes han hecho todo lo posible, pero no hemos podido encontrarlos. El comodoro Tyr se inquietó y envió al capitán Korasi de regreso para evaluar la situación. Ella ha sugerido algún plan disparatado para infiltrarse en Black Knights. Será mejor que hables con ella. Me alegro mucho de verte de nuevo, Player.",
    ["Can you explain the Gaze of Saradomin to me?"] = "¿Puedes explicarme la Mirada de Saradomin?",
    ["I don't really understand this 'Gaze of Saradomin' thing... Do you think you could explain what it does for me?"] = "Realmente no entiendo esto de 'Mirada de Saradomin'... ¿Crees que podrías explicar lo que hace por mí?",
    ["Certainly, [sirrah/milady]! As you know, we Temple Knights are personally favoured by Saradomin himself. And when I say personally favoured, I don't mean that some time in the future he's going to buy us all a drink! He watches over us, and, when we die, we're offered the chance to respawn in Falador Castle, ready to get on with our adventures. Now, this doesn't happen if we die in especially evil places like the Wilderness, but it can be a big help if you're out slaying dragons or whatever. Our equipment isn't protected any more than usual, but it's a small price to pay to be hale and hearty again, what?"] = "¡Por supuesto, [sirrah/milady]! Como sabes, nosotros, los Caballeros del Templo, somos personalmente favorecidos por el propio Saradomin. Y cuando digo favorecido personalmente, no me refiero a que en algún momento en el futuro nos invite a una bebida a todos. Él nos cuida y, cuando morimos, se nos ofrece la oportunidad de reaparecer en el Castillo Falador, listos para continuar con nuestras aventuras. Ahora bien, esto no sucede si morimos en lugares especialmente malvados como el Wilderness, pero puede ser de gran ayuda si estás matando dragones o lo que sea. Nuestro equipo no está más protegido de lo habitual, pero es un pequeño precio a pagar para volver a estar sano y salvo, ¿qué?",
    ["Was there something else you wanted to ask good old Tiffy, [sirrah/milady]?"] = "¿Había algo más que quisieras preguntarle a la buena Tiffy, [sirrah/milady]?",
    ["Do you have any jobs for me yet?"] = "¿Tienes algún trabajo para mí todavía?",
    ["*If the player has :*"] = "*Si el player tiene :*",
    ["Sorry dear [dear boy/gal] but we are still in the process of organising. I'm sure that we will have something for you soon, so please feel free to check back later. Anything else I can do for you in the meantime?"] = "Lo siento querido [dear boy/gal], pero todavía estamos en el proceso de organización. Estoy seguro de que pronto tendremos algo para usted, así que no dude en volver a consultar más tarde. ¿Puedo hacer algo más por ti mientras tanto?",
    ["*If the player has completed Ritual of the Mahjarrat:*"] = "*Si el player ha completado el Ritual del Mahjarrat:*",
    ["Can I buy some armour?"] = "¿Puedo comprar algo de armadura?",
    ["Of course, dear [dear boy/gal]. I can sell you up to Proselyte level items only, I'm afraid."] = "Por supuesto, querido [dear boy/gal]. Me temo que sólo puedo venderte artículos de nivel Prosélito.",
    ["*If the player has completed Recruitment Drive, but not The Slug Menace:*"] = "*Si el player ha completado la campaña de reclutamiento, pero no La amenaza de las babosas:*",
    ["Of course, dear [dear boy/gal]. I can sell you up to Initiate level items only, I'm afraid."] = "Por supuesto, querido [dear boy/gal]. Me temo que sólo puedo venderte artículos de nivel Iniciado.",
    ["Hey Tiffy, I lost my CommOrb..."] = "Hola Tiffy, perdí mi CommOrb...",
    ["Very careless of you, what? Here, take another, but be careful of this one!"] = "Muy descuidado de tu parte, ¿qué? ¡Toma, toma otro, pero ten cuidado con este!",
    ["Sir Tiffy hands you a CommOrb."] = "Sir Tiffy te entrega un CommOrb.",
    ["Well, see you around, Tiffy."] = "Bueno, nos vemos, Tiffy.",
    ["Ta-ta for now, old bean!"] = "¡Ta-ta por ahora, viejo!",
    ["*When Knight's notes (opened) are brought to Sir Tiffy in Falador park:*"] = "*Cuando las notas de Knight (abiertas) se llevan a Sir Tiffy en el parque Falador:*",
    ["Sir Tiffy! I got this scroll from a knight near Trollheim. He said I should deliver it to you urgently."] = "¡Señor Tiffy! Conseguí este pergamino de un caballero cerca de Trollheim. Dijo que debería entregártelo urgentemente.",
    ["What ho, old [boy/gal]. Well, hand it over and let's have a look, shall we?"] = "Qué puta, viejo [boy/gal]. Bueno, dámelo y echemos un vistazo, ¿de acuerdo?",
    ["*If the player has opened the wax seal before handing the notes to Sir Tiffy:*"] = "*Si el player ha abierto el sello de cera antes de entregarle las notas a Sir Tiffy:*",
    ["Now, let's see what is so urgent. Hmm... I see that this scroll has been tampered with! The wax seal is broken."] = "Ahora veamos qué es tan urgente. Hmm... ¡Veo que este pergamino ha sido manipulado! El sello de cera está roto.",
    ["Err, yes. It was that way when I got it."] = "Err, sí. Era así cuando lo conseguí.",
    ["I see. Anyway, let's see what it says."] = "Ya veo. De todos modos, veamos qué dice.",
    ["Sir Tiffy reads the scroll."] = "Sir Tiffy lee el pergamino.",
    ["Oh dear. Well, thank you very much, young [lad/lass]. You've been a great help. I shall pass it on to my superiors."] = "Dios mío. Bueno, muchas gracias, joven [lad/lass]. Has sido de gran ayuda. Se lo pasaré a mis superiores.",
    ["*If the player hasn't opened the wax seal before handing the notes to Sir Tiffy:*"] = "*Si el player no ha abierto el sello de cera antes de entregarle las notas a Sir Tiffy:*",
    ["Now, let's see what is so urgent. Hmmm..."] = "Ahora veamos qué es tan urgente. Mmm...",
    ["Well, you've been a great help, so I'll tell you a bit about this, shall I? Several weeks ago, a dwarven explorer, named Nestor Peregrine, discovered the entrance to an ancient cave complex while exploring the troll mountains."] = "Bueno, has sido de gran ayuda, así que te contaré un poco sobre esto, ¿de acuerdo? Hace varias semanas, un explorador enano, llamado Nestor Peregrine, descubrió la entrada a un antiguo complejo de cuevas mientras exploraba las montañas troll.",
    ["On his return to Keldagrim, he celebrated in a tavern where we have an informant. The dwarf spoke of a great treasure, apparently mentioned in dwarven legend, and of creatures of great evil, fighting those of great good. I sent Sir Gerry and a small command of knights to investigate the dwarf's stories several months ago and it appears that he has found the resting place of that incredible weapon: the godsword."] = "En su regreso a Keldagrim, celebró en una taberna donde tenemos un informante. El enano habló de un gran tesoro, aparentemente mencionado en una leyenda enana, y de criaturas de gran maldad que luchaban contra aquellas de gran bien. Envié a Sir Gerry y un pequeño comando de caballeros a investigar las historias del enano hace varios meses y parece que ha encontrado el lugar de descanso de esa increíble arma: la espada divina.",
    ["The godsword? What's that?"] = "¿La espada divina? ¿Qué es eso?",
    ["During the great god wars, the evil usurper Zamorak gathered many ancient relics and armies to his cause. There were none powerful enough to stand alone before his might, so our glorious Lord Saradomin gathered a triumvirate of gods to stem the tide of evil. They came together and, using great magics, they created the godsword; a weapon so mighty that it could slay even a god. It was forged in the flames of a volcano and tempered by the tears of the icyene. The mightiest warriors to stand before the army of evil were the aviansie: birdmen followers of Armadyl. They were a proud and mighty warrior race. To them fell the task of delivering the godsword to the holy armies that gathered to oppose Zamorak's evil. Unfortunately, they were attacked by an army of demons before they could reach the safety of the main army. It was a fiendish stroke by the forces of darkness. At the same time as they attacked the aviansie, they also mounted a huge attack on the main armies that opposed them. Realising their intent, several of the gods that were allied against Zamorak sent forces to aid the besieged aviansie, who had retreated into a temple in the mountains. The forces of Saradomin and Bandos arrived in the midst of a pitched battle for the godsword, and it was during this battle that the sword was sundered. Shortly thereafter, the evil one cast a spell of such devastation that it flattened the entire northern half of Gielinor, reducing it to what we now call the Wilderness. This temple must have collapsed, sealing the combatants in."] = "Durante las grandes guerras de los dioses, el malvado usurpador Zamorak reunió muchas reliquias y ejércitos antiguos para su causa. No había ninguno lo suficientemente poderoso como para enfrentarse solo a su poder, por lo que nuestro glorioso Señor Saradomin reunió un triunvirato de dioses para detener la marea del mal. Se unieron y, usando grandes magias, crearon la espada divina; un arma tan poderosa que podría matar incluso a un dios. Fue forjado en las llamas de un volcán y templado por las lágrimas del hielo. Los guerreros más poderosos que se enfrentaron al ejército del mal fueron los aviansie: hombres pájaro seguidores de Armadyl. Eran una raza guerrera orgullosa y poderosa. A ellos recayó la tarea de entregar la espada divina a los ejércitos sagrados que se reunieron para oponerse al mal de Zamorak. Desafortunadamente, fueron atacados por un ejército de demonios antes de que pudieran llegar a la seguridad del ejército principal. Fue un golpe diabólico por parte de las fuerzas de la oscuridad. Al mismo tiempo que atacaron a los aviansie, también montaron un gran ataque contra los principales ejércitos que se oponían a ellos. Al darse cuenta de su intención, varios de los dioses que estaban aliados contra Zamorak enviaron fuerzas para ayudar a los aviansie asediados, que se habían retirado a un templo en las montañas. Las fuerzas de Saradomin y Bandos llegaron en medio de una batalla campal por la espada divina, y fue durante esta batalla que la espada se partió. Poco después, el maligno lanzó un hechizo de tal devastación que arrasó toda la mitad norte de Gielinor, reduciéndola a lo que ahora llamamos Wilderness. Este templo debe haberse derrumbado, encerrando a los combatientes.",
    ["Surely, one of the groups would have gained the upper hand by now? After all, it's been thousands of years since that battle."] = "Seguramente, ¿alguno de los grupos ya habría tomado la delantera? Después de todo, han pasado miles de años desde esa batalla.",
    ["Apparently not. It appears that a millenia old battle is still being fought beneath the ruins of the temple, and the prize for winning the battle is the godsword! Hmm... Well, thank you very much, young [lad/lass]. You've been a great help. I shall pass it on to my superiors."] = "Al parecer no. Parece que todavía se libra una batalla milenaria bajo las ruinas del templo, ¡y el premio por ganar la batalla es la espada divina! Hmm... Bueno, muchas gracias, joven [lad/lass]. Has sido de gran ayuda. Se lo pasaré a mis superiores.",
    ["Is that it then? Aren't we going to do something?"] = "¿Es eso entonces? ¿No vamos a hacer algo?",
    ["Yes, yes. All in good time. I'll have to consult my commanding officer first. Thank you [lad/lass], you're dismissed."] = "Sí, sí. Todo a su debido tiempo. Primero tendré que consultar a mi oficial al mando. Gracias [lad/lass], estás despedido.",
    ["What's that cape you're wearing?"] = "¿Qué es esa capa que llevas puesta?",
    ["Oh, my most prized possession! This is my Benchsitting cape, only able to be worn by masters of benchsitting."] = "¡Oh, mi posesión más preciada! Esta es mi capa de Benchsitting, que solo pueden usar los maestros del benchsitting.",
    ["Can I have one?"] = "¿Puedo tener uno?",
    ["Hmm... I don't think you're as skilled as I am in benchsitting yet."] = "Hmm... No creo que tengas tanta habilidad como yo para sentarte en el banco todavía.",
    ["You need to be level 99 in the Benchsitting skill to unlock the Benchsitting cape."] = "Debes tener el nivel 99 en la habilidad Benchsitting para desbloquear la capa Benchsitting.",
    ["Return to me with a space in your backpack, then perhaps I could consider bestowing such a cape upon you."] = "Vuelve a mí con un espacio en tu backpack, entonces quizás podría considerar otorgarte esa capa.",
    ["Sir Tiffy looks you up and down, examining your benchsitting capabilities."] = "Sir Tiffy te mira de arriba abajo, examinando tu capacidad para sentarte en el banco.",
    ["Hmm... You have a sense of calm about you... An appreciation for admiring the scenery... A good sitting posture... Wooden slat indents on your legs..."] = "Hmm... Tienes una sensación de calma... Un aprecio por admirar el paisaje... Una buena postura al sentarse... Hendiduras de listones de madera en las piernas...",
    ["Yes, I would certainly say you are worthy of such a cape!"] = "Sí, ¡ciertamente diría que eres digno de esa capa!",
    ["[Sir Tiffy hands you a glorious new Benchsitting cape.]"] = "[Sir Tiffy te entrega una nueva y gloriosa capa de Benchsitting.]",
    ["I believe I have already given you one!"] = "¡Creo que ya te he dado uno!",
    ["Hello, Tiffy. Can you tell me a little about the Invasion of Falador?"] = "Hola, Tiffy. ¿Puedes contarme un poco sobre la Invasión de Falador?",
    ["What, ho? Not ten years after the Falador Massacre, and those dastardly Black Knights invade our beautiful white-walled city!"] = "¿Qué, hola? ¡No han transcurrido diez años desde la masacre de Falador y esos cobardes Black Knights invaden nuestra hermosa ciudad de murallas blancas!",
    ["But by strength of King Raddallin's legacy, this city shall never fall to its enemies! We drove those Kinshra back and chased them off."] = "¡Pero gracias al legado del rey Raddallin, esta ciudad nunca caerá en manos de sus enemigos! Hicimos retroceder a esos Kinshra y los ahuyentamos.",
    ["Sir-tified Invasion"] = "Invasión Sirtificada",
    ["Talk to Sir Tiffy in Falador Park about the Invasion of Falador."] = "Habla con Sir Tiffy en el parque Falador sobre la invasión de Falador.",
    ["Though not without the blessed aid of heroes such as you! This city is nothing if not for its own people, and that makes me sleep easy. That and a lovely cuppa before bedtime!"] = "¡Aunque no sin la bendita ayuda de héroes como tú! Esta ciudad no es más que su propia gente, y eso me hace dormir tranquilo. ¡Eso y una deliciosa taza de té antes de acostarse!",
    ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    ["I've finally unlocked stools!"] = "¡Finalmente desbloqueé los taburetes!",
    ["Been at the prunes, have you?"] = "Has estado en las ciruelas pasas, ¿verdad?",
    ["What? No, I'm training to unlock my inverted Benchsitting skillcape, you silly bean!"] = "¿Qué? No, estoy entrenando para desbloquear mi Benchsitting skillcape invertido, ¡tonto!",
    ["Greetings traveller."] = "Saludos viajero.",
    ["Do you have anything to trade?"] = "¿Tienes algo para intercambiar?",
    ["No, I'm sorry."] = "No, lo siento.",
    ["Well, maybe I do, but you need to prove yourself worthy as a White Knight before I will sell you anything."] = "Bueno, tal vez sí, pero debes demostrar que eres digno como Caballero Blanco antes de que te venda algo.",
    ["And how can I do that?"] = "¿Y cómo puedo hacer eso?",
    ["Kill Black Knights and make sure you don't kill any White Knights!"] = "¡Mata a Black Knights y asegúrate de no matar a ningún Caballero Blanco!",
    ["Well, okay then."] = "Bueno, entonces está bien.",
    ["Well, of course! I AM the White Knights armourer after all!"] = "¡Bueno, por supuesto! I ¡Después de todo, soy el armero de los Caballeros Blancos!",
    ["You are currently at Novice level within the White Knights, so your access to equipment is limited."] = "Actualmente estás en el nivel Novato dentro de los Caballeros Blancos, por lo que tu acceso al equipo es limitado.",
    ["You are at Peon level within the White Knights, so not much to choose from I'm afraid."] = "Estás en el nivel Peón dentro de los Caballeros Blancos, así que me temo que no hay mucho para elegir.",
    ["You've reached Page level, that shows a bit of dedication you know! Your available equipment will reflect that!"] = "Has alcanzado el nivel de página, eso demuestra un poco de dedicación, ¿sabes? ¡Tu equipo disponible reflejará eso!",
    ["And may I say what a pleasure it is to serve any Knight who has achieved Noble level!"] = "¡Y puedo decir que es un placer servir a cualquier Caballero que haya alcanzado el nivel Noble!",
    ["And it is so very rare that I see any White Knight who has reached Adept level!"] = "¡Y es muy raro que vea a un Caballero Blanco que haya alcanzado el nivel de Adepto!",
    ["And for a dedicated White Knight to have reached Master level like yourself, you get only the very best of all equipment available!"] = "Y para que un Caballero Blanco dedicado haya alcanzado el nivel Maestro como tú, ¡solo obtienes lo mejor de todos los equipos disponibles!",
    ["Why are there so many knights in this city?"] = "¿Por qué hay tantos caballeros en esta ciudad?",
    ["We are the White Knights of Falador. We are the most powerful order of knights in the land. We are helping the king Vallance rule the kingdom as he is getting old and tired."] = "Somos los Caballeros Blancos de Falador. Somos la orden de caballeros más poderosa del país. Estamos ayudando al rey Vallance a gobernar el reino mientras envejece y se cansa.",
    ["Can I just distract you for a minute?"] = "¿Puedo distraerte por un minuto?",
    ["Can I just talk to you very slowly for a few minutes, while I distract you, so that my friend over there can do something while you're busy being distracted by me?"] = "¿Puedo hablarte muy lentamente durante unos minutos, mientras te distraigo, para que mi amigo de allí pueda hacer algo mientras tú estás ocupado distrayéndome?",
    ["... ...what?"] = "... ...¿qué?",
    ["I'm... not sure what you're asking me... you want to join the White Knights?"] = "No... no estoy seguro de lo que me estás preguntando... ¿quieres unirte a los Caballeros Blancos?",
    ["Nope. I'm just trying to distract you."] = "No. Sólo estoy tratando de distraerte.",
    ["... ...you are very odd."] = "... ...eres muy raro.",
    ["So can I distract you some more?"] = "¿Puedo distraerte un poco más?",
    ["... ...I don't think I want to talk to you anymore."] = "... ...Creo que ya no quiero hablar contigo.",
    ["Ok. My work here is done. 'Bye!"] = "Vale. Mi trabajo aquí ha terminado. '¡Adiós!",
    ["HEY! Just WHAT do you THINK you are DOING??? STAY OUT of MY cupboard!"] = "¡Oye! ¿¿QUÉ CREES que estás HACIENDO??? ¡MANTENTE FUERA de MI armario!",
    ["Maybe you need to get Sir Vyvin further away from his cupboard..."] = "Tal vez necesites alejar a Sir Vyvin de su armario...",
    ["*If player doesn't own Yak Track Task List:*"] = "*Si el jugador no posee la lista de tareas de Yak Track:*",
    ["Ahhh! It's a talking telescope!"] = "¡Ahhh! ¡Es un telescopio parlante!",
    ["Excuse me, there is a talking yak underneath the telescope."] = "Disculpe, hay un yak parlante debajo del telescopio.",
    ["Ahhh! It's a talking yak!"] = "¡Ahhh! ¡Es un yak que habla!",
    ["*If the player participated in the original Yak Track:*"] = "*Si el player participó en el Yak Track original:*",
    ["Wow, deja vu..."] = "Vaya, deja vu...",
    ["Yes, yes, it is quite shocking to see a talking yak in this day and age. I am Sir Yaktrick Moore, savant of the stars."] = "Sí, sí, es bastante impactante ver un yak parlante hoy en día. Soy Sir Yaktrick Moore, sabio de las estrellas.",
    ["Nice to meet you, I am Player."] = "Encantado de conocerte, soy Player.",
    ["*If the player has any skills at level 99, they are listed in this order, with Invention not in the list:*"] = "*Si el player tiene alguna habilidad en el nivel 99, se enumeran en este orden, y Invention no está en la lista:*",
    ["I am a savant of : Attack, Strength, Ranged, Magic, Defence, Constitution, Prayer, Agility, Herblore, Thieving, Crafting, Runecrafting, Mining, Smithing, Fishing, Cooking, Firemaking, Woodcutting, Fletching, Slayer, Farming, Construction, Hunter, Summoning, Dungeoneering, Divination."] = "Soy un sabio de: Attack, Strength, Ranged, Magic, Defence, Constitution, Prayer, Agility, Herblore, Thieving, Crafting, Runecrafting, Mining, Smithing, Fishing, Cooking, Firemaking, Woodcutting, Fletching, Slayer, Farming, Construction, Hunter, Summoning, Dungeoneering, Divination.",
    ["Show off."] = "Presume.",
    ["Welcome back, how can I help you?"] = "Bienvenido de nuevo, ¿en qué puedo ayudarte?",
    ["How does the Yak Track work?"] = "¿Cómo funciona Yak Track?",
    ["Ah, the Yak Track! It's an opportunity to go on an adventure with your very own yak and earn many rewards along the way! Simply put, you can complete tasks to progress along the track. You will be given a choice between two tasks at a time, but you only need to complete one of them to progress. If you don't fancy doing either of them then you can use a task skip to move on. As you progress along the track you will earn rewards; Premier Club members and those who have purchased a Premier Pass will earn additional premium rewards. If you purchase a Premier Pass you will receive any premium rewards you would have been eligible for."] = "¡Ah, el Yak Track! ¡Es una oportunidad para emprender una aventura con tu propio yak y ganar muchas recompensas en el camino! En pocas palabras, puedes completar tareas para avanzar en la pista. Podrás elegir entre dos tareas a la vez, pero solo necesitarás completar una de ellas para progresar. Si no te apetece hacer ninguna de las dos, puedes saltar tareas para seguir adelante. A medida que avances en la pista, ganarás recompensas; Los miembros de Premier Club y aquellos que hayan comprado un Premier Pass obtendrán recompensas premium adicionales. Si compra un Premier Pass, recibirá todas las recompensas premium para las que hubiera sido elegible.",
    ["Sounds great!"] = "¡Suena genial!",
    ["That's a really big telescope."] = "Es un telescopio realmente grande.",
    ["... Can I touch it?"] = "... ¿Puedo tocarlo?",
    ["Please?"] = "¿Por favor?",
    ["Absolutely not."] = "Por supuesto que no.",
    ["Do you have a tragic backstory?"] = "¿Tienes una historia trágica?",
    ["Do you have a backstory?"] = "¿Tienes una historia de fondo?",
    ["Can I hear it?"] = "¿Puedo oírlo?",
    ["Can I hear it now?"] = "¿Puedo escucharlo ahora?",
    ["Fine. I am Sir Yaktrick Moore, savant of the stars. When I was but a young yak I travelled all over Gielinor with my master. We would spend our days on the road and our nights sleeping under the stars. How I value those good old days we used to spend together. Alas, he is no longer with us."] = "Bien. Soy Sir Yaktrick Moore, sabio de las estrellas. Cuando era un joven yak viajé por todo Gielinor con mi maestro. Pasaríamos nuestros días en la carretera y nuestras noches durmiendo bajo las estrellas. Cómo valoro esos buenos viejos tiempos que solíamos pasar juntos. Por desgracia, ya no está con nosotros.",
    ["Oh no. What happened to him?"] = "Oh, no. ¿Qué le pasó?",
    ["He settled down with his wife and had a beautiful family. I still see them on the regular, I'm pretty much a part of the family too."] = "Se estableció con su esposa y tuvo una hermosa familia. Todavía los veo con regularidad, yo también soy prácticamente parte de la familia.",
    ["Wow, that really was a non tragic backstory. Are you sure nothing awful happened? No curses? No fatal mistakes?"] = "Vaya, esa realmente no fue una historia de fondo trágica. ¿Estás seguro de que no pasó nada terrible? ¿Sin maldiciones? ¿Sin errores fatales?",
    ["Nope. I'm just a yak that has a big telescope on his back."] = "No. Sólo soy un yak que tiene un gran telescopio en la espalda.",
    ["Man, that's disappointing."] = "Hombre, eso es decepcionante.",
    ["What!?"] = "¿¡Qué!?",
    ["Oh, nothing!"] = "¡Oh, nada!",
    ["The sister politely ignores you, as if she is not permitted to speak to you yet."] = "La hermana te ignora cortésmente, como si todavía no le permitieran hablar contigo.",
    ["Thank you for helping us, adventurer. I really thought I was going to die, but you saved us."] = "Gracias por ayudarnos, aventurero. Realmente pensé que iba a morir, pero tú nos salvaste.",
    ["Since you're here, adventurer...could I ask for your advice?"] = "Ya que estás aquí, aventurero... ¿podría pedirte consejo?",
    ["Of course."] = "Por supuesto.",
    ["The murders in the abbey made me think about what I want to do with my life. I've been here since I was a child, and I thought I'd spend my whole life here, but now I'm not sure I want to."] = "Los asesinatos en la abadía me hicieron pensar en lo que quiero hacer con mi vida. He estado aquí desde que era un niño y pensé que pasaría toda mi vida aquí, pero ahora no estoy seguro de querer hacerlo.",
    ["I could leave and become a secular musician, travel the world..."] = "Podría irme y convertirme en un músico secular, viajar por el mundo...",
    ["But on the other hand, I do feel the presence of Saradomin here, and if I leave, I can never come back."] = "Pero por otro lado, sí siento la presencia de Saradomin aquí, y si me voy, nunca podré volver.",
    ["What do you think I should do, adventurer?"] = "¿Qué crees que debería hacer, aventurero?",
    ["You should leave the abbey."] = "Deberías abandonar la abadía.",
    ["Thank you, adventurer."] = "Gracias, aventurero.",
    ["You should stay."] = "Deberías quedarte.",
    ["I can't decide for you."] = "No puedo decidir por ti.",
    ["Of course. I suppose I'll stay here and think about it."] = "Por supuesto. Supongo que me quedaré aquí y lo pensaré.",
    ["I'm glad I stayed in the abbey. Wanting to leave was just a phase. There's so much I can do here to praise Saradomin. I think I might even be called to be abbess after Sister Benita retires."] = "Me alegro de haberme quedado en la abadía. Querer irme fue solo una fase. Hay mucho que puedo hacer aquí para elogiar a Saradomin. Creo que incluso podrían llamarme abadesa cuando la hermana Benita se jubile.",
    ["I'll always wonder what life might have been like if I'd left, though."] = "Sin embargo, siempre me preguntaré cómo habría sido la vida si me hubiera ido.",
    ["I'm glad I left the abbey. There's so much more I can do with music now that I can focus on it for its own sake."] = "Me alegro de haber dejado la abadía. Hay mucho más que puedo hacer con la música ahora que puedo concentrarme en ella por sí misma.",
    ["I'll always wonder what life might have been like if I'd stayed, though."] = "Sin embargo, siempre me preguntaré cómo habría sido la vida si me hubiera quedado.",
    ["Hello again, adventurer."] = "Hola de nuevo, aventurero.",
    ["How are you doing?"] = "¿Cómo estás?",
    ["Oh, I'm fine. The clock is running smoothly."] = "Oh, estoy bien. El reloj corre sin problemas.",
    ["Why didn't you tell Abbess Benita who the killer was?"] = "¿Por qué no le dijiste a Abbess Benita quién era el asesino?",
    ["You're the adventurer. You solved the mystery and defeated the killer. It was better that she should hear it from you."] = "Tú eres el aventurero. Resolviste el misterio y derrotaste al asesino. Era mejor que ella lo supiera de ti.",
    ["*(If the player lied about The Killer's true identity:)*"] = "*(Si el player mintió sobre la verdadera identidad de The Killer:)*",
    ["But I lied, and you didn't contradict me."] = "Pero mentí y no me contradijiste.",
    ["*(If the player told the truth about The Killer's true identity:)*"] = "*(Si el player dijo la verdad sobre la verdadera identidad de The Killer:)*",
    ["But I could have lied."] = "Pero podría haber mentido.",
    ["There's a saying: a stopped clock is right twice a day."] = "Hay un dicho: un reloj parado da la hora correcta dos veces al día.",
    ["Well, I don't like that saying. A clock ten minutes slow is never right, but it's a lot more useful than one that's stopped."] = "Bueno, no me gusta ese dicho. Un reloj diez minutos retrasado nunca está bien, pero es mucho más útil que uno parado.",
    ["What are you getting at?"] = "¿A qué te refieres?",
    ["What I am getting at is, perhaps it's better for someone to have the wrong time, if that's what keeps their clock going. It's better than setting the clock right but having it stop."] = "Lo que quiero decir es que tal vez sea mejor que alguien tenga la hora equivocada, si eso es lo que mantiene su reloj en marcha. Es mejor que poner bien el reloj pero que se pare.",
    ["You think it was right for me to lie?"] = "¿Crees que estuvo bien que mintiera?",
    ["I think that you were the mechanic, and it was your decision how best to fix the clock."] = "Creo que tú eras el mecánico y era tu decisión cuál era la mejor manera de arreglar el reloj.",
    ["Hey...who gave you permission to come in here! Get out, get out I say."] = "Oye... ¡quién te dio permiso para entrar aquí! Sal, sal, digo.",
    ["Alright, alright...keep your night cap on."] = "Está bien, está bien... mantén tu gorro de dormir puesto.",
    ["Hey! What do you think you're doing?"] = "¡Oye! ¿Qué crees que estás haciendo?",
    ["Erk! I'd better not start rifling through people's things without permission."] = "¡Erk! Será mejor que no empiece a hurgar en las cosas de la gente sin permiso.",
    ["Hey! What do you think you're doing? Leave my tea alone!"] = "¡Oye! ¿Qué crees que estás haciendo? ¡Deja mi té en paz!",
    ["Hey! What do you think you're doing? Don't go casting that kind of spell anywhere near my tea! Leave my tea alone you telegrabbing fiend!"] = "¡Oye! ¿Qué crees que estás haciendo? ¡No vayas a lanzar ese tipo de hechizo cerca de mi té! ¡Deja mi té en paz, demonio del telegrabado!",
    ["There appears to be someone trapped in ice."] = "Parece haber alguien atrapado en el hielo.",
    ["Light a fire next to him"] = "Enciende un fuego junto a él.",
    ["[You need some logs before you can start a fire.]"] = "[Necesitas algo de logs antes de poder iniciar un incendio.]",
    ["cond=If the player is at least level 13 Magic:"] = "cond=Si el player es al menos el nivel 13 Magic:",
    ["Which spell will you cast?"] = "¿Qué hechizo lanzarás?",
    ["Fire Strike"] = "Golpe de fuego",
    ["cond=If the player is at least level 35 Magic:"] = "cond=Si el player es al menos el nivel 35 Magic:",
    ["cond=If the player is at least level 59 Magic:"] = "cond=Si el player es al menos el nivel 59 Magic:",
    ["cond=If the player is at least level 75 Magic:"] = "cond=Si el player es al menos el nivel 75 Magic:",
    ["cond=If the player is at least level 95 Magic:"] = "cond=Si el player es al menos el nivel 95 Magic:",
    ["Do nothing"] = "no hacer nada",
    ["...What chapter is this? What story?..."] = "...¿Qué capítulo es este? ¿Qué historia?...",
    ["Am I...am I free? My home has been in that ice for so long!"] = "¿Soy...soy libre? ¡Mi casa ha estado en ese hielo durante tanto tiempo!",
    ["How can I reward you? I have so little to offer as a reward. Perhaps I can offer my skills as a storyteller..."] = "¿Cómo puedo recompensarte? Tengo muy poco que ofrecer como recompensa. Quizás pueda ofrecer mis habilidades como narrador...",
    ["Yes, that is what I shall do. I shall let you into my stories, whenever you want, as often as you want. It's the least I can do."] = "Sí, eso es lo que haré. Te dejaré entrar en mis historias, cuando quieras, tantas veces como quieras. Es lo mínimo que puedo hacer.",
    ["Shall I return to the surface now, or is there more you would like to ask?"] = "¿Debo regresar a la superficie ahora o hay más que te gustaría preguntar?",
    ["Head to the surface."] = "Dirígete a la superficie.",
    ["There's more I'd like to ask you."] = "Hay más que me gustaría preguntarte.",
    ["That is the question. I'm Player... No, wrong story, that's your name not mine. Perhaps my name is Ozan...do I look like an Ozan?"] = "Esa es la pregunta. Soy Player... No, historia equivocada, ese es tu nombre, no el mío. Quizás mi nombre es Ozan... ¿parezco un Ozan?",
    ["No, those aren't my names."] = "No, esos no son mis nombres.",
    ["I'm sorry, Player, but I don't quite know who I am."] = "Lo siento, Player, pero no sé muy bien quién soy.",
    ["But how did you know my name? We've only just met."] = "¿Pero cómo supiste mi nombre? Nos acabamos de conocer.",
    ["Oh, I knew your name as soon as your stories flooded the shelves."] = "Oh, supe tu nombre tan pronto como tus historias inundaron los estantes.",
    ["Shelves? Stories?"] = "¿Estantes? ¿Historias?",
    ["The library of my mind; each book a story, each story someone's life, each life full of hopes and dreams. When you came close, your books filled a whole bookcase; each story filled with adventure and potential."] = "La biblioteca de mi mente; cada libro una historia, cada historia la vida de alguien, cada vida llena de esperanzas y sueños. Cuando estuviste cerca, tus libros llenaron una estantería entera; cada historia llena de aventuras y potencial.",
    ["Riiight."] = "Correcto.",
    ["Yet, you don't know who you are?"] = "Aún así, ¿no sabes quién eres?",
    ["No. The library is empty of my stories, it seems."] = "No. Parece que la biblioteca está vacía de mis historias.",
    ["I know that I am a teller of tales and a keeper of stories. But beyond that I do not know."] = "Sé que soy un narrador de cuentos y un guardián de historias. Pero más allá de eso no lo sé.",
    ["You're going to tell me stories?"] = "¿Me vas a contar historias?",
    ["So you're going to tell me stories?"] = "¿Entonces me vas a contar historias?",
    ["Tell you? No, no, I will do so much more than tell you."] = "¿Te lo digo? No, no, haré mucho más que decírtelo.",
    ["I will show you my stories, let you be a part of them, live someone else's life for a while."] = "Te mostraré mis historias, te dejaré ser parte de ellas, vivir la vida de otra persona por un tiempo.",
    ["Just come find me on the surface outside of these demon halls, and I will be able to explain it better. These dungeons are too dangerous for me to go into great detail."] = "Ven a buscarme a la superficie fuera de estos pasillos de demonios y podré explicártelo mejor. Estas mazmorras son demasiado peligrosas para entrar en detalles.",
    ["What are these stories you talk about?"] = "¿Cuáles son esas historias de las que hablas?",
    ["I know all the stories that have taken place within Daemonheim: every grand adventure, every tragic romance... I know them, and in turn I have lived them."] = "Conozco todas las historias que han ocurrido dentro de Daemonheim: cada gran aventura, cada romance trágico... Las conozco, y a su vez las he vivido.",
    ["They are all catalogued safely in my mind's library, to be read at a moment's notice."] = "Todos están catalogados de forma segura en la biblioteca de mi mente, para ser leídos en cualquier momento.",
    ["So, you can tell me what's at the bottom of Daemonheim?"] = "Entonces, ¿puedes decirme qué hay al final de Daemonheim?",
    ["And ruin the adventure for you?"] = "¿Y arruinarte la aventura?",
    ["Spoilers, dear [boy/lady], spoilers."] = "Spoilers, querido [boy/lady], spoilers.",
    ["Could you at least tell me these stories?"] = "¿Podrías al menos contarme estas historias?",
    ["I would love to."] = "Me encantaría.",
    ["But not here. The dungeons are too dangerous for idle storytelling."] = "Pero aquí no. Las mazmorras son demasiado peligrosas para contar historias ociosas.",
    ["Now that I am free from my frost prison, I can meet you on the surface. Come to me there and I will tell you such tales."] = "Ahora que estoy libre de mi prisión helada, puedo encontrarte en la superficie. Ven a verme allí y te contaré esas historias.",
    ["At least, I will if you can jog my memory. Find story elements while in Daemonheim and I will happily relate the associated saga to you on the surface."] = "Al menos lo haré si puedes refrescarme la memoria. Encuentra elementos de la historia mientras estás en Daemonheim y con gusto te contaré la saga asociada en la superficie.",
    ["Why were you frozen in ice?"] = "¿Por qué estabas congelado en hielo?",
    ["I honestly cannot remember."] = "Sinceramente, no lo recuerdo.",
    ["Perhaps it was a cave-in, a flash flood perhaps."] = "Quizás fue un derrumbe, quizás una inundación repentina.",
    ["But then again, I vaguely remember laughter...haunting laughter. Hmmm, was it really laughter, or something my paranoid mind conjured up?"] = "Pero claro, recuerdo vagamente la risa... una risa inquietante. Hmmm, ¿fue realmente risa o algo que evocó mi mente paranoica?",
    ["How long have you been frozen down here?"] = "¿Cuánto tiempo llevas congelado aquí abajo?",
    ["What Age is this?"] = "¿Qué edad es esta?",
    ["It's the 6th Age."] = "Es la sexta edad.",
    ["Oh... In that case, I've been down here for a long time indeed. It may even be centuries."] = "Oh... En ese caso, he estado aquí durante mucho tiempo. Incluso pueden ser siglos.",
    ["Yes, farewell for now, my friend. I will wait for you on the surface, near a nice warm fire if there is one."] = "Sí, adiós por ahora, amigo. Te esperaré en la superficie, cerca de un agradable fuego cálido si lo hay.",
    ["Find story elements here in Daemonheim and visit me with them. They will unlock stories that you will scantly believe."] = "Encuentra elementos de la historia aquí en Daemonheim y visítame con ellos. Desbloquearán historias que difícilmente creerás.",
    ["Greetings, Player. It's so nice to see you again! Have you come to hear a story?"] = "Saludos, Player. ¡Qué lindo verte de nuevo! ¿Has venido a escuchar una historia?",
    ["Yes, tell me a story."] = "Sí, cuéntame una historia.",
    ["*(If the player has not discovered any memory items:)*"] = "*(Si el player no ha descubierto ningún elemento de memoria:)*",
    ["Ah, but you are yet to discover any items in Daemonheim that will jog my memory."] = "Ah, pero aún no has descubierto ningún elemento en Daemonheim que me refresque la memoria.",
    ["I am truly sorry."] = "Lo siento mucho.",
    ["Which story would you like to hear?"] = "¿Qué historia te gustaría escuchar?",
    ["*(Choose a Story interface opens)*"] = "*(Se abre la interfaz Elija una Historia)*",
    ["Play saga"] = "Jugar saga",
    ["*(If the player is carrying items:)*"] = "*(Si el player lleva artículos:)*",
    ["I'm sorry my friend, but you need to clear your inventory before I can tell that story."] = "Lo siento amigo mío, pero debes limpiar tu inventario antes de que pueda contar esa historia.",
    ["Skaldrun cannot tell you a story while you are burdened with material possessions."] = "Skaldrun no puede contarte una historia mientras estás cargado de posesiones materiales.",
    ["You must bank all of the items you are wearing and carrying."] = "Debes guardar en el banco todos los artículos que llevas puestos y que llevas.",
    ["*(If the player selects a saga which they have not unlocked yet:)*"] = "*(Si el player selecciona una saga que aún no ha desbloqueado:)*",
    ["I'm sorry my friend, but I don't yet remember that story."] = "Lo siento amigo mío, pero todavía no recuerdo esa historia.",
    ["*(If the player is currently under the effect of an Overload potion:)*"] = "*(Si el player se encuentra actualmente bajo el efecto de una poción de sobrecarga:)*",
    ["You should return to me once your Overload potion has worn off."] = "Deberías regresar conmigo una vez que tu poción de sobrecarga haya desaparecido.",
    ["*(If the player chose Vengeance, Thok it to Them, Nadir, or Thok Your Block off while on a free-to-play world:)*"] = "*(Si el player elige Vengeance, Thok it to Them, Nadir o Thok Your Block mientras estás en un mundo gratuito:)*",
    ["You must be on a members' world to play this saga."] = "Debes estar en un mundo de miembros para jugar esta saga.",
    ["How do these sagas work, exactly?"] = "¿Cómo funcionan exactamente estas sagas?",
    ["I can take you inside these sagas. There you become the hero of that saga: taking on their form, their mannerisms, their strengths and their weaknesses."] = "Puedo llevarte al interior de estas sagas. Allí te conviertes en el héroe de esa saga: adoptas su forma, sus gestos, sus fortalezas y sus debilidades.",
    ["You live through their story and control their destiny. Their choices will be yours, and their actions will be your actions."] = "Vives su historia y controlas su destino. Sus elecciones serán las tuyas y sus acciones serán las tuyas.",
    ["So, I'll gain experience by becoming them?"] = "Entonces, ¿ganaré experiencia al convertirme en ellos?",
    ["In a manner of speaking. You will not gain anything while I relate the saga to you, but there is experience to be gained if you complete it - so long as you have not done so already."] = "Por así decirlo. No ganarás nada mientras te cuente la saga, pero puedes ganar experiencia si la completas, siempre y cuando no lo hayas hecho ya.",
    ["Once you have completed a saga, I will present you with a book containing its secrets, and this will improve your knowledge in certain areas."] = "Una vez que hayas completado una saga, te presentaré un libro que contiene sus secretos, y esto mejorará tus conocimientos en ciertas áreas.",
    ["You can get two books per saga: one for completing the abridged version of a saga and another for completing 100% of the unabridged version. You must be skilled enough to hear my unabridged sagas, while no skills are required to hear the abridged version."] = "Podrás conseguir dos libros por saga: uno por completar la versión abreviada de una saga y otro por completar el 100% de la versión íntegra. Debes tener la habilidad suficiente para escuchar mis sagas íntegras, mientras que no se requieren habilidades para escuchar la versión abreviada.",
    ["Get to the end of an abridged or unabridged saga and you will gain a small reward; complete all of the secondary objectives in an unabridged saga and you will receive the full rewards."] = "Llega al final de una saga abreviada o íntegra y obtendrás una pequeña recompensa; completa todos los objetivos secundarios en una saga íntegra y recibirás las recompensas completas.",
    ["Can you just tell me these sagas straight away?"] = "¿Puedes contarme estas sagas de inmediato?",
    ["I'm sorry, no. My memory is a mess of uncatalogued stories, so you'll need to jog my memory before I can tell you a saga."] = "Lo siento, no. Mi memoria es un lío de historias sin catalogar, así que tendrás que refrescarme la memoria antes de que pueda contarte una saga.",
    ["There will be reminders throughout the dungeons of Daemonheim: fragments of my memory that have taken physical form."] = "Habrá recordatorios a lo largo de las mazmorras de Daemonheim: fragmentos de mi memoria que han tomado forma física.",
    ["If you can find these, then I'll be able to tell you a new saga."] = "Si puedes encontrarlos, podré contarte una nueva saga.",
    ["Can I fail a saga?"] = "¿Puedo fallar en una saga?",
    ["Yes, I'm afraid so. If you lead your protagonist to destruction, or otherwise damage the fundamental elements of the saga, the story will unravel and you will return here."] = "Sí, me temo que sí. Si llevas a tu protagonista a la destrucción, o dañas de otra manera los elementos fundamentales de la saga, la historia se desmoronará y regresarás aquí.",
    ["But do not despair: if you reach certain points in a saga and fail, you will be able to return to that point and continue."] = "Pero no desesperes: si llegas a ciertos puntos de una saga y fallas, podrás volver a ese punto y continuar.",
    ["Is there anything else I should know?"] = "¿Hay algo más que deba saber?",
    ["Each story is different and has its own nuances and twists. Be sure to read their special rules so that you can understand what is required of you."] = "Cada historia es diferente y tiene sus propios matices y giros. Asegúrese de leer sus reglas especiales para que pueda comprender lo que se requiere de usted.",
    ["I will provide all this information when you come to choose a saga to play."] = "Te proporcionaré toda esta información cuando elijas una saga para jugar.",
    ["I'd like to discuss the dig site."] = "Me gustaría hablar sobre el sitio de excavación.",
    ["Ah, of course! What aspect would you like to discuss?"] = "¡Ah, por supuesto! ¿Qué aspecto te gustaría discutir?",
    ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
    ["Since you released me I have heard about your endeavours in Archaeology."] = "Desde que me liberaste, he oído hablar de tus esfuerzos en Archaeology.",
    ["I wish to learn even more of the stories of this place so I can share them with others."] = "Deseo aprender aún más de las historias de este lugar para poder compartirlas con otros.",
    ["So, I had my friends here send word to the Archaeology guild to request an excavation here."] = "Entonces, hice que mis amigos aquí enviaran un mensaje al gremio Archaeology para solicitar una excavación aquí.",
    ["You'll find plenty of places to dig around the castle ahead."] = "Encontrarás muchos lugares para excavar alrededor del castillo que tienes delante.",
    ["If I find any particularly rare or interesting objects, could I experience more sagas?"] = "Si encuentro algún objeto particularmente raro o interesante, ¿podré experimentar más sagas?",
    ["Especially old objects might result in much hazier experiences, but I could draw some memories from them."] = "Los objetos especialmente antiguos pueden dar lugar a experiencias mucho más confusas, pero puedo extraer algunos recuerdos de ellos.",
    ["I'd better get to excavating then!"] = "¡Será mejor que me ponga a excavar entonces!",
    ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
    ["This fortress was named Daemonheim by the Fremennik. It has been inhabited by Zamorakians for a couple of ages, but its past goes much further back than that."] = "Esta fortaleza fue nombrada Daemonheim por los Fremennik. Ha estado habitada por zamoraks desde hace un par de épocas, pero su pasado se remonta mucho más atrás.",
    ["I've heard some indications of a race called dragonkin."] = "He escuchado algunos indicios de una raza llamada dragonkin.",
    ["My hope is that you and the archaeology guild can help me uncover more of Daemonheim's stories by excavating the site."] = "Espero que tú y el gremio de arqueología puedan ayudarme a descubrir más historias de Daemonheim excavando el sitio.",
    ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
    ["We have yet to uncover anything of significance. Bring me anything that feels special and we can investigate the tale it can tell."] = "Todavía tenemos que descubrir algo significativo. Tráeme cualquier cosa que parezca especial y podremos investigar la historia que puede contar.",
    ["What would you like to discuss?"] = "¿Qué te gustaría discutir?",
    ["Hand in memory objects."] = "Entregar objetos de memoria.",
    ["I found this thing. It feels stranger than some of the other artefacts, like there's one of your stories attached to it."] = "Encontré esto. Se siente más extraño que algunos de los otros artefactos, como si tuviera una de tus historias adjunta.",
    ["This is very old indeed. Too faint to experience in full, but imbued with memories nonetheless. Perhaps you can draw it out yourself. Close your eyes."] = "Esto es muy antiguo. Demasiado débil para experimentarlo en su totalidad, pero aun así imbuido de recuerdos. Quizás puedas sacarlo tú mismo. Cierra los ojos.",
    ["Skaldrun instructs you on precise breathing and mental techniques."] = "Skaldrun le instruirá sobre técnicas mentales y de respiración precisas.",
    ["What do you think about this? I found this old curio and it seems like there's a story behind it."] = "¿Qué opinas de esto? Encontré esta vieja curiosidad y parece que hay una historia detrás.",
    ["Yes, yes. There's a tale to tell here but much of it appears lost to time. Close your eyes and let's see what we can still learn."] = "Sí, sí. Hay una historia que contar aquí, pero gran parte de ella parece perdida en el tiempo. Cierra los ojos y veamos qué podemos aprender aún.",
    ["[Skaldrun instructs you on precise breathing and mental techniques.]"] = "[Skaldrun le instruirá sobre técnicas mentales y de respiración precisas.]",
    ["[As you rest your wings and sit above on the rocky cliffs, your Aughra fellows are still coming in to land.]"] = "[Mientras descansas tus alas y te sientas en los acantilados rocosos, tus compañeros Aughra todavía están aterrizando.]",
    ["[You reflect on your journey. The vision of this place you saw has yet to come to pass but you can make out the outlines, the foundations, even that odd formation of stone.]"] = "[Reflexionas sobre tu viaje. La visión de este lugar que viste aún no se ha hecho realidad, pero puedes distinguir los contornos, los cimientos e incluso esa extraña formación de piedra.]",
    ["[The blood-chilling storm that chased you all the way from Orthen continues to bluster. It clearly bothers your kin.]"] = "[La tormenta escalofriante que os persiguió desde Orthen sigue bramando. Claramente molesta a tus parientes.]",
    ["[Not you, though. You know for sure that all the hardship and quarrels will be worth it.]"] = "[Pero tú no. Sabes con certeza que todas las dificultades y peleas valdrán la pena.]",
    ["[You know that this is your new home. The new nexus of destiny for the Aughra.]"] = "[Sabes que este es tu nuevo hogar. El nuevo nexo de destino para Aughra.]",
    ["[This storm that blows through is but the precursor to the one that will free you from your dreadful curse.]"] = "[Esta tormenta que azota no es más que la precursora de la que os liberará de vuestra terrible maldición.]",
    ["[Together, as one, as the moksha, you saw this. It is with this knowledge that you lie down to sleep, bearing the bitter cold.]"] = "[Juntos, como uno solo, como moksha, visteis esto. Es con este conocimiento que te acuestas a dormir, soportando el frío intenso.]",
    ["[You lay your hammers on the ground and take a step back.]"] = "[Dejas tus martillos en el suelo y das un paso atrás.]",
    ["[You feel the sweat drip from your forehead as you crane your head back to admire your work.]"] = "[Sientes que el sudor gotea de tu frente mientras echas la cabeza hacia atrás para admirar tu trabajo.]",
    ["[A wide smile manifests on your face as you confirm it. It is done. The structure is complete. The Aughra have a new home.]"] = "[Una amplia sonrisa se manifiesta en tu rostro mientras lo confirmas. Está hecho. La estructura está completa. Los Aughra tienen un nuevo hogar.]",
    ["[You imagine the feast that will be held tonight, and after, smoking with your friends.]"] = "[Te imaginas la fiesta que se celebrará esta noche y después, fumando con tus amigos.]",
    ["[Then you realise that your work is not yet complete - it needs a name.]"] = "[Entonces te das cuenta de que tu trabajo aún no está completo: necesita un nombre.]",
    ["[Naming would come tonight too. Okken Fiarakkenven, perhaps? You are unsure if it is a good name, but you will suggest it tonight.]"] = "[El nombramiento también vendría esta noche. ¿Okken Fiarakkenven, tal vez? No estás seguro de si es un buen nombre, pero lo sugerirás esta noche.]",
    ["[Shifting your neck you feel a satisfying crack. For now, your work is done, so you wander towards the courtyard for some relaxation.]"] = "[Al mover el cuello sientes un crujido satisfactorio. Por ahora, tu trabajo ha terminado, así que caminas hacia el patio para relajarte un poco.]",
    ["[You are still not used to the grating crunch of stone that echoes around you with each turn of the cube.]"] = "[Todavía no estás acostumbrado al crujido de la piedra que resuena a tu alrededor con cada vuelta del cubo.]",
    ["[You can feel the flesh under the scales of your neck cringe at the scraping as you twist the puzzle hither and thither.]"] = "[Puedes sentir la carne debajo de las escamas de tu cuello encogerse ante el raspado mientras giras el rompecabezas de aquí para allá.]",
    ["['It is fine,' you think, repeating the old pitch to yourself. 'You need not go to the kitchen if the kitchen can come to you.']"] = "[\"Está bien\", piensas, repitiendo el viejo discurso para ti mismo. \"No es necesario que vayas a la cocina si la cocina puede acudir a ti\".]",
    ["[The door that, moments ago, led from this office into a sprawling garden reveals itself to be a gateway to that imagined kitchen.]"] = "[La puerta que, hace unos momentos, conducía desde esta oficina a un extenso jardín se revela como una puerta de entrada a esa cocina imaginada.]",
    ["[Your mind has wandered between ideas of improved efficiencies and reduction of that damnable abrasive din. Of questions of automation for a daily schedule or as a matter of security.]"] = "[Su mente ha vagado entre ideas de eficiencia mejorada y reducción de ese maldito ruido abrasivo. Por cuestiones de automatización para una agenda diaria o por una cuestión de seguridad.]",
    ["[It must have been an hour. Yes, right on schedule, the rumbling vibrations from deep below vibrate through your feet.]"] = "[Debió haber pasado una hora. Sí, justo a tiempo, las vibraciones retumbantes de lo más profundo vibran a través de tus pies.]",
    ["[You imagine the large masses of stone and dirt tumbling through their new home in the deep abyss, liberated from their dull existence in the earth.]"] = "[Te imaginas las grandes masas de piedra y tierra cayendo a través de su nuevo hogar en el profundo abismo, liberadas de su aburrida existencia en la tierra.]",
    ["[The builders appear in the eye of your mind, cleaning up and stabilising the place.]"] = "[Los constructores aparecen en el ojo de tu mente, limpiando y estabilizando el lugar.]",
    ["[More cubes to produce then, but that can wait. The glorious scent of the gallimastyx meat you have been preparing snaps you back to reality.]"] = "[Entonces habrá que producir más cubos, pero eso puede esperar. El glorioso aroma de la carne de gallimastyx que has estado preparando te devuelve a la realidad.]",
    ["[Cyan-coloured smoke fills the air as you exhale and the tiny crystals within it glitter in the light.]"] = "[El humo de color cian llena el aire al exhalar y los pequeños cristales que contiene brillan con la luz.]",
    ["[The smell is subtle but sweet, much like the plant smouldering in your pipe, and like the many flowers you have cultivated in this garden chamber.]"] = "[El olor es sutil pero dulce, muy parecido a la planta que arde en tu pipa y como a las muchas flores que has cultivado en esta cámara del jardín.]",
    ["[A deep sense of pride washes over you as you glimpse this precious vegetation, the key meditation aid of the Aughra.]"] = "[Un profundo sentimiento de orgullo te invade al vislumbrar esta preciosa vegetación, la ayuda clave para la meditación del Aughra.]",
    ["[You feel pride for your family who stowed their seeds, for none of them grow elsewhere on this planet, nor on any other planet now, thanks to the damnable Roakin.]"] = "[Te sientes orgulloso de tu familia que guardó sus semillas, porque ninguna de ellas crece en ningún otro lugar de este planeta, ni en ningún otro planeta ahora, gracias al maldito Roakin.]",
    ["[You inhale deeply from your pipe to placate the oncoming rage.]"] = "[Inhalas profundamente desde tu pipa para aplacar la ira que se avecina.]",
    ["[One day these trees...these herbs...a whole jungle of these plants will populate this place and beyond.]"] = "[Un día estos árboles... estas hierbas... toda una jungla de estas plantas poblará este lugar y más allá.]",
    ["[Each growth is a small rebellion against them and their curse upon us.]"] = "[Cada crecimiento es una pequeña rebelión contra ellos y su maldición sobre nosotros.]",
    ["[You have spent many mok with the horned people. In sleep and in trance but every time as lucid as a waking moment.]"] = "[Has pasado muchos mok con la gente con cuernos. En sueño y en trance pero siempre tan lúcido como en un momento de vigilia.]",
    ["[Many times you remember swapping knowledge, debating your philosophies, shared your existential problems but you cannot shake the feeling that somehow this time it felt different.]"] = "[Muchas veces recuerdas haber intercambiado conocimientos, debatido sobre tus filosofías, compartido tus problemas existenciales, pero no puedes evitar la sensación de que de alguna manera esta vez se sintió diferente.]",
    ["[His smile was brighter, their movements clearer, her voice sharper. You trust them deeply and they do you, it seems.]"] = "[Su sonrisa era más brillante, sus movimientos más claros, su voz más aguda. Al parecer, confías profundamente en ellos y ellos confían en ti.]",
    ["[In your hand is something new. Bright discs. Blue and green and red and gold.]"] = "[En tu mano hay algo nuevo. Discos brillantes. Azul, verde, rojo y dorado.]",
    ["[There will be a feast, you have decided, and all are welcome here.]"] = "[Habrá una fiesta, lo has decidido, y todos son bienvenidos aquí.]",
    ["[Your mind is clouded. You know not why, but you are incensed and absolutely raging. It is too much. You cry out to yourself.]"] = "[Tu mente está nublada. No sabes por qué, pero estás indignado y absolutamente furioso. Es demasiado. Te gritas a ti mismo.]",
    ["[And the cloud of anger is gone. You look down at the faintly warm stone in your hands. Yes, you have hands again. Back in your own body and breathing a sigh of relief.]"] = "[Y la nube de ira se ha ido. Miras la piedra ligeramente cálida que tienes en las manos. Sí, tienes manos otra vez. De vuelta en tu propio cuerpo y respirando aliviado.]",
    ["[Again, the sweet escape from the grip of the roakin curse is counteracted by some other addlement, the unrepealable rage of this otherwordly behemoth, or the dullness of mind in the body of a mastyx.]"] = "[Una vez más, el dulce escape de las garras de la maldición del roakin se ve contrarrestado por algún otro problema, la ira irreparable de este gigante de otro mundo o el embotamiento mental en el cuerpo de un mastyx.]",
    ["[The portal closes as you fiddle with the huge machine in the centre of the room. You begin the search anew for a creature that suits your temperament.]"] = "[El portal se cierra mientras juegas con la enorme máquina en el centro de la habitación. Comienzas de nuevo la búsqueda de una criatura que se adapte a tu temperamento.]",
    ["[You have studied them in many mok. Wandered the streets of their city. Breathed the thick smoke-dense air. Felt the gentle descent of ash from the clouds above.]"] = "[Los has estudiado en muchos mok. Vagó por las calles de su ciudad. Respiró el aire espeso y denso. Sentí el suave descenso de la ceniza desde las nubes de arriba.]",
    ["[You know their language. Their customs are no longer peculiar to you. Through your own meditations and skill of the gorajo YOU have been there, even if your body has not.]"] = "[Conoces su idioma. Sus costumbres ya no son exclusivas de vosotros. A través de tus propias meditaciones y la habilidad del gorajo TÚ has estado allí, incluso si tu cuerpo no.]",
    ["[You could be free of the curse there. You could help them. You could lead them.]"] = "[Podrías liberarte de la maldición allí. Podrías ayudarlos. Podrías guiarlos.]",
    ["[A devilish smile creeps across your face. You are them. You are not Kalger; you are Kal'Ger.]"] = "[Una sonrisa diabólica se dibuja en tu rostro. Tú eres ellos. No eres Kalger; Eres Kal'Ger.]",
    ["[We are not Aughra. We are Infernals. And now, we will be free.]"] = "[No somos Aughra. Somos Infernales. Y ahora seremos libres.]",
    ["[You swing your hammer down. The wrong technique. You swing again. Better.]"] = "[Bajas el martillo. La técnica equivocada. Te balanceas de nuevo. Mejor.]",
    ["[This is no longer a tool for building walls or repairing things. It is a tool of destruction and war.]"] = "[Esta ya no es una herramienta para construir muros o reparar cosas. Es una herramienta de destrucción y guerra.]",
    ["[For Bilrach, a necessary ally for now. He seeks his lost master.]"] = "[Para Bilrach, un aliado necesario por ahora. Busca a su maestro perdido.]",
    ["[An ally with whom we can liberate our peers from the chains of the Roakin, by using their own strength against them.]"] = "[Un aliado con el que podremos liberar a nuestros compañeros de las cadenas de los Roakin, utilizando su propia fuerza contra ellos.]",
    ["[To bring the source of our pain down on those who would deal it upon us. To become the masters of our own destiny once more.]"] = "[Para hacer caer la fuente de nuestro dolor sobre aquellos que nos lo infligirían. Para volver a ser dueños de nuestro propio destino.]",
    ["[You swing again. A crushing force that cracks the rock clean in two.]"] = "[Te balanceas de nuevo. Una fuerza aplastante que parte la roca en dos.]",
    ["[Again. Now, a fine brick to build a new future.]"] = "[De nuevo. Ahora, un buen ladrillo para construir un nuevo futuro.]",
    ["[You know this was your last mok with the horned people.]"] = "[Sabes que este fue tu último simulacro con la gente con cuernos.]",
    ["[You see the forges around you that blazed and danced with unimaginable heat, and with every colour, while your wills clashed creep and simmer back to their natural inclination.]"] = "[Ves las forjas a tu alrededor que ardieron y bailaron con un calor inimaginable y con todos los colores, mientras tus voluntades chocadas se arrastran y hierven a fuego lento hasta recuperar su inclinación natural.]",
    ["[The smell of the burning flowers fades and the cyan mist dissipates. You are alone with your own thoughts.]"] = "[El olor de las flores quemadas se desvanece y la niebla cian se disipa. Estás solo con tus propios pensamientos.]",
    ["[You know them to be correct. Bilrach is surely mad, but you have resolved to bear the burden.]"] = "[Sabes que son correctos. Seguramente Bilrach está loco, pero usted ha decidido soportar la carga.]",
    ["[Deeper in the earth, as deep in your own heart, there is a light of hope for the freedom of all: Aughra, Syrtes, Nodon and Dactyl alike.]"] = "[En lo más profundo de la tierra, como en lo profundo de tu propio corazón, hay una luz de esperanza para la libertad de todos: Aughra, Syrtes, Nodon y Dactyl por igual.]",
    ["[A wave of invigorating power crashes into you, almost knocking you flying. As you catch your footing you see the creature shrivel and pulse.]"] = "[Una ola de poder vigorizante choca contra ti y casi te hace volar. Cuando recuperas el equilibrio, ves a la criatura encogerse y palpitar.]",
    ["[You are fascinated at the sight of Bilrach's figure, at first warped, perhaps by the mangling nature of these depths. It writhes and molds itself away from its vile skeletal presence to become something almost appealing.]"] = "[Quedas fascinado al ver la figura de Bilrach, al principio deformada, tal vez por la naturaleza destrozada de estas profundidades. Se retuerce y se moldea a partir de su vil presencia esquelética para convertirse en algo casi atractivo.]",
    ["[You ponder if this is how others see you when your own power manifests within a new form. Does the strength you imbue radiate outward?]"] = "[Te preguntas si así es como te ven los demás cuando tu propio poder se manifiesta en una nueva forma. ¿La fuerza que infundes se irradia hacia afuera?]",
    ["[You question whether the broken personalities you have seen manifest of late are a weakness of the host or of the will within.]"] = "[Te preguntas si las personalidades rotas que has visto manifestarse últimamente son una debilidad del anfitrión o de la voluntad interior.]",
    ["[What might happen if it were a god? There is no time to consider these things, for we have already approached the verge of destiny.]"] = "[¿Qué pasaría si fuera un dios? No hay tiempo para considerar estas cosas, porque ya nos hemos acercado al borde del destino.]",
    ["Mystery Uncovered: '[name]'."] = "Misterio descubierto: '[name]'.",
    ["You transcribe the memory into your archaeology journal."] = "Transcribes the memory en tu diario de arqueología.",
    ["You fail to keep your focus and the experience fades."] = "No logras mantener tu concentración y la experiencia se desvanece.",
    ["It seems that's all that we can glean from this."] = "Parece que eso es todo lo que podemos deducir de esto.",
    ["cond=After uncovering the mystery"] = "cond=Después de descubrir el misterio",
    ["We've made some great progress, but I feel like there are more memories to uncover."] = "Hemos logrado grandes avances, pero siento que hay más recuerdos por descubrir.",
    ["You gain 19,500 Archaeology XP for completing a mystery!"] = "¡Ganas 19,500 Archaeology XP por completar un misterio!",
    ["Congratulations! You have completed: 'A New Home' - Solve this mystery."] = "¡Felicitaciones! Has completado: 'Un nuevo hogar' - Resuelve este misterio.",
    ["We seem to have experienced, if only briefly, some snippets of the lives of those who first settled here."] = "Parece que hemos experimentado, aunque sea brevemente, algunos fragmentos de las vidas de quienes se establecieron aquí por primera vez.",
    ["Yes! It was definitely the Aughra dragonkin! They came here to find a way to escape the curse of the elder gods."] = "¡Sí! ¡Definitivamente fueron los dragonantes Aughra! Vinieron aquí para encontrar una manera de escapar de la maldición de los dioses mayores.",
    ["And the horned people must be the gorajo, of which I've learned from other stories."] = "Y la gente con cuernos debe ser el gorajo, del cual he aprendido por otras historias.",
    ["Well done. There are always more stories, but I feel we've found enough evidence for me to make a site report."] = "Bien hecho. Siempre hay más historias, pero creo que hemos encontrado evidencia suficiente para hacer un informe del sitio.",
    ["Return to me if you find anything else of interest."] = "Vuelve conmigo si encuentras algo más de interés.",
    ["We've made some good progress, but we still have more to learn before I can make a report."] = "Hemos logrado algunos buenos avances, pero todavía tenemos más que aprender antes de poder hacer un informe.",
    ["You gain 67,000 Archaeology XP for completing a mystery!"] = "¡Ganas 67 000 Archaeology XP por completar un misterio!",
    ["Congratulations! You have completed: 'A New Form' - Solve this mystery."] = "¡Felicitaciones! Has completado: 'Una nueva forma' - Resuelve este misterio.",
    ["The Aughra dragonkin somehow became the Infernal demons and allied with Bilrach!"] = "¡Los dragonantes Aughra de alguna manera se convirtieron en demonios infernales y se aliaron con Bilrach!",
    ["It would appear so, to escape their curse."] = "Eso parece, para escapar de su maldición.",
    ["It seems like they were planning something else down there, but what?"] = "Parece que estaban planeando algo más ahí abajo, pero ¿qué?",
    ["For now, we can only speculate. This will do nicely for a site report."] = "Por ahora, sólo podemos especular. Esto funcionará muy bien para un informe del sitio.",
    ["cond=After having inspected the strange token"] = "cond=Después de haber inspeccionado el token extraño",
    ["Hey Skaldrun, I happened across a strange token in Daemonheim. It doesn't feel like it belongs here."] = "Hola Skaldrun, me encontré con un token extraño en Daemonheim. No parece que pertenezca aquí.",
    ["Hey Skaldrun, Could you check if there's another imbued memory?"] = "Hola Skaldrun, ¿podrías comprobar si hay otro recuerdo imbuido?",
    ["If you pass it to me, I can take a look."] = "Si me lo pasas puedo echarle un vistazo.",
    ["I seem to have misplaced it. I'll return once I've located it or dug up another so you can inspect it."] = "Parece que lo he extraviado. Regresaré una vez que lo haya localizado o desenterrado otro para que puedas inspeccionarlo.",
    ["Hey Skaldrun, I happened to find this token in Daemonheim. It doesn't feel like it belongs here. Could you check if there's another imbued memory?"] = "Hola Skaldrun, encontré este token en Daemonheim. No parece que pertenezca aquí. ¿Podrías comprobar si hay otro recuerdo imbuido?",
    ["Pass it to me, and I'll take a look."] = "Pásamelo y le echaré un vistazo.",
    ["[Skaldrun wavers and stumbles.]"] = "[Skaldrun vacila y tropieza.]",
    ["[As you grab Skaldrun's shoulders another experience emerges...]"] = "[Mientras agarras los hombros de Skaldrun, surge otra experiencia...]",
    ["[You are running, struggling to catch your breath. You need to get out of here. To reach the surface and get far, far away.]"] = "[Estás corriendo, luchando por recuperar el aliento. Tienes que salir de aquí. Llegar a la superficie y llegar muy, muy lejos.]",
    ["[Everyone you pass gives you an odd look: confusion...concern...suspicion... You've been running for a long time. Now you're starting to get tired.]"] = "[Todo el mundo con el que te cruzas te mira de forma extraña: confusión...preocupación...sospecha... Has estado huyendo durante mucho tiempo. Ahora estás empezando a cansarte.]",
    ["[A chill wind rushes down the stairs. There isn't much further to go. You can do this. You turn a corner and come crashing to the ground.]"] = "[Un viento helado baja las escaleras. No queda mucho más por recorrer. Puedes hacer esto. Doblas una esquina y caes al suelo.]",
    ["[Bathed in shadow, your eyes go wide as you look up to its source. A huge, imposing figure stares down at you.]"] = "[Bañado en sombras, tus ojos se abren cuando miras hacia su fuente. Una figura enorme e imponente te mira fijamente.]",
    ["Where are you going, scribe? Grindle... Grondu..."] = "¿A dónde vas, escriba? Grindle...Grondu...",
    ["[You swallow before meekly correcting him.]"] = "[Tragas saliva antes de corregirlo dócilmente.]",
    ["It's Grondaban. To'Kash, I must..."] = "Es Grondaban. To'Kash, debo...",
    ["[You feel the cold ever more deeply.]"] = "[Sientes el frío cada vez más profundamente.]",
    ["I have to go."] = "Me tengo que ir.",
    ["[You feel your head start to get heavy as you turn and try to walk away.]"] = "[Sientes que tu cabeza comienza a pesarse cuando te giras y tratas de alejarte.]",
    ["Now, now, scribe. There's no rush. Sleep now."] = "Ahora, ahora, escriba. No hay prisa. Duerme ahora.",
    ["[And you pass out.]"] = "[Y te desmayas.]",
    ["That was you?"] = "¿Eras tú?",
    ["You wrote all of those journals I keep finding around Daemonheim."] = "Escribiste todos esos diarios que sigo encontrando sobre Daemonheim.",
    ["Y-yes, it appears so. I remember some of that now. That token is mine. Proof of membership for my druidic order."] = "S-sí, eso parece. Recuerdo algo de eso ahora. Esa ficha es mía. Prueba de membresía de mi orden druídica.",
    ["Where were you going? What did you need to reveal? Do you know what's down there at the very bottom of Daemonheim?"] = "¿Adónde ibas? ¿Qué necesitabas revelar? ¿Sabes qué hay ahí abajo en la parte inferior de Daemonheim?",
    ["Please, let me think..."] = "Por favor, déjame pensar...",
    ["I came under Bilrach's employ as a researcher and scribe. I was undercover to find out what was happening here."] = "Entré a trabajar para Bilrach como investigador y escriba. Estaba encubierto para descubrir qué estaba pasando aquí.",
    ["They were on the edge of bringing Zamorak back to this world. To bypass the Edicts of Guthix. That's why I was running."] = "Estaban a punto de traer a Zamorak de vuelta a este mundo. Para eludir los Edictos de Guthix. Por eso estaba corriendo.",
    ["I finally found out what they were doing and that plan was merely months away from completion."] = "Finalmente descubrí lo que estaban haciendo y faltaban solo unos meses para que se completara el plan.",
    ["But the Edicts fell when Guthix died. Zamorak came back on his own."] = "Pero los Edictos cayeron cuando Guthix murió. Zamorak regresó solo.",
    ["And the new Edicts are keeping the gods out."] = "Y los nuevos Edictos mantienen alejados a los dioses.",
    ["Wait. Could they try it again? How did this plan even work?"] = "Espera. ¿Podrían intentarlo de nuevo? ¿Cómo funcionó este plan?",
    ["What have you learned as you have undergone this excavation project?"] = "¿Qué has aprendido durante este proyecto de excavación?",
    ["Well..."] = "Bueno...",
    ["The Aughra dragonkin were drawn to this place in the distant past."] = "Los dragonantes Aughra fueron atraídos a este lugar en un pasado lejano.",
    ["They built the castle and dug out a massive fortress beneath it to live in."] = "Construyeron el castillo y excavaron una enorme fortaleza debajo para vivir.",
    ["The shifting dungeons were built for convenience, but also security, which is why it took Bilrach so long to descend."] = "Las mazmorras móviles se construyeron para brindar comodidad, pero también seguridad, razón por la cual Bilrach tardó tanto en descender.",
    ["They used a combination of their mysticism, summoning practices and technology to transfer their consciousnesses into the ruling demon class of Infernus."] = "Usaron una combinación de su misticismo, prácticas de invocación y tecnología para transferir sus conciencias a la clase demoníaca gobernante de Infernus.",
    ["They were eventually defeated and exiled."] = "Finalmente fueron derrotados y exiliados.",
    ["Some of the survivors became known as Kal'Gerions, and allied themselves with Bilrach."] = "Algunos de los supervivientes se hicieron conocidos como Kal'Gerions y se aliaron con Bilrach.",
    ["There's apparently some kind of massive rift in the deepest level of the complex."] = "Aparentemente hay algún tipo de grieta masiva en el nivel más profundo del complejo.",
    ["The Edicts block the gods' teleportation magic so that still wouldn't be any use, surely."] = "Los Edictos bloquean la magia de teletransportación de los dioses, por lo que seguramente aún así no serviría de nada.",
    ["Keep thinking. What else have you learned?"] = "Sigue pensando. ¿Qué más has aprendido?",
    ["Wait, the Aughra transfered their essence - the mind, the soul. The personality. Their whole self, everything except for the body."] = "Espera, los Aughra transfirieron su esencia: la mente, el alma. La personalidad. Todo su ser, todo menos el cuerpo.",
    ["Is that possible for a god?"] = "¿Es eso posible para un dios?",
    ["Yes, I remember. That was their plan. You saw that great machine in the depths?"] = "Sí, lo recuerdo. Ese era su plan. ¿Viste esa gran máquina en las profundidades?",
    ["I did. We could destroy it, but what would stop them rebuilding it?"] = "Lo hice. Podríamos destruirlo, pero ¿qué les impediría reconstruirlo?",
    ["And who would be the vessel? Bilrach himself?"] = "¿Y quién sería el barco? ¿El propio Bilrach?",
    ["I do not know what manner of being could contain the essence of a god."] = "No sé qué clase de ser podría contener la esencia de un dios.",
    ["Could Bilrach do it? Maybe. Maybe it would have destroyed him."] = "¿Podría Bilrach hacerlo? Tal vez. Quizás lo habría destruido.",
    ["I need to find out if the new Edicts will work. I'll be back."] = "Necesito saber si los nuevos Edictos funcionarán. Vuelvo enseguida.",
    ["Valluta, who guards the borders of this world, will probably be the best to ask."] = "Valluta, que guarda las fronteras de este mundo, probablemente será el mejor a quien preguntar.",
    ["I most recently saw the Valluta at the Lost Grove - I should head there and talk to her."] = "Recientemente vi a Valluta en Lost Grove. Debería ir allí y hablar con ella.",
    ["Ah, our resident smuggler informed me that a delivery has arrived for you. He told me to tell you he is setting up in the warped depths behind the imposing door."] = "Ah, nuestro contrabandista residente me informó que llegó una entrega para ti. Me dijo que te dijera que se está instalando en las profundidades retorcidas detrás de la imponente puerta.",
    ["Good news! We've tested the theory as far as we can. The experiment failed. I don't think we should be worried about Zamorak coming back this way."] = "¡Buenas noticias! Hemos probado la teoría tanto como hemos podido. El experimento fracasó. No creo que debamos preocuparnos de que Zamorak regrese así.",
    ["I am glad to hear that. The new Edicts must be much more powerful now."] = "Me alegra oír eso. Los nuevos Edictos deben ser ahora mucho más poderosos.",
    ["But shouldn't we still be worried about that rift and what could lie on the other side?"] = "¿Pero no deberíamos seguir preocupados por esa brecha y por lo que podría haber al otro lado?",
    ["For now, it is dormant, sealed and no threat in its present state."] = "Por ahora, está inactivo, sellado y no representa ninguna amenaza en su estado actual.",
    ["For now, we can rest in the knowledge that the Zamorakians can't achieve their original goal."] = "Por ahora, podemos estar tranquilos sabiendo que los zamorakianos no pueden lograr su objetivo original.",
    ["I suppose it's not urgent. I'm just glad that I don't have to deal with yet another world-ending threat."] = "Supongo que no es urgente. Me alegro de no tener que lidiar con otra amenaza que acabe con el mundo.",
    ["Have you recovered any more of your memory?"] = "¿Has recuperado algo más de tu memoria?",
    ["I fear it is no longer mine. I remember some of my time as Bilrach's scribe and nothing else."] = "Me temo que ya no es mío. Recuerdo parte de mi época como escriba de Bilrach y nada más.",
    ["I am no longer Grondaban. But I am not sad, for now I am Skaldrun of the Fremennik."] = "Ya no soy Grondaban. Pero no estoy triste, por ahora soy Skaldrun del Fremennik.",
    ["I will continue to collect and share tales of this place, and take joy in their telling."] = "Continuaré recopilando y compartiendo historias de este lugar, y disfrutaré contándolas.",
    ["Congratulations! You have completed: 'A New Age' - Solve this mystery."] = "¡Felicitaciones! Has completado: 'Una Nueva Era' - Resuelve este misterio.",
    ["Congratulations! You have completed: 'Mysteries - Daemonheim' - Complete all of the listed achievements."] = "¡Felicitaciones! Has completado: 'Misterios - Daemonheim' - Completa todos los logros enumerados.",
    ["Thank you, Skaldrun."] = "Gracias, Skaldrun.",
    ["Discuss the dig site."] = "Discuta el sitio de excavación.",
    ["I'll await your return."] = "Esperaré tu regreso.",
    ["I just came to chat."] = "Sólo vine a charlar.",
    ["Chat? It's been so long since I've had a simple conversation!"] = "¿Chatear? ¡Ha pasado tanto tiempo desde que tuve una conversación sencilla!",
    ["What can you tell me about yourself?"] = "¿Qué puedes decirme sobre ti?",
    ["It's clear that I am a keeper of stories and a teller of tales."] = "Está claro que soy un guardián de historias y un narrador de cuentos.",
    ["Can you tele anything about yourself other than that?"] = "¿Puedes transmitir algo sobre ti además de eso?",
    ["I'm not sure there is anything beyond stories any more."] = "Ya no estoy seguro de que haya nada más allá de las historias.",
    ["I remember small fragments...but I'm not sure they are even my fragments. There are small moments from a childhood: growing up in a settlement named after a hero. I remember chronicling life in Daemonheim for someone. A man, perhaps? I can almost remember a name - almost - but every time I get close to remembering it, it runs away, mocking."] = "Recuerdo pequeños fragmentos... pero no estoy seguro de que sean siquiera mis fragmentos. Hay pequeños momentos de la infancia: crecer en un asentamiento que lleva el nombre de un héroe. Recuerdo haber hecho una crónica de la vida de alguien en Daemonheim. ¿Un hombre, tal vez? Casi puedo recordar un nombre - casi - pero cada vez que estoy cerca de recordarlo, huye burlándose.",
    ["How does that make you feel?"] = "¿Cómo te hace sentir eso?",
    ["I'm not sure. Part of me wonders if I lost my memories on purpose, hiding from who I was. Could I have been so terrible that even I wished to forget myself?"] = "No estoy seguro. Una parte de mí se pregunta si perdí mis recuerdos a propósito, escondiéndome de quién era. ¿Podría haber sido tan terrible que incluso yo deseara olvidarme de mí mismo?",
    ["Do you remember being a horrible person?"] = "¿Recuerdas haber sido una persona horrible?",
    ["No...but then I don't remember being a nice person either."] = "No... pero tampoco recuerdo haber sido una buena persona.",
    ["Aren't you called Skaldrun?"] = "¿No te llamas Skaldrun?",
    ["That's the name the Fremennik have given me. I rather like it."] = "Ese es el nombre que me han dado los Fremennik. Más bien me gusta.",
    ["Is there any way I can help you remember?"] = "¿Hay alguna manera de ayudarte a recordar?",
    ["Perhaps. I no doubt wandered the depths of Daemonheim, so there is a chance I left something behind."] = "Quizás. Sin duda deambulé por las profundidades de Daemonheim, por lo que existe la posibilidad de que haya dejado algo atrás.",
    ["As you go about the dungeons, keep an eye open for things of interest; if they're not mine then they may at least remind me of a story."] = "Mientras recorre las mazmorras, esté atento a las cosas de interés; Si no son míos, al menos tal vez me recuerden una historia.",
    ["How long were you frozen in that block of ice?"] = "¿Cuánto tiempo estuviste congelado en ese bloque de hielo?",
    ["Centuries. I was frozen well before the current Age."] = "Siglos. Me congelé mucho antes de la Era actual.",
    ["What? You're centuries old?"] = "¿Qué? ¿Tienes siglos de antigüedad?",
    ["Oh yes, possibly older. I don't remember."] = "Oh, sí, posiblemente mayor. No lo recuerdo.",
    ["How did it feel, being frozen in ice for so long?"] = "¿Cómo te sentiste al estar congelado en hielo durante tanto tiempo?",
    ["How do you think it felt?"] = "¿Cómo crees que te sentiste?",
    ["It was torture. Imagine staring at the same spot for centuries, never blinking, never moving, never able to look away. Imagine that spot never changed."] = "Fue una tortura. Imagínese estar mirando el mismo lugar durante siglos, sin parpadear, sin moverse, sin poder apartar la mirada. Imagínese que ese lugar nunca cambió.",
    ["I went mad, just as anyone would in my situation. Complete insanity. It was a welcome relief, a break from the endless tedium of that single vision."] = "Me volví loco, como lo haría cualquiera en mi situación. Completa locura. Fue un alivio bienvenido, un descanso del interminable tedio de esa única visión.",
    ["But, soon enough, I became bored of the madness. Even my wayward mind couldn't save me from the banality of my situation. So, I turned to stories and let them grow, let them take me over for a while."] = "Pero pronto me aburrí de la locura. Ni siquiera mi mente descarriada pudo salvarme de la banalidad de mi situación. Así que recurrí a las historias y las dejé crecer, dejé que se apoderaran de mí por un tiempo.",
    ["They freed me. They took me away from my situation and let me experience amazing adventures."] = "Me liberaron. Me sacaron de mi situación y me dejaron vivir aventuras increíbles.",
    ["During those stories, I found a way to become part of the tale, to be the protagonist. It was amazing and liberating."] = "Durante esas historias, encontré una manera de convertirme en parte del cuento, de ser el protagonista. Fue sorprendente y liberador.",
    ["Until you freed me, I spent my time in those stories, living their lives. The magic of my curse served to attract more stories as they occured around me, giving me a limitless supply of tales and adventures."] = "Hasta que me liberaste, pasé mi tiempo en esas historias, viviendo sus vidas. La magia de mi maldición sirvió para atraer más historias a medida que ocurrían a mi alrededor, dándome un suministro ilimitado de cuentos y aventuras.",
    ["How did you end up trapped in the first place?"] = "¿Cómo terminaste atrapado en primer lugar?",
    ["I don't remember. I think it was an accident, a cave-in perhaps, but I'm not sure. I half-remember laughter, but that is either real or a figment of a tortured mind. I cannot say."] = "No lo recuerdo. Creo que fue un accidente, tal vez un derrumbe, pero no estoy seguro. Recuerdo a medias la risa, pero es real o producto de una mente torturada. No puedo decirlo.",
    ["How do these stories work?"] = "¿Cómo funcionan estas historias?",
    ["They began as merely words and memories: tales to recall and little else. But stories have a magic of their own, and I learned to isolate and grow that magic to the degree that I was drawn into them, body and soul."] = "Comenzaron como meras palabras y recuerdos: cuentos para recordar y poco más. Pero las historias tienen una magia propia, y aprendí a aislar y hacer crecer esa magia en la medida en que me sentí atraído por ellas, en cuerpo y alma.",
    ["I was able to live within the stories. While I couldn't change their beginnings or ends, I could influence how the story played out."] = "Pude vivir dentro de las historias. Si bien no podía cambiar sus comienzos ni sus finales, podía influir en cómo se desarrolló la historia.",
    ["All stories are like that to me, and I can step into them as easily as you could step into a room."] = "Todas las historias son así para mí y puedo entrar en ellas tan fácilmente como tú entras en una habitación.",
    ["I feel that I could take you with me. You could step into my stories and live them, just as I can."] = "Siento que podría llevarte conmigo. Podrías adentrarte en mis historias y vivirlas, tal como yo puedo.",
    ["How do you remember all of these stories?"] = "¿Cómo recuerdas todas estas historias?",
    ["Imagine a library, a great building with books from wall to wall; a veritable labyrinth of literature with each book acting as a piece of history, someone's adventures, someone's life. I wander that library in my head."] = "Imagina una biblioteca, un gran edificio con libros de pared a pared; un verdadero laberinto de literatura en el que cada libro actúa como un fragmento de historia, las aventuras de alguien, la vida de alguien. Deambulo por esa biblioteca en mi cabeza.",
    ["So, you have books on everyone?"] = "Entonces, ¿tienes libros sobre todos?",
    ["Oh, some people have a single, thin book. Yet, you have an entire bookcase dedicated to your adventures: some tomes written and others empty, awaiting ink."] = "Oh, algunas personas tienen un solo libro delgado. Sin embargo, tienes una estantería entera dedicada a tus aventuras: algunos tomos escritos y otros vacíos, esperando tinta.",
    ["The only books I cannot find are my own."] = "Los únicos libros que no puedo encontrar son los míos.",
    ["So, how does your curse work?"] = "Entonces, ¿cómo funciona tu maldición?",
    ["I have glimpses of my past, a past where I chronicled life in the depths of Daemonheim. I remember a collection of journals, of them being torn apart and scattered across the dungeon."] = "Tengo destellos de mi pasado, un pasado en el que hice una crónica de la vida en las profundidades de Daemonheim. Recuerdo una colección de diarios, de ellos rotos y esparcidos por el calabozo.",
    ["I recall being told that the journals weren't safe, that anyone could get their hands on them, and that I would be a more suitable receptacle for the information..."] = "Recuerdo que me dijeron que los diarios no eran seguros, que cualquiera podía tenerlos en sus manos y que yo sería un receptáculo más adecuado para la información...",
    ["To ensure the information could be readily accessed, I was granted a mockery of immortality: a body that would neither age nor crumble over the aeons, a body without a heartbeat, stripped o life to fuel this perpetual existence."] = "Para garantizar que se pudiera acceder fácilmente a la información, se me concedió una burla de la inmortalidad: un cuerpo que no envejecería ni se desmoronaría con el paso de los eones, un cuerpo sin latidos, despojado de vida para alimentar esta existencia perpetua.",
    ["Then I was given the second part of my 'gift'."] = "Luego me dieron la segunda parte de mi 'regalo'.",
    ["My mind would become a journal for everything that happened within Daemonheim, storing everything within those dungeons as a library in my mind."] = "Mi mente se convertiría en un diario de todo lo que sucediera dentro de Daemonheim, almacenando todo dentro de esas mazmorras como una biblioteca en mi mente.",
    ["That's all I remember of the curse. I know that the curse forced me to forget who I was. There was no room in my head for unimportant things like memories of self."] = "Eso es todo lo que recuerdo de la maldición. Sé que la maldición me obligó a olvidar quién era. No había lugar en mi cabeza para cosas sin importancia como recuerdos de mí mismo.",
    ["But, although I had become forgotten, the curse became a gift, and the stories saved me from a fate I would not wish on anyone."] = "Pero, aunque me habían olvidado, la maldición se convirtió en un regalo y las historias me salvaron de un destino que no le desearía a nadie.",
    ["How are you enjoying life on the surface?"] = "¿Cómo disfrutas la vida en la superficie?",
    ["Oh, it's fantastic. The Fremennik are so interesting; so noble and brave, and those that guard the dungeons are doubly so."] = "Oh, es fantástico. Los Fremennik son muy interesantes; tan nobles y valientes, y los que guardan las mazmorras lo son doblemente.",
    ["At campfires, I've been telling them stories of their ancestors, and they seem to rather enjoy them. So, yes, I'm very happy here. Thank you so much, Player."] = "En las fogatas, les he estado contando historias de sus antepasados y parecen disfrutarlas. Entonces sí, estoy muy feliz aquí. Muchas gracias, Player.",
    ["I'll leave you be."] = "Te dejaré en paz.",
    ["Very well. My tales will be here should you wish to hear them."] = "Muy bien. Mis cuentos estarán aquí si deseas escucharlos.",
    ["Tell Skaldrun about the bearskin?"] = "¿Cuéntale a Skaldrun sobre la piel de oso?",
    ["I found this bearskin in the dungeon, it seemed out of place."] = "Encontré esta piel de oso en el calabozo, parecía fuera de lugar.",
    ["Ah, yes, that skin. It belonged to an animal, which, in turn, belonged to a cruel and malevolent individual."] = "Ah, sí, esa piel. Pertenecía a un animal, que, a su vez, pertenecía a un individuo cruel y malévolo.",
    ["But he is not the hero of the story. No, there are three heroes in this tale, each working side by side. Perhaps you'd like to hear more?"] = "Pero él no es el héroe de la historia. No, hay tres héroes en esta historia, cada uno de los cuales trabaja codo con codo. ¿Quizás le gustaría saber más?",
    ["Play a saga?"] = "¿Jugar una saga?",
    ["No, not just yet."] = "No, todavía no.",
    ["Well if you're sure. If you do want to hear a story, I am here."] = "Bueno, si estás seguro. Si quieres escuchar una historia, estoy aquí.",
    ["Tell Skaldrun about the sword collection?"] = "¿Cuéntale a Skaldrun sobre la colección de espadas?",
    ["I found this strange collection of swords, all arranged together like a sort of memorial. Does it mean anything to you?"] = "Encontré esta extraña colección de espadas, todas dispuestas juntas como una especie de monumento conmemorativo. ¿Significa algo para ti?",
    ["Few emotions can be as overpowering as the thirst for retribution, and fewer still can be so destructive to others and, ultimately, ourselves."] = "Pocas emociones pueden ser tan abrumadoras como la sed de venganza, y menos aún pueden ser tan destructivas para los demás y, en última instancia, para nosotros mismos.",
    ["Tell Skaldrun about the damaged device?"] = "¿Cuéntale a Skaldrun sobre el dispositivo dañado?",
    ["I found a strange device on my travels. It seems broken, but perhaps you know of its purpose?"] = "Encontré un dispositivo extraño en mis viajes. Parece roto, pero ¿quizás conoces su propósito?",
    ["This device, damaged or not, still yields a tale as powerful as any ancient tome."] = "Este dispositivo, dañado o no, todavía ofrece una historia tan poderosa como cualquier tomo antiguo.",
    ["A tale of corruption and revelation awaits you when you have the time."] = "Una historia de corrupción y revelaciones te espera cuando tengas tiempo.",
    ["Tell Skaldrun about the badly scrawled note?"] = "¿Contarle a Skaldrun sobre la nota mal garabateada?",
    ["I found this illegible note on the floor. Mean anything to you?"] = "Encontré esta nota ilegible en el suelo. ¿Significa algo para ti?",
    ["Oh, yes, I recognize that story!"] = "¡Oh, sí, reconozco esa historia!",
    ["This is a tale of daring heroism, staggering displays of strength and skill and, most importantly, a mighty Fremennik warrior called Thok."] = "Esta es una historia de heroísmo audaz, asombrosas demostraciones de fuerza y habilidad y, lo más importante, un poderoso Fremennik warrior llamado Thok.",
    ["Oh...and his brother Marmaros is in it too."] = "Ah... y su hermano Marmaros también está en esto.",
    ["Tell Skaldrun about the rock and twine bundle?"] = "¿Cuéntale a Skaldrun sobre el paquete de piedras y cordeles?",
    ["I found this...thing...while exploring. I have no idea what it's for."] = "Encontré esta... cosa... mientras exploraba. No tengo idea para qué sirve.",
    ["Oh my, it's magnificent!"] = "¡Dios mío, es magnífico!",
    ["In fact, it does remind me of a tale, one that involves the search for a lost weapon and two mighty brothers, Thok and Marmaros."] = "De hecho, me recuerda a una historia que involucra la búsqueda de un arma perdida y dos hermanos poderosos, Thok y Marmaros.",
    ["Perhaps you should hear of their earlier exploits first before I tell this tale."] = "Quizás deberías oír hablar de sus hazañas anteriores antes de contar esta historia.",
    ["You don't have a spooking tool to spook this enemy with."] = "No tienes una herramienta aterradora para asustar a este enemigo.",
    ["Are you ready for the fight? If you leave the battle before the end, the Skeletal horror will regenerate and you will have to start again from scratch."] = "¿Estás listo para la pelea? Si abandonas la batalla antes del final, el Skeletal horror se regenerará y tendrás que empezar de nuevo desde cero.",
    ["You dig a hole in the ground and bury the bone. <!-- filtered -->"] = "Cavas un hoyo en el suelo y entierras el hueso. <!-- filtered -->",
    ["The skeletal horror's limb vanishes as you kill the skeletal horror."] = "La extremidad del skeletal horror desaparece cuando matas al skeletal horror.",
    ["As the creature is defeated, you gain [number] Prayer and [number] Slayer XP."] = "A medida que la criatura es derrotada, obtienes [número] Prayer y [número] Slayer XP.",
    ["Your bone club breaks."] = "Tu garrote de huesos se rompe.",
    ["These are the private vaults of His Fleshiness, Zemouregal. Go away."] = "Estas son las bóvedas privadas de Su Carnosidad, Zemouregal. Vete.",
    ["I want to access my bank."] = "Quiero acceder a mi banco.",
    ["The bank of New Varrock is now the personal treasury of our glorious leader, Zemouregal. We no longer provide a banking service to fleshy folk."] = "El banco de New Varrock es ahora el tesoro personal de nuestro glorioso líder, Zemouregal. Ya no brindamos servicios bancarios a gente carnosa.",
    ["I have no idea why you are in the private vaults of Zemouregal. Begone."] = "No tengo idea de por qué estás en las bóvedas privadas de Zemouregal. Vete.",
    ["This is the far-superior eastern vaults of Zemouregal. We have protected the treasure of Magnificent Zemouregal at least fifty times better than the western vaults."] = "Estas son las bóvedas orientales muy superiores de Zemouregal. Hemos protegido el tesoro del Magnífico Zemouregal al menos cincuenta veces mejor que las bóvedas occidentales.",
    ["Speak to Skillchipx for more information."] = "Hable con Skillchipx para obtener más información.",
    ["Hello, have you come to help?"] = "Hola, ¿has venido a ayudar?",
    ["Maybe? What do you need?"] = "¿Quizás? ¿Qué necesitas?",
    ["Great, I could do with some help with a few jobs I've been given."] = "Genial, me vendría bien un poco de ayuda con algunos trabajos que me han asignado.",
    ["How many are there?"] = "¿Cuántos hay?",
    ["There are eight tasks, and if you help me with those, I'll find a special reward for you."] = "Hay ocho tareas y si me ayudas con ellas, encontraré una recompensa especial para ti.",
    ["What do I need to do?"] = "¿Qué necesito hacer?",
    ["*(If there isn't space in the player's inventory:)*"] = "*(Si no hay espacio en el inventario de el player:)*",
    ["I've got a list here, but you don't have any space for it."] = "Tengo una lista aquí, pero no tienes espacio para ella.",
    ["*(If there is space in the player's inventory:)*"] = "*(Si hay espacio en el inventario de el player:)*",
    ["Take this, it details all the tasks required."] = "Toma esto, detalla todas las tareas requeridas.",
    ["Ok, thanks!"] = "¡Vale, gracias!",
    ["*(If there are unclaimed reward lamps:)*"] = "*(Si hay lámparas de recompensa no reclamadas:)*",
    ["*(If there is no space in inventory:)*"] = "*(Si no hay espacio en el inventario:)*",
    ["You have earned a small prismatic lamp, but you don't have any space for it. Talk to Skillchipx when you have space to claim it."] = "Te has ganado una pequeña lámpara prismática, pero no tienes espacio para ella. Habla con Skillchipx cuando tengas espacio para reclamarlo.",
    ["Your small prismatic lamp for completing [location] chip task has been added to your inventory."] = "Su pequeña lámpara prismática para completar la tarea del chip [location] se ha agregado a su inventario.",
    ["RuneFest Tasks"] = "Tareas de RuneFest",
    ["*(If the list has been lost:)*"] = "*(Si la lista se ha perdido:)*",
    ["*(If the list is still owned:)*"] = "*(Si la lista aún es propiedad:)*",
    ["I've given you a list with all the tasks details on it already."] = "Ya te he dado una lista con todos los detalles de las tareas.",
    ["Special Flour"] = "Harina Especial",
    ["Well I was trying to make some special flour in the nearby windmill for RuneFest but the controls seemed to have got jammed?"] = "Bueno, estaba intentando hacer un poco de harina especial en el molino de viento cercano para RuneFest pero los controles parecían haberse atascado.",
    ["Want me to take a look?"] = "¿Quieres que le eche un vistazo?",
    ["That'd be great. Perhaps some combination with the levers might do the trick."] = "Eso sería genial. Quizás alguna combinación con las palancas pueda funcionar.",
    ["Try moving them up and down a couple of times, then left and right a couple of times."] = "Intente moverlos hacia arriba y hacia abajo un par de veces, luego hacia la izquierda y hacia la derecha un par de veces.",
    ["It might be, who can say. Let me know what happens."] = "Podría ser, quién sabe. Déjame saber qué pasa.",
    ["I see you've got some of the Special Flour I asked for..."] = "Veo que tienes un poco de la Harina Especial que pedí...",
    ["No problem."] = "No hay problema.",
    ["You've made the Special Flour and have unlocked a skill chip!"] = "¡Has hecho la Harina Especial y has desbloqueado un chip de habilidad!",
    ["You have earned a small prismatic lamp. It has been added to your inventory."] = "Te has ganado una pequeña lámpara prismática. Se ha agregado a su inventario.",
    ["*(If the player has unlocked all the skill chips:)*"] = "*(Si el player ha desbloqueado todas las fichas de habilidad:)*",
    ["Congratulations! You've completed this year's RuneFest tasks for Skillchipx!"] = "¡Felicitaciones! ¡Has completado las tareas de RuneFest de este año para Skillchipx!",
    ["You have earned a medium prismatic lamp. It has been added to your inventory."] = "Te has ganado una lámpara prismática mediana. Se ha agregado a su inventario.",
    ["*(As before.)*"] = "*(Como antes.)*",
    ["Thanks for your help with the flour, that's one more off the list."] = "Gracias por tu ayuda con la harina, esa es una más fuera de la lista.",
    ["Hello, Player. Thanks for all your help with the tasks. Don't forget, if you've got a high enough construction level you can display your Skillchips in your house."] = "Hola, Player. Gracias por toda tu ayuda con las tareas. No lo olvides, si tienes un nivel de construcción lo suficientemente alto, puedes exhibir tus Skillchips en tu casa.",
    ["*If you have already completed the Mogre lore activity*"] = "*Si ya has completado la actividad histórica de Mogre*",
    ["Hey, Skippy."] = "Hola, Skippy.",
    ["Hey you!"] = "¡Hola, tú!",
    ["How do I annoy the Mogres again?"] = "¿Cómo puedo volver a molestar a los Mogres?",
    ["Go south to Mudskipper Point and lob a Fishing Explosive into the sea. You can grab them from the Slayer masters."] = "Ve hacia el sur hasta Mudskipper Point y lanza un explosivo Fishing al mar. Puedes obtenerlos desde Slayer masters.",
    ["Thanks! So, what are you going to do now?"] = "¡Gracias! Entonces, ¿qué vas a hacer ahora?",
    ["Well, I was planning on continuing my hobby of wandering up and down this coastline, bellowing random threats and throwing bottles. And you?"] = "Bueno, estaba planeando continuar con mi pasatiempo de vagar por esta costa, bramando amenazas al azar y arrojando botellas. ¿Y tú?",
    ["I was planning on wandering up and down the landscape, bugging people to see if they had mindblowingly dangerous quests for me to undertake!"] = "¡Estaba planeando vagar arriba y abajo por el paisaje, molestando a la gente para ver si tenían misiones increíblemente peligrosas que yo pudiera emprender!",
    ["Well, good luck with that!"] = "Bueno, ¡buena suerte con eso!",
    ["You too!"] = "¡Tú también!",
    ["Weirdo..."] = "Raro...",
    ["Loony..."] = "Loco...",
    ["*(dialogue terminates)*"] = "*(termina el diálogo)*",
    ["Thanks for getting me out of that pickle with that slaver!"] = "¡Gracias por sacarme de ese aprieto con ese esclavista!",
    ["color=yellow"] = "color=amarillo",
    ["Good day."] = "Buenos días.",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["Sorry. I can't sell weapons to outerlanders. Wouldn't be right. Against our beliefs."] = "Lo siento. No puedo vender armas a los extranjeros. No estaría bien. Contra nuestras creencias.",
    ["Only Fremenniks may purchase weapons and armour here."] = "Sólo los Fremenniks pueden comprar armas y armaduras aquí.",
    ["**What would you like to ask about?**"] = "**¿Sobre qué te gustaría preguntar?**",
    ["Rock Crab Armour"] = "Armadura Roca Crab",
    ["Hello there. I have these shards of rock crab shell, and believe you might be able to make them into armour for me...?"] = "Hola. Tengo estos fragmentos de caparazón de cangrejo de roca y creo que podrías convertirlos en una armadura para mí...",
    ["No problem, [Fremennik name]. What armour you want?"] = "No hay problema, [Fremennik name]. ¿Qué armadura quieres?",
    ["It'll cost 5,000 coins. That ok?"] = "Costará 5000 coins. ¿Está bien?",
    ["Sorry. Need 1 piece of dark daggermouth hide, 1 rock-shell chunk and 5,000 coins to make you helmet. Come back when you got it."] = "Lo siento. Necesitas 1 trozo de piel de boca de daga oscura, 1 trozo de concha de roca y 5000 coins para hacer tu casco. Vuelve cuando lo tengas.",
    ["There you go. Fine helm. You want another?"] = "Ahí lo tienes. Buen timón. ¿Quieres otro?",
    ["Sturdy bodyarmour"] = "Armadura resistente",
    ["It'll cost 10,000 coins. That ok?"] = "Costará 10.000 coins. ¿Está bien?",
    ["Apologies. Need 3 pieces of dark daggermouth hide, 1 rock-shell shard and 10,000 coins to make you strong armour. Come back when you got it."] = "Disculpas. Necesitas 3 piezas de piel de boca de daga oscura, 1 fragmento de concha de roca y 10 000 coins para hacerte una armadura fuerte. Vuelve cuando lo tengas.",
    ["There you go. Sturdy armour. You need another piece?"] = "Ahí lo tienes. Armadura robusta. ¿Necesitas otra pieza?",
    ["It'll cost 7,500 coins. That ok?"] = "Costará 7500 coins. ¿Está bien?",
    ["Apologies. Need 2 pieces of dark daggermouth hide, 1 rock-shell splinter and 7,500 coins to make you leg armour. Come back when you got it."] = "Disculpas. Necesitas 2 piezas de piel de boca de daga oscura, 1 astilla de concha de roca y 7500 coins para hacerte una armadura para las piernas. Vuelve cuando lo tengas.",
    ["AS you wish."] = "Como desees.",
    ["Hello again, [Fremennik name]. Come to see what's for sale?"] = "Hola de nuevo, [Fremennik name]. ¿Vienes a ver qué hay a la venta?",
    ["Show me what you've got."] = "Muéstrame lo que tienes.",
    ["We'll keep his stories alive, at least his legend will live forever."] = "Mantendremos vivas sus historias, al menos su leyenda vivirá para siempre.",
    ["You should speak with the ruler of this isle, King Gjuki Sorvott IV."] = "Deberías hablar con el gobernante de esta isla, el rey Gjuki Sorvott IV.",
    ["Can I have a look at your stock please?"] = "¿Puedo echar un vistazo a sus existencias, por favor?",
    ["No, nothing just now thanks."] = "No, nada ahora, gracias.",
    ["Oh, hello again. Want to buy some weapons?"] = "Oh, hola de nuevo. ¿Quieres comprar algunas armas?",
    ["I'll have a look."] = "Echaré un vistazo.",
    ["Grrr - you don't belong in here, human!"] = "Grrr - ¡no perteneces aquí, humano!",
    ["*(if wearing the werewolf outfit)*"] = "*(si usa el traje de hombre lobo)*",
    ["I'm not a human, I'm a lycanthrope, just look at my claws."] = "No soy un humano, soy un licántropo, solo mira mis garras.",
    ["They're made from paper."] = "Están hechos de papel.",
    ["Well I don't want to hurt anyone with them do I?"] = "Bueno, no quiero lastimar a nadie con ellos, ¿verdad?",
    ["That would be rather the point."] = "Ese sería el punto.",
    ["I would never do such a thing, I'm a pacifist werewolf."] = "Yo nunca haría tal cosa, soy un hombre lobo pacifista.",
    ["Worst excuse ever."] = "La peor excusa jamás creada.",
    ["Yeah... Not my best."] = "Sí... No es mi mejor momento.",
    ["Go away now."] = "Vete ahora.",
    ["I would like to do the skullball course."] = "Me gustaría hacer el curso de Skullball.",
    ["**Player** I think I'll give the Skullball Course a go."] = "**Player** Creo que probaré el curso Skullball.",
    ["*starts the Werewolf Skullball activity*"] = "*inicia la actividad Skullball del hombre lobo*",
    ["What are the instructions for using the skullball course?"] = "¿Cuáles son las instrucciones para utilizar el curso Skullball?",
    ["**Player** What are the instructions for using the skullball course?"] = "**Player** ¿Cuáles son las instrucciones para utilizar el curso Skullball?",
    ["**Skullball Boss** The skullball comes out of one of these four spawnholes. Just kick the ball through the middle of each goal, through the skeleton's feet."] = "**Skullball Boss** La bola de calavera sale de uno de estos cuatro agujeros de generación. Simplemente patea la pelota por el centro de cada portería, a través de los pies del esqueleto.",
    ["**Skullball Boss** There are 10 goals, which you must complete in order, and one final goal."] = "**Skullball Boss** Hay 10 objetivos, que debes completar en orden, y un objetivo final.",
    ["**Skullball Boss** An arrow will point to your ball, just in case lots of people are using the course at the same time as yourself."] = "**Skullball Boss** Una flecha apuntará a tu bola, en caso de que muchas personas estén usando el campo al mismo tiempo que tú.",
    ["**Skullball Boss** The better your time, the more agillity XP you will be awarded. The timer starts when you score your first goal."] = "**Skullball Boss** Cuanto mejor sea tu tiempo, más XP de agilidad recibirás. El cronómetro comienza cuando marcas tu primer gol.",
    ["I seem to have lost my ball - can I have another one?"] = "Parece que perdí mi pelota. ¿Puedo tener otra?",
    ["**Player** I seem to have lost my ball - can I have another one?"] = "**Player** Parece que perdí mi pelota. ¿Puedo tener otra?",
    ["**Skullball Boss** No problem, here's another one. You'll have to start from the beginning again, but the timer will be restarted too."] = "**Skullball Boss** No hay problema, aquí hay otro. Tendrás que volver a empezar desde el principio, pero el cronómetro también se reiniciará.",
    ["*(Skullball activity is reset)*"] = "*(La actividad de Skullball se reinicia)*",
    ["I give up, I can't do it - take my ball away."] = "Me rindo, no puedo hacerlo, quítame la pelota.",
    ["**Player** I give up, I can't do it - take my ball away."] = "**Player** Me rindo, no puedo hacerlo, quítame la pelota.",
    ["**Skullball Boss** Oh dear, such a defeatist."] = "**Skullball Boss** Dios mío, qué derrotista.",
    ["*(Ends activity)*"] = "*(Finaliza la actividad)*",
    ["What are the instructions for the skullball course?"] = "¿Cuáles son las instrucciones para el curso de Skullball?",
    ["*(Ends dialogoue)*"] = "*(Finaliza el diálogo)*",
    ["This is the Skullball Course"] = "Este es el curso Skullball",
    ["Go talk to the boss at the beginning of the course if you'd like a go."] = "Ve a hablar con el jefe al comienzo del curso si quieres intentarlo.",
    ["Grrr - you don't belong in here, human"] = "Grrr - no perteneces aquí, humano",
    ["A lot of bad things must have happened here."] = "Aquí deben haber pasado muchas cosas malas.",
    ["You don't know the half of it, pal!"] = "¡No sabes ni la mitad, amigo!",
    ["Argh! Y-y-you're a talking pile of bones!"] = "¡Argh! ¡Eres un montón de huesos parlantes!",
    ["And you're a talking bag of gas. You gonna listen to my story or what?"] = "Y tú eres una bolsa de gas parlante. ¿Vas a escuchar mi historia o qué?",
    ["No need for insults. What's your story, then?"] = "No hay necesidad de insultos. ¿Cuál es tu historia entonces?",
    ["Captain Cora - that was her name. She's the one who did this to us. Trapped our minds in our bones, cursed us to this eternal torment."] = "Capitán Cora, ese era su nombre. Ella es quien nos hizo esto. Atrapó nuestras mentes en nuestros huesos, nos maldijo a este tormento eterno.",
    ["This musta been, like, twenty years back now. Just showed up one day, how'd you do, then cursed us like that was nothing."] = "Esto debe haber sido hace como veinte años. Apareció un día, ¿cómo te fue? Y luego nos maldijo como si eso no fuera nada.",
    ["Then what?"] = "¿Y luego qué?",
    ["She left. We didn't chase her, though - didn't feel like it. Didn't feel much of anything from that day on."] = "Ella se fue. Pero no la perseguimos, no nos apetecía. A partir de ese día no sentí mucho nada.",
    ["Then slowly, one by one, we all just died...but somehow also kept on living. Then we started decomposing, yet still here in our heads. Now we're all just bones."] = "Luego, lentamente, uno por uno, todos morimos... pero de alguna manera también seguimos viviendo. Luego comenzamos a descomponernos, pero todavía estamos aquí en nuestras cabezas. Ahora todos somos sólo huesos.",
    ["Yet you can still think and talk? And feel?"] = "¿Aún puedes pensar y hablar? ¿Y sentir?",
    ["Don't feel nothing, mate. Like I said, haven't in a long time. We're all just stuck here, not moving on, not going anywhere."] = "No sientas nada, amigo. Como dije, no lo he hecho en mucho tiempo. Estamos todos atrapados aquí, sin avanzar, sin ir a ninguna parte.",
    ["That's horrific. I mean, you Skulls pirates are reprehensible, but still."] = "Eso es horrible. Quiero decir, ustedes, los piratas Skulls, son reprensibles, pero aun así.",
    ["I know, right. She must have learned some serious necromantic magic. She could at least have just turned us into normal zombies. Then we could at least have carried on our piratical ways. This is just cruel."] = "Lo sé, cierto. Debe haber aprendido algo de magia nigromántica seria. Al menos podría habernos convertido en zombis normales. Entonces al menos podríamos haber continuado con nuestras costumbres piratas. Esto es simplemente cruel.",
    ["Leave me to my torment, mate."] = "Déjame con mi tormento, amigo.",
    ["Captain Cora knows some serious necromancy, mate. Don't get on her wrong side like we did."] = "La capitana Cora sabe algo de nigromancia seria, amigo. No te pongas del lado malo de ella como lo hicimos nosotros.",
    ["This place is really starting to depress me."] = "Este lugar realmente está empezando a deprimirme.",
    ["Urgh, you and me both, mate."] = "Urgh, tú y yo, amigo.",
    ["Argh! You can talk!"] = "¡Argh! ¡Puedes hablar!",
    ["So can you, mate, but you don't hear me screaming like a little girl."] = "Tú también puedes, amigo, pero no me oyes gritar como una niña pequeña.",
    ["B-b-but you're a pile of bones."] = "P-p-pero eres un montón de huesos.",
    ["You're on the slim side yourself, pal. Don't be judging. It's not my fault."] = "Tú también eres delgado, amigo. No juzgues. No es mi culpa.",
    ["Okay, I'll bite...unless, maybe I did nibble on a wushroom and this is all a hallucination? Anyway, who is at fault?"] = "Está bien, morderé... a menos que tal vez mordisqueé un baño y todo esto sea una alucinación. De todos modos, ¿quién tiene la culpa?",
    ["The screaming little girl, like I was saying. You don't listen much, do ya?"] = "La niña que grita, como decía. No escuchas mucho, ¿verdad?",
    ["Which little girl?"] = "¿Qué niña?",
    ["What was her name again? Carla, Caroline..."] = "¿Cuál era su nombre? Carla, Caroline...",
    ["Cora?"] = "¿Cora?",
    ["Yeah, that's it - she did this to me."] = "Sí, eso es todo, ella me hizo esto.",
    ["Who are you...er, were you? Were you a Skulls pirate?"] = "¿Quién eres...eh, eras? ¿Eras un Skulls pirate?",
    ["Yeah. The name's Pete, mate. Used to live in this here fort, now I'm just trapped in it."] = "Sí. El nombre es Pete, amigo. Solía ​​vivir en este fuerte, ahora estoy atrapado en él.",
    ["From what I've seen of your gang, that would sound like justice to some people."] = "Por lo que he visto de tu pandilla, eso parecería justicia para algunas personas.",
    ["You sound just like her. 'This is justice', she says. I had no idea who she was at first. You see a lot of faces in the kidnapping game, don't remember any of 'em."] = "Suenas igual que ella. \"Esto es justicia\", dice. Al principio no tenía idea de quién era ella. Ves muchas caras en el juego del secuestro, no recuerdas ninguna de ellas.",
    ["She knew us, though. Said we'd taken her when she was young, killed her folks, sold her to Goshima."] = "Aunque ella nos conocía. Dijimos que la habíamos capturado cuando era joven, que habíamos matado a sus padres y que la habíamos vendido a Goshima.",
    ["Then she did this to us and left."] = "Luego nos hizo esto y se fue.",
    ["What did she do to you?"] = "¿Qué te hizo?",
    ["It's too traumatic to talk about, mate. Ask one of the others."] = "Es demasiado traumático para hablar de ello, amigo. Pregúntale a uno de los demás.",
    ["I'm just going to leave you to it..."] = "Te dejaré con eso...",
    ["I don't wanna talk about it, mate. Cora, that girl we sold to Goshima, she's the one who did this to us."] = "No quiero hablar de eso, amigo. Cora, esa chica que le vendimos a Goshima, ella es quien nos hizo esto.",
    ["Ha! Looks like some 'Skulls' still live in this fort."] = "¡Ja! Parece que algunas 'calaveras' todavía viven en este fuerte.",
    ["No need to make a joke of it, buddy - that's just mean. We're people too ya know!"] = "No es necesario que hagas una broma, amigo, eso es simplemente cruel. ¡Nosotros también somos personas, ya sabes!",
    ["Argh! Oh no, wait, I'm not shocked any more."] = "¡Argh! Oh no, espera, ya no estoy en shock.",
    ["Wow, I can't even creep people out these days. Thanks a lot, that's all I had going for me."] = "Vaya, hoy en día ni siquiera puedo asustar a la gente. Muchas gracias, eso es todo lo que tenía a mi favor.",
    ["Fine, what's your story then?"] = "Bien, ¿cuál es tu historia entonces?",
    ["Me, I was so proud - I'd only just passed the gang's initiation! I was gonna be a pirate like my dad before me, and my dad's dad too."] = "Yo estaba muy orgulloso: ¡acababa de pasar la iniciación de la pandilla! Iba a ser un pirata como mi papá antes que yo, y el papá de mi papá también.",
    ["But then SHE came along and ruined it. I wasn't even born when whatever happened to her, er, happened to her. It ain't my fault!"] = "Pero entonces apareció ELLA y lo arruinó. Yo ni siquiera había nacido cuando lo que le pasó a ella, ejem, le pasó a ella. ¡No es mi culpa!",
    ["Who was 'she'?"] = "¿Quién era 'ella'?",
    ["That's just it - I had no idea? Never seen her before. Says she was the khan of Goshima's lieutenant. Says she'd earned her freedom and came back here to exact revenge on us Skulls."] = "Eso es todo. ¿No tenía idea? Nunca la había visto antes. Dice que era la khan del lugarteniente de Goshima. Dice que se ganó la libertad y regresó aquí para vengarse de nosotros los Skulls.",
    ["I'd done nothing, buddy, like I said. Told her that too, but she didn't care, then 'zap'!, she turns me into this."] = "No había hecho nada, amigo, como dije. Le dije eso también, pero a ella no le importó, entonces ¡zap!, me convierte en esto.",
    ["That's just, like, really unfair, ain't it? I didn't even get a chance to kidnap and ransom people. Not cool."] = "Eso es realmente injusto, ¿no? Ni siquiera tuve la oportunidad de secuestrar y rescatar gente. No es genial.",
    ["I'm too depressed to talk about it."] = "Estoy demasiado deprimido para hablar de eso.",
    ["I've told you all I'm gonna - this is the doing of the khan of Goshima's lieutenant."] = "Ya les dije todo lo que voy a hacer: esto es obra del khan del teniente de Goshima.",
    ["Word has it that you very nearly spoiled our fun!"] = "¡Se dice que casi arruinas nuestra diversión!",
    ["What, you're upset that I tried to put the high priest's soul to rest?"] = "¿Qué? ¿Estás molesto porque intenté hacer descansar el alma del sumo sacerdote?",
    ["So that we could get back to work again? What makes you believe that he even deserves such a burial?"] = "¿Para que podamos volver a trabajar? ¿Qué te hace creer que merece tal entierro?",
    ["Doesn't everyone?"] = "¿No es así para todos?",
    ["What, even those that gain through the blood, sweat, tears and misery of others?"] = "¿Qué, incluso aquellos que ganan con la sangre, el sudor, las lágrimas y la miseria de los demás?",
    ["I was just trying to help and, as it turns out, I've not achieved not a whole lot."] = "Solo estaba tratando de ayudar y resulta que no he logrado mucho.",
    ["I have this acne potion that I thought might clear up your spots?"] = "¿Tengo esta poción para el acné que pensé que podría aclarar tus manchas?",
    ["What, so that I can get back to work?"] = "¿Qué, para poder volver a trabajar?",
    ["Um, no, so that you wouldn't suffer needlessly?"] = "Um, no, ¿para no sufrir innecesariamente?",
    ["I know your type, trying to ruin the small man's fun! I won't have it!"] = "¡Conozco a tu tipo, tratando de arruinar la diversión del hombre pequeño! ¡No lo aceptaré!",
    ["Look, I'm sorry. I only had good intentions, I only wanted to help you."] = "Mira, lo siento. Sólo tenía buenas intenciones, sólo quería ayudarte.",
    ["Cower before me!"] = "¡Encogeos ante mí!",
    ["Carry on, slave."] = "Continúa, esclavo.",
    ["She refuses to make eye contact, and fearfully focuses on her duties."] = "Ella se niega a hacer contacto visual y se concentra con miedo en sus deberes.",
    ["He intently concentrates on scrubbing dishes, and pretends not to hear you."] = "Se concentra intensamente en fregar los platos y finge no oírte.",
    ["He tries not to notice you, and continues to slave over a hot stove."] = "Él trata de no notarte y continúa esclavizándose frente a una estufa caliente.",
    ["Do you know of a Justin or Sammy Servil in this arena?"] = "¿Conoces a Justin o Sammy Servil en este campo?",
    ["Please, leave me alone."] = "Por favor, déjame en paz.",
    ["I've not met anybody in here by that name."] = "No he conocido a nadie aquí con ese nombre.",
    ["I miss da sneeches. We used ta race them round da village."] = "Extraño los estornudos. Solíamos correr con ellos por el pueblo.",
    ["Used to win all da time. How I gonna make pearls now?"] = "Solía ganar todo el tiempo. ¿Cómo voy a hacer perlas ahora?",
    ["I'm not sure what to do with that information."] = "No estoy seguro de qué hacer con esa información.",
    ["Oh, you can use da bank here if you like. It da B.O.G."] = "Oh, puedes usar el banco aquí si quieres. Es el B.O.G.",
    ["Fancy meeting you here, Player. Such a coincidence! Such a small world! But alas, you meet me as I am leaving. The big paperweight, Vorago, and I have already finished our chat... if you could call it that. I will save you the dull and inevitable question. I am here because he has killed a god, Tuska. So, I have invited him to my Big Game. Vorago will join Armadyl. They both gain the chance of seizing the Stone of Jas, because they have both killed gods. Hmmm, I wonder if there will be the opportunity to kill one bird with two stones?"] = "Me alegro de encontrarte aquí, Player. ¡Qué coincidencia! ¡Qué mundo tan pequeño! Pero, ay, me encontrarás cuando me vaya. El pisapapeles grande, Vorago, y yo ya terminamos nuestra charla... si se le puede llamar así. Te ahorraré la pregunta aburrida e inevitable. Estoy aquí porque ha matado a un dios, Tuska. Entonces lo invité a mi gran juego. Vorago se unirá a Armadyl. Ambos tienen la oportunidad de apoderarse de la Piedra de Jas, porque ambos han matado dioses. Hmmm, me pregunto si habrá la oportunidad de matar un pájaro con dos piedras.",
    ["When is this Big Game?"] = "¿Cuándo es este gran juego?",
    ["I grow a little restless, to be frank. Things are going rather slowly. I feel I may have to speed things up."] = "Para ser sincero, me pongo un poco inquieto. Las cosas van bastante lentamente. Siento que quizás tenga que acelerar las cosas.",
    ["What did Vorago say?"] = "¿Qué dijo Vorago?",
    ["Very little. But he will be at the Big Game. To defend Gielinor and the lifeforce of the world. I paraphrase, of course."] = "Muy poco. Pero estará en el Gran Juego. Defender Gielinor y la fuerza vital del mundo. Parafraseo, por supuesto.",
    ["A delight as usual."] = "Una delicia como siempre.",
    ["*Talking to a Sliskelion piece for the first time*"] = "*Hablando con un Sliskelion piece por primera vez*",
    ["Congratulations <name> you are now the proud owner of a fabulous Sliskelion piece! These fabulous items are brought to you by the Great Sliske, gamemaster extraordinaire in honour of his great game. Sliske's great game is making waves across Gielinor and beyond, with whole religions screaming that question: Who's dying next? Well right now you can see who's winning by visiting the fabulous scoreboard in the centre of the Grand Exchange."] = "¡Felicitaciones <name>, ahora eres el orgulloso propietario de un fabuloso Sliskelion piece! Estos fabulosos artículos te los trae el Gran Sliske, extraordinario maestro de juego en honor a su gran juego. El gran juego de Sliske está causando sensación en Gielinor y más allá, con religiones enteras gritando esa pregunta: ¿Quién será el próximo en morir? Pues ahora mismo puedes ver quién está ganando visitando el fabuloso marcador en el centro del Grand Exchange.",
    ["What is the point of these?"] = "¿Cuál es el punto de estos?",
    ["Aside from being a fabulous decoration for any living room, these Sliskelion pieces can be traded in for amazing prizes. Just take 50 of these to the scoreboard in the Grand Exchange and you will be rewarded with power and knowledge. But don't worry, you won't have to walk all that way. When you have 50 Sliskelion pieces, they can teleport you straight there. Convenience and chic in one fantastically handsome package. You can find Sliskelion pieces by simply going about your daily activities."] = "Además de ser una decoración fabulosa para cualquier sala de estar, estas piezas de Sliskelion se pueden canjear por premios increíbles. Simplemente lleva 50 de estos al marcador del Grand Exchange y serás recompensado con poder y conocimiento. Pero no te preocupes, no tendrás que caminar todo ese camino. Cuando tengas 50 piezas de Sliskelion, podrán teletransportarte directamente allí. Comodidad y elegancia en un paquete increíblemente atractivo. Puedes encontrar piezas de Sliskelion simplemente realizando tus actividades diarias.",
    ["What is Sliske's game?"] = "¿Cuál es el juego de Sliske?",
    ["Sliske's game is a revolution made fun. All those stuffy old gods, now get to duke it out for the promise of power and prestige. The contestant with the most points gets to win the most fabulous of prizes, the Stone of Jas itself."] = "El juego de Sliske es una revolución divertida. Todos esos viejos dioses sofocantes ahora pueden pelear por la promesa de poder y prestigio. El concursante con más puntos ganará el premio más fabuloso: la propia Piedra de Jas.",
    ["How do contestants get points?"] = "¿Cómo obtienen puntos los concursantes?",
    ["Originally the game was to kill as many gods as possible. Sadly though we've been forced to amend those rules, due to a general lack of carnage and a surprising surge of reason. So now players collect wonderful Sliske points by defeating other gods or proving themselves worthy. See the scoreboard in the Grand Exchange to see how the contestants are faring."] = "Originalmente el juego consistía en matar tantos dioses como fuera posible. Lamentablemente, nos hemos visto obligados a modificar esas reglas, debido a una falta general de matanza y una sorprendente oleada de razón. Ahora los jugadores acumulan maravillosos puntos Sliske al derrotar a otros dioses o demostrar que son dignos. Consulta el marcador en Grand Exchange para ver cómo les está yendo a los concursantes.",
    ["What's the scoreboard?"] = "¿Cuál es el marcador?",
    ["The name is confusing I know. But basically the score board is a big board that shows the current scores. It's in the centre of the Grand Exchange in Varrock, you really can't miss it."] = "El nombre es confuso, lo sé. Pero básicamente el tablero de puntuación es un tablero grande que muestra las puntuaciones actuales. Está en el centro de Grand Exchange en Varrock, realmente no te lo puedes perder.",
    ["Ok I get the point."] = "Ok, entiendo el punto.",
    ["*Talking to a Sliskelion piece subsequently*"] = "*Hablando con un Sliskelion piece posteriormente*",
    ["Everyone's asking: Who's dying next? Find out who's winning on the scoreboard in the Grand Exchange."] = "Todo el mundo pregunta: ¿Quién será el próximo en morir? Descubre quién gana en el marcador de Grand Exchange.",
    ["Congratulations! You are now the proud owner of a fabulous Sliskelion XP lamp!"] = "¡Felicitaciones! ¡Ahora eres el orgulloso propietario de una fabulosa lámpara Sliskelion XP!",
    ["Oh, you don't appear to have enough inventory space."] = "Oh, parece que no tienes suficiente espacio en el inventario.",
    ["I see you didn't receive your lamp from the last time you came here! So you are now the proud owner of a fabulous Sliskelion XP lamp!"] = "¡Veo que no recibiste tu lámpara la última vez que viniste aquí! ¡Ahora eres el orgulloso propietario de una fabulosa lámpara Sliskelion XP!",
    ["Ahhh, hello there, Player."] = "Ahhh, hola, Player.",
    ["Ah, but I can see you are already strong as is possible! Perhaps you have come to me to purchase a Skillcape of Strength, and thus join the elite few who have mastered this exacting skill?"] = "¡Ah, pero puedo ver que ya eres lo más fuerte posible! ¿Quizás has venido a mí para comprar un Skillcape o un Strength y así unirte a la élite que domina esta exigente habilidad?",
    ["Can you tell me a bit about skillcapes?"] = "¿Puedes contarme un poco sobre skillcapes?",
    ["Sure. You can buy a skillcape when you reach level 99 in a skill. Apart from boosting your statistics in that skill, they can also be used to perform some pretty amazing emotes! Is there anything else you would like to know?"] = "Claro. Puedes comprar un skillcape cuando alcances el nivel 99 en una habilidad. Además de mejorar tus estadísticas en esa habilidad, ¡también pueden usarse para realizar algunos gestos increíbles! ¿Hay algo más que te gustaría saber?",
    ["cond=If the player has 99 Strength:|May I buy a Skillcape of Strength, please?"] = "cond=Si el player tiene 99 Strength:|¿Puedo comprar un Skillcape de Strength, por favor?",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Strength skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Strength skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Strength skillcape."] = "Solo me gustaría cambiar el Strength skillcape.",
    ["No problem, you will now use the [older/newer] model for your Strength skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Strength skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["Ahh, the shot put is a great test of strength and can be quite rewarding. Mind you do it properly, though, you might want to dust your hands with some powdery substance first. It'll give better grip."] = "Ahh, el lanzamiento de peso es una gran prueba de fuerza y puede ser bastante gratificante. Eso sí, asegúrate de hacerlo correctamente; es posible que primero quieras espolvorearte las manos con alguna sustancia en polvo. Le dará un mejor agarre.",
    ["I'll remember that. What should I use?"] = "Lo recordaré. ¿Qué debo usar?",
    ["I personally prefer ground ashes, it makes a nice fine powder and gives some really good grip."] = "Personalmente prefiero las cenizas molidas, produce un polvo fino y agradable y proporciona un agarre realmente bueno.",
    ["Okay, what else?"] = "Vale, ¿qué más?",
    ["Basically you'll need to go in there, make sure you've got nothing cluttering up your hands, pick up a shot and throw it. Depending upon your technique, you can get quite long throws."] = "Básicamente tendrás que entrar allí, asegurarte de no tener nada en tus manos, tomar un tiro y lanzarlo. Dependiendo de tu técnica, puedes realizar lanzamientos bastante largos.",
    ["What was your best?"] = "¿Cuál fue tu mejor?",
    ["Ahh, that would be telling."] = "Ahh, eso sería revelador.",
    ["That's a big axe!"] = "¡Esa es un hacha grande!",
    ["Yes, indeed, it is. Have to be mighty strong to wield it too."] = "Sí, efectivamente lo es. Tienes que ser muy fuerte para manejarlo también.",
    ["But you don't look that strong!"] = "¡Pero no te ves tan fuerte!",
    ["Maybe, maybe not, but I still had to beat a Barbarian to get it. Mind you, usually they don't part with them. This was an unusual circumstance."] = "Tal vez, tal vez no, pero aún así tuve que vencer a un Bárbaro para conseguirlo. Eso sí, normalmente no se separan de ellos. Esta fue una circunstancia inusual.",
    ["I bet him he couldn't catch a squirrel whilst still holding his axe but that I could... and that if I won I'd get his axe."] = "Le apuesto que no podría atrapar una ardilla mientras todavía sostiene su hacha, pero que yo sí podría... y que si ganaba, conseguiría su hacha.",
    ["He went running after the squirrel... nearly caught it too... it shot up a tree and he tried to climb up it, only got a bit tangled up with his axe cause he couldn't hang on to it at the same time and... he fell out of the tree."] = "Salió corriendo detrás de la ardilla... casi la atrapa también... se subió a un árbol y él trató de trepar, solo se enredó un poco con su hacha porque no podía agarrarse a ella al mismo tiempo y... se cayó del árbol.",
    ["Then it was my turn...."] = "Luego fue mi turno....",
    ["I simply went and chopped the tree down with this big old axe, still holding it. The squirrel was so petrified it simply jumped straight out of the tree onto me. I won the axe and let the poor creature go!"] = "Simplemente fui y corté el árbol con esta gran hacha vieja, todavía sosteniéndola. La ardilla estaba tan petrificada que simplemente saltó del árbol hacia mí. ¡Gané el hacha y dejé ir a la pobre criatura!",
    ["I sense a moral in there somewhere."] = "Siento una moraleja en alguna parte.",
    ["Aye indeed. Brawn isn't all you need to wield a big axe, brains are required too!"] = "Sí, claro. Músculo no es todo lo que necesitas para empuñar un hacha grande, ¡también se requiere cerebro!",
    ["Be well, warrior Player."] = "Que estés bien, guerrero Player.",
    ["Yadech continues on your legacy."] = "Yadech continúa con su legado.",
    ["[The strange pumpkin gives you an old pumpkin head.]"] = "[La extraña calabaza te da una vieja cabeza de calabaza.]",
    ["You sense that the energy emanating from the pumpkin would help to upgrade the rotten pumpkin mask."] = "Sientes que la energía que emana de la calabaza ayudaría a mejorar la máscara de calabaza podrida.",
    ["The pumpkin appears to quiver in fear. Although it seems indestructible, it wonders why you continue to stamp on it since you have already upgraded your pumpkin mask."] = "La calabaza parece temblar de miedo. Aunque parece indestructible, me pregunto por qué continúas pisoteándolo si ya has mejorado tu máscara de calabaza.",
    ["You've smashed 250 pumpkins! You can now change the style of your Rotten pumpkin mask."] = "¡Has destrozado 250 calabazas! Ahora puedes cambiar el estilo de tu máscara de calabaza podrida.",
    ["Hi there."] = "Hola.",
    ["Hey, ids me matesh!"] = "¡Oye, me identificas amigo!",
    ["Sorry, have we met?"] = "Lo siento, ¿nos conocemos?",
    ["Yeah! you wazsh wiv me in dat pub overy by hill!"] = "¡Sí! ¡Estás conmigo en ese pub que está muy cerca de la colina!",
    ["I have no idea what you're going on about."] = "No tengo idea de qué estás diciendo.",
    ["Glad yeeash remembers."] = "Me alegra que sí lo recuerdes.",
    ["*Says these occasionally overhead*"] = "*Dice esto de vez en cuando*",
    ["Arr? Be ye wantin' te go on account with our gang o' fillibusters?"] = "¿Llegó? ¿Quieres ir a cuenta con nuestra banda de filibusteros?",
    ["The powder monkey be takin' a caulk after gettin' rowdy on bumboo, so there be plenty of room for ye."] = "El mono de la pólvora se va a poner masilla después de ponerse alborotado en bumboo, así que habrá mucho espacio para ti.",
    ["Riiiiight..."] = "Correcto...",
    ["I'll just be over here if you need me."] = "Estaré aquí si me necesitas.",
    ["Yer standin' in me light stranger. Can I sell ye somethin' that'll make ye move?"] = "Estás parado en mí, un extraño ligero. ¿Puedo venderte algo que te haga mudarte?",
    ["Probably, let's see what you have."] = "Probablemente, veamos qué tienes.",
    ["I doubt it."] = "Lo dudo.",
    ["Then move on stranger."] = "Entonces sigue adelante, extraño.",
    ["That depends on if you have any cutlasses."] = "Eso depende de si tienes algún sable.",
    ["Cutlasses! Think yer a pirate now lad?"] = "¡Alfanjes! ¿Crees que ahora eres un pirata, muchacho?",
    ["Well, yes."] = "Bueno, sí.",
    ["Well, I have some cutlasses."] = "Bueno, tengo algunos alfanjes.",
    ["I have Brass Hand Harry's Cutlass. Well, a load of them to be honest."] = "Tengo el Cutlass de Brass Hand Harry. Bueno, muchos de ellos para ser honesto.",
    ["Then there's Unlucky Jenkins' Lucky Cutlass. Lovely blade that."] = "Luego está Lucky Cutlass del desafortunado Jenkins. Preciosa espada esa.",
    ["I've also got Gentleman Mallard's Rapier. Not a cutlass I know, but the finest blade ever wielded by a privateer."] = "También tengo el estoque de Gentleman Mallard. No es un alfanje, lo que conozco, sino la mejor espada jamás empuñada por un corsario.",
    ["Now, which would ye like to hear about?"] = "Ahora, ¿sobre qué te gustaría saber?",
    ["Brass Hand Harry's Cutlass."] = "Machete de latón de Harry.",
    ["A good choice!"] = "¡Una buena elección!",
    ["Ye may end up meeting Brass Hand Harry if ye hang around long enough."] = "Es posible que acabes conociendo a Brass Hand Harry si te quedas el tiempo suficiente.",
    ["He lost his right hand to a canister round, but that didn't stop him much."] = "Perdió su mano derecha por una bala, pero eso no lo detuvo mucho.",
    ["Then he lost his replacement right hook fightin' the excise men off the coast of Karamja."] = "Luego perdió su gancho derecho de reemplazo peleando contra los encargados del impuesto especial frente a la costa de Karamja.",
    ["Not bein' the sort to lie about mopin', he asked me to make him a cutlass with a brass gauntlet fixed to the handle, and rig it up with a load of straps so he could keep on fightin' without losing his hand again."] = "Como no era de los que mienten sobre lamentarse, me pidió que le hiciera un machete con un guantelete de latón fijado al mango y que lo arreglara con un montón de correas para poder seguir luchando sin volver a perder la mano.",
    ["He's a great man is Harry, but he keeps snappin' the straps while he's at sea, so he sells the cutlasses back to me in exchange for a new one."] = "Es un gran hombre, Harry, pero sigue rompiendo las correas mientras está en el mar, así que me vende los alfanjes a cambio de uno nuevo.",
    ["It's quite a good blade, but the big, brass gauntlet is what makes it worthwhile. It's big enough to fit over even a real gauntlet, so ye get extra protection to yer sword hand."] = "Es una espada bastante buena, pero el gran guantelete de latón es lo que hace que valga la pena. Es lo suficientemente grande como para caber incluso sobre un guantelete real, por lo que obtienes protección adicional para la mano de tu espada.",
    ["I can sell ye one fer 1,040 coins."] = "Puedo venderte uno por 1.040 coins.",
    ["Interested?"] = "¿Interesado?",
    ["Smart lad! Come and see me when ye have the coins for it."] = "¡Muchacho inteligente! Ven a verme cuando tengas el coins para ello.",
    ["Here ye go. I've got a load of these left over if ye need more."] = "Aquí tienes. Me sobra un montón de estos por si necesitas más.",
    ["Well I'll still be here if ye change yer mind."] = "Bueno, todavía estaré aquí si cambias de opinión.",
    ["Unlucky Jenkins' Lucky Cutlass."] = "El sable afortunado del desafortunado Jenkins.",
    ["Arr, tis a sad tale to this sword."] = "Arr, es una historia triste para esta espada.",
    ["Jenkins was the lookout on the Jonah, a cursed vessel if there ever was one."] = "Jenkins era el vigía del Jonah, un barco maldito si alguna vez existió uno.",
    ["One day his ship were attacked by another group of pirates durin' a fierce storm. One of their bowmen took a shot at the Cap'n of the vessel, but it were deflected off his compass and hit Jenkins in the back."] = "Un día su barco fue atacado por otro grupo de piratas durante una feroz tormenta. Uno de sus arqueros disparó al capitán del barco, pero fue desviado de su brújula y alcanzó a Jenkins en la espalda.",
    ["How unlucky!"] = "¡Qué mala suerte!",
    ["That weren't the worst of it lad. He survived the fight, and the ship's surgeon was trying to get the arrow out when... Are ye familiar with the spell bones to bananas?"] = "Eso no fue lo peor, muchacho. Sobrevivió a la pelea, y el cirujano del barco estaba tratando de sacar la flecha cuando... ¿Estás familiarizado con el hechizo de huesos a plátanos?",
    ["Yes, why?"] = "Sí, ¿por qué?",
    ["Well, due to a blow to the head he took in the fight, the surgeon cast that spell, thinking it was some sort of new healing spell. And he did so while touching Jenkins' ribs."] = "Bueno, debido a un golpe en la cabeza que recibió en la pelea, el cirujano lanzó ese hechizo, pensando que era una especie de nuevo hechizo curativo. Y lo hizo mientras tocaba las costillas de Jenkins.",
    ["And that killed him?"] = "¿Y eso lo mató?",
    ["No lad! See, he survived, his bones turned to bananas, as a huge storm blew up and the crew debated what to do with him."] = "¡No, muchacho! Mira, sobrevivió, sus huesos se convirtieron en plátanos, cuando estalló una gran tormenta y la tripulación debatió qué hacer con él.",
    ["But you see, the storm was actually the tail end of a hurricane that had swept the nearby jungle islands, and when it approached the ship it petered out, droppin' all manner of strange things onto the deck and into the ocean."] = "Pero verás, la tormenta era en realidad la cola de un huracán que había barrido las islas selváticas cercanas, y cuando se acercó al barco se apagó, arrojando todo tipo de cosas extrañas sobre la cubierta y hacia el océano.",
    ["The worst part was when the ship was bombarded with ravenous, hunger-crazed monkeys, the majority of which landed on Jenkins as he lay recoverin'."] = "La peor parte fue cuando el barco fue bombardeado con monos hambrientos y hambrientos, la mayoría de los cuales aterrizaron en Jenkins mientras se recuperaba.",
    ["No [lad/lass]! See, what happened next, after the monkeys had had their way with him was..."] = "¡No [lad/lass]! Mira, lo que pasó después, después de que los monos se salieron con la suya con él fue...",
    ["Look, I don't want to hear any more. Why would I want to buy his cutlass?"] = "Mira, no quiero saber nada más. ¿Por qué querría comprar su alfanje?",
    ["Well, after the poor man passed on..."] = "Bueno, después de que el pobre hombre falleciera...",
    ["In a final, terrifying, mashed potato coated tragedy..."] = "En una tragedia final, aterradora, cubierta de puré de patatas...",
    ["His shipmates found his cutlass was completely untouched."] = "Sus compañeros descubrieron que su sable estaba completamente intacto.",
    ["See, having been exposed to all the bad luck that Jenkins went through, the thing is unlikely to ever see anything that bad again."] = "Mira, después de haber estado expuesto a toda la mala suerte por la que pasó Jenkins, es poco probable que vuelva a ver algo tan malo.",
    ["Hence, it must be lucky."] = "Por lo tanto, debe ser suerte.",
    ["Ye can have it fer 2560 coins."] = "Puedes tenerlo por 2560 coins.",
    ["Here ye go. I hope it brings you luck."] = "Aquí tienes. Espero que te traiga suerte.",
    ["Me too, but only the good kind."] = "Yo también, pero solo los buenos.",
    ["Gentleman Mallard's Rapier"] = "Estoque de caballero real",
    ["Gentleman Mallard's Rapier."] = "Estoque de caballero Mallard.",
    ["Well, I'll tell ye the story, but it'll take a great deal of convincin' for me to sell you this rapier."] = "Bueno, te contaré la historia, pero me costará mucho convencerte para venderte este estoque.",
    ["See, gentleman Mallard is a legend in these parts. His family had been rich, shipping all sorts of goods up and down the coast."] = "Mira, el caballero Mallard es una leyenda por estos lares. Su familia era rica y enviaba todo tipo de mercancías a lo largo de la costa.",
    ["Then their rivals got together and had their ships sunk, one after the other, and his business partners were all either bought off or had...accidents."] = "Luego sus rivales se juntaron y hundieron sus barcos, uno tras otro, y todos sus socios comerciales fueron comprados o tuvieron... accidentes.",
    ["With no money and only one ship left, he took to the life of a pirate, but no brigand was he."] = "Sin dinero y con solo un barco, tomó la vida de un pirata, pero no era un bandido.",
    ["He took only from those men that had brought about his downfall, was fair with his men, and generous with his loot."] = "Solo tomó de aquellos hombres que habían provocado su caída, fue justo con sus hombres y generoso con su botín.",
    ["Why, this island would have been wiped out by the shakes if he hadn't turned over his stash to buy medicine."] = "Vaya, esta isla habría sido arrasada por los temblores si él no hubiera recurrido a sus reservas para comprar medicinas.",
    ["One day his ship was attacked by a huge sea creature that swept the decks of men with its tentacles."] = "Un día su barco fue atacado por una enorme criatura marina que barrió las cubiertas de los hombres con sus tentáculos.",
    ["The crew took to the lifeboats, and the last they saw of him the gentleman was stabbin' at the thing as it hauled the ship under the water."] = "La tripulación subió a los botes salvavidas y lo último que vieron de él fue que el caballero estaba apuñalando a la cosa mientras arrastraba el barco bajo el agua.",
    ["A week later about ten foot of tentacle washed up on the beach, with his rapier embedded in it to the hilt."] = "Una semana después, unos tres metros de tentáculo aparecieron en la playa, con su estoque incrustado en él hasta la empuñadura.",
    ["I took it, cleaned it up, and I've been lookin' after it ever since."] = "Lo tomé, lo limpié y lo he estado cuidando desde entonces.",
    ["I can't let it go for less than 25600 coins, and even then that's a bargain."] = "No puedo dejarlo por menos de 25600 coins, e incluso así es una ganga.",
    ["Ye think ye have what it takes to wield it?"] = "¿Crees que tienes lo necesario para manejarlo?",
    ["I hope yer worthy enough to wield this, stranger. I'd hate te think Gentleman Mallard would be disappointed in me fer sellin' it to ye."] = "Espero que seas lo suficientemente digno para empuñar esto, extraño. Odiaría pensar que el caballero Mallard se decepcionaría de mí por vendérselo.",
    ["*(If you have a broken barrelchest anchor in inventory:)* I have this anchor, can you fix it?"] = "*(Si tienes un ancla de barril rota en el inventario:)* Tengo este ancla, ¿puedes arreglarla?",
    ["I have this anchor, can you fix it?"] = "Tengo este ancla, ¿puedes arreglarla?",
    ["Well, this is a very unusual job. This thing looks more suited to bashin' peoples heads in than securing a ship."] = "Bueno, este es un trabajo muy inusual. Esta cosa parece más adecuada para golpear a la gente en la cabeza que para asegurar un barco.",
    ["Where did ye get it?"] = "¿De dónde lo conseguiste?",
    ["You wouldn't believe me if I told you."] = "No me creerías si te lo dijera.",
    ["Stole it eh? Well I can sort it out for 230000 coins, if you like."] = "Lo robó, ¿eh? Bueno, puedo arreglarlo por 230000 coins, si quieres.",
    ["That's too much for me at the moment."] = "Eso es demasiado para mí en este momento.",
    ["Right, let's get to work."] = "Bien, pongámonos a trabajar.",
    ["There ye go, good as new!"] = "¡Ahí lo tienes, como nuevo!",
    ["Thanks Smith!"] = "¡Gracias Smith!",
    ["You need to equip a snowball to cool down the coal."] = "Necesitas equipar una bola de nieve para enfriar el carbón.",
    ["The following has been added to your currency pouch: 75 x Christmas spirit."] = "Se ha añadido lo siguiente a su bolsa de divisas: 75 x Espíritu navideño.",
    ["You have reached the Christmas spirit soft cap of 50,000. You need to spend some tokens in the Christmas Spirit Shop before you can earn more."] = "Has alcanzado el límite flexible de espíritu navideño de 50.000. Debes gastar algunas fichas en la tienda navideña Spirit antes de poder ganar más.",
    ["You fully cool down the coal."] = "Enfrías completamente el carbón.",
    ["The coal has already cooled down!"] = "¡El carbón ya se ha enfriado!",
    ["Hey!"] = "¡Oye!",
    ["Yo, shortstuff!"] = "¡Oye, bajito!",
    ["Despite your wild articulations and gesticulations you fail to catch Joe's attention."] = "A pesar de tus salvajes articulaciones y gesticulaciones, no logras captar la atención de Joe.",
    ["Can you tell me where I would find..."] = "¿Puedes decirme dónde encontraría...?",
    ["Phingspet and Grimesquit"] = "Phingspet y Grimesquit",
    ["Can you tell me where I could find Phingspet and Grimesquit?"] = "¿Puedes decirme dónde puedo encontrar Phingspet y Grimesquit?",
    ["Ah the sisters as strange a pair as your ever likely to meet."] = "Ah, las hermanas son la pareja más extraña que jamás hayas conocido.",
    ["You're most likely to find them in the sewers of Varrock."] = "Lo más probable es que los encuentres en las alcantarillas de Varrock.",
    ["Can you tell me where I would find Jimmy Dazzler?"] = "¿Puedes decirme dónde encontraría Jimmy Dazzler?",
    ["Ah young Jimmy, he must be a made man by now."] = "Ah, joven Jimmy, ya debe ser un hombre hecho.",
    ["I remember when ..."] = "Recuerdo cuando...",
    ["Do you know where I would find him or not?"] = "¿Sabes dónde lo encontraría o no?",
    ["Hrmph! Probably the Flying Horse in Ardougne."] = "¡Hmph! Probablemente el Caballo Volador de Ardougne.",
    ["I doubt he would be too far away from there."] = "Dudo que esté demasiado lejos de allí.",
    ["Can you tell me where I could find Hooknosed Jack?"] = "¿Puedes decirme dónde puedo encontrar Hooknosed Jack?",
    ["That old brawler? Is he still knocking about?"] = "¿Ese viejo luchador? ¿Sigue dando vueltas?",
    ["Well your best bet would be somewhere on the rough side of Varrock, the east side if I remember correctly."] = "Bueno, tu mejor opción sería algún lugar en el lado accidentado de Varrock, el lado este, si no recuerdo mal.",
    ["Can you tell me where I would find 'The Face'?"] = "¿Puedes decirme dónde encontraría 'The Face'?",
    ["What a tragedy, that girl."] = "Qué tragedia, esa chica.",
    ["Look for her in Port Sarim."] = "Búscala en Port Sarim.",
    ["Can you tell me where I would find Felkrash?"] = "¿Puedes decirme dónde encontraría Felkrash?",
    ["Ah queen muck, you'll probably find her in the Port Sarim pits."] = "Ah, reina, probablemente la encontrarás en los boxes de Port Sarim.",
    ["That's all."] = "Eso es todo.",
    ["Thought I was dead, eh?|color=#99FF99}}"] = "Pensé que estaba muerto, ¿eh?|color=#99FF99}}",
    ["I suppose you're back once again to finish me off!"] = "¡Supongo que has vuelto una vez más para acabar conmigo!",
    ["I've been training for this!"] = "¡He estado entrenando para esto!",
    ["You will die by my flame!"] = "¡Morirás por mi llama!",
    ["Ehehehe!"] = "¡Ejejeje!",
    ["I suppose you're here to finish me off!"] = "¡Supongo que estás aquí para acabar conmigo!",
    ["Fine! I will go back to Infernus..."] = "¡Bien! Volveré a Infernus...",
    ["Or I'll kill you! Ehehe!"] = "¡O te mataré! ¡Ejeje!",
    ["Hail, Player. Need something?"] = "Saludo, Player. ¿Necesitas algo?",
    ["What can you tell me about this place?"] = "¿Qué puedes contarme sobre este lugar?",
    ["This floor is less complex than most, and gives you a good introduction to Daemonheim."] = "Este piso es menos complejo que la mayoría y le brinda una buena introducción a Daemonheim.",
    ["Combat will be the only challenge you'll face, so I've given you a selection of melee, ranged and magical gear."] = "El combate será el único desafío al que te enfrentarás, así que te he dado una selección de equipo cuerpo a cuerpo, a distancia y mágico.",
    ["Well, it's not entirely selfless. For me, it's...a long term investment."] = "Bueno, no es del todo desinteresado. Para mí, es... una inversión a largo plazo.",
    ["I don't need your help."] = "No necesito tu ayuda.",
    ["Haha! Well, take it or leave it; it's no skin off my back."] = "¡Jaja! Bueno, tómalo o déjalo; No es piel de mi espalda.",
    ["I was expecting more of a challenge."] = "Esperaba un desafío mayor.",
    ["I was expecting more of a challenge, perhaps something to test my other skills."] = "Esperaba más desafíos, tal vez algo para poner a prueba mis otras habilidades.",
    ["All in good time, Player. This floor may not be complex, but, as you get deeper, you'll need to use all your skills to survive."] = "Todo a su debido tiempo, Player. Puede que este piso no sea complejo, pero, a medida que profundices, necesitarás usar todas tus habilidades para sobrevivir.",
    ["On this floor, you'll be able to fish cave creatures and chop down the creeping trees that grow up the dungeon walls."] = "En este piso, podrás pescar criaturas de las cavernas y talar los árboles rastreros que crecen en las paredes de las mazmorras.",
    ["I'll also give you access to some stock from my shop."] = "También te daré acceso a algunas existencias de mi tienda.",
    ["With the resources available, you should be able to supplement your food supplies by lighting fires and cooking the fish you find."] = "Con los recursos disponibles, deberías poder complementar tus suministros de alimentos encendiendo fuegos y cocinando el pescado que encuentres.",
    ["How are there trees growing underground?"] = "¿Cómo crecen los árboles bajo tierra?",
    ["From what I can tell, they're not native to this plane. Perhaps, like the fish, they were brought through the portals that are dotted about Daemonheim."] = "Por lo que puedo decir, no son nativos de este plano. Quizás, como los peces, fueron traídos a través de los portales que hay repartidos por Daemonheim.",
    ["Where did the fish come from?"] = "¿De dónde vino el pescado?",
    ["I think the past inhabitants of this dungeon brought them through a portal."] = "Creo que los antiguos habitantes de esta mazmorra los trajeron a través de un portal.",
    ["They're remarkably nutritious, even if they don't look appetising."] = "Son extraordinariamente nutritivos, aunque no parezcan apetitosos.",
    ["All in good time, Player. This floor may be simple, but, as you get deeper, you'll need to use all your skills to survive."] = "Todo a su debido tiempo, Player. Este piso puede ser simple, pero, a medida que profundices, necesitarás usar todas tus habilidades para sobrevivir.",
    ["On this floor, you can mine rocks for ore and fashion your own weapons."] = "En este piso, puedes extraer rocas para obtener minerales y crear tus propias armas.",
    ["I've also expanded my shop stock to include fletching tools for making ranged weapons, and rune essence for crafting magical runes."] = "También amplié el stock de mi tienda para incluir herramientas de emplumado para fabricar armas a distancia y esencia rúnica para crear runas mágicas.",
    ["How do I make melee weapons?"] = "¿Cómo hago armas cuerpo a cuerpo?",
    ["Take a pickaxe to the rocks in the dungeon, then smelt the resulting ores in the furnace over there."] = "Lleva un pico a las rocas de la mazmorra y luego funde los minerales resultantes en el horno de allí.",
    ["Finally, grab a hammer and use the smelted bar on the nearby anvil. You can shape the metal into a number of weapons and tools."] = "Finalmente, toma un martillo y usa la barra fundida en el yunque cercano. Puedes darle forma al metal para convertirlo en una serie de armas y herramientas.",
    ["How do I make ranged equipment?"] = "¿Cómo hago equipo a distancia?",
    ["Fletching bows and arrows is easy when you know how. Just grab a knife and use it on a log to make flightless arrow shafts or an unstrung bow."] = "Fletching arcos y flechas es fácil cuando sabes cómo hacerlo. Simplemente toma un cuchillo y úsalo en un tronco para hacer flechas no voladoras o un arco sin cuerda.",
    ["You'll need to add bowstrings to your bows, or feathers and arrowheads to your arrows."] = "Necesitarás agregar cuerdas a tus arcos, o plumas y puntas de flecha a tus flechas.",
    ["How do I craft runes?"] = "¿Cómo creo runas?",
    ["Runecrafting is a powerful skill which is easy to practise within these dungeon walls."] = "Runecrafting es una habilidad poderosa que es fácil de practicar dentro de las paredes de estas mazmorras.",
    ["Daemonheim sits on a site of extreme elemental and chaotic power. This can be focused and channelled through the altar in this room."] = "Daemonheim se encuentra en un sitio de poder elemental y caótico extremo. Esto puede ser enfocado y canalizado a través del altar en esta sala.",
    ["Simply buy some rune essence from my shop - I sell them in special pouches for convenience - and imbue them at the nearby altar. The resulting runes can be used to cast magical spells."] = "Simplemente compra un poco de esencia rúnica en mi tienda (las vendo en bolsas especiales para mayor comodidad) e imbuyelas en el altar cercano. Las runas resultantes se pueden utilizar para lanzar hechizos mágicos.",
    ["I was still expecting more of a challenge."] = "Todavía esperaba un desafío mayor.",
    ["This floor of Daemonheim is home to a species of creature called the bovimastyx. They are non-aggressive, but have thick hides that are perfect for crafting into ranged armour."] = "Este piso de Daemonheim es el hogar de una especie de criatura llamada bovimastyx. No son agresivos, pero tienen pieles gruesas que son perfectas para fabricar armaduras a distancia.",
    ["There are also a number of plants that farmers can harvest. These textiles can be woven into cloth for use in magic robes."] = "También hay una serie de plantas que los agricultores pueden cosechar. Estos textiles se pueden tejer en telas para usar en túnicas mágicas.",
    ["Finally, you have access to the full range of melee armour via smithing."] = "Finalmente, tienes acceso a toda la gama de armaduras cuerpo a cuerpo a través de la herrería.",
    ["Tell me about bovimastyx and ranged armour."] = "Háblame de bovimastyx y armaduras a distancia.",
    ["Tell me more about bovimastyx and ranged armour."] = "Cuéntame más sobre bovimastyx y la armadura a distancia.",
    ["Bovimastyx are large cratures that are easy to trap for those with experience in hunting."] = "Los Bovimastyx son criaturas grandes que son fáciles de atrapar para aquellos con experiencia en la caza.",
    ["You can attack them normally, but you'll be more likely to get hides if you can fletch a suitable trap and get them to step on it."] = "Puedes atacarlos normalmente, pero será más probable que consigas pieles si puedes conseguir una trampa adecuada y lograr que la pisen.",
    ["Tell me about textiles and mage robes."] = "Háblame de textiles y túnicas de mago.",
    ["Tell me more about textiles and mage robes."] = "Cuéntame más sobre textiles y túnicas de mago.",
    ["Otherworldly plants have taken root here, and their stringy leaves and stems are perfect for spinning."] = "Aquí han echado raíces plantas de otro mundo, y sus hojas y tallos fibrosos son perfectos para hilar.",
    ["The result is cloth with remarkable magical properties. It's even mildly resistant to melee damage."] = "El resultado es una tela con notables propiedades mágicas. Es incluso levemente resistente al daño cuerpo a cuerpo.",
    ["Just take a needle and thread to craft it into magic robes."] = "Solo toma una aguja e hilo para crear túnicas mágicas.",
    ["This dungeon floor gives you a taste of everything there is to offer."] = "Este piso de mazmorra te da una idea de todo lo que hay para ofrecer.",
    ["You'll find herbs for potions, chests to unlock, seeds and spores for farming, and we're deep enough for the summoning of familiars to be possible."] = "Encontrarás hierbas para pociones, cofres para desbloquear, semillas y esporas para cultivar, y estamos lo suficientemente profundos como para que sea posible invocar familiares.",
    ["You may also find puzzle rooms, keys and strange doors. Some may lead to rooms that are off the beaten path - optional, as it were."] = "También puedes encontrar salas de rompecabezas, llaves y puertas extrañas. Algunos pueden conducir a habitaciones que están fuera de lo común, opcionales, por así decirlo.",
    ["Tell me about the herbs."] = "Cuéntame sobre las hierbas.",
    ["You can find herbs in a number of areas down here, and many have beneficial properties when mixed with the right reagents."] = "Puedes encontrar hierbas en varias áreas aquí y muchas tienen propiedades beneficiosas cuando se mezclan con los reactivos adecuados.",
    ["You'll need to fill a vial from my shop with water from the tap there. Pop your herb and a suitable secondary item into the vial to create a potion. If you can't find the secondary item you want, I'm also selling them in the"] = "Tendrás que llenar un vial de mi tienda con agua del grifo de allí. Coloca tu hierba y un elemento secundario adecuado en el vial para crear una poción. Si no encuentras el artículo secundario que deseas, también los vendo en el",
    ["shop."] = "tienda.",
    ["Tell me about the chests."] = "Háblame de los cofres.",
    ["Tell me about these chests."] = "Cuéntame sobre estos cofres.",
    ["Locked chests are hard to come by, but the items within them are usually worth the effort."] = "Los cofres cerrados con llave son difíciles de conseguir, pero los objetos que contienen suelen merecer la pena.",
    ["If you've got a trained thief in your party, you can pick the locks and get the loot inside."] = "Si tienes un ladrón entrenado en tu grupo, puedes abrir las cerraduras y meter el botín dentro.",
    ["Tell me about farming with seeds and spores."] = "Cuéntame sobre la agricultura con semillas y esporas.",
    ["It's hard to grow much here in the dark, but the occupants in this place have found a way."] = "Es difícil crecer mucho aquí en la oscuridad, pero los ocupantes de este lugar han encontrado la manera.",
    ["If you can find the relevant seeds, you can grow potatoes, mushrooms, and herbs in the various farming patches. These can be cooked and combined with fish to improve your food."] = "Si puedes encontrar las semillas adecuadas, podrás cultivar patatas, setas y hierbas en las distintas zonas agrícolas. Estos se pueden cocinar y combinar con pescado para mejorar su comida.",
    ["The soil in Daemonheim is extremely fertile: magically so. Simply pop the seed in the ground and it'll become full-grown in just a couple of minutes."] = "El suelo de Daemonheim es extremadamente fértil: mágicamente. Simplemente coloque la semilla en el suelo y crecerá por completo en solo un par de minutos.",
    ["Tell me about summoning familiars."] = "Háblame de summoning familiars.",
    ["Tell me about summoning familiars in Daemonheim."] = "Háblame de summoning familiars en Daemonheim.",
    ["Summoning familiars requires a pouch and spirit shards, available from my shop. You'll also need a specific charm which can be retrieved from fallen enemies."] = "Summoning familiars requiere una bolsa y fragmentos de espíritu, disponibles en mi tienda. También necesitarás un amuleto específico que puedas recuperar de los enemigos caídos.",
    ["Depending on the familiar you're looking to summon, you'll need a summoning secondary item, like ore, wood, textiles, hides, broken bags or food."] = "Dependiendo del familiar que quieras invocar, necesitarás un elemento secundario de invocación, como mineral, madera, textiles, pieles, bolsas rotas o comida.",
    ["Take these items to the summoning obelisk in this room. The finished pouch will enable you to summon a gorajo to help you out."] = "Lleva estos objetos al obelisco de invocación en esta sala. La bolsa terminada te permitirá convocar a un gorajo para que te ayude.",
    ["What's a gora-jo?"] = "¿Qué es un gora-jo?",
    ["It's gora-ho, and they're helpful humanoid creatures from another plane. They seem eager to help when summoned and have their own reasons for disrupting activities in Daemonheim."] = "Son gora-ho y son criaturas humanoides útiles de otro plano. Parecen deseosos de ayudar cuando se les convoca y tienen sus propios motivos para interrumpir las actividades en Daemonheim.",
    ["Tell me about puzzle rooms, keys and strange doors."] = "Cuéntame sobre salas de rompecabezas, llaves y puertas extrañas.",
    ["The founders of this place left rooms to challenge the mind, not just the sword-arm. Be careful in them: many hold penalties for failure."] = "Los fundadores de este lugar dejaron espacios para desafiar la mente, no solo el brazo de la espada. Tenga cuidado con ellos: muchos tienen sanciones por el fracaso.",
    ["You'll also find doors that are locked, protected or beyond reach. You'll need to find a key or use your skills to progress."] = "También encontrarás puertas cerradas, protegidas o fuera de tu alcance. Necesitarás encontrar una clave o usar tus habilidades para progresar.",
    ["Don't feel that you need to explore every room. Some may be optional, while others may require skills that none of you have right now."] = "No sientas que necesitas explorar cada habitación. Algunos pueden ser opcionales, mientras que otros pueden requerir habilidades que ninguno de ustedes tiene en este momento.",
    ["You know all I can teach you already, friend, having conquered many floors yourself."] = "Ya sabes todo lo que puedo enseñarte, amigo, habiendo conquistado muchos pisos tú mismo.",
    ["A friend."] = "Un amigo.",
    ["Okay, what are you doing here, friend?"] = "Vale, ¿qué haces aquí, amigo?",
    ["I'm here to help out."] = "Estoy aquí para ayudar.",
    ["With what?"] = "¿Con qué?",
    ["Well, let's say you find yourself in need of adventuring kit, and you've a heavy pile of rusty coins weighing you down. I can help you with both of those problems. Savvy?"] = "Bueno, digamos que necesitas un equipo de aventuras y tienes una gran pila de coins oxidado sobre ti. Puedo ayudarte con ambos problemas. ¿Comprensión?",
    ["Ah, so you're a trader."] = "Ah, entonces eres un comerciante.",
    ["Keep it down, you fool!"] = "¡Baja el volumen, tonto!",
    ["Yes, I'm a trader. But I'm not supposed to be trading here."] = "Sí, soy un comerciante. Pero se supone que no debo comerciar aquí.",
    ["If you want my goods, you'll learn not to talk about me."] = "Si quieres mis productos, aprenderás a no hablar de mí.",
    ["Right, got you."] = "Bien, te tengo.",
    ["Is there anything else you can do for me?"] = "¿Hay algo más que puedas hacer por mí?",
    ["Well, there's the job I'm supposed to be doing down here."] = "Bueno, ese es el trabajo que se supone que debo hacer aquí abajo.",
    ["Which is?"] = "¿Cuál es?",
    ["Say you chance upon an object you know little about. Show it to me, and I'll tell you what it's used for."] = "Digamos que te topas con un objeto del que sabes poco. Muéstramelo y te diré para qué sirve.",
    ["That's good to know."] = "Es bueno saberlo.",
    ["I can also offer hints about the behaviour of powerful opponents you might meet in the area. I've spent a long time down here, observing them."] = "También puedo ofrecer pistas sobre el comportamiento de oponentes poderosos que puedas encontrar en el área. He pasado mucho tiempo aquí abajo, observándolos.",
    ["I'll be sure to come back if I find a particularly strong opponent, then."] = "Entonces me aseguraré de volver si encuentro un oponente particularmente fuerte.",
    ["You'd be wise to, Player."] = "Sería prudente que lo hicieras, Player.",
    ["How do you know my name?"] = "¿Cómo sabes mi nombre?",
    ["Nothing gets in or out of Daemonheim without me knowing about it."] = "Nada entra o sale de Daemonheim sin que yo lo sepa.",
    ["Fair enough. Back to my other questions."] = "Muy bien. Volviendo a mis otras preguntas.",
    ["Do I have any rewards to claim?"] = "¿Tengo alguna recompensa que reclamar?",
    ["I have no rewards for you at the moment."] = "No tengo recompensas para ti en este momento.",
    ["I'm here to trade."] = "Estoy aquí para intercambiar.",
    ["Sorry, but I don't have anything to sell."] = "Lo siento, pero no tengo nada que vender.",
    ["What great foes await me in this area?"] = "¿Qué grandes enemigos me esperan en esta zona?",
    ["There are a number of terrible foes known to lurk at this depth of Daemonheim. I have seen one such foe lurking about this floor."] = "Se sabe que hay una serie de enemigos terribles que acechan en esta profundidad de Daemonheim. He visto uno de esos enemigos merodeando por este piso.",
    ["The gluttonous behemoth is a great beast with a huge appetite. It will fight using powerful melee attacks, and it has some magical ability."] = "El gigante glotón es una gran bestia con un enorme apetito. Luchará usando poderosos ataques cuerpo a cuerpo y tiene alguna habilidad mágica.",
    ["When wounded, the behemoth will eat in an effort to heal itself. It always has a stockpile of food nearby, so you'll need to stand between the two to stop it from healing. A warning to you: it will ferociously attack anyone blocking"] = "Cuando está herido, el gigante comerá en un esfuerzo por curarse. Siempre tiene una reserva de comida cerca, por lo que tendrás que pararte entre los dos para evitar que se cure. Una advertencia para ti: atacará ferozmente a cualquiera que bloquee",
    ["its path."] = "su camino.",
    ["Astea Frostweb is a mage with a considerable dominion over ice. She will attack with powerful frost-based magicks and she will attempt to freeze you on the spot."] = "Astea Frostweb es una maga con un considerable dominio sobre el hielo. Ella atacará con poderosas magias basadas en escarcha e intentará congelarte en el acto.",
    ["She also has the power to summon ice spiders to her aid, and will call them more frequently against foes who attempt to prevent her magical damage. If that wasn't enough, she can also call upon divine protection from"] = "También tiene el poder de convocar arañas de hielo en su ayuda, y las llamará con más frecuencia contra enemigos que intenten evitar su daño mágico. Si eso no fuera suficiente, también puede invocar la protección divina de",
    ["melee, ranged or magic."] = "cuerpo a cuerpo, a distancia o mágico.",
    ["Icy Bones is a slow but strong ice troll. He will use ranged attacks unless he catches you, in which case he will pummel you with his club."] = "Icy Bones es un troll de hielo lento pero fuerte. Utilizará ataques a distancia a menos que te atrape, en cuyo caso te golpeará con su garrote.",
    ["He can also trap you by raising stalagmites from the ground. If he succeeds, you'll need to be well protected from melee attacks. It might be better to stay out of his reach."] = "También puede atraparte levantando estalagmitas del suelo. Si lo logra, necesitarás estar bien protegido de los ataques cuerpo a cuerpo. Quizás sería mejor mantenerse fuera de su alcance.",
    ["The luminescent icefiend is a larger, more powerful variant of the icefiends wandering Daemonheim. It uses magic and ranged attacks with equal proficiency."] = "El demonio de hielo luminiscente es una variante más grande y poderosa de los demonios de hielo errantes Daemonheim. Utiliza magia y ataques a distancia con igual competencia.",
    ["It will use a devastating spell at certain pain thresholds. Encasing itself in ice, it will become immune to all damage and rain down icicles from above. It is best to avoid these icicles at all costs!"] = "Utilizará un hechizo devastador en ciertos umbrales de dolor. Al encerrarse en hielo, se volverá inmune a todos los daños y hará llover carámbanos desde arriba. ¡Lo mejor es evitar estos carámbanos a toda costa!",
    ["Plane-freezer Lakhrahnaz is a strange creature known as a stalker. It is resistant to ranged and magic attacks, but, unfortunately, striking it with your sword won't be easy."] = "El congelador de aviones Lakhrahnaz es una extraña criatura conocida como acosador. Es resistente a ataques mágicos y a distancia, pero, desafortunadamente, golpearlo con tu espada no será fácil.",
    ["It has frozen the area around it, which has become too slippery to walk on. You must overcome its variety of melee, ranged and magic attacks, as well as the slippery floor of its lair, to get up close and strike at the beast."] = "Ha congelado el área a su alrededor, que se ha vuelto demasiado resbaladiza para caminar. Deberás superar su variedad de ataques cuerpo a cuerpo, a distancia y mágicos, así como el suelo resbaladizo de su guarida, para acercarte y atacar a the beast.",
    ["To'Kash the Bloodchiller is a powerful demon. Like all of its kind, it is susceptible to magic. The demon uses magical as well as melee attacks."] = "To'Kash the Bloodchiller es un demonio poderoso. Como todos los de su especie, es susceptible a la magia. El demonio utiliza ataques mágicos y cuerpo a cuerpo.",
    ["To'Kash has the power to flash-freeze the air's moisture, encasing its victims in blocks of ice. If this happens, I hope you have a friend with you."] = "To'Kash tiene el poder de congelar instantáneamente la humedad del aire, encerrando a sus víctimas en bloques de hielo. Si esto sucede, espero que tengas un amigo contigo.",
    ["You can break a fellow adventurer out of the ice and free them without harming them. If To'Kash frees them, however, he is far from gentle."] = "Puedes sacar a un compañero aventurero del hielo y liberarlo sin hacerle daño. Sin embargo, si To'Kash los libera, estará lejos de ser gentil.",
    ["There is a room full of tunnels with skeletons pouring in. A healer of the gorajo tribe is trying to fight back. She will help you, so long as you are close to her."] = "Hay una habitación llena de túneles por los que entran esqueletos. Un sanador de la tribu gorajo está tratando de defenderse. Ella te ayudará, siempre y cuando estés cerca de ella.",
    ["Her healing is most effective when she's concentrating on only one target. As you defeat more skeletons, watch for the signal that it is time to block a tunnel."] = "Su curación es más efectiva cuando se concentra en un solo objetivo. A medida que derrotes a más esqueletos, estate atento a la señal de que es hora de bloquear un túnel.",
    ["The Hobgoblin Geomancer is a powerful hobgoblin. He carries a spear and conjures various spells. He also has the ability to temporarily sever your link to the gods."] = "El Hobgoblin Geomancer es un poderoso duende. Lleva una lanza y conjura varios hechizos. También tiene la capacidad de cortar temporalmente tu vínculo con los dioses.",
    ["Aside from disabling your prayers, he'll sometimes snare you to the spot, so carrying a ranged weapon might be an advantage."] = "Además de desactivar tus oraciones, a veces te atrapará en el acto, por lo que llevar un arma a distancia podría ser una ventaja.",
    ["The bulwark beast is a stalwart behemoth. His outer shell is as hard as rock and standard weapons won't penetrate it."] = "La bestia baluarte es un gigante incondicional. Su capa exterior es dura como una roca y las armas estándar no la penetran.",
    ["Your best plan would be either to mine away his shell with pickaxes or get around his protection by using magical spells."] = "Tu mejor plan sería extraer su caparazón con picos o eludir su protección usando hechizos mágicos.",
    ["The unholy cursebearer is a powerful user of magic. It will constantly drain your strength while you are close to it. You can restore this strength by worshipping the cursebearer, but this will only make it stronger."] = "El impío portador de la maldición es un poderoso usuario de magia. Constantemente agotará tus fuerzas mientras estés cerca de él. Puedes restaurar esta fuerza adorando al portador de la maldición, pero esto sólo lo hará más fuerte.",
    ["Rammernaut is a brutish human. He carries a huge maul and only uses melee attacks, giving magic users the advantage if they take him on. He's known to get very angry if the gods try to influence the outcome of his"] = "Rammernaut es un humano brutal. Lleva un mazo enorme y solo usa ataques cuerpo a cuerpo, lo que les da a los usuarios de magia la ventaja si se enfrentan a él. Se sabe que se enoja mucho si los dioses intentan influir en el resultado de su",
    ["fights."] = "peleas.",
    ["If he gets enraged, he'll look to charge down his opponents. Best you try to get him to run into a wall whenever he charges blindly."] = "Si se enfurece, buscará atacar a sus oponentes. Lo mejor es que intentes que se estrelle contra una pared cada vez que cargue a ciegas.",
    ["Stomp is an enormous behemoth. Not all if him can fit through the portal to our realm. As he takes damage, you'll find that the lodestones powering the portal will turn on. If you take the associated stones from the floor"] = "Stomp es un gigante enorme. No todos, si él, pueden pasar por el portal a nuestro reino. A medida que reciba daño, descubrirás que las piedras imán que alimentan el portal se encenderán. Si tomas las piedras asociadas del suelo.",
    ["and put them into the lodestones, the portal will weaken. Do this enough times and... well, you'll see."] = "y ponlos en las piedras imán, el portal se debilitará. Haz esto suficientes veces y... bueno, ya verás.",
    ["Har'Lakk the Riftsplitter is a mighty demon. He uses massive magical energy to summon hazardous portals which you would do well to avoid. Magic is his strength as well as his weakness."] = "Har'Lakk the Riftsplitter es un demonio poderoso. Utiliza una enorme energía mágica para invocar portales peligrosos que harías bien en evitar. Magic es tanto su fuerza como su debilidad.",
    ["Lexicus Runewright is, well, mad. He is a powerful librarimancer and is obsessed with books, often using them as weapons. Since he uses magic to do this, you'll find stabbing weapons or ranged attacks are effective in defeating him."] = "Lexicus Runewright está, bueno, enojado. Es un poderoso bibliotecario y está obsesionado con los libros, a menudo usándolos como armas. Dado que usa magia para hacer esto, encontrarás que las armas punzantes o los ataques a distancia son efectivos para derrotarlo.",
    ["Sagittare is a skilled mercenary. He is extremely fast, and can render you immobile. It's best that you try to protect against his magical arrows and figure how to chase him about the room."] = "Sagitario es un mercenario experto. Es extremadamente rápido y puede dejarte inmóvil. Lo mejor es que intentes protegerte de sus flechas mágicas y descubras cómo perseguirlo por la habitación.",
    ["Night-gazer Khighorahk is a stalker that cloaks itself in a shield of shadows. Illumination is its weakness, so keep the torches in the corners of the room lit. This will weaken it and, when weakened fully, it'll make its last stand."] = "El observador nocturno Khighorahk es un acosador que se envuelve en un escudo de sombras. La iluminación es su debilidad, así que mantenga encendidas las antorchas en los rincones de la habitación. Esto lo debilitará y, cuando esté completamente debilitado, hará su última resistencia.",
    ["is a creature of both day and night. Be careful when it flashes, as that is a sign that it will try to blind you. It's best to find something to hide behind to prevent massive damage."] = "es una criatura tanto de día como de noche. Ten cuidado cuando parpadee, ya que es señal de que intentará cegarte. Es mejor encontrar algo detrás de lo cual esconderse para evitar daños masivos.",
    ["Bal'lak the Pummeller is a potent demon. Its defences increase over time, and its weapons open rifts in the ground, through which noxious gases rise. It doesn't seem to like the fumes itself, however, so, if you have a"] = "Bal'lak the Pummeller es un demonio potente. Sus defensas aumentan con el tiempo y sus armas abren grietas en el suelo, a través de las cuales se elevan gases nocivos. Sin embargo, no parece que le gusten los vapores en sí, así que, si tienes un",
    ["defensive party member, lure Bal'lak over them."] = "miembro del grupo defensivo, atrae a Bal'lak sobre ellos.",
    ["The skeletal trio fight as any adventurer would, switching targets and defences to counter their opponents' tactics. You'll need to use magic, ranged, melee and wits to kill off the trio effectively."] = "El trío esquelético lucha como lo haría cualquier aventurero, cambiando objetivos y defensas para contrarrestar las tácticas de sus oponentes. Necesitarás usar magia, a distancia, cuerpo a cuerpo e ingenio para matar al trío de manera efectiva.",
    ["The runebound behemoth is a beast enhanced by mages. It is still tied to the locations that bind it, so operate one class of pillar to remove its defences for a while."] = "El gigante ligado a las runas es una bestia mejorada por magos. Todavía está atado a los lugares que lo unen, así que opera una clase de pilar para eliminar sus defensas por un tiempo.",
    ["A powerful zombie named lords over a dark mausoleum. As you damage him, watch out for the burning effect to the ground about him. As he gets closer to death, he'll call on the deceased and choose graves"] = "Un poderoso zombi llamado señor de un mausoleo oscuro. Mientras lo dañas, ten cuidado con el efecto de quema en el suelo a su alrededor. A medida que se acerca la muerte, visitará al difunto y elegirá tumbas.",
    ["around him. If you don't bless these chosen graves before he rises again, they'll explode and damage anyone near them."] = "a su alrededor. Si no bendices estas tumbas elegidas antes de que resurja, explotarán y dañarán a cualquiera que esté cerca de ellas.",
    ["Necrolords weave rotten flesh and bone into armour and weaponry; a meaty shield keeps swords at bay, a bony sword makes rangers pay."] = "Los necroseñores tejen carne y huesos podridos para crear armaduras y armas; un escudo carnoso mantiene a raya las espadas, una espada ósea hace pagar a los guardabosques.",
    ["Be wary of Flesh-spoiler Haasghenahk. It is somewhat unstable, and liable to burst. Stabbing attacks will help make it explode quicker; just be careful, as there is more inside than meets the eye."] = "Tenga cuidado con el spoiler de carne Haasghenahk. Es algo inestable y propenso a estallar. Los ataques punzantes ayudarán a que explote más rápido; Sólo ten cuidado, ya que hay más dentro de lo que parece.",
    ["Yk'Lagor the Thunderous is a powerful demon, contained by evil mages trying to siphon his power as he remains passive. If you distract enough of the mages pinning him down, their power won't be enough and he'll break free."] = "Yk'Lagor el Atronador es un demonio poderoso, contenido por magos malvados que intentan desviar su poder mientras permanece pasivo. Si distraes lo suficiente a los magos que lo inmovilizan, su poder no será suficiente y él se liberará.",
    ["Watch out as he unleashes true power: if you don't hide from his attacks, you can expect death or a longer fight."] = "Ten cuidado mientras desata su verdadero poder: si no te escondes de sus ataques, puedes esperar la muerte o una pelea más larga.",
    ["Blink will run forever if not stopped, and cannot be hit while he is running. Use something in the room to stop him and then damage him before he runs off again."] = "Blink seguirá funcionando para siempre si no se detiene y no podrá ser golpeado mientras esté corriendo. Usa algo en la habitación para detenerlo y luego dañarlo antes de que vuelva a salir corriendo.",
    ["The warped gulega is a demented familiar from a long-forgotten plane. You'll find that it has great resistance to your attacks. This doesn't apply to things from its own plane, so you'll find familiars are extremely effective"] = "La gulega deformada es un familiar demente de un avión olvidado hace mucho tiempo. Descubrirás que tiene una gran resistencia a tus ataques. Esto no se aplica a cosas de su propio plano, por lo que descubrirás que los familiares son extremadamente efectivos.",
    ["against it."] = "en contra.",
    ["The dreadnauts were human once, but are now screaming monsters. It's best to stay behind him, as he can only kill what he sees in front of him. If you are a quick mage, you'll find running around and firing spells is effective."] = "Los acorazados alguna vez fueron humanos, pero ahora son monstruos que gritan. Es mejor quedarse detrás de él, ya que sólo puede matar lo que ve frente a él. Si eres un mago rápido, descubrirás que correr y disparar hechizos es efectivo.",
    ["The hope devourers feed on faith and fill all with despair. If you see it growl, it would be wise to show that you are not relying on your hope, turning off prayers before he sucks the power from you."] = "Los devoradores de esperanza se alimentan de la fe y llenan a todos de desesperación. Si lo ves gruñir, sería prudente demostrarle que no confías en tu esperanza y apagar las oraciones antes de que te absorba el poder.",
    ["The World-gorger's strengths and weaknesses leak into the world about it. Destroying the eyes on the walls will change its defences to different combat styles; use this to your advantage."] = "Las fortalezas y debilidades del Devorador de Mundos se filtran al mundo a su alrededor. Destruir los ojos en las paredes cambiará sus defensas a diferentes estilos de combate; Usa esto a tu favor.",
    ["Kal'Ger the Warmonger possesses knowledge of how to forge great primal weaponry. He can fly around the room, changing weapons and attack styles; so, keep this in mind and change to new styles to defeat him quickly. If you use"] = "Kal'Ger the Warmonger posee conocimientos sobre cómo forjar grandes armas primarias. Puede volar por la habitación, cambiando de armas y estilos de ataque; así que ten esto en cuenta y cambia a nuevos estilos para derrotarlo rápidamente. si usas",
    ["protect prayers too often he might enrage, so be careful how you use them. As weapons are his strength, wearing armour might be yours..."] = "protege las oraciones con demasiada frecuencia, podría enfurecerlo, así que ten cuidado con cómo las usas. Como las armas son su punto fuerte, llevar armadura podría ser tuyo...",
    ["Can I change my starting items?"] = "¿Puedo cambiar mis artículos iniciales?",
    ["You're currently starting with a stack of coins. I could set up a pre-order, if you'd like."] = "Actualmente estás comenzando con una pila de coins. Podría programar un pedido anticipado, si lo deseas.",
    ["I'll automatically take your coins, and provide a selection of feathers, rune essence and antipoison in return."] = "Automáticamente tomaré tu coins y, a cambio, te proporcionaré una selección de plumas, esencia rúnica y antiveneno.",
    ["I'm currently exchanging your initial selection of coins for feathers, rune essence and antipoison."] = "Actualmente estoy intercambiando tu selección inicial de coins por plumas, esencia rúnica y antiveneno.",
    ["I would like to receive coins."] = "Me gustaría recibir coins.",
    ["I would like to receive feathers, rune essence and antipoison."] = "Me gustaría recibir plumas, esencia rúnica y antiveneno.",
    ["I don't want to change anything."] = "No quiero cambiar nada.",
    ["Very well. Is there anything else you need?"] = "Muy bien. ¿Hay algo más que necesites?",
    ["Can I access my bound and stored items?"] = "¿Puedo acceder a mis artículos encuadernados y almacenados?",
    ["Which one?"] = "¿Cuál?",
    ["Bound items."] = "Artículos encuadernados.",
    ["Smuggler's storage."] = "Almacenamiento de Smuggler.",
    ["I'll be here."] = "Estaré aquí.",
    ["Didn't I just see you?"] = "¿No te acabo de ver?",
    ["Didn't I just see you at the start of the dungeon?"] = "¿No te acabo de ver al comienzo de la mazmorra?",
    ["You managed to get here very quickly."] = "Conseguiste llegar aquí muy rápido.",
    ["I know these floors well, Player. You should spend more time worrying about the dangers lurking below."] = "Conozco bien estos pisos, Player. Debería dedicar más tiempo a preocuparse por los peligros que acechan debajo.",
    ["*The player always starts with the following line:*"] = "*el player siempre comienza con la siguiente línea:*",
    ["Could you tell me what this is used for?"] = "¿Podría decirme para qué se utiliza?",
    ["That's a rock rich in metallic ore. You can smelt it into metal bars at the furnace by using the Smithing skill. It can also be used as a secondary ingredient for bloodrager summoning pouches."] = "Esa es una roca rica en mineral metálico. Puedes fundirlo en barras de metal en el horno usando la habilidad Smithing. También se puede utilizar como ingrediente secundario para las bolsas de invocación de Bloodrager.",
    ["That's a metal bar. You can use it with a hammer on an anvil to create melee armour and weapons by using your smithing abilities."] = "Esa es una barra de metal. Puedes usarlo con un martillo sobre un yunque para crear armaduras y armas cuerpo a cuerpo usando tus habilidades de herrería.",
    ["Those are wooden branches. You can use a tinderbox and your firemaking abilities to burn them, and use the resulting fire to cook. You can also use a knife and your fletching skill to create unstrung bows, basic staves, arrow shafts and traps from them, or use them as a secondary ingredient in creating deathslinger summoning pouches."] = "Esas son ramas de madera. Puedes usar un yesquero y tus habilidades para hacer fuego para quemarlos y usar el fuego resultante para cocinar. También puedes usar un cuchillo y tu habilidad de emplumar para crear arcos sin cuerdas, bastones básicos, flechas y trampas a partir de ellos, o usarlos como ingrediente secundario para crear bolsas de invocación de Deathlinger.",
    ["That's a bowstring. Attach it to an unstrung bow to create a useable ranged weapon."] = "Esa es la cuerda de un arco. Conéctelo a un arco sin cuerda para crear un arma a distancia utilizable.",
    ["That's a textile made from raw plants. Spin it on a spinning wheel to create cloth. You can also use these as a secondary ingredient when creating stormbringer summoning pouches."] = "Es un tejido elaborado a partir de plantas crudas. Gírelo en una rueca para crear tela. También puedes usarlos como ingrediente secundario al crear bolsas de invocación de Stormbringer.",
    ["That is cloth. Use a needle and thread to fashion it into mage armour or magic orbs, using your abilities in crafting. You can also use it to remove poison from weapons."] = "Eso es tela. Usa aguja e hilo para convertirlo en una armadura de mago u orbes mágicos, usando tus habilidades en la elaboración. También puedes usarlo para eliminar el veneno de las armas.",
    ["That's a trap. You can set it in a room with a bovimastyx and trap the creature. You can then skin it to get hides."] = "Eso es una trampa. Puedes colocarlo en una habitación con un bovimastyx y atrapar a la criatura. Luego puedes desollarlo para obtener pieles.",
    ["That's a mastyx hide. You can use a needle and thread to create ranged armour from it, and it can also be used as a secondary ingredient for hoardstalker summoning pouches."] = "Esa es una piel de Mastyx. Puedes usar aguja e hilo para crear una armadura a distancia a partir de ella, y también se puede usar como ingrediente secundario para las bolsas de invocación de hoardstalker.",
    ["That's divine energy. You can use it to craft Divination portents."] = "Esa es energía divina. Puedes usarlo para crear portentos Divination.",
    ["That's a memory. You can convert it into experience and energy at a crater."] = "Eso es un recuerdo. Puedes convertirlo en experiencia y energía en un cráter.",
    ["That's a portent of restoration. It will heal you if you are brought to below half of your health."] = "Ese es un presagio de restauración. Te curará si llegas a menos de la mitad de tu salud.",
    ["That's a portent of passage. It can be used to give you access to rooms that you do not meet the requirements for."] = "Ese es un presagio de transición. Se puede utilizar para darle acceso a habitaciones para las que no cumple con los requisitos.",
    ["That's thread. You can use that, along with a needle, to make ranged armour from hides, or mage armour from cloth."] = "Ese es el hilo. Puedes usarlo, junto con una aguja, para hacer armaduras a distancia con pieles o armaduras de mago con tela.",
    ["That's rune essence. You can use it at an altar to create magical runes using the runecrafting skill."] = "Esa es la esencia rúnica. Puedes usarlo en un altar para crear runas mágicas usando la habilidad de creación de runas.",
    ["Those are magical runes. They contain the magical energies needed to cast spells. You can't be proficient in magic without them."] = "Esas son runas mágicas. Contienen las energías mágicas necesarias para lanzar hechizos. No puedes dominar la magia sin ellos.",
    ["That fish is raw. You can cook it on a fire or range, using your cooking abilities to create food for healing injuries."] = "Ese pescado está crudo. Puedes cocinarlo en el fuego o en la estufa, usando tus habilidades culinarias para crear alimentos para curar heridas.",
    ["That fish is cooked to perfection. Eating it will heal some of your lost life points. You can also use these as secondary ingredients in skinweaver summoning pouches."] = "Ese pescado está cocinado a la perfección. Comerlo curará algunos de tus puntos de vida perdidos. También puedes usarlos como ingredientes secundarios en las bolsas de invocación de tejedores de piel.",
    ["That's a burnt fish. It's entirely useless."] = "Eso es un pescado quemado. Es completamente inútil.",
    ["That's a seed. You can plant it to grow a variety of useful plants by utilising your farming skills."] = "Eso es una semilla. Puedes plantarlo para cultivar una variedad de plantas útiles utilizando tus habilidades agrícolas.",
    ["Urgh, that herb is dirty. Clean it using your abilities in herblore and it becomes an ingredient for potions."] = "Urgh, esa hierba está sucia. Límpialo usando tus habilidades en herblore y se convierte en un ingrediente para pociones.",
    ["That's an empty vial. You can fill it with water to begin the process of mixing potions using your herblore skills."] = "Ese es un vial vacío. Puedes llenarlo con agua para comenzar el proceso de mezclar pociones usando tus habilidades herblore.",
    ["That's a vial of water. Add a clean herb to create an unfinished potion. This is a step in the process of making potions using your herblore skills."] = "Eso es un frasco de agua. Agrega una hierba limpia para crear una poción sin terminar. Este es un paso en el proceso de hacer pociones usando tus habilidades de herboristería.",
    ["That's a restorative potion. Potions of this kind restore lost stats or cure negative ailments, such as poison."] = "Esa es una poción reconstituyente. Las pociones de este tipo restauran las estadísticas perdidas o curan dolencias negativas, como el veneno.",
    ["That's a hatchet. Cut branches from trees with it using your Woodcutting skill. It can also be used to hack down wooden obstructions that are in your way."] = "Eso es un hacha. Corta ramas de árboles con él usando tu habilidad Woodcutting. También se puede utilizar para derribar obstáculos de madera que se encuentren en su camino.",
    ["That's a pickaxe. You can obtain ore from rocks with it using your abilities in mining, and it can also be used as a melee weapon. Rocky barricades block your path in Daemonheim, so your pickaxe can chip away at them."] = "Eso es un pico. Puedes obtener mineral de las rocas usando tus habilidades en minería y también puede usarse como arma cuerpo a cuerpo. Las barricadas rocosas bloquean tu camino en Daemonheim, por lo que tu pico puede derribarlas.",
    ["That's a chisel. You can use it with a hammer to carve things. As far as I know, useful for getting past the dungeon's puzzling mechanisms."] = "Eso es un cincel. Puedes usarlo con un martillo para tallar cosas. Hasta donde yo sé, es útil para superar los desconcertantes mecanismos de la mazmorra.",
    ["That's a melee weapon, so hit enemies with it. It will be particularly effective against opponents with light or no armour."] = "Esa es un arma cuerpo a cuerpo, así que golpea a los enemigos con ella. Será particularmente efectivo contra oponentes con armadura ligera o sin armadura.",
    ["That's an arrow shaft. Attach a feather to it, using your abilities in fletching to create a headless arrow."] = "Eso es el eje de una flecha. Adjunta una pluma y usa tus habilidades para realizar emplumadas para crear una flecha sin cabeza.",
    ["That's a feather. Attach it to an arrow shaft, using your abilities in fletching to create a headless arrow."] = "Eso es una pluma. Sujétalo al eje de una flecha y usa tus habilidades para realizar flechas para crear una flecha sin cabeza.",
    ["That's a headless arrow. Attach arrowheads to it, using your abilities in fletching to create a finished arrow."] = "Esa es una flecha sin cabeza. Adjunte puntas de flecha, utilizando sus habilidades para realizar flechas para crear una flecha terminada.",
    ["That's an arrow. Fire it from a bow using your ranged abilities and deal damage to your enemies."] = "Eso es una flecha. Dispáralo con un arco usando tus habilidades a distancia e inflige daño a tus enemigos.",
    ["That's an unstrung bow. Attach a bowstring to it to create a useable ranged weapon."] = "Ese es un arco sin cuerda. Adjunte una cuerda de arco para crear un arma a distancia utilizable.",
    ["That's a finished bow. Fire arrows at your enemies using your ranged skills."] = "Ese es un arco terminado. Dispara flechas a tus enemigos usando tus habilidades a distancia.",
    ["That's a throwing knife. You can throw it at enemies."] = "Eso es un cuchillo arrojadizo. Puedes arrojarlo a los enemigos.",
    ["That's metal armour. It gives excellent protection against melee and ranged attacks, but weakens your magic powers and renders you vulnerable to magic."] = "Esa es una armadura de metal. Proporciona una excelente protección contra ataques cuerpo a cuerpo y a distancia, pero debilita tus poderes mágicos y te vuelve vulnerable a la magia.",
    ["That's mage armour. It offers limited protection against attacks, but enhances your magical abilities."] = "Esa es la armadura de mago. Ofrece protección limitada contra ataques, pero mejora tus habilidades mágicas.",
    ["That's ranger armour. It offers excellent protection against magic, but mediocre protection against ranged and melee attacks."] = "Esa es la armadura de guardabosques. Ofrece una excelente protección contra la magia, pero una protección mediocre contra ataques cuerpo a cuerpo y a distancia.",
    ["That's a basic staff. You can enchant it at an altar using your skills in runecrafting to enhance its powers."] = "Ese es un staff básico. Puedes encantarlo en un altar usando tus habilidades en la creación de runas para mejorar sus poderes.",
    ["That's a magic wand which will enhance your spellcasting. You can enchant some wands at an altar, using your skills in runecrafting to enhance their powers."] = "Esa es una varita mágica que mejorará tu lanzamiento de hechizos. Puedes encantar algunas varitas en un altar, usando tus habilidades en la elaboración de runas para mejorar sus poderes.",
    ["That's a magic orb which you can carry in your off-hand to enhance your spellcasting. You can enchant some orbs at an altar, using your skills in runecrafting to enhance their powers."] = "Es un orbe mágico que puedes llevar en tu mano izquierda para mejorar tu lanzamiento de hechizos. Puedes encantar algunos orbes en un altar, usando tus habilidades en la creación de runas para mejorar sus poderes.",
    ["That's a catalytic orb. Equipping it in your will increase the accuracy of your magic spells."] = "Ese es un orbe catalítico. Equiparlo en tu aumentará la precisión de tus hechizos mágicos.",
    ["That's a shield that provides a bit of protection against dragons' fiery breath. You don't want to meet a dragon without a shield like that, or you'll fry."] = "Es un escudo que proporciona un poco de protección contra el aliento de fuego de los dragones. No querrás encontrarte con un dragón sin un escudo así, o te freirás.",
    ["Those are just bones. Bury them: it makes the happy, and they will hear your prayers."] = "Esos son sólo huesos. Entiérralos: eso hace felices a los demás, y escucharán tus oraciones.",
    ["This is - was - an adventurer's pack. I'll give you cash for it, or you can use it as a secondary ingredient when creating worldbearer summoning pouches."] = "Esta es, era, una manada de aventureros. Te daré dinero en efectivo por ello, o puedes usarlo como ingrediente secundario al crear bolsas de invocación de portadores del mundo.",
    ["That's a gatestone. Drop it on the floor and you'll be able to teleport back to it later."] = "Esa es una piedra de entrada. Déjalo caer al suelo y podrás teletransportarte a él más tarde.",
    ["This is a key and it opens locked doors. Think of where you swiped it from, and check a door nearby."] = "Esta es una llave que abre puertas cerradas. Piensa de dónde lo robaste y revisa una puerta cercana.",
    ["Urgh! That fish stinks! Even if you cooked it, only a real beast would eat that."] = "¡Uf! ¡Ese pescado apesta! Incluso si lo cocinases, sólo una verdadera bestia se lo comería.",
    ["Bleurgh! Even cooked, that thing stinks! Feed it to an animal quickly, before you stink out the whole of Daemonheim."] = "¡Bleurgh! ¡Incluso cocida, esa cosa apesta! Aliméntalo a un animal rápidamente, antes de que apestes todo Daemonheim.",
    ["Those? Those are nothing. You can give them all to me, if you want."] = "¿Esos? Esos no son nada. Puedes dármelos todos, si quieres.",
    ["If they're nothing, why would you want them?"] = "Si no son nada, ¿para qué los querrías?",
    ["Pft. It was worth a try. Those are rusty coins: lovely money. You can buy things from me with them."] = "Pft. Valió la pena intentarlo. Esos están oxidados coins: dinero precioso. Puedes comprarme cosas con ellos.",
    ["That's your ring of kinship. It binds you to your allies and allows access to party options."] = "Ese es tu anillo de parentesco. Te vincula con tus aliados y permite el acceso a las opciones del grupo.",
    ["It looks like a letter to me. Mind if I take a look?"] = "Me parece una carta. ¿Te importa si echo un vistazo?",
    ["What's it doing down here?"] = "¿Qué está haciendo aquí abajo?",
    ["...Perhaps a keepsake for one of the residents."] = "...Quizás un recuerdo para uno de los residentes.",
    ["Does it belong to you?"] = "¿Te pertenece?",
    ["I have no idea what you are talking about."] = "No tengo idea de qué estás hablando.",
    ["Hmm, okay, if you say so."] = "Hmm, está bien, si tú lo dices.",
    ["Where did you find that? Give it here! You didn't read it did you?"] = "¿Dónde encontraste eso? ¡Dámelo aquí! No lo leíste ¿verdad?",
    ["Yes. What does it have to do with you?"] = "Sí. ¿Qué tiene que ver contigo?",
    ["That's none of your business! Let's just forget this happened, okay?"] = "¡Eso no es asunto tuyo! Olvidemos que esto pasó, ¿vale?",
    ["Sheesh, alright!"] = "¡Dios, está bien!",
    ["No, I didn't. It seemed personal, so I didn't look."] = "No, no lo hice. Parecía personal, así que no miré.",
    ["Well, uh, thanks, I guess. Let's just not talk about this, shall we?"] = "Bueno, gracias, supongo. Simplemente no hablemos de esto, ¿vale?",
    ["You can count on me."] = "Puedes contar conmigo.",
    ["Uh... I've never seen anything like that... Let me see it. ... It's uh... It's not mine if that's what you're asking."] = "Uh... Nunca había visto algo así... Déjame verlo. ... Es uh... No es mío si eso es lo que estás preguntando.",
    ["Hmmm, okay. If you say so."] = "Mmmm, está bien. Si tú lo dices.",
    ["*(Applies to antique rings, arrowheads, ashes, bananas, broken climbing hook heads, climbing hooks, climbing hook heads, coloured vials, journals, magical blastboxes, meatcorn, meatcorn ropes, orbs of oculus, potatoes (except baked cave potato), power crystals, shadow silk hoods, wooden planks and more.)*"] = "*(Se aplica a anillos antiguos, puntas de flecha, cenizas, plátanos, cabezas de ganchos de escalada rotas, ganchos de escalada, cabezas de ganchos de escalada, viales de colores, diarios, cajas explosivas mágicas, maíz de carne, cuerdas de maíz de carne, orbes de óculo, patatas (excepto patatas de cueva horneadas), cristales de poder, capuchas de seda de sombra, planks de madera y más.)*",
    ["I've never seen anything like that before. I've no idea, sorry."] = "Nunca antes había visto algo así. No tengo idea, lo siento.",
    ["Oh. Thanks anyway."] = "Oh. Gracias de todos modos.",
    ["A snake pokes its head out of the wall and attacks you."] = "Una serpiente asoma la cabeza por la pared y te ataca.",
    ["Ouch!"] = "¡Ay!",
    ["I'm getting ready to travel north and take on Ivar to become the new king of giants."] = "Me estoy preparando para viajar al norte y enfrentarme a Ivar para convertirme en el nuevo rey de los gigantes.",
    ["But you're not a giant and you're quite small."] = "Pero no eres un gigante y eres bastante pequeño.",
    ["Old mumsy used to tell me there's nothing that little old Snakearms can't do..."] = "La vieja mamá solía decirme que no hay nada que el pequeño Snakearms no pueda hacer...",
    ["...except come to think of it... there is quite a lot I can't do..."] = "...excepto que ahora que lo pienso... hay muchas cosas que no puedo hacer...",
    ["Hi, human."] = "Hola, humano.",
    ["Hi, ogre."] = "Hola, ogro.",
    ["How are you today, little ogre?"] = "¿Cómo estás hoy, pequeño ogro?",
    ["Can I have some shiny pretties, human?"] = "¿Puedo tener algunas bellezas brillantes, humano?",
    ["What makes you think I'd give my shiny pretties to you?"] = "¿Qué te hace pensar que te daría mis bellezas brillantes?",
    ["That skinny lady at de bank say visitors bring lots of shiny pretties with them when they come visit Oo'glog. Me want my share!"] = "Esa señora flaca del banco dice que los visitantes traen consigo muchas bellezas brillantes cuando vienen a visitar Oo'glog. ¡Quiero mi parte!",
    ["Ah, you see, I've given your share to that skinny lady at the bank; you'll have to ask her for it yourself. Make sure you ask really loudly and growl at her every time she uses a word you don't understand, okay?"] = "Ah, verás, le he dado tu parte a esa señora flaca del banco; Tendrás que pedírselo tú mismo. Asegúrate de preguntarle en voz muy alta y gruñirle cada vez que use una palabra que no entiendes, ¿de acuerdo?",
    ["Yay! Thanks human. I'm gonna get my shiny pretties, even if I have to growl all afternoon."] = "¡Sí! Gracias humano. Voy a conseguir mis bellezas brillantes, incluso si tengo que gruñir toda la tarde.",
    ["Fine, please and thank you very much, madam sir!"] = "¡Bien, por favor y muchas gracias señora señor!",
    ["You're very...polite."] = "Eres muy... educado.",
    ["Me know! Me practising! Balnea say I can have job in Customer Rations when I grow up if me polite enough."] = "¡Lo sé! ¡Yo practicando! Balnea dice que puedo tener trabajo en Customer Rations cuando sea mayor si soy lo suficientemente educado.",
    ["Don't you mean 'Customer Relations'?"] = "¿No te refieres a 'Relaciones Customer'?",
    ["Blechh! Dat not sound near as tasty as 'Customer Rations'. Me not sure me want de job after all."] = "¡Blechh! Eso no suena tan sabroso como 'Customer Rations'. Después de todo, no estoy seguro de querer el trabajo.",
    ["Hey, human. What did you bring me?"] = "Hola, humano. ¿Qué me trajiste?",
    ["Hmm, let me think carefully about this. Oh, yes, I remember, now! Absolutely nothing."] = "Hmm, déjame pensar detenidamente en esto. ¡Oh, sí, ahora lo recuerdo! Absolutamente nada.",
    ["Aw, shucks."] = "Ay, caray.",
    ["How does it feel to be so puny wee small, human?"] = "¿Cómo se siente ser tan pequeño, humano?",
    ["Oh, I dunno. How does it feel to be so incredibly dense?"] = "Oh, no lo sé. ¿Cómo se siente ser tan increíblemente denso?",
    ["Uhh...what dat s'pposed to mean?"] = "Uhh... ¿qué se supone que significa eso?",
    ["Me like pie!"] = "¡Me gusta el pastel!",
    ["Pie! Pie! Pie! Pie! Pie!"] = "¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel! ¡Pastel!",
    ["Yes, dear, pie."] = "Sí, querido, pastel.",
    ["Me wanna go visit Fycie 'n Bugs!"] = "¡Quiero ir a visitar Fycie y Bugs!",
    ["Yes, they're both delightful individuals."] = "Sí, ambos son personas encantadoras.",
    ["Will you take me to see dem, human?"] = "¿Me llevarás a verlos, humano?",
    ["Didn't your mother ever teach you not to talk to strangers?"] = "¿Tu madre nunca te enseñó a no hablar con extraños?",
    ["Me wants CHOMPY for dinner!"] = "¡Quiero CHOMPY para cenar!",
    ["Me hopes you GETS chompy for dinner!"] = "¡Espero que te pongas nervioso para la cena!",
    ["What you talk weird like dat for, human? You sound silly!"] = "¿Por qué hablas así de raro, humano? ¡Suenas tonto!",
    ["Not so very good. Me just drop me lunch in de pool."] = "No muy bien. Simplemente déjame el almuerzo en la piscina.",
    ["Ew...I think I can see it floating over there."] = "Ew... Creo que puedo verlo flotando por allí.",
    ["Oh, thank you human! I have it as a snack next time I go for swim!"] = "¡Oh, gracias humano! ¡Lo tomaré como refrigerio la próxima vez que vaya a nadar!",
    ["You very cute, little creature. Me want to have a human as a pet. What you doing, human? You busy? You want be my little pet human creature?"] = "Eres una pequeña criatura muy linda. Quiero tener un humano como mascota. ¿Qué estás haciendo, humano? ¿Estas ocupado? ¿Quieres ser mi pequeña criatura humana mascota?",
    ["Uh...I think I'm busy at the moment."] = "Uh... Creo que estoy ocupado en este momento.",
    ["Pwetty please?"] = "¿Pequeño, por favor?",
    ["Look, sorry to disappoint, but this isn't going to happen."] = "Mira, lamento decepcionarte, pero esto no va a suceder.",
    ["Aw, you no fun, human."] = "Ay, no eres divertido, humano.",
    ["Can you tell me about this thermal bath?"] = "¿Puedes hablarme de este baño termal?",
    ["Yes, it very hot!"] = "¡Sí, hace mucho calor!",
    ["Yes. Hence the word 'thermal' as a descriptor. How terribly observant of you."] = "Sí. De ahí la palabra \"térmico\" como descriptor. Qué terriblemente observador de tu parte.",
    ["Heat come up from belly of de ground, make you feel lots better when you swim in it."] = "El calor que sube desde el vientre del suelo te hace sentir mucho mejor cuando nadas en él.",
    ["What do you mean?"] = "¿Qué quieres decir?",
    ["Oh, it simple! You feel poisoned, you feel diseased or you just take beating in battle, just take bath in de hot water and you feel all better in no time. It easy to notice effect if you just try it out - but maybe you human types not smart enough to notice things much."] = "¡Oh, es simple! Te sientes envenenado, enfermo o simplemente recibes una paliza en la batalla, simplemente báñate en agua caliente y te sentirás mejor en poco tiempo. Es fácil notar el efecto si lo pruebas, pero tal vez los humanos no sean lo suficientemente inteligentes como para notar mucho las cosas.",
    ["Ahem!"] = "¡Ejem!",
    ["Oo, no spread that cough to me - it sound bad! You better take a swim right now, feel better!"] = "Oh, no me contagie esa tos, ¡suena mal! Será mejor que te bañes ahora mismo, ¡siéntete mejor!",
    ["Can you tell me about this salt-water spring?"] = "¿Puedes hablarme de este manantial de agua salada?",
    ["Yeah, sure, human! De water flows fast from underground. When you bathe here, it make you flow fast overground for long, long time."] = "¡Sí, claro, humano! El agua fluye rápidamente desde el subsuelo. Cuando te bañas aquí, te hace fluir rápidamente sobre la superficie durante mucho, mucho tiempo.",
    ["Flow fast?"] = "¿Fluir rápido?",
    ["You know, flow on your feetsies. Fast-like. Quick, like a bunny!"] = "Ya sabes, fluye sobre tus pies. Rápido. ¡Rápido, como un conejito!",
    ["Are you talking about running?"] = "¿Estás hablando de correr?",
    ["Yeah, run, flow - same thing. Have bath here, it not matter how heavy you are, how much you carry - you can flow long time!"] = "Sí, corre, fluye, lo mismo. Báñese aquí, no importa lo pesado que sea o lo que cargue, ¡puede fluir durante mucho tiempo!",
    ["Thanks, that's good to know."] = "Gracias, es bueno saberlo.",
    ["You pick the target's pocket."] = "Escoges el bolsillo del objetivo.",
    ["You snatch the spies' notes. Smearing them in chocolate beyond repair."] = "Arrebatas las notas de los espías. Untarlos en chocolate sin posibilidad de reparación.",
    ["The following has been added to your currency pouch: [number] Spring tokens."] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] Fichas de primavera.",
    ["You have reached the Spring token soft cap of 30,000. You need to spend some tokens in Gummy's store before you can earn more."] = "Ha alcanzado el límite flexible del token Spring de 30 000. Debes gastar algunas fichas en la tienda de Gummy antes de poder ganar más.",
    ["Your pickpocket target becomes aware of your presence."] = "Su objetivo carterista se da cuenta de su presencia.",
    ["You cannot keep pickpocketing as you have a full inventory."] = "No puedes seguir robando carteras porque tienes un inventario completo.",
    ["You fail to steal from the target."] = "No logras robarle al objetivo.",
    ["You've been stunned."] = "Has quedado atónito.",
    ["Uh...uh...achooo!"] = "Uh... uh... ¡achooo!",
    ["Bless you."] = "Bendito seas.",
    ["Pestilence asked me to look into ways of recruiting more underlings - uh, I mean members - into the clan."] = "Pestilence me pidió que buscara formas de reclutar más subordinados (eh, quiero decir miembros) para el clan.",
    ["I thought that perhaps offering a fast way here for potential applicants would help sign them on, so I drew this little summoning circle."] = "Pensé que tal vez ofrecer una forma rápida aquí para los posibles solicitantes ayudaría a inscribirse, así que dibujé este pequeño círculo de convocatoria.",
    ["It's powered by the candles around the edge - the more that are lit, the more potent and efficient the spell."] = "Funciona con las velas que se encuentran alrededor del borde: cuantas más estén encendidas, más potente y eficiente será el hechizo.",
    ["*sniffle* If you fancy helping I could pay you in Spooky tokens for every guest you summon - consider it your commission."] = "*sniffle* Si te apetece ayudar, podría pagarte en fichas Spooky por cada invitado que convoques; considéralo tu comisión.",
    ["*sniffle* Bye bye."] = "*sollozo* Adiós.",
    ["Can you tell me about this copper-coloured pool?"] = "¿Puedes hablarme de esta piscina de color cobre?",
    ["Yeah, it red!"] = "¡Sí, es rojo!",
    ["Yes, I can see that."] = "Sí, puedo verlo.",
    ["Then why you ask, silly human?"] = "Entonces, ¿por qué lo preguntas, humano tonto?",
    ["Well, it's hard to explain. I just sense a strange energy coming from this pool. Do you know anything about it?"] = "Bueno, es difícil de explicar. Siento una extraña energía proveniente de este estanque. ¿Sabes algo al respecto?",
    ["Oh, well, it called de 'Bandos pool' round here. It s'pposed to be special-special. It hard to explain to human creature like you. Maybe you need talk to auntie Seegud. She explain good about these things."] = "Oh, bueno, por aquí se llama 'piscina Bandos'. Se supone que es especial, especial. Es difícil de explicarle a una criatura humana como tú. Quizás necesites hablar con la tía Seegud. Ella explica bien sobre estas cosas.",
    ["*Any one of the following may happen:*"] = "*Cualquiera de los siguientes puede ocurrir:*",
    ["*Option 1*"] = "*Opción 1*",
    ["*sings* Let it snow, let it snow, let it snow."] = "*canta* Déjalo nevar, déjalo nevar, déjalo nevar.",
    ["*Option 2*"] = "*Opción 2*",
    ["*sings* I'm dreaming of a white RuneScape."] = "*canta* Estoy soñando con un RuneScape blanco.",
    ["*Option 3*"] = "*Opción 3*",
    ["*sings* There's no business like snow business!"] = "*canta* ¡No hay negocio como el negocio de la nieve!",
    ["*Option 4*"] = "*Opción 4*",
    ["Did you know that we snow imps have over a hundred words for snow?"] = "¿Sabías que los diablillos de las nieves tenemos más de cien palabras para referirse a la nieve?",
    ["Nah. I made that up."] = "No. Yo lo inventé.",
    ["*Option 5*"] = "*Opción 5*",
    ["Snowflakes! Millions of snowflakes! No two are the same, you know."] = "¡Copos de nieve! ¡Millones de copos de nieve! No hay dos iguales, ¿sabes?",
    ["*Option 6*"] = "*Opción 6*",
    ["Isn't snow brilliant?"] = "¿No es brillante la nieve?",
    ["*Option 7*"] = "*Opción 7*",
    ["Snow! Ha ha ha ha! Snow everywhere!"] = "¡Nieve! ¡Ja, ja, ja, ja! ¡Nieve por todas partes!",
    ["I's a snow imp! From der Land of snow!"] = "¡Soy un diablillo de las nieves! ¡Desde el país de la nieve!",
    ["The Land of Snow?"] = "¿La tierra de la nieve?",
    ["The Land of Snow! Y'know, the magic land where snow comes from."] = "¡La tierra de la nieve! Ya sabes, la tierra mágica de donde viene la nieve.",
    ["Where did you think snow came from? Maybe that it appears spontaneously, like when water vapour in the air forms into ice crystals?"] = "¿De dónde pensaste que venía la nieve? ¿Quizás aparece de forma espontánea, como cuando el vapor de agua del aire se transforma en cristales de hielo?",
    ["Well, yes, actually."] = "Bueno, sí, en realidad.",
    ["Ha ha ha! Don't be silly! It comes from the Land of Snow."] = "** Diablillo de las nieves: ** ¡Ja, ja, ja! ¡No seas tonto! Proviene del País de la Nieve.",
    ["Why are you making it snow?"] = "¿Por qué haces que nieve?",
    ["Cause it's Christmas, innit."] = "Porque es Navidad, ¿no?",
    ["What can I do with all this snow?"] = "¿Qué puedo hacer con toda esta nieve?",
    ["Whatever yer like! I don't care! There's plen'y more where this lot came from."] = "¡Lo que quieras! ¡No me importa! Hay mucho más de donde vino este lote.",
    ["You could make a snowman, if you like. When it's big enough, I'll give you a snowman 'at to finish it. These 'ats also include a veg'table fer a nose an' anything else yer need."] = "Podrías hacer un muñeco de nieve, si quieres. Cuando sea lo suficientemente grande, te daré un muñeco de nieve para terminarlo. Estos platos también incluyen una mesa de verduras para la nariz y cualquier otra cosa que necesites.",
    ["Or you could just 'have a good ol'-fashioned snowball fight!"] = "¡O simplemente podrías \"tener una buena pelea de bolas de nieve a la antigua usanza!",
    ["Could I have a snowman hat, please?"] = "¿Podría darme un gorro de muñeco de nieve, por favor?",
    ["*Option appears to select a snowman hat.*"] = "*Aparece la opción para seleccionar un sombrero de muñeco de nieve.*",
    ["Can I go to the Land of Snow?"] = "¿Puedo ir al País de la Nieve?",
    ["We don't just let anyone into the Land of Snow, mate. You need to show you like snow first. Help to build a snowman!"] = "No dejamos que nadie entre a la Tierra de la Nieve, amigo. Primero debes demostrar que te gusta la nieve. ¡Ayuda a construir un muñeco de nieve!",
    ["Oi, yous!"] = "¡Oye, tú!",
    ["Yes! We's got a big problem. Santa's gone missing!"] = "¡Sí! Tenemos un gran problema. ¡Papá Noel ha desaparecido!",
    ["Again? Doesn't it happen almost every other year?"] = "¿Otra vez? ¿No sucede casi cada dos años?",
    ["Pretty much. I dunno how he always does that. It's 'cause everybody luvs him, methinks. But anyways!"] = "Más o menos. No sé cómo siempre hace eso. Creo que es porque todo el mundo lo quiere. ¡Pero de todos modos!",
    ["Tell me more."] = "Cuéntame más.",
    ["Some massive ice island been floating down from up North. Now normally we's not interested in more ice, especially in Gielinor. We just stick to der Land of Snow. But dat one was special! We got word dat it was covered in pressies!"] = "Una enorme isla de hielo ha estado flotando desde el norte. Normalmente no nos interesa más hielo, especialmente en Gielinor. Simplemente nos quedamos en el País de la Nieve. ¡Pero ese fue especial! ¡Nos enteramos de que estaba cubierto de prensas!",
    ["We had to in-vest-gi... In-ve-stag... Check it out. So my pal <Player's snow imp> went to have a look."] = "Tuvimos que in-vestir-gi... In-ve-stag... Compruébalo. Entonces mi amigo <Player's snow imp> fue a echar un vistazo.",
    ["<Player's snow imp>! I know him!"] = "¡<Player's snow imp>! ¡Lo conozco!",
    ["Oh yeah? Are you Player?"] = "¿Ah, sí? ¿Eres Player?",
    ["That's me!"] = "¡Ese soy yo!",
    ["He always talks about you! In good ways, mostly, too! Anyways. He went there, then he never came back. We knows he didn't open der pressies 'cause dat's against der rules. So Prince Jack went ta look for him. And 'e never came back too. Sooo... Der Queen went..."] = "¡Él siempre habla de ti! ¡En el buen sentido, sobre todo también! De todos modos. Fue allí y nunca regresó. Sabemos que no abrió las imprentas porque eso va en contra de las reglas. Entonces el príncipe Jack fue a buscarlo. Y tampoco volvió nunca más. Entonces... Der Queen fue...",
    ["Let me guess. They're all gone? <Player's snow imp>, Jack, the Queen of Snow and Santa?"] = "Déjame adivinar. ¿Se han ido todos? <Player's snow imp>, Jack, el Queen of Snow y Santa?",
    ["Yaaa! Der mystery pressies kidnapped all of Christmas! Will ya help?"] = "¡Yaaa! ¡Las prensas misteriosas secuestraron toda la Navidad! ¿Me ayudarás?",
    ["Yes, I will"] = "Sí, lo haré",
    ["Yaaaay! Time ta save everybody!"] = "¡Yaaaay! ¡Es hora de salvar a todos!",
    ["So, what do I need to do?"] = "Entonces, ¿qué debo hacer?",
    ["Go to da island, find everyone and come back? There is a lodestone on it, so it's easy to get there. We's sent an Orb of oculus ta see, and we saw der pressies. They all got a label on ta say who they are for. But dey's not our pressies. We didn't pack them. And anyone dat's got somefink to do wiv Christmas who goes there vanishes. Go check der labels out. Find <Player's snow imp>! We's counting on ya!"] = "¿Ir a la isla, encontrar a todos y volver? Hay un lodestone, por lo que es fácil llegar allí. Enviamos un orbe de óculo para ver y vimos las prensas. Todos tienen una etiqueta que dice para quién son. Pero ellos no son nuestros presos. No los empacamos. Y cualquiera que tenga algo que hacer con la Navidad y vaya allí, desaparece. Ve a revisar las etiquetas. ¡Encuentra <Player's snow imp>! ¡Contamos contigo!",
    ["I guess I'll have a look, then."] = "Supongo que echaré un vistazo entonces.",
    ["No, sorry"] = "No, lo siento",
    ["Booooo, I'll have ta ask someone nicer."] = "Booooo, tendré que pedírselo a alguien más amable.",
    ["*(If you talk to him again)*"] = "*(Si vuelves a hablar con él)*",
    ["Ah, it's ya. Did ya change yer mind? Will ya help Santa and der Queen and Jack and <Imp's name>?"] = "Ah, eres tú. ¿Cambiaste de opinión? ¿Ayudarás a Santa, a la Reina, a Jack y a <Imp's name>?",
    ["*(Same options as above)*"] = "*(Las mismas opciones que arriba)*",
    ["*After all Quests parts completed*"] = "*Después de completar todas las partes de las misiones*",
    ["Hiya again! So, have you saved everybody yet?"] = "¡Hola de nuevo! Entonces, ¿ya salvaste a todos?",
    ["I knew ya could do it! Three cheers for Player!"] = "¡Sabía que podías hacerlo! ¡Tres hurras por Player!",
    ["Hey, Player!"] = "¡Oye, Player!",
    ["[Snow imp]! Nice to see you!"] = "¡[Snow imp]! ¡Qué bueno verte!",
    ["Nice ta see ya too! I missed ya a bit. It's nice of ya to pay me a little visit!"] = "¡Encantado de verte también! Te extrañé un poco. ¡Qué amable de tu parte hacerme una pequeña visita!",
    ["Well that's the least I could do for a friend!"] = "Bueno, ¡eso es lo menos que puedo hacer por un amigo!",
    ["Ya! Best ooman mate eva!"] = "¡Sí! ¡La mejor compañera de ooman, eva!",
    ["I's good. Christmas went very well after we saved der day from der evil penguins!"] = "Estoy bien. ¡La Navidad fue muy bien después de que salvamos el día de los malvados pingüinos!",
    ["Yes, I remember! We freed Jack after cooking the penguins a feast, and the Queen of Snow after doing some ice-skating. We freed Santa after defeating the penguins and their Snowverload with snowmen..."] = "¡Sí, lo recuerdo! Liberamos a Jack después de preparar un festín para los pingüinos y a Queen of Snow después de patinar sobre hielo. Liberamos a Santa después de derrotar a los pingüinos y su Snowverload con muñecos de nieve...",
    ["We did! Der penguins wanted ta take ova der world by givin' pressies to kings and queens. Pressies wiv penguins in! But instead of giving der pressie ta King Arthur, we gave der pressie to der King Black Dragon."] = "¡Lo hicimos! Los pingüinos querían apoderarse del mundo dándoles prensas a reyes y reinas. Pressies con pingüinos dentro! Pero en lugar de darle la prensa a King Arthur, le dimos la prensa al Rey Dragón Negro.",
    ["The look on their faces! Priceless. You almost had me, though! I thought we were done for!"] = "¡La expresión de sus caras! Inestimable. ¡Aunque casi me tienes! ¡Pensé que estábamos acabados!",
    ["Haha! Ya shouldn't have worried! Der King Black Dragon is an old friend. I deliver his pressies every year! But anyways!"] = "¡Jaja! ¡No deberías haberte preocupado! El Rey Dragón Negro es un viejo amigo. ¡Le entrego sus prensas todos los años! ¡Pero de todos modos!",
    ["We had a party for der penguins to keep em out of pressies, deir leader was all grumpies but Christmas was saved! I wonder if he'll ever get up to more mischief..."] = "Tuvimos una fiesta para los pingüinos para mantenerlos alejados de las presiones, su líder estaba de mal humor, ¡pero se salvó la Navidad! Me pregunto si alguna vez hará más travesuras...",
    ["What an adventure it was! Good times!"] = "¡Qué aventura fue! ¡Buenos tiempos!",
    ["True dat! Hopefully dere'll be no mischief next time, but den I wouldn't get ta see ya!"] = "¡Es cierto! Ojalá no haya ninguna travesura la próxima vez, ¡pero no podré verte!",
    ["Can you come with me to Gielinor?"] = "¿Puedes venir conmigo a Gielinor?",
    ["Nah, sorry. Dem planes are not close enuff for me ta make it through."] = "No, lo siento. Los aviones no están lo suficientemente cerca como para que pueda pasar.",
    ["But you could use that portal there?"] = "¿Pero podrías usar ese portal allí?",
    ["Snow imp-proof, that is. Besides, I've got my hands full with Scourges!"] = "A prueba de nieve, claro está. Además, ¡tengo las manos ocupadas con Scourges!",
    ["What? Is he back to his old tricks?"] = "¿Qué? ¿Ha vuelto a sus viejos trucos?",
    ["Nah mate... but dat don't stop me from pranking 'im!"] = "No amigo... ¡pero eso no me impide hacerle una broma!",
    ["Ha! Maybe I could come along and give you a hand? I still have that old ghost costume."] = "¡Ja! ¿Quizás podría venir y echarte una mano? Todavía tengo ese viejo disfraz de fantasma.",
    ["I don't fink they'll let ya. The Land of Snow ain't really a place for oomans."] = "No creo que te dejen. La Tierra de la Nieve no es realmente un lugar para oomans.",
    ["Ah well... I guess I can always come back here to see you?"] = "Ah, bueno... ¿Supongo que siempre puedo volver aquí para verte?",
    ["Dat ya can!"] = "¡Eso sí puedes!",
    ["Tell me about the Queen of Snow and Santa."] = "Cuéntame sobre Queen of Snow y Santa.",
    ["It's a long story."] = "Es una larga historia.",
    ["I've got time for it."] = "Tengo tiempo para ello.",
    ["Round Christmas, Gielinor and the Land of Snow are close together, so, 'casionally, random people stumble across portals an' turn up in the Land of Snow. Ages ago, some young lad - wearing a fancy red costume and carryin' a"] = "Durante la Navidad, Gielinor y la Tierra de la Nieve están muy juntos, por lo que, ocasionalmente, personas al azar tropiezan con portales y aparecen en la Tierra de la Nieve. Hace mucho tiempo, un joven, vestido con un elegante traje rojo y llevando una",
    ["backpack with some pressies in it - pops out of nowhere in the Palace of Snow's garden. Well, the youngest princess 'appened to be 'aving a snowball fight in the garden with us snow imps. She saw this guy, whose name was Nicklaus,"] = "backpack con algunas prensas dentro: aparece de la nada en el jardín del Palacio de la Nieve. Bueno, la princesa más joven parecía estar teniendo una pelea de bolas de nieve en el jardín con nosotros, los diablillos de nieve. Vio a este tipo, cuyo nombre era Nicklaus,",
    ["and they got talking. In fact, they got on so well that she gave him some of 'er very best magic deer fer flying places with. Event'ly, he went away, but he didn't forget her. A year or so later 'e came back, this time askin' fer"] = "y se pusieron a hablar. De hecho, se llevaban tan bien que ella le regaló algunos de sus mejores ciervos mágicos para volar. Al final se fue, pero no la olvidó. Un año más tarde regresó, esta vez preguntando por",
    ["her hand in marriage. Now, marriage 'tween an ice sprite and an ooman is real frowned upon, but the Princess really loved Nicklaus, so they let 'er do it and, soon af'er, Prince Jack appeared. A decade of married bliss passed and the"] = "su mano en matrimonio. Ahora, el matrimonio entre un duende del hielo y un hombre está muy mal visto, pero la princesa realmente amaba a Nicklaus, así que la dejaron hacerlo y, poco después, apareció el Príncipe Jack. Pasó una década de felicidad matrimonial y el",
    ["Princess was chosen to take the throne as Queen of Snow. That was kinda weird, 'cause the Princess was married to a human, but she couldn't say no. Soon their duties took up all of their time, an' Santa, as uvvers knew him, was"] = "La princesa fue elegida para ocupar el trono como Queen of Snow. Eso fue un poco extraño, porque la princesa estaba casada con un humano, pero no podía decir que no. Pronto sus deberes ocuparon todo su tiempo, y Santa, como lo conocían todos, fue",
    ["getting old much faster than she was. It was thought best that Santa leave the Land of Snow; which meant Jack grew up without his dad. Jack's mum were really busy, so 'e was neglected an' became re-belly-us."] = "envejeciendo mucho más rápido que ella. Se pensó que era mejor que Santa abandonara la Tierra de la Nieve; lo que significaba que Jack creció sin su padre. La madre de Jack estaba muy ocupada, por lo que la descuidaron y se volvió rebelde.",
    ["Wow, that's a sad story. But where does Scourge come into all this?"] = "Vaya, esa es una historia triste. ¿Pero dónde entra Scourge en todo esto?",
    ["De start of these two stories are pretty similar! Scourge was a young'un once, just like Nick he stumbled across the Land of Snow by accident. This was shortly before Nick found it. Scourge and the princess fell in love, just like"] = "¡El comienzo de estas dos historias es bastante similar! Scourge alguna vez fue un joven, al igual que Nick, tropezó con la Tierra de la Nieve por accidente. Esto fue poco antes de que Nick lo encontrara. Scourge y la princesa se enamoraron, al igual que",
    ["Nick - Scourge went away, but 'e didn't come back for years. The princess watched 'is actions in - and saw how crew-ol he really was. Soon she was distracted by the arrival of Santa n any feelings she'd had for Scourge"] = "Nick - Scourge se fue, pero no regresó durante años. La princesa observó sus acciones en y vio lo amable que era en realidad. Pronto se distrajo con la llegada de Santa y cualquier sentimiento que hubiera tenido por Scourge.",
    ["melted. A long time later Scourge returned, but the Snow Queen had no time for 'im. That embittered Scourge."] = "derretido. Mucho tiempo después, Scourge regresó, pero la Reina de las Nieves no tenía tiempo para él. Ese Azote amargado.",
    ["Two stories, so very similar and yet so very different."] = "Dos historias, muy similares y, al mismo tiempo, muy diferentes.",
    ["You got a point there."] = "Tienes razón.",
    ["Actually, never mind."] = "En realidad, no importa.",
    ["Can you leave me for a while?"] = "¿Puedes dejarme por un tiempo?",
    ["Could you leave me for a while?"] = "¿Podrías dejarme un rato?",
    ["Sure - see ya! Just op'rate yer amulet to call me back."] = "Claro, ¡nos vemos! Solo opera tu amuleto para volver a llamarme.",
    ["[Snow imp's name] returns to his duties."] = "[Snow imp's name] vuelve a sus funciones.",
    ["Ello, [Player]!"] = "¡Hola, [Player]!",
    ["Hello again [Snow imp]. Merry Christmas!"] = "Hola de nuevo [Snow imp]. ¡Feliz navidad!",
    ["Merry Christmas [Player], thanks for bringing me to da feastie!"] = "Feliz Navidad [Player], ¡gracias por invitarme a la fiesta!",
    ["No problem! It wouldn't be Christmas without [Snow imp], would it?"] = "¡No hay problema! No sería Navidad sin [Snow imp], ¿verdad?",
    ["Certainly not [Player]"] = "Ciertamente no [Player]",
    ["Aight' guv?"] = "¿Está bien, jefe?",
    ["[Snow imp name] flashes you a cheeky wink."] = "[Snow imp name] te hace un guiño descarado.",
    ["You'd better be chatting to the big man imself'."] = "Será mejor que estés charlando con el gran hombre en persona.",
    ["The imp points at Santa."] = "El diablillo señala a Santa.",
    ["[Buy one of the new Christmas jumpers from the Christmas Spirit Shop, and unlock the Snowman Slippers from the new seasonal quest 'Cold Front'.]"] = "[Compra uno de los nuevos jerseys navideños en la tienda navideña Spirit y desbloquea las zapatillas de muñeco de nieve de la nueva misión de temporada 'Cold Front'.]",
    ["[The Christmas festivities have now ended.]"] = "[Las fiestas navideñas ya han terminado.]",
    ["You do not have any space in your inventory to catch this impling."] = "No tienes espacio en tu inventario para captar este implicado.",
    ["The following has been added to your currency pouch: 100 x Christmas spirit."] = "Se ha añadido lo siguiente a su bolsa de divisas: 100 x Espíritu navideño.",
    ["You manage to catch the impling and loot it."] = "Consigues atrapar el implícito y saquearlo.",
    ["You manage to catch the impling and squeeze it into a jar."] = "Consigues coger el implícito y exprimirlo en un frasco.",
    ["Let the snow rangers and warriors step up to fight. I shall show them that Magic is the mightiest art."] = "Deja que los guardabosques y los guerreros de las nieves den un paso al frente para luchar. Les mostraré que Magic es el arte más poderoso.",
    ["Foolish warrior. Your helm will not protect you from my mighty spells."] = "Guerrero tonto. Tu yelmo no te protegerá de mis poderosos hechizos.",
    ["Let us see whether your arrows of ice will win against my bolts of arcane power."] = "Veamos si tus flechas de hielo vencerán a mis rayos de poder arcano.",
    ["En garde, fellow wizard. We shall see who of us is the stronger."] = "En guardia, compañero mago. Veremos quién de nosotros es más fuerte.",
    ["To fight in the snow tournament, complete the 'Cold Front' quest."] = "Para luchar en el torneo de nieve, completa la misión \"Frente Frío\".",
    ["Acquire the Queen of Snow's permission, 'fore I barrage and feign contrition."] = "Obtenga el permiso de Queen of Snow, antes de atacar y fingir arrepentimiento.",
    ["I need her Majesty's commission? I'll go and file that petition."] = "¿Necesito el encargo de Su Majestad? Iré y presentaré esa petición.",
    ["Til ye bear her concession, we're frozen assets. (Pardon the expression.)"] = "Hasta que aceptes su concesión, somos activos congelados. (Perdón por la expresión.)",
    ["When I complete her festive mission, I'll strike you down with swift perdition."] = "Cuando complete su misión festiva, te derribaré con una rápida perdición.",
    ["You need snowballs equipped to take part in a snowball fight!"] = "¡Necesitas bolas de nieve equipadas para participar en una pelea de bolas de nieve!",
    ["The Christmas festivities have now ended."] = "Las fiestas navideñas ya han terminado.",
    ["Afraid your puny adventurer arms can't handle a little sentient snow, Player?"] = "¿Tienes miedo de que tus débiles brazos de aventurero no puedan soportar un poco de nieve sensible, Player?",
    ["Come on. Let's fight!"] = "Vamos. ¡Luchemos!",
    ["Don't be afraid to unleash your full snowball fighting against me! The Queen of Snow will make sure I come back."] = "¡No tengas miedo de desatar toda tu bola de nieve luchando contra mí! El Queen of Snow se asegurará de que regrese.",
    ["Let's give the crowd what they want!"] = "¡Démosle a la multitud lo que quiere!",
    ["Show me what you've got, Player!"] = "¡Muéstrame lo que tienes, Player!",
    ["The crowd makes me feel so alive!"] = "¡La multitud me hace sentir tan vivo!",
    ["Ha ha! None are a match for my bow."] = "¡Ja, ja! Ninguno es rival para mi arco.",
    ["Your sword lacks finesse. I shall win the day."] = "Tu espada carece de delicadeza. Ganaré el día.",
    ["Let us test our bows against one another."] = "Probemos nuestros arcos unos contra otros.",
    ["Your enchantments are no match for my arrows, sorcerer."] = "Tus encantamientos no son rival para mis flechas, hechicero.",
    ["Before I shoot you with precision, you'll have to get the Queen's permission."] = "Antes de dispararte con precisión, tendrás que obtener el permiso de la Reina.",
    ["Thou must secure majestic concession. 'Tis the path toward progression."] = "Debes conseguir una concesión majestuosa. Es el camino hacia la progresión.",
    ["Hail, noble visitor. We, who are about to melt, salute you."] = "Salve, noble visitante. Nosotros, que estamos a punto de derretirnos, os saludamos.",
    ["Ha ha! There's nothing like the clash of ice on ice."] = "¡Ja, ja! No hay nada como el choque de hielo contra hielo.",
    ["Ha ha! Your holly bow is no match for my ice sword."] = "¡Ja, ja! Tu arco sagrado no es rival para mi espada de hielo.",
    ["I will triumph over your spells, yet."] = "Aún triunfaré sobre tus hechizos.",
    ["I'd beat you into submission were it not for the Queen's permission."] = "Te golpearía hasta someterte si no fuera por el permiso de la Reina.",
    ["Til thee bringeth royal concession, we cannot commence our combat session."] = "Hasta que no hagas una concesión real, no podemos comenzar nuestra sesión de combate.",
    ["Would you like to try a delicious snowcone?"] = "¿Te gustaría probar un delicioso cono de nieve?",
    ["That sounds lovely. Now let's give it a try... Wait... what is this... Ah! Oh no! It's..."] = "Eso suena encantador. Ahora intentémoslo... Espera... ¿qué es esto? ¡Ah! ¡Oh, no! Es...",
    ["BRAIN FREEZE!"] = "¡CONGELACIÓN CEREBRAL!",
    ["*(The dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["Merry Christmas! Welcome to the Land of Snow!"] = "¡Feliz Navidad! ¡Bienvenidos a la Tierra de la Nieve!",
    ["Merry Christmas!"] = "¡Feliz Navidad!",
    ["And a Happy New Year!"] = "¡Y un feliz año nuevo!",
    ["What is the Land of Snow?"] = "¿Qué es la Tierra de la Nieve?",
    ["The Land of Snow is where all the magic of winter weather comes from. Not nasty weather like blizzards, but clear, bright stars above and crips snow underfoot."] = "La Tierra de la Nieve es de donde proviene toda la magia del clima invernal. No un clima desagradable como las ventiscas, sino estrellas claras y brillantes arriba y nieve crujiente bajo los pies.",
    ["I want to go home."] = "Quiero irme a casa.",
    ["Very well! Go forth and have a happy Christmas!"] = "¡Muy bien! ¡Adelante y que tengas una feliz Navidad!",
    ["Snowverload has spawned in the snowball arena. Work together to bring it down!"] = "Snowverload ha aparecido en la arena de bolas de nieve. ¡Trabajad juntos para derribarlo!",
    ["You take some snowballs. Snowverload will now attack you if you have them equipped!"] = "Toma algunas bolas de nieve. ¡Snowverload ahora te atacará si los tienes equipados!",
    ["You don't have enough space in your backpack to take any snowballs."] = "No tienes suficiente espacio en tu backpack para meter bolas de nieve.",
    ["You can't attack while transmogrified into this form."] = "No puedes atacar mientras estás transformado en esta forma.",
    ["You can only attack Snowverload with snowballs!"] = "¡Solo puedes atacar a Snowverload con bolas de nieve!",
    ["Snowverload traps you in a bauble! Roll in front of them to be smashed free."] = "¡Snowverload te atrapa en una chuchería! Ruede frente a ellos para liberarse.",
    ["You weren't in range for Snowverload to smash the bauble. Best you roll away!"] = "No estabas dentro del alcance de Snowverload para romper la chuchería. ¡Será mejor que te vayas rodando!",
    ["Snowverload shatters you free from the bauble!"] = "¡Snowverload te libera de la chuchería!",
    ["You break free from the bauble!"] = "¡Te liberas de la chuchería!",
    ["You've been turned into a fire entity. Find the [number] snow elementals to free yourself!"] = "Te has convertido en una entidad de fuego. ¡Encuentra los elementales de nieve [número] para liberarte!",
    ["You've successfully melted all the snow elementals!"] = "¡Has derretido con éxito todos los elementales de nieve!",
    ["A present has spawned. Get in it before Snowverload attacks!"] = "Ha surgido un regalo. ¡Entra antes de que ataque Snowverload!",
    ["You successfully hide in the present and dodge Snoverload's attack."] = "Te escondes con éxito en el presente y esquivas el ataque de Snoverload.",
    ["You've no need to do that."] = "No es necesario que hagas eso.",
    ["You've been turned into a snowman. Find the fire entity to melt yourself!"] = "Te has convertido en un muñeco de nieve. ¡Encuentra la entidad de fuego para derretirte!",
    ["You've been successfully melted by the fire entity!"] = "¡La entidad de fuego te ha derretido con éxito!",
    ["You've been covered with a stocking. Run around to shake it free!"] = "Te han cubierto con una media. ¡Corre para liberarlo!",
    ["The Queen of Snow protects you from death!"] = "¡El Queen of Snow te protege de la muerte!",
    ["Defeating Snowverload has rewarded you with some festive goodies! They can be found in your backpack, or at your feet if you have no space."] = "¡Derrotar a Snowverload te ha recompensado con algunos regalos festivos! Puedes encontrarlos en tu backpack, o a tus pies si no tienes espacio.",
    ["[50–100] x Snowball"] = "[50–100] x Bola de nieve",
    ["[200–300] x Christmas wrapping paper"] = "[200–300] x Papel de regalo navideño",
    ["You have acquired Snowverload's nose!"] = "¡Has adquirido la nariz de Snowverload!",
    ["Since you have no more space in your backpack, Snowverload's nose has been sent to your bank."] = "Como no tienes más espacio en tu backpack, la nariz de Snowverload ha sido enviada a tu banco.",
    ["The following has been added to your currency pouch: 500 x Christmas spirit."] = "Se ha añadido lo siguiente a su bolsa de divisas: 500 x Espíritu navideño.",
    ["You have already received rewards from killing Snowverload this hour so cannot claim any more."] = "Ya recibiste recompensas por matar a Snowverload esta hora, así que no puedes reclamar más.",
    ["Try again when they next appear."] = "Inténtalo de nuevo la próxima vez que aparezcan.",
    ["I hear the owlery has a new dish, snails with sprinkles! I really should go and try them out."] = "He oído que la lechucería tiene un plato nuevo: ¡caracoles con chispas! Realmente debería ir y probarlos.",
    ["Outta de way, human. Dis place not open yet!"] = "Fuera del camino, humano. ¡Este lugar aún no está abierto!",
    ["That's not very friendly."] = "Eso no es muy amigable.",
    ["Me said OUTTA DE WAY! You no can sleep here!"] = "¡Dije FUERA DEL CAMINO! ¡No puedes dormir aquí!",
    ["Alright, alright! Keep your hat on! I never said I wanted to."] = "¡Está bien, está bien! ¡Mantén tu sombrero puesto! Nunca dije que quisiera.",
    ["How's business?"] = "¿Cómo va el negocio?",
    ["Is okay. De sleepers like de fluffsie pillows. Dey good for small, soft heads like yours. You big help to Snurgh. If you ever wants to try dem out, you can stay free anytime."] = "Está bien. A los que duermen les gustan las almohadas mullidas. Son buenos para cabezas pequeñas y suaves como la tuya. Eres de gran ayuda para Snurgh. Si alguna vez quieres probarlos, puedes permanecer libre en cualquier momento.",
    ["Why, thank you. I'll keep that in mind."] = "Bueno, gracias. Lo tendré en cuenta.",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["Leave me alone."] = "Déjame en paz.",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["*(Some of the following dialogues appear above Solak and Merethiel with some being displayed as* colour=#00DFFF}} *and* colour=#9B30FF}} *in the chat box). All lines are voiced unless noted otherwise.*"] = "*(Algunos de los siguientes diálogos aparecen encima de Solak y Merethiel y algunos se muestran como* color=#00DFFF}} *y* color=#9B30FF}} *en el cuadro de chat). Todas las líneas están expresadas a menos que se indique lo contrario.*",
    ["*Start of fight*"] = "*Inicio de la pelea*",
    ["*Green spore bomb special attack*"] = "*Ataque especial de bomba de esporas verdes*",
    ["*Spawning volatile rootlings*"] = "*Desovando raíces volátiles*",
    ["*Root special attack*"] = "*Ataque especial de raíz*",
    ["*Failing to deal enough damage to Solak's arms and legs in time*"] = "*No lograr causar suficiente daño a los brazos y piernas de Solak a tiempo*",
    ["MWAHHAHAHAHA (not voiced)"] = "MWAHHAHAHAHA (sin voz)",
    ["*After recalling Blight afflicted core*"] = "*Después de recordar el núcleo afectado por Blight*",
    ["*Entering phase 2*"] = "*Entrando a la fase 2*",
    ["Free me...I can't hold on any longer... (only appears in the chatbox and is not voiced)"] = "Free me...I can't hold on any longer... (solo aparece en el chatbox y no tiene voz)",
    ["*Cleansing with Merethiel*"] = "*Limpieza con Merethiel*",
    ["Player needs aid! Champions! Let me cleanse you, step into the light. (\"Player needs aid!\" does not appear in the chat box, and the entire line is not voiced)"] = "Player needs aid! Champions! Let me cleanse you, step into the light. (\"¡Player necesita ayuda!\" no aparece en el cuadro de chat y no se expresa toda la línea)",
    ["*Attempting to cleanse during Merethiel's cooldown*"] = "*Intentando limpiar durante el tiempo de reutilización de Merethiel*",
    ["I have no energy at the moment...He's draining me. (not voiced)"] = "I have no energy at the moment...He's draining me. (sin voz)",
    ["*Anima bomb special attack*"] = "*Ataque especial de bomba anima*",
    ["*Anima barrage special attack*"] = "*Ataque especial de bombardeo de anima*",
    ["*Binding crush special attack*"] = "*Ataque especial de aplastamiento vinculante*",
    ["*Being instantly killed by the binding crush*"] = "*Siendo asesinado instantáneamente por el aplastamiento vinculante*",
    ["Pitiful mortal (not voiced)"] = "Pitiful mortal (sin voz)",
    ["*Tornado special attack*"] = "*Ataque especial de tornado*",
    ["ARGHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH (not voiced)"] = "ARGHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH (sin voz)",
    ["*Entering phase 3*"] = "*Entrando a la fase 3*",
    ["*Stun special attack*"] = "*Aturdir ataque especial*",
    ["GIVE ME THE LIFE YOU SO TIGHTLY CLING TO. (has two voice recordings)"] = "GIVE ME THE LIFE YOU SO TIGHTLY CLING TO. (tiene dos grabaciones de voz)",
    ["*Charging a sigil*"] = "*Cargando un sigilo*",
    ["Arghhh (not voiced)"] = "Arghhh (sin voz)",
    ["Erethdor is pushing back on my connection, watch out! (not voiced)"] = "Erethdor is pushing back on my connection, watch out! (sin voz)",
    ["*Attempting to enter Solak's mind before charging a sigil*"] = "*Intentando entrar en la mente de Solak antes de cargar un sigilo*",
    ["I haven't got a connection yet, you'll need to subdue Solak before I can send anyone through. (not voiced)"] = "I haven't got a connection yet, you'll need to subdue Solak before I can send anyone through. (sin voz)",
    ["*Attempting to enter Solak's mind while two players are already inside*"] = "*Intentando entrar en la mente de Solak mientras dos jugadores ya están dentro*",
    ["I can't send you through, the connection to his mind is not yet strong enough to let anyone else in. (not voiced)"] = "I can't send you through, the connection to his mind is not yet strong enough to let anyone else in. (sin voz)",
    ["*Attempting to leave Solak's mind too soon*"] = "*Intentando salir de la mente de Solak demasiado pronto*",
    ["I don't have the strength to pull you back through just yet, break Erethdor's hold! (not voiced)"] = "I don't have the strength to pull you back through just yet, break Erethdor's hold! (sin voz)",
    ["*Entering phase 4*"] = "*Entrando a la fase 4*",
    ["I'm going to make a connection to Solak's mind to cast him out. (reuses the \"I'm going to make a connection to cast him out.\" voice line)"] = "I'm going to make a connection to Solak's mind to cast him out. (reutiliza la línea de voz \"Voy a hacer una conexión para expulsarlo.\")",
    ["I can't transport you between this world and his mind that quickly... (not voiced)"] = "I can't transport you between this world and his mind that quickly... (sin voz)",
    ["*Charging a blight bomb*"] = "*Cargando una bomba plaga*",
    ["THIS ENDS NOW. (has two voice recordings)"] = "THIS ENDS NOW. (tiene dos grabaciones de voz)",
    ["*Launching a blight bomb*"] = "*Lanzando una bomba plaga*",
    ["Blight in its purest form, let it rain amongst you (not voiced)"] = "Blight in its purest form, let it rain amongst you (sin voz)",
    ["*Solak's consciousness being killed*"] = "*La conciencia de Solak está siendo asesinada*",
    ["*Defeating Solak*"] = "*Derrotando a Solak*",
    ["*Being resurrected after defeating Solak*"] = "*Ser resucitado después de derrotar a Solak*",
    ["No champion, the grove will not allow you to die after freeing Solak! (not voiced)"] = "No champion, the grove will not allow you to die after freeing Solak! (sin voz)",
    ["WHAT WOULD YOU LIKE TO SAY?"] = "¿QUÉ TE GUSTARÍA DECIR?",
    ["Claim loot."] = "Reclama el botín.",
    ["I have nothing for you..."] = "No tengo nada para ti...",
    ["[Player] received: [number] [Item]."] = "[Player] recibió: [número] [Item].",
    ["[Player] received: 1 torn grimoire page."] = "[Player] recibió: 1 página de grimorio rota.",
    ["Solak?"] = "¿Solak?",
    ["Solak? Is that you? Are you free from Erethdor's influence?"] = "¿Solak? ¿Eres tu? ¿Estás libre de la influencia de Erethdor?",
    ["Yes... I am finally myself again, albeit frailer than I used to be."] = "Sí... Por fin vuelvo a ser yo mismo, aunque más frágil de lo que solía ser.",
    ["Oh Solak, what a relief!"] = "¡Oh Solak, qué alivio!",
    ["It fills me with joy to see you freed from my brother's corruption and hold. It is unforgivable what he did to you and the grove."] = "Me llena de alegría verte libre de la corrupción y el control de mi hermano. Es imperdonable lo que te hizo a ti y a la arboleda.",
    ["Please, let me pledge my fealty to you and help you restore the grove while you heal."] = "Por favor, déjame prometerte mi lealtad y ayudarte a restaurar la arboleda mientras te recuperas.",
    ["Ah, Merethiel, what happened here was not your wrongdoing, the crimes of your blood are not your own."] = "Ah, Merethiel, lo que pasó aquí no fue tu culpa, los crímenes de tu sangre no son tuyos.",
    ["I beg of you, let me help. My magic will help you and the grove heal once again."] = "Te lo ruego, déjame ayudarte. Mi magia os ayudará a ti y a la arboleda a sanar una vez más.",
    ["SELECT AN OPTION"] = "Selecciona una opción",
    ["Can I fight Solak?"] = "¿Puedo luchar contra Solak?",
    ["I agree. You should let her help. Think about the grove!"] = "Estoy de acuerdo. Deberías dejarla ayudar. ¡Piensa en la arboleda!",
    ["The grove needs to be restored. I agree that together, we could achieve more in a shorter time."] = "Es necesario restaurar la arboleda. Estoy de acuerdo en que juntos podríamos lograr más en menos tiempo.",
    ["You're a strong independent tree, you don't need her!"] = "Eres un árbol fuerte e independiente, ¡no la necesitas!",
    ["How dare you speak to the ancient Guardian of the Grove like that?"] = "¿Cómo te atreves a hablarle así al antiguo Guardián de la Arboleda?",
    ["He might not 'need' me - but together we can help restore the grove faster."] = "Puede que no me \"necesite\", pero juntos podemos ayudar a restaurar la arboleda más rápido.",
    ["It would fill me with pride to help you, ancient one. I'm not driven by guilt for my brother's misdeeds, but I need a purpose. I am here already, so let me help, if you will?"] = "Me llenaría de orgullo ayudarte, anciano. No me mueve la culpa por las fechorías de mi hermano, pero necesito un propósito. Ya estoy aquí, así que déjame ayudarte, ¿quieres?",
    ["So be it, young elf. I thank you for freeing me."] = "Que así sea, joven elfo. Te agradezco por liberarme.",
    ["And you and your valiant friends, human."] = "Y tú y tus valientes amigos, humanos.",
    ["Why do you have a hole in your chest?"] = "¿Por qué tienes un agujero en el pecho?",
    ["When Erethdor came for the heart, he took me by surprise. He had quickly conjured a dark magic, a powerful blight that quickly burnt through my bark revealing the grove's greatest treasure."] = "Cuando Erethdor vino por el corazón, me tomó por sorpresa. Rápidamente había conjurado una magia oscura, una poderosa plaga que rápidamente quemó mi corteza y reveló el mayor tesoro de la arboleda.",
    ["The grove contains a great many treasures, but greatest is the heart of the tree. A long long time ago, walkers much larger than I would roam the lands. Huge hulking beings. They were very few, so the stories say..."] = "La arboleda contiene muchos tesoros, pero el más grande es el corazón del árbol. Hace mucho, mucho tiempo, caminantes mucho más grandes que yo deambulaban por las tierras. Seres enormes y corpulentos. Eran muy pocos, eso dicen las historias...",
    ["When these creatures got old they'd lay down across valleys to die. Upon their death their bodies would become one with the land. They sprouted forests so vast even I would have trouble traversing. It was one of these very far away groves I went to hide the heart in."] = "Cuando estas criaturas envejecían, se tumbaban en los valles para morir. Tras su muerte, sus cuerpos se volverían uno con la tierra. De ellos surgieron bosques tan vastos que incluso a mí me resultaría difícil atravesarlos. Fue una de esas arboledas muy lejanas donde fui a esconder el corazón.",
    ["Rarely one of these groves will spawn trees like this one, its roots dig so deep they almost pierce the elder halls themselves, being this close to the core they soaked the anima for thousands of years."] = "Rara vez una de estas arboledas genera árboles como este, sus raíces son tan profundas que casi perforan los pasillos de los ancianos, al estar tan cerca del núcleo de que empaparon el ánima durante miles de años.",
    ["Eventually this tree will be so fed it will in a sense come to life, develop thoughts and can be communed with. With complete power over the land around them they shaped and carved it, the magic of this land led to an all manner of creatures being attracted whilst also spawning its own from the magical bark."] = "Con el tiempo, este árbol será tan alimentado que, en cierto sentido, cobrará vida, desarrollará pensamientos y podrá comunicarse con él. Con poder total sobre la tierra que los rodeaba, la moldearon y tallaron, la magia de esta tierra llevó a que atrajeran todo tipo de criaturas y al mismo tiempo engendraran las suyas propias a partir de la corteza mágica.",
    ["Like the wisps you find floating around and the fairies... Though I believe they're simply fond of the mushrooms the land produces. Quaint little things."] = "Como los mechones que encuentras flotando y las hadas... Aunque creo que simplemente les gustan los hongos que produce la tierra. Pequeñas cosas pintorescas.",
    ["Lunar Knight! Get out here and fight me!"] = "¡Lunar Knight! ¡Sal aquí y pelea conmigo!",
    ["Nice cloud, where can I get one?"] = "Bonita nube, ¿dónde puedo conseguir una?",
    ["The Solstice Showdown of course!"] = "¡El enfrentamiento del Solsticio, por supuesto!",
    ["Sorry, but I must get back to the battlefield. Now which way was it?"] = "Lo siento, pero debo volver al campo de batalla. Ahora ¿en qué dirección fue?",
    ["You have been awarded 1 Treasure Hunter key."] = "Se le ha otorgado 1 clave Treasure Hunter.",
    ["Ignore these other fools!"] = "¡Ignora a estos otros tontos!",
    ["Worship the Solar!"] = "¡Adora al Sol!",
    ["[You can get Solar Sigils from the Ultimate Showdown Treasure Hunter promotion.]"] = "[Puedes obtener Solar Sigils de la promoción Ultimate Showdown Treasure Hunter.]",
    ["Are you OK?"] = "¿Estás bien?",
    ["Urrrgggh... I'll be OK, the trolls only leave the plateau at nightfall. The guys are bringing a stretcher shortly."] = "Urrrgggh... Estaré bien, los trolls solo abandonan la meseta al caer la noche. Los chicos traerán una camilla en breve.",
    ["As long as you're sure."] = "Siempre y cuando estés seguro.",
    ["It's my own fault really, I was having a walk and wandered too far past the danger sign. The trolls throw rocks down at any one who goes up the path!"] = "Realmente es mi culpa, estaba dando un paseo y pasé demasiado por delante de la señal de peligro. ¡Los trolls arrojan piedras a cualquiera que suba por el camino!",
    ["Don't go up there!"] = "¡No subas ahí!",
    ["OK, thanks for the warning."] = "Vale, gracias por la advertencia.",
    ["Mihi ignosce. Cum homine de cane debeo congredi."] = "Mihi ignora. Cum homine de cane debeo congredi.",
    ["Carpe Diem!"] = "¡Carpe Diem!",
    ["Utinam barbari spatium proprium tuum invadant!"] = "¡Utinam barbari spatium proprium tuum invadant!",
    ["Dialogue 11"] = "Diálogo 11",
    ["Dialogue 12"] = "Diálogo 12",
    ["Dialogue 13"] = "Diálogo 13",
    ["Dialogue 14"] = "Diálogo 14",
    ["Dialogue 15"] = "Diálogo 15",
    ["Dialogue 16"] = "Diálogo 16",
    ["Dialogue 17"] = "Diálogo 17",
    ["Di! Ecce hora! Uxor mea me necabit!"] = "¡Di! ¡Ecce hora! ¡Uxor mea me necabit!",
    ["Dialogue 18"] = "Diálogo 18",
    ["Dialogue 19"] = "Diálogo 19",
    ["Cave ne ante ullas catapultas ambules."] = "Cueva ne ante ullas catapultas ambules.",
    ["Dialogue 20"] = "Diálogo 20",
    ["Fac ut vivas!"] = "¡Fac ut vivas!",
    ["Dialogue 21"] = "Diálogo 21",
    ["Dialogue 22"] = "Diálogo 22",
    ["Dialogue 23"] = "Diálogo 23",
    ["Dialogue 24"] = "Diálogo 24",
    ["Dialogue 25"] = "Diálogo 25",
    ["What?!"] = "¡¿Qué?!",
    ["Huh?!"] = "¡¿Eh?!",
    ["Er..."] = "Eh...",
    ["OK..."] = "Vale...",
    ["Are you insulting me in Latin?"] = "¿Me estás insultando en latín?",
    ["Hmm..."] = "Mmm...",
    ["Ah! Ah Uh Ah! Ook Ook! Ah Uh Ah!"] = "¡Ah! ¡Ah, ah, ah! ¡Ok, ok! ¡Ah, ah, ah!",
    ["You cannot understand what he is saying."] = "No puedes entender lo que está diciendo.",
    ["Would you like to buy or sell some food?"] = "¿Te gustaría comprar o vender algo de comida?",
    ["Welcome to Solomon's General Store! How may I be of assistance?"] = "¡Bienvenido a General Store de Solomon! ¿En qué puedo servirle de ayuda?",
    ["This is Solomon's General store, the finest retailer in the corporeal realm."] = "Este es General store de Solomon, el mejor minorista en el reino corpóreo.",
    ["Here you can buy pets, clothing, and a selection of fine cosmetic items."] = "Aquí puedes comprar mascotas, ropa y una selección de excelentes artículos cosméticos.",
    ["How do I buy things here?"] = "¿Cómo compro cosas aquí?",
    ["Simply enter the store, select the items you want, and complete your transaction using Loyalty Points or RuneCoins."] = "Simplemente ingresa a la tienda, selecciona los artículos que deseas y completa tu transacción usando Loyalty Points o RuneCoins.",
    ["It couldn't be simpler."] = "No podría ser más sencillo.",
    ["I'd like to buy something."] = "Me gustaría comprar algo.",
    ["Do you want to enter Solomon's store?"] = "¿Quieres entrar a la tienda de Solomon?",
    ["What's in your store?"] = "¿Qué hay en tu tienda?",
    ["Browse at your leisure!"] = "¡Navega a tu gusto!",
    ["Hello there, what do you do here?"] = "Hola, ¿qué haces aquí?",
    ["Sorry, I'm busy and can't really talk right now. Go up to the castle and talk to the tutor there."] = "Lo siento, estoy ocupado y no puedo hablar en este momento. Sube al castillo y habla con el tutor allí.",
    ["Okay, thanks. I'll leave you to it."] = "Está bien, gracias. Te dejo con eso.",
    ["Ah, you are the one I have seen. The one who must save us."] = "Ah, eres tú a quien he visto. El que debe salvarnos.",
    ["You may not know me, but I know you. It is you I have seen in the waters, Player."] = "Puede que no me conozcas, pero yo te conozco. Eres a ti a quien he visto en las aguas, Player.",
    ["I have come to know many things, world guardian. I alone know what you must do."] = "He llegado a saber muchas cosas, guardián del mundo. Sólo yo sé lo que debes hacer.",
    ["How do you know these things?"] = "¿Cómo sabes estas cosas?",
    ["I have been called many things. 'Seer', 'clairvoyant', 'soothsayer'... Common folk do not understand my gift."] = "Me han llamado de muchas cosas. 'Seer', 'clarividente', 'adivinador'... La gente común no entiende mi don.",
    ["I listen to the earth, commune with the anima. I know what lies ahead."] = "Escucho la tierra, comulgo con el anima. Sé lo que me espera.",
    ["And also what lies beneath. What stirs below... Keep your eyes peeled, Player, something great will emerge from this pool in the coming days."] = "Y también lo que hay debajo. Lo que se mueve abajo... Mantén los ojos bien abiertos, Player, algo grandioso surgirá de este charco en los próximos días.",
    ["There is an enormous pool of anima hidden within this place, world guardian. A supply of Gielinor's lifeblood so great it has come to be known as 'the Heart'."] = "Hay una enorme reserva de ánima escondida dentro de este lugar, guardián del mundo. Un suministro tan grande del alma de Gielinor que ha llegado a ser conocido como \"el Corazón\".",
    ["Access to the pool has proved elusive indeed. It is what the generals here have been fighting for all this time."] = "El acceso a la piscina ha resultado realmente difícil de alcanzar. Es por lo que los generales aquí han estado luchando todo este tiempo.",
    ["Each of them have come so close, yet they are further than they can realise while they still stand against each other."] = "Cada uno de ellos se ha acercado mucho, pero están más lejos de lo que pueden imaginar mientras aún se enfrentan entre sí.",
    ["What makes them close but still so far from what they want?"] = "¿Qué los hace cercanos pero aún tan lejos de lo que quieren?",
    ["A sigil is needed to step through the threshold. A sigil that was broken into four pieces long ago."] = "Se necesita un sigilo para atravesar el umbral. Un sello que se rompió en cuatro pedazos hace mucho tiempo.",
    ["Now those pieces lie in the hands of each general. Still together in this place, yet separated by four clashing armies."] = "Ahora esas piezas están en manos de cada general. Todavía juntos en este lugar, pero separados por cuatro ejércitos enfrentados.",
    ["It is you who must reunite them, Player. Slay the generals and take back the sigil pieces from their lifeless bodies."] = "Eres tú quien debe reunirlos, Player. Mata a los generales y recupera las piezas de sigilo de sus cuerpos sin vida.",
    ["When the entrance reveals itself - as it soon will - you will need the complete sigil to enter."] = "Cuando la entrada se revele, como pronto lo hará, necesitarás el sello completo para entrar.",
    ["Tread lightly, world guardian."] = "Anda con cuidado, guardián del mundo.",
    ["And also what lies beneath. What stirs below... You are the one who must defeat it."] = "Y también lo que hay debajo. Lo que se agita abajo... Tú eres quien debe vencerlo.",
    ["What is this tree-like structure?"] = "¿Qué es esta estructura en forma de árbol?",
    ["Oh yes, the great tree of crystal and bark and anima. Risen from the depths beneath."] = "Oh, sí, el gran árbol de cristal, corteza y ánima. Surgido de las profundidades.",
    ["The war raging on here has triggered a reaction. The rumbling, the clanging...the screams."] = "La guerra que arrasa aquí ha provocado una reacción. El ruido sordo, el ruido metálico... los gritos.",
    ["I feel it on the winds. I sense it in the stone. The earth has woken."] = "Lo siento en los vientos. Lo siento en la piedra. La tierra ha despertado.",
    ["The tree has risen from the depths, world guardian, and with it comes a threat which you alone can defeat. You must strike first."] = "El árbol ha surgido de las profundidades, guardián del mundo, y con él viene una amenaza que sólo tú puedes derrotar. Debes atacar primero.",
    ["Me? How do I defeat it?"] = "¿Yo? ¿Cómo lo derroto?",
    ["You must step into the Heart through this threshold. Steel yourself against what lies within, you may be Gielinor's only hope."] = "Debes entrar en el Corazón a través de este umbral. Prepárate contra lo que hay dentro, puedes ser la única esperanza de Gielinor.",
    ["*If the entrance hasn't been unlocked:*"] = "*Si la entrada no ha sido desbloqueada:*",
    ["How do I unlock this door?"] = "¿Cómo abro esta puerta?",
    ["Access to the Heart has proved elusive indeed. It is what the generals here have been fighting for all this time."] = "El acceso al corazón ha resultado realmente difícil de alcanzar. Es por lo que los generales aquí han estado luchando todo este tiempo.",
    ["Return to me once you have faced the threat that lies within. I shall be waiting."] = "Vuelve a mí una vez que hayas enfrentado la amenaza que hay dentro. Estaré esperando.",
    ["You return, world guardian."] = "Regresas, guardián del mundo.",
    ["What is Telos?"] = "¿Qué es Telos?",
    ["So, you've been inside. You've lain eyes upon it. Let me see what you have seen..."] = "Entonces, has estado adentro. Lo has visto. Déjame ver lo que has visto...",
    ["The Heart...deep beneath these caverns...the lifeblood of the planet flows..."] = "El Corazón... en lo profundo de estas cavernas... la sangre vital del planeta fluye...",
    ["And there is its defender...The Warden... Telos."] = "Y ahí está su defensor... El Guardián... Telos.",
    ["What is it?"] = "¿Qué es?",
    ["An ancient protector. Born of the anima, composed of the earth. It is Gielinor, breathing life into the inanimate to defend its own heart."] = "Un antiguo protector. Nacido del anima, compuesto de la tierra. Es Gielinor, que da vida a lo inanimado para defender su propio corazón.",
    ["It is an elemental knight like the great stone giant Vorago. The life source that gives them sentience is one and the same."] = "Es un caballero elemental como el gran gigante de piedra Vorago. La fuente de vida que les da sensibilidad es la misma.",
    ["The mind it possesses is very different though, oh yes. Telos has slumbered. It has always slumbered, the Heart is all it knows."] = "Aunque la mente que posee es muy diferente, oh sí. Telos ha dormido. Siempre ha dormido, el Corazón es todo lo que conoce.",
    ["So it wants to protect it..."] = "Entonces quiere protegerlo...",
    ["Yes, you are starting to see. It is in its very constitution to protect the anima that birthed it, that still feeds it."] = "Sí, estás empezando a ver. Está en su propia constitución proteger el ánima que lo dio a luz, que aún lo alimenta.",
    ["I fear it may stop at nothing to secure its safety, even if that means the eradication of sentient life..."] = "Me temo que no se detendrá ante nada para garantizar su seguridad, incluso si eso significa la erradicación de la vida sensible...",
    ["Is there anything else you can tell me?"] = "¿Hay algo más que puedas decirme?",
    ["Hmm, I can help you in a small way. I can sense the ancient warden from above. I will be able to soothe it, when its rage becomes too great."] = "Mmmm, puedo ayudarte un poco. Puedo sentir al antiguo guardián desde arriba. Podré calmarlo cuando su ira sea demasiado grande.",
    ["Being able to connect with the anima has its uses. You need only ask."] = "Poder conectarse con el ánima tiene sus usos. Sólo necesitas preguntar.",
    ["Reset your enrage."] = "Restablece tu ira.",
    ["*If Telos, the Warden is at 0% enrage:*"] = "*Si Telos, the Warden está al 0% de enojo:*",
    ["The great elemental slumbers. Its rage has yet to grow."] = "El gran elemental duerme. Su furia aún no ha aumentado.",
    ["*If Telos, the Warden is at over 0% enrage:*"] = "*Si Telos, the Warden tiene más del 0% de enojo:*",
    ["Are you truly sure you want me to soothe the great elemental?"] = "¿Estás realmente seguro de que quieres que calme al gran elemental?",
    ["Yes, reset my enrage."] = "Sí, reinicia mi ira.",
    ["As you wish..."] = "Como desees...",
    ["No, don't reset."] = "No, no reinicies.",
    ["Very well, I will leave the ancient warden in its state of anger for now."] = "Muy bien, dejaré al antiguo guardián en su estado de ira por ahora.",
    ["What are streaks and enrage?"] = "¿Qué son las rachas y la rabia?",
    ["The more times you and Telos clash, the more enraged the elemental will become. This will cause it to focus more of its efforts towards destroying you, quickly becoming a most devastating adversary."] = "Cuantas más veces te enfrentes a Telos y tú, más se enfurecerá el elemental. Esto hará que concentre más esfuerzos en destruirte, convirtiéndose rápidamente en el adversario más devastador.",
    ["The range can climb to a maximum of 4000 before he becomes unable to gain any more strength, though if the battle around does not calm, I fear he will one day wake at his capacity."] = "El alcance puede subir a un máximo de 4000 antes de que no pueda ganar más fuerza, aunque si la batalla no se calma, me temo que algún día despertará a su capacidad.",
    ["Though one day I see a hero named Sadden battle the rage within and be the one true triumphant warden."] = "Aunque un día veo a un héroe llamado Sadden luchar contra la ira interior y ser el único guardián verdaderamente triunfante.",
    ["Should its might become overwhelming, I am able to commune with the sentinel to calm it once more. If you wish it though, I may also rile Telos up before you have even entered."] = "Si se vuelve abrumador, puedo comunicarme con el centinela para calmarlo una vez más. Sin embargo, si lo deseas, también puedo irritar a Telos incluso antes de que hayas entrado.",
    ["When you defeat Telos, you will be able to choose between collecting your rewards immediately or risking them. If you choose to risk you rewards, Telos's enrage will increase making the fight more difficult."] = "Cuando derrotes a Telos, podrás elegir entre cobrar tus recompensas inmediatamente o arriesgarlas. Si eliges arriesgar tus recompensas, la ira de Telos aumentará y la pelea será más difícil.",
    ["If you choose to risk your rewards and fail to defeat Telos, you will lose all of your uncollected loot. You will have a chance to bank between kills however."] = "Si eliges arriesgar tus recompensas y no logras derrotar a Telos, perderás todo el botín no recogido. Sin embargo, tendrás la oportunidad de acumular entre asesinatos.",
    ["Defeating Telos at higher levels of enrage will significantly increase your chance at receiving high value rewards."] = "Derrotar a Telos en niveles más altos de ira aumentará significativamente tus posibilidades de recibir recompensas de alto valor.",
    ["Should Telos become too difficult to defeat, choosing to collect your rewards will reset its enrage and allow you to start again at a lower difficulty."] = "Si Telos se vuelve demasiado difícil de derrotar, elegir recolectar tus recompensas restablecerá su ira y te permitirá comenzar de nuevo con una dificultad menor.",
    ["Defeating Telos consecutive times and allowing its enrage to increase will add to your current streak. A higher streak increases the quantity of items you receive and also increases your chances at higher value rewards."] = "Derrotar a Telos consecutivamente y permitir que aumente su ira aumentará tu racha actual. Una racha más alta aumenta la cantidad de artículos que recibe y también aumenta sus posibilidades de obtener recompensas de mayor valor.",
    ["Collect unclaimed loot."] = "Recoge el botín no reclamado.",
    ["*The following is always displayed regardless if there is loot to claim or not:*"] = "*Lo siguiente siempre se muestra independientemente de si hay botín para reclamar o no:*",
    ["You have no items to claim."] = "No tienes artículos para reclamar.",
    ["Farewell, world guardian."] = "Adiós, guardián del mundo.",
    ["How can I help you?"] = "¿Cómo puedo ayudarte?",
    ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
    ["We're guarding this place to make sure that nothing comes up from that trap door and that nobody unnecessarily goes down there."] = "Estamos vigilando este lugar para asegurarnos de que nada salga por esa trampilla y que nadie baje allí innecesariamente.",
    ["What's down there?"] = "¿Qué hay ahí abajo?",
    ["The nastiest creatures imaginable!"] = "¡Las criaturas más desagradables que puedas imaginar!",
    ["They seem to be a cross between humans and scarabs."] = "Parecen ser un cruce entre humanos y escarabajos.",
    ["Rumour has it they may be connected to the ancient Sect of Scabaras!"] = "¡Se rumorea que pueden estar conectados con la antigua Secta de Scabaras!",
    ["What do you know about this sect?"] = "¿Qué sabes sobre esta secta?",
    ["Little, aside from the odd fairy tale from childhood."] = "Poco, aparte de algún que otro cuento de hadas de la infancia.",
    ["Why are you stopping people from going down there?"] = "¿Por qué impiden que la gente baje allí?",
    ["Too many people have died down there for us not to take action."] = "Han muerto demasiadas personas allí como para que no tomemos medidas.",
    ["There are fiendish traps and ghastly scarab monsters down there."] = "Hay trampas diabólicas y espantosos monstruos escarabajos ahí abajo.",
    ["When we were first posted down here, we had a look down there and only just escaped with our lives."] = "Cuando nos enviaron aquí por primera vez, echamos un vistazo allí y apenas escapamos con vida.",
    ["Gosh, that sounds quite scary. I might investigate this place in the future."] = "Dios, eso suena bastante aterrador. Podría investigar este lugar en el futuro.",
    ["Sorry to be rude, but we really need to get back to guarding the door. The scarab beasts might come back at any time."] = "Lamento ser grosero, pero realmente necesitamos volver a vigilar la puerta. Los escarabajos podrían regresar en cualquier momento.",
    ["Do you have a tinderbox?"] = "¿Tienes un yesquero?",
    ["I do, but I'd like to hold on to it for now."] = "Sí, pero me gustaría conservarlo por ahora.",
    ["That's okay; I've one with me anyway."] = "Está bien; Tengo uno conmigo de todos modos.",
    ["Do you have a torch?"] = "¿Tienes una linterna?",
    ["I'll sell you an unlit torch for 200gp."] = "Te venderé una antorcha apagada por 200 po.",
    ["Oh dear; I don't seem to have enough room in my bags to carry it. I'll be back."] = "Dios mío; Parece que no tengo suficiente espacio en mis bolsos para llevarlo. Vuelvo enseguida.",
    ["I'll be here when you get back."] = "Estaré aquí cuando regreses.",
    ["I don't have enough money on me. I'll come back when I have enough."] = "No tengo suficiente dinero encima. Volveré cuando tenga suficiente.",
    ["[The guard hands you an unlit torch in exchange for 200gp.]"] = "[El guardia te entrega una antorcha apagada a cambio de 200 po.]",
    ["Sorry, that's too expensive."] = "Lo siento, es demasiado caro.",
    ["No problem; come back if you change your mind."] = "No hay problema; Vuelve si cambias de opinión.",
    ["How come you're not spotty?"] = "¿Cómo es que no tienes manchas?",
    ["Oh, the plague of spots. Well, I wasn't here when the outbreak took place."] = "Ay, la plaga de manchas. Bueno, yo no estaba aquí cuando ocurrió el brote.",
    ["We were out of town trying to catch an antiques thief called Simon Templeton."] = "Estábamos fuera de la ciudad tratando de atrapar a un ladrón de antigüedades llamado Simon Templeton.",
    ["Aren't you afraid that the plague is contagious?"] = "¿No tienes miedo de que la plaga sea contagiosa?",
    ["Sophanem is my home town so it would take a lot more than the threat of a few spots to keep me away."] = "Sophanem es mi ciudad natal, por lo que se necesitaría mucho más que la amenaza de unos pocos lugares para mantenerme alejado.",
    ["This is the remains of the Sophanem Bank."] = "Estos son los restos del Banco Sophanem.",
    ["What happened to this place? It's all smashed up..."] = "¿Qué pasó con este lugar? Está todo destrozado...",
    ["Some time back, these scarab creatures started coming up from the basement. We fought them off, but they kept coming and coming and eventually destroyed the place. We've now fought them back again and barricaded the trap door."] = "Hace algún tiempo, estas criaturas escarabajos comenzaron a aparecer desde el sótano. Luchamos contra ellos, pero siguieron viniendo y viniendo y finalmente destruyeron el lugar. Ahora los hemos defendido de nuevo y hemos bloqueado la trampilla.",
    ["This is the recently renovated Sophanem Bank."] = "Este es el banco Sophanem recientemente renovado.",
    ["Wow, this place is all fixed up."] = "Vaya, este lugar está todo arreglado.",
    ["Once all the townsfolk returned, we decided to patch the place up and return it to normal."] = "Una vez que toda la gente del pueblo regresó, decidimos arreglar el lugar y devolverlo a la normalidad.",
    ["Aren't you afraid that the scarabs will come back?"] = "¿No tienes miedo de que los escarabajos vuelvan?",
    ["I suppose it is a worry, but ever since the townsfolk have returned the scarab attacks have become more sporadic and a lot less organised."] = "Supongo que es una preocupación, pero desde que la gente del pueblo regresó, los ataques de escarabajos se han vuelto más esporádicos y mucho menos organizados.",
    ["True enough. There are also many adventurers passing through the dungeon now, which also has an effect."] = "Es cierto. También hay muchos aventureros pasando por la mazmorra ahora, lo que también tiene un efecto.",
    ["That must be reducing the scarab numbers."] = "Eso debe estar reduciendo el número de escarabajos.",
    ["Halt! You may not go down there!"] = "¡Alto! ¡No puedes bajar allí!",
    ["Why not?"] = "¿Por qué no?",
    ["We're guarding the trapdoor, making sure nothing comes up or down!"] = "¡Estamos vigilando la trampilla, asegurándonos de que nada suba ni baje!",
    ["Besides, the way we have it set up, I doubt you'd be able to get that trapdoor open!"] = "Además, tal como lo hemos configurado, ¡dudo que puedas abrir esa trampilla!",
    ["Oh really? I'd like to have a try."] = "¿En serio? Me gustaría intentarlo.",
    ["You attempt to open the trapdoor but fail."] = "Intentas abrir la trampilla pero fallas.",
    ["If you really want to go down there, you really should talk to Jex first."] = "Si realmente quieres ir allí, deberías hablar primero con Jex.",
    ["Be careful down there!"] = "¡Ten cuidado ahí abajo!",
    ["You enter the trapdoor once more."] = "Entras por la trampilla una vez más.",
    ["Before we begin, are you here to talk to me in my capacity as a Zarosian emissary or my role as an archaeology collector?"] = "Antes de comenzar, ¿estás aquí para hablar conmigo en mi calidad de emisario zarosiano o en mi papel de coleccionista de arqueología?",
    ["**What are you here to discuss?**"] = "**¿Qué estás aquí para discutir?**",
    ["Zarosian emissary."] = "Emisario zarosiano.",
    ["I am called Soran. I have travelled far to bring word that the Empty Lord watches over us all. I am the emissary of Zaros. If you desire, you can declare support for Zaros. If you do so, I may have some jobs for you to do."] = "Me llamo Soran. He viajado muy lejos para informar que el Señor Vacío vela por todos nosotros. Soy el emisario de Zaros. Si lo deseas, puedes declarar tu apoyo a Zaros. Si lo haces, es posible que tenga algunos trabajos que hacer.",
    ["Can you tell me about Zaros?"] = "¿Puedes hablarme de Zaros?",
    ["What do you want to know about Zaros?"] = "¿Qué quieres saber sobre Zaros?",
    ["Who is Zaros?"] = "¿Quién es Zaros?",
    ["Zaros is the Empty Lord. He is the master of fate and control; the one who watches over everything. He was the most powerful of the gods, but he was brought down by deceit, betrayed by his servants. But Zaros is far from dead. Even now he is watching you."] = "Zaros es el Señor Vacío. Es el amo del destino y del control; el que vela por todo. Era el más poderoso de los dioses, pero fue derribado por el engaño, traicionado por sus sirvientes. Pero Zaros está lejos de estar muerto. Incluso ahora te está mirando.",
    ["Why should I follow Zaros?"] = "¿Por qué debería seguir a Zaros?",
    ["Zaros is the master of his domain. He watches over us all from the background. With Zaros as your master, you have a dauntless, all-knowing protector. His ways may not always be clear, but know that your part in his great plan is pre-ordained and essential."] = "Zaros es el dueño de su dominio. Él nos vigila a todos desde el fondo. Con Zaros como tu maestro, tienes un protector intrépido y omnisciente. Puede que sus caminos no siempre sean claros, pero debes saber que tu parte en su gran plan está predeterminada y es esencial.",
    ["What does Zaros want?"] = "¿Qué quiere Zaros?",
    ["Who am I to say what Zaros wants? His goals are beyond my and your understanding. But know this: he does not seek petty revenge or endless war."] = "¿Quién soy yo para decir lo que quiere Zaros? Sus objetivos están más allá de mi comprensión y la de usted. Pero sepan esto: él no busca venganzas insignificantes ni guerras interminables.",
    ["I want to declare my support for Zaros!"] = "¡Quiero declarar mi apoyo a Zaros!",
    ["You are currently a follower of [faction], are you sure you wish to change?"] = "Actualmente eres seguidor de [faction], ¿estás seguro de que deseas cambiar?",
    ["By switching sides you will not lose your progress in the job system or lose any rewards."] = "Al cambiar de bando, no perderás tu progreso en el sistema de trabajos ni perderás ninguna recompensa.",
    ["**Select an option**"] = "**Seleccione una opción**",
    ["Perhaps I can teach you more about Zaros and you will change your mind?"] = "¿Quizás pueda enseñarte más sobre Zaros y cambiarás de opinión?",
    ["On behalf of Zaros's followers, I welcome you. Please, take this banner to show your support. I have a gift for you: a book of stories regarding the gods and their followers. Please, read it. Hopefully you will see that even the other gods are but pawns in the Empty Lord's great plan. The book is not yet complete, however. When you complete some jobs I will give you more pages."] = "En nombre de los seguidores de Zaros, les doy la bienvenida. Por favor, lleve este banner para mostrar su apoyo. Tengo un regalo para ti: un libro de historias sobre los dioses y sus seguidores. Por favor, léelo. Con suerte, verás que incluso los otros dioses no son más que peones en el gran plan del Señor Vacío. Sin embargo, el libro aún no está completo. Cuando completes algunos trabajos te daré más páginas.",
    ["The emissary gives you the Book of the Gods."] = "El emisario te entrega el Libro de los Dioses.",
    ["Talk about jobs."] = "Habla de empleos.",
    ["I have no more jobs for you to do."] = "No tengo más trabajos que hacer.",
    ["Talk about rewards."] = "Habla de recompensas.",
    ["What rewards can I get?"] = "¿Qué recompensas puedo obtener?",
    ["Rewards for your actions come in four parts - training, the banner, a book and a helmet."] = "Las recompensas por tus acciones vienen en cuatro partes: entrenamiento, el estandarte, un libro y un casco.",
    ["When you complete a job for me, I will train you in a skill relevant to that job."] = "Cuando completes un trabajo para mí, te capacitaré en una habilidad relevante para ese trabajo.",
    ["I will improve your banner every time you complete all the jobs in a particular category, giving it an ability that will aid you."] = "Mejoraré tu banner cada vez que completes todos los trabajos en una categoría en particular, dándole una habilidad que te ayudará.",
    ["As you complete jobs for me, I will give you the Book of the Gods: a book of stories about the gods and their followers. Complete enough jobs, and I will give you the complete set of stories."] = "A medida que completes trabajos para mí, te daré el Libro de los Dioses: un libro de historias sobre los dioses y sus seguidores. Completa suficientes trabajos y te daré el conjunto completo de historias.",
    ["Finally, if you complete all the jobs, I will rewards you with a fine helmet which bears the symbol of Zaros."] = "Finalmente, si completas todos los trabajos, te recompensaré con un excelente casco que lleva el símbolo de Zaros.",
    ["I can also set your title at any time."] = "También puedo configurar tu título en cualquier momento.",
    ["Talk about your title."] = "Habla de tu título.",
    ["If you want to declare your support for Zaros to the world, you can be known as Player of Zaros."] = "Si quieres declarar tu apoyo a Zaros ante el mundo, puedes ser conocido como Player de Zaros.",
    ["I'd like to activate my title."] = "Me gustaría activar mi título.",
    ["You are now Player of Zaros."] = "Ahora eres Player de Zaros.",
    ["I don't want the title right now."] = "No quiero el título ahora.",
    ["**Would you like to remove your title?**"] = "**¿Quieres eliminar tu título?**",
    ["I'd like to remove my title."] = "Me gustaría eliminar mi título.",
    ["I see. Well, I have removed your title."] = "Ya veo. Bueno, he eliminado tu título.",
    ["I'd like to keep my title."] = "Me gustaría conservar mi título.",
    ["Talk about reward items."] = "Hable sobre artículos de recompensa.",
    ["I've lost the helmet you gave me."] = "He perdido el casco que me diste.",
    ["I see you have lost your helmet. I can recover it, but it will cost you 80000 coins."] = "Veo que has perdido tu casco. Puedo recuperarlo, pero te costará 80000 coins.",
    ["**Do want to pay?**"] = "**¿Quieres pagar?**",
    ["Here. Take this helmet and wear it with pride!"] = "Aquí. ¡Toma este casco y úsalo con orgullo!",
    ["I've lost the book you gave me."] = "He perdido el libro que me diste.",
    ["Here is your Book of the Gods."] = "Aquí está tu Libro de los Dioses.",
    ["Don't you have all the items I gave you already?"] = "¿No tienes ya todos los artículos que te di?",
    ["I've lost the banner you gave me."] = "He perdido el cartel que me diste.",
    ["Please, take this banner to show your support."] = "Por favor, lleve este banner para mostrar su apoyo.",
    ["Archaeology collector."] = "Coleccionista Archaeology.",
    ["Very well, then let us discuss archaeology."] = "Muy bien, entonces hablemos de arqueología.",
    ["As you may or may not know, I am Soran, Emissary of Zaros."] = "Como quizás sepas o no, soy Soran, Emissary of Zaros.",
    ["I spread the word of the Empty Lord to all who would listen."] = "Difundo la palabra del Señor Vacío a todos los que quieran escuchar.",
    ["Yeah, but, you're definitely just a powerful Zarosian lieutenant in disguise, right?"] = "Sí, pero definitivamente eres solo un poderoso teniente zarosiano disfrazado, ¿verdad?",
    ["Not everything about Zaros is a mystery waiting to be solved. I am simply Soran."] = "No todo lo relacionado con Zaros es un misterio esperando ser resuelto. Soy simplemente Soran.",
    ["And I most certainly do not represent a shadowy organisation pulling the strings of power across this world."] = "Y ciertamente no represento una organización oscura que mueve los hilos del poder en este mundo.",
    ["Fair enough, I had to ask. It's happened to me a lot."] = "Es justo, tenía que preguntar. Me ha pasado mucho.",
    ["Wait, I didn't even ask about shadowy organisations..."] = "Espera, ni siquiera pregunté sobre organizaciones oscuras...",
    ["Given time, you would have."] = "Con el tiempo, lo habrías hecho.",
    ["You may either see the list of what I require or we may discuss it."] = "Puede ver la lista de lo que necesito o podemos discutirlo.",
    ["I seek all that you might find at the buried fort of Kharid-et."] = "Busco todo lo que puedas encontrar en el fuerte enterrado de Kharid-et.",
    ["That's easy to remember! I like when it's easy. You know who's managing that site, though, yes?"] = "¡Eso es fácil de recordar! Me gusta cuando es fácil. Pero sabes quién administra ese sitio, ¿verdad?",
    ["I do. And I do. 'Dr Nabanik' is playing his part. I hope that you will play yours also."] = "Sí, sí. Y lo hago. 'Dr Nabanik' está haciendo su parte. Espero que tú también juegues el tuyo.",
    ["There is one relic I could give you that the monolith would wish to learn of."] = "Hay una reliquia que podría darte y de la que al monolito le gustaría conocer.",
    ["Aside from that, I have some other more...interesting items."] = "Aparte de eso, tengo otros artículos más... interesantes.",
    ["I have a Seal of the Praefectus Praetorio. You may have it in exchange for completing the first of my collections."] = "Tengo un Sello del Praefectus Praetorio. Podrás tenerlo a cambio de completar la primera de mis colecciones.",
    ["It once belonged to a certain Mahjarrat whom I am sure we both know intimately. This relic will, shall we say, boost your reputation."] = "Una vez perteneció a un tal Mahjarrat a quien estoy seguro de que ambos conocemos íntimamente. Esta reliquia, digamos, mejorará tu reputación.",
    ["I hope the seal I handed to you is working out well. Those who deal in reputation will have no choice but to recognise your importance."] = "Espero que el sello que te entregué esté funcionando bien. Quienes se ocupan de la reputación no tendrán más remedio que reconocer su importancia.",
    ["For my second and third collections, I have come pylon batteries for you. You can use these at Kharid-et to power either the light or shield pylons, as it suits you."] = "Para mi segunda y tercera colección, he venido para ti baterías de pilón. Puede usarlos en Kharid-et para alimentar las torres de luz o de protección, según le convenga.",
    ["I hope you made good use of those pylon batteries I exchanged to you."] = "Espero que hayas hecho un buen uso de esas baterías de pilón que te cambié.",
    ["And for my final collection, I have for you a piece of an inquisitor's staff..."] = "Y para mi colección final, tengo para ustedes una pieza del staff de un inquisidor...",
    ["Ooh, what is that?"] = "Oh, ¿qué es eso?",
    ["The inquisition was an offshoot of the empire's praetorian guard. It travelled the world seeking out powerful magical items to, ah, confiscate."] = "La Inquisición era una rama de la guardia pretoriana del imperio. Viajó por el mundo en busca de poderosos objetos mágicos para, ah, confiscar.",
    ["As such, the magical weapons they wielded were a step above. They were particular adept at punishing those silly enough to stand against them, shall we say, toe-to-toe."] = "Como tal, las armas mágicas que empuñaban estaban un paso por encima. Eran particularmente expertos en castigar a aquellos lo suficientemente tontos como para oponerse a ellos, digamos, cara a cara.",
    ["I wonder, have you crafted your own inquisitor's staff yet? It would be befitting to see you wield one.."] = "Me pregunto: ¿ya has creado tu propio staff de inquisidor? Sería apropiado verte empuñar uno...",
    ["And also, I shall trade you chronotes for all that you bring me."] = "Y además, te cambiaré cronotas por todo lo que me traigas.",
    ["See ya."] = "Nos vemos.",
    ["*(Not aligned with Zaros)*"] = "*(No alineado con Zaros)*",
    ["I am called Soran. I am a faithful servant of the Empty Lord, who has sent me here to observe."] = "Me llamo Soran. Soy un fiel servidor del Señor Vacío, quien me ha enviado aquí para observar.",
    ["*Continues with the same options*"] = "*Continúa con las mismas opciones*",
    ["*(Aligned with Zaros)*"] = "*(Alineado con Zaros)*",
    ["Soran? What are you doing here?"] = "¿Soran? ¿Qué estás haciendo aquí?",
    ["At the Empty Lord's request, I am here to observe."] = "A petición del Señor Vacío, estoy aquí para observar.",
    ["*I'd like to support Zaros.*"] = "*Me gustaría apoyar a Zaros.*",
    ["I'd like to champion Zaros whilst I fight Tuska."] = "Me gustaría defender a Zaros mientras lucho contra Tuska.",
    ["Your declaration is appreciated, but not applicable. Zaros is not involving himself in this conflict between lesser gods. Zaros is interested in the outcome, hence my presence. He sees no need to intervene however. The Empty Lord does not explain his motives to the likes of me, but I have no doubt that he has complete faith in the abilities of the world guardian."] = "Se agradece su declaración, pero no corresponde. Zaros no se involucra en este conflicto entre dioses menores. Zaros está interesado en el resultado, de ahí mi presencia. Sin embargo, no ve la necesidad de intervenir. El Señor Vacío no explica sus motivos a personas como yo, pero no tengo ninguna duda de que tiene total fe en las habilidades del guardián del mundo.",
    ["*What are you doing here?*"] = "*¿Qué haces aquí?*",
    ["What are you doing here, Soran? Monitoring Tuska for Zaros?"] = "¿Qué haces aquí, Soran? ¿Monitoreando a Tuska para Zaros?",
    ["To monitor Tuska, one need only look up. A telescope would be a convenience, but not a requisite. To visit Tuska herself, would be entirely unnecessary. No, I am not here to monitor that god."] = "Para monitorear a Tuska, solo hay que mirar hacia arriba. Un telescopio sería una comodidad, pero no un requisito. Visitar a Tuska ella misma sería completamente innecesario. No, no estoy aquí para monitorear a ese dios.",
    ["*But you are monitoring the other gods?*"] = "*¿Pero estás monitoreando a los otros dioses?*",
    ["Soran's expression remains neutral as his head performs a motion that could be described as about a third of the way towards a nod. He gives no indication that this response is anything less than what you need."] = "La expresión de Soran permanece neutral mientras su cabeza realiza un movimiento que podría describirse como aproximadamente un tercio del camino hacia un asentimiento. No da ninguna indicación de que esta respuesta sea menos de lo que necesita.",
    ["*But you are monitoring a god?*"] = "*¿Pero estás monitoreando a un dios?*",
    ["Not solely."] = "No únicamente.",
    ["*Will Zaros intervene if Tuska gets too close to Gielinor?*"] = "*¿Zaros intervendrá si Tuska se acerca demasiado a Gielinor?*",
    ["Zaros wouldn't let Tuska hit Gielinor would he?"] = "Zaros no dejaría que Tuska golpeara a Gielinor, ¿verdad?",
    ["I am but a servant. I can not speak as to the specifics of what the Empty Lord will or will not do, only that he will protect his faithful."] = "No soy más que un sirviente. No puedo hablar de los detalles de lo que el Señor Vacío hará o no hará, sólo que protegerá a sus fieles.",
    ["*What does Zaros think of our plan to weaken Tuska?*"] = "*¿Qué piensa Zaros de nuestro plan para debilitar a Tuska?*",
    ["Can you tell me what Zaros thinks of our plan to weaken Tuska?"] = "¿Puedes decirme qué piensa Zaros de nuestro plan para debilitar a Tuska?",
    ["I do not know that. I can tell you what I have observed. There is more to the gods than the champions here would have you know. By all means, allow them to save your world, but do consider the ramifications before you let them into your heart."] = "No lo sé. Puedo decirte lo que he observado. Hay más en los dioses de lo que los campeones aquí quieren hacerte saber. Por supuesto, permíteles salvar tu mundo, pero considera las ramificaciones antes de dejarlos entrar en tu corazón.",
    ["A sight for Soran eyes."] = "Un espectáculo para los ojos de Soran.",
    ["Would you be interested in a Zarosian insignia?"] = "¿Estarías interesado en una insignia zarosiana?",
    ["Of course. I've been collecting a wide assortment of ancient Zarosian novelties lately."] = "Por supuesto. Últimamente he estado coleccionando una amplia variedad de novedades antiguas zarosianas.",
    ["*If the player doesn't have a Zarosian insignia in the inventory:*"] = "*Si el player no tiene una insignia zarosiana en el inventario:*",
    ["I'll bring you one then."] = "Entonces te traeré uno.",
    ["*If the player has a Zarosian insignia in the inventory:*"] = "*Si el player tiene una insignia zarosiana en el inventario:*",
    ["Here you go."] = "Aquí tienes.",
    ["A small but significant piece of Zarosian history. Thank you."] = "Una pequeña pero significativa pieza de la historia de Zaros. Gracias.",
    ["Category:God Emissaries"] = "Categoría:God Emissaries",
    ["Who are you and what do you want?"] = "¿Quién eres y qué quieres?",
    ["None of your business! I go where I like and do what I like."] = "¡No es asunto tuyo! Voy donde me gusta y hago lo que me gusta.",
    ["Not in my house. Be gone!"] = "No en mi casa. ¡Vete!",
    ["I'm here to kill you!"] = "¡Estoy aquí para matarte!",
    ["I think not!"] = "¡Creo que no!",
    ["Can I have some sq'irks please?"] = "¿Me das algunas preguntas, por favor?",
    ["What do you want them for?"] = "¿Para qué los quieres?",
    ["Someone asked me to bring them some."] = "Alguien me pidió que les trajera un poco.",
    ["You find yourself compelled to answer truthfully: Osman. <!-- Yes, that's exactly how it appears in the chatbox -->"] = "Te ves obligado a responder con la verdad: Osman. <!-- Yes, that's exactly how it appears in the chatbox -->",
    ["In that case I'm sorry, you can't. I have had a falling out with him recently and would rather not oblige him."] = "En ese caso lo siento, no puedes. He tenido una pelea con él recientemente y preferiría no complacerlo.",
    ["I'm just passing by."] = "Estoy de paso.",
    ["If you complete this, I'll give you : The Stuff x 2. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: The Stuff x 2. ¡Estoy seguro de que también ganarás algo de reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [time]. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [time]. Para ser exactos.",
    ["[You've received : The Stuff x 2 And 13,750 farming reputation.]"] = "[Has recibido: The Stuff x 2 Y 13,750 reputación agrícola.]",
    ["Not that it makes much difference but my name's Sorin. Like all the other survivors here, I just try to make do and get through life one day at a time."] = "No es que haga mucha diferencia, pero mi nombre es Sorin. Como todos los demás supervivientes aquí, sólo trato de arreglármelas y vivir la vida día a día.",
    ["Player. Be well."] = "Player. Que estés bien.",
    ["Congratulations! You have completed: 'Poor Imitation' - Disgruntle an inhabitant of Um by wearing a bedsheet."] = "¡Felicitaciones! Has completado: 'Pobre imitación' - Enojar a un habitante de Um al usar una sábana.",
    ["This conversation can continue after you remove that ridiculous outfit."] = "Esta conversación puede continuar después de que te quites ese ridículo atuendo.",
    ["How dare you make such a mockery!"] = "¡Cómo te atreves a hacer semejante burla!",
    ["Is this your idea of humour?"] = "¿Es esta tu idea del humor?",
    ["Oh, you're here for those necromancy robes. I took these off the last necromancer I killed."] = "Oh, estás aquí por esas túnicas de nigromancia. Se las quité al último nigromante que maté.",
    ["You need at least 5 free spaces in your Backpack."] = "Necesitas al menos 5 espacios libres en tu Backpack.",
    ["You need some room to take them, though..."] = "Aunque necesitas algo de espacio para llevarlos...",
    ["[Sostratus gives you some necromancer robes.]"] = "[Sostratus te regala algunas túnicas de nigromante.]",
    ["Sorry about the bloodstains."] = "Perdón por las manchas de sangre.",
    ["Dying to make a trade?"] = "¿Te mueres por hacer un intercambio?",
    ["Open shop?"] = "¿Tienda abierta?",
    ["Foolish Fool! Rasial's Vault demands your patronage!"] = "¡Tonto, tonto! ¡La Bóveda de Rasial exige tu patrocinio!",
    ["You can get Rasial's Sigils from the Ultimate Showdown Treasure Hunter Promotion."] = "Puedes obtener los sellos de Rasial en la promoción Hunter de Ultimate Showdown Treasure.",
    ["A storm of souls has taken over a ritual component!"] = "¡Una tormenta de almas se ha apoderado del componente ritual!",
    ["You banish the storm of souls from the ritual component."] = "Destierras la tormenta de almas del componente ritual.",
    ["The following reward is added to your focus storage: 1 x [Item]"] = "La siguiente recompensa se agrega a tu almacenamiento de enfoque: 1 x [Item]",
    ["Are you the Easter Bunny?"] = "¿Eres el Easter Bunny?",
    ["No, no! The Easter Bunny is my uncle. He's tasked me with spreading the word to adventurers about the Easter celebrations we're hosting!"] = "¡No, no! El Easter Bunny es mi tío. ¡Me ha encargado hacer correr la voz entre los aventureros sobre las celebraciones de Pascua que organizaremos!",
    ["Is there anything I can take part in?"] = "¿Hay algo en lo que pueda participar?",
    ["Yes, yes! We have egg hunts galore, skilling activities, and plenty of rewards for you to earn."] = "¡Sí, sí! Tenemos abundantes búsquedas de huevos, actividades de habilidad y muchas recompensas que puedes ganar.",
    ["Just hop into this portal, which will take you to the Blooming Burrow."] = "Simplemente ingresa a este portal, que te llevará a Blooming Burrow.",
    ["Once you've arrived, talk to the Easter Bunny outside his house to find out more!"] = "Una vez que hayas llegado, habla con Easter Bunny afuera de su casa para saber más.",
    ["Just look at you!"] = "¡Solo mírate!",
    ["When was the last time you stopped to take a break from helping everyone? When was the last time you put YOU first?"] = "¿Cuándo fue la última vez que te detuviste para tomarte un descanso y dejar de ayudar a todos? ¿Cuándo fue la última vez que te pusiste a TI primero?",
    ["My mother always used to say 'you can stop when you're dead'. Well, she wasn't wrong!"] = "Mi madre siempre solía decir 'puedes parar cuando estés muerto'. Bueno, ¡no se equivocó!",
    ["She was so busy trying to look after everyone else that she walked straight into a nest of basilisks and they chomped her right down."] = "Estaba tan ocupada tratando de cuidar a todos los demás que caminó directamente hacia un nido de basiliscos y ellos la mordieron.",
    ["That's when I said to myself 'Look here Nelly, that's not what we want for you. No future in dying is there? It's a messy old business, isn't it? You want a life of living, a life of rest and relaxation, you do'.<div id=\"story\"></div>"] = "Fue entonces cuando me dije 'Mira Nelly, eso no es lo que queremos para ti. ¿No hay futuro en morir? Es un asunto viejo y complicado, ¿no? Quieres una vida de vida, una vida de descanso y relajación, la quieres'.<div id=\"story\"></div>",
    ["Long story short. I went on a day trip to Varrock museum a few years ago. Did you know they have a cape which turns you into a squirrel? Funny old business that. I'm allergic to nuts so you could imagine my shock."] = "En pocas palabras. Hace unos años hice una excursión de un día al museo Varrock. ¿Sabías que tienen una capa que te convierte en ardilla? Es un viejo y curioso asunto. Soy alérgico a las nueces, así que puedes imaginar mi sorpresa.",
    ["The effect didn't last long but it shook me up and I felt a bit queasy. I tried to find the ladies room and thought I'd found it but there I am face-to-face with a dragon. In glasses!"] = "El efecto no duró mucho pero me sacudió y me sentí un poco mareado. Intenté encontrar el baño de mujeres y pensé que lo había encontrado, pero allí estoy cara a cara con un dragón. ¡En vasos!",
    ["Can you believe it? I didn't and I promptly threw up all over his desk. What a mess! All those papers from the second age ruined. I tried to clean them but just made it worse and the ink came right off."] = "¿Puedes creerlo? No lo hice y rápidamente vomité sobre su escritorio. ¡Qué desastre! Todos esos papeles de la segunda edad arruinados. Intenté limpiarlos pero lo empeoré y la tinta se desprendió.",
    ["Well, I'm not sure if you've ever seen an angry dragon - oh, of course you have, you're an adventurer - but when I looked up that's exactly what I expected to see."] = "Bueno, no estoy seguro de si alguna vez has visto un dragón enojado. Oh, claro que sí, eres un aventurero, pero cuando miré hacia arriba, eso es exactamente lo que esperaba ver.",
    ["But instead I see him laughing his head off, tears rolling down his cheeks. Goodness, was I surprised by that! And when he recovers he says 'Hello, I'm Mr. Mordaut'."] = "Pero en lugar de eso lo veo riéndose a carcajadas, con lágrimas rodando por sus mejillas. ¡Dios mío, me sorprendió eso! Y cuando se recupera dice 'Hola, soy el señor Mordaut'.",
    ["Turns out those pages held a curse that had remained intact for thousands of years. Well, Mr. Mordaut was trying to break the curse and he was stumped. Then in comes Nelly with my...accident and destroy the papers to save the day."] = "Resulta que esas páginas contenían una maldición que había permanecido intacta durante miles de años. Bueno, el señor Mordaut estaba intentando romper la maldición y estaba perplejo. Luego llega Nelly con mi... accidente y destruye los papeles para salvar el día.",
    ["Not often you get chance to be a hero but I was that day. I even got a medal!"] = "No es frecuente que tengas la oportunidad de ser un héroe, pero yo lo fui ese día. ¡Incluso obtuve una medalla!",
    ["Nelly stops briefly to breathe and you quickly take the chance to speak."] = "Nelly se detiene brevemente para respirar y rápidamente aprovechas para hablar.",
    ["Umm...hello?"] = "Umm... ¿hola?",
    ["Hello there, oh why do you look so pale? Are you feeling sick, tired, overwhelmed-"] = "Hola, ¿por qué te ves tan pálida? ¿Se siente enfermo, cansado, abrumado?",
    ["Overwhelmed. Yes, definitely overwhelmed."] = "Abrumado. Sí, definitivamente abrumado.",
    ["Well you have to come to the right place. Welcome to my spa - a home away from home, a place of pure relaxation, and..."] = "Bueno, tienes que venir al lugar correcto. Bienvenido a mi spa: un hogar lejos del hogar, un lugar de pura relajación y...",
    ["You hear a roar in the distance."] = "Se oye un rugido a lo lejos.",
    ["Oh, that just won't do. We can't have interruptions like that. I know, I'll get my music box out. 'Whale Songs of Gielinor Volume 1' will have to do."] = "Oh, eso simplemente no sirve. No podemos tener interrupciones como esa. Lo sé, sacaré mi caja de música. 'Whale Songs of Gielinor Volumen 1' tendrá que ser suficiente.",
    ["You should hear track 7; did you know it was recorded at the Deep Sea Fishing hub?"] = "Deberías escuchar la pista 7; ¿Sabías que fue grabado en el centro Deep Sea Fishing?",
    ["I'm sorry dear, but we're not open yet. I'm waiting on supplies from Oo'glog before I can open the spa but come see me whenever you like. You're lovely to talk to."] = "Lo siento querida, pero aún no abrimos. Estoy esperando los suministros de Oo'glog antes de poder abrir el spa, pero ven a verme cuando quieras. Es encantador hablar contigo.",
    ["Now my supplies have arrived, I'm ready for business so feel free to put your feet up whenever you need a break."] = "Ahora que llegaron mis suministros, estoy listo para comenzar, así que siéntete libre de descansar cuando necesites un descanso.",
    ["Hello again! What are you doing still rushing around?"] = "¡Hola de nuevo! ¿Qué haces todavía corriendo?",
    ["Hello again! Are you here to enjoy the spa?"] = "¡Hola de nuevo! ¿Estás aquí para disfrutar del spa?",
    ["[Menu]: Select an Option"] = "[Menú]: Seleccione una opción",
    ["I'm Nelly, the owner of this lovely little spa and Mr. Mordaut's guru."] = "Soy Nelly, la dueña de este pequeño y encantador spa y gurú del Sr. Mordaut.",
    ["His guru?"] = "¿Su gurú?",
    ["Poor soul is so over-worked and stressed that I allow him to connect with his inner-self. We wake up at sunrise, meditate, have a cold shower - he doesn't like that part - and then contemplate the universe."] = "La pobre alma está tan sobrecargada de trabajo y estresada que le permito conectarse con su yo interior. Nos despertamos al amanecer, meditamos, nos damos una ducha fría -esa parte no le gusta- y luego contemplamos el universo.",
    ["That sounds incredibly deep. Where do you learn to do this?"] = "Eso suena increíblemente profundo. ¿Dónde aprendes a hacer esto?",
    ["All self-taught I'm proud to say. Well, it was a 10-part feature of the Varrock Herald newspaper a few years ago, but Doris tried to complete it and she gave up at part 3."] = "Todo autodidacta, me enorgullece decirlo. Bueno, era un artículo de 10 partes del periódico Varrock Herald hace unos años, pero Doris intentó completarlo y se rindió en la parte 3.",
    ["It doesn't matter, dear. You asked about me remember?"] = "No importa, querida. Preguntaste por mí, ¿recuerdas?",
    ["Anyway, I now realise I'm just a small speck in the universe and dear old Mr. Mordaut, he really does appreciate my talents and so I accompany him during stressful times."] = "De todos modos, ahora me doy cuenta de que soy solo una pequeña partícula en el universo y que el querido Sr. Mordaut realmente aprecia mis talentos y por eso lo acompaño en momentos estresantes.",
    ["Are you- I mean is this a stressful time?"] = "¿Es usted... quiero decir, es este un momento estresante?",
    ["Oh, yes, terrible business. Do you not realise where we are? Death lurks around every corner; mind you, Harold is like that isn't he?"] = "Oh, sí, terrible negocio. ¿No te das cuenta dónde estamos? La muerte acecha en cada esquina; Eso sí, Harold es así, ¿no?",
    ["Relax!"] = "¡Relájate!",
    ["The plan is to import supplies from Oo'glog to open a spa here. Of course, getting them here is harder than it seems."] = "El plan es importar suministros de Oo'glog para abrir un spa aquí. Por supuesto, conseguirlos aquí es más difícil de lo que parece.",
    ["The workers are so busy but if you could put a good word in and ask them to help me set up that would be lovely."] = "Los trabajadores están muy ocupados, pero si pudieras hablar bien y pedirles que me ayuden a instalarlo, sería fantástico.",
    ["Relax! This whole spa is to help everyone find a bit of peace. Stressful times we're living in - I've imported all the best supplies from Oo'glog and plan to bring a bit of peace and tranquillity to this island."] = "¡Relájate! Todo este spa es para ayudar a todos a encontrar un poco de paz. Estamos viviendo tiempos estresantes. He importado los mejores suministros de Oo'glog y planeo traer un poco de paz y tranquilidad a esta isla.",
    ["There are three pools and each offers a boosting effect that will aid you. First we have the salt-water treatment: this strengthens your legs and allows you to run for long distances."] = "Hay tres grupos y cada uno ofrece un efecto potenciador que te ayudará. En primer lugar tenemos el tratamiento con agua salada: esto fortalece las piernas y te permite correr largas distancias.",
    ["Our thermal pool will boost your vitality and make you resistant to poisons. That should help protect you against those pesky Vile blooms, should you have any plans to face them."] = "Nuestra piscina termal aumentará tu vitalidad y te hará resistente a los venenos. Eso debería ayudarte a protegerte contra esas molestas flores viles, en caso de que tengas algún plan para enfrentarlas.",
    ["Finally, we have a mud bath which helps you connect with your primal senses. I strongly recommend this treatment if you plan on doing any hunting any of those big, scary creatures on the island."] = "Finalmente, tenemos un baño de barro que te ayuda a conectar con tus sentidos primarios. Recomiendo encarecidamente este tratamiento si planeas cazar alguna de esas criaturas grandes y aterradoras de la isla.",
    ["What benefits do I get for helping upgrade the spa?"] = "¿Qué beneficios obtengo por ayudar a mejorar el spa?",
    ["If you help me to build the spa, I can get some supplies from the mainland."] = "Si me ayudas a construir el spa, puedo conseguir algunos suministros del continente.",
    ["The main benefit I think you'll like is that my relaxation salts will enter your soul. This will allow you to gain more experience while training Agility on the island. I can also offer you use of my spa pools which offer various benefits."] = "El principal beneficio que creo que te gustará es que mis sales de relajación entrarán en tu alma. Esto te permitirá ganar más experiencia mientras entrenas a Agility en la isla. También puedo ofrecerle el uso de mis piscinas de spa que ofrecen diversos beneficios.",
    ["If you can help me fully upgrade my spa I believe I can use this island to modify the spa pools to make the effects last longer. Surely that sounds appealing to an adventurer like yourself?"] = "Si pueden ayudarme a mejorar completamente mi spa, creo que puedo usar esta isla para modificar las piscinas del spa y hacer que los efectos duren más. ¿Seguramente eso suena atractivo para un aventurero como tú?",
    ["If you help me to upgrade the spa, I can get some supplies from the mainland."] = "Si me ayudas a mejorar el spa, puedo conseguir algunos suministros del continente.",
    ["The main benefit I think you'll like is that my relaxation salts will enter your soul. This will allow you to gain more experience while training Agility on the island."] = "El principal beneficio que creo que te gustará es que mis sales de relajación entrarán en tu alma. Esto te permitirá ganar más experiencia mientras entrenas a Agility en la isla.",
    ["I can also offer you the use of my spa pools which offer various benefits."] = "También puedo ofrecerte el uso de mis piscinas de spa que ofrecen varios beneficios.",
    ["Finally, I can use this island to modify the spa pools to make the effects last longer. Surely that sounds appealing to an adventurer like yourself?"] = "Finalmente, puedo usar esta isla para modificar las piscinas del spa y hacer que los efectos duren más. ¿Seguramente eso suena atractivo para un aventurero como tú?",
    ["How did you meet Mr. Mordaut?"] = "¿Cómo conoció al señor Mordaut?",
    ["What an incredible story!"] = "¡Qué historia tan increíble!",
    ["I better go."] = "Mejor me voy.",
    ["Take care."] = "Cuídate.",
    ["I hate this job. All the other staff are so happy all the time. It depresses me."] = "Odio este trabajo. Todos los demás staff están muy felices todo el tiempo. Me deprime.",
    ["Why don't you get a new job?"] = "¿Por qué no consigues un nuevo trabajo?",
    ["I can't find any other work. I wanted to be a Gnomeball player but I wasn't big enough. I came up with some clever tricks using my feet, but I was told they weren't fit for gnomeball. 'Gnomeball is played with the hands,' they said. Well, even Mad Donna isn't as good as I am with my feet."] = "No encuentro ningún otro trabajo. Quería ser jugador de Gnomeball pero no era lo suficientemente grande. Se me ocurrieron algunos trucos ingeniosos usando mis pies, pero me dijeron que no eran aptos para gnomeball. \"El Gnomeball se juega con las manos\", decían. Bueno, ni siquiera Mad Donna es tan buena con los pies como yo.",
    ["Can you show me your tricks?"] = "¿Puedes mostrarme tus trucos?",
    ["I'd love to, but I'm supposed to be at work right now. Besides, the other gnomes laugh at me. They don't appreciate skill when they see it!"] = "Me encantaría, pero se supone que debo estar en el trabajo ahora mismo. Además, los otros gnomos se ríen de mí. ¡No aprecian la habilidad cuando la ven!",
    ["Who is Mad Donna?"] = "¿Quién es la loca Donna?",
    ["Mad Donna is a genius with a gnomeball! She invented a trick using everything except the hands to control a gnomeball. It's called the Mad Donna Seven. Other gnomes call her mad because her trick doesn't involve holding the gnomeball. But she's my inspiration to invent new and exciting tricks!"] = "¡Mad Donna es un genio con una bola de gnomo! Inventó un truco usando todo excepto las manos para controlar una bola de gnomo. Se llama Mad Donna Seven. Otros gnomos la llaman loca porque su truco no implica sostener la bola de gnomo. ¡Pero ella es mi inspiración para inventar trucos nuevos y emocionantes!",
    ["OK, whatever."] = "Está bien, lo que sea.",
    ["Aren't you going to wish me a nice day?"] = "¿No me vas a desear un lindo día?",
    ["Have a day. It can be nice if you can be bothered. I know I can't."] = "Que tengas un día. Puede ser agradable si te molestan. Sé que no puedo.",
    ["... nice."] = "... bien.",
    ["A cloud of sparkles has taken over a glyph!"] = "¡Una nube de destellos se ha apoderado de un glifo!",
    ["You expel the sparkles on the glyph."] = "Expulsas los destellos del glifo.",
    ["The following reward is added to the ritual chest: 1 x [Item]"] = "Se agrega la siguiente recompensa al cofre ritual: 1 x [Item]",
    ["Look dad it you! Fritty Plower!"] = "¡Mira papá, eres tú! ¡Arado fritty!",
    ["Even own boy make fun of me. This sad day for trolls."] = "Incluso mi propio chico se burla de mí. Este día triste para los trolls.",
    ["Big rock!"] = "¡Gran roca!",
    ["Hahaha, big rock, big rock!"] = "¡Jajaja, gran roca, gran roca!",
    ["What you want?"] = "¿Qué quieres?",
    ["Chatterchatterchatter chatterchatter chatter!"] = "¡Chatterchatterchatterchatterchatterchatter!",
    ["Hmm. If I was more skilled with animals, I would be able to figure out what he's saying."] = "Mmm. Si fuera más hábil con los animales, podría entender lo que dice.",
    ["Chatter! (Hi!)"] = "¡Charla! (¡Hola!)",
    ["How did you end up here?"] = "¿Cómo terminaste aquí?",
    ["Chatter chatterchatter chatter-chip. (I used to live near the Ranging Guild up in McGrubor's Wood.)"] = "Chatter chatterchatter chatter-chip. (Solía ​​vivir cerca del Ranging Guild en McGrubor's Wood).",
    ["Chip chatterchatter. (One day, I was out foraging for nuts when I noticed a crowd at the guild.)"] = "Chip parlotea. (Un día, estaba buscando nueces cuando noté una multitud en el gremio).",
    ["Chip chip-chatter. (Geoff was trying to join the guild, aiming the shot that would've got him in.)"] = "Chip-chip-charla. (Geoff estaba tratando de unirse al gremio, apuntando el tiro que lo habría metido).",
    ["What happened next?"] = "¿Qué pasó después?",
    ["Chip chatter chatter-chip. (The arrow soared towards its target, but ricocheted off something that was carried by a passing swallow.)"] = "Chip parloteo parloteo-chip. (La flecha se elevó hacia su objetivo, pero rebotó en algo que llevaba una golondrina que pasaba).",
    ["What could a swallow possibly carry?"] = "¿Qué podría llevar una golondrina?",
    ["Chatter chatterchatter chatter. (I don't know! The next thing I knew, the arrow was coming right for me!)"] = "Charla, charla, charla, charla. (¡No lo sé! Lo siguiente que supe fue que ¡la flecha venía directamente hacia mí!)",
    ["Chatter-cip chatterchatter-chip. (When I woke up, I was here and Geoff was looking after me.)"] = "Chatter-cip chatterchatter-chip. (Cuando desperté, estaba aquí y Geoff me estaba cuidando).",
    ["Chip chatterchatter. (It's quite nice here, so I decided to stay and cheer Geoff up.)"] = "Chip parlotea. (Es bastante agradable aquí, así que decidí quedarme y animar a Geoff).",
    ["An interesting but implausible tale."] = "Una historia interesante pero inverosímil.",
    ["Chatter-chip-chatter! (Thanks! I brush it every day.)"] = "¡Chatter-chip-chatter! (¡Gracias! Lo cepillo todos los días).",
    ["Boring!"] = "¡Aburrido!",
    ["Chatter-chip! (<span style=\"color:#3366FF\">This would be impolite to translate.</span>)"] = "¡Chatter-chip! (<span style=\"color:#3366FF\">Sería descortés traducir esto.</span>)",
    ["Say, that's a nice hat."] = "Oye, es un bonito sombrero.",
    ["Chatterchatterchatter chatter-chip. (Yeah, it's jaunty.)"] = "Chatterchatterchatter chatter-chip. (Sí, es alegre).",
    ["Can I have it?"] = "¿Puedo tenerlo?",
    ["Chatter chip-chip chatter! (Don't you think it would be a bit small for you?)"] = "¡Chatter chip-chip chat! (¿No crees que te quedaría un poco pequeño?)",
    ["I suppose."] = "Supongo.",
    ["Chatter chatter chatter chatter-chip. (I can give directions to where I found it, if you like.)"] = "Charla, charla, charla, charla, chip. (Puedo darte indicaciones sobre dónde lo encontré, si quieres).",
    ["Chip-chip-chip-chip-chip-chatter. (Okay, if you scurry about two-hundred paces north, then about five-hundred paces east, you should get there.)"] = "Chip-chip-chip-chip-chip-charla. (Está bien, si corres unos doscientos pasos al norte y luego unos quinientos pasos al este, deberías llegar allí).",
    ["Hmm, could you write that down for me?"] = "Hmm, ¿podrías escribirme eso?",
    ["Chatter-chatter. (I'm a squirrel.)"] = "Charla-charla. (Soy una ardilla).",
    ["Nah."] = "No.",
    ["Chip-chip. (Suit yourself.)"] = "Chip-chip. (Haz lo que quieras.)",
    ["Chatter chatter-chip chip chatter-chip. (I can give directions to where I found it, if you like.)"] = "Chatter chatter-chip chip chatter-chip. (Puedo darte indicaciones sobre dónde lo encontré, si quieres).",
    ["Where did you get it?"] = "¿De dónde lo conseguiste?",
    ["Chatter-chip-chatter chatterchatter chatter-chip! (I found this great place where you can get all kinds of stuff like this.)"] = "¡Chatter-chip-chatter, chatterchatter, chatter-chip! (Encontré este gran lugar donde puedes conseguir todo tipo de cosas como esta).",
    ["Really? Can you tell me where it is?"] = "¿En serio? ¿Puedes decirme dónde está?",
    ["Chatter! Chip-chip-chatter chatter chatter. (I don't know the name of the place, but I can give you directions if you like.)"] = "¡Charla! Chip-chip-charla, charla, charla. (No sé el nombre del lugar, pero puedo darte indicaciones si quieres).",
    ["Yes, please go on!"] = "¡Sí, continúa!",
    ["Chatterchatterchatterchatterchatter. (Well, as the crow flies-)"] = "Chatterchatterchatterchatterchatter. (Bueno, en línea recta-)",
    ["As the crow flies? How does a squirrel know how the crow flies?"] = "¿En línea recta? ¿Cómo sabe una ardilla cómo vuela el cuervo?",
    ["Chip chatterchipchatter chatterchatter! (Hey! My uncle was a crow!)"] = "¡Chip chatterchipchatter chatterchatter! (¡Oye! ¡Mi tío era un cuervo!)",
    ["That...that doesn't make any sense."] = "Eso... eso no tiene ningún sentido.",
    ["Chatter-chip-chatter-chip-chip. (Look, do you want these directions or not?)"] = "Chatter-chip-chatter-chip-chip. (Mira, ¿quieres estas instrucciones o no?)",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["What do you think of Geoff?"] = "¿Qué opinas de Geoff?",
    ["Chatter chatter-chip chatter. (He's good guy. It's a shame that he still blames himself for my leg.)"] = "Charla, charla, charla. (Es un buen tipo. Es una pena que todavía se culpe por mi pierna).",
    ["To what do I owe the pleasure?"] = "¿A qué debo el placer?",
    ["What's your story?"] = "¿Cuál es tu historia?",
    ["I could tell you, but I'd have to kill you."] = "Podría decírtelo, pero tendría que matarte.",
    ["Given the circumstances I'm not sure if that's a joke..."] = "Dadas las circunstancias, no estoy seguro de si es una broma...",
    ["Right now, I'm not sure either."] = "En este momento, tampoco estoy seguro.",
    ["I'll take the risk."] = "Me arriesgaré.",
    ["Ha, you're bold indeed."] = "Ja, eres realmente atrevido.",
    ["The surrounding bandits give you a worrying glare."] = "Los bandidos de los alrededores te lanzan una mirada preocupante.",
    ["Alright, I'll bite. Used to make a pretty penny evicting a few poor souls from their bodies."] = "Muy bien, morderé. Solía ​​ganar bastante dinero desalojando a algunas pobres almas de sus cuerpos.",
    ["An assassin, then."] = "Entonces, un asesino.",
    ["You'd be surprised how often you'll find 'employment' in a 'civilised' place like Misthalin."] = "Te sorprendería saber con qué frecuencia encontrarás \"empleo\" en un lugar \"civilizado\" como Misthalin.",
    ["I hadn't thought that someone might eventually take offence. I'm known to the authorities now, a fugitive."] = "No había pensado que alguien eventualmente podría ofenderse. Ahora las autoridades me conocen, soy un fugitivo.",
    ["Speaking on the topic, got anyone around these parts you need taking care of? My rates are reasonable."] = "Hablando sobre el tema, ¿hay alguien por aquí de quien necesites ocuparte? Mis tarifas son razonables.",
    ["I'll keep your offer in mind."] = "Tendré en cuenta tu oferta.",
    ["At your service."] = "A su servicio.",
    ["Ah. Erm. No thank you."] = "Ah. Emmm. No, gracias.",
    ["I'll, erm, just let you get back to your business."] = "Te dejaré volver a tus asuntos.",
    ["You seem to be pretty welcoming now."] = "Pareces ser bastante acogedor ahora.",
    ["I'm getting a good feeling from you. You're marked by your intentions."] = "Tengo un buen presentimiento por tu parte. Estás marcado por tus intenciones.",
    ["You can tell, huh? It is a little thrilling, and a little scary."] = "Se nota, ¿eh? Es un poco emocionante y un poco aterrador.",
    ["Wonderful isn't it? Blood pumping, adrenaline flowing."] = "Maravilloso, ¿no? La sangre bombea, adrenaline fluye.",
    ["We have more trust in someone willing to put themselves at risk. The overly cautious don't belong in these lands."] = "Confiamos más en alguien dispuesto a ponerse en riesgo. Los demasiado cautelosos no pertenecen a estas tierras.",
    ["How did you get your nickname?"] = "¿Cómo obtuviste tu apodo?",
    ["Well, that's a long story."] = "Bueno, esa es una larga historia.",
    ["Go on."] = "Continúa.",
    ["You see..."] = "Verás...",
    ["my kills have been described as notably rapid."] = "mis muertes han sido descritas como notablemente rápidas.",
    ["And my real name?"] = "¿Y mi verdadero nombre?",
    ["That's Keith."] = "Ese es Keith.",
    ["We've been tasked by Santa to bring a whole bunch of fun to Gielinor this season. I'm handing out flyers that will let you know everything we have planned."] = "Santa nos ha encargado traer mucha diversión a Gielinor esta temporada. Estoy repartiendo folletos que les informarán todo lo que hemos planeado.",
    ["Can I interest you in one?"] = "¿Puedo interesarte en uno?",
    ["Well, I guess there's snow time like the present!"] = "Bueno, ¡supongo que hay épocas de nieve como las actuales!",
    ["It looks like one of my colleagues has already managed to give you one! Please come back if you lose the flyer."] = "¡Parece que uno de mis colegas ya logró darte uno! Por favor regrese si pierde el volante.",
    ["Remind me why you're here?"] = "¿Recuérdame por qué estás aquí?",
    ["Of course, if you lose the flyer, you can always come talk to me to get a new one. Alternatively, I can let you know all the interesting events we have planned."] = "Por supuesto, si pierdes el folleto, siempre puedes venir a hablar conmigo para conseguir uno nuevo. Alternativamente, puedo informarte de todos los eventos interesantes que hemos planeado.",
    ["What awaits me this festive season?"] = "¿Qué me espera en estas fiestas?",
    ["Can I have another flyer?"] = "¿Puedo tener otro folleto?",
    ["Come back when you have some inventory space."] = "Vuelve cuando tengas algo de espacio en el inventario.",
    ["Goodbye Spencer! It was ice to meet you!"] = "¡Adiós Spencer! ¡Fue hielo conocerte!",
    ["Bye for now!"] = "¡Adiós por ahora!",
    ["ello 'ello!"] = "¡Hola, hola!",
    ["What's going on?"] = "¿Qué está pasando?",
    ["Only da best time of the year!"] = "¡Solo la mejor época del año!",
    ["Diango and da pixies 'ave joined us in the Christmas Village. He's a slowpoke so probably needs your 'elp to set up 'is workshop."] = "Diango y los duendes se han unido a nosotros en Christmas Village. Es lento, por lo que probablemente necesite tu ayuda para montar su taller.",
    ["There's also skilling activities, weekly visits from Santa 'imself, and wrapping paper to make prezzies too!"] = "¡También hay actividades de habilidad, visitas semanales del mismísimo Papá Noel y papel de regalo para hacer prezzies también!",
    ["We've also set up an advent calendar, and weekly buffs over the festive season, which we're callin' 'Winter Weeks'. Trademarked, that."] = "También hemos creado un calendario de Adviento y mejoras semanales durante la temporada festiva, a las que llamaremos \"Semanas de Invierno\". Marca registrada, eso.",
    ["Jump into that portal over there to join in!"] = "¡Salta a ese portal de allí para unirte!",
    ["Wow, thanks! It sounds like there's plenty for me to get stuck into."] = "¡Vaya, gracias! Parece que hay mucho en lo que quedarme atrapado.",
    ["What can I get?"] = "¿Qué puedo conseguir?",
    ["What can I get from the festivities?"] = "¿Qué puedo obtener de las festividades?",
    ["Ya seet those people sittin' over there wearin' the pj's and slippers? You can get those from Santa's Lodge!"] = "¿Ves a esa gente sentada allí en pijama y pantuflas? ¡Puedes conseguirlos en Santa's Lodge!",
    ["If ye wanna sit like them, you can if you 'elp out Diango and the pixies in 'is workshop."] = "Si quieres sentarte como ellos, puedes hacerlo si ayudas a Diango y a los duendes en su taller.",
    ["Holly has some new stuff in 'er store too, so check that out! We're also wrapping up a bunch more new rewards in da Christmas presents this year - Noel can tell you about 'em."] = "Holly también tiene algunas cosas nuevas en su tienda, ¡así que échale un vistazo! También estamos finalizando un montón de recompensas nuevas en los regalos de Navidad de este año: Noel puede informarte sobre ellas.",
    ["Thanks! That's a lot of new rewards to check out."] = "¡Gracias! Son muchas recompensas nuevas para ver.",
    ["Dey don't call it the season of giving for nuthin'!"] = "¡No la llaman la temporada de dar por nada!",
    ["You're too late! The festivities are over pal, but you can still visit the Christmas Village if ya got any goodies left to claim!"] = "¡Llegas demasiado tarde! ¡Las festividades han terminado, amigo, pero aún puedes visitar Christmas Village si aún te queda algo por reclamar!",
    ["You're too late, Christmas is over! Come back next year."] = "¡Llegas demasiado tarde, se acabó la Navidad! Vuelve el año que viene.",
    ["Da lovely lady of the season, da Queen of Snow 'erself, 'as set up a snowball arena in da village. She didn't look very 'appy wiv it though, so maybe you can 'elp her out."] = "La encantadora dama de la temporada, la propia Queen of Snow, instaló una arena de bolas de nieve en el pueblo. Sin embargo, no parecía muy contenta con eso, así que tal vez puedas ayudarla.",
    ["Jump into this portal to join in!"] = "¡Ingresa a este portal para unirte!",
    ["Ya seet those people sittin' over there wearin' the jumpers? You can get those from Holly's Christmas Spirit Shop!"] = "¿Ves a esas personas sentadas allí con jerseys? ¡Puedes conseguirlos en la tienda navideña Spirit de Holly!",
    ["If ye wanna have their snazzy slippers too, you can if you 'elp out the Queen of Snow in 'er snowball arena."] = "Si también quieres tener sus elegantes pantuflas, puedes hacerlo si ayudas al Queen of Snow en su campo de bolas de nieve.",
    ["We're also wrapping up a bunch more new rewards in da Christmas presents this year - Noel can tell you about 'em."] = "También estamos finalizando un montón de recompensas nuevas en los regalos de Navidad de este año; Noel puede informarte sobre ellas.",
    ["The Sphinx ignores you."] = "El Sphinx te ignora.",
    ["Ah, how interesting...a cat. Come here to me, kitty."] = "Ah, qué interesante... un gato. Ven aquí, gatito.",
    ["**[Cat:]** Meow."] = "**[Cat:]** Miau.",
    ["Your cat and the Sphinx converse in a yeowling language for a short time."] = "Tu gato y el Sphinx conversan en un lenguaje aullante durante un breve momento.",
    ["Do you think that you'll be able to communicate with me at a deeper level because you're wearing that amulet of catspeak?"] = "¿Crees que podrás comunicarte conmigo a un nivel más profundo porque llevas ese amuleto de gato?",
    ["Ummm, yes."] = "Mmmm, sí.",
    ["Foolish human, am I not part human? The Sphinx shakes her head in bemusement."] = "Humano tonto, ¿no soy en parte humano? La Sphinx sacude la cabeza desconcertada.",
    ["**Player:** I need help."] = "**Player:** Necesito ayuda.",
    ["What with? Your cat tells me that you have held The Devourer at bay."] = "¿Con qué? Tu gato me dice que has mantenido a raya al Devorador.",
    ["I need help with The Devourer."] = "Necesito ayuda con El Devorador.",
    ["I need help with The Devourer. I haven't defeated her."] = "Necesito ayuda con The Devourer. No la he derrotado.",
    ["I hope that you will come to the understanding that not all the world's problems can be solved by an individual. You've done your bit; it's now up to the Menaphites and the priests of Icthlarin to solve this standoff."] = "Espero que llegues a comprender que no todos los problemas del mundo pueden ser resueltos por un individuo. Has puesto tu granito de arena; Ahora depende de los menafitas y los sacerdotes de Icthlarin resolver este enfrentamiento.",
    ["I have to confess that, despite myself, I am impressed by your actions. I may have some work for you at a later date."] = "Tengo que confesar que, a mi pesar, estoy impresionado por tus acciones. Es posible que tenga algo de trabajo para usted en una fecha posterior.",
    ["Can you tell me about the gods of the Menaphites?"] = "¿Puedes hablarme de los dioses de los menafitas?",
    ["**Sphinx:** I suppose I could spare a moment or two. Who do you want to know about?"] = "**Sphinx:** Supongo que podría dedicar un momento o dos. ¿De quién quieres saber?",
    ["I am an agent of neither good nor evil. I am unconcerned with the plight of mankind and their petty wars and beliefs."] = "No soy un agente ni del bien ni del mal. No me preocupan la difícil situación de la humanidad y sus pequeñas guerras y creencias.",
    ["Well, now that you've told me what you're not, can you please tell me who or what you are?"] = "Bueno, ahora que me has dicho lo que no eres, ¿podrías decirme quién o qué eres?",
    ["I am the guardian of feline kind."] = "Soy el guardián de los felinos.",
    ["Why would they need a guardian?"] = "¿Por qué necesitarían un tutor?",
    ["Cats play a significant role in the religion of this area, particularly when it comes to guarding the dead from The Devourer."] = "Los gatos juegan un papel importante en la religión de esta zona, particularmente cuando se trata de proteger a los muertos del Devorador.",
    ["The Devourer?"] = "¿El Devorador?",
    ["She's the very incarnation of destruction. I would think you remember her from your previous activities."] = "Ella es la encarnación misma de la destrucción. Creo que la recuerdas de tus actividades anteriores.",
    ["Can I ask about someone else?"] = "¿Puedo preguntar por alguien más?",
    ["Thanks, I think I now have a better understanding of this place."] = "Gracias, creo que ahora entiendo mejor este lugar.",
    ["Tell me about the major gods."] = "Háblame de los dioses principales.",
    ["Tell me about Tumeken."] = "Háblame de Tumekén.",
    ["Tumeken is the chief god of the area. You could say that you see him wherever you look but never notice him."] = "Tumeken es el dios principal de la zona. Se podría decir que lo ves dondequiera que mires pero nunca lo notas.",
    ["So he's the god of this land. The desert is a harsh place; would that make him friendly or unfriendly? Or will you say, 'both', as usual?"] = "Entonces él es el dios de esta tierra. El desierto es un lugar duro; ¿Eso lo haría amigable o antipático? ¿O dirás \"ambos\", como siempre?",
    ["You begin to understand. The desert is indeed harsh but it protects us from outsiders. Outsiders generally mean us no good, so he protects Menaphos through this harshness."] = "Empiezas a entender. El desierto es ciertamente duro pero nos protege de los forasteros. Los forasteros generalmente no nos quieren bien, por lo que protege a Menaphos a través de esta dureza.",
    ["You humans have a saying, 'you have to be cruel to be kind', it seems to fit Tumeken."] = "Ustedes los humanos tienen un dicho: 'hay que ser cruel para ser amable', parece encajar con Tumeken.",
    ["If he is so powerful, why doesn't he get involved more? After all, I've had to do some missions where a deity could have polished off miraculously."] = "Si es tan poderoso, ¿por qué no se involucra más? Después de todo, he tenido que hacer algunas misiones en las que una deidad podría haber acabado milagrosamente.",
    ["Well, if you can imagine the force of the desert, it's not exactly a subtle instrument. Why use a sledgehammer to crack a nut...especially when you can be persuaded to help?"] = "Bueno, si puedes imaginar la fuerza del desierto, no es exactamente un instrumento sutil. ¿Por qué utilizar un mazo para romper una nuez... especialmente cuando te pueden convencer para que ayudes?",
    ["Sounds a bit lazy, really."] = "Suena un poco vago, la verdad.",
    ["It's lucky that he prefers to spend his time with Elidinis rather than smiting you."] = "Es una suerte que prefiera pasar su tiempo con Elidinis en lugar de golpearte.",
    ["Tell me about Elidinis."] = "Háblame de Elidinis.",
    ["The Menaphite pantheon is made up of four main deities."] = "El panteón menafita está formado por cuatro deidades principales.",
    ["Hang on... Pantheon? Deities? What are you talking about?"] = "Espera... ¿Panteón? ¿Deidades? ¿De qué estás hablando?",
    ["Sorry, I'm getting a bit ahead of myself. A pantheon is the collective name for the gods or deities of a group of people."] = "Lo siento, me estoy adelantando un poco. Un panteón es el nombre colectivo de los dioses o deidades de un grupo de personas.",
    ["The main god which the Menaphites worship is called Tumeken. His wife, Elidinis, is the god of fertility and growth."] = "El dios principal que adoran los menafitas se llama Tumeken. Su esposa, Elidinis, es la diosa de la fertilidad y el crecimiento.",
    ["Does she have anything to do with the river?"] = "¿Tiene algo que ver con el río?",
    ["That's very observant of you. The river Elid is named in her honour as it brings growth and life to the area during times of flood."] = "Eso es muy observador de tu parte. El río Elid lleva su nombre en su honor, ya que aporta crecimiento y vida a la zona durante las épocas de inundaciones.",
    ["Some might also phrase it that she is named after the river, or that she is the river. It's a common area of theological debate."] = "Algunos también podrían decir que ella lleva el nombre del río, o que ella es el río. Es un área común de debate teológico.",
    ["So where do the other two main deities fit in?"] = "Entonces, ¿dónde encajan las otras dos deidades principales?",
    ["Tumeken and Elidinis had two children: Icthlarin and The Devourer."] = "Tumeken y Elidinis tuvieron dos hijos: Icthlarin y The Devourer.",
    ["Tell me about Amascut."] = "Háblame de Amascut.",
    ["Tell me about The Devourer. With a name like that, it's no wonder she turned out to be messed up."] = "Háblame de El Devorador. Con un nombre así, no es de extrañar que resultara hecha un desastre.",
    ["She was not always called such. She is thought of by her deeds, now, rather than her name."] = "No siempre la llamaron así. Ahora se piensa en ella por sus hechos, más que por su nombre.",
    ["The Devourer is the goddess of destruction; she craves only to destroy things."] = "La Devoradora es la diosa de la destrucción; ella sólo anhela destruir las cosas.",
    ["I thought someone said she wasn't evil?"] = "Pensé que alguien había dicho que ella no era malvada.",
    ["Fire destroys, but is that evil?"] = "El fuego destruye, pero ¿es eso malo?",
    ["Um, no, but it also creates heat."] = "Um, no, pero también genera calor.",
    ["Okay, we could have an overlong theological debate now, but to get to my point, recently - well, in the last age or so - The Devourer has taken to destroying humans."] = "Vale, podríamos tener un debate teológico demasiado largo ahora, pero para ir al punto, recientemente (bueno, en la última era) El Devorador se ha dedicado a destruir humanos.",
    ["Not just killing them; totally destroying them, body and soul. This has brought her into conflict with Icthlarin."] = "No sólo matarlos; destruyéndolos totalmente, en cuerpo y alma. Esto la ha puesto en conflicto con Icthlarin.",
    ["Ah hah, I see where this is going: the cats are used to protect the dead from The Devourer."] = "Ah, ja, ya veo a dónde va esto: los gatos se utilizan para proteger a los muertos del Devorador.",
    ["Indeed, The Devourer is terrified of cats for reasons I will not explain. Her followers - although few in number - are not, so I have to watch for them in my role as protector of cats."] = "De hecho, El Devorador tiene miedo de los gatos por razones que no explicaré. Sus seguidores, aunque pocos, no lo son, por lo que tengo que estar atento a ellos en mi papel de protector de los gatos.",
    ["Tell me about Icthlarin."] = "Háblame de Icthlarin.",
    ["I ensure the survival of cats and, for this service, Icthlarin grants me eternal life."] = "Aseguro la supervivencia de los gatos y, por este servicio, Icthlarin me concede la vida eterna.",
    ["So, then, you are a follower of Icthlarin?"] = "Entonces, ¿eres seguidor de Icthlarin?",
    ["Nothing of the sort. As I've said before, I have no interest in humans. I look after my kind and, for that, Icthlarin looks after me."] = "Nada de eso. Como he dicho antes, no tengo ningún interés en los humanos. Cuido a los de mi especie y, por eso, Icthlarin me cuida a mí.",
    ["So you protect the good cats against the follower of the bad god, the Devourer? That I can understand, at last."] = "¿Entonces proteges a los gatos buenos contra el seguidor del dios malo, el Devorador? Eso lo puedo entender, por fin.",
    ["No, it's not really that simple. Neither are either good or bad. Icthlarin is the god of the dead and takes care of the passing of souls from one plane to another."] = "No, en realidad no es tan simple. Tampoco son buenos ni malos. Icthlarin es el dios de los muertos y se encarga del paso de las almas de un plano a otro.",
    ["He once even was worshipped by the Mahjarrat but they turned away from him in the Third Age to follow Zamorak."] = "Una vez incluso fue adorado por Mahjarrat, pero se alejaron de él en la Tercera Edad para seguir a Zamorak.",
    ["Or maybe it was Zaros to whom they turned; it was a long time ago and not that important. Suffice to say, Icthlarin cares for the dead rather than creating them."] = "O tal vez fue Zaros a quien recurrieron; Fue hace mucho tiempo y no es tan importante. Basta decir que Icthlarin se preocupa por los muertos en lugar de crearlos.",
    ["Tell me about the minor gods."] = "Háblame de los dioses menores.",
    ["Tell me about Scabaras."] = "Háblame de Scabaras.",
    ["The Sect of Scabaras: a cult dedicated to the lesser deity Scabaras."] = "La Secta de Scabaras: un culto dedicado a la deidad menor Scabaras.",
    ["What's a lesser deity?"] = "¿Qué es una deidad menor?",
    ["The Book of Light and Day says that Tumeken once fell into a deep sleep and dreamt for four days and four nights. The first night he slept and dreamt a good dream. He dreamt of a journey long and arduous. From the loins of his subconscious, Apmeken was born into reality, a physical manifestation of his dream. Tumeken continued to have pleasant dreams for a further two days and two nights. After each, a new deity came into being. On the fourth night, however, Tumeken dreamt a bad dream. He dreamt of himself and he dreamt of his increasing isolation caused by his extended sleep. This isolation sprung forth into the world and took on the form of Scabaras."] = "El Libro de la Luz y el Día dice que una vez Tumeken cayó en un sueño profundo y soñó durante cuatro días y cuatro noches. La primera noche durmió y tuvo un buen sueño. Soñaba con un viaje largo y arduo. De las entrañas de su subconsciente, Apmeken nació a la realidad, una manifestación física de su sueño. Tumeken continuó teniendo sueños placenteros durante dos días y dos noches más. Después de cada uno, surgió una nueva deidad. Sin embargo, la cuarta noche, Tumeken tuvo una pesadilla. Soñaba consigo mismo y soñaba con el aislamiento cada vez mayor provocado por el sueño prolongado. Este aislamiento brotó en el mundo y tomó la forma de Scabaras.",
    ["Okay, you could've just said...'a dream' or something. Where were we?"] = "Vale, podrías haber dicho simplemente... \"un sueño\" o algo así. ¿Dónde estábamos?",
    ["Yes, the followers of Scabaras used to be great architects of the subterranean. According to legend, they once planned to build a passage under the river Elid. No doubt Elidinis smote them because none of the followers were ever seen again."] = "Sí, los seguidores de Scabaras solían ser grandes arquitectos del subterráneo. Según la leyenda, una vez planearon construir un pasaje bajo el río Elid. Sin duda, Elidinis los golpeó porque nunca más se volvió a ver a ninguno de sus seguidores.",
    ["That sounds interesting. Do they have any altars or temples left in the city?"] = "Eso suena interesante. ¿Les queda algún altar o templo en la ciudad?",
    ["Yes, there is a shrine dedicated to Scabaras in the Temple of the Lesser Gods in the north-east of this city. Jex there might know more about the minor deities."] = "Sí, hay un santuario dedicado a Scabaras en el Templo de los Dioses Menores en el noreste de esta ciudad. Jex es posible que sepa más sobre las deidades menores.",
    ["Tell me about Het."] = "Háblame de Het.",
    ["Het is the lesser deity concerned with strength and physical health. Sophanem is the city of the dead. so Het isn't worshipped much here."] = "Het es la deidad menor que se ocupa de la fuerza y la salud física. Sophanem es la ciudad de los muertos. así que aquí no se adora mucho a Het.",
    ["Can you tell me any more?"] = "¿Puedes contarme algo más?",
    ["Yes, there is a shrine dedicated to Het in the Temple of the Lesser Gods in the north-east of this city. Jex there should know more about Het."] = "Sí, hay un santuario dedicado a Het en el Templo de los Dioses Menores en el noreste de esta ciudad. Jex debería saber más sobre Het.",
    ["Tell me about Crondis."] = "Háblame de Crondis.",
    ["Crondis is the lesser deity of resourcefulness and unassuming cunning. She has the head of a crocodile, which I don't see as being physically pleasant."] = "Crondis es la deidad menor del ingenio y la astucia sencilla. Tiene cabeza de cocodrilo, lo cual no me parece nada agradable físicamente.",
    ["Coming from a mixed up creature like yourself, that's an interesting criticism. Any other information you can impart?"] = "Viniendo de una criatura confusa como tú, es una crítica interesante. ¿Alguna otra información que puedas impartir?",
    ["There is a place sacred to Crondis in the Temple of the Lesser Gods in the north-east of this city. Jex there should know more about this deity."] = "Hay un lugar sagrado para Crondis en el Templo de los Dioses Menores en el noreste de esta ciudad. Jex debería saber más sobre esta deidad.",
    ["Tell me about Apmeken."] = "Háblame de Apmeken.",
    ["Apmeken has the head of a monkey and is the incarnation of friendship and jest. Good for a chat, but prone to exaggeration, by all reports."] = "Apmeken tiene cabeza de mono y es la encarnación de la amistad y la broma. Bueno para charlar, pero propenso a la exageración, según todos los informes.",
    ["You've met Apmeken?"] = "¿Conoces a Apmeken?",
    ["That's for me to know and you to contemplate. By all accounts she's a feisty thing. It is said that, during Tumeken's Dream, she scampered upon Tumeken's very shoulders."] = "Eso es para que yo lo sepa y tú lo contemples. Según todos los indicios, ella es una persona luchadora. Se dice que, durante el Sueño de Tumeken, ella correteó sobre los hombros de Tumeken.",
    ["What did Tumeken do?"] = "¿Qué hizo Tumeken?",
    ["Turned her into a deity, of all things. I'm sure Jex at the Temple of the Lesser Gods can give more information, should you seek it."] = "La convirtió en una deidad, entre todas las cosas. Estoy seguro de que Jex en el Templo de los Dioses Menores puede brindarle más información, si la busca.",
    ["Meow."] = "Miau.",
    ["What do you want, human?"] = "¿Qué quieres, humano?",
    ["I need help."] = "Necesito ayuda.",
    ["Do you have a spare amulet of catspeak?"] = "¿Tienes un amuleto de gato de repuesto?",
    ["Well, I suppose I do. Seeing as you're such a good guardian of cats, I'll give you one. Be careful with it, though, I only have so many."] = "Bueno, supongo que sí. Como eres tan buen guardián de los gatos, te regalaré uno. Pero ten cuidado con eso, solo tengo una cantidad limitada.",
    ["The Sphinx hands you an amulet of catspeak."] = "El Sphinx te entrega un amuleto de gato.",
    ["You have the feel of a cat person about you. Do you look after one?"] = "Tienes la sensación de ser un gato a tu alrededor. ¿Cuidas uno?",
    ["Yes, but I don't bring it to harsh places like this."] = "Sí, pero no lo llevo a lugares difíciles como este.",
    ["A pity; they can be of great help in some adventures. I would like to talk to your cat. Would you bring it to me?"] = "Una lástima; Pueden ser de gran ayuda en algunas aventuras. Me gustaría hablar con tu gato. ¿Me lo traerías?",
    ["I might, but I have a few things to sort out first though."] = "Puede que sí, pero primero tengo algunas cosas que resolver.",
    ["No, you are mistaken."] = "No, estás equivocado.",
    ["Really? I'm generally quite good at knowing these sorts of things."] = "¿En serio? Generalmente soy bastante bueno sabiendo este tipo de cosas.",
    ["Yes, but I've left mine in the bank."] = "Sí, pero el mío lo dejé en el banco.",
    ["What? That's no place for a cat!"] = "¿Qué? ¡Ese no es lugar para un gato!",
    ["Human, you interest me not."] = "Humano, no me interesas.",
    ["What? I'm really interesting! I'm a daring adventurer and have completed many daring quests."] = "¿Qué? ¡Soy realmente interesante! Soy un aventurero atrevido y he completado muchas misiones atrevidas.",
    ["I'm sure you have, but you know nothing of my kind."] = "Estoy seguro de que sí, pero no sabes nada de los de mi especie.",
    ["What do you mean by 'your kind'?"] = "¿Qué quieres decir con \"los de tu especie\"?",
    ["Come back to me when you befriend one of mine."] = "Vuelve a mí cuando te hagas amigo de uno de los míos.",
    ["Are you interested in buying or selling spice?"] = "¿Estás interesado en comprar o vender especias?",
    ["Urrgh, another one! Go away man-thing you no spooky."] = "¡Urrgh, otro! Vete, hombre, no tienes miedo.",
    ["Correct, I was just wondering what you are doing in this cave."] = "Correcto, me preguntaba qué estás haciendo en esta cueva.",
    ["Spicy Flower love cave, why Spicy Flower be anywhere else?"] = "Spicy Flower ama la cueva, ¿por qué Spicy Flower está en otro lugar?",
    ["You one of them zomboes? Not got no brains, me never liked them."] = "¿Eres uno de esos zombis? No tengo cerebro, nunca me gustaron.",
    ["No, I am very much alive."] = "No, estoy muy vivo.",
    ["Den what you doing here. You lost or somefing?"] = "¿Qué estás haciendo aquí? ¿Perdiste o algo así?",
    ["I'm here to slay some trolls!"] = "¡Estoy aquí para matar algunos trolls!",
    ["**Player:** I'm here to kill all these trolls!"] = "**Player:** ¡Estoy aquí para matar a todos estos trolls!",
    ["Thanks, you help make new troll spookies big and strong like Spicy Flower."] = "Gracias, ayudas a que los nuevos trolls espeluznantes sean grandes y fuertes como Spicy Flower.",
    ["No I..."] = "No, yo...",
    ["You good zomboe, me try not to eat you."] = "Buen zomboe, trato de no comerte.",
    ["**Player:** What is this place?"] = "**Player:** ¿Qué es este lugar?",
    ["This entrance to Trollgrav."] = "Esta entrada a Trollgrav.",
    ["What's Trollgrav?"] = "¿Qué es Trollgrav?",
    ["How you not know Trollgrav. Everyone know Trollgrav."] = "Cómo no conoces a Trollgrav. Todo el mundo conoce a Trollgrav.",
    ["Well I don't. What is it?"] = "Bueno, no lo sé. ¿Qué es?",
    ["It where all the strong troll spookies come."] = "Es de donde vienen todos los trolls espeluznantes fuertes.",
    ["If all the strong trolls go there, why aren't you in there?"] = "Si todos los trolls fuertes van allí, ¿por qué no estás tú?",
    ["I here to help the new spookies get big and strong so they can go to Trollgrav."] = "Estoy aquí para ayudar a los nuevos spookies a hacerse grandes y fuertes para que puedan ir a Trollgrav.",
    ["That and I on the look out for zomboes. You not zomboe are you?"] = "Eso y yo buscando zombis. No eres zombie, ¿verdad?",
    ["No, once again I am not a zombie."] = "No, una vez más no soy un zombie.",
    ["Why are you called Spicy Flower?"] = "¿Por qué te llamas Spicy Flower?",
    ["Why are you called Spicy Flower? That seems like an odd name."] = "¿Por qué te llamas Spicy Flower? Parece un nombre extraño.",
    ["First thing me eat was Spicy Flower."] = "Lo primero que comí fue Spicy Flower.",
    ["Me only troll that like Spicy Flower, so I eat as much as I like."] = "Yo solo trolleo a los que les gusta Spicy Flower, así que como todo lo que quiero.",
    ["Me miss spicy flowers, Spicy Flower has only stupid cave flowers here."] = "Extraño las flores picantes, Spicy Flower aquí solo tiene flores estúpidas de las cavernas.",
    ["Tell you wot, you bring me Spicy Flower, maybe I not smush you like bug."] = "Te digo una cosa, tráeme Spicy Flower, tal vez no te aplaste como a un insecto.",
    ["I'll get you some flowers."] = "Te traeré algunas flores.",
    ["Okay, what exactly are 'spicy flowers'?"] = "Bien, ¿qué son exactamente las 'flores picantes'?",
    ["You should know, it human food."] = "Debes saber que es alimento para humanos.",
    ["Well, humans eat a lot of different food. If it's human food, where did you get it from?"] = "Bueno, los humanos comemos muchos alimentos diferentes. Si es comida humana, ¿de dónde la sacaste?",
    ["We trolls trade for it off stinky humans. They come along looking for trolls shinies. We trolls not have shinies, so we just cook and eat them, keep their fings."] = "Los trolls lo intercambiamos con humanos apestosos. Vienen buscando trolls brillantes. Los trolls no tenemos brillos, así que simplemente los cocinamos y los comemos, conservando sus dedos.",
    ["I thought you said you traded for them?"] = "Pensé que habías dicho que habías cambiado por ellos.",
    ["We did trade. I just said we took his fings and ate him."] = "Intercambiamos. Sólo dije que le cogimos los dedos y nos lo comimos.",
    ["That's not trading. Trading is where you give someone something to get another thing in return."] = "Eso no es comercio. El trading es cuando le das algo a alguien para recibir otra cosa a cambio.",
    ["Spicy Flower do that all the time, but stupid to do with human, rather just eat dem, much less to work out."] = "Spicy Flower hace eso todo el tiempo, pero es una estupidez hacerlo con humanos, prefiere simplemente comerlos, y mucho menos hacer ejercicio.",
    ["We're getting side-tracked, I'll go find you a 'spicy flower'."] = "Nos estamos desviando, iré a buscarte un 'spicy flower'.",
    ["Spicy Flower so happy! You might change mind about zomboes."] = "¡Spicy Flower qué feliz! Quizás cambies de opinión sobre los zombis.",
    ["For Saradomin's sake! I'm not a zombie!"] = "¡Por el bien de Saradomin! ¡No soy un zombi!",
    ["How you know Seradoomin? Me thought only trolls know him."] = "¿Cómo conoces a Seradoomin? Pensé que sólo los trolls lo conocían.",
    ["Wait, how do you know Saradomin? It didn't seem like much of a troll topic."] = "Espera, ¿cómo conoces a Saradomin? No parecía un tema muy troll.",
    ["Wot you talking bout, he over at other end of cave helping train spookies."] = "¿De qué estás hablando? Él está en el otro extremo de la cueva ayudando a entrenar a los fantasmas.",
    ["I don't think I can do this anymore."] = "Creo que ya no puedo hacer esto.",
    ["Uhh... maybe later?"] = "Uhh... ¿tal vez más tarde?",
    ["Stinky human, me too sad to smush now."] = "Humano apestoso, estoy demasiado triste para aplastarme ahora.",
    ["**Player:** Goodbye."] = "**Player:** Adiós.",
    ["You come back soon Mr Zomboe. Bring tasties."] = "Vuelva pronto, Sr. Zomboe. Trae delicias.",
    ["Whatchu doin stoopid zomboe. Tryna put fings in Spicy face."] = "¿Qué estás haciendo con un zombi estúpido? Tryna le puso los dedos a la cara de Spicy.",
    ["I... Thought you might be hungry?"] = "Yo... ¿Pensé que podrías tener hambre?",
    ["Well I not, now go away."] = "Bueno, no, ahora vete.",
    ["You bring me spicy flower?"] = "¿Me traes spicy flower?",
    ["Can you tell me about the spicy flowers."] = "¿Puedes hablarme de las flores picantes?",
    ["We trolls trade for it off stinky humans."] = "Los trolls lo intercambiamos con humanos apestosos.",
    ["They come along looking for trolls shinies."] = "Vienen buscando trolls brillantes.",
    ["We trolls not have shinies, so we just cook and eat them, keep their fings."] = "Los trolls no tenemos brillos, así que simplemente los cocinamos y los comemos, conservando sus dedos.",
    ["I brought you a spicy flower."] = "Te traje un spicy flower.",
    ["I brought you a spicy flower, I... think."] = "Te traje un spicy flower, creo.",
    ["Give it 'ere den!"] = "¡Dámelo aquí!",
    ["What you doin' that not spicy flower!"] = "¡Qué estás haciendo que no sea spicy flower!",
    ["You found the spicy flower!"] = "¡Encontraste el spicy flower!",
    ["Me knew you were good zomboe."] = "Sabía que eras un buen zomboe.",
    ["Now give it 'ere."] = "Ahora dáselo aquí.",
    ["Well here goes nothing."] = "Bueno, aquí va nada.",
    ["You throw the nightshade into the ghost troll's mouth."] = "Lanzas la hierba mora en la boca del troll fantasma.",
    ["It passes straight through the troll."] = "Pasa directamente a través del troll.",
    ["Aww, me can't enjoy nuffin no more."] = "Aww, ya no puedo disfrutar más de Nuffin.",
    ["I'm sorry, is there anything I can do?"] = "Lo siento, ¿hay algo que pueda hacer?",
    ["No, no point."] = "No, no tiene sentido.",
    ["I... Guess I'll leave you to it."] = "Yo... Supongo que te dejo con eso.",
    ["Congratulations! You have completed: 'Fleur-de-lich' - Satiate Spicy Flower's appetite for spicy flowers."] = "¡Felicitaciones! Has completado: 'Fleur-de-lich' - Sacia el apetito de Spicy Flower por las flores especiadas.",
    ["Not sure me want to talk right now."] = "No estoy seguro de querer hablar ahora.",
    ["Hello, tree whisperer. I have been alone so long, but it is good to be part of the Anima Mundi once again."] = "Hola, susurrador de árboles. He estado solo mucho tiempo, pero es bueno ser parte de Anima Mundi una vez más.",
    ["I can hear my brethren clearly...but not all of them. I wonder, might you help reconnect me to them all?"] = "Puedo escuchar a mis hermanos claramente... pero no a todos. Me pregunto, ¿podrías ayudarme a reconectarme con todos ellos?",
    ["The tree to the south in the Poison Wastes sounds troubled."] = "El árbol al sur en Poison Wastes suena preocupado.",
    ["I cannot sense my brethren in Port Sarim."] = "No puedo sentir a mis hermanos en Port Sarim.",
    ["I cannot sense my brethren in Etceteria."] = "No puedo sentir a mis hermanos en Etceteria.",
    ["I cannot sense my brethren in Brimhaven."] = "No puedo sentir a mis hermanos en Brimhaven.",
    ["I cannot sense my brethren on Manor Farm."] = "No puedo sentir a mis hermanos en Manor Farm.",
    ["I feel my brethren in [location] is returning."] = "Siento que mis hermanos en [location] están regresando.",
    ["My brethren in [location] is close. Perhaps you should go see them."] = "Mis hermanos en [location] son cercanos. Quizás deberías ir a verlos.",
    ["If you could find a way to return these brethren to me, I would be most grateful. I've left a little reward with our gnome friend here should you manage this."] = "Si pudieras encontrar una manera de devolverme a estos hermanos, te estaría muy agradecido. Le dejé una pequeña recompensa a nuestro amigo gnomo si logras esto.",
    ["No...wait...I can hear them all again! Thank you, tree whisperer, thank you! I've asked our gnome friend here to reward you for your efforts."] = "No... espera... ¡Puedo escucharlos a todos otra vez! ¡Gracias, susurrador de árboles, gracias! Le pedí a nuestro amigo gnomo que te recompensara por tus esfuerzos.",
    ["**Spirit tree:** If you are a friend of the gnome people, you are a friend of mine. Do you wish to travel, or are you here to ask about the evil tree?"] = "**Spirit tree:** Si eres amigo del pueblo gnomo, eres amigo mío. ¿Quieres viajar o estás aquí para preguntar sobre el árbol del mal?",
    ["Travel."] = "Viajar.",
    ["You can travel to the trees related to me. Where do you wish to travel, whisperer?"] = "Puedes viajar a los árboles relacionados conmigo. ¿Adónde deseas viajar, susurrador?",
    ["*(Upon selecting a valid spirit tree:)*"] = "*(Al seleccionar un spirit tree válido:)*",
    ["You feel at one with the spirit tree."] = "Te sientes uno con el spirit tree.",
    ["Evil tree."] = "Árbol malvado.",
    ["The taint of the evil tree is not currently on the land. There won't be an evil tree for a long time."] = "La contaminación del árbol malvado no está actualmente en la tierra. No habrá un árbol malvado por mucho tiempo.",
    ["The taint of the evil tree is not currently on the land. There will be an evil tree in approximately [number] hour [number] minutes."] = "La contaminación del árbol malvado no está actualmente en la tierra. Habrá un árbol malvado en aproximadamente [número] hora [número] minutos.",
    ["I can help you find the where it will spawn, but my knowledge outside of the anima mundi is limited."] = "Puedo ayudarte a encontrar el lugar donde aparecerá, pero mi conocimiento fuera del anima mundi es limitado.",
    ["It can be found close to a [location] *(See Evil Tree#Locations with hints for list of locations)*."] = "Se puede encontrar cerca de [location] *(Ver Evil Tree#Ubicaciones con sugerencias para obtener una lista de ubicaciones)*.",
    ["What is this 'evil tree'?"] = "¿Qué es este 'árbol del mal'?",
    ["It is an abomination of nature that must be destroyed as quickly as possible. We do not know where it will appear, but, when it does, you should go to it immediately and help out!"] = "Es una abominación de la naturaleza que debe ser destruida lo más rápido posible. No sabemos dónde aparecerá, pero, cuando aparezca, ¡debes acudir inmediatamente y ayudar!",
    ["If you are a friend of the gnome people, you are a friend of mine. Do you wish to travel, or are you interested in the strange sapling?"] = "Si eres amigo del pueblo gnomo, eres amigo mío. ¿Quieres viajar o estás interesado en el extraño retoño?",
    ["Strange sapling."] = "Extraño retoño.",
    ["I can help you to find the strange sapling, but my knowledge outside of the anima mundi is limited."] = "Puedo ayudarte a encontrar el extraño retoño, pero mi conocimiento fuera del anima mundi es limitado.",
    ["It can be found at [location] *(See Evil Tree#Locations with hints for list of locations)*."] = "Se puede encontrar en [location] *(Ver Evil Tree#Locations con sugerencias para una lista de ubicaciones)*.",
    ["If you are a friend of the gnome people, you are a friend of mine. Do you wish to travel, or are you here to help dispatch the evil tree?"] = "Si eres amigo del pueblo gnomo, eres amigo mío. ¿Quieres viajar o estás aquí para ayudar a acabar con el árbol malvado?",
    ["**Spirit tree:** Would you like me to teleport you directly there?"] = "**Spirit tree:** ¿Quieres que te teletransporte directamente allí?",
    ["It is an abomination of nature, which has appeared at [location]*(See Evil Tree#Locations with hints for list of locations)*. You should go there immediately to help out!"] = "Es una abominación de la naturaleza, que ha aparecido en [location]*(Ver Evil Tree#Locations con sugerencias para una lista de ubicaciones)*. ¡Deberías ir allí inmediatamente para ayudar!",
    ["I've changed my mind, I want to stay here."] = "He cambiado de opinión, quiero quedarme aquí.",
    ["You will offer 100 spirit shards in exchange for a temporary pouch-infusion speed boost. Do you wish to continue?"] = "Ofrecerás 100 fragmentos de espíritu a cambio de un aumento temporal de la velocidad de infusión de la bolsa. ¿Quieres continuar?",
    ["Don't show this again"] = "No volver a mostrar esto",
    ["You offer 100 spirit shards to the spirit. This communion strengthens your spirit plane connection and grants you the ability to infuse pouches more quickly for a while."] = "Ofreces 100 fragmentos de espíritu al espíritu. Esta comunión fortalece la conexión de tu plano espiritual y te otorga la capacidad de infundir bolsas más rápidamente durante un tiempo.",
    ["You need 100 spirit shards to commune with the spirit."] = "Necesitas 100 fragmentos de espíritu para comunicarte con el espíritu.",
    ["Greetings, One who is not Chosen."] = "Saludos, Uno que no es Elegido.",
    ["Not Chosen?"] = "¿No has sido elegido?",
    ["I am the Spirit of the Kingdom of Asgarnia. I guard the Banner that symbolises the kingdom's first founding."] = "Soy el Spirit del Reino de Asgarnia. Guardo el estandarte que simboliza la primera fundación del reino.",
    ["The Banner! That's what I've been searching for!"] = "¡El estandarte! ¡Eso es lo que he estado buscando!",
    ["When the Chosen One comes, she will take up the Banner and lead Falador and Asgarnia to its destiny."] = "Cuando llegue el Elegido, ella tomará el Estandarte y guiará a Falador y Asgarnia a su destino.",
    ["I can do that, if you let me have that banner."] = "Puedo hacer eso, si me dejas tener ese banner.",
    ["No. Sorry, but there is too much else you need to do."] = "No. Lo siento, pero hay mucho más que debes hacer.",
    ["You have no time to be King/Queen of a single kingdom with its daily bureaucracy and its constant demands."] = "No tienes tiempo para ser Rey/Reina de un solo reino con su burocracia diaria y sus constantes exigencias.",
    ["You are not the Chosen One."] = "Tú no eres el Elegido.",
    ["After all I've done to find this Banner...?"] = "¿Después de todo lo que he hecho para encontrar este Banner...?",
    ["Yet I see you being influential in this kingdom's future, nonetheless."] = "Sin embargo, veo que eres influyente en el futuro de este reino.",
    ["As such, though I cannot allow you to take the true Banner, I can give you its blessing, and let you bear its resemblance..."] = "Como tal, aunque no puedo permitirte tomar el verdadero Estandarte, puedo darte su bendición y permitirte llevar su parecido...",
    ["Wow, that tingles. Wait, I have questions...!"] = "Vaya, eso me hormiguea. Espera, ¡tengo preguntas...!",
    ["...goodbye, adventurer..."] = "...adiós, aventurero...",
    ["[This powerful spirit seems capable of speaking to you even though you are not wearing an Amulet of Ghostspeak.]"] = "[Este poderoso espíritu parece capaz de hablarte aunque no lleves puesto un Amuleto de Hablafantasma.]",
    ["Who treads upon my grave?"] = "¿Quién pisa mi tumba?",
    ["I seek your wisdom."] = "Busco tu sabiduría.",
    ["Indeed, I feel you have beheld the far places in the heavens."] = "De hecho, siento que has contemplado los lugares lejanos de los cielos.",
    ["Congratulations! You have completed: 'Unholy Crafting' - Unlock the ability to craft unholy symbols."] = "¡Felicitaciones! Has completado: 'Unholy Crafting': desbloquea la capacidad de crear símbolos impíos.",
    ["Here is a mould to make a token for our Lord; a mould for the unholy symbol of Zamorak. Return to me when you desire my blessing./My Lord instructs me to help you. I see you have a mould for the unholy symbol of our Lord. Come to me when you desire my blessing."] = "Aquí tenéis un molde para hacer una ficha para nuestro Señor; un molde para el símbolo impío de Zamorak. Vuelve a mí cuando desees mi bendición./Mi Señor me ordena que te ayude. Veo que tienes un molde para el símbolo impío de nuestro Señor. Ven a mí cuando desees mi bendición.",
    ["I have come to seek a blessing."] = "He venido a buscar una bendición.",
    ["No blessings will be given to those who have no symbol of our Lord's love."] = "No se darán bendiciones a aquellos que no tengan un símbolo del amor de nuestro Señor.",
    ["I see you have the unholy symbol of our Lord. I will bless it for you."] = "Veo que tienes el símbolo impío de nuestro Señor. Yo te lo bendeciré.",
    ["[The ghost mutters in a strange voice. The unholy symbol throbs with power.]"] = "[El fantasma murmura con una voz extraña. El símbolo impío palpita de poder.]",
    ["The symbol of our Lord has been blessed with power!"] = "¡El símbolo de nuestro Señor ha sido bendecido con poder!",
    ["My master calls."] = "Mi maestro llama.",
    ["I see you have the unholy symbol of our Lord. It is blessed with the Lord Zamorak's power."] = "Veo que tienes el símbolo impío de nuestro Señor. Está bendecido con el poder del Señor Zamorak.",
    ["Come to me when your faith weakens."] = "Ven a mí cuando tu fe se debilite.",
    ["I need another unholy symbol mould."] = "Necesito otro molde de símbolo impío.",
    ["I need another mould for the unholy symbol."] = "Necesito otro molde para el símbolo impío.",
    ["The ghost hands you another mould."] = "El fantasma te entrega otro molde.",
    ["A lost object is easy to replace. The loss of the affections of our Lord is impossible to forgive."] = "Un objeto perdido es fácil de reemplazar. La pérdida del afecto de nuestro Señor es imposible de perdonar.",
    ["One you already have, another is not needed. Leave me be."] = "Uno ya lo tienes, otro no es necesario. Déjame en paz.",
    ["I have come to kill you."] = "He venido a matarte.",
    ["The might of mortals, to me, is as the dust to the sea."] = "Para mí, el poder de los mortales es como el polvo del mar.",
    ["Thank you, tree whisperer. My brethren tell me that, in the past, you have had to travel back to our paternal tree before choosing your destination; however, your deeds have enhanced your attunement to the anima mundi and"] = "Gracias, susurrador de árboles. Me cuentan mis hermanos que, en el pasado, habéis tenido que viajar de regreso a nuestro árbol paterno antes de elegir vuestro destino; sin embargo, tus acciones han mejorado tu sintonía con el anima mundi y",
    ["there is no more need for this. You may now travel freely between all of my brethren."] = "Ya no hay necesidad de esto. Ahora podéis viajar libremente entre todos mis hermanos.",
    ["If you are a friend of the gnome people, you are a friend of mine. Do you wish to travel, or are you here to ask about the evil tree?"] = "Si eres amigo del pueblo gnomo, eres amigo mío. ¿Quieres viajar o estás aquí para preguntar sobre el árbol del mal?",
    ["The tree doesn't feel like talking."] = "El árbol no tiene ganas de hablar.",
    ["You must have completed Tree Gnome Village to do this."] = "Debes haber completado Tree Gnome Village para hacer esto.",
    ["Category:Scenery transcripts"] = "Categoría: Transcripciones de paisajes",
    ["What? Do I have something on my face?"] = "¿Qué? ¿Tengo algo en la cara?",
    ["Woo wooo woo."] = "Woo, woo, woo.",
    ["You...you are decorated in flesh!"] = "Tú... ¡estás decorado en carne!",
    ["I guess I am."] = "Supongo que sí.",
    ["Just don't let them take it from you."] = "No dejes que te lo quiten.",
    ["I promised I would never leave his side. Then they froze me and I could no longer keep up."] = "Prometí que nunca me alejaría de su lado. Luego me congelaron y ya no pude seguir el ritmo.",
    ["Umm...that doesn't really answer the question. Who are you?"] = "Umm... eso realmente no responde la pregunta. ¿Quién eres?",
    ["Did you come to give me your flesh?"] = "¿Viniste a darme tu carne?",
    ["No, I just want to know who you are."] = "No, solo quiero saber quién eres.",
    ["They called me something. It may have been Lamel. Or Urgand."] = "Me llamaron de alguna manera. Pudo haber sido Lamel. O Urgand.",
    ["You don't even remember your name?"] = "¿Ni siquiera recuerdas tu nombre?",
    ["My name is an importance of the past and no longer a burden I must carry with me."] = "Mi nombre es una importancia del pasado y ya no es una carga que debo llevar conmigo.",
    ["How long have you been here?"] = "¿Cuánto tiempo llevas aquí?",
    ["Since shortly before red and blue were rudely interrupted by green."] = "Desde poco antes el rojo y el azul fueron bruscamente interrumpidos por el verde.",
    ["Hmm. I see."] = "Mmm. Veo.",
    ["Can Lemal or Dnagru share more of his knowledge with you, flesh dancer?"] = "¿Pueden Lemal o Dnagru compartir más conocimientos contigo, bailarín de carne?",
    ["When were red and blue interrupted?"] = "¿Cuándo se interrumpieron el rojo y el azul?",
    ["At some point in the afternoon. Before the arrows but after the demons."] = "En algún momento de la tarde. Antes de las flechas pero después de los demonios.",
    ["Eh...I mean...at what point in time?"] = "Eh... quiero decir... ¿en qué momento?",
    ["It was the third in a row, around the nights of 4,000 glowing eyes. It had already been born from pain, but I was late."] = "Fue el tercero consecutivo, alrededor de las noches de 4.000 ojos brillantes. Ya había nacido del dolor, pero llegué tarde.",
    ["Oh, when you put it that way..."] = "Oh, cuando lo pones de esa manera...",
    ["Was that the end of your dance?"] = "¿Ese fue el final de tu baile?",
    ["Yes, that was it."] = "Sí, eso fue todo.",
    ["Okay, I'm leaving now."] = "Está bien, ya me voy.",
    ["The sword had sought its new home and my time in flesh was over. Demons laughed and angels wept. I froze but my lord moved, and I was left in the presence of pain."] = "La espada había buscado su nuevo hogar y mi tiempo en la carne había terminado. Los demonios reían y los ángeles lloraban. Me quedé helado pero mi señor se movió y quedé en presencia del dolor.",
    ["I take it you died?"] = "¿Supongo que moriste?",
    ["Haha. Your dance entertains Gnameall."] = "Jaja. Tu baile entretiene a Gnameall.",
    ["Is that a yes?"] = "¿Es un sí?",
    ["As truly as the western lands fell. But I have not strayed from his red path. No, I have been careful."] = "Tan cierto como cayeron las tierras occidentales. Pero no me he desviado de su camino rojo. No, he tenido cuidado.",
    ["Whose path?"] = "¿El camino de quién?",
    ["The red Rokazma, of course. No, Ludgem has not followed the path of men. Mokazra was a beacon of war as well as a searching light. Oh, how he searched. The light got weaker so Lamreg lit a candle of his own. But Tighux put his fist down and demons as well as angels flew!"] = "El Rokazma rojo, por supuesto. No, Ludgem no ha seguido el camino de los hombres. Mokazra fue un faro de guerra y también una luz de búsqueda. Oh, cómo buscó. La luz se debilitó y Lamreg encendió su propia vela. ¡Pero Tighux bajó el puño y tanto los demonios como los ángeles volaron!",
    ["Who did what now?"] = "¿Quién hizo qué ahora?",
    ["One said right, one said left. The paths crossed, and there was middle. The struggle shone with the light of living eyes! But they grew bleak, withered, and died."] = "Uno dijo derecha, el otro dijo izquierda. Los caminos se cruzaron y hubo un punto medio. ¡La lucha brilló con la luz de ojos vivos! Pero se debilitaron, se marchitaron y murieron.",
    ["Who died?"] = "¿Quién murió?",
    ["Many of us. But we had to. We were insignificant in their reflections - nothing but a second of necessary suffering for their benefit. Leaves will fall from the trees, but the mountains remain. But then he awoke and disrupted it all!"] = "Muchos de nosotros. Pero teníamos que hacerlo. Éramos insignificantes en sus reflexiones: nada más que un segundo de sufrimiento necesario para su beneficio. Las hojas caerán de los árboles, pero las montañas permanecerán. ¡Pero entonces despertó y lo trastocó todo!",
    ["Who woke up?"] = "¿Quién despertó?",
    ["Green! The red path had fallen in the shadow of blue wings, but all knew what had to be done! The crossroads would be intertwined into one and the struggle would cease!"] = "¡Verde! El camino rojo había caído en la sombra de unas alas azules, ¡pero todos sabían lo que había que hacer! ¡Las encrucijadas se entrelazarían en una sola y la lucha cesaría!",
    ["And that's when green woke up?"] = "¿Y fue entonces cuando Green despertó?",
    ["Yes! It mixed and all was white. The crossroad chose no path, it became a wall. The bright light blinds whoever comes too close, and everyone crashes into the wall, unable to get away! And only because of green...only because it would not see a leaf be pulled from the tree, but instead fall to the ground and slowly rot. It did nothing good for anyone involved. The light must continue to flow, but the bearer of the prism is nowhere to be seen, not with the start of the tail taken away. If only it had let us end it the only true way... Now dance, you disguised in the flesh of past times. Garel must rest."] = "¡Sí! Se mezcló y todo quedó blanco. El cruce no eligió camino, se convirtió en un muro. La luz brillante ciega a quien se acerca demasiado y todos chocan contra la pared, ¡sin poder escapar! Y sólo por el verde... sólo porque no vería arrancar una hoja del árbol, sino que caería al suelo y se pudriría lentamente. No hizo nada bueno para ninguno de los involucrados. La luz debe continuar fluyendo, pero el portador del prisma no se ve por ningún lado, no con el comienzo de la cola quitado. Si tan solo nos hubiera permitido terminarlo de la única manera verdadera... Ahora baila, disfrazada en la carne de tiempos pasados. Garel debe descansar.",
    ["That's a shame."] = "Es una pena.",
    ["What did he search for?"] = "¿Qué buscó?",
    ["Shh! It's a secret! So secret that not even the candles knew. But they would look, and they would guess, and red faded to darkness and extinguished the candles of failure. But the red beacon was not alone in its flicker. No, all lights mimicked the one that came before. They took turns being the glowing eye, and now the eye was blue."] = "¡Shh! ¡Es un secreto! Tan secreto que ni las velas lo sabían. Pero miraban y adivinaban, y el rojo se desvanecía en la oscuridad y apagaba las velas del fracaso. Pero la baliza roja no estaba sola en su parpadeo. No, todas las luces imitaban la anterior. Se turnaron para ser el ojo brillante y ahora el ojo era azul.",
    ["But that's when Hugixt took it away!"] = "¡Pero fue entonces cuando Hugixt se lo quitó!",
    ["Thanks, I won't."] = "Gracias, no lo haré.",
    ["The flesh has returned to me again."] = "La carne ha vuelto a mí otra vez.",
    ["That smells nice!"] = "¡Eso huele bien!",
    ["Mmm, yes. Some hunters caught it earlier today."] = "Mmmm, sí. Algunos cazadores lo capturaron hoy.",
    ["Can I have some?"] = "¿Me das un poco?",
    ["Oh, it's not cooked yet. But they sell frogburgers in the market!"] = "Oh, aún no está cocido. ¡Pero venden hamburguesas de rana en el mercado!",
    ["Ah, Player; what can I do for you?"] = "Ah, Player; ¿Qué puedo hacer por ti?",
    ["I need another assignment."] = "Necesito otra tarea.",
    ["I'm here about blessed hatchets again."] = "Estoy aquí otra vez por las benditas hachas.",
    ["I am here to discuss any rewards I might be eligible for."] = "Estoy aquí para discutir cualquier recompensa para la que pueda ser elegible.",
    ["So you're here instead of Turael?"] = "¿Entonces estás aquí en lugar de Turael?",
    ["Yes... I have something written down here somewhere..."] = "Sí... Tengo algo escrito aquí en alguna parte...",
    ["You can find chickens near the flax field on the west side of the river."] = "Puedes encontrar gallinas cerca del campo de lino en el lado oeste del río.",
    ["Wolves are pack animals, so you'll always find them in groups. Watch out for their bite, it can be nasty. There are plenty to kill on White Wolf Mountain."] = "Los lobos son animales de manada, por lo que siempre los encontrarás en grupos. Cuidado con su picadura, puede ser desagradable. Hay mucho que matar en White Wolf Mountain.",
    ["Cows are bigger than you, and they'll often hit hard but react fairly slowly. You can slaughter the ones in Lumbridge - I bet they are up to no good."] = "Las vacas son más grandes que tú y, a menudo, golpean fuerte pero reaccionan con bastante lentitud. Puedes masacrar a los de Lumbridge. Apuesto a que no traman nada bueno.",
    ["The crawling hands are found in the northern parts of the enchanted cave under the lake, to the south-east of here."] = "Las manos que se arrastran se encuentran en la parte norte de la cueva encantada debajo del lago, al sureste de aquí.",
    ["The last Crawling hand I killed I found fire spells took them down effectively."] = "La última mano reptante que maté descubrí que los hechizos de fuego los derribaron de manera efectiva.",
    ["The gelatinous abominations are found in the enchanted cave under the lake, to the south-east of here."] = "Las abominaciones gelatinosas se encuentran en la cueva encantada debajo del lago, al sureste de aquí.",
    ["They can only be beaten by bursting this core wearing spiked gauntlets, once you have damaged them enough."] = "Solo se les puede derrotar explotando este núcleo usando guanteletes con púas, una vez que los hayas dañado lo suficiente.",
    ["The last Gelatinous abomination I killed I found a bow and arrows took them down effectively."] = "La última abominación gelatinosa que maté encontré un arco y las flechas los derribaron de manera efectiva.",
    ["There are a lot of trolls wandering this area. The cave to the north-west of the castle is crawling with them."] = "Hay muchos trolls deambulando por esta zona. La cueva al noroeste del castillo está repleta de ellos.",
    ["You can find juvenile wolves if you go south-west to White Wolf Mountain."] = "Puedes encontrar lobos jóvenes si vas al suroeste hasta White Wolf Mountain.",
    ["The last Wolf I killed I found water spells took them down effectively."] = "Descubrí que el último lobo que maté los hechizos de agua los derribaron de manera efectiva.",
    ["You discover a memory that contains a sealed clue scroll ([tier])."] = "Descubres un recuerdo que contiene un pergamino de pistas sellado ([tier]).",
    ["[Earn the Flower Sprout aura override, and the recolourable Spring Picnic outfit, by taking part in the Hunt for the Golden Eggs! Speak to Nougat Bunny in the Blooming Burrow to find out more.]"] = "[¡Consigue la anulación del aura de Brote de flores y el traje de picnic de primavera recolorable participando en la Búsqueda de los huevos de oro! Habla con Nougat Bunny en Blooming Burrow para obtener más información.]",
    [";When cleaning an item"] = ";Al limpiar un artículo",
    ["EXTERMINATE!<ref>A reference to Daleks from **</ref>"] = "¡EXTERMINAR!<ref>A referencia a Daleks de **</ref>",
    ["Everybody's dead [Player]<ref>A reference to **</ref>"] = "Todo el mundo está muerto [Player]<ref>A referencia a **</ref>",
    ["You know, its times like these that I realise what a superhero I am.<ref>A reference to **</ref>"] = "Ya sabes, en momentos como estos me doy cuenta de lo superhéroe que soy.<ref>A referencia a **</ref>",
    ["Spring Cleaner: Omnomnom.<ref>A reference to Heavy from **</ref>"] = "Spring Cleaner: Omnomnom.<ref>A referencia a Heavy de **</ref>",
    ["You know, I've always wondered what that thing was made of, now I know."] = "Sabes, siempre me he preguntado de qué estaba hecha esa cosa, ahora lo sé.",
    ["Cake and grief counselling will be available at the conclusion of your next slayer task<ref>A reference to GLaDOS from **</ref>"] = "El asesoramiento sobre pasteles y duelo estará disponible al finalizar tu próxima tarea de asesino<ref>A referencia a GLaDOS de **</ref>",
    ["Does not compute.<ref>A catchphrase from * My Living Doll* and *Lost in Space*</ref>"] = "No calcula.<ref>A eslogan de * My Living Doll* y *Lost in Space*</ref>",
    ["Ah well, you didn't need it anyway."] = "Ah, bueno, no lo necesitabas de todos modos.",
    ["I'm sorry [Player], I'm afraid I can't do that.<ref>A reference to HAL 9000 from **</ref>"] = "Lo siento [Player], me temo que no puedo hacer eso.<ref>A referencia a HAL 9000 de **</ref>",
    [";When disassembling an item"] = ";Al desmontar un artículo",
    ["Seems to be a lot of things made of pure junk in this world."] = "Parece haber muchas cosas hechas de pura basura en este mundo.",
    ["YES DISASSEMBLE!"] = "¡SI DESMONTAR!",
    [";When adding to pocket"] = ";Al agregar al bolsillo",
    ["Where are we going? If it was bad you'd tell me, right?"] = "¿A dónde vamos? Si fuera malo me lo dirías ¿no?",
    ["Would you like to play a game?<ref>Possibly an allusion to Joshua, in *Wargames*</ref>"] = "¿Te gustaría jugar un juego?<ref>Posiblemente una alusión a Joshua, en *Wargames*</ref>",
    [";When changing modes"] = ";Al cambiar de modo",
    ["No disassemble Spring Cleaner!<ref>A reference to Number 5 from **</ref>"] = "No desarmar Spring Cleaner!<ref>A referencia al número 5 de **</ref>",
    ["I feel smarter already.<ref>Possible reference to Postal Dude from **</ref>"] = "Ya me siento más inteligente.<ref>Posible referencia a Postal Dude de **</ref>",
    [";When unchecking the mute option"] = ";Al desmarcar la opción de silencio",
    ["I knew you couldn't resist hearing me talk!"] = "¡Sabía que no podrías resistirte a escucharme hablar!",
    ["Hey Spring Cleaner."] = "Hola Spring Cleaner.",
    ["Hey [Player], did you know... BEHIND YOU, LOOK OUT!"] = "Hola [Player], ¿sabías que... DETRÁS DE TI, CUIDADO!",
    ["Haha, made you look!"] = "Jaja, ¡te hizo lucir!",
    ["Hey Spring Cleaner tell me something interesting."] = "Hola Spring Cleaner, cuéntame algo interesante.",
    ["72.1% of statistics are made up."] = "El 72,1% de las estadísticas están compuestas.",
    [":::*or*"] = ":::*o*",
    ["The chances of getting a dragon pickaxe on your next Chaos Dwarf kill is 5000 to 1."] = "Las posibilidades de conseguir un pico de dragón en tu próxima muerte de Enano del Caos son de 5000 a 1.",
    ["Hey Spring Cleaner tell me something funny."] = "Hola Spring Cleaner, cuéntame algo gracioso.",
    ["I got scammed by someone the other day, you could say he cleaned me out."] = "Alguien me estafó el otro día, se podría decir que me limpió.",
    [":*No dialogue*"] = ":*Sin diálogo*",
    ["Hssssssss..."] = "Hsssssss...",
    ["Skkskskksk..."] = "Skksksksk...",
    ["Squick gives you a taijitu in thanks for the rescue."] = "Squick te regala un taijitu en agradecimiento por el rescate.",
    ["Er, you're a squid. How exactly are you stranded?"] = "Er, eres un calamar. ¿Cómo exactamente estás varado?",
    ["Not swim."] = "No nadar.",
    ["You can't swim? You do realize you're a FLYING squid, right?"] = "¿No sabes nadar? Te das cuenta de que eres un calamar VOLADOR, ¿verdad?",
    ["Oh, yeah! I forgot. Dur."] = "¡Oh, sí! Me olvidé. Dur.",
    ["So, you don't need me to rescue you."] = "Entonces, no necesitas que te rescate.",
    ["Yeah, do. Lost confidence. Not fly water."] = "Sí, hazlo. Confianza perdida. No agua con mosca.",
    ["You're a flying squid that's afraid to fly over water?"] = "¿Eres un calamar volador que tiene miedo de volar sobre el agua?",
    ["Scary ship. Black and spiky. Harbinger."] = "Barco aterrador. Negro y puntiagudo. Heraldo.",
    ["Also not like wet. Make me ink."] = "Tampoco me gusta estar mojado. Hazme tinta.",
    ["I hate to break it to you, but you're already wet."] = "Odio decírtelo, pero ya estás mojado.",
    ["Get off it! No wet! Hate wet! No make wet!"] = "¡Déjalo! ¡No mojado! ¡Odio mojado! ¡No mojar!",
    ["I ink self! I ink you! Ink your face!"] = "¡Me entinto yo mismo! ¡Te entinto! ¡Entinta tu cara!",
    ["Fine, fine! Just calm down. I'll take you on my boat."] = "¡Bien, bien! Sólo cálmate. Te llevaré en mi barco.",
    ["Go home! Yay!"] = "¡Vete a casa! ¡Hurra!",
    ["Where is home?"] = "¿Dónde está tu casa?",
    ["Nishi? Where's Nishi?"] = "¿Nishi? ¿Dónde está Nishi?",
    ["Oh, you do you mean Aminishi?"] = "Oh, ¿te refieres a Aminishi?",
    ["Nishi!"] = "¡Nishi!",
    ["Okay, let's go find your parents."] = "Está bien, vayamos a buscar a tus padres.",
    ["AM parent! Not kiddie! You rude."] = "¡SOY padre! ¡No niño! Eres grosero.",
    ["** Squire (Intermediate): ** Hi, how can I help you?"] = "** Squire (Intermedio): ** Hola, ¿en qué puedo ayudarte?",
    ["Select An Option *"] = "*Seleccione una opción*",
    ["** Squire (Intermediate): ** I'm a Squire for the Void Knights."] = "** Squire (Intermedio): ** Soy un Squire de los Void Knights.",
    ["** Player: ** The who?"] = "** Player: ** ¿El quién?",
    ["** Squire (Intermediate): ** The Void Knights, they are great warriors of balance who do Guthix's work here in Gielinor."] = "** Squire (Intermedio): ** Los Void Knights, son grandes guerreros del equilibrio que hacen el trabajo de Guthix aquí en Gielinor.",
    ["Wow, can I join?"] = "Vaya, ¿puedo unirme?",
    ["** Squire (Intermediate): ** Entry is strictly invite only, however we do need help continuing Guthix's work."] = "** Squire (Intermedio): ** La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
    ["What kind of work?"] = "¿Qué tipo de trabajo?",
    ["** Squire (Intermediate): ** Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "** Squire (Intermedio): ** Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
    ["What's the problem?"] = "¿Cuál es el problema?",
    ["** Squire (Intermediate): ** Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "** Squire (Intermedio): ** Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo para aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["** Squire (Intermediate): ** We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "** Squire (Intermedio): ** Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
    ["Sorry, but I can't."] = "Lo siento, pero no puedo.",
    ["What's 'Gielinor'?"] = "¿Qué es 'Gielinor'?",
    ["** Squire (Intermediate): ** It is the name that Guthix gave to this world, so we honour him with its use."] = "**Squire (Intermedio): **Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
    ["I'd rather not, sorry."] = "Preferiría no hacerlo, lo siento.",
    ["Uh huh, sure."] = "Ajá, claro.",
    ["** Player: ** Who are you?"] = "** Player: ** ¿Quién eres?",
    ["** Squire (Novice): ** I'm a Void Knight squire, my lord."] = "** Squire (Novicio): ** Soy un escudero de Void Knight, mi señor.",
    ["** Player: ** So I see. Well, keep up the good work."] = "** Player: ** Ya veo. Bueno, sigue con el buen trabajo.",
    ["** Squire (Intermediate): ** This is where we launch our landers to combat the invasion of the nearby islands. You'll see three landers - one for novice, intermediate and veteran adventurers. Each has a different difficulty, but they therefore offer varying rewards."] = "** Squire (Intermedio): ** Aquí es donde lanzamos nuestros módulos de aterrizaje para combatir la invasión de las islas cercanas. Verás tres módulos de aterrizaje: uno para aventureros novatos, intermedios y veteranos. Cada uno tiene una dificultad diferente, pero por lo tanto ofrecen diferentes recompensas.",
    ["** Player: ** And this lander is...?"] = "** Player: ** ¿Y este módulo de aterrizaje es...?",
    ["** Squire (Intermediate): ** The intermediate."] = "** Squire (Intermedio): ** El intermedio.",
    ["** Player: ** So how do they work?"] = "** Player: ** Entonces, ¿cómo funcionan?",
    ["** Squire (Intermediate): ** Simple. We send a lander out every three minutes, however we need at least five volunteers or it's a suicide mission. The lander can only hold a maximum of twenty five people though, so we do send them out early if they get full. If you'd be willing to help us then just wait in the lander and we'll launch it as soon as it's ready. However you will need a combat level of 70 to use this lander."] = "** Squire (Intermedio): ** Sencillo. Enviamos un módulo de aterrizaje cada tres minutos, pero necesitamos al menos cinco voluntarios o será una misión suicida. Sin embargo, el módulo de aterrizaje solo puede albergar a un máximo de veinticinco personas, por lo que los enviamos temprano si se llenan. Si está dispuesto a ayudarnos, espere en el módulo de aterrizaje y lo lanzaremos tan pronto como esté listo. Sin embargo, necesitarás un nivel de combate de 70 para utilizar este módulo de aterrizaje.",
    ["I'm fine thanks."] = "Estoy bien, gracias.",
    ["** Player: ** I'm fine thanks."] = "** Player: ** Estoy bien gracias.",
    ["** Squire (Novice): ** Hi, how can I help you?"] = "** Squire (novato): ** Hola, ¿en qué puedo ayudarte?",
    ["** Squire (Novice): ** I'm a Squire for the Void Knights."] = "** Squire (novato): ** Soy un Squire de los Void Knights.",
    ["** Squire (Novice): ** The Void Knights, they are great warriors of balance who do Guthix's work here in Gielinor."] = "** Squire (novato): ** Los Void Knights, son grandes guerreros del equilibrio que hacen el trabajo de Guthix aquí en Gielinor.",
    ["** Squire (Novice): ** Entry is strictly invite only, however we do need help continuing Guthix's work."] = "** Squire (novato): ** La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
    ["** Squire (Novice): ** Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "** Squire (novato): ** Ah, bueno, verás que intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
    ["** Squire (Novice): ** Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "** Squire (Novato): ** Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo para aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["** Squire (Novice): ** We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "** Squire (novato): ** Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
    ["** Squire (Novice): ** It is the name that Guthix gave to this world, so we honour him with its use."] = "**Squire (Novicio): **Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
    ["** Squire (Novice): ** This is where we launch our landers to combat the invasion of the nearby islands. You'll see three landers - one for novice, intermediate and veteran adventurers. Each has a different difficulty, but they therefore offer varying rewards."] = "** Squire (Novato): ** Aquí es donde lanzamos nuestros módulos de aterrizaje para combatir la invasión de las islas cercanas. Verás tres módulos de aterrizaje: uno para aventureros novatos, intermedios y veteranos. Cada uno tiene una dificultad diferente, pero por lo tanto ofrecen diferentes recompensas.",
    ["** Squire (Novice): ** The novice."] = "** Squire (Novicio): ** El novato.",
    ["** Squire (Novice): ** Simple. We send a lander out every three minutes, however we need at least five volunteers or it's a suicide mission. The lander can only hold a maximum of twenty five people though, so we do send them out early if they get full. If you'd be willing to help us then just wait in the lander and we'll launch it as soon as it's ready. However you will need a combat level of 35 to use this lander."] = "** Squire (novato): ** Sencillo. Enviamos un módulo de aterrizaje cada tres minutos, pero necesitamos al menos cinco voluntarios o será una misión suicida. Sin embargo, el módulo de aterrizaje solo puede albergar a un máximo de veinticinco personas, por lo que los enviamos temprano si se llenan. Si está dispuesto a ayudarnos, espere en el módulo de aterrizaje y lo lanzaremos tan pronto como esté listo. Sin embargo, necesitarás un nivel de combate de 35 para utilizar este módulo de aterrizaje.",
    ["** Squire (Veteran): ** Hi, how can I help you?"] = "** Squire (Veterano): ** Hola, ¿en qué puedo ayudarte?",
    ["** Squire (Veteran): ** I'm a Squire for the Void Knights."] = "** Squire (Veterano): ** Soy un Squire de los Void Knights.",
    ["** Squire (Veteran): ** The Void Knights, they are great warriors of balance who do Guthix's work here in Gielinor."] = "** Squire (Veterano): ** Los Void Knights, son grandes guerreros del equilibrio que hacen el trabajo de Guthix aquí en Gielinor.",
    ["** Squire (Veteran): ** Entry is strictly invite only, however we do need help continuing Guthix's work."] = "** Squire (Veterano): ** La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
    ["** Squire (Veteran): ** Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "** Squire (Veterano): ** Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
    ["** Squire (Veteran): ** Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "** Squire (Veterano): ** Bueno, el orden ha disminuido bastante con los años, es un proceso muy largo para aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y han estado entrando extrañas criaturas. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["** Squire (Veteran): ** We send launchers from our outpost to the nearby islands. If you go and wait in the lander there that'd really help."] = "** Squire (Veterano): ** Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas en el módulo de aterrizaje, eso sería de gran ayuda.",
    ["** Squire (Veteran): ** It is the name that Guthix gave to this world, so we honour him with its use."] = "**Squire (Veterano): **Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
    ["** Squire (Veteran): ** This is where we launch our landers to combat the invasion of the nearby islands. You'll see three landers - one for novice, intermediate and veteran adventurers. Each has a different difficulty, but they therefore offer varying rewards."] = "** Squire (Veterano): ** Aquí es donde lanzamos nuestros módulos de aterrizaje para combatir la invasión de las islas cercanas. Verás tres módulos de aterrizaje: uno para aventureros novatos, intermedios y veteranos. Cada uno tiene una dificultad diferente, pero por lo tanto ofrecen diferentes recompensas.",
    ["** Squire (Veteran): ** The veteran."] = "** Squire (Veterano): ** El veterano.",
    ["** Squire (Veteran): ** Simple. We send a lander out every three minutes, however we need at least five volunteers or it's a suicide mission. The lander can only hold a maximum of twenty five people though, so we do send them out early if they get full. If you'd be willing to help us then just wait in the lander and we'll launch it as soon as it's ready. However you will need a combat level of 100 to use this lander."] = "** Squire (Veterano): ** Sencillo. Enviamos un módulo de aterrizaje cada tres minutos, pero necesitamos al menos cinco voluntarios o será una misión suicida. Sin embargo, el módulo de aterrizaje solo puede albergar a un máximo de veinticinco personas, por lo que los enviamos temprano si se llenan. Si está dispuesto a ayudarnos, espere en el módulo de aterrizaje y lo lanzaremos tan pronto como esté listo. Sin embargo, necesitarás un nivel de combate de 100 para utilizar este módulo de aterrizaje.",
    ["*When talking to the Squire in the Archery store on Void Knight Outpost.*"] = "*Al hablar con Squire en la tienda Archery en Void Knight Outpost.*",
    ["Hi, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
    ["What do you have for sale?"] = "¿Qué tienes a la venta?",
    ["I'm fine thanks"] = "Estoy bien, gracias.",
    ["** Squire: ** Hi, how can I help you?"] = "** Squire: ** Hola, ¿en qué puedo ayudarte?",
    ["*When talking to the Squire in the Void Knight Outpost smithy.*"] = "*Al hablar con Squire en la herrería del puesto avanzado Void Knight.*",
    ["Can you repair my items for me?"] = "¿Pueden reparar mis artículos por mí?",
    ["Of course I'll repair it, though the materials may cost you. Just hand me the item and I'll have a look."] = "Por supuesto que lo repararé, aunque los materiales te pueden costar. Sólo dame el artículo y echaré un vistazo.",
    ["*Using the right click option \"Repair all\" with the squire without having any items able to be repaired results in the following dialogue:*"] = "*Usar la opción de clic derecho \"Reparar todo\" con el escudero sin tener ningún elemento que pueda repararse da como resultado el siguiente diálogo:*",
    ["You do not have any items that can be repaired or recharged."] = "No tienes ningún artículo que pueda repararse o recargarse.",
    ["I'm a squire for the Void Knights."] = "Soy un escudero de los Void Knights.",
    ["The who?"] = "¿Quién?",
    ["The Void Knights, they are great warriors of balance who do Guthix's work here in Gielinor."] = "Los Void Knights, son grandes guerreros del equilibrio que hacen el trabajo de Guthix aquí en Gielinor.",
    ["Entry is strictly invite only, however we do need help continuing Guthix's work."] = "La entrada es estrictamente solo por invitación, sin embargo, necesitamos ayuda para continuar con el trabajo de Guthix.",
    ["*(Same as below)*"] = "*(Igual que a continuación)*",
    ["Ah well you see we try to keep Gielinor as Guthix intended, it's very challenging. Actually we've been having some problems recently, maybe you could help us?"] = "Ah, bueno, verás, intentamos mantener Gielinor como pretendía Guthix, es un gran desafío. De hecho, hemos tenido algunos problemas recientemente, ¿quizás podrías ayudarnos?",
    ["Well the order has become quite diminished over the years, it's a very long process to learn the skills of a Void Knight. Recently there have been breaches into our realm from somewhere else, and strange creatures have been"] = "Bueno, el orden ha disminuido bastante con el paso de los años, es un proceso muy largo aprender las habilidades de un Void Knight. Recientemente ha habido irrupciones en nuestro reino desde algún otro lugar, y extrañas criaturas han sido",
    ["pouring through. We can't let that happen, and we'd be very grateful if you'd help us."] = "fluyendo. No podemos permitir que eso suceda y le agradeceríamos mucho que nos ayudara.",
    ["We send launchers from our outpost to the nearby islands. If you go and wait in the lander there then that'd really help."] = "Enviamos lanzadores desde nuestro puesto de avanzada a las islas cercanas. Si vas y esperas allí en el módulo de aterrizaje, eso sería de gran ayuda.",
    ["It is the name that Guthix gave to this world, so we honour him with its use."] = "Es el nombre que Guthix le dio a este mundo, por eso lo honramos con su uso.",
    ["Where does this ship go?"] = "¿Adónde va este barco?",
    ["To the Void Knight outpost. It's a small island just off the coast of Karamja."] = "Al puesto avanzado de Void Knight. Es una pequeña isla frente a la costa de Karamja.",
    ["I'd like to go to your outpost."] = "Me gustaría ir a tu puesto de avanzada.",
    ["That's nice."] = "Eso es bueno.",
    ["Certainly, right this way."] = "Ciertamente, por aquí.",
    ["The ship arrives at the Void Knight outpost."] = "El barco llega al puesto avanzado Void Knight.",
    ["I'd like to go back to Port Sarim please."] = "Me gustaría volver a Port Sarim, por favor.",
    ["Ok, but please come back soon and help us."] = "Ok, pero vuelve pronto y ayúdanos.",
    ["The ship arrives at Port Sarim."] = "El barco llega a Port Sarim.",
    ["*The same dialogue appears for the Squire (Novice), Squire (Intermediate), and Squire (Veteran)*"] = "*Aparece el mismo diálogo para Squire (principiante), Squire (intermedio) y Squire (veterano)*",
    ["[missing]"] = "[desaparecido]",
    ["Congratulations! You managed to destroy all the portals! We've awarded you 4 Void Knight Commendations."] = "¡Felicitaciones! ¡Conseguiste destruir todos los portales! Le hemos otorgado 4 elogios Void Knight.",
    ["The knights noticed your lack of zeal in that battle and have not presented you with any points."] = "Los caballeros notaron tu falta de celo en esa batalla y no te han otorgado ningún punto.",
    ["You must defend the Void Knight while the portals are unsummoned. The ritual takes twenty minutes though, so oyu can help out by destroying them yourselves! Now Go GO GO!"] = "Debes defender el Void Knight mientras los portales no están convocados. Sin embargo, el ritual dura veinte minutos, ¡así que oyu puede ayudar destruyéndolos ustedes mismos! ¡Ahora ve, ve, ve!",
    ["Be quick, we're under attack!"] = "¡Date prisa, estamos bajo ataque!",
    ["This island is being invaded by outsiders and the Void Knight over there is using a ritual to unsummon their portals. We must defend the Void Knight at all costs, however if you get an opening you can destroy the portals yourself."] = "Esta isla está siendo invadida por forasteros y los Void Knight de allí están usando un ritual para cancelar sus portales. Debemos defender el Void Knight a toda costa, sin embargo si consigues una apertura podrás destruir los portales tú mismo.",
    ["How do I repair things?"] = "¿Cómo reparo las cosas?",
    ["I want to leave."] = "Quiero irme.",
    ["I'd better get back to it then."] = "Entonces será mejor que vuelva a ello.",
    ["There are stockpiles of logs near the trees on the island. You'll need to collect logs from the stockpiles and use a hammer to repair the defences."] = "Hay reservas de logs cerca de los árboles de la isla. Necesitarás recolectar logs de las reservas y usar un martillo para reparar las defensas.",
    ["Away you go then, the lander will take you back."] = "Entonces vete, el módulo de aterrizaje te llevará de regreso.",
    ["What do you want to do?"] = "¿Qué quieres hacer?",
    ["Chat."] = "Charla.",
    ["Hello friend! Many thanks for all your help! Vyvin never even realised it was a different sword, and I still have my job!"] = "¡Hola amigo! ¡Muchas gracias por toda tu ayuda! Vyvin ni siquiera se dio cuenta de que era una espada diferente, ¡y yo todavía tengo mi trabajo!",
    ["I've come for my reward."] = "He venido por mi recompensa.",
    ["So, you've finished the Hard Tasks, well done! I believe congratulations are in order."] = "Entonces, has terminado las tareas difíciles, ¡bien hecho! Creo que las felicitaciones son necesarias.",
    ["Right you are."] = "Tienes razón.",
    ["[The squire hands you a shield.]"] = "[El escudero te entrega un escudo.]",
    ["This is the third stage of the Falador shield: a tower shield. It grants you all the benefits that the buckler and kiteshield did, full Prayer restore, and access to some interesting new seeds that my friend Wyson has found."] = "Esta es la tercera etapa del escudo Falador: un escudo de torre. Te otorga todos los beneficios que obtuvieron el escudo y el escudo de cometa, restauración completa de Prayer y acceso a algunas semillas nuevas e interesantes que mi amigo Wyson encontró.",
    ["As before, Prayer restore can only be used once per day, but this time it restores all of your Prayer points!"] = "Como antes, la restauración Prayer solo se puede usar una vez al día, ¡pero esta vez restaura todos tus puntos Prayer!",
    ["The new seeds I mentioned were discovered by Wyson, who can be found in Falador Park. He'll give you some new seeds in return for the skin of the giant mole beneath Falador Park."] = "Las nuevas semillas que mencioné fueron descubiertas por Wyson, quien se puede encontrar en el parque Falador. Te dará algunas semillas nuevas a cambio de la piel del topo gigante que se encuentra debajo del parque Falador.",
    ["As well as these features, the shield is pretty handy in combat, and gives you a big Prayer boost."] = "Además de estas características, el escudo es bastante útil en combate y te brinda un gran impulso de Prayer.",
    ["Oh, and I've sent word to the Master Crafter at the guild to the south, he'll now let you use his bank deposit box."] = "Ah, y le he enviado un mensaje al Master Crafter del gremio del sur, ahora te permitirá usar su caja de depósito bancaria.",
    ["If you should lose your shield, come back and see me for another one."] = "Si pierdes tu escudo, regresa y busca otro.",
    ["Wow, thanks!"] = "¡Vaya, gracias!",
    ["I've even thrown in an old teapot I've found in the castle."] = "Incluso arrojé una tetera vieja que encontré en el castillo.",
    ["[He indicates the 'teapot'.]"] = "[Señala la \"tetera\".]",
    ["This isn't a teapot, it's a magical lamp!"] = "¡Esto no es una tetera, es una lámpara mágica!",
    ["Ah. That would explain a lot..."] = "Ah. Eso explicaría muchas cosas...",
    ["Where is the shield that I gave you, Player?"] = "¿Dónde está el escudo que te di, Player?",
    ["I lost it, I'm not sure where."] = "Lo perdí, no estoy seguro de dónde.",
    ["Luckily, I have a spare. Take better care of it next time."] = "Por suerte, tengo uno de repuesto. Cuídalo mejor la próxima vez.",
    ["[The squire hands you a new shield.]"] = "[El escudero te entrega un escudo nuevo.]",
    ["I've lost my shield."] = "He perdido mi escudo.",
    ["What? That was valuable equipment!"] = "¿Qué? ¡Ese era un equipo valioso!",
    ["Some also give items that will help complete other tasks, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otras tareas y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Falador set, you are presented with a shield."] = "Por completar el conjunto Falador, se te presenta un escudo.",
    ["This shield will become increasingly useful as you complete greater difficulties of task sets."] = "Este escudo será cada vez más útil a medida que completes conjuntos de tareas de mayor dificultad.",
    ["You need to complete all tasks within a particular difficulty set, then you can claim your reward."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Falador set's tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Falador son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["To claim your Falador set rewards, speak to Redbeard Frank in Port Sarim, the chemist in Rimmington, or myself."] = "Para reclamar las recompensas del conjunto Falador, habla con Redbeard Frank en Port Sarim, el químico de Rimmington o conmigo mismo.",
    ["Falador shield 1"] = "Escudo Falador 1",
    ["Falador shield 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Escudo Falador 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["[You're handed another Falador shield 1.]"] = "[Te entregan otro escudo Falador 1.]",
    ["Falador shield 2"] = "Escudo Falador 2",
    ["Falador shield 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Escudo Falador 2? Sí, pero me temo que te costaría 2500 coins.",
    ["[You're handed another Falador shield 2.]"] = "[Te entregan otro escudo Falador 2.]",
    ["Falador shield 3"] = "Escudo Falador 3",
    ["Falador shield 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Escudo Falador 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["[You're handed another Falador shield 3.]"] = "[Te entregan otro escudo Falador 3.]",
    ["Falador shield 4"] = "Escudo Falador 4",
    ["Falador shield 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Escudo Falador 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["[You're handed another Falador shield 4.]"] = "[Te entregan otro escudo Falador 4.]",
    ["[Squire Asrol has given you your next clue scroll.]"] = "[Squire Asrol te ha dado tu siguiente pergamino de pistas.]",
    ["Awesome stuff!"] = "¡Cosas increíbles!",
    ["Hello there. If you're looking for Sir Amik, go up two staircases from here."] = "Hola. Si buscas a Sir Amik, sube dos escaleras desde aquí.",
    ["Hello there. Could I ask you about the-"] = "Hola. ¿Puedo preguntarte sobre-?",
    ["Not at the moment, I'm afraid! It's not nearly safe enough to talk right now."] = "¡Me temo que no por el momento! No es lo suficientemente seguro hablar ahora.",
    ["But you don't even know what I was going to ask!"] = "¡Pero ni siquiera sabes lo que iba a preguntar!",
    ["Oh, I have enough of an idea to know that it's not safe enough to talk about it on a free world."] = "Oh, tengo una idea suficiente para saber que no es lo suficientemente seguro hablar de ello en un mundo libre.",
    ["So, I'm curious. What are you doing up here and what's that interesting contraption?"] = "Entonces, tengo curiosidad. ¿Qué estás haciendo aquí arriba y qué es ese artilugio tan interesante?",
    ["Well, it's all part of King Roald's new security initiative."] = "Bueno, todo es parte de la nueva iniciativa de seguridad de King Roald.",
    ["Security initiative? That sounds intriguing. What's going on?"] = "¿Iniciativa de seguridad? Eso suena intrigante. ¿Qué está sucediendo?",
    ["I'm afraid that I can't discuss it in detail at present, but if you're that interested, have a chat with the king. Last I heard, we needed some extra hands on deck."] = "Me temo que no puedo discutirlo en detalle en este momento, pero si estás interesado, habla con el rey. Lo último que supe es que necesitábamos algunas manos extra.",
    ["Thanks, I just might."] = "Gracias, tal vez.",
    ["Hello again! And what might I be able to do for you today?"] = "¡Hola de nuevo! ¿Y qué podría hacer por ti hoy?",
    ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
    ["Of course. Once the beacon is lit, just leave 5 logs with me and I'll take care of the fire for as long as I can."] = "Por supuesto. Una vez que la baliza esté encendida, déjame 5 logs y yo me ocuparé del fuego todo el tiempo que pueda.",
    ["Well, I could, but since you're here, you might as well do it yourself."] = "Bueno, podría, pero ya que estás aquí, es mejor que lo hagas tú mismo.",
    ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
    ["I'm afraid you don't have enough of the right type of log for me to use."] = "Me temo que no tienes suficiente registro del tipo correcto para que yo lo use.",
    ["I'll need five logs to be able to tend the fire. Is that okay?"] = "Necesitaré cinco logs para poder atender el fuego. ¿Está bien?",
    ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
    ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
    ["Thank you! I'll use these five logs to keep the beacon burning while you're away."] = "¡Gracias! Usaré estos cinco logs para mantener encendida la baliza mientras estás fuera.",
    ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
    ["Well, you know where I am if you change your mind."] = "Bueno, ya sabes dónde estoy si cambias de opinión.",
    ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
    ["Of course I will; don't worry. I'll use the logs you've already left with me."] = "Por supuesto que lo haré; no te preocupes. Usaré el logs que ya me dejaste.",
    ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
    ["But, of course! Just have a look at my map."] = "¡Pero claro! Sólo echa un vistazo a mi mapa.",
    ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
    ["I can tell you about the state of the beacons in either direction, up to the last fires that are lit."] = "Puedo informarte del estado de las balizas en ambas direcciones, hasta los últimos fuegos que se encienden.",
    ["I could probably tell you about the other beacons as well, but I'd need the help of a macaw."] = "Probablemente también podría contarte sobre las otras balizas, pero necesitaría la ayuda de una guacamaya.",
    ["A macaw?"] = "¿Una guacamaya?",
    ["Yes. Macaws have the ability to fly high into the air and see things that are much further away."] = "Sí. Los guacamayos tienen la capacidad de volar muy alto en el aire y ver cosas que están mucho más lejos.",
    ["They are also highly intelligent and can be trained to provide the exact information I'd need for a complete overview of the beacon network."] = "También son muy inteligentes y se les puede entrenar para proporcionar la información exacta que necesito para obtener una descripción completa de la red de balizas.",
    ["Come to think of it, the macaw you've got there in your pack would be perfect."] = "Ahora que lo pienso, la guacamaya que tienes en tu mochila sería perfecta.",
    ["Very well, thank you. We're ever so grateful for your help in testing the beacon network."] = "Muy bien, gracias. Estamos muy agradecidos por su ayuda para probar la red de balizas.",
    ["Oh, it was no big deal. You're doing most of the hard work, standing watch like that."] = "Oh, no fue gran cosa. Tú estás haciendo la mayor parte del trabajo duro, haciendo guardia de esa manera.",
    ["To be honest, I'd intended to become an 'Arcanist', but due to an administrative error, I ended up being put forward as an 'Arsonist'."] = "Para ser honesto, tenía la intención de convertirme en 'Arcanista', pero debido a un error administrativo, terminé siendo propuesto como 'Incendiario'.",
    ["Go figure."] = "Imagínate.",
    ["Still, things worked out for the best. It's a great honour to play such an important role in protecting the kingdom."] = "Aún así, las cosas salieron bien. Es un gran honor desempeñar un papel tan importante en la protección del reino.",
    ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
    ["Goodbye, then. Stop by again if you're in the neighbourhood - it's nice to have the company."] = "Adiós, entonces. Vuelve a visitarnos si estás en el vecindario: es bueno tener compañía.",
    ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
    ["Thank you very much. This macaw will help me give you more detailed information about the beacon network."] = "Muchas gracias. Esta guacamaya me ayudará a brindarles información más detallada sobre la red de balizas.",
    ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
    ["I've already given her a macaw; she doesn't need another."] = "Ya le regalé una guacamaya; ella no necesita otra.",
    ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
    ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
    ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
    ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
    ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
    ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
    ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
    ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    ["I'm sorry, my lord, but you cannot enter this area."] = "Lo siento, mi señor, pero no puede ingresar a esta área.",
    ["[You need to have completed the King's Ransom Quest to gain access to the Knight Waves.]"] = "[Debes haber completado King's Ransom Quest para obtener acceso a Knight Waves.]",
    ["Greetings, brave knight!"] = "¡Saludos, valiente caballero!",
    ["Hello. What's through that door?"] = "Hola. ¿Qué hay a través de esa puerta?",
    ["That door leads to the training ground for the Knights of the Round Table."] = "Esa puerta conduce al campo de entrenamiento de los Caballeros de la Mesa Redonda.",
    ["Can I go in there?"] = "¿Puedo entrar ahí?",
    ["Of course, my [lord/lady]. But I must tell you the rules first. Would you like to hear them now?"] = "Por supuesto, mi [lord/lady]. Pero primero debo decirte las reglas. ¿Te gustaría escucharlos ahora?",
    ["Stuns and binds will not work in the training grounds. Merlin has cast a spell over the grounds to prevent anyone using prayer, stuns or binds."] = "Los aturdimientos y ataduras no funcionarán en los campos de entrenamiento. Merlín ha lanzado un hechizo sobre el terreno para evitar que cualquiera utilice oraciones, aturdimiento o ataduras.",
    ["Upon entering the grounds, you will fight each of the Round Table Knights in turn. Each knight is more skilled than the last, but all have different attack styles that can be exploited. There are eight knights in all, and each will do damage not only to your life points, but also your combat stats. If you should die in the grounds, Merlin will teleport you back here. You will not lose any of your items."] = "Al entrar al recinto, lucharás contra cada uno de los Caballeros de la Mesa Redonda por turno. Cada caballero es más hábil que el anterior, pero todos tienen diferentes estilos de ataque que pueden explotarse. Hay ocho caballeros en total, y cada uno de ellos dañará no sólo tus puntos de vida, sino también tus estadísticas de combate. Si mueres en el terreno, Merlín te teletransportará de regreso aquí. No perderás ninguno de tus artículos.",
    ["If you feel you cannot complete the battle, you may exit the training grounds. However, if you exit or die, you will have to start over with the first knight the next time you enter."] = "Si sientes que no puedes completar la batalla, puedes salir del campo de entrenamiento. Sin embargo, si sales o mueres, tendrás que empezar de nuevo con el primer caballero la próxima vez que entres.",
    ["If you are a great warrior and defeat Sir Lancelot, mightiest of all knights, you will receive great rewards. Four new prayers will become available to you and your respawn point will be set to Camelot, as well as 20,000 XP in to each of your combat stats."] = "Si eres un gran guerrero y derrotas a Sir Lancelot, el más poderoso de todos los caballeros, recibirás grandes recompensas. Cuatro nuevas oraciones estarán disponibles para ti y tu punto de reaparición se establecerá en Camelot, así como 20 000 XP en cada una de tus estadísticas de combate.",
    ["If you do not want your respawn set to Camelot, Merlin can change it for you."] = "Si no quieres que tu reaparición esté configurada en Camelot, Merlín puede cambiarlo por ti.",
    ["Would you like me to repeat any of that for you?"] = "¿Quieres que te repita algo de eso?",
    ["Tell me about the training ground."] = "Cuéntame sobre el campo de entrenamiento.",
    ["Merlin will prevent the use of Prayer, Stuns and binds."] = "Merlín evitará el uso de Prayer, aturde y vincula.",
    ["Why?"] = "¿Por qué?",
    ["These grounds are for only the best knights of the land. It is not just testing your combat ability, but your honour and your chivalry. You must face your enemy head on, honourably and bravely. Be watchful of your stats, as the knights can do damage to your combat stats as well as your life points."] = "Estos terrenos son solo para los mejores caballeros de la tierra. No se trata sólo de poner a prueba tu capacidad de combate, sino también tu honor y tu caballerosidad. Debes enfrentarte a tu enemigo de frente, con honor y valentía. Esté atento a sus estadísticas, ya que los caballeros pueden dañar sus estadísticas de combate y sus puntos de vida.",
    ["Tell me about dying or leaving the grounds."] = "Cuéntame sobre morir o abandonar el recinto.",
    ["As these are only training grounds, we keep our knights safe. If you should die, you will be teleported back to here and all of your items will be safe."] = "Como estos son solo campos de entrenamiento, mantenemos a nuestros caballeros a salvo. Si mueres, serás teletransportado de regreso aquí y todos tus artículos estarán a salvo.",
    ["However, leaving the training grounds, in any way, will mean you will have to start from the beginning the next time you enter. These grounds do not favour cowards."] = "Sin embargo, abandonar el campo de entrenamiento, de cualquier manera, significará que tendrás que comenzar desde el principio la próxima vez que ingreses. Estos motivos no favorecen a los cobardes.",
    ["I have to start again? What do you mean?"] = "¿Tengo que empezar de nuevo? ¿Qué quieres decir?",
    ["You fight each knight of the Round Table, starting with Sir Bedivere and finishing with Sir Lancelot. Leaving means you will have to begin fighting Sir Bedivere again and work your way back up."] = "Luchas contra cada caballero de la Mesa Redonda, comenzando con Sir Bedivere y terminando con Sir Lancelot. Irse significa que tendrás que empezar a luchar contra Sir Bedivere nuevamente y volver a ascender.",
    ["What if I log out during the fights?"] = "¿Qué pasa si me desconecto durante las peleas?",
    ["If you log out during a fight, upon logging back in you will fight the knight you were fighting when you logged out."] = "Si cierras sesión durante una pelea, al volver a iniciar sesión lucharás contra el caballero con el que estabas peleando cuando te desconectaste.",
    ["Tell me about the rewards."] = "Cuéntame sobre las recompensas.",
    ["King Arthur believes in rewarding his knights for their chivalry. Having proven yourself in combat against his knights, and in your services rendered to Camelot, you will be rewarded with four new prayers, and a new respawn at Camelot, as well as 20,000 XP in to each of your combat stats."] = "King Arthur cree en recompensar a sus caballeros por su caballerosidad. Habiendo demostrado tu valía en combate contra sus caballeros y en los servicios prestados a Camelot, serás recompensado con cuatro nuevas oraciones y una nueva reaparición en Camelot, así como 20 000 XP en cada una de tus estadísticas de combate.",
    ["What do the new prayers do?"] = "¿Qué hacen las nuevas oraciones?",
    ["Ah, patience is a virtue in knights, my [lord/lady]. Fight in the training ground and earn your reward to find out!"] = "Ah, la paciencia es una virtud en los caballeros, mi [lord/lady]. ¡Lucha en el campo de entrenamiento y gana tu recompensa para descubrirlo!",
    ["Then tell me about the respawn - how will it work?"] = "Entonces cuéntame sobre la reaparición: ¿cómo funcionará?",
    ["Ah, Merlin has offered, as a reward for your help, to let you respawn in the safety of Camelot, should you befall misfortune elsewhere in the world. Should you wish to change your respawn back to Lumbridge, simply speak to Merlin."] = "Ah, Merlín te ha ofrecido, como recompensa por tu ayuda, permitirte reaparecer en la seguridad de Camelot, en caso de que te ocurra una desgracia en otra parte del mundo. Si deseas cambiar tu reaparición a Lumbridge, simplemente habla con Merlín.",
    ["Good day, my [lord/lady]. Is there anything I can do for you?"] = "Buenos días, mi [lord/lady]. ¿Hay algo que pueda hacer por ti?",
    ["*Talking to the Squire*"] = "*Hablando con el Squire*",
    ["Congratulations on succeeding in the Knight Waves, my [lord/lady]."] = "Felicitaciones por triunfar en Knight Waves, mi [lord/lady].",
    ["Thank you. Can I go back inside?"] = "Gracias. ¿Puedo volver a entrar?",
    ["I'm afraid not, my [lord/lady]. Once you have won, you cannot re-enter."] = "Me temo que no, mi [lord/lady]. Una vez que hayas ganado, no podrás volver a participar.",
    ["There is a silent choir who dread the conductor showing its terrible face."] = "Hay un coro silencioso que teme al director que muestra su terrible cara.",
    ["There is an effigy of a king presiding over a court of corpses."] = "Hay una efigie de un rey que preside un tribunal de cadáveres.",
    ["There is a cathedral-chambered heart that beats not blood but nightmares."] = "Hay un corazón en la cámara de una catedral que no late con sangre sino con pesadillas.",
    ["There is a cosmic abortion which swims the oceans of the dead."] = "Hay un aborto cósmico que nada en los océanos de los muertos.",
    ["There is a stranger that wears a black mask under its skin."] = "Hay un extraño que lleva una máscara negra debajo de su piel.",
    ["There is a someone who weeps because you still live."] = "Hay alguien que llora porque aún vives.",
    ["There is a library of sorrow in which the end of your story is whispered."] = "Hay una biblioteca de tristeza en la que se susurra el final de tu historia.",
    ["There is a wound in the world, and it is bleeding once again."] = "Hay una herida en el mundo y está sangrando una vez más.",
    ["There is a well of malevolence which is close to spilling over."] = "Hay un pozo de malevolencia que está a punto de desbordarse.",
    ["There is an empire of stone, ash and bones. It rises."] = "Hay un imperio de piedra, ceniza y huesos. Se levanta.",
    ["There is a stern judge who has already passed your sentence."] = "Hay un juez severo que ya dictó tu sentencia.",
    ["There is a time for everything to end; yours approaches."] = "Hay un momento para que todo termine; el tuyo se acerca.",
    ["There is an absence of a god that has learned how to hate."] = "Hay una ausencia de un dios que ha aprendido a odiar.",
    ["There is a void that echoes with howls of madness."] = "Hay un vacío que resuena con aullidos de locura.",
    ["There are maggots in the belly of beast."] = "Hay gusanos en el vientre de la bestia.",
    ["There are worlds where mindless madness is the only salvation."] = "Hay mundos donde la locura sin sentido es la única salvación.",
    ["There will come a great rending, which none will survive."] = "Vendrá un gran desgarro del que ninguno sobrevivirá.",
    ["There is a scream so loud you think of it as silence."] = "Hay un grito tan fuerte que lo consideras silencio.",
    ["There is an ocean of the dead, which you will one day swim."] = "Hay un océano de muertos, en el que algún día nadarás.",
    ["There is an avalanche of horror which gains momentum every heartbeat."] = "Hay una avalancha de horror que cobra impulso con cada latido.",
    ["There is an impatient hell that knows your name."] = "Hay un infierno impaciente que sabe tu nombre.",
    ["There is an atrocity written in black stone."] = "Hay una atrocidad escrita en piedra negra.",
    ["There is a monument built to honour absolute suffering."] = "Hay un monumento construido en honor al sufrimiento absoluto.",
    ["There is a killing name that makes nations weep."] = "Hay un nombre asesino que hace llorar a las naciones.",
    ["There is a record of the vilest blasphemy."] = "Hay un registro de la blasfemia más vil.",
    ["There is a city of black stone where the screaming never stops."] = "Hay una ciudad de piedra negra donde los gritos nunca paran.",
    ["There is a place so dark not even hope can light the way."] = "Hay un lugar tan oscuro que ni siquiera la esperanza puede iluminar el camino.",
    ["There is a chain of souls that spans worlds."] = "Hay una cadena de almas que abarca mundos.",
    ["There is something with a choking hand for every throat."] = "Hay algo con una mano asfixiante para cada garganta.",
    ["There is a cruel reaper who has a thousand gibbering faces."] = "Hay un segador cruel que tiene mil caras farfullando.",
    ["Meow!"] = "¡Miau!",
    ["Can't talk. Hunting!"] = "No puedo hablar. ¡Caza!",
    ["Hello cat. Would you like to come stay in a great big oasis, out in the nice, warm sun?"] = "Hola gato. ¿Le gustaría quedarse en un gran oasis, bajo el agradable y cálido sol?",
    ["How dare you speak to me, weakling? Do you not know who I am? I am the mightiest feline warrior in these lands!"] = "¿Cómo te atreves a hablarme, debilucho? ¿No sabes quién soy? ¡Soy el guerrero felino más poderoso de estas tierras!",
    ["Well, I am the World Guardian, you know."] = "Bueno, yo soy el Guardián Mundial, ¿sabes?",
    ["Pfft. Sounds pretentious."] = "Pfft. Suena pretencioso.",
    ["You want me to consider your proposal? In that case, I want you to prove you're a skilled warrior!"] = "¿Quieres que considere tu propuesta? En ese caso, ¡quiero que demuestres que eres un guerrero hábil!",
    ["I have heard rumours of a great beast made of ice that has assembled an army of frozen warriors in an ancient city buried beneath the ground."] = "He oído rumores sobre una gran bestia hecha de hielo que ha reunido un ejército de guerreros congelados en una antigua ciudad enterrada bajo tierra.",
    ["Defeat this beast and I shall consider your proposal."] = "Derrota a esta bestia y consideraré tu propuesta.",
    ["The Arch-Glacor? Oh I've already done that."] = "¿El Arch-Glacor? Ah, ya lo hice.",
    ["WHAT? I mean... Hrm... Perhaps you are a worthy warrior after all."] = "¿QUÉ? Quiero decir... Hrm... Quizás seas un guerrero digno después de todo.",
    ["Very well, I shall visit this oasis of yours. Perhaps there is a chance for glory there."] = "Muy bien, visitaré este oasis tuyo. Quizás allí haya una posibilidad de gloria.",
    ["You have completed: 'Impress the hunter' and gained progress towards the Oasis Restoration event."] = "Has completado: 'Impresionar al cazador' y has progresado hacia el evento Restauración del Oasis.",
    ["Farewell warrior!"] = "¡Adiós guerrero!",
    ["I shall seek out this monster."] = "Buscaré a este monstruo.",
    ["Good luck, you'll need it."] = "Buena suerte, la necesitarás.",
    ["Curse them! Those lizards think they can mock me from their watery sanctuaries?"] = "¡Malditos sean! ¿Esos lagartos creen que pueden burlarse de mí desde sus santuarios acuáticos?",
    ["They'll be sorry as soon as I learn how to swim!"] = "¡Se arrepentirán tan pronto como aprenda a nadar!",
    ["There is only one who is all powerful, and his greatest weapon is love."] = "Sólo hay uno que es todopoderoso, y su mayor arma es el amor.",
    ["Have you no shame? We are all grieving at the moment."] = "¿No tienes vergüenza? Todos estamos de duelo en este momento.",
    ["Thank you for all your help in solving the murder."] = "Gracias por toda su ayuda para resolver el asesinato.",
    ["Hello, bold adventurer."] = "Hola, aventurero audaz.",
    ["Are these your trucks?"] = "¿Son estos tus camiones?",
    ["Yes, I use them to transport coal over the river. I will let other people use them too, I'm a nice person like that..."] = "Sí, los uso para transportar carbón por el río. Dejaré que otras personas los usen también, soy una buena persona así...",
    ["Just put coal in a truck and I'll move it down to my depot over the river."] = "Simplemente pon carbón en un camión y lo llevaré a mi depósito sobre el río.",
    ["Hello, Mr Stankers."] = "Hola, señor Stankers.",
    ["Would you like a poison chalice?"] = "¿Quieres un cáliz envenenado?",
    ["Take one from my shop. You might consider buying one of my fine pickaxes while you're looking."] = "Llévate uno de mi tienda. Podrías considerar comprar uno de mis finos picos mientras miras.",
    ["Pickaxes?"] = "¿Picos?",
    ["Yes, I've started a business. It's not going very well so far, but the poison chalices are quite a nice loss-leader."] = "Sí, comencé un negocio. Las cosas no van muy bien hasta ahora, pero los cálices venenosos son un buen líder de pérdidas.",
    ["What's a poison chalice?"] = "¿Qué es un cáliz venenoso?",
    ["It's an exciting drink I've invented. I don't know what it tastes like. I haven't tried it myself."] = "Es una bebida emocionante que he inventado. No sé a qué sabe. Yo mismo no lo he probado.",
    ["Hi. I've completed the Medium Tasks in the Seers' Village set. Can I have a reward?"] = "Hola. Completé las tareas medianas en el conjunto Seers' Village. ¿Puedo tener una recompensa?",
    ["Well done! Yes, I have a reward for you. I'll just anoint your headband with one of my mixtures. Oh and here's an old lamp I had lying around."] = "¡Bien hecho! Sí, tengo una recompensa para ti. Simplemente ungiré tu diadema con una de mis mezclas. Ah, y aquí hay una lámpara vieja que tenía por ahí.",
    ["[Stankers produces a chalice containing a vile-looking concoction that he pours all over your headband.]"] = "[Stankers produce un cáliz que contiene un brebaje de aspecto vil que vierte sobre tu diadema.]",
    ["Erm, thank you...I guess."] = "Erm, gracias... Supongo.",
    ["Don't worry, but it may be a little sticky for a while. While wearing it, 'Flax' will give you 60 flax per day, you'll be able to see better in the dark, and your defence against magic attacks will be boosted."] = "No te preocupes, pero puede que quede un poco pegajoso por un tiempo. Mientras lo uses, 'Flax' te dará 60 linaza por día, podrás ver mejor en la oscuridad y tu defensa contra ataques mágicos aumentará.",
    ["I'll allow 280 pieces of coal in my coal truck, and you'll receive bonuses when cutting maple and normal trees. Oh, you will also find your fingers are more nimble on the spinning wheel in Seers' Village."] = "Permitiré 280 piezas de carbón en mi camión de carbón y recibirás bonificaciones al cortar arces y árboles normales. Oh, también descubrirás que tus dedos son más ágiles en la rueca en Seers' Village.",
    ["I've lost my headband."] = "Perdí mi diadema.",
    ["No worries. I happen to have a spare here."] = "No te preocupes. Resulta que tengo uno de repuesto aquí.",
    ["To claim your Seers' Village set rewards, speak to any seer in the village, Sir Kay in Camelot, or myself."] = "Para reclamar las recompensas del conjunto Seers' Village, habla con cualquier vidente de la aldea, con Sir Kay en Camelot o conmigo mismo.",
    ["Toggle Camelot Teleport to [Seers' Village /Camelot]?"] = "¿Cambiar Camelot Teleport a [Seers' Village /Camelot]?",
    ["Camelot Teleport will now teleport you to the [Seers' Village /to the gates of Camelot]."] = "Camelot Teleport ahora te teletransportará al [Seers' Village /to the gates of Camelot].",
    ["Is it, indeed."] = "Lo es, efectivamente.",
    ["What's so good about it?"] = "¿Qué tiene de bueno?",
    ["Over here, [lad/lass]."] = "Por aquí, [lad/lass].",
    ["Behold, another to bathe in the glory of the Spotlight!"] = "¡He aquí otro para bañarse en la gloria de Spotlight!",
    ["Who, me?"] = "¿Quién, yo?",
    ["Indeed!"] = "¡Efectivamente!",
    ["I represent the League of Many, dedicated to the art of friendly competition, and I seek to reward those who play games together."] = "Represento a la Liga de Muchos, dedicada al arte de la competencia amistosa, y busco recompensar a quienes juegan juntos.",
    ["Whenever you play minigames I will reward you with thaler, the coin of our League."] = "Siempre que juegues minijuegos te recompensaré con tálero, la moneda de nuestra Liga.",
    ["Play the game on which our Spotlight falls and we will give you those thaler at five times the normal rate!"] = "¡Juega el juego en el que cae nuestro foco y te daremos esos táleros cinco veces más caros que lo normal!",
    ["Tell me more about the Spotlight."] = "Cuéntame más sobre Spotlight.",
    ["Every three days the Spotlight moves. Whichever minigame the Spotlight falls on is worth five times the usual rate of thaler for my store!"] = "Cada tres días, Spotlight se mueve. ¡Cualquiera que sea el minijuego en el que se encuentre Spotlight vale cinco veces el precio habitual de táleros en mi tienda!",
    ["You can check which minigame is Spotlighted, and which will be coming up next, on the Minigames list."] = "Puedes comprobar qué minijuego está Destacado y cuál será el siguiente en la lista de Minijuegos.",
    ["Would you like to open up the Minigames tab?"] = "¿Quieres abrir la pestaña Minijuegos?",
    ["What can I buy with thaler?"] = "¿Qué puedo comprar con tálero?",
    ["I offer a range of rewards from minigames around Gielinor! Armour, tools and some compelling miscellany are available."] = "¡Ofrezco una variedad de recompensas de minijuegos relacionados con Gielinor! Se encuentran disponibles armaduras, herramientas y algunos otros elementos interesantes.",
    ["I've also secured a number of, shall we say, more limited edition items, which will be around for a shorted period. Here, take a look..."] = "También he conseguido una serie de, digamos, artículos de edición más limitada, que estarán disponibles por un período más breve. Aquí, echa un vistazo...",
    ["Would you like to open the shop?"] = "¿Quieres abrir la tienda?",
    ["What's currently in the Spotlight?"] = "¿Qué hay actualmente en el foco de atención?",
    ["[Current minigame] is currently under the Spotlight. [Next minigame] is coming up next, in about <number> days."] = "[Current minigame] se encuentra actualmente bajo el foco de atención. [Next minigame] será el próximo, en aproximadamente <number> días.",
    ["Bye"] = "Adiós",
    ["Why hello there. What can I do for you?"] = "Hola. ¿Qué puedo hacer por ti?",
    ["I don't think I heard you mining this star."] = "No creo haberte oído extraer esta estrella.",
    ["Really? I... er... I've been here this whole time!"] = "¿En serio? Yo... eh... ¡He estado aquí todo este tiempo!",
    ["My ears are very sensitive, and I'm quite sure I didn't hear you."] = "Mis oídos son muy sensibles y estoy bastante seguro de que no te escuché.",
    ["Worth a shot."] = "Vale la pena intentarlo.",
    ["Thank you for helping me out of here."] = "Gracias por ayudarme a salir de aquí.",
    ["I have rewarded you by making it so you can mine extra ore for the next [number] minutes. Also, have 152 cosmic runes, 52 astral runes, 70 gold stone spirits, and 50,002 coins."] = "Te he recompensado haciéndolo para que puedas extraer mineral extra durante los próximos minutos [número]. Además, tenga 152 runas cósmicas, 52 runas astrales, 70 espíritus de piedras doradas y 50.002 coins.",
    ["Hello, strange creature."] = "Hola, extraña criatura.",
    ["I'm not strange."] = "No soy extraño.",
    ["Hehe. If you say so."] = "Jeje. Si tú lo dices.",
    ["If anything, you're the strange, glowing, one."] = "En todo caso, tú eres el extraño y brillante.",
    ["Isn't that funny? One of the things I find odd about you is that you DON'T glow."] = "¿No es gracioso? Una de las cosas que encuentro raras de ti es que NO brillas.",
    ["So what are you? Where did you come from?"] = "Entonces, ¿qué eres? ¿De dónde vienes?",
    ["I'm a star sprite! I was in my star in the sky, when it lost control and crashed into the ground. With half my star sticking in the ground, I became stuck. Fortunately, I was mined out by the kind creatures of your race."] = "¡Soy un star sprite! Estaba en mi estrella en el cielo, cuando perdió el control y se estrelló contra el suelo. Con la mitad de mi estrella clavada en el suelo, me quedé estancado. Afortunadamente, las amables criaturas de tu raza me sacaron.",
    ["What is a star sprite?"] = "¿Qué es un star sprite?",
    ["We're what makes the stars in the sky shine. I made this star shine when it was in the sky."] = "Somos lo que hace brillar las estrellas en el cielo. Hice brillar esta estrella cuando estaba en el cielo.",
    ["What happened to your star?"] = "¿Qué pasó con tu estrella?",
    ["What happened to your star exactly?"] = "¿Qué le pasó exactamente a tu estrella?",
    ["I was in my star in the sky, when it lost control and crashed into the ground. If it weren't for your kind, I would still be stuck in there!"] = "Estaba en mi estrella en el cielo, cuando perdió el control y se estrelló contra el suelo. ¡Si no fuera por los de tu especie, todavía estaría atrapado allí!",
    ["What are you going to do without your star?"] = "¿Qué vas a hacer sin tu estrella?",
    ["Don't worry about me. I'm sure I'll find some good rocks around here and get back up into the sky in no time."] = "No te preocupes por mí. Estoy seguro de que encontraré algunas buenas rocas por aquí y volveré al cielo en poco tiempo.",
    ["I thought stars were huge balls of burning gas."] = "Pensé que las estrellas eran enormes bolas de gas ardiendo.",
    ["Most of them are, but a lot of shooting stars on this plane of the multiverse are rocks with star sprites in them."] = "La mayoría lo son, pero muchas estrellas fugaces en este plano del multiverso son rocas con espíritus estelares en ellas.",
    ["Are you okay?"] = "¿Estás bien?",
    ["Are you okay? That looked like a nasty crash."] = "¿Estás bien? Parecía un accidente desagradable.",
    ["Yes, these things happen all the time."] = "Sí, estas cosas suceden todo el tiempo.",
    ["Err... Well, I'm glad you're okay at least."] = "Err... Bueno, me alegro de que al menos estés bien.",
    ["Goodbye!"] = "¡Adiós!",
    ["It's been lovely talking to you, but I've got to go."] = "Ha sido un placer hablar contigo, pero tengo que irme.",
    ["Goodbye strange creature!"] = "¡Adiós criatura extraña!",
    ["What are you trying to do?"] = "¿Qué estás intentando hacer?",
    ["I'm.... honestly not sure."] = "Estoy... sinceramente, no estoy seguro.",
    ["[You must visit Wizard Rosalina on the second floor of the Wizards' Tower to be able to teleport from a fallen star.]"] = "[Debes visitar Wizard Rosalina en el segundo piso de Wizards' Tower para poder teletransportarte desde una estrella caída.]",
    ["Teleport to Wizard Rosalina?"] = "¿Teletransportarse a Wizard Rosalina?",
    ["Happy travels!"] = "¡Felices viajes!",
    ["**Statue of Death: :** Welcome back adventurer. The citadel took some cleaning up after you left, that dragonkin really lost his temper."] = "**Statue of Death: :** Bienvenido de nuevo aventurero. La ciudadela tuvo que ser limpiada un poco después de que te fuiste, ese dragonante realmente perdió los estribos.",
    ["Ask about rewards."] = "Pregunta por las recompensas.",
    ["XP lamps"] = "lámparas XP",
    ["*If you have not yet claimed any XP lamps*"] = "*Si aún no has reclamado ninguna lámpara XP*",
    ["Sliske was most entertained by your efforts. He left you these lamps so that you may do even better next time."] = "Sliske quedó muy entretenido con tus esfuerzos. Te dejó estas lámparas para que la próxima vez lo hagas aún mejor.",
    ["*If you do not yet have the required skill level to claim any XP lamp*"] = "*Si aún no tienes el skill level requerido para reclamar cualquier lámpara XP*",
    ["You need a [Skill] level of at least X to receive the [Skill] lamp."] = "Necesita un nivel [Skill] de al menos X para recibir la lámpara [Skill].",
    ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
    ["*If you have already claimed all XP lamps*"] = "*Si ya has reclamado todas las lámparas XP*",
    ["**Statue of Death: :** I've already given you that reward."] = "**Statue of Death: :** Ya te di esa recompensa.",
    ["Barrows amulets"] = "Amuletos de túmulos",
    ["*If you have not yet claimed all Barrows amulets.*"] = "*Si aún no has reclamado todos los amuletos de Barrows.*",
    ["**Statue of Death: :** Sliske left you these amulets he infused with his power. Consider them an invitation to the Barrows. He will soon be holding games there, but for now you may shatter an amulet against a wight's sarcophagus to kill him before he wakes. Use them wisely, though. You may only use these amulets for each run through the tombs."] = "**Statue of Death: :** Sliske te dejó estos amuletos que le infundió su poder. Considérelos una invitación a los Túmulos. Pronto celebrará juegos allí, pero por ahora puedes romper un amuleto contra el sarcófago de un espectro para matarlo antes de que despierte. Sin embargo, úselos sabiamente. Solo puedes usar estos amuletos para cada recorrido por las tumbas.",
    ["*If you have already claimed all Barrows amulets.*"] = "*Si ya has reclamado todos los amuletos de Barrows.*",
    ["**Statue of Death: :** I've already give you that reward. In case you forgot, the amulets can be scattered against a brother's sarcophagus to kill them before they wake. But use them wisely. You may only use three amulets for each run through the tombs."] = "**Statue of Death: :** Ya te di esa recompensa. En caso de que lo hayas olvidado, los amuletos se pueden esparcir contra el sarcófago de un hermano para matarlo antes de que despierte. Pero utilícelos sabiamente. Solo puedes usar tres amuletos por cada recorrido por las tumbas.",
    ["Book of the Underworld"] = "Libro del inframundo",
    ["*If you don't have a Book of the Underworld*"] = "*Si no tienes un Libro del Inframundo*",
    ["***Statue of Death: :** ​*Misplaced your Book of the Underworld, have you? Here, have another."] = "***Statue of Death: :** ​*Perdiste tu Libro del Inframundo, ¿verdad? Toma, toma otro.",
    ["*If you already have a Book of the Underworld*"] = "*Si ya tienes un Libro del Inframundo*",
    ["**Statue of Death: :** You've already got one of those, I'm afraid I can't give you another one."] = "**Statue of Death: :** Ya tienes uno de esos, me temo que no puedo darte otro.",
    ["Alternate death animations"] = "Animaciones de muerte alternativas.",
    ["**Statue of Death: :** Now that you know them personally, Death or Icthlarin may pay you a visit when you die. Which would you prefer?"] = "**Statue of Death: :** Ahora que los conoces personalmente, Death o Icthlarin pueden hacerte una visita cuando mueras. ¿Cuál preferirías?",
    ["I want Death to reap my soul."] = "Quiero que la Muerte coseche mi alma.",
    ["**Statue of Death: :** Very well. Send my regards to the Reaper."] = "**Statue of Death: :** Muy bien. Envía mis saludos al Reaper.",
    ["*(Returns to previous-to-previous options)*"] = "*(Vuelve a las opciones anteriores a anteriores)*",
    ["I want Icthlarin to guide my spirit"] = "Quiero que Icthlarin guíe mi espíritu.",
    ["**Statue of Death: :** Very well. Take your chances with the jackal."] = "**Statue of Death: :** Muy bien. Arriésgate con el chacal.",
    ["I don't want either of them to visit me."] = "No quiero que ninguno de los dos me visite.",
    ["**Statue of Death: :** A wise choice, personally I wouldn't feel safe with either of them."] = "**Statue of Death: :** Una elección acertada, personalmente no me sentiría seguro con ninguno de los dos.",
    ["Ask about Sliske's ascension."] = "Pregunte sobre la ascensión de Sliske.",
    ["Ask about the Staff of Armadyl"] = "Pregunta por el Staff de Armadyl",
    ["**Statue of Death: :** The Staff of Armadyl is a powerful elder god artefact which gained its name from being in Armadyl's possession. Ironically, it has been used primarily for violence in Gielinor, most notably by Zamorak to kill Zaros and Sliske to kill Guthix. It seems to be the weapon of choice if you are going to slay a god, which Sliske is now in possession of. Now Sliske is in possession of both the Stone of Jas and the Staff of Armadyl: two of the most powerful items in existence."] = "**Statue of Death: :** El Staff de Armadyl es un poderoso artefacto de dios anciano que obtuvo su nombre por estar en posesión de Armadyl. Irónicamente, se ha utilizado principalmente con fines violentos en Gielinor, sobre todo por Zamorak para matar a Zaros y Sliske para matar a Guthix. Parece ser el arma preferida si vas a matar a un dios, que ahora posee Sliske. Ahora Sliske está en posesión tanto de la Piedra de Jas como del Staff de Armadyl: dos de los objetos más poderosos que existen.",
    ["Ask about the Stone of Jas"] = "Pregunta por la Piedra de Jas",
    ["**Statue of Death: :** The Stone of Jas is a powerful elder god artefact which acts as a physical store of the elder gods' energy. Anyone who touches it is infused with incredible power but they also become a target for the dragonkin This is because the elder gods tied the dragonkin to the Stone as a defence system, cursing them for all of time. The more the Stone of Jas is used the more the power of the dragonkin increases. It is not known if there is a limit to this effect. Perhaps they could grow stronger than the gods themselves. Sliske now possesses the Stone, and is offering it as a reward to the greatest god slayer."] = "**Statue of Death: :** La Piedra de Jas es un poderoso artefacto de los dioses mayores que actúa como un almacén físico de la energía de los dioses mayores. Cualquiera que lo toque recibe un poder increíble, pero también se convierte en un objetivo para los dragonantes. Esto se debe a que los dioses mayores ataron a los dragonantes a la Piedra como sistema de defensa, maldiciéndolos para siempre. Cuanto más se usa la Piedra de Jas, más aumenta el poder de los dragonantes. No se sabe si existe un límite para este efecto. Quizás podrían volverse más fuertes que los propios dioses. Sliske ahora posee la Piedra y la ofrece como recompensa al mayor cazador de dioses.",
    ["Ask if Sliske has become a god."] = "Pregúntale si Sliske se ha convertido en un dios.",
    ["**Statue of Death: :** Hahaha! The question on everybody's lips, it would seem... You'll just have to wait to find that one out, Sliske plays his cards close to his chest. Besides, it's far too entertaining watching everyone get so wound up about it!"] = "**Statue of Death: :** ¡Jajaja! La pregunta que está en boca de todos, al parecer... Tendrás que esperar para descubrirla, Sliske juega sus cartas cerca de su pecho. Además, ¡es demasiado entretenido ver a todos tan emocionados por eso!",
    ["Back."] = "Atrás.",
    ["*(Returns to initial options)*"] = "*(Vuelve a las opciones iniciales)*",
    ["View cutscenes."] = "Ver escenas.",
    ["Sliske's Grand Entrance."] = "Gran entrada de Sliske.",
    ["*(Cutscene plays)*"] = "*(Reproducciones de escena)*",
    ["Releasing the Dragonkin."] = "Liberando al Dragonkin.",
    ["The Great Escape."] = "La gran evasión.",
    ["Where were you on the full moon?"] = "¿Dónde estabas en la luna llena?",
    ["I decided to do battle with the giant mole. It was a tough fight, but I prevailed. I am the mole slayer, FEAR THE SWING OF MY BLADE!"] = "Decidí luchar contra el topo gigante. Fue una pelea dura, pero prevalecí. Soy el asesino de topos, ¡TEME AL BOLETIN DE MI ESPADA!",
    ["Did you see anything suspicious?"] = "¿Viste algo sospechoso?",
    ["I was too busy fighting a mole. A great big mole, with sharp, pointed teeth - none of these garden-variety moles."] = "Estaba demasiado ocupado luchando contra un topo. Un gran topo, con dientes afilados y puntiagudos... ninguno de esos topos comunes.",
    ["Who do you suspect of being the werewolf?"] = "¿De quién sospechas que es el hombre lobo?",
    ["Jamie is a bit creepy. He keeps laughing when he treads on spiders. It's weird."] = "Jamie es un poco espeluznante. Sigue riéndose cuando pisa arañas. Es raro.",
    ["[Accuse Steve of being the werewolf.]"] = "[Acusa a Steve de ser el hombre lobo.]",
    ["Steve! Don't think you can hide your fangs from me! I see you for what you really are: A WEREWOLF!"] = "¡Steve! ¡No creas que puedes ocultarme tus colmillos! Te veo por lo que realmente eres: ¡UN HOMBRE LOBO!",
    ["*(Steve dies.)*"] = "*(Steve muere.)*",
    ["Ah...oops. Guess I was wrong."] = "Ah... Ups. Supongo que estaba equivocado.",
    ["*Steve dies*"] = "*Steve muere*",
    ["I have a feeling you're mostly fluff!"] = "¡Tengo la sensación de que eres casi un tonto!",
    ["Bee, over here!"] = "¡Abeja, por aquí!",
    ["Bzzzz?"] = "¿Bzzzz?",
    ["**}}:** Aw, look at your big old face!"] = "**}}:** ¡Oh, mira tu gran cara!",
    ["Stop it, tell it what you think!"] = "¡Basta, di lo que piensas!",
    ["**}}:** You've always been my least favourite!"] = "**}}:** ¡Siempre has sido mi menos favorito!",
    ["Nice!"] = "¡Bien!",
    ["Bzzzzz?"] = "¿Bzzzzz?",
    ["**}}:** You sound like a yak when you sleep!"] = "**}}:** ¡Suenas como un yak cuando duermes!",
    ["Boom!"] = "¡Auge!",
    ["**}}:** You don't even know the difference between nectar and pollen."] = "**}}:** Ni siquiera sabes la diferencia entre néctar y polen.",
    ["Nice one!"] = "¡Qué bueno!",
    ["My brother and sisters to the north-east are always looking for help with the ritual."] = "Mi hermano y mis hermanas del noreste siempre están buscando ayuda con el ritual.",
    ["I have a special request for [breed]. Especially if it has the [Trait] trait!"] = "Tengo un pedido especial para [breed]. ¡Especialmente si tiene el rasgo [Trait]!",
    ["I'm also after some Salamanders, in fact I'll buy up to [number] more while I'm here."] = "También busco algunas salamandras; de hecho, compraré hasta [número] más mientras esté aquí.",
    ["Are you sure you want me to take all the Salamanders you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todas las Salamandras que tienes? No aceptaré ninguno de tus favoritos.",
    ["**SELL ALL OF YOUR SALAMANDERS?**"] = "**¿VENDER TODAS TUS SALAMANDRAS?**",
    ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
    ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
    ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
    ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
    ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
    ["Can I help out in the factory?"] = "¿Puedo ayudar en la fábrica?",
    ["You don't look like a bunny. So, no."] = "No pareces un conejito. Entonces no.",
    ["[Complete the seasonal quest 'Great Egg-spectations' to take part in the factory line activity.]"] = "[Completa la misión de temporada \"Grandes espectáculos de huevos\" para participar en la actividad de la línea de fábrica.]",
    ["Nice title!"] = "¡Buen título!",
    ["We could never agree on a single colour..."] = "Nunca pudimos ponernos de acuerdo en un solo color...",
    ["You've unlocked the 'Chocolate' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Chocolate' para el título 'el Huevo'!",
    ["So we made one that combines all of our favourite chocolate types!"] = "¡Así que hicimos uno que combina todos nuestros tipos de chocolate favoritos!",
    ["I don't believe we've met before! I'm Sticky."] = "¡No creo que nos hayamos conocido antes! Soy pegajoso.",
    ["Hi! I'm Player."] = "¡Hola! Soy Player.",
    ["Hiya, Player!"] = "¡Hola, Player!",
    ["What brought you here?"] = "¿Qué te trajo aquí?",
    ["Mainly my children - Cocoa, Stewy, Gooey, and Chewy. They had nothing but positive things to say about this new Burrow that my brother has set up, so I had to see it for myself."] = "Principalmente mis hijos: Cocoa, Stewy, Gooey y Chewy. No tenían más que cosas positivas que decir sobre esta nueva Madriguera que mi hermano ha creado, así que tuve que verlo con mis propios ojos.",
    ["It's been lovely getting to watch them grow into the Bunny business."] = "Ha sido maravilloso verlos crecer en el negocio de Bunny.",
    ["That's sweet. Do you do any work for the Bunny business?"] = "Eso es dulce. ¿Trabajas algún trabajo para el negocio Bunny?",
    ["Not yet! But I'm hoping to propose a new honeycomb-filled chocolate to my brother at some point."] = "¡Aún no! Pero espero proponerle a mi hermano un nuevo chocolate relleno de panal en algún momento.",
    ["Though I can't take the credit for the idea - that goes to my wife, Honey. Unfortunately she's rather allergic to bees, so I'm the only one who can see this dream through to reality."] = "Aunque no puedo atribuirme el mérito de la idea, eso es para mi esposa, Honey. Desafortunadamente, ella es bastante alérgica a las abejas, así que soy el único que puede hacer realidad este sueño.",
    ["Oh, but I hope you don't take me to just be an opportunist here! I really do love the bees too. They do so much for us, it's only fair we repay them with some love and care."] = "¡Oh, pero espero que no me tomes como un simple oportunista! Realmente amo a las abejas también. Hacen tanto por nosotros que es justo que les devolvamos algo de amor y cuidado.",
    ["Tell me more about beekeeping."] = "Cuéntame más sobre la apicultura.",
    ["Can I help to look after the bees?"] = "¿Puedo ayudar a cuidar a las abejas?",
    ["The more the merrier! For the most part you can just tend to the hives, but make sure to keep an eye on anything which could disturb the bees."] = "¡Cuantos más, mejor! En su mayor parte, puedes simplemente ocuparte de las colmenas, pero asegúrate de estar atento a cualquier cosa que pueda molestar a las abejas.",
    ["Wasps will agitate them, whilst wilted flowers will upset them."] = "Las avispas los agitarán, mientras que las flores marchitas los alterarán.",
    ["If they get too agitated, well, I wouldn't recommend continuing to harvest their hives without gloves. And if they're not happy, that's sure to affect your Farming training."] = "Si se agitan demasiado, bueno, no recomendaría continuar cosechando sus colmenas sin guantes. Y si no están contentos, seguramente afectará tu entrenamiento Farming.",
    ["I've got plenty of wasp traps and flower food in the area to deal with the disturbances, so feel free to take as many as you need."] = "Tengo muchas trampas para avispas y alimento para flores en el área para hacer frente a las perturbaciones, así que siéntete libre de llevar tantas como necesites.",
    ["I also noticed a pile of metal doodads on the way in. What are they?"] = "También noté un montón de adornos de metal en el camino. ¿Qué son?",
    ["Metal doodads... Oh! The smokers! Yes, occasionally you might just lose track of the bees. That's where the smokers come in - simply use a smoker on the hive to regain track of the little bumbles."] = "Adornos metálicos... ¡Oh! ¡Los fumadores! Sí, de vez en cuando es posible que pierdas la pista de las abejas. Ahí es donde entran los fumadores: simplemente use un ahumador en la colmena para recuperar la pista de los pequeños abejorros.",
    ["Can I earn anything here?"] = "¿Puedo ganar algo aquí?",
    ["Well, in addition to Farming experience, I can also pay you some spring tokens for helping out."] = "Bueno, además de la experiencia Farming, también puedo pagarte algunas fichas de primavera por ayudar.",
    ["If you find any honeycomb shards whilst tending to the hives you're also free to keep them! I believe you can combine them into various types of complete honeycomb."] = "Si encuentras fragmentos de panal mientras cuidas las colmenas, ¡también puedes quedártelos! Creo que puedes combinarlos en varios tipos de panal completo.",
    ["Goodbye, Player!"] = "¡Adiós, Player!",
    ["Ay-uh, 'tis a grand day for the fishin'. Will ye be wantin' to exchange yer fish for banknotes?"] = "Sí, es un gran día para pescar. ¿Querrás cambiar tu pescado por billetes?",
    ["Okay, exchange all my fish for banknotes."] = "Está bien, cambia todo mi pescado por billetes.",
    ["There ye goes."] = "Ahí va.",
    ["Ahhh, ye've nothing that ol' Stiles can exchange. I'll do yer lobbies, yer swordies an' yer tuna, that's all."] = "Ahhh, no tienes nada que el viejo Stiles pueda intercambiar. Me encargaré de tus lobbys, de tus espadachines y de tu atún, eso es todo.",
    ["Who are you and why are you here?"] = "¿Quién eres y por qué estás aquí?",
    ["Ahhh, when I were a young'un my name were Nigel but, these days, folks mostly call me Stiles."] = "Ahhh, cuando era joven mi nombre era Nigel pero, hoy en día, la gente me llama principalmente Stiles.",
    ["Long time ago, in Draynor Village, there were three brothers who'd exchange yer stuff for bitty bits o' paper, like these new-fangled banknotes we've got today. Niles, Miles an' Giles they called themselves."] = "Hace mucho tiempo, en Draynor Village, había tres hermanos que cambiaban tus cosas por pedacitos de papel, como estos novedosos billetes que tenemos hoy. Niles, Miles y Giles se llamaban a sí mismos.",
    ["They be long gone, like the golden days, but they were an inspiration to me, so I took this trade myself, an' I changed my name to Stiles."] = "Ya pasaron hace tiempo, como los días dorados, pero fueron una inspiración para mí, así que tomé este oficio yo mismo y cambié mi nombre a Stiles.",
    ["But why are you here, in this place?"] = "¿Pero por qué estás aquí, en este lugar?",
    ["The smell of yon bananas were drivin' me scatty, so I can't go too near the fishing spots."] = "El olor de esos plátanos me estaba volviendo loco, así que no puedo acercarme demasiado a los lugares de pesca.",
    ["A tough-lookin' geezer callin' himself a slayer master tried to give me a nosepeg once, but I bain't wearin' one o' them things. Ol' Stiles has a tender nose."] = "Un vejete de aspecto rudo que se hace llamar slayer master intentó darme una clavija una vez, pero no puedo usar ninguna de esas cosas. Ol' Stiles tiene una nariz tierna.",
    ["So, would ye like me to exchange yer fish now?"] = "Entonces, ¿quieres que te cambie el pescado ahora?",
    ["Which fish can you exchange?"] = "¿Qué pez puedes intercambiar?",
    ["Ahhh, ol' Stiles has banknotes for yer lobbies, yer swordies and yer tuna. 'Tis a grand service I be offerin' here, and nary a penny do I ask in return."] = "Ahhh, el viejo Stiles tiene billetes para sus lobbys, sus espadachines y su atún. Es un gran servicio el que ofrezco aquí y no pido ni un centavo a cambio.",
    ["Why don't you exchange other fish?"] = "¿Por qué no intercambias otros peces?",
    ["Ahhh, I bain't looking to learn a new trade at my age. Lobbies, swordies an' tuna is enough fer ol' Stiles. Would ye like me to exchange yer fish now?"] = "Ahhh, no busco aprender un nuevo oficio a mi edad. Lobbies, espadachines y atún son suficientes para el viejo Stiles. ¿Quieres que te cambie el pescado ahora?",
    ["Hello there, I have no time to exchange right now, I'm actually on a hunt for some golden eggs."] = "Hola. No tengo tiempo para intercambiar en este momento. De hecho, estoy buscando algunos huevos de oro.",
    ["Ah-ha 'tis you that be huntin' for this then."] = "Ah-ha, entonces eres tú quien está buscando esto.",
    ["[Stiles produces a golden egg from the nearby barrel and hands it to you.]"] = "[Stiles saca un huevo de oro del barril cercano y te lo entrega.]",
    ["You found a golden egg! Cracking it open you discover your next clue."] = "¡Encontraste un huevo de oro! Al abrirlo, descubres la siguiente pista.",
    ["The following has been added to your currency pouch: 3 x Egg points."] = "Se ha agregado lo siguiente a su bolsa de divisas: 3 x puntos Egg.",
    ["The following has been added to your currency pouch: 10 x Treasure Trail Points."] = "Se ha agregado lo siguiente a su bolsa de divisas: 10 x Puntos Treasure Trail.",
    ["Perfect, thanks Stiles!"] = "Perfecto, ¡gracias Stiles!",
    ["Stiles wishes yer good luck findin' the rest of 'em."] = "Stiles te desea buena suerte para encontrar al resto.",
    ["Ye want me to exchange all yer lobbies, yer swordies an' yer tuna fer banknotes?"] = "¿Quieres que cambie todos tus lobbys, tus espadachines y tu atún por billetes?",
    ["Ah, the Stone. Known by many names, including, much to my discomfort, the Fist of Guthix."] = "Ah, la Piedra. Conocida por muchos nombres, incluido, para mi malestar, el Puño de Guthix.",
    ["Its ancient power has opened up boundless potential, and the lust for that power has irrevocably scarred this perfect world."] = "Su antiguo poder ha abierto un potencial ilimitado, y el ansia por ese poder ha marcado irrevocablemente este mundo perfecto.",
    ["The races I brought to Gielinor have fought, died and longed for it. I set these events in motion, inciting millennia of conflict and death. I hold myself accountable for these atrocities."] = "Las razas que traje a Gielinor han luchado, muerto y anhelado por ello. Puse en marcha estos acontecimientos, incitando milenios de conflicto y muerte. Me hago responsable de estas atrocidades.",
    ["I sought to share its power with mortals, that they might not be subjugated by the gods. They left their gods behind, attracted by the potential of magic."] = "Intenté compartir su poder con los mortales, para que no fueran subyugados por los dioses. Dejaron atrás a sus dioses, atraídos por el potencial de la magia.",
    ["I distilled the Stone's essence into runic magic, stones of power, but the discovery of magic spells I left in the hands of those that followed me to Gielinor."] = "Destilé la esencia de la Piedra en magia rúnica, piedras de poder, pero el descubrimiento de hechizos mágicos lo dejé en manos de aquellos que me siguieron hasta Gielinor.",
    ["The diversity of magical effects they achieved was inspiring...though many only sought mastery of only the basest elements, drawing on them for raw offensive power."] = "La diversidad de efectos mágicos que lograron fue inspiradora... aunque muchos solo buscaban el dominio de los elementos más básicos, recurriendo a ellos para obtener un poder ofensivo puro.",
    ["I should have seen this as a sign of things to come, but I hoped that in free reign they might see the harmful impact for themselves, and gain enlightenment from their destructive impulses."] = "Debería haber visto esto como una señal de lo que vendría, pero esperaba que en rienda suelta pudieran ver el impacto dañino por sí mismos y obtener iluminación de sus impulsos destructivos.",
    ["Alas, the colonists returned to me, empty-handed and hungry for more power; their desire for rune stones almost an addiction."] = "Por desgracia, los colonos regresaron a mí, con las manos vacías y hambrientos de más poder; su deseo por las piedras rúnicas es casi una adicción.",
    ["Reluctantly, I sought to indulge them, but I sensed within the Stone a growing presence: anger, violent rage."] = "De mala gana, traté de complacerlos, pero sentí dentro de la Piedra una presencia creciente: ira, rabia violenta.",
    ["It grew as I drew power from the Stone, and I feared that this terrible ferocity might be unleashed."] = "Creció a medida que extraía poder de la Piedra, y temí que esta terrible ferocidad pudiera desatarse.",
    ["I realised that I had abused the Stone's power too long, and the consequences if I persevered would be grave; so I hid the Stone, for our own protection."] = "Me di cuenta de que había abusado del poder de la Piedra durante demasiado tiempo y que las consecuencias si perseveraba serían graves; así que escondí la Piedra, para nuestra propia protección.",
    ["My refusal was poorly received. Some turned to desperate worship, others to violence over the jealously hoarded rune stones, now a precious commodity stained in spilt blood."] = "Mi negativa fue mal recibida. Algunos recurrieron a la adoración desesperada, otros a la violencia por las piedras rúnicas celosamente atesoradas, ahora un bien precioso manchado con sangre derramada.",
    ["In retrospect, I was motivated by cowardice and fatigue, but it was at this time that I withdrew into slumber."] = "En retrospectiva, me motivaron la cobardía y la fatiga, pero fue en ese momento que me quedé dormido.",
    ["I hoped that, should I awake, I might bear witness to a more civilised age."] = "Esperaba que, si despertara, podría ser testigo de una época más civilizada.",
    ["That time did not come."] = "Ese momento no llegó.",
    ["Are you one of the returned citizens?"] = "¿Es usted uno de los ciudadanos retornados?",
    ["Why, yes. You must be the adventurer who Maisa talked to us about?"] = "Pues, sí. ¿Debes ser el aventurero del que nos habló Maisa?",
    ["That would be me. Now, can you help me?"] = "Ese sería yo. Ahora, ¿puedes ayudarme?",
    ["Probably not; I'm a stone mason and have little to offer an adventurer."] = "Probablemente no; Soy cantero y tengo poco que ofrecer a un aventurero.",
    ["You know what would be brilliant?"] = "¿Sabes qué sería genial?",
    ["Could you make some granite armour or alter granite armour to better fit me?"] = "¿Podrías hacer una armadura de granito o modificarla para que me quede mejor?",
    ["I'm adraid I can't do that, sorry. In the blazing desert sun, granite armour isn't very popular so I haven't had any experience of working with it."] = "Me temo que no puedo hacer eso, lo siento. Bajo el sol abrasador del desierto, las armaduras de granito no son muy populares, así que no he tenido ninguna experiencia trabajando con ellas.",
    ["Once the place is a bit less chaotic, however, I will try to think of ways you adventurers can help. Who knows what I'll come up with."] = "Sin embargo, una vez que el lugar sea un poco menos caótico, intentaré pensar en formas en que ustedes, los aventureros, puedan ayudar. Quién sabe qué se me ocurrirá.",
    ["Should I come back soon, then?"] = "Entonces, ¿debería volver pronto?",
    ["I wouldn't hold my breath. I'm thinking it will be months before I have work for you rather than a few days."] = "No aguantaría la respiración. Creo que pasarán meses antes de que tenga trabajo para usted en lugar de unos pocos días.",
    ["Welcome, fellow dreamer."] = "Bienvenido, compañero soñador.",
    ["If you could provide me some resources from your base camp, I could create a stonemason for you to train at within this dream, and teach you something of Ilujankan construction techniques."] = "Si pudieras proporcionarme algunos recursos de tu campamento base, podría crear un cantero para que entrenes dentro de este sueño y enseñarte algo sobre las técnicas de construcción de Ilujankan.",
    ["Thank you for the stone. If you keep supplying me with more, I can teach you much about Ilujankan construction techniques."] = "Gracias por la piedra. Si sigues proporcionándome más, puedo enseñarte mucho sobre las técnicas de construcción de Ilujankan.",
    ["You are learning much of our ways. Keep on as you are, and I will share a story with you."] = "Estás aprendiendo mucho de nuestras costumbres. Sigue como estás y compartiré una historia contigo.",
    ["You have learned much. I shall soon share my tale with Pastkeeper Sharrigan."] = "Has aprendido mucho. Pronto compartiré mi historia con Pastkeeper Sharrigan.",
    ["I have recounted my tale to Pastkeeper Sharrigan. Thank you for all of your efforts. Perhaps you should train at one of the other stations for a time."] = "Le he contado mi historia a Pastkeeper Sharrigan. Gracias por todos sus esfuerzos. Quizás deberías entrenar en alguna de las otras estaciones por un tiempo.",
    ["You must build a station before you can contribute resources to it."] = "Debes construir una estación antes de poder aportarle recursos.",
    ["Contribute [number] x stone and store [number] XP in this station?"] = "¿Contribuir [número] x piedra y almacenar [número] XP en esta estación?",
    ["The stonemason now has [number]/350,000 Construction XP stored in it."] = "El cantero ahora tiene [número]/350,000 Construction XP almacenados.",
    ["You contribute to the station: [number] x stone"] = "Tu contribuyes a la estación: [número] x piedra.",
    ["You have too few of this resource to contribute to this station."] = "Tienes muy pocos recursos de este recurso para contribuir a esta estación.",
    ["This skilling station is already at maximum capacity of resources."] = "Esta estación de habilidades ya está en su máxima capacidad de recursos.",
    ["**CONTRIBUTE [NUMBER] X STONE AND STORE [NUMBER] XP IN THIS STATION?**"] = "**¿CONTRIBUIR [número] X STONE Y ALMACENAR [número] XP EN ESTA ESTACIÓN?**",
    ["Do you want to buy any stone for building? Or gold leaf?"] = "¿Quieres comprar alguna piedra para construir? ¿O pan de oro?",
    ["Yes please"] = "si por favor",
    ["What kind of stone do you sell?"] = "¿Qué tipo de piedra vendes?",
    ["A few kinds. Limestone, of course. Here in Keldagrim we're surrounded by the stuff so I can practically give it away! You'll be able to build some kinds of furniture out of that."] = "Algunos tipos. Piedra caliza, por supuesto. ¡Aquí en Keldagrim estamos rodeados de cosas así que prácticamente puedo regalarlas! Podrás construir algunos tipos de furniture a partir de eso.",
    ["Marble is much better, of course, but it costs a lot for me to get hold of it. You can make some beautiful pieces of furniture out of that."] = "El mármol es mucho mejor, claro, pero me cuesta mucho conseguirlo. Puedes hacer un hermoso pieces of furniture con eso.",
    ["I also sell gold leaf, which can be used to decorate furniture made of marble or mahogany."] = "También vendo pan de oro, que se puede utilizar para decorar furniture de mármol o caoba.",
    ["Then for the very special furniture I sell these magic stones. Only the most skilled builders can work them, but they can create a few amazing pieces of furniture with them."] = "Entonces, para el muy especial furniture, vendo estas piedras mágicas. Sólo los constructores más hábiles pueden trabajar con ellos, pero pueden crear algunos pieces of furniture increíbles con ellos.",
    ["So, do you want to buy anything?"] = "Entonces, ¿quieres comprar algo?",
    ["Talk about the Task System."] = "Hable sobre el sistema de tareas.",
    ["Dig, dig, DIG! You want to dig? You need a spade!"] = "¡Cavar, cavar, CAVAR! ¿Quieres cavar? ¡Necesitas una pala!",
    ["Yes you're right, I probably do. Where can I get one?"] = "Sí, tienes razón, probablemente sí. ¿Dónde puedo conseguir uno?",
    ["Ohh... Spades have cost me so much hassle - always being pestered for them! I ended up giving in and just putting one at each mound for you forgetful adventurers to use."] = "Ohh... Las espadas me han costado muchos problemas: ¡siempre me molestan por ellas! Terminé cediendo y simplemente poniendo uno en cada montículo para que lo usen ustedes, aventureros olvidadizos.",
    ["*Note: All of these conversations can also start with the Strange Old Man saying \"Dig, dig, dig.\" first.*"] = "*Nota: Todas estas conversaciones también pueden comenzar con el Strange Old Man diciendo \"Excavar, excavar, excavar\". primero.*",
    ["I'll leave you to it then..."] = "Entonces te dejo con eso...",
    ["Pst, wanna hear a secret?"] = "Pst, ¿quieres escuchar un secreto?",
    ["Sure!"] = "¡Claro!",
    ["They're not normal!"] = "¡No son normales!",
    ["Knock, knock."] = "Toc, toc.",
    ["A big scary monster, HAHAHAHAHAHAHAHAHAHA!"] = "¡Un gran monstruo aterrador, JAJAJAJAJAJAJAJAJAJAJAJA!",
    ["What? I didn't ask for a book!"] = "¿Qué? ¡No pedí un libro!",
    ["The...ring...Jennica..."] = "El... anillo...Jennica...",
    ["How do you know about Jennica?"] = "¿Cómo sabes sobre Jennica?",
    ["Jennica... Dig, dig, dig... Dig..."] = "Jennica... Cava, cava, cava... Cava...",
    ["Dig?"] = "¿Excavar?",
    ["I've completed all of the Hard Tasks in the Morytania set."] = "He completado todas las tareas difíciles del conjunto Morytania.",
    ["So you have. I have some special leggings kept aside for you."] = "Así que sí. Tengo unos leggings especiales reservados para ti.",
    ["[The Strange Old Man hands you a pair of leggings and a lamp.]"] = "[El Strange Old Man te entrega un par de mallas y una lámpara.]",
    ["There you go. They be a bit strange, but they should help you out when you're getting rid of pesky shades once and for all."] = "Ahí lo tienes. Pueden ser un poco extraños, pero deberían ayudarte a deshacerte de las molestas gafas de sol de una vez por todas.",
    ["Thanks! What else do they do?"] = "¡Gracias! ¿Qué más hacen?",
    ["Well, ghosties will understand you, and I've had a word with Hiylik, so you'll get better rewards for helping unfortunates to the temple. Ahh...they also protect a little from the foul influence of the Barrows, and they seem to be linked with those...tablet things you use to get to the Altar of Blood."] = "Bueno, los fantasmas te entenderán y hablé con Hiylik, por lo que obtendrás mejores recompensas por ayudar a los desafortunados a llegar al templo. Ahh... también protegen un poco de la mala influencia de los Túmulos, y parecen estar relacionados con esas... tabletas que usas para llegar al Altar de Sangre.",
    ["Ah, the leggings-wearer! How are you finding them?"] = "¡Ah, el que usa calzas! ¿Cómo los estás encontrando?",
    ["I lost them."] = "Los perdí.",
    ["Oh, no!"] = "¡Oh, no!",
    ["Never mind, I have another pair. Here..."] = "No importa, tengo otro par. Aquí...",
    ["[The Strange Old Man hands you a pair of leggings.]"] = "[El Strange Old Man te entrega un par de leggings.]",
    ["For completing the Morytania set, you are presented with some leggings."] = "Para completar el conjunto Morytania, se te presentan unos leggings.",
    ["These leggings will become increasingly useful as you complete greater difficulties of task sets."] = "Estos leggings serán cada vez más útiles a medida que completes conjuntos de tareas de mayor dificultad.",
    ["You need to complete all Tasks within a particular difficulty set, then you can claim your reward."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Morytania set's Tasks are simple, some require certain skill levels, and others require quests to be started or completed."] = "Algunas de las tareas del conjunto Morytania son simples, algunas requieren cierto skill levels y otras requieren que se inicien o completen misiones.",
    ["To claim your Morytania set rewards, speak to Hiylik Myna just east of Paterdomus, Robin in Port Phasmatys, Old Man Ral in Meiyerditch or myself."] = "Para reclamar las recompensas del conjunto Morytania, habla con Hiylik Myna justo al este de Paterdomus, Robin en Port Phasmatys, Old Man Ral en Meiyerditch o conmigo mismo.",
    ["Morytania legs 1"] = "Morytania piernas 1",
    ["Morytania legs 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "Morytania piernas 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["[You're handed another Morytania legs 1.]"] = "[Te entregan otras piernas Morytania 1.]",
    ["Morytania legs 2"] = "Morytania piernas 2",
    ["Morytania legs 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "Morytania piernas 2? Sí, pero me temo que te costaría 2500 coins.",
    ["[You're handed another Morytania legs 2.]"] = "[Te entregan otras piernas Morytania 2.]",
    ["Morytania legs 3"] = "Morytania piernas 3",
    ["Morytania legs 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "Morytania piernas 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["[You're handed another Morytania legs 3.]"] = "[Te entregan otras piernas Morytania 3.]",
    ["Morytania legs 4"] = "Morytania piernas 4",
    ["Morytania legs 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "Morytania patas 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["[You're handed another Morytania legs 4.]"] = "[Te entregan otras patas Morytania 4.]",
    ["**WHAT WOULD YOU LIKE TO DO?**"] = "**¿QUÉ TE GUSTARÍA HACER?**",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal].",
    ["If you complete this, I'll give you : A Barrows item x 1. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Un objeto de Barrows x 1. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You've received : [Reward] x [number] And 13,750 farming reputation."] = "Has recibido: [Reward] x [número] Y 13,750 reputación agrícola.",
    ["A new request will be available in [number] days, [number] hours and [number] minutes.."] = "Una nueva solicitud estará disponible en [número] días, [número] horas y [número] minutos.",
    ["You've already completed this request, there will be a new weekly request in [number] days, [number] hours and [number] minutes.."] = "Ya has completado esta solicitud, habrá una nueva solicitud semanal en [número] días, [número] horas y [número] minutos.",
    ["I don't see anything here that could be of any use to me."] = "No veo nada aquí que pueda serme útil.",
    ["I bet I could use this to make my fishing lure more attractive for the fish Laniakea has asked me to catch."] = "Apuesto a que podría usar esto para hacer que mi señuelo de pesca sea más atractivo para los peces que Laniakea me ha pedido que capture.",
    ["I already have one of these feathers sitting around somewhere, I don't need another."] = "Ya tengo una de estas plumas por ahí, no necesito otra.",
    ["It's Hallowe'en soon and we're so excited!"] = "¡Pronto será Halloween y estamos muy emocionados!",
    ["It's our favourite time of the year and we want everyone to get together wearing our favourite costume."] = "Es nuestra época favorita del año y queremos que todos nos reunamos vistiendo nuestro disfraz favorito.",
    ["You should come see me when it's time and I'll get you all prepared for the costume gathering."] = "Deberías venir a verme cuando llegue el momento y los prepararé a todos para la reunión de disfraces.",
    ["Come back on 31st October to take part in the costume gathering."] = "Vuelve el 31 de octubre para participar en el encuentro de disfraces.",
    ["You don't have a costume! Quick, put this on!"] = "¡No tienes disfraz! ¡Rápido, ponte esto!",
    ["Try on the costume."] = "Pruébate el disfraz.",
    ["You start to feel a little spooky..."] = "Empiezas a sentirte un poco espeluznante...",
    ["The costume gathering was awesome! Hopefully we can do it again next year."] = "¡La reunión de disfraces fue increíble! Ojalá podamos volver a hacerlo el año que viene.",
    ["*(The strange face does not have a chathead nor will his name appear in the chatbox; the name is included in the transcript to discern spoken lines from non-dialogue text.)*"] = "*(El strange face no tiene un chathead ni su nombre aparecerá en el cuadro de chat; el nombre se incluye en la transcripción para distinguir las líneas habladas del texto que no es de diálogo).*",
    ["You don't have the requirements to fight in the tower."] = "No tienes los requisitos para luchar en la torre.",
    ["See the requirements."] = "Ver los requisitos.",
    ["[You need to have completed at least 20 combat quests that feature bosses used in the tower. A combat level of 110 is recommended.]"] = "[Debes haber completado al menos 20 misiones de combate que incluyan jefes utilizados en la torre. Se recomienda un nivel de combate de 110.]",
    ["Ask about the Sunfreet boss."] = "Pregunta por el jefe de Sunfreet.",
    ["Woah!"] = "¡Guau!",
    ["It is intriguing that you took so long before coming to me. Fearful, traveller?"] = "Es intrigante que hayas tardado tanto en acudir a mí. ¿Miedo, viajero?",
    ["Should I be?"] = "¿Debería serlo?",
    ["It is my duty to inform you that many warriors fight here, and they all succumb to defeat eventually. If that instils terror in you, walk away now."] = "Es mi deber informarles que muchos guerreros luchan aquí y todos sucumben a la derrota eventualmente. Si eso te infunde terror, aléjate ahora.",
    ["[The Dominion Tower contains a wealth of monsters to fight. The arena is safe and you won't lose any items if you die. Would you like to try your skills against the Sunfreet?]"] = "[La Torre del Dominio contiene una gran cantidad de monstruos contra los que luchar. La arena es segura y no perderás ningún objeto si mueres. ¿Te gustaría probar tus habilidades contra el Sunfreet?]",
    ["Face the Sunfreet?"] = "¿Enfrentar al Sunfreet?",
    ["[The face on the wall groans and scowls at you. Perhaps you should talk to it first.]"] = "[The face en la pared gime y te frunce el ceño. Quizás deberías hablar con él primero.]",
    ["[You don't have the requirements to play this content, but you can spectate some of the matches taking place if you would like.]"] = "[No tienes los requisitos para jugar este contenido, pero puedes presenciar algunos de los partidos que se llevan a cabo si lo deseas.]",
    ["[A combat level of 110 or above is recommended for this content.]"] = "[Se recomienda un nivel de combate de 110 o superior para este contenido.]",
    ["Do you wish to proceed?"] = "¿Desea continuar?",
    ["There are monsters in the tower?"] = "¿Hay monstruos en la torre?",
    ["If that is the terminology you would use, yes. Through the powers bestowed upon me by my creator, I can generate opponents for you based on your memories of them. Men and women have fought here for generations."] = "Si esa es la terminología que usarías, sí. A través de los poderes que me otorgó mi creador, puedo generar oponentes para ti en función de tus recuerdos de ellos. Hombres y mujeres han luchado aquí durante generaciones.",
    ["Impressive. So, you control the tower?"] = "Impresionante. Entonces, ¿controlas la torre?",
    ["The tower is I, and I have control of the tower. I see what happens in any corner of any floor. I am always watching."] = "La torre soy yo y tengo el control de la torre. Veo lo que pasa en cualquier rincón de cualquier piso. Siempre estoy mirando.",
    ["So, you believe yourself a mighty warrior?"] = "Entonces, ¿te crees un guerrero poderoso?",
    ["Only the greatest warrior that ever lived!"] = "¡Solo el guerrero más grande que jamás haya existido!",
    ["Intriguing. Such belief in your own abilities..."] = "Intrigante. Esa creencia en tus propias habilidades...",
    ["Your confidence may have a foundation, but judgment will come in battle."] = "Tu confianza puede tener una base, pero el juicio vendrá en la batalla.",
    ["I'm pretty handy with a weapon."] = "Soy bastante hábil con un arma.",
    ["Intriguing...I sense humility in you."] = "Intrigante... Siento humildad en ti.",
    ["For your sake, I hope 'pretty handy' is an understatement."] = "Por tu bien, espero que \"bastante útil\" sea quedarse corto.",
    ["**Player:** You mentioned that you were created by someone, but why?"] = "**Player:** Mencionaste que fuiste creado por alguien, pero ¿por qué?",
    ["My purpose...must never stop..."] = "Mi propósito... nunca debe detenerse...",
    ["Sorry? Are you alright?"] = "¿Perdón? ¿Estás bien?",
    ["You must fight in the tower, warrior. Demonstrate your ability to others and learn."] = "Debes luchar en la torre, guerrero. Demuestra tu habilidad a los demás y aprende.",
    ["I'd have thought that, as a guide, you'd be a little more welcoming."] = "Pensé que, como guía, serías un poco más acogedor.",
    ["You will find I am welcoming enough."] = "Descubrirás que soy lo suficientemente acogedor.",
    ["Now, I can offer you more guidance; or, if you overflow with confidence, you can figure it out yourself. I am the tower, I am ever-present, so come to me if you change your mind."] = "Ahora puedo ofrecerte más orientación; o, si te desborda confianza, puedes resolverlo tú mismo. Yo soy la torre, estoy siempre presente, así que ven a mí si cambias de opinión.",
    ["Receive further instruction?"] = "¿Recibir más instrucciones?",
    ["You are proving to be wise."] = "Estás demostrando ser sabio.",
    ["Your choice. Come back if you change your mind."] = "Tú eliges. Vuelve si cambias de opinión.",
    ["You return. Speak."] = "Regresas. Hablar.",
    ["Can you teach me more about the tower?"] = "¿Puedes enseñarme más sobre la torre?",
    ["An inevitable question."] = "Una pregunta inevitable.",
    ["Lesson 1 - Overview"] = "Lección 1 - Descripción general",
    ["[Speaking with the tower is best done at the entrance.]"] = "[Es mejor hablar con la torre en la entrada.]",
    ["[Here there's also a bank.]"] = "[Aquí también hay un banco.]",
    ["[And a reward box for claiming your battle spoils.]"] = "[Y una caja de recompensa por reclamar el botín de batalla.]",
    ["[Here are the main stairs leading to the battles available in the tower. Upon ascending, you will be presented with five options.]"] = "[Aquí están las escaleras principales que conducen a las batallas disponibles en la torre. Al ascender, se le presentarán cinco opciones.]",
    ["[First is 'Climber'. In this mode, you will scale the tower fighting one battle per floor, each time receiving a handicap. Since the handicaps stack, the challenge intensifies the higher you go, but then so does the reward.]"] = "[El primero es 'Escalador'. En este modo, escalarás la torre librando una batalla por piso, recibiendo cada vez una desventaja. Dado que las desventajas se acumulan, el desafío se intensifica cuanto más alto llegas, pero también lo hace la recompensa.]",
    ["[Second is 'Endurance'. In this mode, you fight one monster per floor but you can only take one inventory of equipment and supplies with you. You should think wisely about your inventory management.]"] = "[En segundo lugar está la \"resistencia\". En este modo, luchas contra un monstruo por piso, pero solo puedes llevar contigo un inventario de equipos y suministros. Debe pensar sabiamente en la gestión de su inventario.]",
    ["[Third is 'Special'. In this mode, you fight one of 8 challenges, carefully configured to offer unique combat situations.]"] = "[El tercero es \"Especial\". En este modo, luchas en uno de los 8 desafíos, cuidadosamente configurados para ofrecer situaciones de combate únicas.]",
    ["[Fourth is 'Freestyle'. In this mode, you may fight any monster you have conquered in the tower so far, setting your own rules.]"] = "[El cuarto es el 'Estilo libre'. En este modo podrás luchar contra cualquier monstruo que hayas conquistado en la torre hasta el momento, estableciendo tus propias reglas.]",
    ["[Lastly is 'Spectator' mode. In this mode, you may observe the fight of a friend or choose from the more difficult battles currently in progress.]"] = "[Por último está el modo 'Espectador'. En este modo, puedes observar la pelea de un amigo o elegir entre las batallas más difíciles que se encuentran actualmente en curso.]",
    ["[Fight well and you'll receive dominion factor; this you can have converted to items by visiting the reward chests. There are also a variety of accomplishments that will unlock further rewards for you to use within and without the tower.]"] = "[Lucha bien y recibirás el factor de dominio; Esto lo puedes convertir en artículos visitando los cofres de recompensa. También hay una variedad de logros que desbloquearán más recompensas que podrás usar dentro y fuera de la torre.]",
    ["Lesson 2 - Climber Mode"] = "Lección 2 - Modo escalador",
    ["[In 'Climber', you move up the floors, fighting a battle on each level, receiving handicaps as you go.]"] = "[En 'Climber', subes de piso, peleas una batalla en cada nivel y recibes desventajas a medida que avanzas.]",
    ["[Start at the stairs. You can opt for the 'Climber' battle type, where you shall be assigned a random foe before being taken into the arena itself.]"] = "[Empiece por las escaleras. Puedes optar por el tipo de batalla 'Escalador', donde se te asignará un enemigo aleatorio antes de ser llevado a la arena.]",
    ["[This is where you will arrive. You can leave this way and come back later, but you must fight your current boss or claim your rewards before playing another battle type.]"] = "[Aquí es donde llegarás. Puedes salir de esta manera y volver más tarde, pero debes luchar contra tu jefe actual o reclamar tus recompensas antes de jugar otro tipo de batalla.]",
    ["[When you are ready, proceed through these gates and you will be required to pick a handicap.]"] = "[Cuando esté listo, pase por estas puertas y se le pedirá que elija una discapacidad.]",
    ["[There are 22 handicaps in total. Most will hinder, few will assist. How problematic they are depends on your fighting style and skill.]"] = "[Hay 22 handicaps en total. La mayoría obstaculizará, pocos ayudarán. Lo problemáticos que sean depende de tu estilo y habilidad de lucha.]",
    ["[With the handicap selected, you will be placed in the arena to fight your foe. If you die, you will spawn back at the entrance and won't lose any items.]"] = "[Con la desventaja seleccionada, serás colocado en la arena para luchar contra tu enemigo. Si mueres, reaparecerás en la entrada y no perderás ningún objeto.]",
    ["[Should you win, you'll be free to go through the exit gate.]"] = "[Si ganas, podrás pasar por la puerta de salida.]",
    ["[For success, you receive a dominion factor based on the level of challenge you faced in battle. This increases dramatically as you climb the floors. After a battle in 'Climber' mode, you have a choice:]"] = "[Para tener éxito, recibes un factor de dominio basado en el nivel de desafío que enfrentaste en la batalla. Esto aumenta dramáticamente a medida que subes los pisos. Después de una batalla en el modo 'Escalador', tienes una opción:]",
    ["[You can ascend these stairs to the next floor and face a battle made more difficult with an additional handicap and a greater reward. But, if you die in the next battle, you will lose most of the dominion factor earned so far.]"] = "[Podrás subir estas escaleras hasta el siguiente piso y afrontar una batalla aún más difícil con una desventaja adicional y una recompensa mayor. Pero, si mueres en la próxima batalla, perderás la mayor parte del factor de dominio ganado hasta el momento.]",
    ["[You can leave and come back another time to fight. You won't lose the dominion factor you have earned by leaving.]"] = "[Puedes irte y volver en otro momento para luchar. No perderás el factor de dominio que te has ganado al irte.]",
    ["[Or, if you feel you have fought to the very limits of your abilities, you can claim all the dominion factor you have collected so far from the reward box. So in this mode you will want to fight as high as your skill permits - it's up to you to figure out your limit!]"] = "[O, si sientes que has luchado hasta el límite de tus habilidades, puedes reclamar todo el factor de dominio que has acumulado hasta ahora en la caja de recompensas. Así que en este modo querrás luchar tan alto como tu habilidad te lo permita. ¡Depende de ti determinar tu límite!]",
    ["[There is also a bank chest on every floor to prepare yourself for the next battle.]"] = "[También hay un cofre del banco en cada piso para prepararte para la próxima batalla.]",
    ["Lesson 3 - Endurance Mode"] = "Lección 3 - Modo de resistencia",
    ["[In 'Endurance', you will rise up the floors, fighting a battle on each floor. You won't receive any handicaps, but you will not be able to access your bank to replenish items or change combat equipment.]"] = "[En 'Endurance', subirás pisos y librarás una batalla en cada piso. No recibirás ninguna desventaja, pero no podrás acceder a tu banco para reponer artículos o cambiar equipo de combate.]",
    ["[When you have all the items required for battle, start again at the stairs by selecting 'Endurance'. You will then be assigned a random battle, before being taken to the arena.]"] = "[Cuando tengas todos los elementos necesarios para la batalla, comienza de nuevo en las escaleras seleccionando \"Resistencia\". Luego se te asignará una batalla aleatoria antes de ser llevado a la arena.]",
    ["[In the arena, you can leave but it will reset your progress and dominion factor.]"] = "[En la arena, puedes salir pero esto restablecerá tu progreso y factor de dominio.]",
    ["[Start by passing through the gate, into the arena...]"] = "[Comience pasando por la puerta, hacia la arena...]",
    ["[You will fight your battles with whatever you are carrying. If you lose, you will be back at the entrance with all the dominion factor you have earned so far.]"] = "[Pelearás tus batallas con lo que sea que lleves. Si pierdes, volverás a la entrada con todo el factor de dominio que has ganado hasta el momento.]",
    ["[If you win, you will get a dominion factor based on the level of the challenge you just overcame, and will be free to go through the exit gate.]"] = "[Si ganas, obtendrás un factor de dominio basado en el nivel del desafío que acabas de superar y podrás atravesar la puerta de salida.]",
    ["[You then have a choice. You can go up a level and fight the next boss, and, since you don't lose dominion factor for dying, there is nothing to risk but your time.]"] = "[Entonces tienes una opción. Puedes subir de nivel y luchar contra el siguiente jefe y, como no pierdes factor de dominio al morir, no hay nada que arriesgar excepto tu tiempo.]",
    ["[Or, you can claim your reward or exit back to the entrance, which means you won't be able to go to the next floor.]"] = "[O puede reclamar su recompensa o regresar a la entrada, lo que significa que no podrá pasar al siguiente piso.]",
    ["[The goal here is to survive as many fights as possible with only one set of items. Since the bosses vary and you don't have an infinite supply of food, this will prove difficult!]"] = "[El objetivo aquí es sobrevivir a tantas peleas como sea posible con un solo conjunto de elementos. Dado que los jefes varían y no tienes un suministro infinito de alimentos, ¡esto resultará difícil!]",
    ["Lesson 4 - Special Mode"] = "Lección 4 - Modo Especial",
    ["[In 'Special', you get to choose from one of eight specially designed battles. These vary in challenge and rules. For example, fighting all the dagannoth bosses simultaneously.]"] = "[En 'Especial', puedes elegir entre una de las ocho batallas especialmente diseñadas. Estos varían en desafío y reglas. Por ejemplo, luchar contra todos los jefes dagannoth simultáneamente.]",
    ["[Start by visiting the stairs and selecting the 'Special' battle type. From here, you will be shown a selection of battles to choose from.]"] = "[Comience visitando las escaleras y seleccionando el tipo de batalla \"Especial\". Desde aquí, se te mostrará una selección de batallas para elegir.]",
    ["[After your selection, you will be taken to the arena to fight the battle. If you die, you get nothing. If you win, you get dominion factor, which is a set amount for each battle.]"] = "[Después de tu selección, serás llevado a la arena para pelear la batalla. Si mueres, no obtienes nada. Si ganas, obtienes el factor de dominio, que es una cantidad fija para cada batalla.]",
    ["[If you want to try another battle, head up the spiral stairs. If you don't, you can head down.]"] = "[Si quieres intentar otra batalla, sube las escaleras de caracol. Si no lo haces, puedes bajar.]",
    ["[You can collect your dominion factor here or at the entrance.]"] = "[Puedes recoger tu factor de dominio aquí o en la entrada.]",
    ["Lesson 5 - Freestyle Mode"] = "Lección 5 - Modo estilo libre",
    ["[In 'Freestyle', you are free to choose the opponents you will face. Keep in mind that you will only be set against bosses that you have faced previously in the outside world and that you have beaten in Endurance or Climber mode.]"] = "[En 'Freestyle', eres libre de elegir a los oponentes a los que te enfrentarás. Ten en cuenta que solo te enfrentarás a jefes a los que te hayas enfrentado anteriormente en el mundo exterior y a los que hayas vencido en el modo Resistencia o Escalador.]",
    ["[You will not get any rewards for fighting this way. Instead, this option enables you to practice your tactics against certain bosses or demonstrate your fighting prowess to others.]"] = "[No obtendrás ninguna recompensa por luchar de esta manera. En cambio, esta opción te permite practicar tus tácticas contra ciertos jefes o demostrar tu destreza en la lucha a otros.]",
    ["Lesson 6 - Rumble Mode"] = "Lección 6 - Modo Rumble",
    ["[Rumble Mode is a multi-player mode in which you will face multiple bosses.]"] = "[Rumble Mode es un modo multijugador en el que te enfrentarás a múltiples jefes.]",
    ["[You can pick how many players you want to enter the fight with you. You may also put a password key onto your fight to prevent strangers from interrupting.]"] = "[Puedes elegir cuántos jugadores quieres que participen en la pelea contigo. También puedes poner una contraseña en tu pelea para evitar que extraños interrumpan.]",
    ["[Once you begin you will be faced with multiple bosses which will spawn in staggered waves. You will need to beat them quickly or be overwhelmed!]"] = "[Una vez que comiences, te enfrentarás a múltiples jefes que aparecerán en oleadas escalonadas. ¡Tendrás que vencerlos rápidamente o sentirte abrumado!]",
    ["[If you die you will not be able to jump back into the fight, but you will automatically spectate the rest of the fight.]"] = "[Si mueres, no podrás volver a la pelea, pero automáticamente serás espectador del resto de la pelea.]",
    ["[For surviving in Rumble Mode you will be able to unlock titles and unique items.]"] = "[Para sobrevivir en el modo Rumble podrás desbloquear títulos y elementos únicos.]",
    ["[These include the supreme medallion, which works like the super dominion medallion, but gives higher stats and more teleports.]"] = "[Estos incluyen el medallón supremo, que funciona como el medallón de superdominio, pero ofrece estadísticas más altas y más teletransportes.]",
    ["Lesson 7 - Spectator Mode"] = "Lección 7 - Modo Espectador",
    ["[The 'Spectator' option lets you watch battles others are performing. You have two basic options: to tag another fighter with your dominion medallion and watch their battle, or to select from a list of battles currently taking place.]"] = "[La opción 'Espectador' te permite ver las batallas que realizan otros. Tienes dos opciones básicas: etiquetar a otro luchador con tu medallón de dominio y ver su batalla, o seleccionar de una lista de batallas que se están llevando a cabo actualmente.]",
    ["[To tag a fighter with your dominion medallion, simply use it on them. They have to be accepting aid.]"] = "[Para etiquetar a un luchador con tu medallón de dominio, simplemente úsalo sobre él. Tienen que aceptar ayuda.]",
    ["[The fighter must then go into a battle, which can be of any type.]"] = "[El luchador debe entonces entrar en una batalla, que puede ser de cualquier tipo.]",
    ["[You can then visit the stairs and select to be a spectator. You will be offered the option to view that fighter's battle.]"] = "[Luego puedes visitar las escaleras y seleccionar ser espectador. Se te ofrecerá la opción de ver la batalla de ese luchador.]",
    ["[You will be taken to the spectator area around the arena. You can leave at any time by going down the stairs.]"] = "[Serás llevado al área de espectadores alrededor de la arena. Puedes salir en cualquier momento bajando las escaleras.]",
    ["[To get a better view of the action, click on any of the spectator eyes. They all operate in the same way.]"] = "[Para obtener una mejor vista de la acción, haga clic en cualquiera de los ojos del espectador. Todos operan de la misma manera.]",
    ["[For the other option for spectating a match, go to the entrance stairs, then under the spectator option you can view other battles in progress. These are not all battles, but a selection of the most difficult ones taking place.]"] = "[Para la otra opción de ver una partida, ve a las escaleras de entrada, luego, en la opción de espectador, podrás ver otras batallas en progreso. Estas no son todas las batallas, sino una selección de las más difíciles que tienen lugar.]",
    ["[When starting any battle, you will find an option to allow you to toggle whether others can be a spectator to your match.]"] = "[Al comenzar cualquier batalla, encontrarás una opción que te permitirá alternar si otros pueden ser espectadores de tu partida.]",
    ["Lesson 8 - Rewards"] = "Lección 8 - Recompensas",
    ["[After a battle you are awarded dominion factor. Visit a reward chest, either in the arena or here at the entrance, and the tower will fill the box with items based on the dominion factor you have.]"] = "[Después de una batalla se te concede el factor de dominio. Visita un cofre de recompensa, ya sea en la arena o aquí en la entrada, y la torre llenará la caja con elementos según el factor de dominio que tengas.]",
    ["[The power-up items can only be used within the tower. There are various bombs, which deal damage to bosses, and three dominion weapons of impressive power. There's also a special horn. If you call from it, the tower will provide extra food in the arena.]"] = "[Los elementos de encendido solo se pueden usar dentro de la torre. Hay varias bombas que causan daño a los jefes y tres armas de dominio de un poder impresionante. También hay una bocina especial. Si llamas desde ahí, la torre te proporcionará comida extra en la arena.]",
    ["[The tower is tracking your accomplishments, and will reward you with special items. If you talk to the tower further, he will show you the list and what he wants you to perform to obtain them. Some of these items can be used within the tower, and some you can take and use elsewhere!]"] = "[La torre rastrea tus logros y te recompensará con artículos especiales. Si hablas más con la torre, él te mostrará la lista y lo que quiere que hagas para obtenerlos. ¡Algunos de estos elementos se pueden usar dentro de la torre y otros puedes llevarlos y usarlos en otro lugar!]",
    ["Lesson 9 - Extra Information"] = "Lección 9 - Información adicional",
    ["[There's a scoreboard down at the entrance, if you want to see what others have achieved recently.]"] = "[Hay un marcador en la entrada, si quieres ver lo que otros han logrado recientemente.]",
    ["[If you're lucky, you'll find journal pages. Some warrior decided to chronicle the tower's past. If you speak with the tower with some pages, he will provide a journal for you to store the pages in.]"] = "[Si tienes suerte, encontrarás páginas de diario. Algún guerrero decidió hacer una crónica del pasado de la torre. Si hablas con la torre con algunas páginas, él te proporcionará un diario para que las guardes.]",
    ["Could I have a look at these rewards you mentioned?}}"] = "¿Puedo echar un vistazo a estas recompensas que mencionaste?}}",
    ["Mortals are so goal-driven."] = "Los mortales están muy motivados por objetivos.",
    ["May I have a dominion medallion?"] = "¿Puedo tener un medallón de dominio?",
    ["[The face coughs out a dominion medallion. Note that the medallion will boost your combat stats when in an arena, but when you remove it, it will take away any boosts you have.]"] = "[The face tose un medallón de dominio. Ten en cuenta que el medallón aumentará tus estadísticas de combate cuando estés en una arena, pero cuando lo elimines, te quitará cualquier mejora que tengas.]",
    ["There. Rub the medallion and it will bring you back here."] = "Ahí. Frota el medallón y te traerá de vuelta aquí.",
    ["You already have one."] = "Ya tienes uno.",
    ["Can you tell me more about the tower's history?"] = "¿Puedes contarme más sobre la historia de la torre?",
    ["You mean MY history?"] = "¿Te refieres a MI historia?",
    ["I guess so."] = "Supongo que sí.",
    ["It is astounding how mortals are driven to learn about ancient times, and things they have no control over."] = "Es sorprendente cómo los mortales se ven impulsados a aprender sobre la antigüedad y cosas sobre las que no tienen control.",
    ["I was built many of your generations ago, by a man simply known as 'The Founder'. He desired a place to observe warriors and how they handled themselves in extreme combat situations. He was not a fighter himself, but he was fascinated by the abilities of others."] = "Fui construido hace muchas de tus generaciones, por un hombre conocido simplemente como 'El Fundador'. Quería un lugar para observar a los guerreros y cómo se comportaban en situaciones extremas de combate. Él mismo no era un luchador, pero estaba fascinado por las habilidades de los demás.",
    ["He wanted this tower to live on long after he was dead. His legacy to the world. Upon finishing its construction, he bound me to it, not trusting mortal men to look after it."] = "Quería que esta torre siguiera viva mucho después de su muerte. Su legado al mundo. Al terminar su construcción, me ató a él, sin confiar en hombres mortales para cuidarlo.",
    ["That's it?"] = "¿Eso es todo?",
    ["Other humans have noted my history. If you are fortunate, you will find some among the spoils of your battles."] = "Otros humanos han notado mi historia. Si tienes suerte, encontrarás algo entre el botín de tus batallas.",
    ["Have you anything to help me store journal pages?"] = "¿Tiene algo que pueda ayudarme a almacenar las páginas del diario?",
    ["Collecting information about my history? Curious. I shall see what I have in my archives."] = "¿Recopilando información sobre mi historial? Curioso. Veré lo que tengo en mis archivos.",
    ["[The face spits out a journal for you.]"] = "[The face te escupe un diario.]",
    ["Attach your pages to the book. Magic will bind them in place."] = "Adjunte sus páginas al libro. Magic los unirá en su lugar.",
    ["Actually, I've nothing to say."] = "En realidad, no tengo nada que decir.",
    ["Strange."] = "Extraño.",
    ["Er... Nothing."] = "Er... Nada.",
    ["I think we've been through this before, haven't we?"] = "Creo que ya hemos pasado por esto antes, ¿no?",
    ["What's through that door?"] = "¿Qué hay a través de esa puerta?",
    ["Hey! You can't go in there. Only authorised personnel of the VTAM Corporation are allowed beyond this point."] = "¡Oye! No puedes entrar allí. Sólo el personal autorizado de VTAM Corporation puede pasar de este punto.",
    ["How do I get a job with the VTAM corporation?"] = "¿Cómo consigo un trabajo en la corporación VTAM?",
    ["Get a copy of the Varrock Herald. If we have any positions right now, they'll be advertised in there."] = "Obtenga una copia de Varrock Herald. Si tenemos algún puesto en este momento, se anunciará allí.",
    ["Sorry. That's classified information."] = "Lo siento. Esa es información clasificada.",
    ["You stay away from there! Black Arm dog!"] = "¡Mantente alejado de allí! ¡Perro de brazo negro!",
    ["This is a private business. As in, ask too many questions and you get kicked in the privates."] = "Este es un negocio privado. A Entra, haz demasiadas preguntas y te echarán en privado.",
    ["Yeah, it's been a highlight of the past few minutes."] = "Sí, ha sido lo más destacado de los últimos minutos.",
    ["The Shield of Arrav is back in the Museum!"] = "¡El Escudo de Arrav está de vuelta en el Museo!",
    ["I'm glad we could come to an arrangement that didn't involve running, screaming or disembowelment."] = "Me alegro de que pudiéramos llegar a un acuerdo que no implicara correr, gritar o destripar.",
    ["Tell me about the Shield of Arrav."] = "Háblame del Escudo de Arrav.",
    ["That's a blast from the past! We stole that from the museum years ago!"] = "¡Eso es una explosión del pasado! ¡Lo robamos del museo hace años!",
    ["Over thirty years ago, the Phoenix Gang were subject to infighting and the shield got broken in half."] = "Hace más de treinta años, la banda Phoenix estuvo sujeta a luchas internas y el escudo se rompió por la mitad.",
    ["Shortly after the fight, some gang members decided they didn't want to be part of our gang any more."] = "Poco después de la pelea, algunos pandilleros decidieron que ya no querían ser parte de nuestra pandilla.",
    ["Katrine and her lackeys split off to form their own gang. The Black Arm Gang."] = "Katrine y sus lacayos se separaron para formar su propia pandilla. La banda del brazo negro.",
    ["On their way out, they looted what they could from us - which included one of the halves of the shield. We've been rivals with the Black Arm ever since."] = "Al salir, nos saquearon lo que pudieron, que incluía una de las mitades del escudo. Hemos sido rivales del Black Arm desde entonces.",
    ["That was only the start of our troubles. When Zemouregal invaded Varrock, he came after both gangs. He wanted each half of the shield."] = "Ese fue solo el comienzo de nuestros problemas. Cuando Zemouregal invadió Varrock, persiguió a ambas bandas. Quería cada mitad del escudo.",
    ["After he killed Katrine and I, he brought us back as zombies."] = "Después de que nos mató a Katrine y a mí, nos trajo de vuelta como zombis.",
    ["What happened to the shield after that?"] = "¿Qué pasó con el escudo después de eso?",
    ["I don't really know. Zemouregal stored the two halves in separate vaults. Maybe only Arrav can make it work?"] = "Realmente no lo sé. Zemouregal almacenó las dos mitades en bóvedas separadas. ¿Quizás sólo Arrav pueda hacerlo funcionar?",
    ["I've lost my lockpick..."] = "He perdido mi ganzúa...",
    ["[Straven gives you a new lockpick.]"] = "[Straven te ofrece una nueva ganzúa.]",
    ["I hope no one stole it from you. That would never do."] = "Espero que nadie te lo haya robado. Eso nunca serviría.",
    ["I've lost my crossbow..."] = "He perdido mi ballesta...",
    ["[Straven replaces your crossbow.]"] = "[Straven reemplaza tu ballesta.]",
    ["I've lost my grapple..."] = "He perdido mi agarre...",
    ["[Straven replaces your grapple.]"] = "[Straven reemplaza tu garfio.]",
    ["Get out of here, Black Arm lackey!"] = "¡Fuera de aquí, lacayo de Brazo Negro!",
    ["Who's a good boy?"] = "¿Quién es un buen chico?",
    ["*happy barking*"] = "*ladridos felices*",
    ["The dog happily eats the treat."] = "El perro come felizmente la golosina.",
    ["You give the dog some nice bones. It happily gnaws on them."] = "Le das al perro unos buenos huesos. Felizmente los roe.",
    ["*If the achievement 'Dog and Bone' hasn't been completed:*"] = "*Si no se ha completado el logro 'Perro y Hueso':*",
    ["Congratulations! You have completed: 'Dog and Bone' - Give a bone to one of Varrock's stray dogs (or to your pet stray dog if you have one)."] = "¡Felicitaciones! Has completado: 'Perro y Hueso' - Dale un hueso a uno de los perros callejeros de Varrock (o a tu mascota stray dog si tienes una).",
    ["You give the dog a nice piece of meat. It gobbles it up."] = "Le das al perro un buen trozo de carne. Se lo traga.",
    ["The dog doesn't seem interested in that."] = "El perro no parece interesado en eso.",
    ["Hello there little fellow."] = "Hola, pequeño.",
    ["I'm not little and if you say that again I'll gut you."] = "No soy pequeño y si vuelves a decir eso te destriparé.",
    ["Easy there, I didn't mean to offend."] = "Tranquilo, no quise ofender.",
    ["I'll let you off this once. Well what do you want? Information?"] = "Te dejaré ir por esta vez. Bueno, ¿qué quieres? ¿Información?",
    ["Yes tell me about..."] = "Sí, cuéntame sobre...",
    ["The Menaphites"] = "Los menafitas",
    ["Tell me about the Menaphites."] = "Háblame de los menafitas.",
    ["They're a bad bunch, always starting fights down in the Asp and Snake. Word on the street is that they're led by some deranged priest. Though nobody gets to see him as he deals through Rashid the Operator. They are planning something but they're such a close knit group that little ever slips out."] = "Son un grupo malo, siempre inician peleas en Asp y Snake. Se dice en la calle que están dirigidos por algún sacerdote trastornado. Aunque nadie puede verlo mientras negocia a través de Rashid the Operator. Están planeando algo, pero son un grupo tan unido que nunca se les escapa nada.",
    ["Well do you need any other information then?"] = "Bueno, ¿entonces necesitas alguna otra información?",
    ["Come back if you need any info about anything in the town."] = "Vuelve si necesitas información sobre algo en la ciudad.",
    ["I will do thanks."] = "Lo haré, gracias.",
    ["The bandits"] = "los bandidos",
    ["Tell me about the bandits."] = "Háblame de los bandidos.",
    ["There's not much really to say about them, they're just a group of local thugs led by the largest amongst them. They don't harbour the ambitions of the Menaphites."] = "Realmente no hay mucho que decir sobre ellos, son solo un grupo de matones locales liderados por el más grande de ellos. No albergan las ambiciones de los menafitas.",
    ["The Mayor"] = "el alcalde",
    ["Tell me about the mayor."] = "Háblame del alcalde.",
    ["The mayor is a spineless coward. The current state of the town is all his fault. He didn't stand up to the Menaphites when they first came to town. When he finally realised his mistake he hired a group of thugs to try get rid of them."] = "El alcalde es un cobarde sin carácter. El estado actual del pueblo es todo culpa suya. No se enfrentó a los menafitas cuando llegaron por primera vez a la ciudad. Cuando finalmente se dio cuenta de su error, contrató a un grupo de matones para intentar deshacerse de ellos.",
    ["When they discovered him to be weak they turned against him too. Thus causing an even larger mess."] = "Cuando descubrieron que era débil, también se volvieron contra él. Provocando así un desastre aún mayor.",
    ["The town"] = "la ciudad",
    ["Tell me about the town."] = "Cuéntame sobre la ciudad.",
    ["Not much to say about it. Pollivneach is a small town located between Al Kharid and Menaphos and has a particularly bad crime problem. Besides that nothing much happens here."] = "No hay mucho que decir al respecto. Pollivneach es una pequeña ciudad situada entre Al Kharid y Menaphos y tiene un problema de delincuencia especialmente grave. Además de eso, aquí no pasa mucho.",
    ["Hey there!"] = "¡Hola!",
    ["Did you see the way I distracted that guy? Man I'm one smooth operator!"] = "¿Viste la forma en que distraí a ese tipo? ¡Hombre, soy un operador suave!",
    ["Ya you were good alright."] = "Estuviste bien, ¿verdad?",
    ["So where's my money?"] = "Entonces, ¿dónde está mi dinero?",
    ["What money?"] = "¿Qué dinero?",
    ["Don't play stupid with me, I'm better at it. Where's my money?"] = "No te hagas el estúpido conmigo, soy mejor en eso. ¿Dónde está mi dinero?",
    ["Oh that money! I don't think you deserve it!"] = "¡Oh, ese dinero! ¡No creo que te lo merezcas!",
    ["Liar, thief!"] = "¡Mentiroso, ladrón!",
    ["How observant of you!"] = "¡Qué observador de tu parte!",
    ["Give me my money!"] = "¡Dame mi dinero!",
    ["Make me!"] = "¡Hazme!",
    ["You'll be sorry!"] = "¡Te arrepentirás!",
    ["Here you go, thanks."] = "Aquí tienes, gracias.",
    ["colour=#EB2F2F"] = "color=#EB2F2F",
    ["Here I go what? You haven't got any money!"] = "¿Aquí voy, qué? ¡No tienes dinero!",
    ["Thanks [sir/ma'am], I didn't think you would hold up your side of the deal. There's not much honour among thieves, you know."] = "Gracias [sir/ma'am], no pensé que cumplirías tu parte del trato. No hay mucho honor entre los ladrones, ¿sabes?",
    ["Yes tell me about...."] = "Sí, cuéntame sobre...",
    ["There's not much really to say about them, they're just a group of local thugs led by the largest among them. They don't harbour the ambitions of the Menaphites."] = "Realmente no hay mucho que decir sobre ellos, son solo un grupo de matones locales liderados por el más grande de ellos. No albergan las ambiciones de los menafitas.",
    ["Tell me about the Mayor."] = "Háblame del alcalde.",
    ["Ali Morrisane's nephew"] = "sobrino de Ali Morrisane",
    ["Tell me about Ali Morrisane's nephew."] = "Háblame del sobrino de Ali Morrisane.",
    ["He was ok, although he used to kick us when he caught any of us stealing from his stall."] = "Estaba bien, aunque solía patearnos cuando nos pillaba robando en su puesto.",
    ["Do you know where he is now then?"] = "¿Sabes dónde está ahora?",
    ["He disappeared around a week ago, he was involved in some dodgy business with both the gangs. I think he scammed them. Whether he got away with it or they got him I don't know, but I reckon if you gained either of the gangs' trust they may let you in on some more info."] = "Desapareció hace aproximadamente una semana, estuvo involucrado en algún negocio dudoso con ambas pandillas. Creo que los estafó. No sé si se salió con la suya o si lo atraparon, pero creo que si te ganaste la confianza de alguna de las pandillas, es posible que te den más información.",
    ["Not much really to say about it. Pollnivneach is a small town located between Al Kharid and Menaphos and has a particularly bad crime problem. Besides that nothing much happens here."] = "Realmente no hay mucho que decir al respecto. Pollnivneach es una pequeña ciudad ubicada entre Al Kharid y Menaphos y tiene un problema de delincuencia particularmente grave. Además de eso, aquí no pasa mucho.",
    ["Thief! Thief!"] = "¡Ladrón! ¡Ladrón!",
    ["Shut up! Don't cause any more trouble or you'll regret it."] = "¡Cállate! No provoques más problemas o te arrepentirás.",
    ["Give me double and I'll be quiet!"] = "¡Dame el doble y me callaré!",
    ["Sorry, I don't have enough money on me, I'll give it to you the next time we meet."] = "Lo siento, no tengo suficiente dinero encima, te lo daré la próxima vez que nos veamos.",
    ["I've heard that before. If you don't give me the money, you will be sorry."] = "Ya había oído eso antes. Si no me das el dinero, lo lamentarás.",
    ["Ok here you go - you thief."] = "Ok, aquí tienes, ladrón.",
    ["Hi! Do you want to go rob some more people? I could do with some more money."] = "¡Hola! ¿Quieres ir a robar a más personas? Me vendría bien algo más de dinero.",
    ["Ok, lets do it again."] = "Ok, hagámoslo de nuevo.",
    ["There doesn't seem to be anyone around to rob at the moment. Perhaps we can try again later."] = "No parece haber nadie cerca a quien robar en este momento. Quizás podamos volver a intentarlo más tarde.",
    ["I don't think that trick will work here again! It's a small town and people talk."] = "¡No creo que ese truco vuelva a funcionar aquí! Es un pueblo pequeño y la gente habla.",
    ["Well do you need any information then?"] = "Bueno, ¿entonces necesitas alguna información?",
    ["No thanks, I think I have a fair idea of what is going on in the town now."] = "No, gracias. Creo que tengo una idea bastante clara de lo que está pasando en la ciudad ahora.",
    ["This cheeky gublinch claimed to be a Jagex Moderator! He was reported straight away and dealt with."] = "¡Este descarado gublin afirmó ser moderador de Jagex! Fue denunciado de inmediato y atendido.",
    ["This wretched gublinch was asking a player for his telephone number. The player helped us catch him by refusing to give their information away and reporting the gublinch straight away!"] = "Este desgraciado le pedía a un jugador su número de teléfono. ¡el player nos ayudó a atraparlo negándose a revelar su información y denunciando al gublin de inmediato!",
    ["This sly gublinch wanted to meet one of his player friends in the real world. The player obviously refused and reported him straight away."] = "Este astuto gublin quería conocer a uno de sus amigos jugadores en el mundo real. el player obviamente se negó y lo denunció de inmediato.",
    ["This vile gublinchette was asking a player for his home address. The clever player didn't give her their address, but used the Report Abuse button to report her instead."] = "Esta vil gublinchette le estaba preguntando a un jugador la dirección de su casa. El inteligente jugador no le dio su dirección, sino que utilizó el botón Informar abuso para denunciarla.",
    ["This sneaky gublinch wanted to set up a webcam conversation with a player! The player refused and sensibly used the Report Abuse button to enable us to catch him."] = "¡Este astuto gublin quería entablar una conversación por cámara web con un jugador! el player se negó y utilizó sensatamente el botón Informar abuso para permitirnos atraparlo.",
    ["This evil gublinch asked a player where she went to college. The player was smart enough to not tell the gublinch and reported him instead."] = "Este malvado gublin le preguntó a un jugador dónde iba a la universidad. el player fue lo suficientemente inteligente como para no decírselo al gublinch y, en cambio, lo denunció.",
    ["This naughty gublinchette gave a player her email address. The wise player hit the Report Abuse button straight away, allowing us to catch her!"] = "Esta gublinchette traviesa le dio a un jugador su dirección de correo electrónico. ¡El jugador inteligente presionó el botón Report Abuse inmediatamente, permitiéndonos atraparla!",
    ["You look like an accomplished strykewyrm hunter."] = "Pareces un strykewyrm hunter consumado.",
    ["Hey, are you going to the abbey?"] = "Oye, ¿vas a la abadía?",
    ["The abbey?"] = "¿La abadía?",
    ["The Abbey of Saint Elspeth? It's the only place that path leads."] = "¿La Abadía de Santa Elspeth? Es el único lugar al que conduce ese camino.",
    ["Well, if you're heading to the abbey, you should keep your ears open. Their music is famous all over the world."] = "Bueno, si te diriges a la abadía, debes mantener los oídos abiertos. Su música es famosa en todo el mundo.",
    ["I can hear 'em sometimes, when the wind is right. Times like that, I don't mind I'm not catching any strykewyrms."] = "A veces puedo oírlos, cuando el viento sopla. En momentos así, no me importa no atrapar ningún strykewyrms.",
    ["The One Piercing Note quest is fully voice-acted and features live recorded music. We suggest that you turn your sound on in order to get the most out of it."] = "La misión One Piercing Note está totalmente interpretada por voz y cuenta con música grabada en vivo. Le sugerimos que active el sonido para aprovecharlo al máximo.",
    ["Well, you're going the wrong way, then. The only place that path leads is the abbey."] = "Bueno, entonces vas por el camino equivocado. El único lugar al que conduce ese camino es la abadía.",
    ["Hello there. Could I ask you about th-"] = "Hola. ¿Puedo preguntarte sobre eso?",
    ["Hmph! Don't you know anything? It not safe to talk right now."] = "¡Hmph! ¿No sabes nada? No es seguro hablar ahora.",
    ["But you don't even know what I was going to ask."] = "Pero ni siquiera sabes lo que iba a preguntar.",
    ["I know enough to know it not safe to talk unless we on members' world."] = "Sé lo suficiente como para saber que no es seguro hablar a menos que estemos en el mundo de miembros.",
    ["Hi there!"] = "¡Hola!",
    ["Hmmph. Hi yourself."] = "Hmmph. Hola a ti mismo.",
    ["That doesn't sound very friendly!"] = "¡Eso no suena muy amigable!",
    ["It hard to feel friendly when feet hurt."] = "Es difícil sentirse amigable cuando te duelen los pies.",
    ["I take your point. Have you tried, you know, just sitting down?"] = "Entiendo tu punto. ¿Has intentado, ya sabes, simplemente sentarte?",
    ["Sitting makes back hurt."] = "Sentarse hace que duela la espalda.",
    ["Ah. That is a dilemma."] = "Ah. Ése es un dilema.",
    ["Hi there. I was wondering if you could help me out."] = "Hola. Me preguntaba si podrías ayudarme.",
    ["Sorry. Can't hear you. My ears too cold and my feet hurt."] = "Lo siento. No puedo oírte. Mis oídos están demasiado fríos y me duelen los pies.",
    ["How does your feet hurting stop you from hearing?"] = "¿Cómo es que el dolor de pies te impide oír?",
    ["Am glad I can't hear - you sound very annoying."] = "Me alegro de no poder oírte. Suenas muy molesto.",
    ["Right. So, say I were to bring you - oh, I don't know - a nice, warm hat to cover your ears. Then would you be able to hear me?"] = "Correcto. Entonces, digamos que te trajera, oh, no lo sé, un bonito y cálido gorro para cubrirte las orejas. ¿Entonces podrías oírme?",
    ["If it were nice, warm, furry kebbit hat made by Frawd the ogress. Those very good to look at AND very warm."] = "Si fuera un lindo, cálido y peludo gorro kebbit hecho por Frawd la ogresa. Son muy bonitos a la vista y muy cálidos.",
    ["You're not very subtle, you know."] = "No eres muy sutil, ¿sabes?",
    ["What? Sorry. Ears too cold to hear you and all."] = "¿Qué? Lo siento. Oídos demasiado fríos para oírte a ti y a todo eso.",
    ["Oh, kebbit hat! That exactly what I always wanted. It would be perfect thing to keep wind out of hair."] = "¡Oh, sombrero de kebbit! Eso es exactamente lo que siempre quise. Sería perfecto para mantener el cabello alejado del viento.",
    ["What hair? You don't have any hair!"] = "¿Qué pelo? ¡No tienes pelo!",
    ["Are you going to give it or are you here to taunt me?"] = "¿Vas a darlo o estás aquí para burlarte de mí?",
    ["Go ahead and take it."] = "Adelante, tómalo.",
    ["Thank you very much. It fit like dream! My ears so warm now."] = "Muchas gracias. ¡Encaja como un sueño! Mis oídos están tan calientes ahora.",
    ["Glad you like it. It suits you to a 'T'."] = "Me alegra que te guste. Te queda perfecto.",
    ["Very grateful. I in your debt, human."] = "Muy agradecido. Estoy en deuda contigo, humano.",
    ["Sorry, I just brought it here to taunt you."] = "Lo siento, solo lo traje aquí para burlarme de ti.",
    ["Harrumph. It good thing my ears too cold to hear you or I'd get real angry."] = "Harrumph. Es bueno que mis oídos estén demasiado fríos para escucharte o me enojaría mucho.",
    ["Hmph, it's you. Thanks much for great hat. Anything you want in return?"] = "Hmph, eres tú. Muchas gracias por el gran sombrero. ¿Algo que quieras a cambio?",
    ["Of course. Once you light beacon, give me 5 logs and I make fire burn long time."] = "Por supuesto. Una vez que enciendas la baliza, dame 5 logs y haré que el fuego arda por mucho tiempo.",
    ["I only look after blazing fire. You deal with dying fire yourself!"] = "Sólo me ocupo del fuego ardiente. ¡Tú mismo te ocupas del fuego moribundo!",
    ["How can I tend fire for you? You don't have enough good logs for me to use!"] = "¿Cómo puedo cuidar el fuego por ti? ¡No tienes suficiente logs bueno para que yo lo use!",
    ["Need five logs to tend fire. Okay?"] = "Necesitas cinco logs para cuidar el fuego. ¿Bueno?",
    ["Thanks. I use these five logs to keep beacon burning while you away."] = "Gracias. Utilizo estos cinco logs para mantener la baliza encendida mientras estás fuera.",
    ["Well. You know where I am if you change your mind."] = "Bueno. Sabes dónde estoy si cambias de opinión.",
    ["Of course. I use logs you already left here."] = "Por supuesto. Yo uso logs que ya dejaste aquí.",
    ["Yes, well, if you must, have look at map."] = "Sí, bueno, si es necesario, mira el mapa.",
    ["Hmm, what you saying? Dat my eyes aren't good? They much better than yours! I can tell you about all beacons in either direction, as long as they lit."] = "Hmm, ¿qué estás diciendo? ¿Mis ojos no son buenos? ¡Son mucho mejores que los tuyos! Puedo informarle sobre todas las balizas en cualquier dirección, siempre que estén encendidas.",
    ["Yes, but what about beacons that aren't lit?"] = "Sí, pero ¿qué pasa con las balizas que no están encendidas?",
    ["I could tell about the other beacons as well, if I have help from macaw."] = "También podría contarte sobre las otras balizas, si tengo ayuda de la guacamaya.",
    ["Yes. Macaws can fly high into air and see long distance. They also very smart creature."] = "Sí. Las guacamayas pueden volar muy alto en el aire y ver a larga distancia. También son criaturas muy inteligentes.",
    ["Can fly into air and then report back about whole beacon network."] = "Puede volar por el aire y luego informar sobre toda la red de balizas.",
    ["Hey, you holding a macaw. You give macaw, I tell you about other beacons, too."] = "Oye, estás sosteniendo una guacamaya. Le das guacamayo, te hablo de otras balizas también.",
    ["Awful! Why you ask such stupid questions?"] = "¡Horrible! ¿Por qué haces preguntas tan estúpidas?",
    ["It hard to be friendly when feet hurt."] = "Es difícil ser amigable cuando te duelen los pies.",
    ["Thanks. Macaw help me tell you more about other beacons."] = "Gracias. Guacamayo ayúdame a contarte más sobre otras balizas.",
    ["I've already given him a macaw; he doesn't need another."] = "Ya le regalé una guacamaya; él no necesita otro.",
    ["*Sob!* I'm going to fail! I hate exams."] = "*¡Sollozo!* ¡Voy a fracasar! Odio los exámenes.",
    ["Cheer up! I'm sure you'll do fine. Try to concentrate."] = "¡Anímate! Estoy seguro de que lo harás bien. Intenta concentrarte.",
    ["No talking in the exam, please."] = "No hables durante el examen, por favor.",
    ["Bah! I hate maths."] = "¡Bah! Odio las matemáticas.",
    ["I thought this was a Player Safety exam?"] = "Pensé que era un examen de seguridad de Player.",
    ["Yes, it is - but I just hate maths."] = "Sí, lo es, pero odio las matemáticas.",
    ["Please leave the students alone while they take their exams. We don't want any cheating in here."] = "Por favor, deje a los estudiantes en paz mientras realizan sus exámenes. No queremos ningún engaño aquí.",
    ["Oh! Sorry about that."] = "¡Oh! Lo lamento.",
    ["What's 769 x 426?"] = "¿Cuánto es 769 x 426?",
    ["What? Er… I don't know."] = "¿Qué? Er… no lo sé.",
    ["How are you doing with the exam?"] = "¿Cómo te va con el examen?",
    ["That good, huh?"] = "Qué bueno, ¿eh?",
    ["I broke my pencil. Do you have a spare one?"] = "Se me rompió el lápiz. ¿Tienes uno de repuesto?",
    ["No, I don't."] = "No, no lo hago.",
    ["How's the exam going at the moment?"] = "¿Cómo va el examen en este momento?",
    ["What exam?"] = "¿Qué examen?",
    ["Uh… the exam you're taking?"] = "Eh... ¿el examen que vas a realizar?",
    ["I'm not taking an exam. I'm drawing pictures."] = "No voy a hacer un examen. Estoy haciendo dibujos.",
    ["Oh. I… er… see."] = "Oh. Yo... eh... veo.",
    ["Shh, the invigilator will find out! Take this and go!"] = "¡Shh, el supervisor lo descubrirá! ¡Toma esto y vete!",
    ["Shhh! I'm waiting for the show!"] = "¡Shhh! ¡Estoy esperando el espectáculo!",
    ["What's on the bill?"] = "¿Qué hay en la factura?",
    ["Nothing an outerlander would enjoy!"] = "¡Nada que un extranjero disfrutaría!",
    ["There's a performance of an epic from olden times tonight! The epic of Bukalla!"] = "¡Esta noche hay una presentación de una epopeya de tiempos antiguos! ¡The epic of Bukalla!",
    ["Bukalla?"] = "¿Bukalla?",
    ["He was a famed slayer of daggermouths in olden times. It's a very inspirational song."] = "Era un famoso cazador de bocas de daga en la antigüedad. Es una canción muy inspiradora.",
    ["Sounds interesting! Maybe I'll stick around."] = "¡Suena interesante! Quizás me quede por aquí.",
    ["The Epic of Bukalla is a live recorded poem, roughly five minutes in length. We suggest that you turn your sound on in order to get the most out of it."] = "The Epic of Bukalla es un poema grabado en vivo, de aproximadamente cinco minutos de duración. Le sugerimos que active el sonido para aprovecharlo al máximo.",
    ["I'm ready to hear it!"] = "¡Estoy listo para escucharlo!",
    ["Wait a second!"] = "¡Espera un segundo!",
    ["Sounds boring"] = "Suena aburrido",
    ["Sounds boring."] = "Suena aburrido.",
    ["Well, you're missing out on a glorious piece of history."] = "Bueno, te estás perdiendo una gloriosa parte de la historia.",
    ["Hey what's going on here?"] = "Oye, ¿qué está pasando aquí?",
    ["You make burial armour for fallen ancestors."] = "Haces armaduras funerarias para los ancestros caídos.",
    ["What is burial armour?"] = "¿Qué es la armadura funeraria?",
    ["Dwarves die lots. Miners crushed by rocks. Warriors stabbed by goblins. Smiths get black lung. To honour our dead, we build them armour so they can keep on working in afterlife."] = "Los enanos mueren mucho. Mineros aplastados por rocas. Guerreros apuñalados por duendes. Los Smith tienen pulmón negro. Para honrar a nuestros muertos, les construimos armaduras para que puedan seguir trabajando en el más allá.",
    ["How can I make burial armour?"] = "¿Cómo puedo hacer una armadura funeraria?",
    ["You smith full set of adamant armour (or better). Helm, body, legs, gauntlets and boots. Then you upgrade each piece until it is best. Then smith them into burial armour set at burial anvil. It is simple. But slow. Like wife of Suak! Or you are lazy. You buy fully upgraded armour. You smith burial armour set. Suak does not like the lazy smith."] = "Creas un conjunto completo de armadura inflexible (o mejor). Yelmo, cuerpo, piernas, guanteletes y botas. Luego actualizas cada pieza hasta que sea la mejor. Luego, conviértelos en una armadura funeraria colocada en el yunque funerario. Es sencillo. Pero lento. ¡Como esposa de Suak! O eres un vago. Compras una armadura completamente mejorada. Tu conjunto de armadura funeraria de herrero. A Suak no le gusta el herrero perezoso.",
    ["Tell me more about yourself."] = "Cuéntame más sobre ti.",
    ["Suak not so smart with words, but good with hammer."] = "Suak no es tan inteligente con las palabras, pero es bueno con el martillo.",
    ["What's up with the suits of armour?"] = "¿Qué pasa con las armaduras?",
    ["Dwarves not buried with armour will be unable to make way to afterlife. They come here. We give them burial armour. They go. Suak thinks they pass on."] = "Los enanos que no estén enterrados con armadura no podrán abrir paso al más allá. Ellos vienen aquí. Les damos armadura funeraria. Ellos van. Suak cree que fallecen.",
    ["What do I get from this?"] = "¿Qué obtengo de esto?",
    ["To build armour for our beloved dead. An honour. Great experience for you. For helping our dead, you earn respect of Suak."] = "Para construir armaduras para nuestros amados muertos. Un honor. Gran experiencia para ti. Por ayudar a nuestros muertos, te ganas el respeto de Suak.",
    ["Dwarves die lots. Miners crushed by rocks. Warriors stabbed by goblins. Smiths get black lung."] = "Los enanos mueren mucho. Mineros aplastados por rocas. Guerreros apuñalados por duendes. Los Smith tienen pulmón negro.",
    ["To honour our dead, we build them armour so they can keep on working in afterlife."] = "Para honrar a nuestros muertos, les construimos armaduras para que puedan seguir trabajando en el más allá.",
    ["Sten will show."] = "Sten aparecerá.",
    ["STEN!"] = "¡ESTEN!",
    ["This is good method of training for smiths between level 30 and 70. Gives range of experience."] = "Este es un buen método de entrenamiento para herreros entre niveles 30 y 70. Proporciona variedad de experiencia.",
    ["To make burial armour you need ingots."] = "Para hacer armaduras funerarias necesitas lingotes.",
    ["To make ingots, despoist ore of the kind you wish to work with in the furnace. Using noted ore will speed this up rapidly."] = "Para hacer lingotes, despoja el mineral del tipo con el que deseas trabajar en el horno. El uso de mineral destacado acelerará esto rápidamente.",
    ["Don't forget to include coal if you want to work with any metal other than iron."] = "No olvides incluir carbón si quieres trabajar con cualquier metal que no sea hierro.",
    ["Burial armour can be made with different grades of ingots (I, II and III). The higher the grade, the more experience you'll earn, but it will require more ores to make. The armour can be made in different metals; more precious metals giving you greater"] = "Las armaduras funerarias se pueden fabricar con diferentes grados de lingotes (I, II y III). Cuanto mayor sea el grado, más experiencia ganarás, pero necesitarás más minerales para producirlo. La armadura se puede fabricar en diferentes metales; más metales preciosos que le brindan mayor",
    ["experience."] = "experiencia.",
    ["Select the ingot you wish to work with and withdraw as many as you can. Try different metal types and grades to find what expense and experience rate suits you best."] = "Selecciona el lingote con el que deseas trabajar y retira tantos como puedas. Pruebe diferentes tipos y grados de metales para encontrar el costo y la tasa de experiencia que mejor se adapten a sus necesidades.",
    ["Head to one of the anvils near Suak. He may not come across as intelligent, but do as he says and you'll earn more experience. He knows his stuff!"] = "Dirígete a uno de los yunques cerca de Suak. Puede que no parezca tan inteligente, pero haz lo que te dice y ganarás más experiencia. ¡Él sabe lo que hace!",
    ["Either listen to what he's saying or consult the interface in the centre of the screen to find out what you should be smithing."] = "Escucha lo que dice o consulta la interfaz en el centro de la pantalla para saber qué deberías forjar.",
    ["Currently, Suak's talking about helms. So, smithing helms will earn you greater experience than anything else. Try to keep your smithing in line with his orders."] = "Actualmente, Suak está hablando de timones. Por lo tanto, forjar yelmos te otorgará mayor experiencia que cualquier otra cosa. Intenta mantener tu herrería en línea con sus órdenes.",
    ["Place finished armour in the nearby chute, then collect more ingots and repeat."] = "Coloca la armadura terminada en el conducto cercano, luego recoge más lingotes y repite.",
    ["I not so smart with words, but good with hammer. You learn lots from me if you listen well."] = "No soy tan inteligente con las palabras, pero soy bueno con el martillo. Aprendes mucho de mí si escuchas bien.",
    ["What's up with the walking suits of armour?"] = "¿Qué pasa con las armaduras para caminar?",
    ["Dwarves not buried with armour will be unable to make way to afterlife. They come here."] = "Los enanos que no estén enterrados con armadura no podrán abrir paso al más allá. Ellos vienen aquí.",
    ["Smashing up armours makes'em leave. I think they pass on."] = "Destrozar armaduras los hace irse. Creo que pasan.",
    ["To build armour for our beloved dead. An honour. Great experience for you."] = "Para construir armaduras para nuestros amados muertos. Un honor. Gran experiencia para ti.",
    ["For helping our dead, you earn my respect. Listen to my words for great experience."] = "Por ayudar a nuestros muertos, te ganas mi respeto. Escuche mis palabras para una gran experiencia.",
    ["You have touched the Catalyst mortal, you have doomed yourself and will invite the Dragonkin's wrath."] = "Has tocado al mortal Catalizador, te has condenado a ti mismo e invitarás a la ira de los Dragonantes.",
    ["Beware the Dragonkin, mortal! Beware! Beware!"] = "¡Cuidado con los Dragonkin, mortal! ¡Tener cuidado! ¡Tener cuidado!",
    ["The Catalyst?"] = "¿El catalizador?",
    ["What you mistakenly call the Stone of Jas. It is a tool of the Creators and is not meant for mortal hands."] = "Lo que erróneamente llamas la Piedra de Jas. Es una herramienta de los Creadores y no está destinada a manos mortales.",
    ["In time you will learn the error of your ways. But I have grown fond of you in our conversation mortal."] = "Con el tiempo aprenderás el error de tus caminos. Pero me he encariñado contigo en nuestra conversación mortal.",
    ["I shall give you my wisdom so that you may have a fighting chance in what will come."] = "Te daré mi sabiduría para que tengas una oportunidad de luchar en lo que vendrá.",
    ["You gain 25,000 bonus xp in [skill]."] = "Obtienes 25.000 xp de bonificación en [skill].",
    ["This is only said should the Ulthven necromancer that summoned the skeleton yells color=yellow|The trumpets of war beckon you!"] = "Esto sólo se dice si el Ulthven necromancer que convocó al esqueleto grita color=yellow|The trumpets of war beckon you!.",
    ["You have 1 minute before your familiar vanishes."] = "Tienes 1 minuto antes de que tu familiar desaparezca.",
    ["You have 30 seconds before your familiar vanishes."] = "Tienes 30 segundos antes de que tu familiar desaparezca.",
    ["Your familiar has returned to the spirit plane."] = "Tu familiar ha regresado al plano espiritual.",
    ["Your follower has left."] = "Tu seguidor se ha ido.",
    ["I don't think you are skilled enough to help me, young adventurer. You should try talking to me again later."] = "No creo que tengas la habilidad suficiente para ayudarme, joven aventurero. Deberías intentar hablar conmigo de nuevo más tarde.",
    ["I don't suppose there's a chance that you'll let me try, even though you think I'm incapable?"] = "Supongo que no hay ninguna posibilidad de que me dejes intentarlo, ¿aunque creas que soy incapaz?",
    ["Don't ever question my judgement, unless you're after a grisly fate."] = "Nunca cuestiones mi juicio, a menos que busques un destino espantoso.",
    ["You've not proven yourself to me, so don't expect my help - begone!"] = "No me has demostrado tu valía, así que no esperes mi ayuda. ¡Vete!",
    ["Uncaring brute. Do you think I'll act as a shopkeeper while my sister is in peril?"] = "Bruto indiferente. ¿Crees que actuaré como comerciante mientras mi hermana esté en peligro?",
    ["Ello, I am a Slayer Master now."] = "Hola, ahora soy un Slayer Master.",
    ["*If you are currently on a Slayer assignment*"] = "*Si actualmente estás en una asignación de Slayer*",
    ["You are still hunting [assigned creatures]; come back when you've finished your task."] = "Aún estás buscando a [assigned creatures]; Vuelve cuando hayas terminado tu tarea.",
    ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
    ["I have a wide selection of Slayer equipment; take a look!"] = "Tengo una amplia selección de equipos Slayer; ¡eche un vistazo!",
    ["*(Slayer Equipment interface opens)*"] = "*(Se abre la interfaz del equipo Slayer)*",
    ["View rewards."] = "Ver recompensas.",
    ["*(Slayer Rewards interface opens)*"] = "*(Se abre la interfaz de recompensas Slayer)*",
    ["How do I earn co-op points to spend on rewards?"] = "¿Cómo gano puntos cooperativos para gastarlos en recompensas?",
    ["You'll gain co-op reward points if you complete at least half of your contribution to a task with a friend. That means you need to be in a group for most of the time you're working on the task, but it doesn't matter if your friend beats you to the majority of kills! You'll still have been in a group for most of your contribution, so you're still entitled to a co-op reward point."] = "Obtendrás puntos de recompensa cooperativa si completas al menos la mitad de tu contribución a una tarea con un amigo. Eso significa que debes estar en un grupo la mayor parte del tiempo que estés trabajando en la tarea, ¡pero no importa si tu amigo te gana en la mayoría de las muertes! Aún habrás estado en un grupo durante la mayor parte de tu contribución, por lo que aún tendrás derecho a un punto de recompensa cooperativa.",
    ["Where can I use the co-op food and potion rewards?"] = "¿Dónde puedo usar las recompensas cooperativas de comida y pociones?",
    ["The rewards can be used in most of the areas we commonly send you to complete your tasks."] = "Las recompensas se pueden usar en la mayoría de las áreas que comúnmente te enviamos para completar tus tareas.",
    ["I have some questions about your sister and the smoky dungeons."] = "Tengo algunas preguntas sobre tu hermana y las mazmorras humeantes.",
    ["I have some questions about your sister."] = "Tengo algunas preguntas sobre tu hermana.",
    ["There's not much to say. She's back in a safe place, where no one will see her again."] = "No hay mucho que decir. Está de regreso en un lugar seguro, donde nadie la volverá a ver.",
    ["She started incinerating things when I freed her, and she said some pretty odd things. I'd prefer it if you gave me some answers."] = "Empezó a incinerar cosas cuando la liberé y dijo algunas cosas bastante raras. Preferiría que me dieras algunas respuestas.",
    ["Am I my sister's keeper? Some things must remain a mystery, known only to the gods."] = "¿Soy el guardián de mi hermana? Algunas cosas deben seguir siendo un misterio, conocido sólo por los dioses.",
    ["I'd like to know about the inhabitants to the dungeons."] = "Me gustaría saber sobre los habitantes de las mazmorras.",
    ["They are monsters, so they are fit only for slaying. With no thoughts of an afterlife, they live a simple life of kill and be killed. You should strive for such an existence, for therein lies happiness."] = "Son monstruos, por lo que solo sirven para matar. Sin pensar en una vida futura, viven una vida sencilla de matar y morir. Debéis esforzaros por lograr esa existencia, porque en ella reside la felicidad.",
    ["That's quite a grim philosophy."] = "Esa es una filosofía bastante sombría.",
    ["Why are you so shifty when I ask about your sister?"] = "¿Por qué eres tan astuto cuando te pregunto por tu hermana?",
    ["Shifty? Me? I'm protecting her and leaving no clues to her location."] = "¿Cambiante? ¿A mí? La estoy protegiendo y no dejo pistas sobre su ubicación.",
    ["But why not tell me?"] = "¿Pero por qué no decírmelo?",
    ["There has already been a kidnap attempt and there may be another. Now, I shall be silent, in case I reveal too much."] = "Ya ha habido un intento de secuestro y puede haber otro. Ahora guardaré silencio por si revela demasiado.",
    ["The barriers in the dungeon confuse me."] = "Las barreras del calabozo me confunden.",
    ["Well, they should be mostly passable. I weakened them for you after you rescued Jesmona. You should be able to sate your destructive appetite upon these creatures."] = "Bueno, en su mayoría deberían ser transitables. Los debilité por ti después de que rescataste a Jesmona. Deberías poder saciar tu apetito destructivo con estas criaturas.",
    ["I'm not after anything, in fact."] = "De hecho, no busco nada.",
    ["Er...nothing..."] = "Eh... nada...",
    ["Hello there, Player, what can I help you with?"] = "Hola, Player, ¿en qué puedo ayudarte?",
    ["How am I doing so far?"] = "¿Cómo estoy hasta ahora?",
    ["You're currently assigned to kill [assigned creatures]; only X more to go."] = "Actualmente estás asignado a matar a [assigned creatures]; sólo faltan X más.",
    ["Where are you?"] = "¿Dónde estás?",
    ["Got any tips for me?"] = "¿Tienes algún consejo para mí?",
    ["That's all thanks."] = "Eso es todo gracias.",
    ["My name is Sumona; I'm a Slayer Master."] = "Mi nombre es Sumona; Soy un Slayer Master.",
    ["You'll find me in Pollnivneach. I'll be here when you need a new task."] = "Me encontrarás en Pollnivneach. Estaré aquí cuando necesites una nueva tarea.",
    ["The last [assigned creature] I killed I found [weapons] took them down effectively."] = "El último [assigned creature] que maté descubrí que [weapons] los derribó de manera efectiva.",
    ["[Task hint]"] = "[sugerencia de tarea]",
    ["Nothing really."] = "Nada realmente.",
    ["Ello, Player"] = "Hola, Player",
    ["I'm using magic to communicate with you."] = "Estoy usando magia para comunicarme contigo.",
    ["Er...nothing."] = "Eh... nada.",
    ["Aberrant spectres are fetid, vile ghosts. The very smell of them will paralyse and harm you, while a nosepeg will help ignore their stink. If you sniff carefully, you may be able to detect their aroma beneath the town's well. Kill a few of them, as they offend my nose."] = "Los espectros aberrantes son fantasmas fétidos y viles. El solo olor de ellos te paralizará y te hará daño, mientras que una clavija te ayudará a ignorar su hedor. Si hueles con atención, es posible que puedas detectar su aroma debajo del pozo de la ciudad. Mata a algunos de ellos, ya que ofenden mi nariz.",
    ["Abyssal demons are nasty creatures to deal with. They aren't really part of this realm and are able to move very quickly to trap their prey. I'm sure you'd love a nice abyssal whip or two, so cull these demons in the Slayer Tower near Canifis."] = "Los demonios abisales son criaturas desagradables con las que lidiar. En realidad, no son parte de este reino y pueden moverse muy rápidamente para atrapar a sus presas. Estoy seguro de que te encantará uno o dos buenos látigos abisales, así que elimina a estos demonios en la Torre Slayer cerca de Canifis.",
    ["Aquanites are amphibious creatures that attract prey using the glowing lures on their heads. They attack stronger opponents from a distance with water magic, and dislike those who pray against it. You'll find these despicable, slimy creatures in the Fremennik Slayer Dungeon, in a chamber past the kurasks."] = "Los acuanitas son criaturas anfibias que atraen a sus presas utilizando los señuelos brillantes que tienen en la cabeza. Atacan a oponentes más fuertes desde la distancia con magia de agua y no les agradan aquellos que rezan en contra de ella. Encontrarás estas despreciables y viscosas criaturas en la mazmorra Fremennik Slayer, en una cámara más allá de los kurasks.",
    ["Aviansies can be found in the Godwars Dungeon north of Trollheim. As they are flying, you'll find melee attacks are not going to cut it."] = "Los aviansies se pueden encontrar en Godwars Dungeon al norte de Trollheim. Mientras vuelan, descubrirás que los ataques cuerpo a cuerpo no serán suficientes.",
    ["Banshees use a piercing scream to shock their enemies, so you'll need some earmuffs to protect yourself. I am sometimes disturbed in my sleep by their wails, so do me a favour and thin out those beneath us."] = "Las Banshees usan un grito desgarrador para sorprender a sus enemigos, por lo que necesitarás unas orejeras para protegerte. A veces sus lamentos me perturban mientras duermo, así que hazme un favor y elimina a los que están debajo de nosotros.",
    ["Basilisks, like Cockatrices, have a gaze which will paralyse and harm their prey. You'll need a mirror shield to protect you. Conveniently, you can have some combat fun with these brutes in the dungeon beneath the town well."] = "Los basiliscos, como las cacatúas, tienen una mirada que paraliza y daña a sus presas. Necesitarás un escudo de espejo para protegerte. Convenientemente, puedes divertirte en el combate con estos brutos en la mazmorra debajo de la ciudad.",
    ["Black demons are creatures that are weak to ranged attacks. They're the strongest type of demon and are therefore very dangerous. Prove yourself more dangerous by slaying these demons in their lairs beneath Taverley or Edgeville."] = "Los demonios negros son criaturas débiles a los ataques a distancia. Son el tipo de demonio más fuerte y, por tanto, muy peligrosos. Demuestra que eres más peligroso matando a estos demonios en sus guaridas debajo de Taverley o Edgeville.",
    ["Bloodveld are strange, demonic creatures that use their long rasping tongue to feed on just about anything. They are rather robust but frankly feeble and have been seen in the Slayer Tower near Canifis, among other places. I never liked the look of them, so off you go and wipe them out."] = "Los Bloodveld son extrañas criaturas demoníacas que usan su larga lengua áspera para alimentarse de casi cualquier cosa. Son bastante robustos pero francamente débiles y se han visto en la Torre Slayer cerca de Canifis, entre otros lugares. Nunca me gustó su aspecto, así que ve y bórralos.",
    ["Blue dragons aren't as strong as other dragons, but they're still very powerful. Watch out for their fiery breath! Taverley is home to these pests - I'm sure you'll enjoy murdering a few."] = "Los dragones azules no son tan fuertes como otros dragones, pero siguen siendo muy poderosos. ¡Cuidado con su aliento de fuego! Taverley es el hogar de estas plagas; estoy seguro de que disfrutarás asesinando algunas.",
    ["Cave crawlers are small and fast, often hiding in ambush. Avoid their barbed tongue or you'll get poisoned. The ones in the caves below here have grown large and fat in blissful isolation - go and be a force of natural selection."] = "Los rastreadores de cuevas son pequeños y rápidos, y a menudo se esconden en emboscadas. Evita su lengua con púas o te envenenarán. Los que están en las cuevas de aquí abajo han crecido y engordado en un maravilloso aislamiento: ve y sé una fuerza de selección natural.",
    ["Cave horrors can be found under Mos Le'Harmless. You will need a witchwood icon to fight them effectively. If you want to make a nice Slayer helmet, you'll need the black mask they drop."] = "Los horrores de las cuevas se pueden encontrar debajo de Mos Le'Harmless. Necesitarás un ícono de madera mágica para luchar contra ellos de manera efectiva. Si quieres hacer un bonito casco Slayer, necesitarás la máscara negra que sueltan.",
    ["The last Corrupted creature I killed I found many different combat styles took them down effectively."] = "La última criatura corrupta que maté encontré que muchos estilos de combate diferentes la derribaron de manera efectiva.",
    ["[You can find corrupted creatures in the Sophanem Slayer Dungeon.]"] = "[Puedes encontrar criaturas corruptas en la mazmorra Sophanem Slayer.]",
    ["Without their master, Cres's automatons roam Guthix's chambers, attacking any who enter. They are programmed to use magic, melee or ranged and do a violent area-of-effect attack. Guthix's chambers may be reached via his shrine, or the excavation west of the Legends' Guild."] = "Sin su maestro, los autómatas de Cres deambulan por las cámaras de Guthix, atacando a cualquiera que entre. Están programados para usar magia, cuerpo a cuerpo o a distancia y realizar un violento ataque de área de efecto. Se puede llegar a las cámaras de Guthix a través de su santuario o de la excavación al oeste de Legends' Guild.",
    ["Crocodiles are large reptiles that live near water. You'll want to have a stabbing weapon handy for puncturing their thick, scaly hides. These are desert beasts, so seek them there."] = "Los cocodrilos son reptiles grandes que viven cerca del agua. Querrás tener a mano un arma punzante para perforar sus pieles gruesas y escamosas. Estas son bestias del desierto, así que búscalas allí.",
    ["Dagannoth are large, sea-dwelling creatures that are very aggressive. You'll often find them in caves near sea water. You'll cackle with glee if you set up a cannon and massacre them."] = "Los Dagannoth son criaturas marinas grandes que son muy agresivas. A menudo los encontrarás en cuevas cerca del agua de mar. Te reirás de alegría si colocas un cañón y los masacras.",
    ["Desert lizards are large reptiles with tough skin. They're cold-blooded, so dousing them with freezing water will finish them off after a tough battle."] = "Los lagartos del desierto son reptiles grandes con piel dura. Tienen sangre fría, por lo que rociarlos con agua helada acabará con ellos después de una dura batalla.",
    ["These things are the curse of the desert! Head north to find them on the hills above the Shantay Pass. Watch out for their vicious ranged attacks."] = "¡Estas cosas son la maldición del desierto! Dirígete hacia el norte para encontrarlos en las colinas sobre el paso Shantay. Cuidado con sus feroces ataques a distancia.",
    ["Dust devils use clouds of dust, sand, ash and whatever else they can inhale to blind and disorientate their victims. You'll be able to test your skills on them in the smoky dungeon to the west. Get going!"] = "Los remolinos de polvo utilizan nubes de polvo, arena, cenizas y cualquier otra cosa que puedan inhalar para cegar y desorientar a sus víctimas. Podrás probar tus habilidades con ellos en la mazmorra humeante del oeste. ¡Ponerse en marcha!",
    ["Elves are quick, agile and vicious fighters that often favour bows, polearms and snide remarks. Their dedication to trees, bushes and music is an affront to me, so go and cause havoc in their vile villages. You'll need to travel far to the west."] = "Los elfos son luchadores rápidos, ágiles y feroces que a menudo prefieren arcos, armas de asta y comentarios sarcásticos. Su dedicación a los árboles, los arbustos y la música es una afrenta para mí, así que ve y causa estragos en sus viles aldeas. Tendrás que viajar muy hacia el oeste.",
    ["Like other giants, Fire giants often wield large weapons. Learn to recognise what kind of weapon it is and act accordingly. Prove that bigger isn't always better by defeating some. They lurk in the smoke dungeon, west of here, telling tales of your weakness."] = "Al igual que otros gigantes, los gigantes de fuego suelen empuñar armas grandes. Aprende a reconocer qué tipo de arma es y actúa en consecuencia. Demuestra que más grande no siempre es mejor derrotando a algunos. Acechan en la mazmorra de humo, al oeste de aquí, contando historias de tu debilidad.",
    ["Fungal magi live in the upper levels of a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, and be prepared for their magical attacks. The fungus helps them repair physical damage, so you might prefer using magical attacks too."] = "Los magos fúngicos viven en los niveles superiores de una cueva al noreste de Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia y estar preparado para sus ataques mágicos. El hongo les ayuda a reparar el daño físico, por lo que es posible que también prefieras usar ataques mágicos.",
    ["Gargoyles are winged creatures of stone. You'll need to fight them until they are close to death, before breaking them apart with a rock hammer. They refuse to serve me, so smite them in my name. They are hiding out in the Slayer Tower near Canifis."] = "Las gárgolas son criaturas aladas de piedra. Tendrás que luchar contra ellos hasta que estén al borde de la muerte, antes de destrozarlos con un martillo de roca. Se niegan a servirme, así que golpéalos en mi nombre. Se esconden en la torre Slayer cerca de Canifis.",
    ["Greater demons are creatures that are weak to ranged attacks. Though not the strongest of demons, they are still dangerous. Prove yourself by doing away with them. If you don't know, a large number live in the Brimhaven Dungeon."] = "Los demonios mayores son criaturas débiles a los ataques a distancia. Aunque no son los demonios más fuertes, siguen siendo peligrosos. Ponte a prueba eliminándolos. Si no lo sabes, un gran número vive en la mazmorra Brimhaven.",
    ["Grifolapines live in a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, and dodge when they charge at you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolapinos viven en una cueva al noreste del Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que debes luchar contra ellas desde la distancia y esquivar cuando cargan contra ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
    ["Grifolaroos live in a cave north-east of the Mage Training Arena. The creatures of that dungeon are coated in toxic fungus, so you should fight them from a distance, although they'll try to hop over obstacles towards you. The fungus helps them repair physical damage, so you might prefer using magical attacks."] = "Los grifolaroos viven en una cueva al noreste del Mage Training Arena. Las criaturas de esa mazmorra están cubiertas de hongos tóxicos, por lo que deberás luchar contra ellas desde la distancia, aunque intentarán saltar los obstáculos hacia ti. El hongo les ayuda a reparar el daño físico, por lo que quizás prefieras usar ataques mágicos.",
    ["Grotworms have recently been spotted in a cave near Rimmington. They will bite and attack with some sort of acid spit. Be careful - they are very aggressive."] = "Recientemente se han visto gusanos grot en una cueva cerca de Rimmington. Morderán y atacarán con una especie de saliva ácida. Tenga cuidado, son muy agresivos.",
    ["Hellhounds are a cross between dogs and demons, and are dangerous with a fierce bite. Although they are not cats, they deserve to die anyway. You'll be doing Gielinor a favour if you slay Hellhounds beneath Taverley."] = "Los Hellhounds son un cruce entre perros y demonios, y son peligrosos con una mordida feroz. Aunque no son gatos, merecen morir de todos modos. Le harás un favor a Gielinor si matas Hellhounds debajo de Taverley.",
    ["Iron dragons are some of the weaker metallic dragons, but their iron scales are far thicker than normal iron armour. Brimhaven Dungeon has a few of these creatures in residence; I think they should be exterminated because they bore me."] = "Los dragones de hierro son algunos de los dragones metálicos más débiles, pero sus escamas de hierro son mucho más gruesas que las armaduras de hierro normales. Brimhaven Dungeon tiene algunas de estas criaturas en residencia; Creo que deberían ser exterminados porque me aburren.",
    ["These tricky creatures burrow beneath the jungle north west of Oo'glog. Be careful, as these poisonous jungle wyrms like to use magical attacks from a distance, while they should be weak to stab attacks."] = "Estas engañosas criaturas se esconden bajo la jungla al noroeste de Oo'glog. Ten cuidado, ya que a estos venenosos wyrms de la jungla les gusta usar ataques mágicos desde la distancia, mientras que deberían ser débiles para apuñalar ataques.",
    ["Kalphites are large insects that live in hives under the desert sands. Their Queen is rumoured to be quite powerful. Show people that you are a force to be feared by slaying her brood in the hive to the north-west."] = "Los calfitos son insectos grandes que viven en colmenas bajo las arenas del desierto. Se rumorea que su Reina es bastante poderosa. Muéstrale a la gente que eres una fuerza a la que temer matando a sus crías en la colmena del noroeste.",
    ["Kurasks are large, brutal creatures with very thick hides. You'll need a leaf-bladed weapon, broad arrows, or a magic dart to harm them. Unluckily for kurasks, I am sending you to kill them. Luckily for you, kurasks thrive in the dungeons below Pollnivneach."] = "Los Kurasks son criaturas grandes y brutales con pieles muy gruesas. Necesitarás un arma con hoja de hoja, flechas anchas o un dardo mágico para dañarlos. Desafortunadamente para los kurasks, te envío a matarlos. Por suerte para ti, los kurasks prosperan en las mazmorras debajo de Pollnivneach.",
    ["These warped jade vine creatures will not hesitate to use their environment to help them in combat if they cannot retaliate otherwise. The baby jadinkos are easiest to kill, but the males offer the greatest rewards. Ranged weapons made from vines are best against them."] = "Estas criaturas deformadas de enredadera de jade no dudarán en utilizar su entorno para ayudarles en el combate si no pueden tomar represalias de otra manera. Las crías de jadinkos son más fáciles de matar, pero los machos ofrecen las mayores recompensas. Las armas Ranged hechas de enredaderas son mejores contra ellos.",
    ["Nechryael are demons of decay that summon small-winged beings to help them fight their victims. I don't like them much, so kill a few as a personal favour. You can find them up to no good in the Slayer Tower near Canifis."] = "Los Nechryael son demonios de la decadencia que convocan a seres de pequeñas alas para que les ayuden a luchar contra sus víctimas. No me gustan mucho, así que mato algunos como favor personal. Puedes encontrarlos haciendo cosas malas en la Torre Slayer cerca de Canifis.",
    ["The last Profane Scabarite I killed I found earth spells took them down effectively."] = "El último scabarita profano que maté descubrí que los hechizos de tierra los derribaron de manera efectiva.",
    ["Profane scabarites are insect-like that have abandoned their beliefs. They are causing issues for people of the desert. You will find them near the river Elid."] = "Los escabaritos profanos son parecidos a insectos que han abandonado sus creencias. Están causando problemas a la gente del desierto. Los encontrarás cerca del río Elid.",
    ["Red dragons are fearsome firebreathers, stronger than green or blue. I'm sure that you'll have fun pitting your skills against their claws in either Brimhaven's depths or the ravaged lands far to the north."] = "Los dragones rojos son temibles lanzafuegos, más fuertes que el verde o el azul. Estoy seguro de que te divertirás probando tus habilidades contra sus garras en las profundidades de Brimhaven o en las tierras devastadas del lejano norte.",
    ["The last Scabaras lancer I killed I found fire spells took them down effectively."] = "El último lancero de Scabaras que maté encontré que los hechizos de fuego los derribaron de manera efectiva.",
    ["[Scabarites are the followers of Scabaras and consist of anything from the lowliest dung beetle to the vilest scarab mage. They are most commonly found near and under Sophanem. They are traitorous creatures in the main, so commit genocide upon them.]"] = "[Los scabaritas son seguidores de Scabaras y están formados por cualquier cosa, desde el más humilde escarabajo pelotero hasta el más vil mago escarabajo. Se encuentran más comúnmente cerca y debajo de Sophanem. Son criaturas traidoras en su mayoría, así que comete genocidio contra ellos.]",
    ["Scorpions are almost always venomous and usually found in groups. Last I heard there was a large group near the mine north of Al Kharid."] = "Los escorpiones casi siempre son venenosos y generalmente se encuentran en grupos. Lo último que supe fue que había un grupo grande cerca de la mina al norte de Al Kharid.",
    ["You can find soul devourers in the Sophanem Slayer Dungeon."] = "Puedes encontrar devoradores de almas en la mazmorra Sophanem Slayer.",
    ["Spiritual warriors are fighters that have dedicated their souls to their deity; however, they still retain a fighter's weakness to Magic. They can be found fighting for the god whose cause they support. Kill them all and let their gods lament."] = "Los guerreros espirituales son luchadores que han dedicado sus almas a su deidad; sin embargo, todavía conservan la debilidad de un luchador hacia Magic. Se los puede encontrar luchando por el dios cuya causa apoyan. Mátalos a todos y deja que sus dioses se lamenten.",
    ["Spiritual mages are the strongest of the spiritual guardians. They are devastating against warriors, but a smart ranger can often defeat them. They can be found in the icy God Wars Dungeon near Trollheim, supporting the cause of their chosen god. All these gods must be caused to lament; go slay their followers for me."] = "Los magos espirituales son los más fuertes de los guardianes espirituales. Son devastadores contra los guerreros, pero un explorador inteligente a menudo puede derrotarlos. Se pueden encontrar en el helado God Wars Dungeon cerca de Trollheim, apoyando la causa de su dios elegido. Hay que hacer lamentar a todos estos dioses; Ve a matar a sus seguidores por mí.",
    ["Terror dogs are, unsurprisingly, dogs that terrorise the weak. They are the servants of Tarn, who annoyed me when he was young. Be a force of vengeance for me by cleaning his lair of these pathetic servitors."] = "Los perros del terror son, como era de esperar, perros que aterrorizan a los débiles. Son los sirvientes de Tarn, que me molestaban cuando era joven. Sé una fuerza de venganza para mí limpiando su guarida de estos patéticos sirvientes.",
    ["The last Mountain troll I killed I found water spells took them down effectively."] = "El último troll de montaña que maté descubrí que los hechizos de agua los derribaron de manera efectiva.",
    ["Trolls regenerate quickly but are still vulnerable to poisons and usually use crushing weapons. I've nothing much against them but their ridiculous names. Unluckily for them, that's enough of a reason to put a few in their graves."] = "Los trolls se regeneran rápidamente pero siguen siendo vulnerables a los venenos y suelen utilizar armas aplastantes. No tengo mucho contra ellos excepto sus ridículos nombres. Desafortunadamente para ellos, esa es una razón suficiente para poner a algunos en sus tumbas.",
    ["Turoths are large vicious creatures with thick hides. You'll need a leaf-bladed weapon, broad arrows, or a magic dart to harm them. I am sure you'll make yourself useful by killing the ones beneath our feet."] = "Los turoths son criaturas grandes y feroces con pieles gruesas. Necesitarás un arma con hoja de hoja, flechas anchas o un dardo mágico para dañarlos. Estoy seguro de que serás útil matando a los que están bajo nuestros pies.",
    ["These foul creatures can be found throughout Meiyerditch and Darkmeyer in Morytania. They have a telepathic ability which enables them to dodge incoming attacks, so you'll need a weapon specially created to harm them."] = "Estas repugnantes criaturas se pueden encontrar en Meiyerditch y Darkmeyer en Morytania. Tienen una habilidad telepática que les permite esquivar los ataques entrantes, por lo que necesitarás un arma especialmente creada para dañarlos.",
    ["Warped tortoises are creatures tainted by magical waste. They are vulnerable to an elven chime. I know you have seen them in your adventures, so go crack some carapace."] = "Las tortugas deformadas son criaturas contaminadas por desechos mágicos. Son vulnerables a un timbre élfico. Sé que los has visto en tus aventuras, así que ve a romper un caparazón.",
    ["[number] [minute/minutes] until this"] = "¡Se anuncia la clasificación de [number] [minute/minutes] until this",
    ["Can you leave me alone please? I'm trying to get a bit of rest."] = "¿Puedes dejarme en paz, por favor? Estoy intentando descansar un poco.",
    ["Sorry, I'm busy!"] = "¡Lo siento, estoy ocupado!",
    ["Yeah... I don't think that's right."] = "Sí... no creo que sea correcto.",
    ["Congratulations! You have completed: 'Beating Your Meat' - Use a meat tenderiser on a super cow."] = "¡Felicitaciones! Ha completado: 'Batir la carne': utilice un ablandador de carne en un super cow.",
    ["Nothing interesting happens."] = "No pasa nada interesante.",
    ["Go downstairs and speak to Commander Veldaban. Your business is with him."] = "Baja las escaleras y habla con el comandante Veldaban. Tu negocio es con él.",
    ["I hear you are the human that Veldaban has employed to help rebuild the statue. How is that going?"] = "He oído que eres el humano que Veldaban ha contratado para ayudar a reconstruir la estatua. ¿Cómo va eso?",
    ["How did you know about that?"] = "¿Cómo supiste eso?",
    ["Veldaban is in my employ."] = "Veldaban está a mi servicio.",
    ["Now, was there anything else you wanted to talk about?"] = "Ahora, ¿había algo más de lo que quisieras hablar?",
    ["**Player:** Who are you?"] = "**Player:** ¿Quién eres?",
    ["I am Bisi. I am the Supreme Commander of the Black Guard."] = "Soy Bisi. Soy el Supreme Commander del Black Guard.",
    ["I thought Veldaban was in command?"] = "¿Pensé que Veldaban estaba al mando?",
    ["Only of our regiment in Keldagrim, and a most honourable position it is as well."] = "Sólo de nuestro regimiento en Keldagrim, y también es una posición muy honorable.",
    ["But the Black Guard has many regiments across the dwarven realm. All the Commanders of those regiments report to me."] = "Pero el Black Guard tiene muchos regimientos en todo el reino de los enanos. Todos los comandantes de esos regimientos me reportan.",
    ["Oh yes, I helped Commander Lawgof once, in his fight against the goblins."] = "Oh, sí, una vez ayudé al comandante Lawgof en su lucha contra los duendes.",
    ["That's good to hear."] = "Es bueno escucharlo.",
    ["What news have you?"] = "¿Qué novedades tienes?",
    ["Apart from the statue of King Alvis falling down, you mean? I don't know. There is something suspicious about the whole case."] = "Aparte de la estatua del rey Alvis cayendo, ¿quieres decir? No sé. Hay algo sospechoso en todo el caso.",
    ["How do you mean?"] = "¿Qué quieres decir?",
    ["We've had several incidents recently. For a while, we even closed off the city. And now this."] = "Hemos tenido varios incidentes recientemente. Durante un tiempo incluso cerramos la ciudad. Y ahora esto.",
    ["I must go now."] = "Debo irme ahora.",
    ["Then I bid you farewell, human."] = "Entonces me despido de ti, humano.",
    ["Veldaban told me about your involvement in the rebuilding of the statue. Congratulations."] = "Veldaban me habló de tu participación en la reconstrucción de la estatua. Felicidades.",
    ["Apart from you helping to rebuild the statue for [chosen company]?"] = "¿Aparte de ayudar a reconstruir la estatua de [chosen company]?",
    ["There seems to be some general unrest in the city. There is trouble brewing in Keldagrim."] = "Parece haber cierto malestar general en la ciudad. Se están gestando problemas en Keldagrim.",
    ["But I'm sure Commander Veldaban is on top of it. He's a very capable officer, and I'm starting to get too old for this sort of thing."] = "Pero estoy seguro de que el comandante Veldaban está al tanto. Es un oficial muy capaz y estoy empezando a envejecer para este tipo de cosas.",
    ["The Red Axe has withdrawn from the city to some unknown location. I believe Commander Veldaban has asked you to assist him in finding their secret headquarters?"] = "El Hacha Roja se ha retirado de la ciudad a algún lugar desconocido. Creo que el comandante Veldaban le ha pedido que le ayude a encontrar su cuartel general secreto.",
    ["Oh yes, you're right."] = "Ah, sí, tienes razón.",
    ["I heard you were out investigating the Red Axe. Did you find out any info?"] = "Escuché que estabas investigando el Hacha Roja. ¿Descubriste alguna información?",
    ["I...I'm not sure."] = "Yo... no estoy seguro.",
    ["I hope Veldaban is right about you, and you're not just a drunk."] = "Espero que Veldaban tenga razón acerca de ti y que no seas solo un borracho.",
    ["I'm not!"] = "¡No lo soy!",
    ["I hope you can prove that some time in the future, Player."] = "Espero que puedas demostrarlo en algún momento en el futuro, Player.",
    ["I hope you're pleased with yourself, human. Your escapades have cost me my best officer and made me a laughing stock in the Palace. I'll have to work hard to restore the Consortium's confidence in the Black Guard."] = "Espero que estés satisfecho contigo mismo, humano. Tus escapadas me han costado mi mejor oficial y me han convertido en el hazmerreír de Palacio. Tendré que trabajar duro para restablecer la confianza del Consorcio en el Black Guard.",
    ["You need to deal with the Red Axe!"] = "¡Tienes que lidiar con el Hacha Roja!",
    ["We dealt with that in the Consortium meeting, human! I do not have the resources for an assault on the Red Axe stronghold. Now, leave me alone!"] = "¡Tratamos eso en la reunión del Consorcio, humano! No tengo los recursos para un asalto a la fortaleza de Red Axe. ¡Ahora déjame en paz!",
    ["The Black Guard has many regiments across the dwarven realm. All the Commanders of those regiments report to me."] = "El Black Guard tiene muchos regimientos en todo el reino de los enanos. Todos los comandantes de esos regimientos me reportan.",
    ["**Player:** What news have you?"] = "**Player:** ¿Qué novedades tienes?",
    ["I have no news for you, human."] = "No tengo noticias para ti, humano.",
    ["Thanks for your help in the assault on the Red Axe base, human. I didn't think we had the resources, but with your help and the help of the troll army, we just about pulled it off."] = "Gracias por tu ayuda en el asalto a la base de Red Axe, humano. No pensé que tuviéramos los recursos, pero con tu ayuda y la del ejército de trolls, casi lo logramos.",
    ["What's happening to the Black Guard now the war is over?"] = "¿Qué está pasando con Black Guard ahora que la guerra ha terminado?",
    ["The new king is giving me freedom to run the Black Guard without interference. His only orders were that Black Guards should be given free beer every day, paid for out of the royal treasury."] = "El nuevo rey me da libertad para ejecutar Black Guard sin interferencias. Sus únicas órdenes fueron que a los Guardias Negros se les diera cerveza gratis todos los días, pagada con cargo al tesoro real.",
    ["That's certainly making him popular with the troops. Whether it'll improve our fighting fitness remains to be seen."] = "Eso ciertamente lo hace popular entre las tropas. Queda por ver si mejorará nuestra aptitud para la lucha.",
    ["Apart from that, things are back to more or less how they were when the Consortium was in charge. I'm keeping guards on the troll border. I don't trust those smelly piles of rocks, treaty or no treaty."] = "Aparte de eso, las cosas han vuelto más o menos a ser como cuando el Consorcio estaba a cargo. Mantendré guardias en la frontera troll. No confío en esos malolientes montones de piedras, con tratado o sin tratado.",
    ["Now that his war with the Red Axe is finished, King Veldaban has asked me to review the Black Guard's priorities. He wants more focus on police work across the city, less on defence of the Consortium's assets."] = "Ahora que su guerra con Red Axe ha terminado, el Rey Veldaban me ha pedido que revise las prioridades de Black Guard. Quiere centrarse más en el trabajo policial en toda la ciudad, menos en la defensa de los activos del Consorcio.",
    ["He's also set up a special division to tackle fraud and tax evasion. Sometimes i think he wants to use any excuse to seize the companies' wealth and redistribute it to the people...or to his own treasury."] = "También creó una división especial para combatir el fraude y la evasión fiscal. A veces pienso que quiere utilizar cualquier excusa para apoderarse de la riqueza de las empresas y redistribuirla entre la gente... o entre su propio tesoro.",
    ["I'm glad he's letting me keep guards on our border with the trolls, though. I don't trust those smelly piles of rocks, treaty or no treaty."] = "Pero me alegro de que me permita mantener guardias en nuestra frontera con los trolls. No confío en esos malolientes montones de piedras, con tratado o sin tratado.",
    ["With the Consortium back in charge, things are going back to how they were before Veldaban became king."] = "Con el Consorcio nuevamente a cargo, las cosas volverán a ser como eran antes de que Veldaban se convirtiera en rey.",
    ["Outside the city, we're focusing on defending the Consortium's mining sites from trolls and goblins. With Veldaban dead, the Consortium isn't expecting his treaty with the trolls to last forever."] = "Fuera de la ciudad, nos estamos centrando en defender los sitios mineros del Consorcio de trolls y duendes. Con Veldaban muerto, el Consorcio no espera que su tratado con los trolls dure para siempre.",
    ["Outside the city, we're focusing on defending the Consortium's mining sites from trolls and goblins. The Consortium isn't expecting his treaty with the trolls to last forever."] = "Fuera de la ciudad, nos estamos centrando en defender los sitios mineros del Consorcio de trolls y duendes. El Consorcio no espera que su tratado con los trolls dure para siempre.",
    ["In Keldagrim, we're increasing patrols in Keldagrim East to guard against a possible Monarchist uprising. The Consortium has given us powers to break up protests. They don't want a repeat of what happened last time."] = "En Keldagrim, estamos aumentando las patrullas en Keldagrim Este para protegernos contra un posible levantamiento monárquico. El Consorcio nos ha dado poderes para disolver las protestas. No quieren que se repita lo que pasó la última vez.",
    ["*(If the player has full health:)*"] = "*(Si el player tiene salud completa:)*",
    ["*(If the player does not have full health:)*"] = "*(Si el player no tiene salud completa:)*",
    ["Yes, I do. Thankfully, we can cope with almost anything. Jaraah really is a wonderful surgeon; his methods are a little unorthodox but he gets the job done. I shouldn't tell you this, but his nickname is 'The Butcher'."] = "Sí, lo hago. Afortunadamente, podemos hacer frente a casi cualquier cosa. Jaraah realmente es un cirujano maravilloso; sus métodos son un poco poco ortodoxos pero hace el trabajo. No debería decirte esto, pero su apodo es 'El Carnicero'.",
    ["Not so much these days, but back when the Duel Arena was still around I saw my fair share of injuries."] = "No tanto estos días, pero cuando el Duel Arena todavía existía, vi una buena cantidad de lesiones.",
    ["Thankfully, we could cope with almost anything. Jaraah really is a wonderful surgeon. His methods were a little unorthodox, but he got the job done."] = "Afortunadamente, pudimos hacer frente a casi cualquier cosa. Jaraah realmente es un cirujano maravilloso. Sus métodos eran un poco poco ortodoxos, pero hizo el trabajo.",
    ["I work here, so yes. You're silly!"] = "Trabajo aquí, así que sí. ¡Eres tonto!",
    ["Well, this is where I work now, so yes. Here's as good a place as any to set up a hospital."] = "Bueno, aquí es donde trabajo ahora, así que sí. Éste es un lugar tan bueno como cualquier otro para montar un hospital.",
    ["Can I buy a Skillcape of Constitution from you?"] = "¿Puedo comprarles un Skillcape o un Constitution?",
    ["*(If the player has any of the Ring of Charos variants equipped:)*"] = "*(Si el player tiene alguna de las variantes de Ring of Charos equipada:)*",
    ["*(If the player doesn't have any of the Ring of Charos variants equipped:)*"] = "*(Si el player no tiene ninguna de las variantes de Ring of Charos equipadas:)*",
    ["Why, certainly my friend. However, owning such an item makes you part of an elite group, and that privilege will cost you 99,000 coins."] = "Vaya, ciertamente amigo mío. Sin embargo, poseer un artículo de este tipo te convierte en parte de un grupo de élite y ese privilegio te costará 99 000 coins.",
    ["**Surgeon General Tafani:** Not at all; there are many other adventurers who would love the opportunity to purchase such a prestigious item! You can find me here if you change your mind."] = "**Surgeon General Tafani:** En absoluto; ¡Hay muchos otros aventureros a quienes les encantaría tener la oportunidad de comprar un artículo tan prestigioso! Puedes encontrarme aquí si cambias de opinión.",
    ["*(If the player has the required amount of coins:)*"] = "*(Si el player tiene la cantidad requerida de coins:)*",
    ["*(If the player doesn't have the required amount of coins:)*"] = "*(Si el player no tiene la cantidad requerida de coins:)*",
    ["But, unfortunately, I was mistaken."] = "Pero, lamentablemente, me equivoqué.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Constitution master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Constitution master cape.",
    ["Buy Constitution master cape for 120,000 coins?"] = "¿Comprar Constitution master cape por 120.000 coins?",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["*(If the player has chosen the new skillcape models:)*"] = "*(Si el player ha elegido los nuevos modelos skillcape :)*",
    ["Yes, I would like to wear the old version of the skillcape."] = "Sí, me gustaría usar la versión antigua del skillcape.",
    ["Would you like to wear the old model for just this cape, or for the Quest point cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo antiguo solo para esta capa, o para la capa de puntos Quest y todos los skillcapes que tienes?",
    ["I would just like to change the Constitution skillcape."] = "Solo me gustaría cambiar el Constitution skillcape.",
    ["No problem, you will now use the older model for your Constitution skillcape."] = "No hay problema, ahora utilizarás el modelo anterior para tu Constitution skillcape.",
    ["No problem, you will now use the older model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo anterior para todos tus skillcapes!",
    ["Great! I'm glad you're enjoying our new version!"] = "¡Genial! ¡Me alegra que estés disfrutando de nuestra nueva versión!",
    ["*(If the player is using the old skillcape models except for the Constitution cape:)*"] = "*(Si el player está usando los modelos skillcape antiguos excepto la capa Constitution :)*",
    ["If you want, I can make it so you use the newer model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo más nuevo para todos los skillcapes que tienes!",
    ["Ok, I'd like to wear the newer version for all my skillcapes."] = "Ok, me gustaría usar la versión más nueva para todos mis skillcapes.",
    ["Great, you will now use the newer model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo más nuevo para todos tus skillcapes!",
    ["*(If the player has chosen the old skillcape models:)*"] = "*(Si el player ha elegido los modelos antiguos skillcape :)*",
    ["It looks like you're currently using the old model for your Constitution skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Constitution skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["Yes, I would like to wear the new version of the skillcape."] = "Sí, me gustaría usar la nueva versión del skillcape.",
    ["Would you like to wear the newer model for just this cape, or all of the skillcapes you own?"] = "¿Te gustaría usar el modelo más nuevo solo para esta capa o para todos los skillcapes que tienes?",
    ["No problem, you will now use the newer model for your Constitution skillcape."] = "No hay problema, ahora utilizarás el modelo más nuevo para tu Constitution skillcape.",
    ["No problem, you will now use the newer model for all of your skillcapes!"] = "No hay problema, ¡ahora usarás el modelo más nuevo para todos tus skillcapes!",
    ["Great! I'm glad you're still enjoying the old version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión anterior!",
    ["*(If the player is using the new skillcape models except for the Constitution cape:)*"] = "*(Si el player está usando los nuevos modelos skillcape excepto la capa Constitution :)*",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas!",
    ["Are you all okay, after - you know - the Duel Arena collapsed?"] = "¿Están todos bien después de que, ya saben, el Duel Arena colapsara?",
    ["Oh quite. We've all been through much worse."] = "Oh, bastante. Todos hemos pasado por cosas mucho peores.",
    ["Really? Like what?"] = "¿En serio? ¿Cómo qué?",
    ["Well...there was...the pineapple incident."] = "Bueno... hubo... el incidente de la piña.",
    ["What happened there?"] = "¿Qué pasó allí?",
    ["We do not talk about it. EVER! I still hear the screams when I dream."] = "No hablamos de eso. ¡ALGUNA VEZ! Todavía escucho los gritos cuando sueño.",
    ["You have completed: 'Check in with the doc' and gained progress towards the Oasis Restoration event."] = "Has completado: 'Consulta con el médico' y has progresado hacia el evento Restauración del Oasis.",
    ["The horror! The sweet sticky horror!"] = "¡El horror! ¡El dulce y pegajoso horror!",
    ["Excuse me?"] = "¿Perdón?",
    ["What do you want? ...Oh, wait. I know! You're probably just like all the others, aren't you? After some fancy spell or potion from me, I bet!"] = "¿Qué quieres? ...Oh, espera. ¡Lo sé! Probablemente eres como todos los demás, ¿no? Después de algún hechizo o poción elegante de mi parte, ¡apuesto!",
    ["What? No! At least, I don't think so. What sort of spells do you have?"] = "¿Qué? ¡No! Al menos yo no lo creo. ¿Qué tipo de hechizos tienes?",
    ["Hah! I knew it! I expect you want my Aphro-Dizzy-Yak spell! Want someone to fall madly in love with you, eh?"] = "¡Ja! ¡Lo sabía! ¡Supongo que querrás mi hechizo Aphro-Dizzy-Yak! ¿Quieres que alguien se enamore perdidamente de ti, eh?",
    ["That spell sounds very interesting, but I didn't mean to disturb you!"] = "Ese hechizo suena muy interesante, ¡pero no era mi intención molestarte!",
    ["Well, I see that you do have some manners. I'm glad to see that you use them. Now, if it's all the same, I am very busy at the moment. Unless you want something specific, please come back another time."] = "Bueno, veo que tienes algunos modales. Me alegra ver que los usas. Ahora bien, si es igual, estoy muy ocupado en este momento. A menos que quieras algo específico, vuelve en otro momento.",
    ["Yes, of course. Goodbye!"] = "Sí, por supuesto. ¡Adiós!",
    ["Oh, it's you again! Well, what is it this time?"] = "¡Oh, eres tú otra vez! Bueno, ¿qué pasa esta vez?",
    ["Do you have any jobs or quests that I could do for you?"] = "¿Tienes algún trabajo o misión que pueda hacer por ti?",
    ["Hah! There are plenty of things I need done, but something tells me you're not quite ready for them right now. Come back another time!"] = "¡Ja! Hay muchas cosas que necesito hacer, pero algo me dice que no estás preparado para ellas en este momento. ¡Vuelve en otro momento!",
    ["She looks very content. It must be a very nice change of scenery from the usual caves, swamps, and Halloween set pieces."] = "Se ve muy contenta. Debe ser un cambio de escenario muy agradable con respecto a las cuevas, pantanos y escenarios habituales de Halloween.",
    ["Hello. Where are you going?"] = "Hola. ¿Adónde vas?",
    ["None of your business! Leave me alone!"] = "¡No es asunto tuyo! ¡Déjame en paz!",
    ["It just seemed as if you were walking in circles."] = "Parecía como si estuvieras caminando en círculos.",
    ["No I'm not! Now leave me alone!"] = "¡No, no lo soy! ¡Ahora déjame en paz!",
    ["Okay, okay."] = "Está bien, está bien.",
    ["Why are you still wandering around here?"] = "¿Por qué sigues deambulando por aquí?",
    ["I'm now the official liaison between Rellekka and our camp. It involves a fair bit of walking around, you know."] = "Ahora soy el enlace oficial entre Rellekka y nuestro campamento. Implica caminar bastante, ¿sabes?",
    ["*If the player is not wearing a monkeyspeak amulet or cramulet*"] = "*Si el player no lleva un amuleto o cramulet de Monkeyspeak*",
    ["Hey there, little monkey!"] = "¡Hola, pequeño mono!",
    ["Ook!"] = "¡Ok!",
    ["*If the player is wearing a monkeyspeak amulet or cramulet*"] = "*Si el player lleva un amuleto o cramulet de habla de mono*",
    ["I'm not a child, yer know! I'm a bloodthirsty pirate! I just happen to also be a monkey."] = "No soy un niño, ¿sabes? ¡Soy un pirata sediento de sangre! Resulta que yo también soy un mono.",
    ["Oh, sorry. So, er, why are you here?"] = "Oh, lo siento. Entonces, ¿por qué estás aquí?",
    ["It was The Harbinger that sunk us. Fortunately, they're not big into taking my kind. Unfortunately, that didn't stop 'em attacking and killing a bunch of us and sinking our ship, The Barrel."] = "Fue The Harbinger el que nos hundió. Afortunadamente, no les gusta aceptar a los de mi especie. Desafortunadamente, eso no les impidió atacarnos y matarnos a un grupo de nosotros y hundir nuestro barco, The Barrel.",
    ["You skin the giant snake."] = "Desollas a la serpiente gigante.",
    ["*One of the following is said occasionally by swamp toads:*"] = "*Ocasionalmente los sapos de pantano dicen una de las siguientes cosas:*",
    ["*Occasionally, while bloating a toad*"] = "*Ocasionalmente, mientras hincha un sapo*",
    ["You manage to catch the toad and inflate it with the swamp gas."] = "Consigues atrapar el sapo e inflarlo con el gas del pantano.",
    ["You need an Ogre Bellow to do this."] = "Necesitas un Ogre Bellow para hacer esto.",
    ["One of your bloated toads manages to escape."] = "Uno de tus sapos hinchados logra escapar.",
    ["*If releasing all in inventory*"] = "*Si libera todo lo que hay en el inventario*",
    ["You release the toads and see them hop off into the distance."] = "Liberas a los sapos y los ves saltar en la distancia.",
    ["*If releasing only one*"] = "*Si sueltas solo uno*",
    ["You release the toad and see it hop off into the distance."] = "Liberas al sapo y lo ves saltar en la distancia.",
    ["*Occasionally, each released toad will say one of the following as they hop away:*"] = "*Ocasionalmente, cada sapo liberado dirá una de las siguientes palabras mientras se aleja saltando:*",
    ["You won't attract a chompy bird this far away from the ogre area."] = "No atraerás a un chompy bird tan lejos del área de los ogros.",
    ["Hello outerlander. This is my home, I would be grateful if you would leave."] = "Hola extranjero. Esta es mi casa, te agradecería que te fueras.",
    ["Oh. Okay."] = "Oh. Bueno.",
    ["I am sorry outerlander, I will not offer you hospitality until my Chieftain has vouched for your honesty. This is our way."] = "Lo siento, outsider, no te ofreceré hospitalidad hasta que mi Jefe haya respondido por tu honestidad. Este es nuestro camino.",
    ["Hey! Outerlander! Do you normally just barge into someones home and wander around as you please?"] = "¡Oye! ¡Exterior! ¿Normalmente irrumpes en la casa de alguien y deambulas como te apetece?",
    ["Erm.... Well, yes actually."] = "Erm... Bueno, en realidad sí.",
    ["Well not here you don't."] = "Bueno, aquí no.",
    ["Greetings to you brother [Fremennik name]. How fare you today?"] = "Saludos hermano [Fremennik name]. ¿Cómo te encuentras hoy?",
    ["I am fine thanks Swensen. How are you doing?"] = "Estoy bien, gracias Swensen. ¿Cómo estás?",
    ["I am fine too!"] = "¡Yo también estoy bien!",
    ["Agony. Suffering! Anguish. Misery, sorrow and death."] = "Agonía. ¡Sufrimiento! Angustia. Miseria, tristeza y muerte.",
    ["The pain ripped through my body as like liquid rending a terrible wound in the earth. I have never imagined such pain. An ordeal without end. A nightmare from which I would not awake."] = "El dolor atravesó mi cuerpo como si un líquido hubiera abierto una terrible herida en la tierra. Nunca imaginé tal dolor. Un calvario sin fin. Una pesadilla de la que no despertaría.",
    ["My soul was bound to Gielinor, and the tether blazed with searing torment."] = "Mi alma estaba atada a Gielinor, y la atadura ardía con un tormento abrasador.",
    ["I suffered as the world suffered, trapped in a prison of my own making. A prison of flesh and soil and eternal slumber, just as I had sought."] = "Sufrí como sufrió el mundo, atrapado en una prisión que yo mismo había creado. Una prisión de carne, tierra y sueño eterno, tal como lo había buscado.",
    ["I do not know how long I rocked and screamed and wailed. I did not expect any to hear my cries, nor did I want to be found."] = "No sé cuánto tiempo me mecí, grité y gemí. No esperaba que nadie escuchara mis gritos, ni quería que me encontraran.",
    ["My torment ceased as suddenly as it began."] = "Mi tormento cesó tan repentinamente como comenzó.",
    ["At first, I thought that sweet oblivion had claimed me and finally brought an end to my agony."] = "Al principio, pensé que el dulce olvido me había reclamado y finalmente puso fin a mi agonía.",
    ["I realised my eyes were open. As my vision cleared, I saw four tiny figures surrounding me, dressed in robes of my colour."] = "Me di cuenta de que tenía los ojos abiertos. Cuando mi visión se aclaró, vi cuatro pequeñas figuras rodeándome, vestidas con túnicas de mi color.",
    ["The air was befouled by the smell of burnt sacrifices."] = "El aire estaba contaminado por el olor de los sacrificios quemados.",
    ["The four druids bowed down before me, chanting in a familiar tongue, drawing on the power of the elements to stabilise me."] = "Los cuatro druidas se inclinaron ante mí, cantando en una lengua familiar, aprovechando el poder de los elementos para estabilizarme.",
    ["Later, I learned their names: Ria, Atrew, Rief and Thera. They pledged their lives to me."] = "Más tarde, supe sus nombres: Ria, Atrew, Rief y Thera. Me prometieron sus vidas.",
    ["I entreated them to cease their worship, but they would not be discouraged. Their sleeping god had arisen, and they revelled in the throes of adoration."] = "Les rogué que dejaran de adorar, pero no se desanimarían. Su dios dormido se había levantado y ellos se deleitaban en medio de la adoración.",
    ["I gazed down at my wounded body, as my connection to the soil faded. The wound that tore across my chest had already begun to heal."] = "Miré mi cuerpo herido mientras mi conexión con el suelo se desvanecía. La herida que me atravesó el pecho ya había comenzado a sanar.",
    ["I blinked, and I was on the surface of Gielinor. The world was on fire."] = "Parpadeé y estaba en la superficie de Gielinor. El mundo estaba en llamas.",
    ["The Stone. They had used the Stone."] = "La Piedra. Habían usado la Piedra.",
    ["Not to create, but to destroy. And the nightmares that had plagued me, of death and battle and strife that I prayed were only dreams, were made flesh, worse than I could have imagined."] = "No para crear, sino para destruir. Y las pesadillas que me habían atormentado, de muerte, batalla y lucha por las que oraba, eran sólo sueños, se hicieron realidad, peores de lo que podría haber imaginado.",
    ["Millennia of conflict. Mortal lives ground beneath the war machine of avarice and ambition."] = "Milenios de conflicto. Mortal vive bajo la máquina de guerra de la avaricia y la ambición.",
    ["The world burned because I chose to tolerate their greed. Gielinor suffered for my cowardice."] = "El mundo ardió porque elegí tolerar su codicia. Gielinor sufrió por mi cobardía.",
    ["I could no longer hide from my duty to this world, hoping the maintain a neutral equilibrium. I was forced to take action."] = "Ya no podía esconderme de mi deber para con este mundo, esperando mantener un equilibrio neutral. I me vi obligado a actuar.",
